int T_STR_KEY::CompByStr(const void *v1, const void *v2)
{
	return (*((T_STR_KEY*)v1)).csStr.Compare((*((T_STR_KEY*)v2)).csStr);
}

int T_UINT_POS::CompByUINT(const void *v1, const void *v2)
{
	return (*((T_UINT_POS*)v1)).uINT - ((*((T_UINT_POS*)v2)).uINT);
}

int T_UINT_POS::CompByPOS(const void *v1, const void *v2)
{
	return (*((T_UINT_POS*)v1)).nPos - ((*((T_UINT_POS*)v2)).nPos);
}

class CChangeBaseStageAndRecoverOnReturn
{
public:
	CChangeBaseStageAndRecoverOnReturn(CStagCtrl* pStagCtrl, BOOL bSet=TRUE)
	{
		m_pStagCtrl = pStagCtrl;
		m_bChange = FALSE;
		m_CurStagK = m_pStagCtrl->GetCurStag();
		if (bSet) Set();
	}
	virtual ~CChangeBaseStageAndRecoverOnReturn()
	{
		Recover();
	}
	void Set()
	{
		if (m_CurStagK != 0) 
		{
			m_bChange = TRUE;
			m_pStagCtrl->ChangeCurStagWithoutUpdateNotify(0);
		}
	}
	void Recover()
	{
		if (m_bChange)
		{
			m_pStagCtrl->ChangeCurStagWithoutUpdateNotify(m_CurStagK);
			m_bChange = FALSE;
		}
	}
	BOOL IsBaseStage() { return m_CurStagK == 0; }
	CStagCtrl* m_pStagCtrl;
	BOOL m_bChange;
	BOOL m_CurStagK;
};

//////////////////////////////////////////////////////////////////////
// CLinkedKeyNode : 연결관계에 분기/병합이 포함된 경우에 활용되는 데이터 구조

BOOL CLinkedKeyNode::AddNext(CLinkedKeyNode* pNode)
{
	ASSERT(pNode);
	ASSERT(pNode->GetKey());

	for (int i=0; i<m_aNext.GetSize(); ++i)
	{
		if (m_aNext.GetAt(i)->GetKey() == pNode->GetKey())  { return TRUE; }
	}

	m_aNext.Add(pNode);
	pNode->AddPrev(this);

	return TRUE;
}

BOOL CLinkedKeyNode::AddPrev(CLinkedKeyNode* pNode)
{
	ASSERT(pNode);
	ASSERT(pNode->GetKey());

	for (int i=0; i<m_aPrev.GetSize(); ++i)
	{
		if (m_aPrev.GetAt(i)->GetKey() == pNode->GetKey())  { return TRUE; }
	}

	m_aPrev.Add(pNode);
	pNode->AddNext(this);

	return TRUE;
}

int CLinkedKeyNode::GetNextKeyList(CArray<UINT,UINT>& raKeyNext) const
{
	raKeyNext.RemoveAll();

	for (int i=0; i<m_aNext.GetSize(); ++i)
	{
		raKeyNext.Add(m_aNext.GetAt(i)->GetKey());
	}

	return raKeyNext.GetSize();
}

int CLinkedKeyNode::GetPrevKeyList(CArray<UINT,UINT>& raKeyPrev) const
{
	raKeyPrev.RemoveAll();

	for (int i=0; i<m_aPrev.GetSize(); ++i)
	{
		raKeyPrev.Add(m_aPrev.GetAt(i)->GetKey());
	}

	return raKeyPrev.GetSize();
}

UINT CLinkedKeyNode::GetKey() const
{
	return m_key;
}

CLinkedKeyNode::CLinkedKeyNode(UINT key)
{
	m_key = key;
}

CLinkedKeyNode::~CLinkedKeyNode()
{
	m_aPrev.RemoveAll();
	m_aNext.RemoveAll();
}

//////////////////////////////////////////////////////////////////////
// CLinkedKeyMgr : 연결관계에 분기/병합이 포함된 경우에 활용되는 데이터 구조

BOOL CLinkedKeyMgr::AddPrev(UINT key, UINT keyPrev)
{
	ASSERT(key);  ASSERT(keyPrev);

	CLinkedKeyNode* pNode     = GetOrAddNode(key);
	CLinkedKeyNode* pNodePrev = GetOrAddNode(keyPrev);

	return pNode->AddPrev(pNodePrev);
}

BOOL CLinkedKeyMgr::AddNext(UINT key, UINT keyNext)
{
	ASSERT(key);  ASSERT(keyNext);

	CLinkedKeyNode* pNode     = GetOrAddNode(key);
	CLinkedKeyNode* pNodeNext = GetOrAddNode(keyNext);

	return pNode->AddNext(pNodeNext);
}

BOOL CLinkedKeyMgr::RemoveKey(UINT key)
{
	CLinkedKeyNode* pNode = GetNode(key);
	if (pNode == NULL)  { ASSERT(0);  return TRUE; }

	// 연결 삭제
	CLinkedKeyNode* pNode_conn = NULL;
	CArray<UINT,UINT> aKey_conn;  aKey_conn.RemoveAll();

	pNode->GetNextKeyList(aKey_conn);
	for (int i=0; i<aKey_conn.GetSize(); ++i)
	{
		pNode_conn = GetNode(aKey_conn[i]);  ASSERT(pNode_conn);
		for (int k=pNode_conn->m_aPrev.GetSize()-1; k>=0; --k)
		{
			if (pNode_conn->m_aPrev[k]->GetKey() == key) pNode_conn->m_aPrev.RemoveAt(k);
		}
	}

	pNode->GetPrevKeyList(aKey_conn);
	for (int i=0; i<aKey_conn.GetSize(); ++i)
	{
		pNode_conn = GetNode(aKey_conn[i]);  ASSERT(pNode_conn);
		for (int k=pNode_conn->m_aNext.GetSize()-1; k>=0; --k)
		{
			if (pNode_conn->m_aNext[k]->GetKey() == key) pNode_conn->m_aNext.RemoveAt(k);
		}
	}

	// map에서 삭제
	delete pNode;  pNode = NULL;
	m_map.RemoveKey(key);

	return TRUE;
}

CLinkedKeyNode* CLinkedKeyMgr::GetOrAddNode(UINT key)
{
	CLinkedKeyNode* pNode = GetNode(key);
	if (pNode == NULL)  pNode = AddNode(key);

	return pNode;
}

CLinkedKeyNode* CLinkedKeyMgr::AddNode(UINT key)
{
	CLinkedKeyNode* pNode = GetNode(key);
	if (pNode == NULL)
	{
		pNode = new CLinkedKeyNode(key);
		m_map.SetAt(key, pNode);
	}

	return pNode;
}

int CLinkedKeyMgr::GetNextKeyList(UINT key, CArray<UINT,UINT>& raKeyNext) const
{
	CLinkedKeyNode* pNode = GetNode(key);
	if (pNode == NULL)  { /*ASSERT(0);*/  return 0; }

	return pNode->GetNextKeyList(raKeyNext);
}

// 위층 전체 키 리스트
int CLinkedKeyMgr::GetNextKeyList_all(T_STOR_K StorK, CArray<T_STOR_K,T_STOR_K>& raStorKAll) const
{
	CArray<T_STOR_K,T_STOR_K> aStorK_Up;
	GetNextKeyList(StorK, aStorK_Up);
	for(int i=0; i<aStorK_Up.GetSize(); i++)
	{
		T_STOR_K StorK_up = aStorK_Up[i];
		raStorKAll.Add(StorK_up);
		GetNextKeyList_all(StorK_up, raStorKAll);
	}

	return raStorKAll.GetSize();
}

int CLinkedKeyMgr::GetPrevKeyList(UINT key, CArray<UINT,UINT>& raKeyPrev) const
{
	CLinkedKeyNode* pNode = GetNode(key);
	if (pNode == NULL)  { /*ASSERT(0);*/  return 0; }

	return pNode->GetPrevKeyList(raKeyPrev);
}

// 등록 되어 있는 모든 key 리스트 반환
int CLinkedKeyMgr::GetKeyListAll(CArray<UINT,UINT>& raKey) const
{
	return m_map.GetSortedKeyListforUintK(raKey);
}

BOOL CLinkedKeyMgr::ExistKey(UINT key) const
{
	return m_map.Exist(key);
}

CLinkedKeyNode* CLinkedKeyMgr::GetNode(UINT key) const
{
	CLinkedKeyNode* pNode = NULL;
	if (!m_map.Lookup(key, pNode))  return NULL;

	ASSERT(pNode);
	return pNode;
}

CLinkedKeyMgr::CLinkedKeyMgr()
{
	m_map.RemoveAll();
	m_map.InitHashTable(997);
}

CLinkedKeyMgr::~CLinkedKeyMgr() 
{
	Clear();
}

void CLinkedKeyMgr::Clear()
{
	UINT key = 0;
	CLinkedKeyNode* pNode = NULL;

	POSITION pos = m_map.GetStartPosition();
	while (pos)
	{
		m_map.GetNextAssoc(pos, key, pNode);
		if (pNode) { delete pNode;  pNode = NULL; }
	}
	m_map.RemoveAll();
	m_map.InitHashTable(997);
}

void CLinkedKeyMgr::Copy(CLinkedKeyMgr& src)
{
	m_map.RemoveAll();

	CArray<UINT,UINT> aKey, aKey_Next, aKey_Prev;
	src.GetKeyListAll(aKey);
	m_map.InitHashTable(aKey.GetSize()+1);
	for(int i=0; i<aKey.GetSize(); i++)
	{
		AddNode(aKey[i]);
		src.GetNextKeyList(aKey[i], aKey_Next);
		for(int j=0; j<aKey_Next.GetSize(); j++)
		{
			AddNext(aKey[i], aKey_Next[j]);
		}
		src.GetPrevKeyList(aKey[i], aKey_Prev);
		for(int j=0; j<aKey_Prev.GetSize(); j++)
		{
			AddPrev(aKey[i], aKey_Prev[j]);
		}
	}
}

