BOOL CAttrCtrl::CheckLcomLabel(BOOL bAllLoadCase, T_LCOM_D& DataLcom)
{
	if(GetCountStld() == 0)return FALSE;
	if(bAllLoadCase)return TRUE;

	for(int i=0; i<DataLcom.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = DataLcom.aCombination[i];
		int nLoadCaseKey=rLcomBase.LoadCaseKey;
		if(nLoadCaseKey == 0)break;
		int nLcomAnalType=rLcomBase.AnalType;
		if(nLcomAnalType == D_LCOM_STATIC)
		{
			return TRUE;
		}
		else if(nLcomAnalType == D_LCOM_CRANE)
		{
			return TRUE;
		}
		else if(nLcomAnalType == D_LCOM_STAGE)
		{
			return TRUE;
		}
		else if(nLcomAnalType == D_LCOM_CB_GENERAL || nLcomAnalType == D_LCOM_CB_STEEL || nLcomAnalType == D_LCOM_CB_CONCRETE || 
			nLcomAnalType == D_LCOM_CB_FOOTING || nLcomAnalType == D_LCOM_CB_SRC   || nLcomAnalType == D_LCOM_CB_ALUMINUM ||
			nLcomAnalType == D_LCOM_CB_STLCOMP || nLcomAnalType == D_LCOM_CB_CFSTEEL || nLcomAnalType == D_LCOM_CB_SEISMIC ||
			nLcomAnalType == D_LCOM_CB_LINEAR_EVAL)
		{
			T_LCOM_D lcom;
			int nLcomType=0;
			if(nLcomAnalType == D_LCOM_CB_GENERAL )nLcomType=D_LCOMTYPE_GENERAL;
			if(nLcomAnalType == D_LCOM_CB_STEEL   )nLcomType=D_LCOMTYPE_STEEL  ;
			if(nLcomAnalType == D_LCOM_CB_CONCRETE)nLcomType=D_LCOMTYPE_CONCRETE;
			if(nLcomAnalType == D_LCOM_CB_FOOTING )nLcomType=D_LCOMTYPE_FDN    ;
			if(nLcomAnalType == D_LCOM_CB_SRC     )nLcomType=D_LCOMTYPE_SRC    ;
			if(nLcomAnalType == D_LCOM_CB_ALUMINUM)nLcomType=D_LCOMTYPE_ALUMINUM;
			if(nLcomAnalType == D_LCOM_CB_STLCOMP )nLcomType=D_LCOMTYPE_STLCOMP;
			if(nLcomAnalType == D_LCOM_CB_CFSTEEL )nLcomType=D_LCOMTYPE_CFSTEEL;
			if(nLcomAnalType == D_LCOM_CB_SEISMIC )nLcomType=D_LCOMTYPE_SEISMIC;
			if(nLcomAnalType == D_LCOM_CB_LINEAR_EVAL )nLcomType=D_LCOMTYPE_LINEAR_EVAL;
			if(!GetLcom(nLcomType, rLcomBase.LoadCaseKey, lcom)){ASSERT(FALSE);continue;}
			if (CheckLcomLabel(bAllLoadCase, lcom)) return TRUE;
			else continue;
		}
		else
		{
			ASSERT(nLcomAnalType != D_LCOM_ENVELOPE);
			continue;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::CheckLcomLabelThis(BOOL bAllLoadCase, T_LCOM_D& DataLcom)
{
	if(GetCountThis() == 0)return FALSE; 
	if(bAllLoadCase)return TRUE;

	for(int i=0; i<DataLcom.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = DataLcom.aCombination[i];
		int nLoadCaseKey=rLcomBase.LoadCaseKey;
		if(nLoadCaseKey == 0)break;
		int nLcomAnalType=rLcomBase.AnalType;
		if(nLcomAnalType == D_LCOM_HISTORY)
		{
			return TRUE;
		}
		else if(nLcomAnalType == D_LCOM_CB_GENERAL || nLcomAnalType == D_LCOM_CB_STEEL || nLcomAnalType == D_LCOM_CB_CONCRETE || 
			nLcomAnalType == D_LCOM_CB_FOOTING || nLcomAnalType == D_LCOM_CB_SRC   || nLcomAnalType == D_LCOM_CB_ALUMINUM ||
			nLcomAnalType == D_LCOM_CB_STLCOMP || nLcomAnalType == D_LCOM_CB_CFSTEEL || nLcomAnalType == D_LCOM_CB_SEISMIC ||
			nLcomAnalType == D_LCOM_CB_LINEAR_EVAL)
		{
			T_LCOM_D lcom;
			int nLcomType=0;
			if(nLcomAnalType == D_LCOM_CB_GENERAL )nLcomType=D_LCOMTYPE_GENERAL;
			if(nLcomAnalType == D_LCOM_CB_STEEL   )nLcomType=D_LCOMTYPE_STEEL  ;
			if(nLcomAnalType == D_LCOM_CB_CONCRETE)nLcomType=D_LCOMTYPE_CONCRETE;
			if(nLcomAnalType == D_LCOM_CB_FOOTING )nLcomType=D_LCOMTYPE_FDN    ;
			if(nLcomAnalType == D_LCOM_CB_SRC     )nLcomType=D_LCOMTYPE_SRC    ;
			if(nLcomAnalType == D_LCOM_CB_ALUMINUM)nLcomType=D_LCOMTYPE_ALUMINUM;
			if(nLcomAnalType == D_LCOM_CB_STLCOMP )nLcomType=D_LCOMTYPE_STLCOMP;
			if(nLcomAnalType == D_LCOM_CB_CFSTEEL )nLcomType=D_LCOMTYPE_CFSTEEL;
			if(nLcomAnalType == D_LCOM_CB_SEISMIC )nLcomType=D_LCOMTYPE_SEISMIC;
			if(nLcomAnalType == D_LCOM_CB_LINEAR_EVAL )nLcomType=D_LCOMTYPE_LINEAR_EVAL;
			if(!GetLcom(nLcomType, rLcomBase.LoadCaseKey, lcom)){ASSERT(FALSE);continue;}
			if (CheckLcomLabelThis(bAllLoadCase, lcom)) return TRUE;
			else continue;
		}
		else
		{
			ASSERT(nLcomAnalType != D_LCOM_ENVELOPE);
			continue;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::CheckLcomLabelGilc(BOOL bAllLoadCase, T_LCOM_D& DataLcom)
{
	if(GetCountGilc() == 0)return FALSE; 
	if(bAllLoadCase)return TRUE;

	for(int i=0; i<DataLcom.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = DataLcom.aCombination[i];
		int nLoadCaseKey=rLcomBase.LoadCaseKey;
		if(nLoadCaseKey == 0)break;
		int nLcomAnalType=rLcomBase.AnalType;
		if(nLcomAnalType == D_LCOM_GRIDMODEL)
		{
			return TRUE;
		}
		else if(nLcomAnalType == D_LCOM_CB_GENERAL || nLcomAnalType == D_LCOM_CB_STEEL || nLcomAnalType == D_LCOM_CB_CONCRETE || 
			nLcomAnalType == D_LCOM_CB_FOOTING || nLcomAnalType == D_LCOM_CB_SRC   || nLcomAnalType == D_LCOM_CB_ALUMINUM ||
			nLcomAnalType == D_LCOM_CB_STLCOMP)
		{
			T_LCOM_D lcom;
			int nLcomType=0;
			if(nLcomAnalType == D_LCOM_CB_GENERAL )nLcomType=D_LCOMTYPE_GENERAL;
			if(nLcomAnalType == D_LCOM_CB_STEEL   )nLcomType=D_LCOMTYPE_STEEL  ;
			if(nLcomAnalType == D_LCOM_CB_CONCRETE)nLcomType=D_LCOMTYPE_CONCRETE;
			if(nLcomAnalType == D_LCOM_CB_FOOTING )nLcomType=D_LCOMTYPE_FDN    ;
			if(nLcomAnalType == D_LCOM_CB_SRC     )nLcomType=D_LCOMTYPE_SRC    ;
			if(nLcomAnalType == D_LCOM_CB_ALUMINUM)nLcomType=D_LCOMTYPE_ALUMINUM;
			if(nLcomAnalType == D_LCOM_CB_STLCOMP )nLcomType=D_LCOMTYPE_STLCOMP;
			if(nLcomAnalType == D_LCOM_CB_CFSTEEL )nLcomType=D_LCOMTYPE_CFSTEEL;
			if(nLcomAnalType == D_LCOM_CB_SEISMIC )nLcomType=D_LCOMTYPE_SEISMIC;
			if(nLcomAnalType == D_LCOM_CB_LINEAR_EVAL )nLcomType=D_LCOMTYPE_LINEAR_EVAL;
			if(!GetLcom(nLcomType, rLcomBase.LoadCaseKey, lcom)){ASSERT(FALSE);continue;}
			if (CheckLcomLabelGilc(bAllLoadCase, lcom)) return TRUE;
			else continue;
		}
		else
		{
			ASSERT(nLcomAnalType != D_LCOM_ENVELOPE);
			continue;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetLcomStldFactor(T_STLD_K KeyStld, T_LCOM_D& DataLcom, double& dStldFactor, double& dStagFactor, BOOL bTDPL)
{
	dStldFactor=0.;
	dStagFactor=0.;
	int nLoadCombType=DataLcom.LoadCombType;   // 0=ADD 1=ENVELOPE 2=ABS 3=SRSS
	for(int i=0; i<DataLcom.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = DataLcom.aCombination[i];
		int nLoadCaseKey=rLcomBase.LoadCaseKey;
		if(nLoadCaseKey == 0)break;
		int nLcomAnalType=rLcomBase.AnalType;
		switch (nLcomAnalType)
		{
		case D_LCOM_STATIC:
			{
				if(nLoadCombType != 0)
				{
					dStldFactor=0.;
					dStagFactor=0.;
					return FALSE;
				}
				if(nLoadCaseKey != KeyStld)continue;
				dStldFactor+=rLcomBase.Factor;
			}
			break;
		case D_LCOM_STAGE:
			{
				if(nLoadCombType != 0)
				{
					dStldFactor=0.;
					dStagFactor=0.;
					return FALSE;
				}

				//---------------------------------------------------
				// Summation인경우 건 하중이 무조건 그려짐 
				//---------------------------------------------------
				UINT nLoadKSum,nLoadKTen;

				nLoadKTen = 3;

#ifdef _CIVIL 
				nLoadKSum = D_SGLD_SUM_CVL;
#else         
				nLoadKSum = D_SGLD_SUM_GEN;
#endif

				if(nLoadCaseKey == nLoadKSum)
				{
					dStagFactor+=rLcomBase.Factor;  
					continue; 
				}

				//---------------------------------------------------
				// Tendon인경우 
				//---------------------------------------------------
				if(bTDPL)
					if(nLoadCaseKey == nLoadKTen )
					{
						dStagFactor+=rLcomBase.Factor;
						continue; 
					}

					//---------------------------------------------------
					// Tendon이 아닌경우 
					// Civil : DEAD(1),ERECTION(2) 
					// Gen   : DEAD(1),LIVE(2)
					// 인자로 넘어온 KeyStld가 T_STCT_D::StctCase[D_STCT_NUMSTCT]안에 
					// 존재하는경우 (2)타입으로 비교해서 StageFactor를 증가시킴  
					// T_STCT_D::StctCase[D_STCT_NUMSTCT]안에 없으면 (1)타입과 
					// 비교해서 StageFactor를 증가시킴 
					//---------------------------------------------------

					BOOL bExistEracLoadK =FALSE;
					BOOL bExistMatchEracLoadK=FALSE;
					T_STCT_D StctD;
					// Stage Analysis Control안에 KeyStld가 
					// 있는경우 (2)으로 비교한다 
					if(GetStct(StctD))
					{
						for(int iii = 0; iii<StctD.aErection.GetSize(); ++iii)
						{
							for(int kkk=0; kkk<D_STCT_NUMSTCT; kkk++)
							{
								if(StctD.aErection[iii].LoadCaseKey[kkk]==0)break;
								if(StctD.aErection[iii].LoadCaseKey[kkk]==KeyStld)
								{ 
									bExistEracLoadK = TRUE;
									bExistMatchEracLoadK = (D_SGLD_ER1_CVL <= nLoadCaseKey && nLoadCaseKey <= D_SGLD_ER20_CVL) && (iii + D_SGLD_ER1_CVL == nLoadCaseKey);
									break;
								}
							}
						}
/*#ifdef _CIVIL */
						if (bExistMatchEracLoadK)
						{
							dStagFactor += rLcomBase.Factor;
							continue;
						}
// #else         
// 						if (bExistLoadK && nLoadCaseKey == 2)
// 						{
// 							dStagFactor += rLcomBase.Factor;
// 							continue;
// 						}
// #endif
					}
					// Stage Analysis Control안에 KeyStld가 
					// 없는경우 (1) 로 비교한다 
					if(nLoadCaseKey == 1 && !bExistEracLoadK)	// Eraction에 포함되어 있는 하중이라면 Dead에는 없다.
					{
						dStagFactor+=rLcomBase.Factor;  
						continue; 
					}
			}
			break;
		case D_LCOM_CB_GENERAL:
		case D_LCOM_CB_STEEL:
		case D_LCOM_CB_CONCRETE:
		case D_LCOM_CB_FOOTING:
		case D_LCOM_CB_SRC:
		case D_LCOM_CB_ALUMINUM:
		case D_LCOM_CB_STLCOMP:
		case D_LCOM_CB_CFSTEEL:
		case D_LCOM_CB_SEISMIC:
		case D_LCOM_CB_LINEAR_EVAL:
			{				
				int nLcomType = m_pDoc->m_pAttrCtrl2->GetLcomTypeByAnalType(nLcomAnalType);
				
				T_LCOM_D lcom;
				if(!GetLcom(nLcomType, nLoadCaseKey, lcom)){ASSERT(FALSE);continue;}
				double dStldFactorTemp=0.;
				double dStagFactorTemp=0.;
				if(!GetLcomStldFactor(KeyStld, lcom, dStldFactorTemp, dStagFactorTemp))
				{
					dStldFactor=0.;
					dStagFactor=0.;
					return FALSE;
				}
				dStldFactor+=dStldFactorTemp*rLcomBase.Factor;
				dStagFactor+=dStagFactorTemp*rLcomBase.Factor;
			}
			break;
		default:
			{
				ASSERT(nLcomAnalType != D_LCOM_ENVELOPE);
				continue;
			}
			break;
		}
	}
	return TRUE;
}

BOOL CAttrCtrl::GetLcomThisFactor(T_THIS_K KeyThis, T_LCOM_D& DataLcom, double& dThisFactor)
{
	dThisFactor=0.;
	int nLoadCombType=DataLcom.LoadCombType;   // 0=ADD 1=ENVELOPE 2=ABS 3=SRSS
	for(int i=0; i<DataLcom.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = DataLcom.aCombination[i];
		int nLoadCaseKey=rLcomBase.LoadCaseKey;
		if(nLoadCaseKey == 0)break;
		int nLcomAnalType=rLcomBase.AnalType;
		if(nLcomAnalType == D_LCOM_HISTORY)
		{
			if(nLoadCombType != 0)  // if not ADD
			{
				dThisFactor=0.;
				return FALSE;
			}
			if(nLoadCaseKey != KeyThis)continue;
			dThisFactor+=rLcomBase.Factor;
		}
		else if(nLcomAnalType == D_LCOM_CB_GENERAL || nLcomAnalType == D_LCOM_CB_STEEL || nLcomAnalType == D_LCOM_CB_CONCRETE || 
			nLcomAnalType == D_LCOM_CB_FOOTING || nLcomAnalType == D_LCOM_CB_SRC   || nLcomAnalType == D_LCOM_CB_ALUMINUM ||
			nLcomAnalType == D_LCOM_CB_STLCOMP || nLcomAnalType == D_LCOM_CB_CFSTEEL || nLcomAnalType == D_LCOM_CB_SEISMIC ||
			nLcomAnalType == D_LCOM_CB_LINEAR_EVAL)
		{
			T_LCOM_D lcom;
			int nLcomType=0;
			if(nLcomAnalType == D_LCOM_CB_GENERAL )nLcomType=D_LCOMTYPE_GENERAL;
			if(nLcomAnalType == D_LCOM_CB_STEEL   )nLcomType=D_LCOMTYPE_STEEL  ;
			if(nLcomAnalType == D_LCOM_CB_CONCRETE)nLcomType=D_LCOMTYPE_CONCRETE;
			if(nLcomAnalType == D_LCOM_CB_FOOTING )nLcomType=D_LCOMTYPE_FDN    ;
			if(nLcomAnalType == D_LCOM_CB_SRC     )nLcomType=D_LCOMTYPE_SRC    ;
			if(nLcomAnalType == D_LCOM_CB_ALUMINUM)nLcomType=D_LCOMTYPE_ALUMINUM;
			if(nLcomAnalType == D_LCOM_CB_STLCOMP )nLcomType=D_LCOMTYPE_STLCOMP;
			if(nLcomAnalType == D_LCOM_CB_CFSTEEL )nLcomType=D_LCOMTYPE_CFSTEEL;
			if(nLcomAnalType == D_LCOM_CB_SEISMIC )nLcomType=D_LCOMTYPE_SEISMIC;
			if(nLcomAnalType == D_LCOM_CB_LINEAR_EVAL)nLcomType=D_LCOMTYPE_LINEAR_EVAL;
			if(!GetLcom(nLcomType, rLcomBase.LoadCaseKey, lcom)){ASSERT(FALSE);continue;}
			double dThisFactorTemp=0.;
			if(!GetLcomThisFactor(KeyThis, lcom, dThisFactorTemp))
			{
				dThisFactor=0.;
				return FALSE;
			}
			dThisFactor+=dThisFactorTemp*rLcomBase.Factor;
		}
		else
		{
			ASSERT(nLcomAnalType != D_LCOM_ENVELOPE);
			continue;
		}
	}
	return TRUE;
}

BOOL CAttrCtrl::GetLcomGilcFactor(T_GILC_K KeyGilc, T_LCOM_D& DataLcom, double& dGilcFactor)
{
	dGilcFactor=0.;
	int nLoadCombType=DataLcom.LoadCombType;   // 0=ADD 1=ENVELOPE 2=ABS 3=SRSS
	for(int i=0; i<DataLcom.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = DataLcom.aCombination[i];
		int nLoadCaseKey=rLcomBase.LoadCaseKey;
		if(nLoadCaseKey == 0)break;
		int nLcomAnalType=rLcomBase.AnalType;
		if(nLcomAnalType == D_LCOM_GRIDMODEL)
		{
			if(nLoadCombType != 0)  // if not ADD
			{
				dGilcFactor=0.;
				return FALSE;
			}
			if(nLoadCaseKey != KeyGilc)continue;
			dGilcFactor+=rLcomBase.Factor;
		}
		else if(nLcomAnalType == D_LCOM_CB_GENERAL || nLcomAnalType == D_LCOM_CB_STEEL || nLcomAnalType == D_LCOM_CB_CONCRETE || 
			nLcomAnalType == D_LCOM_CB_FOOTING || nLcomAnalType == D_LCOM_CB_SRC   || nLcomAnalType == D_LCOM_CB_ALUMINUM ||
			nLcomAnalType == D_LCOM_CB_STLCOMP)
		{
			T_LCOM_D lcom;
			int nLcomType=0;
			if(nLcomAnalType == D_LCOM_CB_GENERAL )nLcomType=D_LCOMTYPE_GENERAL;
			if(nLcomAnalType == D_LCOM_CB_STEEL   )nLcomType=D_LCOMTYPE_STEEL  ;
			if(nLcomAnalType == D_LCOM_CB_CONCRETE)nLcomType=D_LCOMTYPE_CONCRETE;
			if(nLcomAnalType == D_LCOM_CB_FOOTING )nLcomType=D_LCOMTYPE_FDN    ;
			if(nLcomAnalType == D_LCOM_CB_SRC     )nLcomType=D_LCOMTYPE_SRC    ;
			if(nLcomAnalType == D_LCOM_CB_ALUMINUM)nLcomType=D_LCOMTYPE_ALUMINUM;
			if(nLcomAnalType == D_LCOM_CB_STLCOMP )nLcomType=D_LCOMTYPE_STLCOMP;
			if(nLcomAnalType == D_LCOM_CB_CFSTEEL )nLcomType=D_LCOMTYPE_CFSTEEL;
			if(nLcomAnalType == D_LCOM_CB_SEISMIC )nLcomType=D_LCOMTYPE_SEISMIC;
			if(nLcomAnalType == D_LCOM_CB_LINEAR_EVAL )nLcomType=D_LCOMTYPE_LINEAR_EVAL;
			if(!GetLcom(nLcomType, rLcomBase.LoadCaseKey, lcom)){ASSERT(FALSE);continue;}
			double dGilcFactorTemp=0.;
			if(!GetLcomGilcFactor(KeyGilc, lcom, dGilcFactorTemp))
			{
				dGilcFactor=0.;
				return FALSE;
			}
			dGilcFactor+=dGilcFactorTemp*rLcomBase.Factor;
		}
		else
		{
			ASSERT(nLcomAnalType != D_LCOM_ENVELOPE);
			continue;
		}
	}
	return TRUE;
}

