void CAttrCtrl::GetNodeKeyList(std::vector<T_NODE_K>& rarKeyList)
{
	rarKeyList.clear();
	int nCount = GetCountNode();
	if (nCount > 0)
	{
		T_NODE_K Key;
		T_NODE_D Data;
		rarKeyList.reserve(nCount);
		POSITION pos = m_pDataMemb->m_node.GetStart();
		while (pos != NULL)
		{
			m_pDataMemb->m_node.GetNext(pos, Key, Data);
			rarKeyList.push_back(Key);
		}
	}
}

void CAttrCtrl::GetNodeKeyList(CArray<T_NODE_K, T_NODE_K>& rarKeyList)
{
	rarKeyList.RemoveAll();
	int nCount=GetCountNode();
	if(nCount >0)
	{
		T_NODE_K Key;
		T_NODE_D Data;
		rarKeyList.SetSize(nCount);
		POSITION pos=m_pDataMemb->m_node.GetStart();
		int nIndex=0;
		while(pos != NULL)
		{
			m_pDataMemb->m_node.GetNext(pos, Key, Data);
			rarKeyList[nIndex]=Key;
			nIndex++;
		}
		CQSort::QSortUInt(rarKeyList.GetData(), nCount);
	}
}

