BOOL CAttrCtrl::ExistNode(double x, double y, double z, T_NODE_K& ExistKey)
{
	ExistKey = 0;

	const double dZero = CDBDoc::GetDocPoint()->m_pInitCtrl->GetPreferenceRegardZero();

	CArray<T_NODE_K, T_NODE_K> arNodeKey; arNodeKey.RemoveAll();
	GetNodeKeyList(arNodeKey);
	int nNodeSize = arNodeKey.GetSize();
	for(int i=0 ; i<nNodeSize ; ++i)
	{
		T_NODE_K NodeK = arNodeKey[i];
		T_NODE_D NodeD; NodeD.Initialize();
		if(!GetNode(NodeK, NodeD)) continue;

		if((fabs(NodeD.x-x)<dZero) && (fabs(NodeD.y-y)<dZero) && (fabs(NodeD.z-z)<dZero))
		{
			ExistKey = NodeK;
			break;
		}
	}

	if(ExistKey == 0)
		return FALSE;
	else
		return TRUE;
}

