BOOL CAttrCtrl::IsUnusedNode(T_NODE_K Key)
{
	NodeList* pList;
	if (!m_pDataMemb->m_node.GetList(Key, pList)) return TRUE;
	if(pList->GetCount() == 0)return TRUE;
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		// ===== // DB_NODE_DATA
		ListData=pList->GetNext(pos);
		if(ListData.nCmd != LT_GRUP_CMD && ListData.nCmd != LT_GUNO_CMD)return FALSE;
	}
	// THRD에 사용된 거 검사
	// HDCT에 사용된 거 검사
	// NLCT에 사용된 거 검사
	// THRD에 사용된 거는 UnUsed Node로 처리한다. Performance 문제.
	// THRD가 중요한 데이타 아니고 Node삭제시 THRD 지워지므로 상관 없다.
	// HDCT, NLCT의 경우 요소에 연결된 절점이 아닌 경우는 지워져도 되는 경우로 한다.

	return TRUE;
}

BOOL CAttrCtrl::IsUnconnectedNode(T_NODE_K KeyNode)
{
	T_LIST_DATA ListData;
	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_ELEM_CMD)return FALSE;
	}
	return TRUE;
}

void CAttrCtrl::IsDofFixed(T_NODE_K KeyNode, BOOL bFix[CONS_SIZE])
{
	for(int i=0; i<CONS_SIZE; i++)bFix[i]=TRUE;
	T_LIST_DATA ListData;
	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		// ===== // DB_DATA
		if(ListData.nCmd == LT_ELEM_CMD)
		{
			T_ELEM_K key;
			T_ELEM_D data;
			key=ListData.nKey;
			VERIFY(GetElem(key, data));
			int nDof = GetCountDof(key);
			if(nDof==7) // 7th DOF Beam(7)
			{
				for(int i=0; i<CONS_SIZE; i++)bFix[i]=FALSE;
			}
			else if(nDof > 3)     // 6th DOF Beam(6), Plate(5), Wall(6), Panel(5), BDSSlab(5), SDSSlab(5)
			{
				for(int i=0; i<6; i++)bFix[i]=FALSE;
			}
			else if(IsOnlyDispDof(data.eltyp))  // Truss, Plstrs, Solid, Trtens, TrComp
			{
				for(int i=0; i<3; i++)bFix[i]=FALSE;
			}
			else if(IsXZPlaneDof(data.eltyp))   // Plstrn, Axisym
			{
				bFix[0]=FALSE;
				bFix[2]=FALSE;
				//        bFix[4]=FALSE;
			}
			else
			{
				for(int i=0; i<6; i++)bFix[i]=FALSE;
			}  
			// Plane Stress Element의 Drilling Dof가 있는 경우 Fix 시키지 않는다.(04.08.31) KYM
			if(IsPlstrs(data.eltyp) && data.nSubType == 1)   
			{
				for(int i = 3; i < 6; i++) bFix[i] = FALSE;
			}
		}
		else if(ListData.nCmd == LT_NSPR_CMD)
		{
			T_NSPR_K key;
			T_NSPR_D data;
			key.keymap=ListData.nKey;
			VERIFY(GetNspr(key, data));
			if(data.nGenCompTen==0)
			{
				for(int i=0; i<6; i++)
				{
					if(data.bFixed[i]) 
					{
						bFix[i]=FALSE;
					}
					else
					{
						if(data.Spring[i] != 0.) bFix[i]=FALSE;
					}
				}
			}
			else // linear type이 아닌 경우 회전자유도만 fix
			{
				bFix[0] = bFix[1] = bFix[2] = FALSE;
			}
		}
		// MNET:XXXX 20080227 mylee - 정부장님 요청으로 걸린 Node 모두 - 구속되지않도록
		else if(ListData.nCmd == LT_MCON_CMD)
		{
			for(int i=0; i<6; i++)bFix[i]=FALSE;
		}
		else if(ListData.nCmd == LT_GSPR_CMD)
		{
			T_GSPR_K key;
			T_GSPR_D data;
			T_GSTP_D datagstp;
			key.keymap=ListData.nKey;
			VERIFY(GetGspr(key, data));
			VERIFY(GetGstp(data.SpringTypeKey, datagstp));
			for(int i=0; i<6; i++)
				if(datagstp.Spring[i] != 0.)bFix[i]=FALSE;
		}
		else if(ListData.nCmd == LT_ELNK_CMD)
		{
			T_ELNK_K key;
			T_ELNK_D data;
			key=ListData.nKey;
			VERIFY(GetElnk(key, data));
			int nDof=6;
			if(data.nSubOption == 2 || data.nSubOption == 3)nDof=3;
// 			if(data.nSubOption == 0)
// 			{
// 				if(!data.bFixed[3] && !data.bFixed[4] && !data.bFixed[5] && 
// 				    data.Spring[3] == 0. && data.Spring[4] == 0. && data.Spring[5] == 0.) nDof=3;
// 			}	
				
			for(int i=0; i<nDof; i++)bFix[i]=FALSE;
		}
		else if(ListData.nCmd == LT_NLNK_CMD)
		{
			T_NLNK_K key;
			T_NLNK_D data;
			key=ListData.nKey;
			VERIFY(GetNlnk(key, data));
			for(int i=0; i<6; i++)bFix[i]=FALSE;
			//      for(int i=0; i<6; i++)
			//        if(data.Spring[i] != 0.)bFix[i]=FALSE;
		}
		else if(ListData.nCmd == LT_SDSP_CMD)
		{
			T_SDSP_K key;
			T_SDSP_D data;
			key.keymap=ListData.nKey;
			VERIFY(GetSdsp(key, data));
			for(int i=0; i<6; i++)
				if(data.Flag[i] == '1')bFix[i]=FALSE;
		}
		else if(ListData.nCmd == LT_SMPT_CMD)
		{
			bFix[2]=FALSE;
		}
		// 7개의 자유도가 모두 있을 경우에는 더 이상 다른 요소에 대해 확인할 필요 없음
		if(bFix[0]==FALSE && bFix[1]==FALSE && bFix[2]==FALSE && bFix[3]==FALSE && bFix[4]==FALSE && bFix[5]==FALSE && bFix[6]==FALSE)  
			return;
	}
	return;
}

void CAttrCtrl::IsDofConstraintForDesign(T_NODE_K KeyNode, BOOL bConstraint[6], BOOL bCheck_LT_ELEM_CMD)
{
	for(int i=0; i<6; i++)bConstraint[i]=FALSE;
	int iCountConnectElem=0;
	BOOL bOnlyConnectElem=TRUE; // PMS:4130-Seungjun-20100310 Taiwan Steel Deflection checking (TWN-ASD96, LSD96).
	T_LIST_DATA ListData;
	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_ELEM_CMD && bCheck_LT_ELEM_CMD)  // Element.
		{
			iCountConnectElem++;
			// PMS:4130-Seungjun-20100310 Taiwan Steel Deflection checking (TWN-ASD96, LSD96).
			// boundary condition을 먼저 판단할 경우 free node로 판단할 수 있음. 따라서 초기값 TRUE로 처리 하고 boundary condition을 판단하면 False로 처리.
			//bOnlyConnectElem = TRUE;  
			// Elem.
			T_ELEM_K ElemK = ListData.nKey;
			T_ELEM_D ElemD;
			VERIFY(GetElem(ElemK, ElemD));
			//+++++++++++++++++++++++++++++++++++
			// DX, DY, DZ.
			// Node.
            /// [JIRA,GEN-958] sub beam 판단 시, 2D 요소 미고려.
			T_NODE_K NodeStaK = ElemD.elnod[0];
			T_NODE_K NodeEndK = ElemD.elnod[1];
			T_NODE_D NodeStaD, NodeEndD;
			VERIFY(GetNode(NodeStaK, NodeStaD));
			VERIFY(GetNode(NodeEndK, NodeEndD));
			// For Frame, Wall, Solid, ... NOT Use m_pDoc->calcLAVElem().
			double dLen = sqrt(pow(NodeStaD.x-NodeEndD.x,2) + pow(NodeStaD.y-NodeEndD.y,2) + pow(NodeStaD.z-NodeEndD.z,2));
			double dTol = 0.01;
			// DX.
			if(fabs(NodeStaD.x-NodeEndD.x)/dLen > dTol) bConstraint[0] = TRUE;
			// DY.
			if(fabs(NodeStaD.y-NodeEndD.y)/dLen > dTol) bConstraint[1] = TRUE;
			// DZ.
			if(fabs(NodeStaD.z-NodeEndD.z)/dLen > dTol) bConstraint[2] = TRUE;
			else if(IsWall(ElemD.eltyp))                bConstraint[2] = TRUE;
            else if(IsPlate(ElemD.eltyp))
            {
                double adPlaneLocalVector[3][3] = { { 0.0, }, };
                m_pDoc->calcPlaneLocalVector(ElemK, adPlaneLocalVector);    //판,고체 요소의 요소좌표계 계산
                if ( fabs(fabs(adPlaneLocalVector[2][2])-1.0) > dTol) { bConstraint[2] = TRUE; }
            }
			else
			{
				// For Skewed Column by User.
				T_MBTP_D MbtpD;
				if(GetMbtp(ElemK,MbtpD))
				{
					if(MbtpD.nMbType==D_MBTP_COLUMN)        bConstraint[2] = TRUE;
				}
			}
			//+++++++++++++++++++++++++++++++++++
			// RX, RY, RZ.
			if(GetCountDof(ElemD.eltyp) > 3)
			{
				for(int i=3; i<6; i++)  bConstraint[i] = TRUE;
			}
		}
		else if(ListData.nCmd == LT_NSPR_CMD) // Nonlinear Spring.
		{
			bOnlyConnectElem = FALSE;
			T_NSPR_K key;
			T_NSPR_D data;
			key.keymap=ListData.nKey;
			VERIFY(GetNspr(key, data));
			for(int i=0; i<6; i++)
				if(data.Spring[i]!=0.0)  bConstraint[i]=TRUE;
		}
		else if(ListData.nCmd == LT_CONS_CMD) // Constraint.
		{
			bOnlyConnectElem = FALSE;
			T_CONS_K key;
			T_CONS_D data;
			key.keymap=ListData.nKey;
			VERIFY(GetCons(key, data));
			for(int i=0; i<6; i++)
				if(data.Constraint[i]=='1') bConstraint[i]=TRUE;
		}
		else if(ListData.nCmd == LT_GSPR_CMD) // General Spring.
		{
			bOnlyConnectElem = FALSE;
			T_GSPR_K key;
			T_GSPR_D data;
			T_GSTP_D datagstp;
			key.keymap=ListData.nKey;
			VERIFY(GetGspr(key, data));
			VERIFY(GetGstp(data.SpringTypeKey, datagstp));
			for(int i=0; i<6; i++)
				if(datagstp.Spring[i]!=0.0) bConstraint[i]=TRUE;
		}
		// MQC:8966 Seungjun-20141105 : 켄틸레버 판단시 rigid link 고려.
		else if(ListData.nCmd == LT_RIGD_CMD) // Rigid Link.
		{
			bOnlyConnectElem = FALSE;
			T_RIGD_K key;
			T_RIGD_D data;
			key.keymap=ListData.nKey;
			GetRigd(key, data);

			CString Digit;
			Digit.Format(_T("%6.6d"),data.nSlaveType);
			for(int j=0; j<6; j++)
			{
				if(Digit.GetAt(j) == '1') bConstraint[j] = TRUE;
				else                      bConstraint[j] = FALSE;
			}
		}
		else if(ListData.nCmd == LT_ELNK_CMD) // Elastic Link.
		{
			bOnlyConnectElem = FALSE;
			T_ELNK_K key;
			T_ELNK_D data;
			key=ListData.nKey;
			VERIFY(GetElnk(key, data));
			for(int i=0; i<6; i++)
				if(data.Spring[i]!=0.0) bConstraint[i]=TRUE;
		}
		else if(ListData.nCmd == LT_NLNK_CMD) // Nonlinear Link.
		{
			bOnlyConnectElem = FALSE;
			T_NLNK_K key;
			T_NLNK_D data;
			key=ListData.nKey;
			VERIFY(GetNlnk(key, data));
			for(int i=0; i<6; i++)bConstraint[i]=TRUE;
		}
		else if(ListData.nCmd == LT_SDSP_CMD) // Specified Displacement of Support.
		{
			bOnlyConnectElem = FALSE;
			T_SDSP_K key;
			T_SDSP_D data;
			key.keymap=ListData.nKey;
			VERIFY(GetSdsp(key, data));
			for(int i=0; i<6; i++)
				if(data.Flag[i]=='1') bConstraint[i]=TRUE;
		}
		else if(ListData.nCmd == LT_SMPT_CMD) // Settlement.
		{
			bOnlyConnectElem = FALSE;
			bConstraint[2]=TRUE;
		}
	}

	// Set Free End Node.
	if(iCountConnectElem==1 && bOnlyConnectElem)
	{
		for(int i=0; i<6; i++)  
			bConstraint[i]=FALSE;
	}

	T_ACTL_D ActlD;
	if (!m_pDoc->m_pAttrCtrl->GetActl(ActlD))  ActlD.Initialize();
	if(bConstraint[2]==FALSE && ActlD.bAutoWallConstraint && IsNodeOnWallLine(KeyNode))
		bConstraint[2] = TRUE;

	static const BOOL bTestEnv_IsDofConstraintForDesignPrint = CTestEnvMgr::GetTestEnvST(_LSX(IsDofConstraintForDesignPrint)) == _LSX(yes);
	if(bTestEnv_IsDofConstraintForDesignPrint)
	{
		CString str;
		str.Format(_T("Node : %d, Constraint : "), KeyNode);
		for(int i=0; i<6; i++)
			str += bConstraint[i] ? '1':'0';
		GSaveHistoryFormatNF(str);
	}

	return;
}

void CAttrCtrl::GetSupportCondition(T_NODE_K KeyNode, BOOL bConstraint[6], const T_KEY_LIST *lstExceptElems)
{
	for(int i=0; i<6; i++)
		bConstraint[i]=FALSE;
	int iCountConnectElem=0;
	BOOL bOnlyConnectElem=TRUE; 
	CMap<T_KEY, T_KEY, T_KEY, T_KEY> mapExcept;
	if(lstExceptElems != nullptr && lstExceptElems->GetCount() >0)
	{
		mapExcept.InitHashTable(lstExceptElems->GetCount()+1);
		for (int i=0; i<lstExceptElems->GetCount(); i++)
		{
			mapExcept.SetAt(lstExceptElems->GetAt(i), lstExceptElems->GetAt(i));
		}
	}
	T_LIST_DATA ListData;
	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		// ===== // DB_DATA
		if(ListData.nCmd == LT_ELEM_CMD)  // Element.
		{
			T_ELEM_K ElemK = ListData.nKey;
			if(mapExcept.PLookup(ElemK) != nullptr)
				continue;
			iCountConnectElem++;      
			T_ELEM_D ElemD;
			VERIFY(GetElem(ElemK, ElemD));
			//+++++++++++++++++++++++++++++++++++
			// DX, DY, DZ.
			// Node.
			T_NODE_K NodeStaK = ElemD.elnod[0];
			T_NODE_K NodeEndK = ElemD.elnod[1];
			T_NODE_D NodeStaD, NodeEndD;
			VERIFY(GetNode(NodeStaK, NodeStaD));
			VERIFY(GetNode(NodeEndK, NodeEndD));
			// For Frame, Wall, Solid, ... NOT Use m_pDoc->calcLAVElem().
			double dLen = sqrt(pow(NodeStaD.x-NodeEndD.x,2) + pow(NodeStaD.y-NodeEndD.y,2) + pow(NodeStaD.z-NodeEndD.z,2));
			double dTol = 0.01;
			// DX.
			if(fabs(NodeStaD.x-NodeEndD.x)/dLen > dTol) bConstraint[0] = TRUE;
			// DY.
			if(fabs(NodeStaD.y-NodeEndD.y)/dLen > dTol) bConstraint[1] = TRUE;
			// DZ.
			if(fabs(NodeStaD.z-NodeEndD.z)/dLen > dTol) bConstraint[2] = TRUE;
			else if(IsWall(ElemD.eltyp))                bConstraint[2] = TRUE;
			else
			{
				if(GetMemberType(ElemK) == D_MBTP_COLUMN)        
					bConstraint[2] = TRUE;
			}
			//+++++++++++++++++++++++++++++++++++
			// RX, RY, RZ.
			if(GetCountDof(ElemD.eltyp) > 3)
			{
				for(int i=3; i<6; i++)  
					bConstraint[i] = TRUE;
			}
		}
		else if(ListData.nCmd == LT_NSPR_CMD) // Nonlinear Spring.
		{
			bOnlyConnectElem = FALSE;
			T_NSPR_K key;
			T_NSPR_D data;
			key.keymap=ListData.nKey;
			VERIFY(GetNspr(key, data));
			for(int i=0; i<6; i++)
				if(data.Spring[i]!=0.0)  bConstraint[i]=TRUE;
		}
		else if(ListData.nCmd == LT_CONS_CMD) // Constraint.
		{
			bOnlyConnectElem = FALSE;
			T_CONS_K key;
			T_CONS_D data;
			key.keymap=ListData.nKey;
			VERIFY(GetCons(key, data));
			for(int i=0; i<6; i++)
				if(data.Constraint[i]=='1') bConstraint[i]=TRUE;
		}
		else if(ListData.nCmd == LT_GSPR_CMD) // General Spring.
		{
			bOnlyConnectElem = FALSE;
			T_GSPR_K key;
			T_GSPR_D data;
			T_GSTP_D datagstp;
			key.keymap=ListData.nKey;
			VERIFY(GetGspr(key, data));
			VERIFY(GetGstp(data.SpringTypeKey, datagstp));
			for(int i=0; i<6; i++)
				if(datagstp.Spring[i]!=0.0) bConstraint[i]=TRUE;
		}
		// MQC:8966 Seungjun-20141105 : 켄틸레버 판단시 rigid link 고려.
		else if(ListData.nCmd == LT_RIGD_CMD) // Rigid Link.
		{
			bOnlyConnectElem = FALSE;
			T_RIGD_K key;
			T_RIGD_D data;
			key.keymap=ListData.nKey;
			GetRigd(key, data);

			CString Digit;
			Digit.Format(_T("%6.6d"),data.nSlaveType);
			for(int j=0; j<6; j++)
			{
				if(Digit.GetAt(j) == '1') bConstraint[j] = TRUE;
				else                      bConstraint[j] = FALSE;
			}
		}
		else if(ListData.nCmd == LT_ELNK_CMD) // Elastic Link.
		{
			bOnlyConnectElem = FALSE;
			T_ELNK_K key;
			T_ELNK_D data;
			key=ListData.nKey;
			VERIFY(GetElnk(key, data));
			for(int i=0; i<6; i++)
				if(data.Spring[i]!=0.0) bConstraint[i]=TRUE;
		}
		else if(ListData.nCmd == LT_NLNK_CMD) // Nonlinear Link.
		{
			bOnlyConnectElem = FALSE;
			T_NLNK_K key;
			T_NLNK_D data;
			key=ListData.nKey;
			VERIFY(GetNlnk(key, data));
			for(int i=0; i<6; i++)bConstraint[i]=TRUE;
		}
		else if(ListData.nCmd == LT_SDSP_CMD) // Specified Displacement of Support.
		{
			bOnlyConnectElem = FALSE;
			T_SDSP_K key;
			T_SDSP_D data;
			key.keymap=ListData.nKey;
			VERIFY(GetSdsp(key, data));
			for(int i=0; i<6; i++)
				if(data.Flag[i]=='1') bConstraint[i]=TRUE;
		}
		else if(ListData.nCmd == LT_SMPT_CMD) // Settlement.
		{
			bOnlyConnectElem = FALSE;
			bConstraint[2]=TRUE;
		}
	}
	// Set Free End Node.
	if(iCountConnectElem==0 && bOnlyConnectElem)
	{
		for(int i=0; i<6; i++)  
			bConstraint[i]=FALSE;
	}
	return;
}

void CAttrCtrl::GetConnectedElem(T_NODE_K KeyNode, CArray<T_ELEM_K, T_ELEM_K>& aElemList)
{
	aElemList.RemoveAll();
	T_LIST_DATA ListData;
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetList(KeyNode, pList)) {return;}
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		// ===== // DB_DATA
		if(ListData.nCmd == LT_ELEM_CMD)aElemList.Add(ListData.nKey);
	}
	return;
}

void CAttrCtrl::GetConnectedElem(T_NODE_K KeyNode, std::vector<T_ELEM_K>& aElemList)
{
	aElemList.clear();
	T_LIST_DATA ListData;
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetList(KeyNode, pList)) {return;}
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		// ===== // DB_DATA
		if(ListData.nCmd == LT_ELEM_CMD)aElemList.push_back(ListData.nKey);
	}
	return;
}

std::vector<T_NODE_K> CAttrCtrl::GetNodeFromElementbyRelatedNode(const T_NODE_K nodeKey)
{
	auto GetNodeIndex = [](const T_NODE_K& nodeKey, const T_ELEM_D& elemData)
	{
		for (int i = 0; i < D_ELEM_MAXNOD; ++i)
		{
			if (elemData.elnod[i] == nodeKey)
			{
				return i;
			}
		}
		return -1;
	};

	if (!ExistNode(nodeKey))
	{
		return {};
	}

	// 1. 해당 node와 관련된 element를 가져온다.
	std::vector<T_NODE_K> vecElemKey;
	GetConnectedElem(nodeKey, vecElemKey);

	// 2. element 내부에 input node와 선으로 연결되는 node를 가져온다.
	std::vector<T_NODE_K> vecNodeKey;
	for (const auto elemKey : vecElemKey)
	{
		T_ELEM_D elemData;
		if (!GetElem(elemKey, elemData))
		{
			continue;
		}

		switch (elemData.eltyp)
		{
		case BEAM_EL:
		case TRUSS_EL:
		case TRTENS_EL:
		case TRCOMP_EL:
		{
			T_NODE_K targetNodeKey = elemData.elnod[0] == nodeKey ? elemData.elnod[1] : elemData.elnod[0];
			vecNodeKey.push_back(targetNodeKey);
			break;
		}
		case PLATE_EL:
		case PLSTRS_EL:
		case PLSTRN_EL:
		case AXISYM_EL:
		case WALL_EL:
		case WALLOPEN_EL:
		{
			const int idx = GetNodeIndex(nodeKey, elemData);
			if (idx < 0)
			{
				continue;
			}
			const int numNode = GetNumNode(elemData.eltyp, elemData.elnod);

			vecNodeKey.push_back(elemData.elnod[(idx + 1) % 4]);
			if (numNode == 3)
			{
				vecNodeKey.push_back(elemData.elnod[(idx + 2) % 4]);
			}
			else
			{
				vecNodeKey.push_back(elemData.elnod[(idx + 3) % 4]);
			}
			break;
		}
		case SOLID_EL:
		{
			const int idx = GetNodeIndex(nodeKey, elemData);
			if (idx < 0)
			{
				continue;
			}

			const int numNode = GetNumNode(elemData.eltyp, elemData.elnod);
			if (numNode == 4)
			{
				vecNodeKey.push_back(elemData.elnod[(idx + 1) % 4]);
				vecNodeKey.push_back(elemData.elnod[(idx + 2) % 4]);
				vecNodeKey.push_back(elemData.elnod[(idx + 3) % 4]);

			}
			else if (numNode == 6)
			{
				const std::vector<std::vector<int>> vecIdx = { {1, 2, 3}, {0, 2, 4}, {0, 1, 5}, {4, 5, 0}, {3, 5, 1}, {3, 4, 2} };
				vecNodeKey.push_back(elemData.elnod[vecIdx[idx][0]]);
				vecNodeKey.push_back(elemData.elnod[vecIdx[idx][1]]);
				vecNodeKey.push_back(elemData.elnod[vecIdx[idx][2]]);
			}
			else if (numNode == 8)
			{
				const std::vector<std::vector<int>> vecIdx = { {1, 3, 4}, {0, 2, 5}, {1, 3, 6}, {0, 2, 7}, {5, 7, 0}, {4, 6, 1}, {5, 7, 2}, {4, 6, 3} };
				vecNodeKey.push_back(elemData.elnod[vecIdx[idx][0]]);
				vecNodeKey.push_back(elemData.elnod[vecIdx[idx][1]]);
				vecNodeKey.push_back(elemData.elnod[vecIdx[idx][2]]);
			}
			break;
		}
		default:
			ASSERT(false);
			continue;
		}
	}

	return vecNodeKey;
}

void CAttrCtrl::GetConnectedElem4BeamTruss(T_NODE_K KeyNode, CArray<T_ELEM_K, T_ELEM_K>& aElemList)
{
	aElemList.RemoveAll();
	T_LIST_DATA ListData;
	NodeList* pList;
	if (!m_pDataMemb->m_node.GetList(KeyNode, pList)) { return; }

	T_ELEM_D ElemD;
	POSITION pos = pList->GetHeadPosition();
	while (pos != NULL)
	{
		ListData = pList->GetNext(pos);

		T_ELEM_K ElemK = ListData.nKey;
		if (!GetElem(ElemK, ElemD)) continue;
		if (!IsTruss(ElemD.eltyp) && !IsBeam(ElemD.eltyp)) continue;

		// ===== // DB_DATA
		if (ListData.nCmd == LT_ELEM_CMD)aElemList.Add(ListData.nKey);
	}
	return;
}

// nDir : 0=X  1=Y
BOOL CAttrCtrl::SortNodeKeyListByDirection(CArray<T_NODE_K, T_NODE_K>& raNodeK, int nDir)
{
	if (raNodeK.GetSize() == 0) { ASSERT(0);  return FALSE; }

	CArray<double, double>arLevel;
	arLevel.SetSize(raNodeK.GetSize());

	T_NODE_D NodeD;
	for (int i = 0; i < raNodeK.GetSize(); ++i)
	{
		if (!GetNode(raNodeK[i], NodeD)) { ASSERT(0);  return FALSE; }
		if(nDir == 0 )
			arLevel[i] = NodeD.x;
		else
			arLevel[i] = NodeD.y;
	}

	CQSort::QSortDblWithIndex(raNodeK.GetData(), arLevel.GetData(), raNodeK.GetSize());
	return TRUE;
}

// nType=0:ratio  1:distance
T_NODE_D CAttrCtrl::LinearInterpolNode(const T_NODE_D& A, const T_NODE_D& B, int nType, double Val)
{
	T_NODE_D R;

	// A -> B 방향 벡터
	double dx = B.x - A.x;
	double dy = B.y - A.y;
	double dz = B.z - A.z;

	// 길이
	double len = sqrt(dx * dx + dy * dy + dz * dz);
	if (len <= 1e-12) 
	{
		// A와 B가 동일한 경우, 그냥 A값 반환
		return A;
	}

	if (nType == 0)
	{
		if      (Val <= 0.0) return A;
		else if (Val >= 1.0) return B;
	}
	else if (nType == 1)
	{
		if      (Val <= 0.0) return A;
		else if (Val >= len) return B;
	}

	// 방향 벡터의 정규화
	double ux = dx / len;
	double uy = dy / len;
	double uz = dz / len;

	// 거리 비율 t만큼 진행한 위치 계산
	double dist = 0.0;
	if (nType == 0)
	{
		dist = len * Val; // 전체 길이의 t 비율
	}
	else if (nType == 1)
	{
		dist = Val;
	}

	R.x = A.x + ux * dist;
	R.y = A.y + uy * dist;
	R.z = A.z + uz * dist;

	return R;
}

T_NODE_D CAttrCtrl::MovePoint(const T_NODE_D& P, const T_NODE_D& vec, double L)
{
	// vec 정규화
	double len = sqrt(vec.x * vec.x + vec.y * vec.y + vec.z * vec.z);
	if (len < 1e-12)
		return P; // 방향이 없으면 이동하지 않음

	double ux = vec.x / len;
	double uy = vec.y / len;
	double uz = vec.z / len;

	// 이동
	T_NODE_D R;
	R.x = P.x + ux * L;
	R.y = P.y + uy * L;
	R.z = P.z + uz * L;
	return R;
}

// 구석점 찾기. 
// craCandidateNodeK 수직부재 절점키
// raCornerNodeK : 구석점 절점키
