void CAttrCtrl::GetElemKeyList(CArray<T_ELEM_K, T_ELEM_K>& rarKeyList, BOOL bWithoutDummyElem/*=TRUE*/)
{
	rarKeyList.RemoveAll();
	int nCount=GetCountElem(FALSE);
	if(nCount >0)
	{
		T_ELEM_K Key;
		T_ELEM_D Data;
		rarKeyList.SetSize(nCount);
		POSITION pos=m_pDataMemb->m_elem.GetStart();
		int nIndex=0;
		while(pos != NULL)
		{
			m_pDataMemb->m_elem.GetNext(pos, Key, Data);
			rarKeyList[nIndex]=Key;
			nIndex++;
		}
		CQSort::QSortUInt(rarKeyList.GetData(), nCount);
	}

	if (bWithoutDummyElem)
	{
		for (int i=rarKeyList.GetSize()-1; i>=0; --i)
		{
			if (ExistElemDummy(rarKeyList[i]))  rarKeyList.RemoveAt(i);
		}
	}
}

void CAttrCtrl::GetElemNodeKeyList(CArray<T_ELEM_K, T_ELEM_K>& rKeyElemList, CArray<T_NODE_K, T_NODE_K>& rKeyNodeList)
{
	rKeyNodeList.RemoveAll();
	int nCount=rKeyElemList.GetSize();
	if(nCount == 0)return;

	POSITION pos;
	T_NODE_K KeyNode;
	T_ELEM_D DataElem;
	CMap<T_NODE_K, T_NODE_K, T_NODE_K, T_NODE_K>KeyNodeMap;
	KeyNodeMap.InitHashTable(m_pDoc->GetHashSizeNode());

	for(int i=0; i<nCount; i++)
	{
		GetElem(rKeyElemList[i], DataElem);
		int nNode=GetNumNode(DataElem.eltyp, DataElem.elnod);
		for(int j=0; j<nNode; j++)KeyNodeMap.SetAt(DataElem.elnod[j], DataElem.elnod[j]);
	}
	nCount=KeyNodeMap.GetCount();
	if(nCount > 0)
	{
		rKeyNodeList.SetSize(nCount);
		int nIndex=0;
		pos=KeyNodeMap.GetStartPosition();
		while(pos != NULL)
		{
			KeyNodeMap.GetNextAssoc(pos, KeyNode, KeyNode);
			rKeyNodeList[nIndex]=KeyNode;
			nIndex++;
		}
		CQSort::QSortUInt(rKeyNodeList.GetData(), nCount);
	}
}

void CAttrCtrl::GetElemNodeKeyList(std::vector<T_ELEM_K>& rKeyElemList, std::vector<T_NODE_K>& rKeyNodeList)
{
	rKeyNodeList.clear();
	int nCount=(int)rKeyElemList.size();
	if(nCount == 0)return;

	/*T_NODE_K KeyNode;*/
	T_ELEM_D DataElem;
	std::map<T_NODE_K,T_NODE_K> KeyNodeMap;
	typedef std::pair<T_NODE_K,T_NODE_K> pairNode;

	for(int i=0; i<nCount; i++)
	{
		GetElem(rKeyElemList[i], DataElem);
		int nNode=GetNumNode(DataElem.eltyp, DataElem.elnod);
		for(int j=0; j<nNode; j++)
		{
			KeyNodeMap.insert(pairNode(DataElem.elnod[j], DataElem.elnod[j]));
		}
	}
	nCount=(int)KeyNodeMap.size();
	if(nCount > 0)
	{
		rKeyNodeList.clear();
		rKeyNodeList.reserve(nCount);
		for( std::map<T_NODE_K,T_NODE_K>::iterator itr = KeyNodeMap.begin(); itr != KeyNodeMap.end(); ++itr )
			rKeyNodeList.push_back( itr->second );

		CQSort::QSortUInt(rKeyNodeList.data(), nCount);
	}
}

