BOOL CAttrCtrl::FilteredNotRootElemKeyByList(CArray<T_ELEM_K,T_ELEM_K>& ElemKeyList,CArray<T_ELEM_K,T_ELEM_K>& NotRootElemList)
{
	NotRootElemList.RemoveAll();

	//CDBDoc* pDoc = CDBDoc::GetDocPoint();
	//CStoryData StoryData(pDoc);
	//StoryData.MakeStoryData(1);
	CStoryData* pStoryData = m_pDoc->GetStoryData();

	CArray<T_ELEM_K,T_ELEM_K> RootKeySavedList;
	CArray<T_ELEM_K,T_ELEM_K> aTempArrList;
	for(int index=ElemKeyList.GetSize() -1; index>= 0; index--)
	{
		T_ELEM_K RootElemKey;
		CArray<T_ELEM_K,T_ELEM_K> tempElemKeyList;
		BOOL bSuccess = m_pDoc->m_pAttrCtrl->GetKeyListBy_WallID_ByStor(tempElemKeyList,ElemKeyList[index], NULL, pStoryData);
		if(bSuccess==FALSE) return FALSE;

		m_pDoc->m_pAttrCtrl->GetRootWallElemKey(tempElemKeyList,RootElemKey);

		if(ElemKeyList[index] != RootElemKey)		//현재 루프를 도는 요소가 Root 요소가 아닐 경우.
		{
			NotRootElemList.Add(ElemKeyList[index]);
			ElemKeyList.RemoveAt(index);
		}
	}

	return TRUE;
}

// 입력받은 요소 키들의 Root Wall 요소키만 aElemK에 남깁니다.
BOOL CAttrCtrl::MakeRootWallElemKeyList(CArray<T_ELEM_K,T_ELEM_K>& aElemK)
{
	CMap<T_ELEM_K,T_ELEM_K,T_ELEM_K,T_ELEM_K> mRootElemK;
	mRootElemK.InitHashTable(HASHSIZEELEM);

	T_ELEM_K RootElemK;
	CArray<T_ELEM_K,T_ELEM_K> tempElemKeyList;
	CStoryData* pStoryData = m_pDoc->GetStoryData();
	for(int i=0; i<aElemK.GetSize(); i++)
	{    
		T_ELEM_D ElemD;
		GetElem(aElemK[i], ElemD);
		if(!IsWall(ElemD.eltyp)) 
			continue;

		tempElemKeyList.RemoveAll();
		BOOL bSuccess = m_pDoc->m_pAttrCtrl->GetKeyListBy_WallID_ByStor(tempElemKeyList, aElemK[i], NULL, pStoryData);
		if(bSuccess==FALSE) return FALSE;
		if(tempElemKeyList.IsEmpty()) continue;

		m_pDoc->m_pAttrCtrl->GetRootWallElemKey(tempElemKeyList,RootElemK);
		mRootElemK.SetAt(RootElemK,RootElemK);
	}

	aElemK.RemoveAll();
	POSITION pos = mRootElemK.GetStartPosition();
	while(pos)
	{
		mRootElemK.GetNextAssoc(pos,RootElemK,RootElemK);
		aElemK.Add(RootElemK);
	}
	CArrayUtil::Sort(aElemK);
	return TRUE;
}

void CAttrCtrl::GetKeyListNodeElem(CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K>& KeyElemMap,
								   CArray<T_NODE_K, T_NODE_K>* pKeyNode, CArray<T_ELEM_K, T_ELEM_K>* pKeyElem)
{
	POSITION pos;
	T_NODE_K KeyNode;
	T_ELEM_K KeyElem;
	T_ELEM_D DataElem;

	int nCount=KeyElemMap.GetCount();

	if(nCount != 0 && pKeyElem != NULL)
	{
		pKeyElem->SetSize(nCount);
		int nIndex=0;
		pos=KeyElemMap.GetStartPosition();
		while(pos != NULL)
		{
			KeyElemMap.GetNextAssoc(pos, KeyElem, KeyElem);
			pKeyElem->SetAt(nIndex, KeyElem);
			nIndex++;
		}
		CQSort::QSortUInt(pKeyElem->GetData(), nCount);
	}
	if(nCount != 0 && pKeyNode != NULL)
	{
		CMap<T_NODE_K, T_NODE_K, T_NODE_K, T_NODE_K>KeyNodeMap;
		KeyNodeMap.InitHashTable(m_pDoc->GetHashSizeNode());

		pos=KeyElemMap.GetStartPosition();
		while(pos != NULL)
		{
			KeyElemMap.GetNextAssoc(pos, KeyElem, KeyElem);
			GetElem(KeyElem, DataElem);
			int nNode=GetNumNode(DataElem.eltyp, DataElem.elnod);
			for(int i=0; i<nNode; i++)KeyNodeMap.SetAt(DataElem.elnod[i], DataElem.elnod[i]);
		}
		nCount=KeyNodeMap.GetCount();
		if(nCount > 0)
		{
			pKeyNode->SetSize(nCount);
			int nIndex=0;
			pos=KeyNodeMap.GetStartPosition();
			while(pos != NULL)
			{
				KeyNodeMap.GetNextAssoc(pos, KeyNode, KeyNode);
				pKeyNode->SetAt(nIndex, KeyNode);
				nIndex++;
			}
			CQSort::QSortUInt(pKeyNode->GetData(), nCount);
		}
	}
}

// 용도:요소가 수평보요소인지 판단.
// 담당:선종복
BOOL CAttrCtrl::IsElemHorizontalBeam(T_ELEM_K ElemK)
{
	T_ELEM_D ElemD;
	if (!GetElem(ElemK, ElemD)) return FALSE;
	return IsElemHorizontalBeam(ElemD);
}

// 용도:요소가 수평보요소인지 판단.
// 담당:선종복
BOOL CAttrCtrl::IsElemHorizontalBeam(T_ELEM_D ElemD)
{
	if (!IsFrameType(ElemD.eltyp)) return FALSE;

	// 수평보인지 판단
	double xyz[2][3];
	double FrameLocalVector[3][3];
	double angle=ElemD.angle;
	T_NODE_D NodeD;
	if (!GetNode(ElemD.elnod[0], NodeD)) return FALSE;
	xyz[0][0] = NodeD.x;
	xyz[0][1] = NodeD.y;
	xyz[0][2] = NodeD.z;
	if (!GetNode(ElemD.elnod[1], NodeD)) return FALSE;
	xyz[1][0] = NodeD.x;
	xyz[1][1] = NodeD.y;
	xyz[1][2] = NodeD.z;

	if(!m_pDoc->calcFrameLocalVector(xyz[0], xyz[1], angle, FrameLocalVector))return FALSE;
	if(fabs(FrameLocalVector[0][2]) < 1.e-5) return TRUE;
	return FALSE;
}

// bBeforeComposite : MQC:3612 by KJH 20110223 (합성전 고려)
BOOL CAttrCtrl::GetElemOffs(T_ELEM_K KeyElem, T_OFFS_D& rData, BOOL bCalcTaperedGroup, BOOL bLocalSectionOffset, BOOL bBeforeComposite, BOOL bNotConsiderBetaAngle/*=FALSE*/)
{
	rData.Initialize();
	if(GetOffsElem(KeyElem, rData))return TRUE;  // 사용자 입력 오프셋이 우선순위 0순위
	T_ELEM_D DataElem;
	GetElem(KeyElem, DataElem);
	T_SECT_D DataSect;
	if(IsNeedSect(DataElem.eltyp) && GetSect(DataElem.elpro, DataSect))
	{
		int nOffsetPosition=GetOffsetPosition(DataSect);
		int nOffsetCenter = GetOffsetCenterType(DataSect);
		if(nOffsetCenter != 0 || nOffsetPosition != 5)
		{
			T_TSGR_K KeyTsgr=GetElemTsgrKey(KeyElem);
			if(KeyTsgr > 0 && bCalcTaperedGroup)
			{
				// nCalcOption(PSC단면계산시간절약을위한) : =0:단면치수만 계산  =1:Torsion을 뺀 나머지 계산 2:정상적인 강성계산을 함 ; PSC단면이외에는 1, 2 동일
				m_pDoc->calcElemSect(KeyElem, DataSect, 1, FALSE, FALSE, FALSE);
			}
			double FrameLocalVector[3][3];
			VERIFY(m_pDoc->calcFrameLocalVector(KeyElem, FrameLocalVector, FALSE, bNotConsiderBetaAngle));

			double hi, bi, hj, bj;
			if(!GetSectOffsetFromCentroid(DataSect, hi, bi, hj, bj, bBeforeComposite))return FALSE;

			for(int i=0; i<2; i++)
			{
				double dX, dY, dZ;
				if(i == 0){dZ=-hi; dY=-bi;}
				else      {dZ=-hj; dY=-bj;}
				dX=0.;
				if(!bLocalSectionOffset)CMathFunc::mathUCS2GCS(dX, dY, dZ, FrameLocalVector);
				if(i == 0){rData.Offset[0]=dX, rData.Offset[1]=dY, rData.Offset[2]=dZ;}
				else      {rData.Offset[3]=dX, rData.Offset[4]=dY, rData.Offset[5]=dZ;}
			}
			rData.nOffsetType=4;
			return TRUE;
		}
	}
	if(m_pDoc->m_Pzef.bOffset)
	{
		if(m_pDoc->calcPanelZoneEffect(KeyElem, m_pDoc->m_Styp, m_pDoc->m_Pzef, rData))return TRUE;
	}
	return FALSE;
}

int CAttrCtrl::ChangeEltyp(int eltyp)
{
	int nt=0;
	if(eltyp==1 )nt=TRUSS_EL;      // 1
	if(eltyp==2 )nt=BEAM_EL;       // 2
	if(eltyp==3 )nt=PLSTRS_EL;     // 3
	if(eltyp==4 )nt=PLATE_EL;      // 4
	if(eltyp==5 )nt=WALL_EL;       // 5
	if(eltyp==6 )nt=PANEL_EL;      // 18
	if(eltyp==7 )nt=BDSSLAB_EL;    // 19
	if(eltyp==8 )nt=SDSSLAB_EL;    // 20
	if(eltyp==9 )nt=PLSTRN_EL;     // 6
	if(eltyp==10)nt=AXISYM_EL;     // 7
	if(eltyp==11)nt=SOLID_EL;      // 8
	if(eltyp==12)nt=TRTENS_EL;     // 9
	if(eltyp==13)nt=TRCOMP_EL;     // 10
	ASSERT(nt);
	return nt;
}

