BOOL CAttrCtrl::IsVerticalFrame(const T_NODE_D& Node_I, const T_NODE_D& Node_J)
{
	double Coor_i[3], Coor_j[3];
	Coor_i[0]=Node_I.x;
	Coor_i[1]=Node_I.y;
	Coor_i[2]=Node_I.z;
	Coor_j[0]=Node_J.x;
	Coor_j[1]=Node_J.y;
	Coor_j[2]=Node_J.z;
	return IsVerticalFrame(Coor_i, Coor_j);
}

BOOL CAttrCtrl::IsVerticalFrame(const double Coor_i[3], const double Coor_j[3])
{
	double dx=Coor_i[0]-Coor_j[0];
	double dy=Coor_i[1]-Coor_j[1];
	double dz=Coor_i[2]-Coor_j[2];
	double Length=CMathFunc::mathLength(dx, dy, dz);
	if(Length < m_pInitCtrl->ZeroLength())return FALSE;
	double Distance=CMathFunc::mathLength(dx, dy);
	if(Distance/Length < m_pInitCtrl->VertTol())return TRUE;
	return FALSE;
}

BOOL CAttrCtrl::IsHorizontalFrame(const T_NODE_D& Node_I, const T_NODE_D& Node_J)
{
	double Coor_i[3], Coor_j[3];
	Coor_i[0]=Node_I.x;
	Coor_i[1]=Node_I.y;
	Coor_i[2]=Node_I.z;
	Coor_j[0]=Node_J.x;
	Coor_j[1]=Node_J.y;
	Coor_j[2]=Node_J.z;
	return IsHorizontalFrame(Coor_i, Coor_j);
}

BOOL CAttrCtrl::IsHorizontalFrame(const double Coor_i[3], const double Coor_j[3])
{
	double dx=Coor_i[0]-Coor_j[0];
	double dy=Coor_i[1]-Coor_j[1];
	double dz=Coor_i[2]-Coor_j[2];
	double Length=CMathFunc::mathLength(dx, dy, dz);
	if(Length < m_pInitCtrl->ZeroLength())return FALSE;
	double Distance=fabs(dz);
	//if(Distance/Length < m_pInitCtrl->VertTol())return TRUE;
	if(Distance/Length < m_pInitCtrl->HorzTol())return TRUE;
	return FALSE;
}

int CAttrCtrl::GetMemberType(T_ELEM_K KeyElem, BOOL bTrussAsBrace/*=TRUE*/)
{
	T_ELEM_D DataElem;
	if(!GetElem(KeyElem, DataElem))
		return 0;

	if(DataElem.eltyp==WALL_EL) 
		return D_MBTP_WALL;

    if ( !IsFrameType(DataElem.eltyp) )
    {
        CMembCtrl* pMembCtrl = CMembCtrl::GetMembCtrl();
        T_SBDO_D SbdoD;
        if ( !pMembCtrl->GetSbdoByElem(KeyElem, SbdoD) )
        {
            return 0;
        }

        switch ( SbdoD.nMembTypeCivil )
        {
        case 1:
            return D_MBTP_PLATEBEAM;
        case 2:
            return D_MBTP_PLATECOLM;
        case 3:
            return D_MBTP_SHELL;
        default:
            return 0;
        }
    }

	T_MBTP_D DataMbtp;
	if(GetMbtp(KeyElem, DataMbtp))
	{
		if(DataMbtp.nMbType == 1)
			return 1; // column
		else if(DataMbtp.nMbType == 2)
			return 2; // beam
		else if(DataMbtp.nMbType == 3)
			return 3; // brace
		else if(DataMbtp.nMbType == 5)
			return 5; //Truss
		ASSERT(FALSE);
		return 0;
	}
	if(IsTruss(DataElem.eltyp))
		return bTrussAsBrace ? 3 : 5;
	T_NODE_D DataNodeI, DataNodeJ;
	VERIFY(GetNode(DataElem.elnod[0], DataNodeI));
	VERIFY(GetNode(DataElem.elnod[1], DataNodeJ));
	if(IsVerticalFrame(DataNodeI, DataNodeJ))
		return 1;
	if(IsHorizontalFrame(DataNodeI, DataNodeJ))
		return 2;
	return 3;
}

int CAttrCtrl::GetMemberType_JUD(T_ELEM_K KeyElem, BOOL bPassMbtp)
{	
	T_ELEM_D ElemD;
	if(!GetElem(KeyElem, ElemD)) return 0;

	// Wall
	if(ElemD.eltyp==WALL_EL) return D_MBTP_WALL;

	// Frame이 아니고 Wall이 아닐경우
	if(!IsFrameType(ElemD.eltyp)) return 0;      

	if(!bPassMbtp)
	{
		T_MBTP_D DataMbtp; DataMbtp.Initialize();
		if(GetMbtp(KeyElem, DataMbtp))
		{
			if(DataMbtp.nMbType == 1)
				return 1; // column
			else if(DataMbtp.nMbType == 2)
				return 2; // beam
			else if(DataMbtp.nMbType == 3)
				return 3; // brace
			else
				ASSERT(FALSE);
			return 0;
		}         
	}

	// Truss
	if(IsTruss(ElemD.eltyp)) return 3;

	// Beam
	T_NODE_D DataNodeI, DataNodeJ;
	VERIFY(GetNode(ElemD.elnod[0], DataNodeI));
	VERIFY(GetNode(ElemD.elnod[1], DataNodeJ));
	if(IsHorizontalFrame(DataNodeI, DataNodeJ))return 2;

	BOOL bReleaseI, bReleaseJ;
	if(m_pDoc->m_pAttrCtrl2->IsBraceByFrameElem(KeyElem, bReleaseI, bReleaseJ)) return 3;

	// 나머지는 모두 기둥
	return 1;  
}

int CAttrCtrl::GetEltypeCount(int eltyp)
{
	ASSERT(eltyp > 0 && eltyp <= MAX_ELTYP_NUM);
	if(eltyp <= 0 || eltyp > MAX_ELTYP_NUM)return 0;
	int nCount=m_pDataMemb->m_elem.GetCountEltyp(eltyp);
	if(eltyp == TRUSS_EL)nCount+=m_pDataMemb->m_elem.GetCountEltyp(TRTENS_EL)+m_pDataMemb->m_elem.GetCountEltyp(TRCOMP_EL);
	return nCount;
}

