int CAttrCtrl::GetElemTypeAndName(CArray<int, int>& raType, CArray<CString, CString&>& raElemName)
{
	struct tData
	{
		int nType;
		CString str;
		int nMask;
	};

	tData aTypeNameMask[] = {
		{(int)TRUSS_EL   ,_LS(IDS_DBLIB__ADDED__TRUSS)        , (int)D_PROD_ALL           },
		{(int)BEAM_EL    ,_LS(IDS_DBLIB__ADDED__BEAM )        , (int)D_PROD_GEN+D_PROD_CVL},
		{(int)PLSTRS_EL  ,_LS(IDS_DBLIB__ADDED__PLANE_STRESS) , (int)D_PROD_GEN+D_PROD_CVL},
		{(int)PLATE_EL   ,_LS(IDS_DBLIB__ADDED__PLATE       ) , (int)D_PROD_GEN+D_PROD_CVL},
		{(int)WALL_EL    ,_LS(IDS_DBLIB__ADDED__WALL        ) , (int)D_PROD_GEN           },
		{(int)WALLOPEN_EL,_LS(IDS_DBLIB__ADDED___Wall_OPEN   ), (int)D_PROD_GEN           },
		{(int)PLSTRN_EL  ,_LS(IDS_DBLIB__ADDED__PLANE_STRAIN) , (int)D_PROD_GEN+D_PROD_CVL},
		{(int)AXISYM_EL  ,_LS(IDS_DBLIB__ADDED__AXISYMMETRIC) , (int)D_PROD_GEN+D_PROD_CVL},
		{(int)SOLID_EL   ,_LS(IDS_DBLIB__ADDED__SOLID       ) , (int)D_PROD_GEN+D_PROD_CVL},
		{(int)TRTENS_EL  ,_LS(IDS_DBLIB__ADDED__TENS_TRUSS  ) , (int)D_PROD_GEN+D_PROD_CVL},
		{(int)TRCOMP_EL  ,_LS(IDS_DBLIB__ADDED__COMP_TRUSS  ) , (int)D_PROD_GEN+D_PROD_CVL},
		{(int)PANEL_EL   ,_LS(IDS_DBLIB__ADDED__PANEL       ) , (int)0 },
		{(int)BDSSLAB_EL ,_LS(IDS_DBLIB__ADDED__SLAB        ) , (int)0 },
		{(int)SDSSLAB_EL ,_LS(IDS_DBLIB__ADDED__SLAB        ) , (int)0 },
	};

	int nMask = CProduct::GetProductID();

	raType.RemoveAll();
	raElemName.RemoveAll();
	int nCount=0;
	int nNum = 14;
	for (int i = 0; i < nNum; i++)
	{
		if ((aTypeNameMask[i].nMask & nMask) == 0) continue;
		raType.Add(aTypeNameMask[i].nType);
		raElemName.Add(aTypeNameMask[i].str);
		nCount++;
	}
	return nCount;
}

BOOL CAttrCtrl::GetSolidFaceList(T_ELEM_D& DataElem, CArray<T_ELEM_D, T_ELEM_D&>& aFaceList) // solid요소의 각 Face를 Plate형태로 만들어줌
{
	const int Solid4Node[4][4]={ 0, 1, 2,-1,  0, 1, 3,-1,  1, 2, 3,-1,  2, 0, 3,-1};
	const int Solid6Node[5][4]={ 0, 1, 2,-1,  3, 4, 5,-1,  0, 1, 4, 3,  1, 2, 5, 4,  2, 0, 3, 5};
	const int Solid8Node[6][4]={ 0, 1, 2, 3,  4, 5, 6, 7,  0, 1, 5, 4,  1, 2, 6, 5,  2, 3, 7, 6,  3, 0, 4, 7};

	aFaceList.RemoveAll();
	if(!IsSolid(DataElem.eltyp))return FALSE;
	int nNode=GetNumNode(DataElem.eltyp, DataElem.elnod);
	if(nNode != 4 && nNode != 6 && nNode != 8)return FALSE;
	T_ELEM_D elem;
	elem.Initialize();
	elem.eltyp=GetPlateID();
	elem.elmat=DataElem.elmat;
	elem.elpro=0;
	int nFace=0;
	if(nNode == 4)nFace=4;
	if(nNode == 6)nFace=5;
	if(nNode == 8)nFace=6;
	int nIndex;
	for(int i=0; i<nFace; i++)
	{
		for(int j=0; j<4; j++)
		{
			if(nFace == 4)nIndex=Solid4Node[i][j];
			if(nFace == 5)nIndex=Solid6Node[i][j];
			if(nFace == 6)nIndex=Solid8Node[i][j];
			elem.elnod[j]=0;
			if(nIndex == -1)continue;
			elem.elnod[j]=DataElem.elnod[nIndex];
		}
		aFaceList.Add(elem);
	}
	return TRUE;
}

