int GetNodeNum(T_ELEM_D& ElemD)
{
	for(int i = 0; i < D_ELEM_MAXNOD; i++)
	{
		if(ElemD.elnod[i] == NULL) return i;
	}

	return -1;
}

BOOL CAttrCtrl::IsConnectedElem(CArray<T_ELEM_K, T_ELEM_K>& aElemKey)
{	
	int nSizeElem = aElemKey.GetSize();
	CArray<T_ELEM_D, T_ELEM_D&> aElemD;
	aElemD.SetSize(aElemKey.GetSize());
	for(int i = 0; i < nSizeElem; i++)
	{
		GetElem(aElemKey[i], aElemD[i]);
	}

	for(int i = 0; i < nSizeElem; i++)
	{
		if(GetNodeNum(aElemD[i]) != 2)
		{
			return FALSE;
		}
	}

	// 자료구조 세팅
	CMap<T_NODE_K, T_NODE_K, T_ELEM_K, T_ELEM_K> mapStNodeKToElemK;
	CMap<T_NODE_K, T_NODE_K, T_ELEM_K, T_ELEM_K> mapEnNodeKToElemK;
	mapStNodeKToElemK.InitHashTable(500);
	mapEnNodeKToElemK.InitHashTable(500);
	for(int i = 0; i < nSizeElem; i++)
	{
		mapStNodeKToElemK.SetAt(aElemD[i].elnod[0], aElemKey[i]);
		mapEnNodeKToElemK.SetAt(aElemD[i].elnod[1], aElemKey[i]);
	}	

	// 정방향으로 연결된 elem찾기(idx 0번 과의 연결성을 체크한다.)
	const int nIdxStart = 0;
	T_NODE_K NodeKNext;
	T_ELEM_K ElemKFind;
	T_ELEM_D ElemDFind;
	NodeKNext = aElemD[nIdxStart].elnod[1];

	CArray<T_ELEM_K, T_ELEM_K> aConnectedElem; // 연결된 순서와 무관하게 들어감.. 이 배열을 연결된 Elem Key들 받아오는데 쓰지 마세요..
	int nCnt = 0;
	while(NodeKNext != NULL)
	{
		if(mapStNodeKToElemK.Lookup(NodeKNext, ElemKFind))
		{
			aConnectedElem.Add(ElemKFind);
			GetElem(ElemKFind, ElemDFind);
			NodeKNext = ElemDFind.elnod[1];
		}
		else
		{
			break;
		}

		if(nCnt > nSizeElem)
		{
			return FALSE; // 모든 Elem이 띠형태로 연결되어 있는 경우
		}		
		nCnt++;
	}

	// 역방향으로 연결된 Elem 찾기(idx 0번 과의 연결성을 체크한다.)
	NodeKNext = aElemD[nIdxStart].elnod[0];
	nCnt = 0;
	while(NodeKNext != NULL)
	{
		if(mapEnNodeKToElemK.Lookup(NodeKNext, ElemKFind))
		{
			aConnectedElem.Add(ElemKFind);
			GetElem(ElemKFind, ElemDFind);
			NodeKNext = ElemDFind.elnod[0];
		}
		else
		{
			break;
		}

		ASSERT(nCnt <= nSizeElem);// 모든 Elem이 띠형태로 연결되어 있는 경우 (정방향 탐색때 이미 걸러지므로 이상황은 있을수 없다.)
		nCnt++;
	}

	if(aConnectedElem.GetSize() + 1 == aElemKey.GetSize())
	{
		return TRUE;
	}
	else
	{
		return FALSE;
	}
}

