////////////// tsgr ////////////////

void CAttrCtrl::GetTsgrList(CArray<CString, CString&>& rstrTsgrList)
{
	rstrTsgrList.RemoveAll();

	int nCount=GetCountTsgr();
	if(nCount == 0)return;

	POSITION pos;
	T_TSGR_K Key;
	T_TSGR_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartTsgr();
		while(pos != NULL)
		{
			GetNextTsgr(pos, Key, Data);
			if(Data.GroupId == i)
			{
				rstrTsgrList.Add(Data.GroupName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetTsgrKeyList(CArray<T_TSGR_K, T_TSGR_K>& rTsgrKeyList)
{
	/*
	rTsgrKeyList.RemoveAll();

	int nCount=GetCountTsgr();
	if(nCount == 0)return;

	POSITION pos;
	T_TSGR_K Key;
	T_TSGR_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartTsgr();
	while(pos != NULL)
	{
	GetNextTsgr(pos, Key, Data);
	if(Data.GroupId == i)
	{
	rTsgrKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rTsgrKeyList.RemoveAll();
	int nCount=GetCountTsgr();
	if(nCount == 0)return;

	CArray<T_TSGR_K, T_TSGR_K> aTsgrKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rTsgrKeyList.SetSize(nCount);
	aTsgrKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_TSGR_K Key;
	T_TSGR_D Data;
	int i = 0;
	pos = GetStartTsgr();
	while (pos != NULL)
	{
		GetNextTsgr(pos, Key, Data);
		aTsgrKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.GroupId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rTsgrKeyList[i] = aTsgrKey[ix];
	}
}

