// Base Model로 변경하여 
T_TSGR_K CAttrCtrl::GetElemTsgrKey(T_ELEM_K KeyElem)
{
	T_STAG_K KeyCurStag=m_pDoc->m_pStagCtrl->GetCurStag();
	m_pDoc->m_pStagCtrl->ChangeCurStagWithoutUpdateNotify(0);

	T_TSGR_K KeyTsgr=0;
	T_LIST_DATA ListData;
	ElemList* pList;
	POSITION pos;
	if(!m_pDataMemb->m_elem.GetList(KeyElem, pList))
	{
		ASSERT(FALSE);
		goto END;
	}
	pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_TSGR_CMD)
		{
			KeyTsgr=ListData.nKey;
			goto END;
		}
	}

END:
	m_pDoc->m_pStagCtrl->ChangeCurStagWithoutUpdateNotify(KeyCurStag);
	return KeyTsgr;
}

