void CAttrCtrl::GetEssfElem(T_ELEM_K KeyElem, CArray<T_ESSF_K, T_ESSF_K>& rKeyList, CArray<T_ESSF_D, T_ESSF_D&>& rDataList)
{
	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while (pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if (ListData.nCmd == LT_ESSF_CMD)
		{
			T_ESSF_K key;
			T_ESSF_D data;
			key.keymap=ListData.nKey;
			GetEssf(key, data);
			rKeyList.Add(key);
			rDataList.Add(data);
		}
	}
}

BOOL CAttrCtrl::GetEssfElem(T_ELEM_K KeyElem, T_ESSF_D& rData)
{
	CArray<T_ESSF_K, T_ESSF_K> aKey;
	CArray<T_ESSF_D, T_ESSF_D&> aData;
	GetEssfElem(KeyElem, aKey, aData);
	int nNum = aData.GetSize();
	if (nNum == 0) return FALSE;
	
	double dScaleFactorMin[7] = { 1. };
	if (m_pDoc->m_pStagCtrl->IsBaseStag())
	{
		// 하나의 단면에 여러 Secf 데이터가 있는 경우 가장 불리한 경우를 찾는다.     
		for (int j = 0; j < 7; j++)
		{
			dScaleFactorMin[j] = aData[0].dScaleFactor[j]; // mylee secf
		}
		for (int i = 1; i < nNum; i++)
		{
			for (int j = 0; j < 7; j++)
			{
				dScaleFactorMin[j] = min(aData[i].dScaleFactor[j], dScaleFactorMin[j]);
			}
		}
		for (int j = 0; j < 7; j++)
		{
			rData.dScaleFactor[j] = dScaleFactorMin[j];
		}
	}
	else  // 시공단계이면 맨 마지막에 Active된 Secf를 리턴한다.
	{
		// 시공단계에서는 해당 단면에 1개만 되도록 변경됨 : by jbseon 05.03.09
		// 따라서 바로 리턴한다.
		VERIFY(aKey.GetSize() == 1);
		for (int j = 0; j < 7; j++)
		{
			rData.dScaleFactor[j] = aData[0].dScaleFactor[j];
		}

	}
	return TRUE;
}

BOOL CAttrCtrl::GetEssfBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, T_ELEM_K KeyElem, T_ESSF_D& rData)
{
	if (bAllGroup) return GetEssfElem(KeyElem, rData);

	int nBngrKeyNum = raKeyBngr.GetSize();
	if (nBngrKeyNum == 0) return FALSE;
	CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
	mapBngrKey.InitHashTable(HASHSIZEBNGR);
	for (int i = 0; i < nBngrKeyNum; i++)
		mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

	ElemList* pList;
	if (!m_pDataMemb->m_elem.GetList(KeyElem, pList))return FALSE;

	BOOL bFirst=TRUE;
	rData.Initialize();
	T_ESSF_K KeyEssf;
	T_ESSF_D DataEssf;
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while (pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if (ListData.nCmd == LT_ESSF_CMD)
		{
			KeyEssf.keymap = ListData.nKey;
			if (KeyEssf.key.entity == KeyElem)
			{
				GetEssf(KeyEssf, DataEssf);
				if (mapBngrKey.Lookup(DataEssf.GroupKey, DataEssf.GroupKey))
				{
					if (bFirst)
					{
						rData = DataEssf;
						bFirst = FALSE;
					}
					else
					{
						if (DataEssf.dScaleFactor[0] < rData.dScaleFactor[0])
							rData = DataEssf;
					}
				}
			}
		}
	}
	return TRUE;
}

