BOOL CAttrCtrl::GetWssfBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, T_ELEM_K KeyElem, T_WSSF_D& rData)
{
	if (bAllGroup) return GetWssfElem(KeyElem, rData);

	int nBngrKeyNum = raKeyBngr.GetSize();
	if (nBngrKeyNum == 0) return FALSE;
	CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
	mapBngrKey.InitHashTable(HASHSIZEBNGR);
	for (int i = 0; i < nBngrKeyNum; i++)
		mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

	ElemList* pList;
	if(!m_pDataMemb->m_elem.GetList(KeyElem, pList))return FALSE;

	BOOL bFirst=TRUE;
	rData.Initialize();
	T_WSSF_K KeyWssf;
	T_WSSF_D DataWssf;
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_WSSF_CMD)
		{
			KeyWssf.keymap = ListData.nKey;
			if (KeyWssf.key.entity == KeyElem)
			{
				GetWssf(KeyWssf, DataWssf);
				if (mapBngrKey.Lookup(DataWssf.GroupKey, DataWssf.GroupKey))
				{
					if (bFirst)
					{
						rData = DataWssf;
						bFirst = FALSE;
					}
					else
					{
						if (DataWssf.dShear < rData.dShear)
							rData = DataWssf;
					}
				}
			}
		}
	}
	return TRUE;
}

