BOOL CAttrCtrl::GetSerialPssf(T_ELEM_K KeyElem, T_BNGR_K KeyBngr,T_PSSF_KEY& rKeySerial)
{
	ElemList* pList;
	if(!m_pDataMemb->m_elem.GetListFromBaseDB(KeyElem, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_PSSF_CMD)
		{
			T_PSSF_K key;
			T_PSSF_D data;
			key.keymap=ListData.nKey;
			m_pDataMemb->m_pssf.GetFromBaseDB(key, data);
			if(data.GroupKey == KeyBngr)
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_PSSF_K key;
	T_PSSF_D data;
	key.key.entity=KeyElem;
	int j=0;
	while(TRUE)
	{
		j++;
		key.key.serial=j;
		if(!m_pDataMemb->m_pssf.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeKeyPssf(T_ELEM_K KeyElem, T_BNGR_K KeyBngr,T_PSSF_K& rKey)
{
	rKey.key.entity=KeyElem;
	rKey.key.serial=0;

	T_PSSF_KEY KeySerial;
	if(!GetSerialPssf(KeyElem, KeyBngr, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

void CAttrCtrl::GetPssfKeyList(CArray<T_PSSF_K, T_PSSF_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_PSSF_K Key;
	T_PSSF_D Data;
	pos=GetStartPssf();
	while(pos != NULL)
	{
		GetNextPssf(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());  
}

void CAttrCtrl::GetPssfElemKeyList(CArray<T_ELEM_K, T_ELEM_K>& rElemKeyList)
{
	rElemKeyList.RemoveAll();
	CArray<T_PSSF_K, T_PSSF_K> aPssfKeyList;
	GetPssfKeyList(aPssfKeyList);
	int nNum = aPssfKeyList.GetSize();
	if (nNum == 0) return;
	rElemKeyList.Add(aPssfKeyList[0].key.entity);
	for (int i = 1; i < nNum; i++)
	{
		if (aPssfKeyList[i].key.entity == aPssfKeyList[i-1].key.entity)
			continue;
		rElemKeyList.Add(aPssfKeyList[i].key.entity);
	}
}

