BOOL CAttrCtrl::GetPssfElem(T_ELEM_K KeyElem, T_PSSF_D& rData)
{
	CArray<T_PSSF_K, T_PSSF_K> aKey;
	CArray<T_PSSF_D, T_PSSF_D&> aData;
	GetPssfElem(KeyElem, aKey, aData);
	int nNum = aData.GetSize();
	if (nNum == 0) return FALSE;

	double dShearMin = 1.0;  

	// 시공단계중에서 PSSF 데이터 없다.
	// Base Stage, PostCS 모두 동일하게 처리 (by jbseon : 05.03.09
	// 하나의 요소에 여러 Pssf 데이터가 있는 경우 가장 불리한 경우를 찾는다.     

	dShearMin   = aData[0].dShear;    
	for (int i = 1; i < nNum; i++)
	{
		dShearMin   = min(aData[i].dShear,  dShearMin);
	}
	rData.dShear   = dShearMin;    
	return TRUE;
}

