double CAttrCtrl::GetLocalAxisAngle4Dir(T_ELEM_K KeyElem, int nLocalAxis, int nDirType, double OriginPoint[3])
{
	double dAngle = 0.;
	double PlaneLocalVector[3][3]={0.,};
	m_pDoc->calcPlaneLocalVector(KeyElem, PlaneLocalVector);
	T_ELEM_D DataElem;
	if(!GetElem(KeyElem, DataElem)) { ASSERT(0); return dAngle; }

	int nDir = -1;
	if(PlaneLocalVector[2][0]<0.||PlaneLocalVector[2][1]<0.||PlaneLocalVector[2][2]<0.) nDir = 1;

	int nNode=0;
	T_NODE_D	node_p, temp, RefPoint, NodeDTmp;
	RefPoint.x = OriginPoint[0];
	RefPoint.y = OriginPoint[1];
	RefPoint.z = OriginPoint[2];

	double RefVector[3] = {0.0, 0.0, 0.0};
	switch(nDirType)
	{
	case 0:
		RefVector[0]=1.0;
		RefVector[1]=0.0;
		RefVector[2]=0.0;
		break;
	case 1:
		RefVector[0]=0.0;
		RefVector[1]=1.0;
		RefVector[2]=0.0;
		break;
	case 2:
		RefVector[0]=0.0;
		RefVector[1]=0.0;
		RefVector[2]=1.0;
		break;
	case 3:
	case 4:
	case 8:
	case 9:
		{
			nNode = GetNumNode(DataElem.eltyp, DataElem.elnod);
			node_p.Initialize();
			for (int j=0;j<nNode;j++) {
				if(!GetNode(DataElem.elnod[j], NodeDTmp)) { ASSERT(0); continue; }
				temp.x = NodeDTmp.x;
				temp.y = NodeDTmp.y;
				temp.z = NodeDTmp.z;
				node_p.x += temp.x;
				node_p.y += temp.y;
				node_p.z += temp.z;
			}
			node_p.x /= (double) nNode;
			node_p.y /= (double) nNode;
			node_p.z /= (double) nNode;

			switch(nDirType)
			{
			case 3:
				{
					RefVector[0]=node_p.x-RefPoint.x;
					RefVector[1]=node_p.y-RefPoint.y;
					RefVector[2]=node_p.z-RefPoint.z;
				}
				break;
			case 4:
				{
					RefVector[0]=node_p.x-RefPoint.x;
					RefVector[1]=node_p.y-RefPoint.y;
					RefVector[2]=node_p.z-RefPoint.z;
					CMathFunc::mathRotate(nDir*-90., 0., 0., 0., PlaneLocalVector[2][0], PlaneLocalVector[2][1], PlaneLocalVector[2][2], RefVector[0], RefVector[1], RefVector[2]);
				}
				break;
			case 8:
				{
					RefVector[0]=RefPoint.x-node_p.x;
					RefVector[1]=RefPoint.y-node_p.y;
					RefVector[2]=RefPoint.z-node_p.z;
				}
				break;
			case 9:
				{
					RefVector[0]=RefPoint.x-node_p.x;
					RefVector[1]=RefPoint.y-node_p.y;
					RefVector[2]=RefPoint.z-node_p.z;
					CMathFunc::mathRotate(nDir*-90., 0., 0., 0., PlaneLocalVector[2][0], PlaneLocalVector[2][1], PlaneLocalVector[2][2], RefVector[0], RefVector[1], RefVector[2]);
				}
				break;
			}
		}
		break;
	case 5:
		RefVector[0]=-1.0;
		RefVector[1]=0.0;
		RefVector[2]=0.0;
		break;
	case 6:
		RefVector[0]=0.0;
		RefVector[1]=-1.0;
		RefVector[2]=0.0;
		break;
	case 7:
		RefVector[0]=0.0;
		RefVector[1]=0.0;
		RefVector[2]=-1.0;
		break;
	}

	double RefVectorN[3] = {0.0, 0.0, 0.0};
	CMathFunc::mathNormalize(RefVector, RefVectorN);

	// 투영 방향
	double vector_xyz[3] = {PlaneLocalVector[2][0], PlaneLocalVector[2][1], PlaneLocalVector[2][2]};

	// 투영할 대상 평면 (도심 좌표축의 x-y 평면)
	double plane_xyz1[3] = {PlaneLocalVector[0][0], PlaneLocalVector[0][1], PlaneLocalVector[0][2]};	// 도심 좌표축의 x축 상의 점 
	double plane_xyz2[3] = {PlaneLocalVector[1][0], PlaneLocalVector[1][1], PlaneLocalVector[1][2]};	// 도심 좌표축의 y축 상의 점 
	double plane_xyz3[3] = {0.0, 0.0, 0.0};																														// 원점 

	// 투영된 위치 
	const double tolerance = 1.0e-10;
	double projected_node_xyz[3] = {0.0,};

	if (!CMathFunc::project_on_plane_vector(RefVectorN, vector_xyz, plane_xyz1, plane_xyz2, plane_xyz3, tolerance, projected_node_xyz))
	{
		// 투영 방향을 뒤집어서 다시 시도.
		vector_xyz[0] = -vector_xyz[0];
		vector_xyz[1] = -vector_xyz[1];
		vector_xyz[2] = -vector_xyz[2];
		if (!CMathFunc::project_on_plane_vector(RefVectorN, vector_xyz, plane_xyz1, plane_xyz2, plane_xyz3, tolerance, projected_node_xyz))
		{
			ASSERT(0);

			// 못찾으면
			projected_node_xyz[0] = RefVectorN[0];
			projected_node_xyz[1] = RefVectorN[1];
			projected_node_xyz[2] = RefVectorN[2];
		}
	}

	double dTol = 1.0e-2;
	if(nLocalAxis==0)
	{
		dAngle = nDir*CMathFunc::mathCrossAngleNormalizeWithSign(projected_node_xyz, PlaneLocalVector[0], dTol);
	}
	else
	{
		dAngle = nDir*CMathFunc::mathCrossAngleNormalizeWithSign(projected_node_xyz, PlaneLocalVector[1], dTol);
	}

	return dAngle;
}

double CAttrCtrl::GetLocalAxisAngle4Vec(T_ELEM_K KeyElem, int nLocalAxis, double RefVector[3])
{
	double dAngle = 0.;
	T_ELEM_D DataElem;
	if(!GetElem(KeyElem, DataElem)) { ASSERT(0); return dAngle; }

	return GetLocalAxisAngle4Vec(DataElem, nLocalAxis, RefVector);
}

double CAttrCtrl::GetLocalAxisAngle4Vec(T_ELEM_D& DataElem, int nLocalAxis, double RefVector[3])
{
	double dAngle = 0.;
	double PlaneLocalVector[3][3]={0.,};
	m_pDoc->calcPlaneLocalVector(DataElem, PlaneLocalVector);

	int nDir = -1;
	if(PlaneLocalVector[2][0]<0.||PlaneLocalVector[2][1]<0.||PlaneLocalVector[2][2]<0.) nDir = 1;
#ifdef _MGEN_CH
	nDir = -1;
	if(fabs(PlaneLocalVector[2][2]) < 1.e-10)
	{
		if(PlaneLocalVector[2][0] < 0. || PlaneLocalVector[2][1] < 0.) 
			nDir = 1;
	}
	else
	{
		if(PlaneLocalVector[2][2] < 0.)
			nDir = 1;
	}
#endif


	// 투영 방향
	double vector_xyz[3] = {PlaneLocalVector[2][0], PlaneLocalVector[2][1], PlaneLocalVector[2][2]};

	// 투영할 대상 평면 (도심 좌표축의 x-y 평면)
	double plane_xyz1[3] = {PlaneLocalVector[0][0], PlaneLocalVector[0][1], PlaneLocalVector[0][2]};	// 도심 좌표축의 x축 상의 점 
	double plane_xyz2[3] = {PlaneLocalVector[1][0], PlaneLocalVector[1][1], PlaneLocalVector[1][2]};	// 도심 좌표축의 y축 상의 점 
	double plane_xyz3[3] = {0.0, 0.0, 0.0};																														// 원점 

	// 투영된 위치 
	const double tolerance = 1.0e-10;
	double projected_node_xyz[3] = {0.0,};

	double RefVectorN[3] = {0.0, 0.0, 0.0};
	CMathFunc::mathNormalize(RefVector, RefVectorN);
	if (!CMathFunc::project_on_plane_vector(RefVectorN, vector_xyz, plane_xyz1, plane_xyz2, plane_xyz3, tolerance, projected_node_xyz))
	{
		// 투영 방향을 뒤집어서 다시 시도.
		vector_xyz[0] = -vector_xyz[0];
		vector_xyz[1] = -vector_xyz[1];
		vector_xyz[2] = -vector_xyz[2];
		if (!CMathFunc::project_on_plane_vector(RefVectorN, vector_xyz, plane_xyz1, plane_xyz2, plane_xyz3, tolerance, projected_node_xyz))
		{
			ASSERT(0);

			// 못찾으면
			projected_node_xyz[0] = RefVectorN[0];
			projected_node_xyz[1] = RefVectorN[1];
			projected_node_xyz[2] = RefVectorN[2];
		}
	}

	double dTol = 1.0e-2;
	if(nLocalAxis==0)
	{
		dAngle = nDir*CMathFunc::mathCrossAngleNormalizeWithSign(projected_node_xyz, PlaneLocalVector[0]);
	}
	else
	{
		dAngle = nDir*CMathFunc::mathCrossAngleNormalizeWithSign(projected_node_xyz, PlaneLocalVector[1]);
	}

	return dAngle;
}

BOOL CAttrCtrl::IsSkipAnalData(T_PSSF_D& PssfD)
{
	const double dValue = 1.0;
	if (CCompFunc::CompRealTol(PssfD.dAxialX	 , dValue, CMathFunc::m_NormalZero) != 0) return FALSE;
	if (CCompFunc::CompRealTol(PssfD.dAxialY	 , dValue, CMathFunc::m_NormalZero) != 0) return FALSE;
	if (CCompFunc::CompRealTol(PssfD.dShear		 , dValue, CMathFunc::m_NormalZero) != 0) return FALSE;
	if (CCompFunc::CompRealTol(PssfD.dOutBendingX, dValue, CMathFunc::m_NormalZero) != 0) return FALSE;
	if (CCompFunc::CompRealTol(PssfD.dOutBendingY, dValue, CMathFunc::m_NormalZero) != 0) return FALSE;
	if (CCompFunc::CompRealTol(PssfD.dOutTorsion , dValue, CMathFunc::m_NormalZero) != 0) return FALSE;
	if (CCompFunc::CompRealTol(PssfD.dOutShearX  , dValue, CMathFunc::m_NormalZero) != 0) return FALSE;
	if (CCompFunc::CompRealTol(PssfD.dOutShearY  , dValue, CMathFunc::m_NormalZero) != 0) return FALSE;
	return TRUE;
}
////////////// matl ////////////////
BOOL CAttrCtrl::IsUsedMatl(T_MATL_K Key)
{
	BOOL bUsed = m_pDataMemb->m_elem.IsUsedMatl(Key);
	if (bUsed) return TRUE;

	// 텐던 Type에도 사용되었는지 조사
	T_TDNT_K TdntKey;
	T_TDNT_D TdntData;
	POSITION pos = m_pDataMemb->m_tdnt.GetStart();
	while (pos)
	{
		m_pDataMemb->m_tdnt.GetNext(pos, TdntKey, TdntData);
		if (TdntData.MatlKey == Key) return TRUE;
	}

	// Sub Domain에도 사용되었는지 조사
	T_SBDO_K SbdoKey;
	T_SBDO_D SbdoData;
	pos = m_pDataMemb->m_sbdo.GetStart();
	while (pos)
	{
		m_pDataMemb->m_sbdo.GetNext(pos, SbdoKey, SbdoData);
		if (SbdoData.bRebarMatl && SbdoData.RebarMatlK == Key) return TRUE;
	}

	return FALSE;
}

