T_MATL_K CAttrCtrl::GetNextNumMatl(T_MATL_K StartNum)
{
	if(StartNum > GetLastNumMatl())return StartNum;
	T_MATL_K Key=StartNum;
	T_MATL_D Data;
	while(TRUE)
	{
		Key++;
		if(!m_pDataMemb->m_matl.Get(Key,Data))
		{
			if(Key < D_MATL_MINNUM || Key > D_MATL_MAXNUM)
				return GetStartNumMatl();
			else
				return Key;
		}
	}
}

T_MATL_K CAttrCtrl::GetLastNumMatlUnused()
{
	T_MATL_K KeyLast=m_pDataMemb->m_matl.m_nLastNum;
	while(TRUE)
	{
		if(!IsUsedMatl(KeyLast) && !ExistMatl(KeyLast))
		{
			if(KeyLast < D_MATL_MINNUM || KeyLast > D_MATL_MAXNUM)
				return GetStartNumMatlUnused();
			else
				return KeyLast;
		}
		KeyLast++;
	}
}

T_MATL_K CAttrCtrl::GetStartNumMatlUnused()
{
	T_MATL_K KeyStart=m_pDataMemb->m_matl.m_nStartNum;
	while(TRUE)
	{
		if(!IsUsedMatl(KeyStart) && !ExistMatl(KeyStart))return KeyStart;
		KeyStart++;
	}
}

T_MATL_K CAttrCtrl::GetNextNumMatlUnused(T_MATL_K StartNum)
{
	if(StartNum > GetLastNumMatlUnused())return StartNum;
	T_MATL_K KeyNext=StartNum+1;
	while(TRUE)
	{
		if(!IsUsedMatl(KeyNext) && !ExistMatl(KeyNext))return KeyNext;
		KeyNext++;
	}
}

void CAttrCtrl::GetKeyListMatlUser(CArray<T_MATL_K, T_MATL_K>* pKeyMatl,
								   CArray<T_NODE_K, T_NODE_K>* pKeyNode, CArray<T_ELEM_K, T_ELEM_K>* pKeyElem)
{
	if(pKeyNode != NULL)pKeyNode->RemoveAll();
	if(pKeyElem != NULL)pKeyElem->RemoveAll();
	if(pKeyNode == NULL && pKeyElem == NULL)return;
	if(pKeyMatl==NULL) {ASSERT(0); return;}
	int nCount=pKeyMatl->GetSize();
	if(nCount == 0)return;

	CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K>KeyElemMap;
	KeyElemMap.InitHashTable(m_pDoc->GetHashSizeElem());

	POSITION pos;
	T_ELEM_K KeyElem;
	T_ELEM_D DataElem;

	pos=GetStartElem();
	while(pos != NULL)
	{
		GetNextElem(pos, KeyElem, DataElem);
		for(int i=0; i<nCount; i++)if(DataElem.elmat == pKeyMatl->GetAt(i))KeyElemMap.SetAt(KeyElem, KeyElem);
	}

	GetKeyListNodeElem(KeyElemMap, pKeyNode, pKeyElem);
}

void CAttrCtrl::GetMatlKeyListUsedInElem(CArray<T_MATL_K, T_MATL_K>& rKeyList)
{
	T_MATL_K KeyMatl;
	int nNum;
	rKeyList.RemoveAll();
	POSITION pos;
	pos=m_pDataMemb->m_elem.GetStartMatlCount();
	while(pos != NULL)
	{
		m_pDataMemb->m_elem.GetNextMatlCount(pos, KeyMatl, nNum);
		rKeyList.Add(KeyMatl);
	}
	if(rKeyList.GetSize() != 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
#ifdef _DEBUG
	CArray<T_MATL_K, T_MATL_K> rKeyList2;
	rKeyList2.RemoveAll();
	CMap<T_MATL_K, T_MATL_K, T_MATL_K, T_MATL_K>mapMatl;
	mapMatl.InitHashTable(HASHSIZEMATL);

	T_ELEM_K Key;
	T_ELEM_D Data;
	pos=GetStartElem();
	while(pos != NULL)
	{
		GetNextElem(pos, Key, Data);
		if(IsNeedMatl(Data.eltyp))mapMatl.SetAt(Data.elmat, Data.elmat);
	}
	pos=mapMatl.GetStartPosition();
	while(pos != NULL)
	{
		mapMatl.GetNextAssoc(pos, KeyMatl, KeyMatl);
		rKeyList2.Add(KeyMatl);
	}
	if(rKeyList2.GetSize() != 0)CQSort::QSortUInt(rKeyList2.GetData(), rKeyList2.GetSize());
	if (rKeyList.GetSize() != rKeyList2.GetSize()) 
		GSaveHistoryFormatNF(_LS(IDS_DBLIB__ADDED__Matl_Different_in_Size_));
	else
	{
		int i = 0;
		for (i = 0; i < rKeyList.GetSize(); i++)
			if (rKeyList[i] != rKeyList2[i]) break;
		if (i != rKeyList.GetSize()) 
			GSaveHistoryFormatNF(_LS(IDS_DBLIB__ADDED__Matl_Different_in_member_));
	}
#endif
}

