BOOL CAttrCtrl::GetMatlDesign(T_MATL_K Key,T_MATD_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_matl.GetDesign(Key,rData);
	if(bReturn)
	{
		m_pUnitCtrl->ConvertUnitMatdOut(rData);
		// Concrete, SRC의 concrete None인 경우 해석용의 탄성계수, 포아송 쓴다.
		if (rData.Type == _T("C") && rData.Data1.CodeName == _T(""))
		{
			T_MATL_D MatlD;
			VERIFY(GetMatl(Key, MatlD));
			rData.Data1.Analysis.Elast = MatlD.Data1.Analysis.Elast;
			rData.Data1.Analysis.Poisson = MatlD.Data1.Analysis.Poisson;

			// PSC Composite
			rData.Data2.Analysis.Elast = MatlD.Data1.Analysis.Elast;
			rData.Data2.Analysis.Poisson = MatlD.Data1.Analysis.Poisson;

		}
		if (rData.Type == _T("SRC") && rData.Data2.CodeName == _T(""))
		{
			T_MATL_D MatlD;
			VERIFY(GetMatl(Key, MatlD));
			rData.Data2.Analysis.Elast = MatlD.Data2.Analysis.Elast;
			rData.Data2.Analysis.Poisson = MatlD.Data2.Analysis.Poisson;
		}
	}
	return bReturn;
}

