// 특정 재질과 단면으로 정의된 요소 리스트 가져오기
int CAttrCtrl::GetElemKeyListMatlSectUser(CArray<T_MATL_K, T_MATL_K>* pKeyMatl,
										  CArray<T_SECT_K, T_SECT_K>* pKeySect,
										  CArray<T_ELEM_K, T_ELEM_K>* pKeyElem/*=NULL*/)
{
	if(pKeyElem != NULL) pKeyElem->RemoveAll();
	else                 return 0;

	if(pKeyMatl == NULL || pKeyMatl->GetSize() == 0)
	{
		GetKeyListSectUser(pKeySect, 0, pKeyElem);
		return pKeyElem->GetSize();

	}
	if(pKeySect == NULL || pKeySect->GetSize() == 0)
	{
		GetKeyListMatlUser(pKeyMatl, 0, pKeyElem);
		return pKeyElem->GetSize();
	}

	CArray<T_ELEM_K, T_ELEM_K> aMatlElem, aSectElem;
	aMatlElem.RemoveAll(); aSectElem.RemoveAll();

	GetKeyListMatlUser(pKeyMatl, 0, &aMatlElem);
	GetKeyListSectUser(pKeySect, 0, &aSectElem);

	CArrayUtil::IntersectUINT(aMatlElem, aSectElem, *pKeyElem);

	qsort(pKeyElem->GetData(), pKeyElem->GetSize(), sizeof(UINT), CCompFunc::UINTAsc);

	return pKeyElem->GetSize();
}
int CAttrCtrl::GetElemKeyListMatlSectUser(T_MATL_K MatlK, T_SECT_K SectK,
										  CArray<T_ELEM_K, T_ELEM_K>* pKeyElem/*=NULL*/)
{
	if(pKeyElem != NULL) pKeyElem->RemoveAll();
	else                 return 0;

	CArray<T_MATL_K, T_MATL_K> aMatlK; 
	aMatlK.RemoveAll();
	if(MatlK != NULL) aMatlK.Add(MatlK);
	CArray<T_SECT_K, T_SECT_K> aSectK; 
	aSectK.RemoveAll();
	if(SectK != NULL) aSectK.Add(SectK);

	return GetElemKeyListMatlSectUser(&aMatlK, &aSectK, pKeyElem);
}

int CAttrCtrl::GetElemKeyListMatlSectUser4AMR(CArray<T_MATL_K, T_MATL_K>* pKeyMatl, T_SECT_K SectK)
{
	if(pKeyMatl == NULL || pKeyMatl->GetSize() == 0)
	{
		return 0;	
	}
	if(SectK==0)
	{
		ASSERT(0);
		return 0;
	}

	CArray<T_ELEM_K, T_ELEM_K> aMatlElem, aSectElem;
	aMatlElem.RemoveAll(); aSectElem.RemoveAll();

	CArray<T_SECT_K, T_SECT_K> aSectK; aSectK.RemoveAll();
	aSectK.Add(SectK);

	GetKeyListMatlUser(pKeyMatl, 0, &aMatlElem);
	GetKeyListSectUser(&aSectK, 0, &aSectElem);

	CArray<T_ELEM_K, T_ELEM_K> aKeyElem;
	CArrayUtil::IntersectUINT(aMatlElem, aSectElem, aKeyElem);

	qsort(aKeyElem.GetData(), aKeyElem.GetSize(), sizeof(UINT), CCompFunc::UINTAsc);

	return aKeyElem.GetSize();
}

T_MATL_K CAttrCtrl::GetMatlKey(CString& rMatlName)
{
	T_MATL_K key;
	T_MATL_D data;
	CString strMatlName=rMatlName;
	strMatlName.TrimRight();

	POSITION pos=m_pDataMemb->m_matl.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_matl.GetNext(pos,key,data);
		if(strMatlName.CompareNoCase(data.Name) == 0)
		{
			return key;
		}
	}
	return FALSE;
}

////////////// secf ////////////////
BOOL CAttrCtrl::GetSerialSecf(T_SECT_K KeySect, T_BNGR_K KeyBngr,T_SECF_KEY& rKeySerial)
{
	SectList* pList;
	if(!m_pDataMemb->m_sect.GetList(KeySect, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_SECF_CMD)
		{
			T_SECF_K key;
			T_SECF_D data;
			key.keymap=ListData.nKey;
			m_pDataMemb->m_secf.GetFromBaseDB(key, data);
			if(data.GroupKey == KeyBngr)
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_SECF_K key;
	T_SECF_D data;
	key.key.entity=KeySect;
	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_secf.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeKeySecf(T_SECT_K KeySect, T_BNGR_K KeyBngr,T_SECF_K& rKey)
{
	rKey.key.entity=KeySect;
	rKey.key.serial=0;

	T_SECF_KEY KeySerial;
	if(!GetSerialSecf(KeySect, KeyBngr, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

