void CAttrCtrl::GetSecfSectKeyList(CArray<T_SECT_K, T_SECT_K>& rSectKeyList)
{
	rSectKeyList.RemoveAll();
	CArray<T_SECF_K, T_SECF_K> aSecfKeyList;
	GetSecfKeyList(aSecfKeyList);
	int nNum = aSecfKeyList.GetSize();
	if (nNum == 0) return;
	rSectKeyList.Add(aSecfKeyList[0].key.entity);
	for (int i = 1; i < nNum; i++)
	{
		if (aSecfKeyList[i].key.entity == aSecfKeyList[i-1].key.entity)
			continue;
		rSectKeyList.Add(aSecfKeyList[i].key.entity);
	}
}

