void CAttrCtrl::GetSecfSect(T_SECT_K KeySect, CArray<T_SECF_K, T_SECF_K>& rKeyList, CArray<T_SECF_D, T_SECF_D&>& rDataList)
{
	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	SectList* pList;
	VERIFY(m_pDataMemb->m_sect.GetList(KeySect, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_SECF_CMD)
		{
			T_SECF_K key;
			T_SECF_D data;
			key.keymap=ListData.nKey;
			if (!GetSecf(key, data)) continue;
			rKeyList.Add(key);
			rDataList.Add(data);
		}
	}
}

BOOL CAttrCtrl::GetSecfSect(T_SECT_K KeySect, T_SECF_D& rData)
{
	if (!ExistSect(KeySect)) return FALSE;
	CArray<T_SECF_K, T_SECF_K> aKey;
	CArray<T_SECF_D, T_SECF_D&> aData;
	GetSecfSect(KeySect, aKey, aData);
	int nNum = aData.GetSize();
	if (nNum == 0) return FALSE;
	double dScaleFactorMin[7] = {1.};
	double dScaleFactorMinJ[7] = {1.};
	double dWarpingScaleFactorMin = 1.;
	double dWarpingScaleFactorMinJ = 1.;
	if (m_pDoc->m_pStagCtrl->IsBaseStag())
	{   
		// 하나의 단면에 여러 Secf 데이터가 있는 경우 가장 불리한 경우를 찾는다.     
		for(int j = 0; j < 7; j++) 
		{
			dScaleFactorMin[j] = aData[0].dScaleFactor[j]; // mylee secf
			dScaleFactorMinJ[j] = aData[0].dScaleFactorJ[j];
		}
		dWarpingScaleFactorMin = aData[0].dWarpingScaleFactor;
		dWarpingScaleFactorMinJ = aData[0].dWarpingScaleFactorJ;
		for(int i = 1; i < nNum; i++)
		{
			for(int j = 0; j < 7; j++)
			{
				dScaleFactorMin[j] = min(aData[i].dScaleFactor[j], dScaleFactorMin[j]);          
				dScaleFactorMinJ[j] = min(aData[i].dScaleFactorJ[j], dScaleFactorMinJ[j]);
			}
			dWarpingScaleFactorMin = min(aData[i].dWarpingScaleFactor, dWarpingScaleFactorMin);
			dWarpingScaleFactorMinJ = min(aData[i].dWarpingScaleFactorJ, dWarpingScaleFactorMinJ);
		}
		for(int j = 0; j < 7; j++)
		{ 
			rData.dScaleFactor[j] = dScaleFactorMin[j];    
			rData.dScaleFactorJ[j] = dScaleFactorMinJ[j];    
		}
		rData.dWarpingScaleFactor = dWarpingScaleFactorMin;
		rData.dWarpingScaleFactorJ = dWarpingScaleFactorMinJ;
	}
	else  // 시공단계이면 맨 마지막에 Active된 Secf를 리턴한다.
	{
		// 시공단계에서는 해당 단면에 1개만 되도록 변경됨 : by jbseon 05.03.09
		// 따라서 바로 리턴한다.
		VERIFY(aKey.GetSize() == 1);
		for (int j = 0; j < 7; j++) 
		{ 
			rData.dScaleFactor[j] = aData[0].dScaleFactor[j]; 
			rData.dScaleFactorJ[j] = aData[0].dScaleFactorJ[j];
		}
		dWarpingScaleFactorMin = aData[0].dWarpingScaleFactor;
		dWarpingScaleFactorMinJ = aData[0].dWarpingScaleFactorJ;

		/*
		int nStageId = 0;
		T_STAG_K StagK;
		T_STAG_D StagD;
		BOOL bStartSect = TRUE; 
		for (int i = 0; i < aKey.GetSize(); i++)
		{
		StagK = m_pDoc->m_pStagCtrl->GetActivatedStageOfSecf(aKey[i]);
		if (!GetStag(StagK, StagD)) continue;
		if (StagD.nStageId > nStageId)
		{
		if(bStartSect)
		{
		for(j = 0; j < 7; j++) dScaleFactorMin[j] = aData[i].dScaleFactor[j];
		bStartSect = FALSE;
		}
		for(j = 0; j < 7; j++) dScaleFactorMin[j] = min(aData[i].dScaleFactor[j], dScaleFactorMin[j]);
		}
		}
		for(j = 0; j < 7; j++) rData.dScaleFactor[j] = dScaleFactorMin[j];    
		*/
	}
	return TRUE;
}

BOOL CAttrCtrl::GetSecfBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, T_SECT_K KeySect, T_SECF_D& rData)
{
	if (bAllGroup) return GetSecfSect(KeySect, rData);

	int nBngrKeyNum = raKeyBngr.GetSize();
	if (nBngrKeyNum == 0) return FALSE;
	CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
	mapBngrKey.InitHashTable(HASHSIZEBNGR);
	for (int i = 0; i < nBngrKeyNum; i++)
		mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

	SectList* pList;
	if(!m_pDataMemb->m_sect.GetList(KeySect, pList))return FALSE;

	BOOL bFirst=TRUE;
	rData.Initialize();
	T_SECF_K KeySecf;
	T_SECF_D DataSecf;
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_SECF_CMD)
		{
			KeySecf.keymap = ListData.nKey;
			if (KeySecf.key.entity == KeySect)
			{
				GetSecf(KeySecf, DataSecf);
				if (mapBngrKey.Lookup(DataSecf.GroupKey, DataSecf.GroupKey))
				{
					if (bFirst)
					{
						rData = DataSecf;
						bFirst = FALSE;
					}
					else
					{
						if (DataSecf.dScaleFactor[0] < rData.dScaleFactor[0])
							rData = DataSecf;
					}
				}
			}
		}
	}
	return TRUE;
}

void CAttrCtrl::GetSecfKeyListBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, CArray<T_SECF_K, T_SECF_K>& rKeyList)
{
	rKeyList.RemoveAll();
	if(bAllGroup) GetSecfKeyList(rKeyList);
	else
	{
		int nBngrKeyNum = raKeyBngr.GetSize();
		if (nBngrKeyNum == 0) return;
		CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
		mapBngrKey.InitHashTable(HASHSIZEBNGR);
		for (int i = 0; i < nBngrKeyNum; i++)
			mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

		T_SECF_D DataSecf;
		GetSecfKeyList(rKeyList);
		for(int i = rKeyList.GetSize() - 1; i >= 0; i--)
		{
			GetSecf(rKeyList[i], DataSecf); 
			if(!mapBngrKey.Lookup(DataSecf.GroupKey, DataSecf.GroupKey)) 
				rKeyList.RemoveAt(i);
		}
	}
}

