void CAttrCtrl::GetMphgKeyList(CArray<T_MPHG_K, T_MPHG_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_MPHG_K Key;
	T_MPHG_D Data;
	pos=GetStartMphg();
	while(pos != NULL)
	{
		GetNextMphg(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

