void CAttrCtrl::GetCscsKeyList(CArray<T_CSCS_K, T_CSCS_K>& rKeyList)
{
	rKeyList.RemoveAll();
	int nCount = GetCountCscs();
	if (nCount == 0) return;

	CArray<int, int> aActStagNo;
	CMap<T_STAG_K, T_STAG_K, int, int> mStagK2No;
	mStagK2No.InitHashTable(HASHSIZESTAG);

	POSITION pos;
	T_STAG_K StagK;
	T_STAG_D StagD;
	pos = GetStartStag();
	while (pos != NULL)
	{
		GetNextStag(pos, StagK, StagD);
		mStagK2No.SetAt(StagK, StagD.nStageId);
	}

	int nStagNo;
	T_CSCS_K Key;
	T_CSCS_D Data;
	pos=GetStartCscs();
	while(pos != NULL)
	{
		GetNextCscs(pos, Key, Data);
		rKeyList.Add(Key);
		VERIFY(mStagK2No.Lookup(Data.ActStagKey, nStagNo));
		aActStagNo.Add(nStagNo);
	}
	//if(rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
	if (rKeyList.GetSize() > 0)
		CQSort::QSortIntWithIndex((int*)rKeyList.GetData(), aActStagNo.GetData(), rKeyList.GetSize());
}

int CAttrCtrl::GetCscsList(T_SECT_K SectK, CArray<T_CSCS_K, T_CSCS_K>& rKeyList, CArray<T_CSCS_D, T_CSCS_D&>& rDataList)
{
	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	T_CSCS_D CscsD;
	CArray<T_CSCS_K, T_CSCS_K> aCscsK;
	GetCscsKeyList(aCscsK);
	for (int i = 0; i < aCscsK.GetSize(); i++)
	{
		GetCscs(aCscsK[i], CscsD);
		if (CscsD.SectKey == SectK)
		{
			rKeyList.Add(aCscsK[i]);
			rDataList.Add(CscsD);
		}
	}

	return rKeyList.GetSize();
}

