T_CSCS_K CAttrCtrl::GetCscsKey(T_CSCS_D& rData)
{
	POSITION pos;
	T_CSCS_K Key;
	T_CSCS_D Data;
	pos=GetStartCscs();
	while(pos != NULL)
	{
		GetNextCscs(pos, Key, Data);
		if (Data.SectKey == rData.SectKey &&
			Data.ActStagKey == rData.ActStagKey)
			return Key;
	}
	return 0;
}

