void CAttrCtrl::Calc_H_OfCscsBefore730(T_CSCS_D& Data) // MNET:2840 20070711 mylee - 이전버전 H 값 Convert
{
	for(int pidx=0 ; pidx<Data.aPart.GetSize() ; ++pidx)
	{
		Data.aPart[pidx].dH=0.0;
		Data.aPart[pidx].dVS=0.0;
		Data.aPart[pidx].dM=0.0;

		if(Data.aPart[pidx].MatlKey==0) // 1) Element --------------------
		{
			// 변경: Element 인 경우는 0. 으로 세팅
			// 재변경: 같은 EDMP 재질에 연결된 경우는 그 H 값을 가져옴, 다를 경우는 0
			CArray<T_ELEM_K, T_ELEM_K> aElemK;
			CArray<T_ELEM_K, T_ELEM_K> arNewActiveElem;
			CNewlyActivatedElemInStag ElemInStage;
			ElemInStage.Initialize(this);
			ElemInStage.GetNewlyActivatedElemList(BEAM_EL, Data.ActStagKey, arNewActiveElem);
			int nCount = arNewActiveElem.GetSize(); // 그 중에서 Section Type이 일치하는 Element 찾음
			for(int j=0; j<nCount; ++j) {
				T_ELEM_D ElemData;
				if(GetElem(arNewActiveElem[j], ElemData)) {
					if(IsNeedSect(ElemData.eltyp)) {
						if(ElemData.elpro == Data.SectKey) aElemK.Add(arNewActiveElem[j]);
					}
				}
			}

			// Edmp 일치 찾음
			BOOL bEdmpAllOk = TRUE;
			T_EDMP_D EdmpD;
			double dEdmpH = 0.;
			for(int j=0 ; j<aElemK.GetSize() ; ++j)
			{
				if(!GetEdmp(aElemK[j], EdmpD)) {bEdmpAllOk=FALSE; break;}
				if(EdmpD.nType != 0) {bEdmpAllOk=FALSE; break;}

				if(j==0) dEdmpH = EdmpD.h;
				else
				{
					if(dEdmpH != EdmpD.h) {bEdmpAllOk=FALSE; break;}
				}
			}
			if(bEdmpAllOk) Data.aPart[pidx].dH = dEdmpH;

			// Edmp 일치하지 않을 때에, 차선책으로 Matl 의 Tdmt 의 H 값이 모두 일치하는 경우 찾음
			if(!bEdmpAllOk)
			{
				BOOL bTdmtAllOk = TRUE;
				double dTdmtH = 0.;
				T_ELEM_D ElemD;
				T_TMAT_D TmatD;
				T_TDMT_D TdmtD;
				for(int j=0 ; j<aElemK.GetSize() ; ++j)
				{
					if(!GetElem(aElemK[j], ElemD)) {bTdmtAllOk=FALSE; break;}
					if(!GetTmat(ElemD.elmat, TmatD)) {bTdmtAllOk=FALSE; break;}
					if(TmatD.TdMatlTypeKey == 0) {bTdmtAllOk=FALSE; break;}
					if(!GetTdmt(TmatD.TdMatlTypeKey, TdmtD)) {bTdmtAllOk=FALSE; break;}
					int nCode = TdmtD.COMMON.nCode;
					if(!(nCode==2 || nCode==5 || nCode==8 || nCode==9 || nCode==11 || nCode==13))
					{
						bTdmtAllOk=FALSE;
						break;
					}
					double dCurH = 0.;
					switch(TdmtD.COMMON.nCode)
					{
					case  2: dCurH=TdmtD.CEB.dMemberSize;     break;
					case  5: dCurH=TdmtD.CEB.dMemberSize;     break;
					case  8: dCurH=TdmtD.JAPAN.dMemberSize;   break;
					case  9: dCurH=TdmtD.CHINA.dMemberSize;   break;
					case 11: dCurH=TdmtD.CHJTG04.dMemberSize; break;
					case 13: dCurH=TdmtD.CEB.dMemberSize;     break;
					}
					if(j==0) dTdmtH = dCurH;
					else
					{
						if(dTdmtH != dCurH) {bTdmtAllOk=FALSE; break;}
					}
				}
				if(bTdmtAllOk) Data.aPart[pidx].dH = dTdmtH;
			}

		}
		else // 2) Material --------------------
		{
			T_MATL_K MatlK = Data.aPart[pidx].MatlKey;
			T_TMAT_D TmatD;
			T_TDMT_D TdmtD;
			if(GetTmat(MatlK, TmatD) && TmatD.TdMatlTypeKey != 0)
			{
				if(GetTdmt(TmatD.TdMatlTypeKey, TdmtD))
				{
					// 1:ACI, 2:CEB, 3:Modify Elasticity Modulus, 4:User defined, 5:KS, 6:PCA, 
					// 7:Combined(ACI&PCA), 8:JAPAN, 9:CHINA, 10:JPJSCE, 11:China(JTG D62-2004),
					// 12:AASHTO
					double dH=0.;
					switch(TdmtD.COMMON.nCode)
					{
					case  1: dH=0.; break;
					case  2: dH=TdmtD.CEB.dMemberSize; break;
					case  3: dH=0.; break;
					case  4: dH=0.; break;
					case  5: dH=TdmtD.CEB.dMemberSize; break;
					case  6: dH=0.; break;
					case  7: dH=0.; break;
					case  8: dH=TdmtD.JAPAN.dMemberSize; break;
					case  9: dH=TdmtD.CHINA.dMemberSize; break;
					case 10: dH=0.; break;
					case 11: dH=TdmtD.CHJTG04.dMemberSize; break;
					case 12: dH=0.; break;
					case 13: dH=TdmtD.CEB.dMemberSize; break;
					}
					Data.aPart[pidx].dH=dH;
				}
			}
		}
	}
}

BOOL CAttrCtrl::Get_H_FromCscs(int nSize, T_CSCS_D CscsData, CArray<double, double>& aH)
{
	int nIndex = 0; // 1 번 Row 에 대해서 계산하는 것처럼
	if (nSize <= 0) return FALSE;
	if (nSize == 1) nSize = 2;
	aH.RemoveAll();
	aH.SetSize(nSize);

	T_SECT_D SectData; SectData.Initialize();

	int nCount = CscsData.aPart.GetSize();
	CArray<T_STAG_K, T_STAG_K> aKeyList;
	m_pDoc->m_pAttrCtrl->GetStagKeyList(aKeyList);

	if (CscsData.nCompType == -1) return FALSE; // User 인 경우 return FALSE 하여 무조건 0 세팅

	if (CscsData.nCompType == 0 || CscsData.nCompType == 1) // 1+2 & 3, 1 & 2+3
	{
		if (nCount != 3) { ASSERT(0); return FALSE; }
		if (aKeyList.GetSize() < 2) return FALSE;

		if (nIndex == 0)
		{
			CscsData.aPart[0].CompStagKey = aKeyList[0];
			CscsData.aPart[2].CompStagKey = aKeyList[1];
			if (CscsData.nCompType == 0)
				CscsData.aPart[1].CompStagKey = aKeyList[0];
			else if (CscsData.nCompType == 1)
				CscsData.aPart[1].CompStagKey = aKeyList[1];
			else ASSERT(0);
		}
		else if (nIndex == 1)
		{
			CscsData.aPart[0].CompStagKey = aKeyList[1];
			CscsData.aPart[2].CompStagKey = aKeyList[0];
			if (CscsData.nCompType == 0)
				CscsData.aPart[1].CompStagKey = aKeyList[1];
			else if (CscsData.nCompType == 1)
				CscsData.aPart[1].CompStagKey = aKeyList[0];
			else ASSERT(0);
		}
	}
	else if (CscsData.nCompType == -2/* || CscsData.nCompType == -1*/) // Normal, not user
	{
		if (aKeyList.GetSize() < CscsData.aPart.GetSize()) return FALSE;

		unsigned int k = 1;
		for (int i = 0; i < nCount; i++)
		{
			if (nIndex == i)
				CscsData.aPart[i].CompStagKey = aKeyList[0];
			else
				CscsData.aPart[i].CompStagKey = aKeyList[k++];
		}
	}

	if (!m_pDoc->m_pAttrCtrl->GetSect(CscsData.SectKey, SectData))
		return FALSE;

	CArray<int, int&> aIndex;
	CArray<T_SECT_D, T_SECT_D&> aResult;
	CArray<T_SECT_D, T_SECT_D&> aCsResult; //2004.05.19 Add Ahn,Jaeoh
	if (CscsData.aPart.GetSize() <= 0) return FALSE;

	// MNET:3964-CJJEONG-20090320 (Tel : 2124) 
	// Tapered 에 Composite General 을 추가하기 위해 처리
	if (SectData.nStype == D_SECT_TYPE_COMPO_G || (SectData.nStype == D_SECT_TYPE_TAPERED && SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_G))
	{ // 계산 안함
	}
	else if (m_pDoc->m_pSectDB->IsSectDumbAndStub(SectData))
	{// 계산 안함
	}
	else
	{
		if (!m_pDoc->m_pSectDB->CalcSectCscs(SectData, CscsData, aResult, aIndex, aCsResult))
			return FALSE;
	}

	// SectData의 종류에 따라 정확한 위치에서 PeriIn, PeriOut 가져와서 계산
	// 1) User
	if (SectData.nStype == D_SECT_TYPE_USER) {} // do nothing
	else if (m_pDoc->m_pSectDB->IsSectDumbAndStub(SectData)) {} // do nothing
	// 2) Psc
	else if (SectData.nStype == D_SECT_TYPE_PSC)
	{
		if (aResult.GetSize() > 1)
		{
			double dUOut = aResult[0].SectBefore.SectI.PeriOut;
			double dAc = aResult[0].SectBefore.SectI.Stiffness.Area;
			if (dUOut != 0) aH[0] = 2 * dAc / dUOut;

			dUOut = aResult[1].SectBefore.SectI.PeriOut;
			dAc = aResult[1].SectBefore.SectI.Stiffness.Area;
			if (dUOut != 0) aH[1] = 2 * dAc / dUOut;
		}
	}
	// 3) Composite
	else if (SectData.nStype == D_SECT_TYPE_COMPO_B || SectData.nStype == D_SECT_TYPE_COMPO_I ||
		SectData.nStype == D_SECT_TYPE_COMPO_TUB || SectData.nStype == D_SECT_TYPE_COMPO_STLG_B ||
		SectData.nStype == D_SECT_TYPE_COMPO_STLG_I || SectData.nStype == D_SECT_TYPE_COMPO_STLG_TUB ||
		SectData.nStype == D_SECT_TYPE_COMPO_CI || SectData.nStype == D_SECT_TYPE_COMPO_CT ||
		SectData.nStype == D_SECT_TYPE_COMPO_PC)
	{
		if (aResult.GetSize() > 1)
		{
			// Part 1
			double dUOut = aResult[0].SectBefore.SectI.PeriOut;
			double dAc = aResult[0].SectBefore.SectI.Stiffness.Area;
			if (dUOut != 0) aH[0] = 2 * dAc / dUOut;

			// Part 2
			double dB = SectData.SectAfter.SectI.Size[0]; // Slab Width
			double dTc = SectData.SectAfter.SectJ.Size[1];
			dAc = dB * dTc;
			dUOut = 2 * dB + 2 * dTc;
			if (dUOut != 0) aH[1] = 2 * dAc / dUOut;
		}
	}
	// 3-1) Composite General Section
	else if (SectData.nStype == D_SECT_TYPE_COMPO_G)
	{
		int nPartNum = SectData.SectBefore.SectI.aGeneralPart.GetSize();
		for (int i = 0; i < nSize; ++i)
		{
			if (i > nPartNum - 1) break;

			double dUOut = SectData.SectBefore.SectI.aGeneralPart[i].PeriOut;
			double dAc = SectData.SectBefore.SectI.aGeneralPart[i].Stiffness.Area;
			if (dUOut != 0) aH[i] = 2 * dAc / dUOut;
		}
	}
	// 4) Tapered
	else if (SectData.nStype == D_SECT_TYPE_TAPERED)
	{
		if (SectData.SectBefore.nStype == D_SECT_TYPE_PSC)
		{
			if (aResult.GetSize() > 1)
			{
				double dUOut = aResult[0].SectBefore.SectI.PeriOut;
				double dAc = aResult[0].SectBefore.SectI.Stiffness.Area;
				double dUOutJ = aResult[0].SectBefore.SectJ.PeriOut;
				double dAcJ = aResult[0].SectBefore.SectJ.Stiffness.Area;
				if (dUOut != 0 && dUOutJ != 0) aH[0] = ((2 * dAc / dUOut) + (2 * dAcJ / dUOutJ)) / 2;

				dUOut = aResult[1].SectBefore.SectI.PeriOut;
				dAc = aResult[1].SectBefore.SectI.Stiffness.Area;
				dUOutJ = aResult[1].SectBefore.SectJ.PeriOut;
				dAcJ = aResult[1].SectBefore.SectJ.Stiffness.Area;
				if (dUOut != 0 && dUOutJ != 0) aH[1] = ((2 * dAc / dUOut) + (2 * dAcJ / dUOutJ)) / 2;
			}
		}
		else if (SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_B || SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_I ||
			SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_TUB || SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_STLG_B ||
			SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_STLG_I || SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_STLG_TUB ||
			SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_CI || SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_CT ||
			SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_PC)
		{
			if (aResult.GetSize() > 1)
			{
				// Part 1
				double dUOut = aResult[0].SectBefore.SectI.PeriOut;
				double dAc = aResult[0].SectBefore.SectI.Stiffness.Area;
				double dUOutJ = aResult[0].SectBefore.SectJ.PeriOut;
				double dAcJ = aResult[0].SectBefore.SectJ.Stiffness.Area;
				if (dUOut != 0 && dUOutJ != 0) aH[0] = ((2 * dAc / dUOut) + (2 * dAcJ / dUOutJ)) / 2;

				// Part 2
				double dB = SectData.SectAfter.SectI.Size[0]; // Slab Width
				double dTc = SectData.SectAfter.SectJ.Size[1];
				double dBJ = SectData.CmpTapJ.Size[59]; // Slab Width
				double dTcJ = SectData.SectAfter.SectJ.Size[1];
				dAc = dB * dTc;
				dUOut = 2 * dB + 2 * dTc;
				dAcJ = dBJ * dTcJ;
				dUOutJ = 2 * dBJ + 2 * dTcJ;
				if (dUOut != 0 && dUOutJ != 0) aH[1] = ((2 * dAc / dUOut) + (2 * dAcJ / dUOutJ)) / 2;
			}
		}
		// MNET:3964-CJJEONG-20090320 (Tel : 2124) 
		// Tapered 에 Composite General 을 추가하기 위해 처리
		else if (SectData.SectBefore.nStype == D_SECT_TYPE_COMPO_G)
		{
			int nPartNum = min(SectData.SectBefore.SectI.aGeneralPart.GetSize(), SectData.SectBefore.SectJ.aGeneralPart.GetSize());
			for (int i = 0; i < nSize; ++i)
			{
				if (i > nPartNum - 1) break;

				// 계산식은 아래와 같이 이루어 지나 자동계산을 안 하기로 해서 0으로 처리함..
				//double dUOut = SectData.SectBefore.SectI.aGeneralPart[i].PeriOut;
				//double dAc = SectData.SectBefore.SectI.aGeneralPart[i].Stiffness.Area;
				//double dUOutJ = SectData.SectBefore.SectJ.aGeneralPart[i].PeriOut;
				//double dAcJ = SectData.SectBefore.SectJ.aGeneralPart[i].Stiffness.Area;
				//if(dUOut !=0 && dUOutJ !=0) aH[i] = ((2 * dAc / dUOut)+(2 * dAcJ / dUOutJ)) / 2;
				aH[i] = 0.0;
			}
			// 대화상자의 성공 카운트를 올리지 않기 위해 return FALSE 함
			return FALSE;
		}
	}
	else
	{
		ASSERT(0);
	}

	// MNET:1603 20080213 mylee - Japan Code 일 때, 2 로 나눠주는 코드
	ASSERT(aH.GetSize() >= 2);
	if (CscsData.nCompType == -1) // User
	{
		ASSERT(0); // 위에서 걸러짐
		return FALSE;
	}
	else if (CscsData.nCompType == 0 || CscsData.nCompType == 1) // 1+2 & 3, 1 & 2+3
	{
		if (IsJapanCode4Cscs(CscsData.aPart[0], CscsData)) aH[0] /= 2.0;
		if (IsJapanCode4Cscs(CscsData.aPart[2], CscsData)) aH[1] /= 2.0;
	}
	else if (CscsData.nCompType == -2) // Normal
	{
		if (IsJapanCode4Cscs(CscsData.aPart[0], CscsData)) aH[0] /= 2.0;
		if (IsJapanCode4Cscs(CscsData.aPart[1], CscsData)) aH[1] /= 2.0;
	}

	return TRUE;
}

BOOL CAttrCtrl::IsJapanCode4Cscs(T_CSCS_BASE &Part, const T_CSCS_D& CscsD)
{
	if (Part.MatlKey == 0) // Element
	{
		CArray<T_ELEM_K, T_ELEM_K> arNewActiveElem;
		CNewlyActivatedElemInStag ElemInStage;
		ElemInStage.Initialize(m_pDoc->m_pAttrCtrl);
		if (!ElemInStage.GetNewlyActivatedElemList(BEAM_EL, CscsD.ActStagKey, arNewActiveElem))
			return FALSE;

		T_MATL_K MatlK;
		CMap<T_MATL_K, T_MATL_K, int, int> mapMatlK;
		// 그 중에서 Section Type이 일치하는 Element 찾음
		int nCount = arNewActiveElem.GetSize();
		for (int i = 0; i < nCount; i++)
		{
			T_ELEM_D ElemData;
			if (m_pDoc->m_pAttrCtrl->GetElem(arNewActiveElem[i], ElemData))
			{
				// 단면이 필요한 요소종류 중에서 단면 키가 같은 요소들만 
				if (m_pDoc->m_pAttrCtrl->IsNeedSect(ElemData.eltyp) && ElemData.elpro == CscsD.SectKey)
				{
					mapMatlK.SetAt(ElemData.elmat, 1);
				}
			}
		}
		// 재질들이 모두 Japan 기준이어야 함
		int nTmp;
		BOOL bTmatExist = FALSE;
		BOOL bTdmtExist = FALSE;
		BOOL bJapanCode = FALSE;
		if (mapMatlK.GetCount() == 0) return FALSE;
		POSITION pos = mapMatlK.GetStartPosition();
		while (pos)
		{
			mapMatlK.GetNextAssoc(pos, MatlK, nTmp);
			T_MATL_D MatlData;
			T_TMAT_D TmatData;
			T_TDMT_D TdmtData;
			if (!m_pDoc->m_pAttrCtrl->GetMatl(MatlK, MatlData)) return FALSE;

			bTmatExist = m_pDoc->m_pAttrCtrl->GetTmat(MatlK, TmatData);
			if (bTmatExist) bTdmtExist = m_pDoc->m_pAttrCtrl->GetTdmt(TmatData.TdMatlTypeKey, TdmtData);
			if (bTdmtExist) bJapanCode = (TdmtData.COMMON.nCode == 8); // Japan Standard인 경우
			if (!bTmatExist || !bTdmtExist || !bJapanCode) return FALSE;
		}
		return TRUE; // 모두 무사통과
	}
	else
	{
		T_MATL_K MatlK = Part.MatlKey;
		T_MATL_D MatlData;
		T_TMAT_D TmatData;
		T_TDMT_D TdmtData;
		BOOL bTmatExist = FALSE;
		BOOL bTdmtExist = FALSE;
		BOOL bJapanCode = FALSE;
		if (!m_pDoc->m_pAttrCtrl->GetMatl(MatlK, MatlData)) return FALSE;

		bTmatExist = m_pDoc->m_pAttrCtrl->GetTmat(MatlK, TmatData);
		if (bTmatExist) bTdmtExist = m_pDoc->m_pAttrCtrl->GetTdmt(TmatData.TdMatlTypeKey, TdmtData);
		if (bTdmtExist) bJapanCode = (TdmtData.COMMON.nCode == 8); // Japan Standard인 경우
		if (!bTmatExist || !bTdmtExist || !bJapanCode) return FALSE;

		return TRUE;
	}
}

//------------------------------------------------------------------------
// cscs util function
BOOL CAttrCtrl::IsSectCscsType(T_SECT_K SectK)
{
	// 현재는 구현의 편리를 위해 간단하게 작성한다.
	// 향후 성능 향상을 위해 관련 데이타를 관리할 필요가 있다.

	// (추가) 이 함수는 시공단계합성단면으로 사용되는지 개략적으로만 판단함.
	// 실제 사용여부를 잘 살펴봐야함.
	T_SECT_D SectD;
	if (!GetSect(SectK, SectD)) return FALSE;
	switch(SectD.nStype)
	{
	case D_SECT_TYPE_REGULAR      : return FALSE;
	case D_SECT_TYPE_SRC          : break;
	case D_SECT_TYPE_USER         : return FALSE;
	case D_SECT_TYPE_COMBINED     : return FALSE;
	case D_SECT_TYPE_STLG_B       : return FALSE;
	case D_SECT_TYPE_STLG_I       : return FALSE;
	case D_SECT_TYPE_STLG_MCELL   : return FALSE;
	case D_SECT_TYPE_TAPERED      : 
		switch(SectD.SectBefore.nStype)
		{
		case D_SECT_TYPE_COMPO_B       : return TRUE;
		case D_SECT_TYPE_COMPO_I       : return TRUE;
		case D_SECT_TYPE_COMPO_TUB     : return TRUE;
		case D_SECT_TYPE_COMPO_STLG_B  : return TRUE;
		case D_SECT_TYPE_COMPO_STLG_I  : return TRUE;
		case D_SECT_TYPE_COMPO_STLG_TUB: return TRUE;
		case D_SECT_TYPE_COMPO_CI      : return TRUE;
		case D_SECT_TYPE_COMPO_CT      : return TRUE;
			// MNET:3964-CJJEONG-20090320 (Tel : 2124) 
			// Tapered 에 Composite General 을 추가하기 위해 처리
		case D_SECT_TYPE_COMPO_G       : return TRUE;
		}

		if (SectD.SectBefore.nStype != D_SECT_TYPE_PSC) return FALSE;
		else  //if (SectD.SectBefore.nStype == D_SECT_TYPE_PSC)
		{
			if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_3CELL) return FALSE;
			if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_4CELL) return FALSE;
			if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_T) return FALSE;
			if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_BOX) return FALSE;
			if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_I) return FALSE;
			if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_NCEL2) return FALSE;
			if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_MID)
			{
				// MID의 경우 둘다 Polygon인 경우만 된다.
				if (SectD.SectBefore.nCellType != 2 ||
					SectD.SectBefore.nCellShape != 2 ) return FALSE;
			}
			if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_HALF)
			{
				// Half의 경우 Circle은 안 된다.
				if (SectD.SectBefore.nCellShape == 1) return FALSE;
			}
		}
		break;
	case D_SECT_TYPE_CONSTRUCTION   :
		{
			// Composite User 단면은  before / after 단면이 각각 있다.
			if(SectD.SectBefore.nStype!=0 && SectD.SectAfter.nStype!=0) return TRUE;
			else return FALSE;

		}
	case D_SECT_TYPE_HIBEAM        : return FALSE;
	case D_SECT_TYPE_COLDFORMED    : return FALSE;
	case D_SECT_TYPE_COMPO_B       : break;
	case D_SECT_TYPE_COMPO_I       : break;
	case D_SECT_TYPE_COMPO_TUB     : break;
	case D_SECT_TYPE_COMPO_STLG_B  : break;
	case D_SECT_TYPE_COMPO_STLG_I  : break;
	case D_SECT_TYPE_COMPO_STLG_TUB: break;
	case D_SECT_TYPE_COMPO_CI      : break;
	case D_SECT_TYPE_COMPO_CT      : break;
	case D_SECT_TYPE_COMPO_PC      : break;
	case D_SECT_TYPE_COMPO_G       : break;
	case D_SECT_TYPE_PSC           : 
		if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_3CELL) return FALSE;
		if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_4CELL) return FALSE;
		if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_T) return FALSE;
		if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_BOX) return FALSE;
		if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_I) return FALSE;
		if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_NCEL2) return FALSE;
		if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_MID)
		{
			// MID의 경우 둘다 Polygon인 경우만 된다.
			if (SectD.SectBefore.nCellType != 2 ||
				SectD.SectBefore.nCellShape != 2 ) return FALSE;
		}
		if (SectD.SectBefore.Shape == D_SECT_SHAPE_PSC_HALF)
		{
			// Half의 경우 Circle은 안 된다.
			if (SectD.SectBefore.nCellShape == 1) return FALSE;
		}
		break;
	}

	return TRUE;
}

// 특정 Stage에서 주어진 단면의 합성 정보를 T_CSCS_D에 반환
// aPart는 현재 Stage에서의 합성된 정보만 가지게 된다.
// 0:오류 또는 시공 합성 단면 아님
// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)
int CAttrCtrl::GetElemSectCompositeInfo(T_ELEM_K ElemK, T_STAG_K StagK, T_CSCS_D& rCscsD)
{
	// 현재는 구현의 편리를 위해 간단하게 리턴한다.
	// 향후 성능(속도) 향상을 위해 관련 데이타를 관리할 필요가 있다.

	// 0. 선행 작업 : 요소의 단면 번호 알아내고 시공합성단면의 후보인지 판별
	T_ELEM_D ElemD;
	T_SECT_K SectK;
	if (!GetElem(ElemK, ElemD)) return 0;
	if (!IsFrameType(ElemD.eltyp)) return 0;
	if (IsTruss(ElemD.eltyp)) return 0;
	if (!IsSectCscsType(ElemD.elpro)) return 0;
	SectK = ElemD.elpro;

	// 1. 요소가 Active되는 Stage를 알아낸다. 
	// 주어진 Stage에 가장 근접한 Active Stage를 알아낸다.
	T_STAG_K ElemActStagK = 0;
	T_STAG_D TempStagD;
	T_STAG_K TempStagK = StagK;

	if (m_pDoc->m_pStagCtrl->IsMinMaxStagkey(TempStagK) || 
		m_pDoc->m_pStagCtrl->IsFinalStagKey(TempStagK)   )
		TempStagK = m_pDataMemb->m_stag.GetLastStag();

	int nReqStageId;
	if (!GetStag(TempStagK, TempStagD)) return 0;
	nReqStageId = TempStagD.nStageId;

	CMap<T_GRUP_K, T_GRUP_K, T_GRUP_K, T_GRUP_K> mElemGrupK;  // 요소가 속한 그룹
	mElemGrupK.InitHashTable(11);

	// change base stage for temporary
	T_STAG_K CurStagK = m_pDoc->m_pStagCtrl->GetCurStag();
	m_pDoc->m_pStagCtrl->ChangeCurStagWithoutUpdateNotify(0);
	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(ElemK, pList));
	m_pDoc->m_pStagCtrl->ChangeCurStagWithoutUpdateNotify(CurStagK);

	T_LIST_DATA ListData;
	POSITION pos = pList->GetHeadPosition();
	while (pos != NULL)
	{
		ListData = pList->GetNext(pos);
		if (ListData.nCmd == LT_GRUP_CMD)
			mElemGrupK.SetAt(ListData.nKey, ListData.nKey);
	}
	if (mElemGrupK.GetCount() == 0) return 0; // Group에 속하지 않았기 때문에 시공단계 포함 불가능

	CArray<T_STAG_K, T_STAG_K> aStagK;
	GetStagKeyList(aStagK);
	for (int i = 0; i < nReqStageId; i++)
	{
		GetStag(aStagK[i], TempStagD);
		T_GRUP_K TempGrupK;
		if (ElemActStagK == 0)  // Active되지 않았다면 이번에 Active되었는지 검사
		{
			for (int j = 0; j < TempStagD.aActiveElem.GetSize(); j++)
				if (mElemGrupK.Lookup(TempStagD.aActiveElem[j].GrupKey, TempGrupK))
				{
					ElemActStagK = aStagK[i];
					break;
				}
		}
		if (ElemActStagK != 0)  // Active되었다면 이번에 Deactive되었는지 검사
		{
			for (int j = 0; j < TempStagD.aDeactiveElem.GetSize(); j++)
				if (mElemGrupK.Lookup(TempStagD.aDeactiveElem[j].GrupKey, TempGrupK))
				{
					ElemActStagK = 0;
					break;
				}
		}
	}
	if (ElemActStagK == 0) return 0;  // Active 안 되었으면 0 리턴

	// 2. 해당 CSCS 정보를 알아낸다.(요소 Active Stage와 단면 번호 이용)
	T_CSCS_K TempCscsK;
	T_CSCS_D TempCscsD;
	BOOL bFound = FALSE;
	pos = GetStartCscs();
	while (pos != 0)
	{
		GetNextCscs(pos, TempCscsK, TempCscsD);
		if (TempCscsD.ActStagKey == ElemActStagK &&
			TempCscsD.SectKey == SectK)
		{
			bFound = TRUE;
			break;
		}
	}
	if (!bFound) return 0;

	// 3. 주어진 Stage에서 Part 결합 상태를 알아낸다.
	rCscsD = TempCscsD;
	rCscsD.aPart.RemoveAll();

	CMap<T_STAG_K, T_STAG_K, int, int> mStagK2Id;
	mStagK2Id.InitHashTable(1001);
	for (int j = 0; j < nReqStageId; j++)
		mStagK2Id.SetAt(aStagK[j], j+1);

	int nStageId;
	if (!mStagK2Id.Lookup(TempCscsD.ActStagKey, nStageId)) return 1;  // 합성 전

	for (int j = 0; j < TempCscsD.aPart.GetSize(); j++)
	{
		BOOL bComposite = FALSE;
		if (TempCscsD.aPart[j].CompStagKey == 0) bComposite = TRUE;
		else 
		{
			if (mStagK2Id.Lookup(TempCscsD.aPart[j].CompStagKey, nStageId)) bComposite = TRUE;
		}

		if (bComposite) rCscsD.aPart.Add(TempCscsD.aPart[j]);
	}
	if (rCscsD.aPart.GetSize() != TempCscsD.aPart.GetSize()) return 2;  // 합성 중
	return 3; // 합성 후
}

//////////////////////////////////////////////////////////////////////////
// 특정 Stage에서 주어진 단면의 합성 정보를 T_CSCS_D에 반환
// aPart는 현재 Stage에서의 합성된 정보만 가지게 된다.
// 0:오류 또는 시공 합성 단면 아님
// 1:시공 합성 단면 : 합성 전 (Active Stage 이전)
// 2:시공 합성 단면 : 합성 중 (Active되고 모든 Part가 합성되기 전)
// 3:시공 합성 단면 : 합성 후 (모든 Part가 합성된 후)

int CAttrCtrl::GetSecvCompositeInfo(T_VBEM_K VbemK, T_STAG_K StagK, T_CSCS_D& rCscsD)
{
	// 현재는 구현의 편리를 위해 간단하게 리턴한다.
	// 향후 성능(속도) 향상을 위해 관련 데이타를 관리할 필요가 있다.

	// 0. 선행 작업 : 요소의 단면 번호 알아내고 시공합성단면의 후보인지 판별
	//T_ELEM_D ElemD;
	T_SECV_K SecvK = VbemK;
	if (!m_pDoc->m_pAttrCtrl2->ExistSecv(SecvK)) return 0;
	if (!ExistCscv(SecvK)) return 0;

	// 1. 요소가 Active되는 Stage를 알아낸다. 
	// 주어진 Stage에 가장 근접한 Active Stage를 알아낸다.
	T_STAG_K ElemActStagK = 0;
	T_STAG_D TempStagD;
	T_STAG_K TempStagK = StagK;

	if (m_pDoc->m_pStagCtrl->IsMinMaxStagkey(TempStagK) ||
		m_pDoc->m_pStagCtrl->IsFinalStagKey(TempStagK))
		TempStagK = m_pDataMemb->m_stag.GetLastStag();

	int nReqStageId;
	if (!GetStag(TempStagK, TempStagD)) return 0;
	nReqStageId = TempStagD.nStageId;

	CMap<T_GRUP_K, T_GRUP_K, T_GRUP_K, T_GRUP_K> mElemGrupK;  // 요소가 속한 그룹
	mElemGrupK.InitHashTable(11);

	//////////////////////////////////////////////////////////////////////////
	// 가상보의 요소들
	CArray<T_ELEM_K, T_ELEM_K> aElemK;    //aElemK.Copy(VsecD.arKeyElem);
 
	// change base stage for temporary
	T_STAG_K CurStagK = m_pDoc->m_pStagCtrl->GetCurStag();
	m_pDoc->m_pStagCtrl->ChangeCurStagWithoutUpdateNotify(0);

	T_VBEM_D VbemD;
	if (!m_pDoc->m_pAttrCtrl2->GetVbem(VbemK, VbemD)) { ASSERT(0); }

	for (int nIJ = 0; nIJ < 2; ++nIJ)
	{
		T_VSEC_K VsecK = (nIJ == 0) ? VbemD.Vsec1 : VbemD.Vsec2;
		T_VSEC_D  VsecD;
		if (!m_pDoc->m_pAttrCtrl2->GetVsec(VsecK, VsecD)) { ASSERT(0);  continue; }

		CArray<T_ELEM_K, T_ELEM_K> aElemK_SL;  //Slab
		CArray<T_ELEM_K, T_ELEM_K> aElemK_GR;  //Girder
		m_pDoc->m_pAttrCtrl2->GetSecvGirderSlabElem(VsecK, aElemK_GR, aElemK_SL);

		if (aElemK_GR.GetSize() > 0)
		{
			aElemK.Append(aElemK_GR);
		}
	}

	if(aElemK.GetSize() == 0) return 0;

	// 설계용 가상보는 항상 같은 그룹으로 지정됨. 
	// 그래서 첫번째 요소로만 검토함. - 추후 개선이 필요할 수 있음.
	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(aElemK[0], pList));
	m_pDoc->m_pStagCtrl->ChangeCurStagWithoutUpdateNotify(CurStagK);
	//////////////////////////////////////////////////////////////////////////

	T_LIST_DATA ListData;
	POSITION pos = pList->GetHeadPosition();
	while (pos != NULL)
	{
		ListData = pList->GetNext(pos);
		if (ListData.nCmd == LT_GRUP_CMD)
			mElemGrupK.SetAt(ListData.nKey, ListData.nKey);
	}
	if (mElemGrupK.GetCount() == 0) return 0; // Group에 속하지 않았기 때문에 시공단계 포함 불가능

	CArray<T_STAG_K, T_STAG_K> aStagK;
	GetStagKeyList(aStagK);
	for (int i = 0; i < nReqStageId; i++)
	{
		GetStag(aStagK[i], TempStagD);
		T_GRUP_K TempGrupK;
		if (ElemActStagK == 0)  // Active되지 않았다면 이번에 Active되었는지 검사
		{
			for (int j = 0; j < TempStagD.aActiveElem.GetSize(); j++)
				if (mElemGrupK.Lookup(TempStagD.aActiveElem[j].GrupKey, TempGrupK))
				{
					ElemActStagK = aStagK[i];
					break;
				}
		}
		if (ElemActStagK != 0)  // Active되었다면 이번에 Deactive되었는지 검사
		{
			for (int j = 0; j < TempStagD.aDeactiveElem.GetSize(); j++)
				if (mElemGrupK.Lookup(TempStagD.aDeactiveElem[j].GrupKey, TempGrupK))
				{
					ElemActStagK = 0;
					break;
				}
		}
	}
	if (ElemActStagK == 0) return 0;  // Active 안 되었으면 0 리턴

	// 2. 해당 CSCS 정보를 알아낸다.(요소 Active Stage와 단면 번호 이용)
	T_CSCV_K TempCscvK;
	T_CSCV_D TempCscvD;
	BOOL bFound = FALSE;
	pos = GetStartCscv();
	while (pos != 0)
	{
		GetNextCscv(pos, TempCscvK, TempCscvD);
		if (TempCscvD.ActStagKey == ElemActStagK &&
			TempCscvD.SectKey == SecvK)
		{
			bFound = TRUE;
			break;
		}
	}
	if (!bFound) return 0;


	T_CSCS_D TempCscsD;
	TempCscvD.ConvertToCscs(TempCscsD);

	// 3. 주어진 Stage에서 Part 결합 상태를 알아낸다.
	rCscsD = TempCscsD;
	rCscsD.aPart.RemoveAll();

	CMap<T_STAG_K, T_STAG_K, int, int> mStagK2Id;
	mStagK2Id.InitHashTable(1001);
	for (int j = 0; j < nReqStageId; j++)
		mStagK2Id.SetAt(aStagK[j], j + 1);

	int nStageId;
	if (!mStagK2Id.Lookup(TempCscsD.ActStagKey, nStageId)) return 1;  // 합성 전

	for (int j = 0; j < TempCscsD.aPart.GetSize(); j++)
	{
		BOOL bComposite = FALSE;
		if (TempCscsD.aPart[j].CompStagKey == 0) bComposite = TRUE;
		else
		{
			if (mStagK2Id.Lookup(TempCscsD.aPart[j].CompStagKey, nStageId)) bComposite = TRUE;
		}

		if (bComposite) rCscsD.aPart.Add(TempCscsD.aPart[j]);
	}
	if (rCscsD.aPart.GetSize() != TempCscsD.aPart.GetSize()) return 2;  // 합성 중
	return 3; // 합성 후
}

int CAttrCtrl::GetElemSectCompositeInfoDgn(ElemPairK ElemK, T_STAG_K StagK, T_CSCS_D& rCscsD)
{
	if (ElemK.second == EN_EL_BEAM)
	{
		return GetElemSectCompositeInfo(ElemK.first, StagK, rCscsD);
	}
	else if (ElemK.second == EN_EL_VBEAM)
	{
		return GetSecvCompositeInfo(ElemK.first, StagK, rCscsD);
	}
	else ASSERT(0);

	return 0;
}


BOOL CAttrCtrl::ConverCscsDataFromDependentMateriaData()
{
	//
	CMap<T_MATL_K, T_MATL_K, T_TDMT_K, T_TDMT_K> mapTdmtK;
	T_TMAT_D TmatD;
	CArray<T_TMAT_K, T_TMAT_K> rTmatKList;
	GetTmatKeyList(rTmatKList);

	for (int i = 0; i < rTmatKList.GetSize(); i++)
	{
		GetTmat(rTmatKList[i], TmatD);
		if (TmatD.TdMatlTypeKey > 0)
		{
			T_TDMT_D TdmtD;
			GetTdmt(TmatD.TdMatlTypeKey, TdmtD);
			if (TdmtD.RUSSIA.dExposeSurfM > 0.0)
			{
				mapTdmtK.SetAt(rTmatKList[i], TmatD.TdMatlTypeKey);
			}
		}
	}
	if (mapTdmtK.GetSize() < 1) return TRUE;

	//
	T_CSCS_D CscsD;
	CArray<T_CSCS_K, T_CSCS_K> rCscsKList;
	GetCscsKeyList(rCscsKList);
	for (int i = 0; i < rCscsKList.GetSize(); i++)
	{
		GetCscs(rCscsKList[i], CscsD);

		CArray<T_ELEM_K, T_ELEM_K> arNewActiveElem;
		CNewlyActivatedElemInStag ElemInStage;
		ElemInStage.Initialize(m_pDoc->m_pAttrCtrl);
		if (!ElemInStage.GetNewlyActivatedElemList(BEAM_EL, rCscsKList[i], arNewActiveElem))
			return TRUE;

		if (arNewActiveElem.GetSize() < 1) return TRUE;

		T_ELEM_D ElemD;
		GetElem(arNewActiveElem[0], ElemD);
		//ElemD.elmat;  // Matl Key

		BOOL bChangeData = FALSE;
		T_TDMT_K TdmtKTemp;
		for (int j = 0; j < CscsD.aPart.GetSize(); j++)
		{
			T_MATL_K MatlKey;
			T_CSCS_BASE& tPart = CscsD.aPart[j];
			if (tPart.MatlKey == 0) MatlKey = ElemD.elmat;
			else                   MatlKey = tPart.MatlKey;

			if (!mapTdmtK.Lookup(MatlKey, TdmtKTemp)) continue;
			if (tPart.dH > 0.0)
			{
				tPart.dM = 1 / tPart.dH;
				tPart.dH = 0.0;
				bChangeData = TRUE;
			}
		}
		if (bChangeData)
		{
			if (!m_pDoc->m_pEditData->AddCscs(rCscsKList[i], CscsD)) ASSERT(0);
		}
	}

	return TRUE;
}

