void CAttrCtrl::GetCscvKeyList(CArray<T_CSCV_K, T_CSCV_K>& rKeyList)
{
	rKeyList.RemoveAll();
	int nCount = GetCountCscv();
	if (nCount == 0) return;

	CArray<int, int> aActStagNo;
	CMap<T_STAG_K, T_STAG_K, int, int> mStagK2No;
	mStagK2No.InitHashTable(HASHSIZESTAG);

	POSITION pos;
	T_STAG_K StagK;
	T_STAG_D StagD;
	pos = GetStartStag();
	while (pos != NULL)
	{
		GetNextStag(pos, StagK, StagD);
		mStagK2No.SetAt(StagK, StagD.nStageId);
	}

	int nStagNo;
	T_CSCV_K Key;
	T_CSCV_D Data;
	pos = GetStartCscv();
	while (pos != NULL)
	{
		GetNextCscv(pos, Key, Data);
		rKeyList.Add(Key);
		VERIFY(mStagK2No.Lookup(Data.ActStagKey, nStagNo));
		aActStagNo.Add(nStagNo);
	}
	//if(rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
	if (rKeyList.GetSize() > 0)
		CQSort::QSortIntWithIndex((int*)rKeyList.GetData(), aActStagNo.GetData(), rKeyList.GetSize());
}

int CAttrCtrl::GetCscvList(T_SECV_K SecvK, CArray<T_CSCV_K, T_CSCV_K>& rKeyList, CArray<T_CSCV_D, T_CSCV_D&>& rDataList)
{
	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	T_CSCV_D CscvD;
	CArray<T_CSCV_K, T_CSCV_K> aCscvK;
	GetCscvKeyList(aCscvK);
	for (int i = 0; i < aCscvK.GetSize(); i++)
	{
		GetCscv(aCscvK[i], CscvD);
		if (CscvD.SectKey == SecvK)
		{
			rKeyList.Add(aCscvK[i]);
			rDataList.Add(CscvD);
		}
	}

	return rKeyList.GetSize();
}

