BOOL CAttrCtrl::GetRpsc(T_RPSC_K Key,T_RPSC_D& rData)
{
#if defined(_CIVIL)
	T_RPSC_SSM_D RpscSSMD; RpscSSMD.Initialize();
	BOOL bReturn = m_pDoc->m_pAttrCtrl2->GetRpscSsm(Key, RpscSSMD);
	if(!m_pDoc->m_pAttrCtrl2->ConvertRpscSSMtoRpsc(Key, RpscSSMD, rData)) bReturn = FALSE;

	// Rpsc 에서는 PSC, Composite 만 지원한다. Data Check 해야한다.
	if(bReturn)
	{
		if(!m_pDoc->m_pAttrCtrl2->CheckRpscSectType(Key)) 
		{
			bReturn = FALSE;
			rData.Initialize();
		}

		// test : Civil일때 RC/SRC에 RPSC_SSM이 입력되어 있으면 ASSERT
		if(m_pDoc->m_pAttrCtrl2->CheckRpscSectType_Gen(Key)) 
		{
			ASSERT(0);
			bReturn = FALSE;
			rData.Initialize();
		}
	}
	return bReturn;
#else
	if(m_pDoc->m_pAttrCtrl2->CheckRpscSectType_Gen(Key)) 
	{
		BOOL bReturnGenSSM=FALSE;
		T_RPSC_SSM_D RpscSSMD; RpscSSMD.Initialize();
		BOOL bReturn = m_pDoc->m_pAttrCtrl2->GetRpscSsm(Key, RpscSSMD);
		if(m_pDoc->m_pAttrCtrl2->ConvertRpscSSMtoRpsc(Key, RpscSSMD, rData)) bReturnGenSSM = TRUE;

		return bReturnGenSSM;
	}
	else
	{
		BOOL bReturn=m_pDataMemb->m_rpsc.Get(Key,rData);
		if(bReturn)m_pUnitCtrl->ConvertUnitRpscOut(rData);
		return bReturn;
	}

#endif
}

BOOL CAttrCtrl::GetRpscByConsiderRbar(BOOL bMbar,T_RPSC_K Key,T_RPSC_D& rData)
{
#if defined(_CIVIL)
	// Add by ZINU.('05.09.21). Check bMbar Option.
	if(!bMbar)	return GetRpsc(Key,rData);	// If Sbar, GetRpsc().

	// Add by ZINU.('05.03.29). Check Consider Rbar Option.
	BOOL bReturn = GetRpsc(Key,rData);

	T_ACTL_D ActlD;
	if(!GetActl(ActlD))	ActlD.Initialize();
	BOOL bConsiderRbar = ActlD.bConsiderRbar;

	// Add by ZINU.('05.09.05). Separate PSC Design from Others.
	// 6=PSC-Design/Strn, 7=Always Consider.
	if(m_pDoc->GetDesignStatus()==6)
	{
		// Add by ZINU.('06.08.02). NO:2365, Always bConsiderRbar=TRUE, if JTG D62-04.
		// Requested by Kye BJ.
		T_PSCD_D PscdD;
		if(!GetDgnPscd(PscdD)) PscdD.Initialize();
		if(PscdD.iDgnCode==JTG_D62_04)	bConsiderRbar = TRUE;
		else if(PscdD.iDgnCode==JSCE02)
		{
			// Modification, Jaeoh [6/20/2011], JSCE02일 경우 해석옵션을 우선시함 
			if(bConsiderRbar) bConsiderRbar = CDBLib::IsConsiderRbarForDgn();
			else {}
		}
		else														bConsiderRbar = CDBLib::IsConsiderRbarForDgn();
	}
	else if(m_pDoc->GetDesignStatus()==7)	bConsiderRbar = TRUE;

	if(!bConsiderRbar)
	{
		rData.Mbar[0].RemoveAll();
		rData.Mbar[1].RemoveAll();
	}
	return bReturn;
#else
	// Add by ZINU.('05.09.21). Check bMbar Option.
	if(!bMbar)	return GetRpsc(Key,rData);	// If Sbar, GetRpsc().

	// Add by ZINU.('05.03.29). Check Consider Rbar Option.
	//   BOOL bReturn=m_pDataMemb->m_rpsc.Get(Key,rData);
	//   if(bReturn)m_pUnitCtrl->ConvertUnitRpscOut(rData);
	BOOL bReturn = GetRpsc(Key,rData);

	T_ACTL_D ActlD;
	if(!GetActl(ActlD))	ActlD.Initialize();
	BOOL bConsiderRbar = ActlD.bConsiderRbar;

	// Add by ZINU.('05.09.05). Separate PSC Design from Others.
	// 6=PSC-Design/Strn, 7=Always Consider.
	if(m_pDoc->GetDesignStatus()==6)
	{
		// Add by ZINU.('06.08.02). NO:2365, Always bConsiderRbar=TRUE, if JTG D62-04.
		// Requested by Kye BJ.
		T_PSCD_D PscdD;
		if(!GetDgnPscd(PscdD)) PscdD.Initialize();
		if(PscdD.iDgnCode==JTG_D62_04)	bConsiderRbar = TRUE;
		else														bConsiderRbar = CDBLib::IsConsiderRbarForDgn();
	}
	else if(m_pDoc->GetDesignStatus()==7)	bConsiderRbar = TRUE;

	if(!bConsiderRbar)
	{
		rData.Mbar[0].RemoveAll();
		rData.Mbar[1].RemoveAll();
	}
	return bReturn;
#endif
}

