BOOL CAttrCtrl::GetRpsd(T_RPSC_K Key,T_RPSC_D& rData)
{
#if defined(_CIVIL)
	T_RPSC_SSM_D RpscSSMD; RpscSSMD.Initialize();
	BOOL bReturn = m_pDoc->m_pAttrCtrl2->GetRpsdSsm(Key, RpscSSMD);

	//////////////////////////////////////////////////////////////////////////
	// Tapered 이면서 bMbarSameJ=TRUE인 경우 J단 철근을 J단 단면형태에 맞게 수정(CCMSectionManagerRebarLongiDlg::SetDlg2Data 참고)
	if(RpscSSMD.bMbarSameJ)
	{
		T_SECT_K SectOrgKey = Key;
		T_SECT_D SectD;
		GetSect(SectOrgKey, SectD);
		T_RPSC_SSM_D RpscSSMData; RpscSSMData.Initialize();
		if(!CSectUtil::CalcTaperedSectRebar(SectD, SectD, 0, RpscSSMD, RpscSSMData))
		{
			// 원래 저장된 값 사용
			//RpscSSMD.Mbar[1].Copy(m_pRpscSSMD->Mbar[0]);
		}
		else
		{
			RpscSSMD.Mbar[1].Copy(RpscSSMData.Mbar[1]);
		}
	}
	//////////////////////////////////////////////////////////////////////////

	if(!m_pDoc->m_pAttrCtrl2->ConvertRpscSSMtoRpsc(Key, RpscSSMD, rData)) bReturn = FALSE;
	return bReturn;
#else
	BOOL bReturn=m_pDataMemb->m_rpsc.GetDesign(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitRpscOut(rData);
	return bReturn;
#endif
}

// T_RPSC_K Key =  T_SECT_K OrgSectK : 원래 단면 key를 입력받도록 개발됨.
BOOL CAttrCtrl::GetRpsdByConsiderRbar(BOOL bMbar,T_RPSC_K Key,T_RPSC_D& rData)
{
#if defined(_CIVIL)
	// Add by ZINU.('05.09.21). Check bMbar Option.
	if(!bMbar)	return GetRpsd(Key,rData);	// If Sbar, GetRpsc().

	// Add by ZINU.('05.03.29). Check Consider Rbar Option.
	BOOL bReturn = GetRpsd(Key,rData);

	T_ACTL_D ActlD;
	if(!GetActl(ActlD))	ActlD.Initialize();
	BOOL bConsiderRbar = ActlD.bConsiderRbar;

	// Add by ZINU.('05.09.05). Separate PSC Design from Others.
	// 6=PSC-Design/Strn, 7=Always Consider.
	if(m_pDoc->GetDesignStatus()==6)
	{
		// Add by ZINU.('06.08.02). NO:2365, Always bConsiderRbar=TRUE, if JTG D62-04.
		// Requested by Kye BJ.
		T_PSCD_D PscdD;
		if(!GetDgnPscd(PscdD)) PscdD.Initialize();
		if(PscdD.iDgnCode==JTG_D62_04)	bConsiderRbar = TRUE;
		else							bConsiderRbar = CDBLib::IsConsiderRbarForDgn();
	}
	else if(m_pDoc->GetDesignStatus()==7)	bConsiderRbar = TRUE;

	if(!bConsiderRbar)
	{
		rData.Mbar[0].RemoveAll();
		rData.Mbar[1].RemoveAll();
	}
	return bReturn;
#else
	// Add by ZINU.('05.09.21). Check bMbar Option.
	if(!bMbar)	return GetRpsd(Key,rData);	// If Sbar, GetRpsc().

	// Add by ZINU.('05.03.29). Check Consider Rbar Option.
	BOOL bReturn=m_pDataMemb->m_rpsc.GetDesign(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitRpscOut(rData);

	T_ACTL_D ActlD;
	if(!GetActl(ActlD))	ActlD.Initialize();
	BOOL bConsiderRbar = ActlD.bConsiderRbar;

	// Add by ZINU.('05.09.05). Separate PSC Design from Others.
	// 6=PSC-Design/Strn, 7=Always Consider.
	if(m_pDoc->GetDesignStatus()==6)
	{
		// Add by ZINU.('06.08.02). NO:2365, Always bConsiderRbar=TRUE, if JTG D62-04.
		// Requested by Kye BJ.
		T_PSCD_D PscdD;
		if(!GetDgnPscd(PscdD)) PscdD.Initialize();
		if(PscdD.iDgnCode==JTG_D62_04)	bConsiderRbar = TRUE;
		else														bConsiderRbar = CDBLib::IsConsiderRbarForDgn();
	}
	else if(m_pDoc->GetDesignStatus()==7)	bConsiderRbar = TRUE;

	if(!bConsiderRbar)
	{
		rData.Mbar[0].RemoveAll();
		rData.Mbar[1].RemoveAll();
	}
	return bReturn;
#endif
}

