void CAttrCtrl::GetThikList(CArray<CString, CString&>& rstrThikList)
{
	rstrThikList.RemoveAll();

	T_THIK_D Data;
	CString strName;
	CArray<T_THIK_K, T_THIK_K>KeyList;
	GetThikKeyList(KeyList);
	int nCount=KeyList.GetSize();
	double dThickness;
	for(int i=0; i<nCount; i++)
	{
		if (GetThik(KeyList[i], Data))
		{
			if (Data.nType == 2) 
			{
				strName.Format(_T("%.4f(%.4f)"),Data.StlWall.ThickCon, Data.StlWall.ThickSteel);
				rstrThikList.Add(strName);
				continue;
			}
		}
		//if(GetThik(KeyList[i], Data))
		if(GetThikForThikName(KeyList[i], dThickness))
		{
			//if(Data.nThickType == 0)
			//{
			strName.Format(_T("%.4f"),dThickness);
			//}
			//else
			//{
			//  strName.Format(_T("%.4f(%.4f)"),Data.ThickIn,Data.ThickOut);
			//}
			rstrThikList.Add(strName);
		}
		else
			ASSERT(FALSE);
	}
}

