{
	return m_pDataMemb->m_thik.m_nLastNum;
}

T_THIK_K CAttrCtrl::GetStartNumThik()
{
	return m_pDataMemb->m_thik.m_nStartNum;
}

T_THIK_K CAttrCtrl::GetNextNumThik(T_THIK_K StartNum)
{
	if(StartNum > GetLastNumThik())return StartNum;
	T_THIK_K Key=StartNum;
	T_THIK_D Data;
	while(TRUE)
	{
		Key++;
		if(!m_pDataMemb->m_thik.Get(Key,Data))
		{
			if(Key < D_THIK_MINNUM || Key > D_THIK_MAXNUM)
				return GetStartNumThik();
			else
				return Key;
		}
	}
}

T_THIK_K CAttrCtrl::GetLastNumThikUnused()
{
	T_THIK_K KeyLast=m_pDataMemb->m_thik.m_nLastNum;
	while(TRUE)
	{
		if(!IsUsedThik(KeyLast) && !ExistThik(KeyLast))
		{
			if(KeyLast < D_THIK_MINNUM || KeyLast > D_THIK_MAXNUM)
				return GetStartNumThikUnused();
			else
				return KeyLast;
		}
		KeyLast++;
	}
}

T_THIK_K CAttrCtrl::GetStartNumThikUnused()
{
	T_THIK_K KeyStart=m_pDataMemb->m_thik.m_nStartNum;
	while(TRUE)
	{
		if(!IsUsedThik(KeyStart) && !ExistThik(KeyStart))return KeyStart;
		KeyStart++;
	}
}

T_THIK_K CAttrCtrl::GetNextNumThikUnused(T_THIK_K StartNum)
{
	if(StartNum > GetLastNumThikUnused())return StartNum;
	T_THIK_K KeyNext=StartNum+1;
	while(TRUE)
	{
		if(!IsUsedThik(KeyNext) && !ExistThik(KeyNext))return KeyNext;
		KeyNext++;
	}
}

void CAttrCtrl::GetKeyListThikUser(CArray<T_THIK_K, T_THIK_K>* pKeyThik,
								   CArray<T_NODE_K, T_NODE_K>* pKeyNode, CArray<T_ELEM_K, T_ELEM_K>* pKeyElem)
{
	if(pKeyNode != NULL)pKeyNode->RemoveAll();
	if(pKeyElem != NULL)pKeyElem->RemoveAll();
	if(pKeyNode == NULL && pKeyElem == NULL)return;
	int nCount=pKeyThik->GetSize();
	if(nCount == 0)return;

	CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K>KeyElemMap;
	KeyElemMap.InitHashTable(m_pDoc->GetHashSizeElem());

	POSITION pos;
	T_ELEM_K KeyElem;
	T_ELEM_D DataElem;

	pos=GetStartElem();
	while(pos != NULL)
	{
		GetNextElem(pos, KeyElem, DataElem);
		if(IsPlaneType(DataElem.eltyp))
		{
			for(int i=0; i<nCount; i++)
				if(DataElem.elpro == pKeyThik->GetAt(i))KeyElemMap.SetAt(KeyElem, KeyElem);
		}
	}

	GetKeyListNodeElem(KeyElemMap, pKeyNode, pKeyElem);
}

void CAttrCtrl::GetThikKeyListUsedInElem(CArray<T_THIK_K, T_THIK_K>& rKeyList)
{
	T_THIK_K KeyThik;
	int nNum;
	rKeyList.RemoveAll();
	POSITION pos=m_pDataMemb->m_elem.GetStartThikCount();
	while(pos != NULL)
	{
		m_pDataMemb->m_elem.GetNextThikCount(pos, KeyThik, nNum);
		rKeyList.Add(KeyThik);
	}
	if(rKeyList.GetSize() != 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
#ifdef _DEBUG
	CArray<T_THIK_K, T_THIK_K> rKeyList2;
	rKeyList2.RemoveAll();
	CMap<T_THIK_K, T_THIK_K, T_THIK_K, T_THIK_K>mapThik;
	mapThik.InitHashTable(HASHSIZETHIK);

	T_ELEM_K Key;
	T_ELEM_D Data;
	pos=GetStartElem();
	while(pos != NULL)
	{
		GetNextElem(pos, Key, Data);
		if(IsNeedThik(Data.eltyp))mapThik.SetAt(Data.elpro, Data.elpro);
	}
	pos=mapThik.GetStartPosition();
	while(pos != NULL)
	{
		mapThik.GetNextAssoc(pos, KeyThik, KeyThik);
		rKeyList2.Add(KeyThik);
	}
	if(rKeyList2.GetSize() != 0)CQSort::QSortUInt(rKeyList2.GetData(), rKeyList2.GetSize());
	if (rKeyList2.GetSize() != rKeyList.GetSize()) 
		GSaveHistoryFormatNF(_LS(IDS_DBLIB__ADDED__Thik_Different_in_Size_));
	else
	{
		int i = 0;
		for (i = 0; i < rKeyList2.GetSize(); i++)
			if (rKeyList2[i] != rKeyList[i]) break;
		if (i != rKeyList2.GetSize()) 
			GSaveHistoryFormatNF(_LS(IDS_DBLIB__ADDED__Thik_Different_in_member_));
	}
#endif
}

// Outofplane 두께를
BOOL CAttrCtrl::GetThikForDataConversion(T_THIK_D& DataThik, double& dThickness)
{
	dThickness=0.;
	if(DataThik.nType == 0)
	{
		if(DataThik.Value.nThickType == 0)
			dThickness=DataThik.Value.ThickIn;
		else if(DataThik.Value.nThickType == 1)
			dThickness=DataThik.Value.ThickOut;
	}
	else if(DataThik.nType == 1)
	{
		dThickness=__max(DataThik.Stiffened.xzValue.ThickOut, DataThik.Stiffened.xzValue.ThickOut);
	}
	else
	{
		ASSERT(FALSE);
		return FALSE;
	}
	return TRUE;
}

BOOL CAttrCtrl::GetThikForDataConversion(T_THIK_K KeyThik, double& dThickness)
{
	T_THIK_D DataThik;
	if(!GetThik(KeyThik, DataThik))
	{
		dThickness=0.;
		return FALSE;
	}
	return GetThikForDataConversion(DataThik, dThickness);
}

