// Inplane두께를 0.이면 Outofplane두께를
BOOL CAttrCtrl::GetThikForWeightAndMass(T_THIK_D& DataThik, double& dThickness)
{
	dThickness=0.;
	if(DataThik.nType == 0)
	{
		if(DataThik.Value.nThickType == 0)
			dThickness=DataThik.Value.ThickIn;
		else if(DataThik.Value.nThickType == 1)
		{
			dThickness=DataThik.Value.ThickIn;
			if(dThickness == 0.)dThickness=DataThik.Value.ThickOut;
		}
	}
	else if(DataThik.nType == 1)
	{
		dThickness=DataThik.Stiffened.dWeightThik;
	}
	else if(DataThik.nType == 2)
	{
		dThickness = (DataThik.StlWall.ThickSteel) + (DataThik.StlWall.ThickCon - DataThik.StlWall.ThickSteel)*25./76.98;
	}
	else
	{
		ASSERT(FALSE);
		return FALSE;
	}
	return TRUE;
}

