void CAttrCtrl::GetStorData(CArray<T_STOR_D, T_STOR_D&>& rStorList)
{
	rStorList.RemoveAll();

	T_STOR_D Data;
	CArray<T_STOR_K, T_STOR_K>KeyList;
	GetStorKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetStor(KeyList[i], Data))
			rStorList.Add(Data);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetStorKeyByElemKey(T_STOR_K& StorK,const T_ELEM_K ElemK, CStoryData* pStoryData/*=NULL*/)
{
	if(CTempDataStore_GetAttrStorKeyByElemKey::GetInstance()->Get(ElemK, StorK))
		return;

	CArray<T_STOR_K,T_STOR_K> rStorKeyList;
	GetStorKeyList(rStorKeyList);

	if (rStorKeyList.GetSize() > 0)
	{
		if(pStoryData == NULL)
			pStoryData = CDBDoc::GetDocPoint()->GetStoryData();

		CDBDoc* pDoc = CDBDoc::GetDocPoint();

		for(int i =0; i<rStorKeyList.GetSize(); i++)
		{
			CArray<T_STOR_K,T_STOR_K> aTgtKey;
			CArray<T_ELEM_K,T_ELEM_K> aKey;

			aTgtKey.Add(rStorKeyList[i]);
			pStoryData->GetMultiStoryElemKey(aTgtKey, aKey);

			for(int j=0; j < aKey.GetSize(); j++)
			{
				if(ElemK == aKey[j]) 
				{
					StorK = rStorKeyList[i];
					CTempDataStore_GetAttrStorKeyByElemKey::GetInstance()->Set(ElemK, StorK);
					return;
				}
			}

		}
	}
}

