CString CAttrCtrl::GetStorNameWithoutModuleName(LPCTSTR lpszName)
{
	CString strName = lpszName;
	int index = strName.ReverseFind(':');
	return strName.Right(strName.GetLength()-(index+1));
}

int CAttrCtrl::GetModuleIndexOfStor(const T_STOR_K StorK, CString& rstrModuleName)
{
	int iModl = 0;
	CString strName = GetModlBaseName();
	BOOL bFound = FALSE;

	T_MODL_D ModlD;
	if (m_pDataMemb->m_modl.Get(ModlD))
	{
		for (int i = 0; i<ModlD.aModule.GetSize(); ++i)
		{
			for (int k=0; k<ModlD.aModule[i].aStoryK.GetSize(); ++k)
			{
				if (StorK == ModlD.aModule[i].aStoryK[k])  { bFound = TRUE;  break; }
			}

			if (bFound) { iModl = i;  strName = ModlD.aModule[i].csModuleName;  break; }
		}
	}

	ASSERT(!strName.IsEmpty());
	rstrModuleName = strName;

	return iModl;
}

CString CAttrCtrl::GetModuleNameOfStor(const T_STOR_K StorK)
{
	CString strModuleName;
	GetModuleIndexOfStor(StorK, strModuleName);

	return strModuleName;
}

CString CAttrCtrl::GetStorNameWithModuleName(T_STOR_K StorK)
{
	CString strName = GetModuleNameOfStor(StorK);

	T_STOR_D StorD;
	if (!m_pDataMemb->m_stor.Get(StorK, StorD))  StorD.Initialize();

	if (!strName.IsEmpty())  strName += _T(":");    // if have module name
	//strName += GetStorNameWithoutModuleName(StorD.StoryName);
	//CString strStorName = GetStorNameWithoutModuleName(StorD.StoryName);
	CString strNameWithmodule;
	strNameWithmodule.Format(_T("%s%s"), strName, StorD.StoryName);

	//return strName;
	return strNameWithmodule;
}

BOOL CAttrCtrl::GetStor(CString& rStoryName, T_STOR_D& rData)
{
	T_STOR_K key;
	T_STOR_D data;
	CString strStoryName=rStoryName;
	strStoryName.TrimRight();

	strStoryName = GetStorNameWithoutModuleName(strStoryName);

	POSITION pos=m_pDataMemb->m_stor.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_stor.GetNext(pos,key,data);
		data.StoryName = GetStorNameWithoutModuleName(data.StoryName);
		if(strStoryName.CompareNoCase(data.StoryName) == 0)
		{
			m_pUnitCtrl->ConvertUnitStorOut(data);
			data.StoryName = GetStorNameWithModuleName(key);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetStor(T_STOR_K Key,T_STOR_D& rData, BOOL bStorNameWithModule/*=TRUE*/)
{
	BOOL bReturn=m_pDataMemb->m_stor.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitStorOut(rData);
	if(bReturn && bStorNameWithModule)
	{
		T_MODL_D ModlD;
		if (m_pDataMemb->m_modl.Get(ModlD))
		{
			if (ModlD.aModule.GetSize()>0)  rData.StoryName = GetStorNameWithModuleName(Key);
		}
	}
	return bReturn;
}

T_STOR_K CAttrCtrl::GetStorKey(CString& rStoryName)
{
	T_STOR_K key=0;
	T_STOR_D data;

	CString strStoryName; strStoryName.Empty();
	POSITION pos=GetStartStor();
	while(pos != NULL)
	{
		GetNextStor(pos,key,data);

		if(rStoryName.CompareNoCase(data.StoryName) == 0) return key;
	}

	// [MQC 10299] 층 이름으로 못 찾으면 탑이름 추가해서 검색
	pos=GetStartStor();
	while(pos != NULL)
	{
		GetNextStor(pos,key,data);
		strStoryName = GetStorNameWithModuleName(key);

		if(rStoryName.CompareNoCase(strStoryName) == 0) return key;
	}

	key=0;
	return key;
}

T_STOR_K CAttrCtrl::GetStorKey(CString& rStoryName, CString& rModuleName)
{
	T_MODL_D ModlD;
	T_MDUL_D MdulD;
	if (!GetModl(ModlD)) return GetStorKey(rStoryName);

	for (int i=0; i<ModlD.aModule.GetSize(); i++)
	{
		const T_MODL_BASE& rModule = ModlD.aModule[i];
		if (rModule.csModuleName != rModuleName) continue;;
		for (int j=0; j<rModule.aStoryK.GetSize(); j++)
		{
			T_STOR_D StorD;
			if (!GetStor(rModule.aStoryK[j], StorD)) { ASSERT(0); continue; }
			if (GetStorNameWithoutModuleName(StorD.StoryName) == rStoryName) return rModule.aStoryK[j];
		}
	}

	ASSERT(0);
	return 0;
}
