T_STOR_K CAttrCtrl::GetLastNumStor()
{
	return m_pDataMemb->m_stor.m_nLastNum;
}

T_STOR_K CAttrCtrl::GetStartNumStor()
{
	return m_pDataMemb->m_stor.m_nStartNum;
}

T_STOR_K CAttrCtrl::GetNextNumStor(T_STOR_K StartNum)
{
	if(StartNum > GetLastNumStor())return StartNum;
	T_STOR_K Key=StartNum;
	T_STOR_D Data;
	while(TRUE)
	{
		Key++;
		if(!m_pDataMemb->m_stor.Get(Key,Data))
		{
			if(Key < D_STOR_MINNUM || Key > D_STOR_MAXNUM)
				return GetStartNumStor();
			else
				return Key;
		}
	}
}

BOOL CAttrCtrl::IsStorHaveArea(const T_STOR_D& StorD) const
{
	if (StorD.aStoryArea.GetSize() > 0)  return TRUE;

	return FALSE;
}

BOOL CAttrCtrl::GetStorArea(const T_STOR_D& StorD, int nVertex, double (*dPolyLine)[2])
{
	// 영역이 없으면 무조건 최대 사각형으로 영역 생성
	if (StorD.aStoryArea.GetSize() == 0)  
	{
		if (nVertex != 4)  { ASSERT(0);  return FALSE; }

		//dPolyLine = new double[nVertex][2];   ASSERT(dPolyLine);    // 외부에서 생성해서 들어와, 여기서는 값만 채우자.
		double dMax = 1.0e12;
		dPolyLine[0][0] =  dMax;      dPolyLine[0][1] =  dMax;
		dPolyLine[1][0] = -dMax;      dPolyLine[1][1] =  dMax;
		dPolyLine[2][0] = -dMax;      dPolyLine[2][1] = -dMax;
		dPolyLine[3][0] =  dMax;      dPolyLine[3][1] = -dMax;
	}
	else
	{
		//pdPolyLine = new double[nVertex][2];   ASSERT(pdPolyLine);    // 외부에서 생성해서 들어와, 여기서는 값만 채우자.

		for(int i=0; i<nVertex; ++i)
		{
			dPolyLine[i][0] = StorD.aStoryArea[i].dX;
			dPolyLine[i][1] = StorD.aStoryArea[i].dY;
		}
	}

	return TRUE;
}

BOOL CAttrCtrl::IsStorOverlapArea(T_STOR_K StorK_src, const T_STOR_D& StorD_tgt)
{
	T_STOR_D StorD_src;
	if (!GetStor(StorK_src, StorD_src))  { ASSERT(0);  return FALSE; }

	// 층 영역이 겹치나?
	int nVertex = StorD_src.aStoryArea.GetSize();
	double (*dPolyLine)[2] = NULL;		
	if (nVertex > 0)     { dPolyLine = new double[nVertex][2];   ASSERT(dPolyLine); }
	else   { nVertex = 4;  dPolyLine = new double[nVertex][2];   ASSERT(dPolyLine); }   // 영역이 없으면 무조건 최대 영역으로 영역 생성

	if (!GetStorArea(StorD_src, nVertex, dPolyLine))  { ASSERT(0);  return FALSE; }

	BOOL bisOverlap = IsStorOverlapArea(StorD_tgt, nVertex, dPolyLine);
	delete [] dPolyLine;

	return bisOverlap;
}

BOOL CAttrCtrl::IsStorOverlapArea(const T_STOR_D& StorD_src, int nVertex_tgt, double (*dPolyLine_tgt)[2])
{
	// 층 영역이 겹치나?
	int nVertex = StorD_src.aStoryArea.GetSize();
	double (*dPolyLine)[2] = NULL;		
	if (nVertex > 0)     { dPolyLine = new double[nVertex][2];   ASSERT(dPolyLine); }
	else   { nVertex = 4;  dPolyLine = new double[nVertex][2];   ASSERT(dPolyLine); }   // 영역이 없으면 무조건 최대 영역으로 영역 생성

	if (!GetStorArea(StorD_src, nVertex, dPolyLine))  { ASSERT(0);  return FALSE; }
	BOOL bisOverlap = CMathFunc::mathIsOverlapPolygon2D(nVertex, dPolyLine, nVertex_tgt, dPolyLine_tgt);

	delete [] dPolyLine;

	return bisOverlap;
}

