// nSelectionType == 0   // 해당층과 층하부로 연결된 NLNK
//                == 1   // 해당층과 층상부로 연결된 NLNK
//                == 2   // 해당층과 층상부와 층하부로 연결된 모든 NLNK
//                == 3   // 해당층과 층하부의 모든 NLNK
//                == 4   // 해당층과 층상부의 모든 NLNK
//                == 5   // 해당층만
void CAttrCtrl::GetKeyListStorUserNlnk(T_STOR_K KeyStorUser, int nSelectionType, CArray<T_NLNK_K, T_NLNK_K>* pKeyNlnk)
{
	// 초기화
	if(pKeyNlnk != NULL)pKeyNlnk->RemoveAll();
	if(pKeyNlnk == NULL)return;

	// 층정보
	CArray<T_STOR_K, T_STOR_K> KeyListStor;
	GetStorKeyList(KeyListStor);
	if(KeyListStor.GetSize() == 0)return;

	// 층 인덱스
	int nStorIndex=-1;
	for(int i=0; i<KeyListStor.GetSize(); i++)
	{
		if(KeyListStor[i] == KeyStorUser)
		{
			nStorIndex=i;
			break;
		}
	}
	if(nStorIndex == -1)return;

	CArray<T_STOR_D, T_STOR_D&> DataListStor;
	GetStorData(DataListStor);

	double dTol=0.;
	for(int iq=1; iq<DataListStor.GetSize(); iq++)
		dTol=__max(dTol, fabs(DataListStor[iq].dStoryLevel-DataListStor[iq-1].dStoryLevel)*1.e-6);

	CMap<T_NODE_K, T_NODE_K, T_STOR_K, T_STOR_K>KeyNodeMap;
	KeyNodeMap.InitHashTable(m_pDoc->GetHashSizeNode());
	CMap<T_NLNK_K, T_NLNK_K, T_STOR_K, T_STOR_K>KeyNlnkMap;
	KeyNlnkMap.InitHashTable(m_pDoc->GetHashSizeElem());

	POSITION pos;
	T_NODE_K KeyNode;
	T_NODE_D DataNode;
	T_STOR_K KeyStor;
	T_STOR_D DataStor;
	T_STOR_D DataStorUser;

	double dStoryLevel=DataListStor[nStorIndex].dStoryLevel, dStoryBelow=0., dStoryAbove=0.;
	BOOL bStoryBelow=FALSE, bStoryAbove=FALSE;
	if(nStorIndex > 0)
	{
		bStoryBelow=TRUE;
		dStoryBelow=DataListStor[nStorIndex-1].dStoryLevel;
	}
	if(nStorIndex < KeyListStor.GetSize()-1)
	{
		bStoryAbove=TRUE;
		dStoryAbove=DataListStor[nStorIndex+1].dStoryLevel;
	}

	// ------------------------------------ Node : Nlnk 구하기 위해 계산 필요
	pos=GetStartNode();
	while(pos != NULL)
	{
		GetNextNode(pos, KeyNode, DataNode);
		// nSelectionType == 0   // 해당층과 층하부로 연결된 절점, 요소
		//                == 1   // 해당층과 층상부로 연결된 절점, 요소
		//                == 2   // 해당층과 층상부와 층하부로 연결된 모든 절점, 요소
		//                == 3   // 해당층과 층하부의 모든 절점, 요소
		//                == 4   // 해당층과 층상부의 모든 절점, 요소
		//                == 5   // 해당층만
		if(nSelectionType == 0)
		{
			if(DataNode.z > dStoryLevel+dTol)continue;
			if(bStoryBelow && DataNode.z < dStoryBelow+dTol)continue;
		}
		else if(nSelectionType == 1)
		{
			if(DataNode.z < dStoryLevel-dTol)continue;
			if(bStoryAbove && DataNode.z > dStoryAbove-dTol)continue;
		}
		else if(nSelectionType == 2)
		{
			if(bStoryBelow && DataNode.z < dStoryBelow+dTol)continue;
			if(bStoryAbove && DataNode.z > dStoryAbove-dTol)continue;
		}
		else if(nSelectionType == 3)
		{
			if(DataNode.z > dStoryLevel+dTol)continue;
		}
		else if(nSelectionType == 4)
		{
			if(DataNode.z < dStoryLevel-dTol)continue;
		}
		else if(nSelectionType == 5)
		{
			if(DataNode.z < dStoryLevel-dTol)continue;
			if(DataNode.z > dStoryLevel+dTol)continue;
		}
		KeyNodeMap.SetAt(KeyNode, KeyStorUser);
	}

	/*
	int nCount=KeyNodeMap.GetCount();
	if(nCount != 0 && pKeyNode != NULL)
	{
	pKeyNode->SetSize(nCount);
	int nIndex=0;
	pos=KeyNodeMap.GetStartPosition();
	while(pos != NULL)
	{
	KeyNodeMap.GetNextAssoc(pos, KeyNode, KeyStor);
	pKeyNode->SetAt(nIndex, KeyNode);
	nIndex++;
	}
	CQSort::QSortUInt(pKeyNode->GetData(), nCount);
	}*/
	// ------------------------------------ Node End

	T_STOR_K KeyStorTemp;
	T_NLNK_K KeyNlnk;
	T_NLNK_D DataNlnk;
	GetStor(KeyStorUser, DataStorUser);
	pos=GetStartNlnk();
	while(pos != NULL)
	{
		GetNextNlnk(pos, KeyNlnk, DataNlnk);
		int nNode=2;
		int nFind=0;
		BOOL bFind=FALSE;
		for(int j=0; j<nNode; j++)
		{
			T_NODE_K CurNodeK = (j==0 ? DataNlnk.Node1 : DataNlnk.Node2);
			if(!KeyNodeMap.Lookup(CurNodeK, KeyStorTemp))continue;
			nFind++;
		}
		if(nFind > 0)
		{
			if(nFind == nNode)
			{
				bFind=TRUE;
			}
			else
			{
				int nSel=0;
				for(int j=0; j<nNode; j++)
				{
					T_NODE_K CurNodeK = (j==0 ? DataNlnk.Node1 : DataNlnk.Node2);
					if(!KeyNodeMap.Lookup(CurNodeK, KeyStorTemp))
					{
						GetNode(CurNodeK, DataNode);
						if(nSelectionType == 0 && DataNode.z > dStoryLevel+dTol)continue;
						if(nSelectionType == 1 && DataNode.z < dStoryLevel-dTol)continue;
						//if(nSelectionType == 2)
						if(nSelectionType == 3)continue;
						if(nSelectionType == 4)continue;
						if(nSelectionType == 5)continue;
					}
					nSel++;
				}
				if(nSel == nNode)bFind=TRUE;
			}
		}
		if(bFind)KeyNlnkMap.SetAt(KeyNlnk, KeyStorUser);
	}

	int nCount=KeyNlnkMap.GetCount();
	if(nCount != 0 && pKeyNlnk != NULL)
	{
		pKeyNlnk->SetSize(nCount);
		int nIndex=0;
		pos=KeyNlnkMap.GetStartPosition();
		while(pos != NULL)
		{
			KeyNlnkMap.GetNextAssoc(pos, KeyNlnk, KeyStor);
			pKeyNlnk->SetAt(nIndex, KeyNlnk);
			nIndex++;
		}
		CQSort::QSortUInt(pKeyNlnk->GetData(), nCount);
	}
}

// nSelectionType == 0   // 해당층과 층하부로 연결된 절점, 요소
//                == 1   // 해당층과 층상부로 연결된 절점, 요소
//                == 2   // 해당층과 층상부와 층하부로 연결된 모든 절점, 요소
//                == 3   // 해당층과 층하부의 모든 절점, 요소
//                == 4   // 해당층과 층상부의 모든 절점, 요소
//                == 5   // 해당층만
void CAttrCtrl::GetKeyListStorUser(T_STOR_K KeyStorUser, int nSelectionType,
								   CArray<T_NODE_K, T_NODE_K>* pKeyNode, CArray<T_ELEM_K, T_ELEM_K>* pKeyElem, CLinkedKeyMgr* pLinkedKeyMgr_stor/*=NULL*/)
{
	ASSERT(KeyStorUser);

	// 초기화
	if(pKeyNode != NULL)pKeyNode->RemoveAll();
	if(pKeyElem != NULL)pKeyElem->RemoveAll();
	if(pKeyNode == NULL && pKeyElem == NULL)return;

	// 층정보
	if(GetCountStor() == 0) return;

	// 상/하층 연결정보 구성
	BOOL bDeleteLinkMgr=FALSE;
	if(!pLinkedKeyMgr_stor) 
	{
		bDeleteLinkMgr=TRUE;
		pLinkedKeyMgr_stor = new CLinkedKeyMgr;
		GetStorLinkedData(*pLinkedKeyMgr_stor, NULL);
	}

	// 층별 level 정보를 저장
	CArray<T_STOR_K,T_STOR_K> aStorK_tot;   aStorK_tot.RemoveAll();
	pLinkedKeyMgr_stor->GetKeyListAll(aStorK_tot);
	if (aStorK_tot.GetSize() == 0)  { /*ASSERT(0);*/  return; }

	CMap<T_STOR_K,T_STOR_K, double,double> mStor2Level;   mStor2Level.RemoveAll();
	GetStorLevel(aStorK_tot, mStor2Level);
	SortStorKeyListByLevel(aStorK_tot);

	CMap<T_NODE_K, T_NODE_K, T_STOR_K, T_STOR_K>KeyNodeMap;
	KeyNodeMap.InitHashTable(m_pDoc->GetHashSizeNode());
	CMap<T_ELEM_K, T_ELEM_K, T_STOR_K, T_STOR_K>KeyElemMap;
	KeyElemMap.InitHashTable(m_pDoc->GetHashSizeElem());

	T_NODE_K KeyNode;
	T_NODE_D DataNode;
	T_STOR_K KeyStor;
	T_STOR_D DataStor;
	T_STOR_D DataStorUser;

	// 허용오차 
	double dTol = M_InitValueCurUnit(0.0001, KN, M, D_UNITSYS_BASE_LENGTH);   // 0.1mm
	//double dTol = m_pDoc->m_pFlagCtrl->GetGeneralCoordinateToleranceCurrentUnit();

	double dStoryLevel = 0.0;
	T_STOR_K StorK_cur = KeyStorUser;
	if (!mStor2Level.Lookup(StorK_cur, dStoryLevel))  { /*ASSERT(0);*/  return; }

	// 층이 속한 Module 정보 세팅
	T_MODL_D ModlD;
	if (!GetModlWithBase(ModlD))  ModlD.Initialize();

	CMapEx<T_STOR_K,T_STOR_K, int,int> mStorK2IndexModl;  mStorK2IndexModl.RemoveAll();  mStorK2IndexModl.InitHashTable(HASHSIZESTOR);
	for (int i=0; i<ModlD.aModule.GetSize(); ++i)
	{
		CArray<T_STOR_K, T_STOR_K>& aStorK_iter = ModlD.aModule[i].aStoryK;
		for (int k=0; k<aStorK_iter.GetSize(); ++k) 
		{ 
			mStorK2IndexModl.SetAt(aStorK_iter[k], i); 
		}
	}

	// 현재 층
	T_STOR_D StorD_cur;
	if (!GetStor(StorK_cur, StorD_cur, FALSE))  { /*ASSERT(0);*/  return; }

	// 위 층  
	T_STOR_D StorD_upper;
	CArray<UINT,UINT> aStorK_upper;
	pLinkedKeyMgr_stor->GetNextKeyList(StorK_cur, aStorK_upper);

	BOOL bExistUpper=FALSE;
	double dLevel_upper = 0.0;
	if(aStorK_upper.GetSize() > 0 )
	{
		int nCurStoryMdul=0;
		mStorK2IndexModl.Lookup(StorK_cur, nCurStoryMdul);

		for (int k=0; k<aStorK_upper.GetSize(); k++)
		{
			int nUpperStoryMdul=0;
			mStorK2IndexModl.Lookup(aStorK_upper[k], nUpperStoryMdul);
			if(nCurStoryMdul!=nUpperStoryMdul) continue;

			bExistUpper = TRUE;
			dLevel_upper = GetStorLevel(aStorK_upper[k]);
			break;
		}
	}

	// 아래 층  
	T_STOR_D StorD_lower;
	CArray<UINT,UINT> aStorK_lower;
	pLinkedKeyMgr_stor->GetPrevKeyList(StorK_cur, aStorK_lower);

	BOOL bExistLower=FALSE;
	double dLevel_lower = 0.0;
	if(aStorK_lower.GetSize() > 0)
	{
		int nCurStoryMdul=0;
		mStorK2IndexModl.Lookup(StorK_cur, nCurStoryMdul);

		for (int k=0; k<aStorK_lower.GetSize(); k++)
		{
			int nLowerStoryMdul=0;
			mStorK2IndexModl.Lookup(aStorK_lower[k], nLowerStoryMdul);
			if(nCurStoryMdul!=nLowerStoryMdul) continue;

			bExistLower = TRUE;
			dLevel_lower = GetStorLevel(aStorK_lower[k]);
			break;
		}
	}
	//-----------------------------------------------------------
	// 다른 모듈에 동일 Level의 층이 있다면 제외 영역으로 고려
	CArray<T_STOR_K,T_STOR_K> aStorK;   aStorK.RemoveAll();
	GetStorKeyList(aStorK);

	double dLevel_curr = dStoryLevel;
	double dLevel_comp = 0;
	CArray<T_STOR_K,T_STOR_K> aStorK_sameLevel;   aStorK_sameLevel.RemoveAll();
	for (int i=0; i<aStorK.GetSize(); ++i)
	{
		if (aStorK[i] == StorK_cur)  continue;

		dLevel_comp = GetStorLevel(aStorK[i]);

		// 레벨이 같은 층
		if(fabs(dLevel_comp-dLevel_curr) < dTol)  
		{ 
			aStorK_sameLevel.Add(aStorK[i]);  continue; 
		}
		// '현재층'과 '같은 모듈의 위층 사이에 있는 층'은 위층으로 추가한다. 
		else if(bExistUpper && (dLevel_curr <= dLevel_comp + dTol) && (dLevel_upper >= dLevel_comp + dTol))
		{
			aStorK_upper.Add(aStorK[i]);  continue; 
		}
		// '현재층'과 '같은 모듈의 아래층 사이에 있는 층'은 아래층 추가한다. 
		else if(bExistLower && (dLevel_curr <= dLevel_comp + dTol) && (dLevel_lower >= dLevel_comp + dTol))
		{
			aStorK_lower.Add(aStorK[i]);  continue; 
		}
	}
	CArrayUtil::RemoveDup(aStorK_upper);
	CArrayUtil::RemoveDup(aStorK_lower);

	CArray<T_STOR_D,T_STOR_D&> aStorD_sameLevel;   aStorD_sameLevel.RemoveAll();
	aStorD_sameLevel.SetSize(aStorK_sameLevel.GetSize());
	for (int i=0; i<aStorK_sameLevel.GetSize(); ++i)
	{
		if (!GetStor(aStorK_sameLevel[i], aStorD_sameLevel[i]))  { ASSERT(0);  return; }
	}
	//-----------------------------------------------------------

	POSITION pos=GetStartNode();
	while(pos != NULL)
	{
		GetNextNode(pos, KeyNode, DataNode);

		// 0단계 : 현재층과 영역검사
		if (StorD_cur.aStoryArea.GetSize() > 1)    // 영역 정보를 가지고 있다면 영역 검사
		{
			if (!IsInsideOfStorArea2D(DataNode.x, DataNode.y, StorD_cur))  continue;
		}
		else  // 영역 정보가 없다면 동일 Level의 영역 정보를 가진 층이 우선
		{
			BOOL bSkip = FALSE;
			for (int k=0; k<aStorD_sameLevel.GetSize(); ++k)
			{
				// 동일 레벨 다른 층 영역에 속한다면 
				if (IsInsideOfStorArea2D(DataNode.x, DataNode.y, aStorD_sameLevel[k]))  { bSkip = TRUE;  break; }
			}
			if (bSkip)  continue;
		}

		// MQC 16524 : Base층 사이에 Module이 지정된 경우의 문제
		// 해당 절점의 정확한 주인이 있다면 양보합시다. (레벨&영역 일치)
		if(ModlD.aModule.GetSize() > 1)
		{
			CArray<UINT,UINT> aStorK_Neighbor;
			if(nSelectionType==0) aStorK_Neighbor.Append(aStorK_lower);
			if(nSelectionType==1) aStorK_Neighbor.Append(aStorK_upper);
			BOOL bSkip=FALSE;
			for(int i=0; i<aStorK_Neighbor.GetSize(); i++)
			{
				double dLevel=0.0;
				if (!mStor2Level.Lookup(aStorK_Neighbor[i], dLevel))  { ASSERT(0);  return; }

				// 높이가 같나?
				if(fabs(DataNode.z-dLevel)>dTol)
					continue;

				// 영역이 일치하나?
				T_STOR_D StorD;
				GetStor(aStorK_Neighbor[i], StorD, FALSE);
				if(IsInsideOfStorArea2D(DataNode.x, DataNode.y, StorD))
					bSkip = TRUE;
			}
			if(bSkip) continue;
		}

		// nSelectionType == 0   // 해당층과 층하부로 연결된 절점, 요소
		//                == 1   // 해당층과 층상부로 연결된 절점, 요소
		//                == 2   // 해당층과 층상부와 층하부로 연결된 모든 절점, 요소
		//                == 3   // 해당층과 층하부의 모든 절점, 요소
		//                == 4   // 해당층과 층상부의 모든 절점, 요소
		//                == 5   // 해당층만
		if(nSelectionType == 0)
		{
			if(DataNode.z > dStoryLevel+dTol)continue;
			//if(bStoryBelow && DataNode.z < dStoryBelow+dTol)continue;

			BOOL bInside = TRUE;
			if(DataNode.z < dStoryLevel-dTol) bInside = FALSE; // 층 레벨이 아니면
			for (int i=0; i<aStorK_lower.GetSize(); ++i)
			{
				T_STOR_K StorK = aStorK_lower[i];

				// 1단계 : Level 검사
				double dLevel_lower = 0.0;
				if (!mStor2Level.Lookup(StorK, dLevel_lower))  { ASSERT(0);  return; }
				if (DataNode.z < dLevel_lower + dTol)  continue;   // 아래층 보다 아래에 있으면 out of bound.

				// 2단계 : 영역 검사
				GetStor(aStorK_lower[i], StorD_lower, FALSE);
				if (IsInsideOfStorArea2D(DataNode.x, DataNode.y, StorD_lower))  { bInside = TRUE;  break; }
			}
			if (!bInside)  continue;
		}
		else if(nSelectionType == 1)
		{
			if(DataNode.z < dStoryLevel-dTol)continue;
			//if(bStoryAbove && DataNode.z > dStoryAbove-dTol)continue;

			BOOL bInside = TRUE;
			if(DataNode.z > dStoryLevel+dTol) bInside = FALSE; // 층 레벨이 아니면
			for (int i=0; i<aStorK_upper.GetSize(); ++i)
			{
				T_STOR_K StorK = aStorK_upper[i];

				// 1단계 : Level 검사
				double dLevel_upper = 0.0;
				if (!mStor2Level.Lookup(StorK, dLevel_upper))  { ASSERT(0);  return; }
				if (DataNode.z > dLevel_upper - dTol)  continue;   // 위층 보다 위에 있으면 out of bound.

				// 2단계 : 영역 검사
				GetStor(aStorK_upper[i], StorD_upper, FALSE);
				if (IsInsideOfStorArea2D(DataNode.x, DataNode.y, StorD_upper))  { bInside = TRUE;  break; }
			}
			if (!bInside)  continue;
		}
		else if(nSelectionType == 2)
		{
			//if(bStoryBelow && DataNode.z < dStoryBelow+dTol)continue;
			//if(bStoryAbove && DataNode.z > dStoryAbove-dTol)continue;

			BOOL bInside = FALSE;
			if(DataNode.z > dStoryLevel-dTol && 
				DataNode.z < dStoryLevel+dTol )
				bInside = TRUE; // 층 레벨이면

			// 아래층들 보다 위에 있나?
			BOOL bUpper = FALSE; 
			{
				for (int i=0; i<aStorK_lower.GetSize(); ++i)
				{
					T_STOR_K StorK = aStorK_lower[i];

					// 1단계 : Level 검사
					double dLevel_lower = 0.0;
					if (!mStor2Level.Lookup(StorK, dLevel_lower))  { ASSERT(0);  return; }
					if (DataNode.z < dLevel_lower + dTol)  continue;   // 아래층 보다 아래에 있으면 out of bound.

					// 2단계 : 영역 검사
					GetStor(aStorK_lower[i], StorD_lower, FALSE);
					if (IsInsideOfStorArea2D(DataNode.x, DataNode.y, StorD_lower))  { bUpper = TRUE;  break; }
				}
				if (bInside) bUpper = TRUE;
				if (!bUpper)  continue;
			}

			// 위층들 보다 아래에 있나?
			BOOL bLower = FALSE;
			{
				for (int i=0; i<aStorK_upper.GetSize(); ++i)
				{
					T_STOR_K StorK = aStorK_upper[i];

					// 1단계 : Level 검사
					double dLevel_upper = 0.0;
					if (!mStor2Level.Lookup(StorK, dLevel_upper))  { ASSERT(0);  return; }
					if (DataNode.z > dLevel_upper - dTol)  continue;   // 위층 보다 위에 있으면 out of bound.

					// 2단계 : 영역 검사
					GetStor(aStorK_upper[i], StorD_upper, FALSE);
					if (IsInsideOfStorArea2D(DataNode.x, DataNode.y, StorD_upper))  { bLower = TRUE;  break; }
				}
				if (bInside) bLower = TRUE;
				if (!bLower)  continue;
			}
		}
		else if(nSelectionType == 3)
		{
			if(DataNode.z > dStoryLevel+dTol)continue;
			//ASSERT(0);    // 다탑 고려 안되어 있음.
		}
		else if(nSelectionType == 4)
		{
			if(DataNode.z < dStoryLevel-dTol)continue;
			//ASSERT(0);    // 다탑 고려 안되어 있음.
		}
		else if(nSelectionType == 5)
		{
			if(DataNode.z < dStoryLevel-dTol)continue;
			if(DataNode.z > dStoryLevel+dTol)continue;
		}
		KeyNodeMap.SetAt(KeyNode, KeyStorUser);
	}

	int nCount=KeyNodeMap.GetCount();
	if(nCount != 0 && pKeyNode != NULL)
	{
		pKeyNode->SetSize(nCount);
		int nIndex=0;
		pos=KeyNodeMap.GetStartPosition();
		while(pos != NULL)
		{
			KeyNodeMap.GetNextAssoc(pos, KeyNode, KeyStor);
			pKeyNode->SetAt(nIndex, KeyNode);
			nIndex++;
		}
		CQSort::QSortUInt(pKeyNode->GetData(), nCount);
	}

	T_STOR_K KeyStorTemp;
	T_ELEM_K KeyElem;
	T_ELEM_D DataElem;
	GetStor(KeyStorUser, DataStorUser);
	pos=GetStartElem();
	while(pos != NULL)
	{
		GetNextElem(pos, KeyElem, DataElem);
		int nNode=GetNumNode(DataElem.eltyp, DataElem.elnod);
		if(nNode == 0)break;
		int nFind=0;
		BOOL bFind=FALSE;
		for(int j=0; j<nNode; j++)
		{
			if(!KeyNodeMap.Lookup(DataElem.elnod[j], KeyStorTemp))continue;
			nFind++;
		}
		if(nFind > 0)
		{
			if(nFind == nNode)
			{
				bFind=TRUE;
			}
			else
			{
				int nSel=0;
				for(int j=0; j<nNode; j++)
				{
					if(!KeyNodeMap.Lookup(DataElem.elnod[j], KeyStorTemp))
					{
						GetNode(DataElem.elnod[j], DataNode);

						// MQC 4829-37. 2014-07-22. by hsshim. 층영역에 없는 절점을 물고 있는 요소는 제외.
						if (StorD_cur.aStoryArea.GetSize() > 1)    // 영역 정보를 가지고 있다면 영역 검사
						{
							if (!IsInsideOfStorArea2D(DataNode.x, DataNode.y, StorD_cur))  continue;
						}

						if(nSelectionType == 0 && DataNode.z > dStoryLevel+dTol)continue;
						if(nSelectionType == 1 && DataNode.z < dStoryLevel-dTol)continue;
						//if(nSelectionType == 2)
						if(nSelectionType == 3)continue;
						if(nSelectionType == 4)continue;
						if(nSelectionType == 5)continue;
					}
					nSel++;
				}
				if(nSel == nNode)bFind=TRUE;
			}
		}
		if(bFind)KeyElemMap.SetAt(KeyElem, KeyStorUser);
	}

	nCount=KeyElemMap.GetCount();
	if(nCount != 0 && pKeyElem != NULL)
	{
		pKeyElem->SetSize(nCount);
		int nIndex=0;
		pos=KeyElemMap.GetStartPosition();
		while(pos != NULL)
		{
			KeyElemMap.GetNextAssoc(pos, KeyElem, KeyStor);
			pKeyElem->SetAt(nIndex, KeyElem);
			nIndex++;
		}
		CQSort::QSortUInt(pKeyElem->GetData(), nCount);
	}

	if(bDeleteLinkMgr)
	{
		delete pLinkedKeyMgr_stor;
	}
}

