double CAttrCtrl::GetStorLevel(T_STOR_K StorK)
{
	T_STOR_D StorD;
	if (!GetStor(StorK, StorD, FALSE))  { ASSERT(0);  StorD.Initialize(); }

	return StorD.dStoryLevel;
}

int CAttrCtrl::GetStorLevel(const CArray<T_STOR_K,T_STOR_K>& aStorK, CMap<T_STOR_K,T_STOR_K, double,double>& rmStor2Level)
{
	if (aStorK.GetSize() > 0)
	{
		rmStor2Level.RemoveAll();
		rmStor2Level.InitHashTable(GF_GetHashSizeByCount(aStorK.GetSize()));
	}

	double dLevel = 0.0; 
	for (int i=0; i<aStorK.GetSize(); ++i)
	{
		dLevel = GetStorLevel(aStorK[i]);
		rmStor2Level.SetAt(aStorK[i], dLevel);
	}         
	ASSERT(aStorK.GetSize() == rmStor2Level.GetCount());

	return rmStor2Level.GetCount();
}

// @param bToUpOrDown : 현재층 기준으로 윗방향으로 층고 or 아래 방향으로 층고. TRUE : u-자형 층고 (윗방향), FALSE : n-자형 층고 (아랫방향)
BOOL CAttrCtrl::GetStorHeight(const CArray<T_STOR_K,T_STOR_K>& aStorK, CMap<T_STOR_K,T_STOR_K, double,double>& rmStor2Height, BOOL bToUpOrDown, 
							  CMap<T_STOR_K,T_STOR_K, T_STOR_K,T_STOR_K>* pmStorCur2Ref_forHeight/*=NULL*/, BOOL bUseStorNodeKMapMgr/*=FALSE*/)
{
	rmStor2Height.RemoveAll();

	CArray<T_STOR_K,T_STOR_K> aStorK_all;    aStorK_all.Copy(aStorK);
	GetStorKeyList(aStorK_all);

	CMap<T_STOR_K,T_STOR_K, double,double> mStor2Level;   mStor2Level.RemoveAll();
	GetStorLevel(aStorK_all, mStor2Level);

	// 상/하층 연결정보 구성
	CLinkedKeyMgr linkedKeyMgr_stor;
	GetStorLinkedData(linkedKeyMgr_stor, &aStorK_all, bUseStorNodeKMapMgr);

	CArray<T_STOR_K,T_STOR_K> aStorK_next;    aStorK_next.RemoveAll();
	double dLevel_next = 0.0;
	double dHeight_max = 0.0;

	double dLevel_cur = 0.0;
	T_STOR_K StorK_cur = 0;
	T_STOR_K StorK_maxRef = 0;
	for (int i=0; i<aStorK.GetSize(); ++i)
	{
		StorK_cur = aStorK[i];
		if (!mStor2Level.Lookup(StorK_cur, dLevel_cur))  { ASSERT(0);  return FALSE; }

		aStorK_next.RemoveAll();
		if (bToUpOrDown) linkedKeyMgr_stor.GetNextKeyList(StorK_cur, aStorK_next);
		else             linkedKeyMgr_stor.GetPrevKeyList(StorK_cur, aStorK_next);

		dHeight_max = 0.0;
		StorK_maxRef = StorK_cur;
		for (int k=0; k<aStorK_next.GetSize(); ++k)
		{
			if (!mStor2Level.Lookup(aStorK_next[k], dLevel_next))  { ASSERT(0);  return FALSE; }
			if (dHeight_max < fabs(dLevel_cur-dLevel_next)) 
			{
				dHeight_max = fabs(dLevel_cur-dLevel_next);
				StorK_maxRef = aStorK_next[k];
			}
		}      

		rmStor2Height.SetAt(StorK_cur, dHeight_max);
		if (pmStorCur2Ref_forHeight)  pmStorCur2Ref_forHeight->SetAt(StorK_cur, StorK_maxRef);
	}    

	return TRUE;
}

void CAttrCtrl::GetNodeKeyListStorUser(const T_STOR_K KeyStor, CArray<T_NODE_K, T_NODE_K>* pKeyNode, BOOL bExcludeMidNode/*=TRUE*/, CLinkedKeyMgr* pLinkedKeyMgr_stor/*=NULL*/, CMapEx<T_NODE_K, T_NODE_K, T_STOR_K, T_STOR_K>* pmNodeK2StorK/*=NULL*/)
{
	ASSERT(pKeyNode != NULL);
	if(pKeyNode != NULL)pKeyNode->RemoveAll();
	if(pKeyNode == NULL)return;
	if(KeyStor == NULL)return;

	CArray<T_STOR_K, T_STOR_K> KeyListStor;
	GetStorKeyList(KeyListStor);
	if(KeyListStor.GetSize() == 0)return;
	CArray<T_STOR_D, T_STOR_D&> DataListStor;
	GetStorData(DataListStor);

	// 상/하층 연결정보 구성
	BOOL bDeleteLinkMgr=FALSE;
	if(!pLinkedKeyMgr_stor) 
	{
		bDeleteLinkMgr=TRUE;
		pLinkedKeyMgr_stor = new CLinkedKeyMgr;
		GetStorLinkedData(*pLinkedKeyMgr_stor, NULL);
	}

	// 층에 있는 node 정보 수집 => KeyNodeMap
	CArray<T_NODE_K,T_NODE_K> aNodeK;
	GetNodeKeyList(aNodeK);

	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	//CStoryData storyData(pDoc);
	CStoryData* pStoryData = pDoc->GetStoryData();

	CMapEx<T_NODE_K, T_NODE_K, T_STOR_K, T_STOR_K> mNodeK2Stor_Local;
	if(pmNodeK2StorK)
	{
		T_NODE_K NodeK=0;
		T_STOR_K StorK=0;
		CopyMap(*pmNodeK2StorK, mNodeK2Stor_Local, NodeK, StorK);
	}
	else
	{
		pStoryData->GetNodeToStorMap(aNodeK, mNodeK2Stor_Local);
	}

	// KeyStor에 속하는 층으로 제한.
	CMapEx<T_STOR_K,T_STOR_K, int,int> mStorK_filter;    mStorK_filter.RemoveAll();
	if (KeyStor!=NULL)
	{
		mStorK_filter.SetAt(KeyStor, 0);

		CArray<T_STOR_K,T_STOR_K> aStorK_prev; aStorK_prev.RemoveAll();
		pLinkedKeyMgr_stor->GetPrevKeyList(KeyStor, aStorK_prev);
		for (int k=0; k<aStorK_prev.GetSize(); ++k)  mStorK_filter.SetAt(aStorK_prev[k], 0);

		T_STOR_K StorK = 0;
		CArray<T_NODE_K,T_NODE_K> aNodeK_remove;
		aNodeK_remove.Copy(aNodeK);
		for (int i=aNodeK_remove.GetSize()-1; i>=0; --i)
		{
			mNodeK2Stor_Local.Lookup(aNodeK_remove[i], StorK);
			if (mStorK_filter.Exist(StorK))  aNodeK_remove.RemoveAt(i);
		}

		for (int i=0; i<aNodeK_remove.GetSize(); ++i) mNodeK2Stor_Local.RemoveKey(aNodeK_remove[i]);
	}

	double dTol=m_pDoc->m_pFlagCtrl->GetGeneralCoordinateToleranceCurrentUnit();
	CMapEx<T_NODE_K,T_NODE_K, int,int> mNodeK_mid;    mNodeK_mid.RemoveAll();
	mNodeK_mid.InitHashTable(HASHSIZENODE);
	CMapEx<T_NODE_K,T_NODE_K, int,int> mNodeK_out;    mNodeK_out.RemoveAll();
	mNodeK_out.InitHashTable(HASHSIZENODE);

	CArray<T_STOR_K,T_STOR_K> aStorK_next;    aStorK_next.RemoveAll();
	CMapEx<T_STOR_K,T_STOR_K, double,double> mStorK2Level;  mStorK2Level.RemoveAll();
	mStorK2Level.InitHashTable(HASHSIZESTOR);
	double dLevel_lower = 0.0;
	double dLevel_upper = 0.0;

	// node 소속층은?
	T_STOR_K StorK_lower = 0;
	T_STOR_K StorK_upper = 0;
	T_NODE_K NodeK = 0;

	POSITION pos = mNodeK2Stor_Local.GetStartPosition();
	while(pos)
	{
		mNodeK2Stor_Local.GetNextAssoc(pos, NodeK, StorK_lower);

		pLinkedKeyMgr_stor->GetNextKeyList(StorK_lower, aStorK_next);
		if (aStorK_next.GetSize() == 0)  continue;    // 다음층이 없는 경우 

		T_NODE_D NodeD;
		if (!GetNode(NodeK, NodeD))  { ASSERT(0);  continue; }

		T_STOR_D StorD;   StorD.Initialize();
		if (aStorK_next.GetSize() == 1) StorK_upper = aStorK_next[0];
		else
		{
			for (int i=0; i<aStorK_next.GetSize(); ++i)
			{
				if (!GetStor(aStorK_next[i], StorD))  { ASSERT(0);  continue; }
				if (StorD.aStoryArea.GetSize() > 0) { StorK_upper = aStorK_next[i];  continue; }

				if (IsInsideOfStorArea2D(NodeD.x, NodeD.y, StorD))  { StorK_upper = aStorK_next[i];  break; }
			}
		}

		if (StorK_upper == 0)  continue;

		// get story level
		if (!mStorK2Level.Lookup(StorK_lower, dLevel_lower))
		{
			GetStor(StorK_lower, StorD);  dLevel_lower = StorD.dStoryLevel;
			mStorK2Level.SetAt(StorK_lower, dLevel_lower);
		}

		if (!mStorK2Level.Lookup(StorK_upper, dLevel_upper))
		{
			GetStor(StorK_upper, StorD);  dLevel_upper = StorD.dStoryLevel;
			mStorK2Level.SetAt(StorK_upper, dLevel_upper);
		}

		double dLevel_boundary = (dLevel_lower+dLevel_upper)*0.5;   // 층 중간 지점
		if (fabs(NodeD.z-dLevel_boundary) < dTol)
		{
			// 중간점에 대한 처리!
			if (bExcludeMidNode)
			{
				// 중간점을 제외  (중간점의 경우 위층과 아래층에 반반씩 분배하는 경우가 있음)
				mNodeK_mid.SetAt(NodeK, 0);
			}
			else
			{
				// 중간점은 상부층에서 제외
				if(KeyStor==StorK_upper) mNodeK_out.SetAt(NodeK, 0);
			}
		}
		else
		{
			// 층간절점을 중간레벨에 따라 상/하부층에 분배
			if(KeyStor==StorK_lower)
			{
				// Boundary 상부 절점들을 제거
				if(NodeD.z>dLevel_boundary+dTol && NodeD.z<dLevel_upper-dTol) mNodeK_out.SetAt(NodeK, 0);
			}
			else
			{
				// Boundary 하부 절점들을 제거
				if(NodeD.z<dLevel_boundary-dTol) mNodeK_out.SetAt(NodeK, 0);
			}
		}
	}

	CArray<T_NODE_K,T_NODE_K> aNodeK_remove;
	// remove mid node
	mNodeK_mid.GetKeyList(aNodeK_remove);
	for (int i=0; i<aNodeK_remove.GetSize(); ++i) mNodeK2Stor_Local.RemoveKey(aNodeK_remove[i]);
	// Boundary 상/하부 절점들을 제거
	mNodeK_out.GetKeyList(aNodeK_remove);
	for (int i=0; i<aNodeK_remove.GetSize(); ++i) mNodeK2Stor_Local.RemoveKey(aNodeK_remove[i]);

	if (mNodeK2Stor_Local.GetCount() > 0)
	{
		mNodeK2Stor_Local.GetKeyList(*pKeyNode);
		CQSort::QSortUInt(pKeyNode->GetData(), pKeyNode->GetSize());
	}

	if(bDeleteLinkMgr) delete pLinkedKeyMgr_stor;  
}

void CAttrCtrl::GetMidNodeKeyListStorUser(T_STOR_K StorUserK, CArray<T_NODE_K, T_NODE_K>* pKeyNode,
										  CString strPosition, CLinkedKeyMgr* pLinkedKeyMgr/*=NULL*/)
{
	ASSERT(pKeyNode != NULL);
	if(pKeyNode != NULL)pKeyNode->RemoveAll();
	if(pKeyNode == NULL)return;
	if(StorUserK==NULL) return;

	CArray<T_STOR_K, T_STOR_K> KeyListStor;
	GetStorKeyList(KeyListStor);
	if(KeyListStor.GetSize() == 0)return;
	CArray<T_STOR_D, T_STOR_D&> DataListStor;
	GetStorData(DataListStor);
	double dTol=0.;
	for(int iq=1; iq<DataListStor.GetSize(); iq++)
		dTol=__max(dTol, fabs(DataListStor[iq].dStoryLevel-DataListStor[iq-1].dStoryLevel)*1.e-6);

	// 상/하층 연결정보 구성
	BOOL bDeleteLinkMgr=FALSE;
	if(!pLinkedKeyMgr) 
	{
		bDeleteLinkMgr=TRUE;
		pLinkedKeyMgr= new CLinkedKeyMgr;
		GetStorLinkedData(*pLinkedKeyMgr, NULL);
	}

	CLinkedKeyMgr linkedKeyMgr_stor;
	linkedKeyMgr_stor.Copy(*pLinkedKeyMgr);
	CArray<T_STOR_K,T_STOR_K> aKeyStor; aKeyStor.RemoveAll();
	aKeyStor.Add(StorUserK);
	GetStorLinkedData_FilterUnlinkedStor(linkedKeyMgr_stor, &aKeyStor);

	//   // 상/하층 연결정보 구성
	//   CLinkedKeyMgr linkedKeyMgr_stor;
	//   CArray<T_STOR_K,T_STOR_K> aKeyStor; aKeyStor.RemoveAll();
	//   aKeyStor.Add(StorUserK);
	//   GetStorLinkedData(linkedKeyMgr_stor, &aKeyStor);

	// 층에 있는 node 정보 수집 => KeyNodeMap
	BOOL bCheckLevel=TRUE;
	CMap<T_NODE_K, T_NODE_K, T_STOR_K, T_STOR_K>KeyNodeMap;
	if (!GetMidNode2StorMap(linkedKeyMgr_stor, KeyNodeMap, bCheckLevel))  { ASSERT(0);  return; }

	// 상/하층 연결정보로 층 구성
	CMapEx<T_STOR_K,T_STOR_K, int,int> mStorK_filter;    mStorK_filter.RemoveAll();
	CArray<T_STOR_K,T_STOR_K> aLinkedKeyStor; aLinkedKeyStor.RemoveAll();
	linkedKeyMgr_stor.GetKeyListAll(aLinkedKeyStor);
	for (int k=0; k<aLinkedKeyStor.GetSize(); ++k) { mStorK_filter.SetAt(aLinkedKeyStor[k], 0); }

	BOOL bFilterLower = FALSE; if(strPosition.CompareNoCase(_T("LOWER"))==0) bFilterLower = TRUE;
	BOOL bFilterUpper = FALSE; if(strPosition.CompareNoCase(_T("UPPER"))==0) bFilterUpper = TRUE;

	int nCount=KeyNodeMap.GetCount();
	if(nCount != 0 && pKeyNode != NULL)
	{
		pKeyNode->SetSize(nCount);
		int nIndex=0;
		T_STOR_K KeyStor = 0;
		T_NODE_K KeyNode = 0;
		POSITION pos=KeyNodeMap.GetStartPosition();
		while(pos != NULL)
		{
			KeyNodeMap.GetNextAssoc(pos, KeyNode, KeyStor);
			if (!mStorK_filter.Exist(KeyStor)) continue;    // 상/하층 연결정보에 속하지 않는 node는 skip

			if(bFilterLower && KeyStor!=StorUserK) continue;
			if(bFilterUpper && KeyStor==StorUserK) continue;

			pKeyNode->SetAt(nIndex, KeyNode);
			nIndex++;
		}
		nCount = nIndex;
		pKeyNode->SetSize(nCount);

		CQSort::QSortUInt(pKeyNode->GetData(), nCount);
	}
}

// MQC:XXXX-HSSHIM-20090723
// @param bIngnoreStorDiaphragm : Story의 bFloorDiaphragm 옵션을 무시할지 여부 
//                                Flexable Floor에 대해서도 Diaphragm으로 가정해서 계산할 필요가 있는 경우에 사용
void CAttrCtrl::GetNodeKeyListStorDiaphragm(T_STOR_K KeyStor, CArray<T_NODE_K, T_NODE_K>& arNodeKey,
											BOOL bIngnoreStorDiaphragm/*=FALSE*/, BOOL bSolver/*=FALSE*/)
{
	if (KeyStor == 0)  { ASSERT(0);  return; }

	arNodeKey.RemoveAll();
	T_STOR_D DataStor;
	if(!GetStor(KeyStor, DataStor))return;
	if(!DataStor.bFloorDiaphragm)   // is Diaphragm story?
	{
		if (!bIngnoreStorDiaphragm)  return;
	}

	// Story Diaphragm 이 지정되어 있어도 일반 스테이지인 경우(base,Final은 제외)에는 Stdg가 입력되어 있어야 된다.
	if(m_pDoc->m_pStagCtrl->IsMinMaxStag())return;
	if(m_pDoc->m_pStagCtrl->IsNormalStag() && !ExistStdg(KeyStor))return;

	double dTol=m_pDoc->m_pFlagCtrl->GetGeneralCoordinateToleranceCurrentUnit();

	//-----------------------------------------------------------
	// 다른 모듈에 동일 Level의 층이 있다면 제외 영역으로 고려
	CArray<T_STOR_K,T_STOR_K> aStorK;   aStorK.RemoveAll();
	GetStorKeyList(aStorK);

	double dLevel_curr = GetStorLevel(KeyStor);
	double dLevel_comp = 0;
	CArray<T_STOR_K,T_STOR_K> aStorK_sameLevel;   aStorK_sameLevel.RemoveAll();
	for (int i=0; i<aStorK.GetSize(); ++i)
	{
		if (aStorK[i] == KeyStor)  continue;

		dLevel_comp = GetStorLevel(aStorK[i]);
		double dDist = fabs(dLevel_comp - dLevel_curr);
		if (dDist + FLT_EPSILON < dTol)
		{
			aStorK_sameLevel.Add(aStorK[i]); 
			continue; 
		}
	}

	CArray<T_STOR_D,T_STOR_D&> aStorD_sameLevel;   aStorD_sameLevel.RemoveAll();
	aStorD_sameLevel.SetSize(aStorK_sameLevel.GetSize());
	for (int i=0; i<aStorK_sameLevel.GetSize(); ++i)
	{
		if (!GetStor(aStorK_sameLevel[i], aStorD_sameLevel[i]))  { ASSERT(0);  return; }
	}

	//-----------------------------------------------------------

	CMapEx<T_NODE_K,T_NODE_K, int,int> mNodeK;    mNodeK.RemoveAll();
	mNodeK.InitHashTable(HASHSIZENODE);
	T_NODE_K KeyNode;
	T_NODE_D DataNode;
	POSITION pos=GetStartNode();
	while(pos != NULL)
	{
		GetNextNode(pos, KeyNode, DataNode);
		if(fabs(DataStor.dStoryLevel-DataNode.z) > dTol)continue;

		if (DataStor.aStoryArea.GetSize() > 1)    // 영역 정보를 가지고 있다면 영역 검사
		{
			if (!IsInsideOfStorArea2D(DataNode.x, DataNode.y, DataStor))  continue;
		}
		else  // 영역 정보가 없다면 동일 Level의 영역 정보를 가진 층이 우선
		{
			BOOL bSkip = FALSE;
			for (int k=0; k<aStorD_sameLevel.GetSize(); ++k)
			{
				if (IsInsideOfStorArea2D(DataNode.x, DataNode.y, aStorD_sameLevel[k]))  { bSkip = TRUE;  break; }
			}
			if (bSkip)  continue;
		}

		// 솔버로 넘길때는 포함시킨다. MQC 9216 JWKWON-2014-12-05
		if(ExistDrls(KeyNode) && !bSolver)continue;
		mNodeK.SetAt(KeyNode,0);
	}

	if (mNodeK.GetCount() > 0)    mNodeK.GetSortedKeyListforUintK(arNodeKey);
}

double CAttrCtrl::GetBldgHeight()
{  
	T_STOR_D StorData;
	CArray<T_STOR_K, T_STOR_K> aStorKeyList;
	GetStorKeyList(aStorKeyList);
	int nStorCount = aStorKeyList.GetSize();
	if(nStorCount > 0) 
	{
		if(!GetStor(aStorKeyList[nStorCount - 1], StorData)) return 0.;
		return StorData.dStoryLevel;
	}
	else return 0.;
}
