void CAttrCtrl::CalcDiaphragmCenter(CArray<double, double>& arCenterX, CArray<double, double>& arCenterY, BOOL bUseBedrockLevel, BOOL bView/*=FALSE*/)
{
	arCenterX.RemoveAll();
	arCenterY.RemoveAll();

	int nStory=GetCountStor();
	if(nStory == 0)return;
	CLateralLoad LateralLoad;
	LateralLoad.Calc_DiaphramCenter(bUseBedrockLevel, bView);
	for(int i=0; i<nStory; i++)
	{
		arCenterX.Add(LateralLoad.m_aDiaphramCenter[i].DiaphCnt_x);
		arCenterY.Add(LateralLoad.m_aDiaphramCenter[i].DiaphCnt_y);
	}
}

////////////// mdul ////////////////

void CAttrCtrl::GetMdulList(CArray<CString, CString&>& rstrMdulList)
{
	rstrMdulList.RemoveAll();

	T_MDUL_D Data;
	CArray<T_MDUL_K, T_MDUL_K>KeyList;
	GetMdulKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetMdul(KeyList[i], Data))
			rstrMdulList.Add(Data.strName);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetMdulKeyList(CArray<T_MDUL_K, T_MDUL_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_MDUL_K Key;
	T_MDUL_D Data;
	pos=GetStartMdul();
	while(pos != NULL)
	{
		GetNextMdul(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::ExistMdul(CString& rMdulName)
{
	T_MDUL_D data;
	return GetMdul(rMdulName, data);
}

BOOL CAttrCtrl::ExistMdul(T_MDUL_K Key)
{
	T_MDUL_D Data;
	return m_pDataMemb->m_mdul.Get(Key,Data);
}

BOOL CAttrCtrl::GetMdul(CString& rMdulName, T_MDUL_D& rData)
{
	T_MDUL_K key;
	T_MDUL_D data;
	CString strMdulName=rMdulName;
	strMdulName.TrimRight();

	POSITION pos=m_pDataMemb->m_mdul.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_mdul.GetNext(pos,key,data);
		if(strMdulName.CompareNoCase(data.strName) == 0)
		{
			m_pUnitCtrl->ConvertUnitMdulOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetMdul(T_MDUL_K Key,T_MDUL_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_mdul.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitMdulOut(rData);
	return bReturn;
}

T_MDUL_K CAttrCtrl::GetMdulKey(CString& rMdulName)
{
	T_MDUL_K key;
	T_MDUL_D data;

	POSITION pos=GetStartMdul();
	while(pos != NULL)
	{
		GetNextMdul(pos,key,data);
		if(rMdulName.CompareNoCase(data.strName) == 0)return key;
	}
	key=0;
	return key;
}

int CAttrCtrl::GetCountMdul()
{
	return m_pDataMemb->m_mdul.GetCount();
}

POSITION CAttrCtrl::GetStartMdul()
{
	return m_pDataMemb->m_mdul.GetStart();
}

void CAttrCtrl::GetNextMdul(POSITION& rNextPosition,T_MDUL_K& rKey,T_MDUL_D& rData)
{
	m_pDataMemb->m_mdul.GetNext(rNextPosition,rKey,rData);
	m_pUnitCtrl->ConvertUnitMdulOut(rData);
}

T_MDUL_K CAttrCtrl::GetLastNumMdul()
{
	return m_pDataMemb->m_mdul.m_nLastNum;
}

T_MDUL_K CAttrCtrl::GetStartNumMdul()
{
	return m_pDataMemb->m_mdul.m_nStartNum;
}

