BOOL CAttrCtrl::ExistModl()
{
	T_MODL_D Data;
	return m_pDataMemb->m_modl.Get(Data);
}

BOOL CAttrCtrl::GetModl(T_MODL_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_modl.Get(rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitModlOut(rData);
	return bReturn;
}

CString CAttrCtrl::GetModlBaseName()
{
	return _LS(IDS_DB_MODL_DEFAULT_MODULE_NAME_BASE);    // // base module 이름
}

// modl 정보가 없어도 default module 정보를 만들어서 반환
BOOL CAttrCtrl::GetModlWithBase(T_MODL_D& rData)
{
	rData.Initialize();
	if (GetModl(rData))  return TRUE;

	CArray<T_STOR_K,T_STOR_K> aStorK_all;  aStorK_all.RemoveAll();
	GetStorKeyList(aStorK_all);

	rData.Initialize();
	T_MODL_BASE Modl_base;    Modl_base.Initialize();
	Modl_base.csModuleName = GetModlBaseName();    // // base module 이름
	Modl_base.aStoryK.Copy(aStorK_all);
	if (Modl_base.StorK_start == 0 && Modl_base.aStoryK.GetSize() > 0) Modl_base.StorK_start = Modl_base.aStoryK[0];
#if defined(_IGEN)
	if (Modl_base.StorK_end == 0   && Modl_base.aStoryK.GetSize() > 0) Modl_base.StorK_end = Modl_base.aStoryK[Modl_base.aStoryK.GetSize()-1];
#endif
	//if (Modl_base.StorK_end == 0   && Modl_base.aStoryK.GetSize() > 0) Modl_base.StorK_end = Modl_base.aStoryK[Modl_base.aStoryK.GetSize()-1];    // end 층은 0으로 설정해 둔다. 탑지정이 끝나면 자동으로 찾도록...
	rData.aModule.Add(Modl_base);

	return TRUE;
}

// StorK_last가 속한 module의 뚜껑 층 반환
// @param StorK_last : StorK_last가 속한 module의 마지막 층
T_STOR_K CAttrCtrl::GetEndStorKOfModule(const T_MODL_D& rData, T_STOR_K StorK_last)
{
	if (StorK_last == 0)  { ASSERT(0);  return 0; }

	double dLevel_last = GetStorLevel(StorK_last);   // StorK_last 보다 같거나 높은 층을 찾는다.
	double dTol=m_pDoc->m_pFlagCtrl->GetGeneralCoordinateToleranceCurrentUnit();

	double dLevel_min = DBL_MAX;
	T_STOR_K StorK_min = 0;
	for (int i=0; i<rData.aModule.GetSize(); ++i)
	{
		if (rData.aModule[i].aStoryK.GetSize() == 0)  continue;  // moduel에 층이 없는 경우

		T_STOR_K StorK_first = rData.aModule[i].aStoryK[0];
		if (rData.aModule[i].StorK_start != 0)  StorK_first = rData.aModule[i].StorK_start;

		double dLevel_first = GetStorLevel(StorK_first);
		if (dLevel_first < dLevel_min)
		{
			if (dLevel_first - dLevel_last > -dTol)  { dLevel_min = dLevel_last;  StorK_min = StorK_first; }
		}
	}

	if (StorK_min == 0)  { /* ASSERT(0); */  StorK_min = StorK_last; }

	return StorK_min;
}

// start ~ end story까지의 module 공간을 고려해서 module의 story list를 반환
BOOL CAttrCtrl::GetModlBySpace(T_MODL_D& rData)
{
	if (!GetModlWithBase(rData)) { ASSERT(0);  return FALSE; }

	// 공간 개념으로 Story List 채우기
	for (int i=0; i<rData.aModule.GetSize(); ++i)
	{
		T_MODL_BASE& Modl_base = rData.aModule[i];
		if (Modl_base.aStoryK.GetSize() == 0)  continue;  // moduel에 층이 없는 경우

		T_STOR_K StorK_first = Modl_base.aStoryK[0];
		if (Modl_base.StorK_start == 0)  Modl_base.StorK_start = StorK_first;
		if (Modl_base.StorK_start != StorK_first)  Modl_base.aStoryK.InsertAt(0, Modl_base.StorK_start);

		T_STOR_K StorK_last = Modl_base.aStoryK[Modl_base.aStoryK.GetSize()-1];
		if (Modl_base.StorK_end == 0)  Modl_base.StorK_end = GetEndStorKOfModule(rData, StorK_last);
		if (Modl_base.StorK_end != StorK_last)  Modl_base.aStoryK.Add(Modl_base.StorK_end);
	}

	return TRUE;
}

