BOOL CAttrCtrl::GetSerialDmas(T_STOR_K Key,T_DMAS_KEY& rKeySerial)
{
	T_DMAS_K key;
	T_DMAS_D data;
	key.key.entity=Key;

	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_dmas.Get(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

