BOOL CAttrCtrl::CalcDmas(T_DMAS_D& rData)
{
	rData.Result.Initialize();
	switch(rData.nMassType)
	{
	case(1):  // Point
		rData.Result.dPointX=rData.Point.dPointX;
		rData.Result.dPointY=rData.Point.dPointY;
		rData.Result.dPointMass=rData.Point.dPointMass;
		rData.Result.dRotationMass=rData.Point.dRotationMass;
		break;
	case(2):  // Line
		rData.Result.dPointX=rData.Line.dPointX;
		rData.Result.dPointY=rData.Line.dPointY;
		rData.Result.dPointMass=rData.Line.dLineMass*rData.Line.dLength;
		rData.Result.dRotationMass=rData.Result.dPointMass*pow(rData.Line.dLength,2.)/12.;
		break;
	case(3):  // Triangle
		{
			double AM=rData.Triangle.dAreaMass;
			double XY[3][2];
			XY[0][0]=rData.Triangle.dP1X;
			XY[0][1]=rData.Triangle.dP1Y;
			XY[1][0]=rData.Triangle.dP2X;
			XY[1][1]=rData.Triangle.dP2Y;
			XY[2][0]=rData.Triangle.dP3X;
			XY[2][1]=rData.Triangle.dP3Y;
			double DX=XY[0][0];
			double DY=XY[0][1];
			for(int i=0; i<3; i++)
			{
				XY[i][0]=XY[i][0]-DX;
				XY[i][1]=XY[i][1]-DY;
			}
			double UXi=(XY[1][0]-XY[0][0])/sqrt(XY[1][0]*XY[1][0]+XY[1][1]*XY[1][1]);
			double UYi=(XY[1][1]-XY[0][1])/sqrt(XY[1][0]*XY[1][0]+XY[1][1]*XY[1][1]);
			double UXj=-UYi;
			double UYj= UXi;
			for(int j=1; j<3; j++)
			{
				double X=XY[j][0]*UXi+XY[j][1]*UYi;
				double Y=XY[j][0]*UXj+XY[j][1]*UYj;
				if(fabs(X) <= 1.e-10)X=0.;
				if(fabs(Y) <= 1.e-10)Y=0.;
				XY[j][0]=X;
				XY[j][1]=Y;
			}
			double B=XY[1][0];
			double D=XY[2][1];
			double A=XY[1][0]-XY[2][0];
			double AREA=B*D/2.0;
			double XC=2.0*B/3.0-A/3.0;
			double YC=D/3.0;
			double RIX=B*pow(D,3.)/36.0;
			double RIY=B*D*(pow(B,2.)-A*B+pow(A,2.))/36.0;
			double RIZ=RIX+RIY;
			double XC1=XC*UXi+YC*UXj+DX;
			double YC1=XC*UYi+YC*UYj+DY;
			rData.Result.dPointX=XC1;
			rData.Result.dPointY=YC1;
			rData.Result.dPointMass=AM*AREA;
			rData.Result.dRotationMass=AM*RIZ;
		}
		break;
	case(4): // Rect
		{
			rData.Result.dPointX=rData.Rect.dPointX;
			rData.Result.dPointY=rData.Rect.dPointY;
			rData.Result.dPointMass=rData.Rect.dAreaMass*rData.Rect.dLength1*rData.Rect.dLength2;
			rData.Result.dRotationMass=rData.Result.dPointMass/12*(pow(rData.Rect.dLength1,2.)+pow(rData.Rect.dLength2,2.));
		}
		break;
	case(5): // LineArc
		{
			double AM=rData.CirArc.dLineMass;
			double ANG=rData.CirArc.dArcAngle;
			double R=rData.CirArc.dArcRadius;
			double A1=rData.CirArc.dCenterAngle;
			double PIQ=CMathFunc::m_pi;
			double RAD=PIQ/180.;
			double ALP=RAD*ANG/2.0;
			double TK=1.0;
			double AREA=ALP*TK*2.0*R;
			double C=R*sin(ALP)/ALP;
			double XC=C*cos(A1*RAD);
			double YC=C*sin(A1*RAD);
			double RIX=pow(R,3.)*TK*(ALP+sin(ALP)*cos(ALP)-2.0*pow(sin(ALP),2.)/ALP);
			double RIY=pow(R,3.)*TK*(ALP-sin(ALP)*cos(ALP));
			double RIZ=RIX+RIY;
			rData.Result.dPointX=rData.CirArc.dPointX+XC;
			rData.Result.dPointY=rData.CirArc.dPointX+YC;
			rData.Result.dPointMass=AM*AREA;
			rData.Result.dRotationMass=AM*RIZ;
		}
		break;
	case(6): // AreaArc
		{
			double AM=rData.CirArea.dAreaMass;
			double ANG=rData.CirArea.dArcAngle;
			double R=rData.CirArea.dArcRadius;
			double TK=rData.CirArea.dArcWidth;
			double A1=rData.CirArea.dCenterAngle;
			double PIQ=CMathFunc::m_pi;
			double RAD=PIQ/180.;
			double ALP=RAD*ANG/2.0;
			double F=TK/R;
			double AREA=ALP*TK*(2.0*R-TK);
			double C=R*2.0*sin(ALP)/(3.0*ALP)*(1.0-F+1.0/(2.0-F));
			double XC=C*cos(A1*RAD);
			double YC=C*sin(A1*RAD);
			double RIX=pow(R,3.)*TK*((1.0-1.5*F+pow(F,2.)-0.25*pow(F,3.))*
				(ALP+sin(ALP)*cos(ALP)-2.0*(pow(sin(ALP),2.))/ALP)+
				pow(F*sin(ALP),2.)/(3.0*ALP*(2.0-F))*(1.0-F+pow(F,2.)/6.0));
			double RIY=pow(R,3.)*TK*(1.0-1.50*F+pow(F,2.)-0.25*pow(F,3.))*(ALP-sin(ALP)*cos(ALP));
			double RIZ=RIX+RIY;
			double RM=AM*AREA;
			double RMI=AM*RIZ;
			rData.Result.dPointX=rData.CirArea.dPointX+XC;
			rData.Result.dPointY=rData.CirArea.dPointY+YC;
			rData.Result.dPointMass=RM;
			rData.Result.dRotationMass=RMI;
		}
		break;
	default:
		ASSERT(FALSE);
		return FALSE;
	}
	return TRUE;
}

