void CAttrCtrl::GetNplnList(CArray<CString, CString&>& rstrPlaneList)
{
	rstrPlaneList.RemoveAll();

	T_NPLN_D Data;
	CArray<T_NPLN_K, T_NPLN_K>KeyList;
	GetNplnKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetNpln(KeyList[i], Data))
			rstrPlaneList.Add(Data.PlaneName);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetNplnKeyList(CArray<T_NPLN_K, T_NPLN_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<CString, CString&>arPlaneName;

	POSITION pos;
	T_NPLN_K Key;
	T_NPLN_D Data;
	pos=GetStartNpln();
	while(pos != NULL)
	{
		GetNextNpln(pos, Key, Data);
		rKeyList.Add(Key);
		arPlaneName.Add(Data.PlaneName);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortStringWithIndex(rKeyList.GetData(), arPlaneName.GetData(), rKeyList.GetSize());
}

