{
	T_NPLN_D Data;
	return m_pDataMemb->m_npln.Get(Key,Data);
}

BOOL CAttrCtrl::GetNpln(CString& rPlaneName, T_NPLN_D& rData)
{
	T_NPLN_K key;
	T_NPLN_D data;
	CString strPlaneName=rPlaneName;
	strPlaneName.TrimRight();

	POSITION pos=m_pDataMemb->m_npln.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_npln.GetNext(pos,key,data);
		if(strPlaneName.CompareNoCase(data.PlaneName) == 0)
		{
			m_pUnitCtrl->ConvertUnitNplnOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

