T_NPLN_K CAttrCtrl::GetNplnKey(CString& rPlaneName)
{
	T_NPLN_K key;
	T_NPLN_D data;

	POSITION pos=GetStartNpln();
	while(pos != NULL)
	{
		GetNextNpln(pos,key,data);
		if(rPlaneName.CompareNoCase(data.PlaneName) == 0)return key;
	}
	key=0;
	return key;
}

