struct T_PLANE_TEMP
{
	double a;
	double b;
	double c;
	double h;
	double tol;
};
void CAttrCtrl::GetKeyListNplnUser(CArray<T_NPLN_K, T_NPLN_K>* pKeyNpln,
								   CArray<T_NODE_K, T_NODE_K>* pKeyNode, CArray<T_ELEM_K, T_ELEM_K>* pKeyElem)
{
	if(pKeyNode != NULL)pKeyNode->RemoveAll();
	if(pKeyElem != NULL)pKeyElem->RemoveAll();
	if(pKeyNode == NULL && pKeyElem == NULL)return;
	int nCount=pKeyNpln->GetSize();
	if(nCount == 0)return;

	CMap<T_NODE_K, T_NODE_K, T_NODE_K, T_NODE_K>KeyNodeMap;
	KeyNodeMap.InitHashTable(m_pDoc->GetHashSizeNode());
	CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K>KeyElemMap;
	KeyElemMap.InitHashTable(m_pDoc->GetHashSizeElem());

	double p1[3], p2[3], p3[3];
	T_NPLN_D DataNpln;
	T_PLANE_TEMP PlaneEquation;
	CArray<T_PLANE_TEMP, T_PLANE_TEMP&> aDataPlane;
	for(int i=0; i<nCount; i++)
	{
		if(GetNpln(pKeyNpln->GetAt(i), DataNpln))
		{
			if(DataNpln.nPlaneType == 1)
			{
				for(int j=0; j<3; j++)
				{
					p1[j]=DataNpln.dPoint[0][j];
					p2[j]=DataNpln.dPoint[1][j];
					p3[j]=DataNpln.dPoint[2][j];
				}
			}
			else if(DataNpln.nPlaneType == 2)
			{
				p1[0]=0., p1[1]=0., p1[2]=DataNpln.dCoor;
				p2[0]=1., p2[1]=0., p2[2]=DataNpln.dCoor;
				p3[0]=0., p3[1]=1., p3[2]=DataNpln.dCoor;
			}
			else if(DataNpln.nPlaneType == 3)
			{
				p1[0]=0., p1[1]=DataNpln.dCoor, p1[2]=0.;
				p2[0]=1., p2[1]=DataNpln.dCoor, p2[2]=0.;
				p3[0]=0., p3[1]=DataNpln.dCoor, p3[2]=1.;
			}
			else if(DataNpln.nPlaneType == 4)
			{
				p1[0]=DataNpln.dCoor, p1[1]=0., p1[2]=0.;
				p2[0]=DataNpln.dCoor, p2[1]=1., p2[2]=0.;
				p3[0]=DataNpln.dCoor, p3[1]=0., p3[2]=1.;
			}
			else
			{
				ASSERT(FALSE);
				return;
			}
			CMathFunc::mathPlaneEquation(p1, p2, p3, PlaneEquation.a, PlaneEquation.b, PlaneEquation.c, PlaneEquation.h);
			PlaneEquation.tol=DataNpln.dTolerance;
			aDataPlane.Add(PlaneEquation);
		}
		else
		{
			ASSERT(FALSE);
			return;
		}
	}

	T_NODE_K KeyNode;
	T_NODE_D DataNode;
	POSITION pos=GetStartNode();
	while(pos != NULL)
	{
		GetNextNode(pos, KeyNode, DataNode);
		for(int i=0; i<nCount; i++)
		{
			double dLength=CMathFunc::mathDistanceToPlane(aDataPlane[i].a, aDataPlane[i].b, aDataPlane[i].c, aDataPlane[i].h, DataNode.x, DataNode.y, DataNode.z);
			if(dLength <= aDataPlane[i].tol)KeyNodeMap.SetAt(KeyNode, KeyNode);
		}
	}

	T_ELEM_K KeyElem;
	T_ELEM_D DataElem;
	if(pKeyElem != NULL)
	{
		pos=GetStartElem();
		while(pos != NULL)
		{
			GetNextElem(pos, KeyElem, DataElem);
			int nNode=GetNumNode(DataElem.eltyp, DataElem.elnod);
			if(nNode == 0)continue;
			int nExist=0;
			for(int i=0; i<nNode; i++)
			{
				if(!KeyNodeMap.Lookup(DataElem.elnod[i], KeyNode))break;
				nExist++;
			}
			if(nExist != nNode)continue;
			KeyElemMap.SetAt(KeyElem, KeyElem);
		}
	}

	if(pKeyNode != NULL)
	{
		int nCount=KeyNodeMap.GetCount();
		if(nCount > 0)
		{
			pKeyNode->SetSize(nCount);
			int nIndex=0;
			pos=KeyNodeMap.GetStartPosition();
			while(pos != NULL)
			{
				KeyNodeMap.GetNextAssoc(pos, KeyNode, KeyNode);
				pKeyNode->SetAt(nIndex, KeyNode);
				nIndex++;
			}
			CQSort::QSortUInt(pKeyNode->GetData(), nCount);
		}
	}
	if(pKeyElem != NULL)
	{
		int nCount=KeyElemMap.GetCount();
		pKeyElem->SetSize(nCount);
		int nIndex=0;
		pos=KeyElemMap.GetStartPosition();
		while(pos != NULL)
		{
			KeyElemMap.GetNextAssoc(pos, KeyElem, KeyElem);
			pKeyElem->SetAt(nIndex, KeyElem);
			nIndex++;
		}
		CQSort::QSortUInt(pKeyElem->GetData(), nCount);
	}
}

