void CAttrCtrl::GetGrupList(CArray<CString, CString&>& rstrGrupList, BOOL bSort)
{
	rstrGrupList.RemoveAll();

	int nCount=GetCountGrup();
	if(nCount == 0)return;

	POSITION pos;
	T_GRUP_K Key;
	T_GRUP_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartGrup();
		while(pos != NULL)
		{
			GetNextGrup(pos, Key, Data);
			if(Data.nGroupId == i)
			{
				rstrGrupList.Add(Data.GroupName);
				break;
			}
		}
	}

	if(bSort) CQSort::QSortString(rstrGrupList.GetData(), rstrGrupList.GetSize());
}

void CAttrCtrl::GetGrupKeyList(CArray<T_GRUP_K, T_GRUP_K>& rGrupKeyList)
{
	/*
	rGrupKeyList.RemoveAll();

	int nCount=GetCountGrup();
	if(nCount == 0)return;

	POSITION pos;
	T_GRUP_K Key;
	T_GRUP_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartGrup();
	while(pos != NULL)
	{
	GetNextGrup(pos, Key, Data);
	if(Data.nGroupId == i)
	{
	rGrupKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rGrupKeyList.RemoveAll();
	int nCount=GetCountGrup();
	if(nCount == 0)return;

	CArray<T_GRUP_K, T_GRUP_K> aGrupKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rGrupKeyList.SetSize(nCount);
	aGrupKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_GRUP_K Key;
	T_GRUP_D Data;
	int i = 0;
	pos = GetStartGrup();
	while (pos != NULL)
	{
		GetNextGrup(pos, Key, Data);
		aGrupKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nGroupId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rGrupKeyList[i] = aGrupKey[ix];
	}
}

