void CAttrCtrl::GetKeyListGrupUser(CArray<T_GRUP_K, T_GRUP_K>* pKeyGrup,
								   CArray<T_NODE_K, T_NODE_K>* pKeyNode, CArray<T_ELEM_K, T_ELEM_K>* pKeyElem)
{
	if(pKeyNode != NULL)pKeyNode->RemoveAll();
	if(pKeyElem != NULL)pKeyElem->RemoveAll();
	if(pKeyNode == NULL && pKeyElem == NULL)return;
	int nCount=pKeyGrup->GetSize();
	if(nCount == 0)return;

	CMap<T_NODE_K, T_NODE_K, T_NODE_K, T_NODE_K>KeyNodeMap;
	KeyNodeMap.InitHashTable(m_pDoc->GetHashSizeNode());
	CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K>KeyElemMap;
	KeyElemMap.InitHashTable(m_pDoc->GetHashSizeElem());

	T_NODE_K KeyNode;
	T_ELEM_K KeyElem;
	POSITION pos;
	T_GRUP_D DataGrup;
	for(int i=0; i<nCount; i++)
	{
		if(GetGrup(pKeyGrup->GetAt(i), DataGrup))
		{
			for(int j=0; j<DataGrup.arKeyNode.GetSize(); j++)
				KeyNodeMap.SetAt(DataGrup.arKeyNode[j], DataGrup.arKeyNode[j]);
			for(int j=0; j<DataGrup.arKeyElem.GetSize(); j++)
				KeyElemMap.SetAt(DataGrup.arKeyElem[j], DataGrup.arKeyElem[j]);
		}
	}

	if(pKeyNode != NULL)
	{
		int nCount=KeyNodeMap.GetCount();
		if(nCount > 0)
		{
			pKeyNode->SetSize(nCount);
			int nIndex=0;
			pos=KeyNodeMap.GetStartPosition();
			while(pos != NULL)
			{
				KeyNodeMap.GetNextAssoc(pos, KeyNode, KeyNode);
				pKeyNode->SetAt(nIndex, KeyNode);
				nIndex++;
			}
			CQSort::QSortUInt(pKeyNode->GetData(), nCount);
		}
	}
	if(pKeyElem != NULL)
	{
		int nCount=KeyElemMap.GetCount();
		pKeyElem->SetSize(nCount);
		int nIndex=0;
		pos=KeyElemMap.GetStartPosition();
		while(pos != NULL)
		{
			KeyElemMap.GetNextAssoc(pos, KeyElem, KeyElem);
			pKeyElem->SetAt(nIndex, KeyElem);
			nIndex++;
		}
		CQSort::QSortUInt(pKeyElem->GetData(), nCount);
	}
}

// Grup은 시공단계에서 Filtering되지 않는다.
// 시공단계에서 Grup의 내용을 Filtering해서 반환해 준다.
// 시공단계에서 Grup에 있는 절점, 요소중 존재하지 않는 것들이 Grup에
// 포함되어 있어서 문제가 되는 경우는 GetGrup4Stage, GetNextGrup4Stage를 호출한다.
BOOL CAttrCtrl::GetGrup4Stage(T_GRUP_K Key, T_GRUP_D& rData)
{
	if (!GetGrup(Key, rData)) return FALSE;
	if (!m_pDoc->m_pStagCtrl->IsBaseStag()) RemoveNodeElemOfGrup(rData);
	return TRUE;
}

void CAttrCtrl::GetNextGrup4Stage(POSITION& rNextPosition,T_GRUP_K& rKey,T_GRUP_D& rData)
{
	GetNextGrup(rNextPosition, rKey, rData);
	if (!m_pDoc->m_pStagCtrl->IsBaseStag()) 
		RemoveNodeElemOfGrup(rData);
}

// Grup에서 현재 상태에서 존재하지 않는 절점, 요소 삭제
// GetGrup4Stage, GetNextGrup4Stage를 위한 함수
void CAttrCtrl::RemoveNodeElemOfGrup(T_GRUP_D& rData)
{
	for (int i = rData.arKeyNode.GetSize()-1; i >= 0; i--)
	{
		if (!ExistNode(rData.arKeyNode[i])) rData.arKeyNode.RemoveAt(i);
	}
	for (int i = rData.arKeyElem.GetSize()-1; i >= 0; i--)
	{
		if (!ExistElem(rData.arKeyElem[i])) rData.arKeyElem.RemoveAt(i);
	}
}

void CAttrCtrl::GetGrupKeyListByElem(T_ELEM_K ElemK, CArray<T_GRUP_K, T_GRUP_K>& aGrupK)
{
	POSITION pos;
	T_GRUP_K Key;
	T_GRUP_D Data;
	int i = 0;
	pos = GetStartGrup();
	while (pos != NULL)
	{
		GetNextGrup(pos, Key, Data);
		for (int i = 0; i < Data.arKeyElem.GetSize(); i++)
		{
			if (Data.arKeyElem[i] == ElemK)
			{
				aGrupK.Add(Key);
				break;
			}
		}
	}
}

