void CAttrCtrl::GetSdomList(CArray<CString, CString&>& rstrSdomList)
{
	rstrSdomList.RemoveAll();

	int nCount=GetCountSdom();
	if(nCount == 0)return;

	POSITION pos;
	T_SDOM_K Key;
	T_SDOM_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartSdom();
		while(pos != NULL)
		{
			GetNextSdom(pos, Key, Data);
			if(Data.nDomainId == i)
			{
				rstrSdomList.Add(Data.strName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetSdomKeyList(CArray<T_SDOM_K, T_SDOM_K>& rSdomKeyList)
{  
	rSdomKeyList.RemoveAll();
	int nCount=GetCountSdom();
	if(nCount == 0)return;

	CArray<T_SDOM_K, T_SDOM_K> aSdomKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rSdomKeyList.SetSize(nCount);
	aSdomKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_SDOM_K Key;
	T_SDOM_D Data;
	int i = 0;
	pos = GetStartSdom();
	while (pos != NULL)
	{
		GetNextSdom(pos, Key, Data);
		aSdomKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nDomainId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rSdomKeyList[i] = aSdomKey[ix];
	}
}

