void CAttrCtrl::GetMadoList(CArray<CString, CString&>& rstrNameList, BOOL bSortByName/*=FALSE*/)
{
	rstrNameList.RemoveAll();

	T_MADO_D Data;
	std::vector<T_MADO_K> KeyList;
	GetMadoKeyList(KeyList, bSortByName);
	int nCount=(int)KeyList.size();
	for(int i=0; i<nCount; i++)
	{
		if(GetMado(KeyList[i], Data))
			rstrNameList.Add(Data.strName);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetMadoKeyList(std::vector<T_MADO_K>& rKeyList, BOOL bSortByName/*=FALSE*/)
{
	rKeyList.clear();
	std::vector<CString> arName;

	int nMado = GetCountMado();
	rKeyList.reserve(nMado);
	arName.reserve(nMado);

	POSITION pos;
	T_MADO_K Key;
	T_MADO_D Data;
	pos=GetStartMado();
	while(pos != NULL)
	{
		GetNextMado(pos, Key, Data);
		rKeyList.push_back(Key);
		arName.push_back(Data.strName);
	}
	if(rKeyList.size() > 0)
	{
		if(bSortByName)
			CQSort::QSortStringWithIndex(rKeyList.data(), arName.data(), rKeyList.size());         
		else 
			CQSort::QSortUInt(rKeyList.data(), rKeyList.size());
	}
}

