int CAttrCtrl::GetElemListMadoK(T_MADO_K MadoK, std::vector<T_ELEM_K>& rElemKeyList, CArray<T_DOEL_K, T_DOEL_K>& rDoelKeyList)
{
	rElemKeyList.clear();

	if(rDoelKeyList.IsEmpty())  GetDoelKeyList(rDoelKeyList);
	int nSize = rDoelKeyList.GetSize();
	rElemKeyList.reserve(nSize*0.25);
	for(int i=0 ; i<nSize ; ++i)
	{
		T_DOEL_D DoelD; DoelD.Initialize();
		if(!GetDoel(rDoelKeyList[i], DoelD)) ASSERT(0);
		if(DoelD.nDomainType == 0 && DoelD.KeyDomain == MadoK)
			rElemKeyList.push_back(rDoelKeyList[i]);    
	}

	CQSort::QSortUInt(rElemKeyList.data(), rElemKeyList.size());

	return (int)rElemKeyList.size();
}

int CAttrCtrl::GetElemListMadoKIncudeSbdo(T_MADO_K MadoK, std::vector<T_ELEM_K>& rElemKeyList, CArray<T_DOEL_K, T_DOEL_K>& rDoelKeyList)
{
	if(rDoelKeyList.IsEmpty())  GetDoelKeyList(rDoelKeyList);

	GetElemListMadoK(MadoK, rElemKeyList, rDoelKeyList);

	int nSbdoSize = rDoelKeyList.GetSize();
	for(int i=0 ; i<nSbdoSize ; ++i)
	{
		T_SBDO_K SbdoK = rDoelKeyList[i];
		T_SBDO_D SbdoD; SbdoD.Initialize();
		if(!GetSbdo(SbdoK, SbdoD)) ASSERT(0);
		if(SbdoD.KeyMado == MadoK)
		{
			int nDoelSize = rDoelKeyList.GetSize();
			for(int j=0 ; j<nDoelSize ; ++j)
			{
				T_DOEL_D DoelD; DoelD.Initialize();
				if(!GetDoel(rDoelKeyList[j], DoelD)) ASSERT(0);
				if(DoelD.nDomainType == 1 && DoelD.KeyDomain == SbdoK)
					rElemKeyList.push_back(rDoelKeyList[j]);    
			}    
		}
	}

	CQSort::QSortUInt(rElemKeyList.data(), rElemKeyList.size());

	return (int)rElemKeyList.size();
}


