////////////// ldgr ////////////////
void CAttrCtrl::GetKeyListLdgrUser(CArray<T_LDGR_K, T_LDGR_K>* pKeyLdgr,
								   CArray<T_NODE_K, T_NODE_K>* pKeyNode, 
								   CArray<T_ELEM_K, T_ELEM_K>* pKeyElem)
{
	ASSERT(pKeyLdgr);
	int nLdgrCount = pKeyLdgr->GetSize();
	CMap<T_NODE_K, T_NODE_K, T_NODE_K, T_NODE_K> mapNode;
	CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K> mapElem;
	if (!pKeyNode && !pKeyElem) return;
	if (pKeyNode) 
	{
		pKeyNode->RemoveAll();
		mapNode.InitHashTable(HASHSIZENODE);
	}
	if (pKeyElem) 
	{
		pKeyElem->RemoveAll();
		mapElem.InitHashTable(HASHSIZEELEM);
	}

	LdgrList* pList;
	POSITION pos;
	T_LIST_DATA ListData;
	for (int i = 0; i < nLdgrCount; i++)
	{
		m_pDataMemb->m_ldgr.GetList(pKeyLdgr->GetAt(i), pList);
		pos = pList->GetHeadPosition();
		while (pos)
		{
			ListData = pList->GetNext(pos);
			switch(ListData.nCmd)
			{
			case LT_BODF_CMD:
				break;
			case LT_NBOF_CMD:
				break;
			case LT_CNLD_CMD:
				{
					if (pKeyNode)
					{
						T_CNLD_K key;
						key.keymap = ListData.nKey;
						mapNode.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_SDSP_CMD:
				{
					if (pKeyNode)
					{
						T_SDSP_K key;
						key.keymap = ListData.nKey;
						mapNode.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_BMLD_CMD:
				{
					if (pKeyElem)
					{
						T_BMLD_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_FMLD_CMD:
				{
					if (pKeyElem)
					{
						T_FMLD_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_FBLA_CMD:
				{
					if (pKeyNode)
					{
						T_FBLA_K key;
						T_FBLA_D data;
						key = ListData.nKey;
						VERIFY(GetFbla(key, data));
						for (int i = 0; i < D_FBLA_MAXNOD; i++)
							if (data.nConnectivity[i] != 0)
								mapNode.SetAt(data.nConnectivity[i], data.nConnectivity[i]);
					}
				}
				break;
			case LT_STBK_CMD:
				{
					if (pKeyNode)
					{
						T_STBK_K key;
						T_STBK_D data;
						key = ListData.nKey;
						VERIFY(GetStbk(key, data));
						if(data.node1!=0 && data.node2!=0)
						{
							mapNode.SetAt(data.node1,data.node1);
							mapNode.SetAt(data.node2,data.node2);
						}
					}
				}
				break;
			case LT_ULCB_CMD:
				{
					if (pKeyElem)
					{
						T_ULCB_K key;
						T_ULCB_D data;
						key = ListData.nKey;
						VERIFY(GetUlcb(key, data));
						mapElem.SetAt(data.ElemKey, data.ElemKey);
					}
				}
				break;
			case LT_PNLA_CMD:
				{
					if (pKeyNode)
					{
						T_PNLA_K key;
						T_PNLA_D data;
						key = ListData.nKey;
						VERIFY(GetPnla(key, data));
						if (data.bLoadingArea)
						{
							for (int i = 0; i < D_PNLA_MAXNOD; i++)
								if (data.nConnectivity[i] != 0)
									mapNode.SetAt(data.nConnectivity[i], data.nConnectivity[i]);
						}
					}
				}
				break;
			case LT_PRST_CMD:
				{
					if (pKeyElem)
					{
						T_PRST_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_PTNS_CMD:
				{
					if (pKeyElem)
					{
						T_PTNS_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_PRES_CMD:
				{
					if (pKeyElem)
					{
						T_PRES_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_STMP_CMD:
				break;
			case LT_NTMP_CMD:
				{
					if (pKeyNode)
					{
						T_NTMP_K key;
						key.keymap = ListData.nKey;
						mapNode.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_ETMP_CMD:
				{
					if (pKeyElem)
					{
						T_ETMP_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_BTMP_CMD:
				{
					if (pKeyElem)
					{
						T_BTMP_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_PTMP_CMD:
				{
					if (pKeyElem)
					{
						T_PTMP_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_GTMP_CMD:
				{
					if (pKeyElem)
					{
						T_GTMP_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_TDPL_CMD:
				break;
			case LT_STAG_CMD:
				break;
			case LT_TMLD_CMD:
				{
					if (pKeyElem)
					{
						T_TMLD_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			case LT_CRPC_CMD:
				{
					if (pKeyElem)
					{
						T_CRPC_K key;
						key.keymap = ListData.nKey;
						mapElem.SetAt(key.key.entity, key.key.entity);
					}
				}
				break;
			default: ASSERT(0); break;
			}
		}
	}

	if (pKeyNode) 
	{
		T_NODE_K key;
		int i = 0;
		int nCount = mapNode.GetCount();
		pKeyNode->SetSize(nCount);
		POSITION pos = mapNode.GetStartPosition();
		while (pos)
		{
			mapNode.GetNextAssoc(pos, key, key);
			pKeyNode->SetAt(i++, key);
		}
		qsort(pKeyNode->GetData(), nCount, sizeof(T_NODE_K), CCompFunc::UINTAsc);
	}
	if (pKeyElem) 
	{
		T_ELEM_K key;
		int i = 0;
		int nCount = mapElem.GetCount();
		pKeyElem->SetSize(nCount);
		POSITION pos = mapElem.GetStartPosition();
		while (pos)
		{
			mapElem.GetNextAssoc(pos, key, key);
			pKeyElem->SetAt(i++, key);
		}
		qsort(pKeyElem->GetData(), nCount, sizeof(T_ELEM_K), CCompFunc::UINTAsc);
	}
}

void CAttrCtrl::GetLdgrList(CArray<CString, CString&>& rstrLdgrList)
{
	rstrLdgrList.RemoveAll();

	int nCount=GetCountLdgr();
	if(nCount == 0)return;

	POSITION pos;
	T_LDGR_K Key;
	T_LDGR_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartLdgr();
		while(pos != NULL)
		{
			GetNextLdgr(pos, Key, Data);
			if(Data.nGroupId == i)
			{
				rstrLdgrList.Add(Data.GroupName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetLdgrKeyList(CArray<T_LDGR_K, T_LDGR_K>& rLdgrKeyList)
{
	/*
	rLdgrKeyList.RemoveAll();

	int nCount=GetCountLdgr();
	if(nCount == 0)return;

	POSITION pos;
	T_LDGR_K Key;
	T_LDGR_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartLdgr();
	while(pos != NULL)
	{
	GetNextLdgr(pos, Key, Data);
	if(Data.nGroupId == i)
	{
	rLdgrKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rLdgrKeyList.RemoveAll();
	int nCount=GetCountLdgr();
	if(nCount == 0)return;

	CArray<T_LDGR_K, T_LDGR_K> aLdgrKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rLdgrKeyList.SetSize(nCount);
	aLdgrKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_LDGR_K Key;
	T_LDGR_D Data;
	int i = 0;
	pos = GetStartLdgr();
	while (pos != NULL)
	{
		GetNextLdgr(pos, Key, Data);
		aLdgrKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nGroupId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rLdgrKeyList[i] = aLdgrKey[ix];
	}
}

