BOOL CAttrCtrl::GetLdgr(CString& rGroupName, T_LDGR_D& rData)
{
	T_LDGR_K key;
	T_LDGR_D data;
	CString strGroupName=rGroupName;
	strGroupName.TrimRight();

	POSITION pos;
	pos=m_pDataMemb->m_ldgr.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_ldgr.GetNext(pos,key,data);
		if(strGroupName.CompareNoCase(data.GroupName) == 0)
		{
			m_pUnitCtrl->ConvertUnitLdgrOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

