T_LDGR_K CAttrCtrl::GetLdgrKey(CString& rGroupName)
{
#ifdef _RUS
	rGroupName.TrimRight();
#endif

	T_LDGR_K key;
	T_LDGR_D data;

	POSITION pos=GetStartLdgr();
	while(pos != NULL)
	{
		GetNextLdgr(pos,key,data);
		if(rGroupName.CompareNoCase(data.GroupName) == 0)return key;
		else
		{
#ifdef _RUS
			// 러시아 언어에서..CompareNoCase 로 안되는 것이 있어서..
			int nLength = rGroupName.GetLength();
			int nDataLength = data.GroupName.GetLength();
			if(nLength == nDataLength)
			{
				BOOL bSame = TRUE;
				for (int i=0; i<nLength; i++)
				{
					if(rGroupName.GetAt(i) != data.GroupName.GetAt(i)) 
					{
						bSame = FALSE;
						break;
					}
				}
				if(bSame) return key;
			}
#endif
		}
	}
	key=0;
	return key;
}

