void CAttrCtrl::GetLdgrHavingFloorOrPlaneLoad(CMapEx<UINT, UINT, int, int>& rmLdgrK)
{
	rmLdgrK.RemoveAll();

	// Plane Load, Floor Load 몇개 안되므로 이거를 Loop돌면서 찾자
	POSITION pos = GetStartPnla();
	T_PNLA_K PnlaK;
	T_PNLA_D PnlaD;
	while (pos)
	{
		GetNextPnla(pos, PnlaK, PnlaD);
		rmLdgrK.SetAt(PnlaD.GroupKey, 0);
	}

	pos = GetStartFbla();
	T_FBLA_K FblaK;
	T_FBLA_D FblaD;
	while (pos)
	{
		GetNextFbla(pos, FblaK, FblaD);
		rmLdgrK.SetAt(FblaD.GroupKey, 0);
	}
}

void CAttrCtrl::GetLdgrDeactivatedInStag(CMapEx<UINT, UINT, int, int>& rmLdgrK)
{
	rmLdgrK.RemoveAll();
	POSITION pos = GetStartStag();
	T_STAG_K StagK;
	T_STAG_D StagD;
	while (pos)
	{
		GetNextStag(pos, StagK, StagD);
		for (int i = 0; i < StagD.aDeactiveLoad.GetSize(); i++)
			rmLdgrK.SetAt(StagD.aDeactiveLoad[i].LdgrKey, 0);
	}
}


