BOOL CAttrCtrl::GetSerialOffs(T_ELEM_K KeyElem, T_BNGR_K KeyBngr,T_OFFS_KEY& rKeySerial)
{
	ElemList* pList;
	if(!m_pDataMemb->m_elem.GetListFromBaseDB(KeyElem, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_OFFS_CMD)
		{
			T_OFFS_K key;
			T_OFFS_D data;
			key.keymap=ListData.nKey;
			m_pDataMemb->m_offs.GetFromBaseDB(key, data);
			if(data.GroupKey == KeyBngr)
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_OFFS_K key;
	T_OFFS_D data;
	key.key.entity=KeyElem;
	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_offs.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeKeyOffs(T_ELEM_K KeyElem, T_BNGR_K KeyBngr,T_OFFS_K& rKey)
{
	rKey.key.entity=KeyElem;
	rKey.key.serial=0;

	T_OFFS_KEY KeySerial;
	if(!GetSerialOffs(KeyElem, KeyBngr, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

void CAttrCtrl::GetOffsKeyList(CArray<T_OFFS_K, T_OFFS_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_OFFS_K Key;
	T_OFFS_D Data;
	pos=GetStartOffs();
	while(pos != NULL)
	{
		GetNextOffs(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetOffsElemKeyList(CArray<T_ELEM_K, T_ELEM_K>& rElemKeyList)
{
	rElemKeyList.RemoveAll();
	CArray<T_OFFS_K, T_OFFS_K> aOffsKeyList;
	GetOffsKeyList(aOffsKeyList);
	int nNum = aOffsKeyList.GetSize();
	if (nNum == 0) return;
	rElemKeyList.Add(aOffsKeyList[0].key.entity);
	for (int i = 1; i < nNum; i++)
	{
		if (aOffsKeyList[i].key.entity == aOffsKeyList[i-1].key.entity)
			continue;
		rElemKeyList.Add(aOffsKeyList[i].key.entity);
	}
}

