void CAttrCtrl::GetOffsElem(T_ELEM_K KeyElem, CArray<T_OFFS_K, T_OFFS_K>& rKeyList, CArray<T_OFFS_D, T_OFFS_D&>& rDataList)
{
	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_OFFS_CMD)
		{
			T_OFFS_K key;
			T_OFFS_D data;
			key.keymap=ListData.nKey;
			GetOffs(key, data);
			rKeyList.Add(key);
			rDataList.Add(data);
		}
	}
}

BOOL CAttrCtrl::GetOffsElem(T_ELEM_K KeyElem, T_OFFS_D& rData)
{
	CArray<T_OFFS_K, T_OFFS_K> aKey;
	CArray<T_OFFS_D, T_OFFS_D&> aData;
	GetOffsElem(KeyElem, aKey, aData);
	int nNum = aData.GetSize();
	if (nNum == 0) return FALSE;
	rData.Initialize();
	for (int i = 0; i < nNum; i++)
	{
		rData.nOffsetType = aData[i].nOffsetType;
		for (int j = 0; j < 6; j++)
			rData.Offset[j] += aData[i].Offset[j];
	}
	return TRUE;
}

BOOL CAttrCtrl::GetOffsBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, T_ELEM_K KeyElem, T_OFFS_D& rData)
{
	if (bAllGroup) return GetOffsElem(KeyElem, rData);

	int nBngrKeyNum = raKeyBngr.GetSize();
	if (nBngrKeyNum == 0) return FALSE;
	CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
	mapBngrKey.InitHashTable(HASHSIZEBNGR);
	for (int i = 0; i < nBngrKeyNum; i++)
		mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

	CChangeBaseStageAndRecoverOnReturn SetStage(m_pDoc->m_pStagCtrl);
	ElemList* pList;
	if(!m_pDataMemb->m_elem.GetList(KeyElem, pList))return FALSE;

	rData.Initialize();
	T_OFFS_K KeyOffs;
	T_OFFS_D DataOffs;
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_OFFS_CMD)
		{
			KeyOffs.keymap = ListData.nKey;
			if (KeyOffs.key.entity == KeyElem)
			{
				GetOffs(KeyOffs, DataOffs);
				if (mapBngrKey.Lookup(DataOffs.GroupKey, DataOffs.GroupKey))
				{
					rData.nOffsetType = DataOffs.nOffsetType;
					for (int j = 0; j < 6; j++)
						rData.Offset[j] += DataOffs.Offset[j];
				}
			}
		}
	}
	for(int i = 0; i < 6; i++)
		if (rData.Offset[i] != 0.0) return TRUE;
	return FALSE;
}

