////////////// cons ////////////////
BOOL CAttrCtrl::GetSerialCons(T_NODE_K KeyNode, T_BNGR_K KeyBngr,T_CONS_KEY& rKeySerial)
{
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetListFromBaseDB(KeyNode, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_CONS_CMD)
		{
			T_CONS_K key;
			T_CONS_D data;
			key.keymap=ListData.nKey;
			m_pDataMemb->m_cons.GetFromBaseDB(key, data);
			if(data.GroupKey == KeyBngr)
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_CONS_K key;
	T_CONS_D data;
	key.key.entity=KeyNode;
	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_cons.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeKeyCons(T_NODE_K KeyNode, T_BNGR_K KeyBngr,T_CONS_K& rKey)
{
	rKey.key.entity=KeyNode;
	rKey.key.serial=0;

	T_CONS_KEY KeySerial;
	if(!GetSerialCons(KeyNode, KeyBngr, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

void CAttrCtrl::GetConsKeyList(CArray<T_CONS_K, T_CONS_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_CONS_K Key;
	T_CONS_D Data;
	pos=GetStartCons();
	while(pos != NULL)
	{
		GetNextCons(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetConsNodeKeyList(CArray<T_NODE_K, T_NODE_K>& rNodeKeyList)
{
	rNodeKeyList.RemoveAll();
	CArray<T_CONS_K, T_CONS_K> aConsKeyList;
	GetConsKeyList(aConsKeyList);
	int nNum = aConsKeyList.GetSize();
	if (nNum == 0) return;
	rNodeKeyList.Add(aConsKeyList[0].key.entity);
	for (int i = 1; i < nNum; i++)
	{
		if (aConsKeyList[i].key.entity == aConsKeyList[i-1].key.entity)
			continue;
		rNodeKeyList.Add(aConsKeyList[i].key.entity);
	}
}

