BOOL CAttrCtrl::GetConsNode(T_NODE_K KeyNode, T_CONS_D& rData)
{
	CArray<T_CONS_K, T_CONS_K> aKey;
	CArray<T_CONS_D, T_CONS_D&> aData;
	GetConsNode(KeyNode, aKey, aData);
	int nNum = aData.GetSize();
	if (nNum == 0) return FALSE;
	rData.Initialize();
	for (int i = 0; i < nNum; i++)
	{
		for (int j = 0; j < 7; j++)		// NX에서 Support 레이블에 Rw를 표현해주기 위해서
			if (aData[i].Constraint[j] == '1') rData.Constraint[j] = '1';
	}
	return TRUE;
}

// Group별 출력은 시공단계인 경우도 Base DB에서 가져와서 
// 절점/요소의 존재 유무 판단해서 Labeling한다.(하중조건별 경계조건기능)
BOOL CAttrCtrl::GetConsBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, T_NODE_K KeyNode, T_CONS_D& rData)
{
	if (bAllGroup) return GetConsNode(KeyNode, rData);

	int nBngrKeyNum = raKeyBngr.GetSize();
	if (nBngrKeyNum == 0) return FALSE;
	CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
	mapBngrKey.InitHashTable(HASHSIZEBNGR);
	for (int i = 0; i < nBngrKeyNum; i++)
		mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

	CChangeBaseStageAndRecoverOnReturn SetStage(m_pDoc->m_pStagCtrl);
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetList(KeyNode, pList)) return FALSE;

	rData.Initialize();
	T_CONS_K KeyCons;
	T_CONS_D DataCons;
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_CONS_CMD)
		{
			KeyCons.keymap = ListData.nKey;
			if (KeyCons.key.entity == KeyNode)
			{
				GetCons(KeyCons, DataCons);
				if (mapBngrKey.Lookup(DataCons.GroupKey, DataCons.GroupKey))
				{
					for (int j = 0; j < 7; j++)		// NX에서 Support 레이블에 Rw를 표현해주기 위해서
						if (DataCons.Constraint[j] == '1') rData.Constraint[j] = '1';
				}
			}
		}
	}
	for(int i = 0; i < 7; i++)		// NX에서 Support 레이블에 Rw를 표현해주기 위해서
		if (rData.Constraint[i] == '1') return TRUE;
	return FALSE;
}

