void CAttrCtrl::GetConstraintCondition(T_NODE_K KeyNode, T_CONS_D& rData)
{
	if(!GetConsNode(KeyNode, rData))rData.Initialize();

	// 0:3-D  1:X-Z Plane  2: Y-Z Plane  3: X-Y Plane  4:XYZRXRY
	switch(m_pDoc->m_Styp.nStructureType)
	{
	case(0):
		break;
	case(1)://DYRXRZ 구속
		rData.Constraint[1]='1';
		rData.Constraint[3]='1';
		rData.Constraint[5]='1';
		break;
	case(2)://DXRYRZ 구속
		rData.Constraint[0]='1';
		rData.Constraint[4]='1';
		rData.Constraint[5]='1';
		break;
	case(3)://DZRXRY 구속
		rData.Constraint[2]='1';
		rData.Constraint[3]='1';
		rData.Constraint[4]='1';
		break;
	case(4)://RZ 구속
		rData.Constraint[5]='1';
		break;
	default:
		ASSERT(FALSE);
		break;
	}
}

