void CAttrCtrl::GetNsprNode(T_NODE_K KeyNode, CArray<T_NSPR_K, T_NSPR_K>& rKeyList, CArray<T_NSPR_D, T_NSPR_D&>& rDataList)
{
	auto _L_CompareNsprKey = [] (std::pair<unsigned int, unsigned int>& Key1, std::pair<unsigned int, unsigned int>& Key2)
	{
		// 1순위 : entity, 2순위 : serial
		if ( Key1.first < Key2.first ) return true;
		if ( Key1.first > Key2.first ) return false;
				 
		if ( Key1.second < Key2.second ) return true;
		if ( Key1.second > Key2.second ) return false;

		return false;
	};

	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_NSPR_CMD)
		{
			T_NSPR_K key;
			T_NSPR_D data;
			key.keymap=ListData.nKey;
			GetNspr(key, data);
			rKeyList.Add(key);
			rDataList.Add(data);
		}
	}

	std::vector<std::pair<unsigned int, unsigned int>> vKeyList;
	for ( int i = 0; i < rKeyList.GetSize(); i++ )
	{
		const auto entity = rKeyList[i].key.entity;
		const auto serial = rKeyList[i].key.serial;
		vKeyList.push_back(std::make_pair(entity, serial));
	}

	std::sort(vKeyList.begin(), vKeyList.end(), _L_CompareNsprKey);

	rKeyList.RemoveAll();
	CArray<T_NSPR_D, T_NSPR_D&> rSortedDataList;
	for ( int i = 0; i < vKeyList.size(); i++ )
	{
		T_NSPR_K key;
		T_NSPR_D data;
		key.key.entity = vKeyList[i].first;
		key.key.serial = vKeyList[i].second;
		GetNspr(key, data);
		rKeyList.Add(key);
		rSortedDataList.Add(data);
	}

	rDataList.RemoveAll();
	rDataList.Copy(rSortedDataList);
}

