BOOL CAttrCtrl::GetNsprDrawNode(T_NODE_K KeyNode, T_NSPR_D& rData,int nType)
{
	CArray<T_NSPR_K, T_NSPR_K> aKey;
	CArray<T_NSPR_D, T_NSPR_D&> aData;
	GetNsprNode(KeyNode, aKey, aData);
	int nNum = aData.GetSize();
	if (nNum == 0) return FALSE;

	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	rData.Initialize();
	for (int i = 0; i < nNum; i++)
	{
		T_NSPR_D DataNspr;
		DataNspr = aData[i];
		if(nType == 0)
		{
			if(DataNspr.nGenCompTen == 0)
			{
				if(DataNspr.bDamping)
				{
					rData.bDamping = TRUE;
					for (int j = 0; j < 6; j++)
					{
						if(fabs(DataNspr.dDamping[j]) > zero)
							rData.dDamping[j] = 1.0;  // MNET:XXXX-JWKWON-20140214
					}
				}
				for (int j = 0; j < 6; j++)
				{
					if(DataNspr.bFixed[j])
					{
						rData.Spring[j] = 1.0;
					}
					else
					{
						if(DataNspr.Spring[j] != 0.0)
							rData.Spring[j] = 1.0;
					}
				}
			}
		}
		else if(nType == 1)
		{
			if(DataNspr.nGenCompTen == 1 || DataNspr.nGenCompTen == 2)
			{
				if(DataNspr.dStiffness != 0)
				{
					if(DataNspr.nDirection == 6)
					{
						if(fabs(DataNspr.dVx)>zero) rData.Spring[0] = 1.0;
						if(fabs(DataNspr.dVy)>zero) rData.Spring[1] = 1.0;
						if(fabs(DataNspr.dVz)>zero) rData.Spring[2] = 1.0;
					}
					else
					{
						rData.Spring[int(DataNspr.nDirection / 2)] = 1.0;
					}
				}
			}
		}
		else if(nType == 2)
		{
			if(DataNspr.nGenCompTen == 3)
			{

				if(DataNspr.nDirection == 6)
				{
					if(fabs(DataNspr.dVx)>zero) rData.Spring[0] = 1.0;
					if(fabs(DataNspr.dVy)>zero) rData.Spring[1] = 1.0;
					if(fabs(DataNspr.dVz)>zero) rData.Spring[2] = 1.0;
				}
				else
				{
					rData.Spring[int(DataNspr.nDirection / 2)] = 1.0;
				}
			}
		}
		/*

		for (int j = 0; j < 6; j++)
		rData.Spring[j] += aData[i].Spring[j];
		*/
	}

	if(rData.bDamping)
	{
		for(int i = 0; i < 6; i++)
			if (rData.Spring[i] != 0.0 || rData.dDamping[i]) return TRUE;
	}
	else
	{
		for(int i = 0; i < 6; i++)
			if (rData.Spring[i] != 0.0) return TRUE;
	}
	return FALSE;
}
BOOL CAttrCtrl::GetNsprDrawBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, T_NODE_K KeyNode, T_NSPR_D& rData, int nType)
{
	if (bAllGroup) return GetNsprDrawNode(KeyNode, rData,nType);

	int nBngrKeyNum = raKeyBngr.GetSize();
	if (nBngrKeyNum == 0) return FALSE;
	CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
	mapBngrKey.InitHashTable(HASHSIZEBNGR);
	for (int i = 0; i < nBngrKeyNum; i++)
		mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

	CChangeBaseStageAndRecoverOnReturn SetStage(m_pDoc->m_pStagCtrl);
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetList(KeyNode, pList))return FALSE;

	rData.Initialize();
	T_NSPR_K KeyNspr;
	T_NSPR_D DataNspr;
	T_LIST_DATA ListData;

	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	const double zero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();
	//if (fabs(something))<=zero);

	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_NSPR_CMD)
		{
			KeyNspr.keymap = ListData.nKey;
			if (KeyNspr.key.entity == KeyNode)
			{
				GetNspr(KeyNspr, DataNspr);
				if (mapBngrKey.Lookup(DataNspr.GroupKey, DataNspr.GroupKey))
				{
					if(nType == 0)
					{
						// MNET:XXXX-JWKWON-20140214 : Damping 추가되면서 레이블도 다른 색상으로 그림..
						if(DataNspr.bDamping)
						{
							rData.bDamping = TRUE;
							for (int j = 0; j < 6; j++)
							{
								if(fabs(DataNspr.dDamping[j]) > zero)
									rData.dDamping[j] = 1.0;  // MNET:XXXX-JWKWON-20140214
							}
						}
						if(DataNspr.nGenCompTen == 0)
						{
							for (int j = 0; j < 6; j++)
							{
								if(DataNspr.bFixed[j]) 
								{
									rData.Spring[j] = 1.0;
								}
								else
								{
									if(fabs(DataNspr.Spring[j]) > zero )
										rData.Spring[j] = 1.0;
								}
							}
						}
					}
					else if(nType == 1)
					{
						if(DataNspr.nGenCompTen == 1 || DataNspr.nGenCompTen == 2)
						{
							if(DataNspr.dStiffness != 0)
							{
								if(DataNspr.nDirection == 6)
								{
									if(fabs(DataNspr.dVx) > zero ) rData.Spring[0] = 1.0;
									if(fabs(DataNspr.dVy) > zero ) rData.Spring[1] = 1.0;
									if(fabs(DataNspr.dVz) > zero ) rData.Spring[2] = 1.0;
								}
								else
								{
									rData.Spring[int(DataNspr.nDirection / 2)] = 1.0;
								}
							}
						}
					}
					else if(nType == 2)
					{
						if(DataNspr.nGenCompTen == 3)
						{              
							if(DataNspr.nDirection == 6)
							{
								if(fabs(DataNspr.dVx) > zero ) rData.Spring[0] = 1.0;
								if(fabs(DataNspr.dVy) > zero ) rData.Spring[1] = 1.0;
								if(fabs(DataNspr.dVz) > zero ) rData.Spring[2] = 1.0;
							}
							else
							{
								rData.Spring[int(DataNspr.nDirection / 2)] = 1.0;
							}
						}
					}

				}
			}
		}
	}

	if(rData.bDamping)
	{
		for(int i = 0; i < 6; i++)
			if (rData.Spring[i] != 0.0 || rData.dDamping[i] != 0.0) return TRUE;
	}
	else
	{
		for(int i = 0; i < 6; i++)
			if (rData.Spring[i] != 0.0) return TRUE;
	}

	return FALSE;
}
