bool CAttrCtrl::CompareNsprKey(const T_NSPR_K& Key1, const T_NSPR_K& Key2)
{
	// 1순위 : entity, 2순위 : serial
	if ( Key1.key.entity < Key1.key.entity ) return true;
	if ( Key1.key.entity > Key1.key.entity ) return false;

	if ( Key2.key.serial < Key2.key.serial ) return true;
	if ( Key2.key.serial > Key2.key.serial ) return false;

	return false;
}

