T_MLFC_K CAttrCtrl::GetMlfcByData(const T_MLFC_DT& arFuncData)
{
	T_MLFC_K key;
	T_MLFC_D data;

	POSITION pos = GetStartMlfc();
	while (pos != NULL)
	{
		GetNextMlfc(pos, key, data);
		if (data.arFuncData.GetSize() == arFuncData.GetSize())
		{
			BOOL bMask = TRUE;
			for (int i = 0; i < arFuncData.GetSize(); i++)
			{
				if (fabs(data.arFuncData[i].dValueX - arFuncData[i].dValueX) > 1e-7 || fabs(data.arFuncData[i].dValueY - arFuncData[i].dValueY) > 1e-7)
				{
					bMask = FALSE;
					break;
				}
			}
			if (bMask)
				return key;
		}
		
	}
	key = 0;
	return key;
}

