// Function to interpolate x values when duplicates are found
void CAttrCtrl::interpolateDuplicates(CArray<T_MLFC_BASE, T_MLFC_BASE&>& aFuncDataOri)
{
	for (int i = 1; i < aFuncDataOri.GetSize(); ++i)
	{
		// Check for duplicates
		if (aFuncDataOri[i].dValueX == aFuncDataOri[i - 1].dValueX)
		{
			double leftX = aFuncDataOri[i - 1].dValueX;
			int endIdx = i;

			// Find the end of the duplicate sequence
			while (endIdx < aFuncDataOri.GetSize() && aFuncDataOri[endIdx].dValueX == leftX) {
				++endIdx;
			}

			double rightX = (endIdx < aFuncDataOri.GetSize()) ? aFuncDataOri[endIdx].dValueX : leftX;
			int duplicateCount = endIdx - i + 1;

			// Interpolate values for all duplicates, including the last one if necessary
			for (int j = i; j < endIdx; ++j)
			{
				aFuncDataOri[j].dValueX = leftX + (rightX - leftX) * (j - i + 1) / duplicateCount;
			}

			i = endIdx - 1; // Skip to the last modified index
		}
	}
}

