BOOL CAttrCtrl::GetAssignedNodeSsps(T_SSPS_K SspsK, CArray<T_NODE_K, T_NODE_K>& aTmpNode)
{
	aTmpNode.RemoveAll();

	T_ELEM_D ElemData; ElemData.Initialize();
	if(!GetElem(SspsK.key.entity, ElemData)) return FALSE;

	T_SSPS_D SspsD; SspsD.Initialize();
	if(!GetSsps(SspsK, SspsD)) return FALSE;
	const int nElementType = SspsD.nElementType;
	const int nEdgeFace  = SspsD.nEdgeFace;

	const int Solid4Node[4][4] = { 0, 2, 1,-1,  0, 1, 3,-1,  1, 2, 3,-1,  2, 0, 3,-1};
	const int Solid6Node[5][4] = { 0, 2, 1,-1,  3, 4, 5,-1,  0, 1, 4, 3,  1, 2, 5, 4,  2, 0, 3, 5};
//	const int Solid8Node[6][4] = { 0, 3, 2, 1,  4, 5, 6, 7,  0, 1, 5, 4,  1, 2, 6, 5,  2, 3, 7, 6,  3, 0, 4, 7};
	const int Solid8Node[6][4] = { 0, 1, 2, 3,  4, 7, 6, 5,  0, 4, 5, 1,  1, 5, 6, 2,  2, 6, 7, 3,  3, 7, 4, 0 };  //변경 : CIVIL-3252

	const int Planar3Edge[3][2] = { 0, 1,  1, 2,  2, 0 };
	const int Planar4Edge[4][2] = { 0, 1,  1, 2,  2, 3,  3, 0 };

	if (nElementType !=0 && nElementType !=1 && nElementType !=2 && nElementType !=3 ) return FALSE;

	int nNode = GetNumNode(ElemData.eltyp, ElemData.elnod);
	if (nElementType == 0) // Frame
	{
		for(int i=0; i<nNode; i++) aTmpNode.Add(ElemData.elnod[i]);
	}
	else if (nElementType == 1) // Planar(Face)
	{
		for(int i=0; i<nNode; i++) aTmpNode.Add(ElemData.elnod[i]);
	}
	else if (nElementType == 2) // Planar(Edge)
	{
		int np = 2;
		int Node[2] = { 0, 0 };
		for (int i=0; i<np; i++)
		{
			if(nNode == 3) Node[i] = ElemData.elnod[Planar3Edge[nEdgeFace][i]];
			if(nNode == 4) Node[i] = ElemData.elnod[Planar4Edge[nEdgeFace][i]];
		}
		for (int i=0; i<np; i++) aTmpNode.Add(Node[i]);
	}
	else // Solid(Face)
	{
		int np = 4;
		int Node[4] = { 0, 0, 0, 0 };

		for (int i=0; i<np; i++)
		{
			if(nNode == 4) Node[i] = ElemData.elnod[Solid4Node[nEdgeFace][i]];
			if(nNode == 6) Node[i] = ElemData.elnod[Solid6Node[nEdgeFace][i]];
			if(nNode == 8) Node[i] = ElemData.elnod[Solid8Node[nEdgeFace][i]];
		}
		if(nNode == 4 && Solid4Node[nEdgeFace][3]==-1) np=3;
		if(nNode == 6 && Solid6Node[nEdgeFace][3]==-1) np=3;

		for(int i = 0; i<np; i++) aTmpNode.Add(Node[i]);
	}
	return TRUE;
}

