BOOL CAttrCtrl::GetGstp(CString& rSpringTypeName, T_GSTP_D& rData)
{
	T_GSTP_K key;
	T_GSTP_D data;
	CString strSpringTypeName=rSpringTypeName;
	strSpringTypeName.TrimRight();

	POSITION pos=m_pDataMemb->m_gstp.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_gstp.GetNext(pos,key,data);
		if(strSpringTypeName.CompareNoCase(data.TypeName) == 0)
		{
			m_pUnitCtrl->ConvertUnitGstpOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetGstp(T_GSTP_K Key, T_GSTP_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_gstp.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitGstpOut(rData);
	return bReturn;
}

T_GSTP_K CAttrCtrl::GetGstpKey(CString& rSpringTypeName)
{
	T_GSTP_K key;
	T_GSTP_D data;

	POSITION pos=GetStartGstp();
	while(pos != NULL)
	{
		GetNextGstp(pos,key,data);
		if(rSpringTypeName.CompareNoCase(data.TypeName) == 0)return key;
	}
	key=0;
	return key;
}

