////////////// dmgb ////////////////

void CAttrCtrl::GetDmgbList(CArray<CString, CString&>& rstrDmgbList)
{
	rstrDmgbList.RemoveAll();

	int nCount = GetCountDmgb();
	if (nCount == 0)return;

	T_DMGB_K Key;
	T_DMGB_D Data;
	for (int i = 1; i <= nCount; i++)
	{
		if (!GetDmgbSeq(i, Key)) { ASSERT(0); return; }
		if (!GetDmgb(Key, Data)) { ASSERT(0); return; }

		rstrDmgbList.Add(Data.PropName);
	}
}

void CAttrCtrl::GetDmgbKeyList(CArray<T_DMGB_K, T_DMGB_K>& rKeyList)
{
	rKeyList.RemoveAll();
	POSITION pos;
	T_DMGB_K Key;
	T_DMGB_D Data;
	pos = GetStartDmgb();
	while (pos != NULL)
	{
		GetNextDmgb(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if (rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetDmgbOildKeyList(CArray<T_DMGB_K, T_DMGB_K>& rKeyList)
{
	rKeyList.RemoveAll();
	POSITION pos;
	T_DMGB_K Key;
	T_DMGB_D Data;
	pos = GetStartDmgb();
	while (pos != NULL)
	{
		GetNextDmgb(pos, Key, Data);
		if (Data.nPropType == 3 || Data.nPropType == 5)
			rKeyList.Add(Key);
	}
	if (rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}
void CAttrCtrl::GetDmgbStldKeyList(CArray<T_DMGB_K, T_DMGB_K>& rKeyList)
{
	rKeyList.RemoveAll();
	POSITION pos;
	T_DMGB_K Key;
	T_DMGB_D Data;
	pos = GetStartDmgb();
	while (pos != NULL)
	{
		GetNextDmgb(pos, Key, Data);
		if (Data.nPropType != 3 && Data.nPropType != 5)
			rKeyList.Add(Key);
	}
	if (rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

