int CAttrCtrl::GetDmgbOildSerialNum(T_DMGB_K DmgbK) // Dmgb중 번호순으로 몇번째인가?
{
	CArray<T_DMGB_K, T_DMGB_K> aDmgbK;
	GetDmgbOildKeyList(aDmgbK);
	for (int i = 0; i < aDmgbK.GetSize(); i++)
	{
		if (DmgbK == aDmgbK[i]) return i + 1;
	}

	ASSERT(0);
	return 0;
}

