	DmgbD.FD.dDisp = CUnitCtrl::ConvValueTgtUnit2CurUnit(D_UNITSYS_FORCE_INDEX_N, D_UNITSYS_LENGTH_INDEX_MM, CUnitCtrl::m_DMGB_UNIT.dDisp, 1.0);
	DmgbD.FD.dInitStiff = CUnitCtrl::ConvValueTgtUnit2CurUnit(D_UNITSYS_FORCE_INDEX_N, D_UNITSYS_LENGTH_INDEX_MM, CUnitCtrl::m_DMGB_UNIT.dInitStiff, 1.0);
	
	DmgbD.VFD.dDamperF = CUnitCtrl::ConvValueTgtUnit2CurUnit(D_UNITSYS_FORCE_INDEX_N, D_UNITSYS_LENGTH_INDEX_MM, CUnitCtrl::m_DMGB_UNIT.dDamperF, 1.0);
