	DmgbD.VFD.dDisp = CUnitCtrl::ConvValueTgtUnit2CurUnit(D_UNITSYS_FORCE_INDEX_N, D_UNITSYS_LENGTH_INDEX_MM, CUnitCtrl::m_DMGB_UNIT.dDisp, 1.0);

	DmgbD.HDRD.dFy = CUnitCtrl::ConvValueTgtUnit2CurUnit(D_UNITSYS_FORCE_INDEX_N, D_UNITSYS_LENGTH_INDEX_MM, CUnitCtrl::m_DMGB_UNIT.dFy, 1.0);
