BOOL CAttrCtrl::IsUserDMGB(T_DMGB_K DmgbK)
{
	T_NLNK_D NlnkD;
	T_NLLP_D NllpD;
	T_DMGB_D DmgbD;

	T_KEY_LIST lstNlnk;
	m_pDoc->m_pAttrCtrl->GetNlnkKeyList(lstNlnk);
	
	for (int i=0; i<lstNlnk.GetCount(); i++)
	{
		NlnkD.Initialize();
		m_pDoc->m_pAttrCtrl->GetNlnk(lstNlnk[i], NlnkD);
		NllpD.Initialize();
		m_pDoc->m_pAttrCtrl->GetNllp(NlnkD.PropKey, NllpD);
		if (NllpD.nApplicationType != 2 || NllpD.nSeisType != 6)
			continue;
		if (DmgbK == NllpD.nSeisKey)
			return TRUE;
	}
	return FALSE;
}

