////////////// gspr ////////////////
BOOL CAttrCtrl::GetSerialGspr(T_NODE_K KeyNode, T_BNGR_K KeyBngr,T_GSPR_KEY& rKeySerial)
{
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetListFromBaseDB(KeyNode, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_GSPR_CMD)
		{
			T_GSPR_K key;
			T_GSPR_D data;
			key.keymap=ListData.nKey;
			m_pDataMemb->m_gspr.GetFromBaseDB(key, data);
			if(data.GroupKey == KeyBngr)
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_GSPR_K key;
	T_GSPR_D data;
	key.key.entity=KeyNode;
	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_gspr.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeKeyGspr(T_NODE_K KeyNode, T_BNGR_K KeyBngr,T_GSPR_K& rKey)
{
	rKey.key.entity=KeyNode;
	rKey.key.serial=0;

	T_GSPR_KEY KeySerial;
	if(!GetSerialGspr(KeyNode, KeyBngr, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

void CAttrCtrl::GetGsprKeyList(CArray<T_GSPR_K, T_GSPR_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_GSPR_K Key;
	T_GSPR_D Data;
	pos=GetStartGspr();
	while(pos != NULL)
	{
		GetNextGspr(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetGsprNodeKeyList(CArray<T_NODE_K, T_NODE_K>& rNodeKeyList)
{
	rNodeKeyList.RemoveAll();
	CArray<T_GSPR_K, T_GSPR_K> aGsprKeyList;
	GetGsprKeyList(aGsprKeyList);
	int nNum = aGsprKeyList.GetSize();
	if (nNum == 0) return;
	rNodeKeyList.Add(aGsprKeyList[0].key.entity);
	for (int i = 1; i < nNum; i++)
	{
		if (aGsprKeyList[i].key.entity == aGsprKeyList[i-1].key.entity)
			continue;
		rNodeKeyList.Add(aGsprKeyList[i].key.entity);
	}
}

