void CAttrCtrl::GetGsprNode(T_NODE_K KeyNode, CArray<T_GSPR_K, T_GSPR_K>& rKeyList, CArray<T_GSPR_D, T_GSPR_D&>& rDataList)
{
	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_GSPR_CMD)
		{
			T_GSPR_K key;
			T_GSPR_D data;
			key.keymap=ListData.nKey;
			GetGspr(key, data);
			rKeyList.Add(key);
			rDataList.Add(data);
		}
	}
}

// 하나의 데이타로 리턴하는 게 불가능한 것 -> Array로 리턴
BOOL CAttrCtrl::GetGsprBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, T_NODE_K KeyNode, CArray<T_GSPR_D, T_GSPR_D&>& raData)
{
	CChangeBaseStageAndRecoverOnReturn SetStage(m_pDoc->m_pStagCtrl, FALSE);
	if (!bAllGroup) SetStage.Set();

	CArray<T_GSPR_K, T_GSPR_K> aKey;
	GetGsprNode(KeyNode, aKey, raData);
	if (!bAllGroup) 
	{
		int nBngrKeyNum = raKeyBngr.GetSize();
		if (nBngrKeyNum == 0) { raData.RemoveAll(); return FALSE; }
		CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
		mapBngrKey.InitHashTable(HASHSIZEBNGR);
		for (int i = 0; i < nBngrKeyNum; i++)
			mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

		for (int i = raData.GetSize()-1; i >= 0; i--)
			if (!mapBngrKey.Lookup(raData[i].GroupKey, raData[i].GroupKey))
				raData.RemoveAt(i);
	}
	if (raData.GetSize() > 0) return TRUE;
	return FALSE;
}

