BOOL CAttrCtrl::ExistRelt(T_RELT_D& rData)
{
	T_RELT_K key;
	T_RELT_D data;

	POSITION pos = m_pDataMemb->m_relt.GetStart();
	while (pos != NULL)
	{
		m_pDataMemb->m_relt.GetNext(pos, key, data);

		if(rData.ElnkKey   == data.ElnkKey &&
			rData.nStatus  == data.nStatus &&
			rData.GroupKey == data.GroupKey)
		{ // 같은 경우

			return TRUE;
		}
		else
		{
			continue;
		}
	}
	return FALSE;
}

