T_RELT_K CAttrCtrl::GetReltKey(T_RELT_D& rData)
{
	T_RELT_K key;
	T_RELT_D data;

	POSITION pos = GetStartRelt();
	while (pos != NULL)
	{
		GetNextRelt(pos, key, data);
		if (data.ElnkKey == rData.ElnkKey && data.nStatus == rData.nStatus && data.GroupKey == rData.GroupKey)return key;
	}
	key = 0;
	return key;
}


