BOOL CAttrCtrl::ConvertMElnktoRElnk()
{
	CArray<T_ELNK_D, T_ELNK_D&> arElnkD;
	CArray<int, int&> aStatus;
	CArray<T_ELNK_K, T_ELNK_K&> rElnkDel;
	CMap<T_MLFC_K, T_MLFC_K, T_MLFC_K, T_MLFC_K> mapMfclDel;

	if (!IsConvertMElnktoRElnk(arElnkD, aStatus, rElnkDel, mapMfclDel)) return FALSE;

	std::map<KeyRlfcPos, ValForRlfcPos> mapRlfcPosData; 
	std::map<KeyReltPos, ValReltPos> mapReltData;
	MakeElnkNewWithRlfc(arElnkD, aStatus, TRUE, mapRlfcPosData, mapReltData, TRUE);

	DeleteMElnkData(rElnkDel, mapMfclDel);

	SetElnktoRElnk(mapRlfcPosData, mapReltData);

	return TRUE;
}


