BOOL CAttrCtrl::IsConvertMElnktoRElnk(CArray<T_ELNK_D, T_ELNK_D&>& arElnkD, CArray<int, int&>& aStatus, 
										CArray<T_ELNK_K, T_ELNK_K&>& rElnkDel, CMap<T_MLFC_K, T_MLFC_K, T_MLFC_K, T_MLFC_K>& mapMfclDel)
{
	if (GetCountStag() < 2) return FALSE;


	//////////////////////////////////////////////////////////////////////////
	CArray<T_ELNK_K, T_ELNK_K> rKeyList;
	GetElnkKeyList(rKeyList);

	std::map<KeyRlfcPos, ValForElnDArray> mapElnDarr;
	CArray<T_ELNK_D, T_ELNK_D&> arElnkDTemp;

	arElnkD.RemoveAll();
	aStatus.RemoveAll();
	rElnkDel.RemoveAll();
	mapMfclDel.InitHashTable(1001);

	T_ELNK_D ElnkD;
	T_MLFC_D MlfcD;

	for(int i=0; i< rKeyList.GetSize(); i++)
	{
		// 1. 데이터 체크용 - 같은 위치의 Link는 하나로 묶음.
		if(!GetElnk(rKeyList[i], ElnkD)) continue;
		if(ElnkD.nSubOption != 4) continue;

		if(ElnkD.nDirection != 1 && ElnkD.nDirection != 2) { ASSERT(0); return FALSE; } // 1:Dy 2:Dz 인 경우만.

		m_pDoc->m_pAttrCtrl->GetMlfc(ElnkD.MlfcK, MlfcD);
		if(!MlfcD.bSymmetric) { ASSERT(0); return FALSE; }
		if( MlfcD.nFuncType != 0) { ASSERT(0); return FALSE; }
		if( MlfcD.arFuncData.GetSize() != 3) { ASSERT(0); return FALSE; }

		ElnkD.dDistance[1] = MlfcD.arFuncData[1].dValueX;
 		ElnkD.dForce[1]    = MlfcD.arFuncData[1].dValueY;

		KeyRlfcPos Key(ElnkD.Node1, ElnkD.Node2, 0);
		auto itrFind = mapElnDarr.find(Key);
		if (itrFind == mapElnDarr.end())
		{ // 없으면

			arElnkDTemp.RemoveAll();
			arElnkDTemp.Add(ElnkD);

			ValForElnDArray Val;
			Val.Set(arElnkDTemp);
			mapElnDarr[Key] = Val;
		}
		else
		{ // 있으면
			ValForElnDArray& Val = itrFind->second;

			arElnkDTemp.RemoveAll();
			arElnkDTemp.Copy(Val.arElnkD);
			arElnkDTemp.Add(ElnkD);

			Val.Set(arElnkDTemp);
		}

		//2. 삭제용 - 원래 Multi Link 대로 정리
		rElnkDel.Add(rKeyList[i]);
		mapMfclDel.SetAt(ElnkD.MlfcK, ElnkD.MlfcK);
	}

	if (mapElnDarr.size() < 1) return FALSE;

	for (auto itrMapLoop = mapElnDarr.begin(); itrMapLoop != mapElnDarr.end(); itrMapLoop++)
	{
		KeyRlfcPos key = itrMapLoop->first;
		ValForElnDArray& data = itrMapLoop->second;

		//////////////////////////////////////////////////////////////////////////
		// [Checking]
 		// 하나의  key에 여러 ElnkD 있어야 한다.
 		if (data.arElnkD.GetSize() < 2) return FALSE;

		// 여러 ElnkD 에는 서로 다른  GroupKey 있어야 한다.
		for (int i = 1; i < data.arElnkD.GetSize(); i++)
		{
			if(data.arElnkD[0].GroupKey == data.arElnkD[i].GroupKey) // GroupKey 가 같은 것이 있으며 FALSE
			{
				return FALSE;
			}
		}

		// GroupKey 개수는 시공단계 개수와 같아야 한다.
		if (data.arElnkD.GetSize() != GetCountStag())
			return FALSE;

		//////////////////////////////////////////////////////////////////////////
		CArray<T_ELNK_D, T_ELNK_D&> arElnkDUse; arElnkDUse.RemoveAll();
 		CArray<int, int&> aStatusUse; aStatusUse.RemoveAll();

		std::vector<std::pair<double, T_ELNK_D>> aForceAndElnkD;

		std::pair<double, T_ELNK_D> EachForceAndElnkD;
		for (int i = 0; i < data.arElnkD.GetSize(); i++)
		{
			EachForceAndElnkD.first = data.arElnkD[i].dForce[1];
			EachForceAndElnkD.second = data.arElnkD[i];
			aForceAndElnkD.push_back(EachForceAndElnkD);
		}
		std::sort(aForceAndElnkD.begin(), aForceAndElnkD.end()); // std::pair 를 sort 하면 firt 를 기준으로 sorting 됨 : 오름차순

		int nSize = (int)aForceAndElnkD.size();
		int nStatus = 0;
		CMap<double, double, int, int> mapSortElnk; mapSortElnk.InitHashTable(7);
		nStatus = 0;  mapSortElnk.SetAt(aForceAndElnkD[0].first, nStatus); // 첫번째는 min 값 0
		nStatus = 1;  mapSortElnk.SetAt(aForceAndElnkD[nSize - 1].first, nStatus); // 마지막은 max 값 1
		for (int i = 1; i < aForceAndElnkD.size() - 1; i++)
		{
			int nTemp;
			if (!mapSortElnk.Lookup(aForceAndElnkD[i].first, nTemp))
			{
				nStatus++;  //2 ,3
				mapSortElnk.SetAt(aForceAndElnkD[i].first, nStatus);
			}
		}
		//////////////////////////////////////////////////////////////////////////
		// [Checking] - 하나의  link에는 최대 4개 타입만 가능
		if (mapSortElnk.GetSize() > 4) { ASSERT(0); return FALSE; }
		//////////////////////////////////////////////////////////////////////////

		int nTemp=0;
		for (int i = 0; i < aForceAndElnkD.size(); i++)
		{
			if (mapSortElnk.Lookup(aForceAndElnkD[i].first, nTemp))
			{
				nStatus = nTemp;
			}
			else
			{
				ASSERT(0); // 여기엔 들어올 수 없다..
			}
			arElnkDUse.Add(aForceAndElnkD[i].second);
			aStatusUse.Add(nStatus);
		}

		arElnkD.Append(arElnkDUse);
		aStatus.Append(aStatusUse);

	} // for mapElnDarr

	return TRUE;
}

void CAttrCtrl::MakeElnkNewWithRlfc(CArray<T_ELNK_D, T_ELNK_D&>& arElnkD, CArray<int, int&>& aStatus, BOOL bFindSameMlfc, 
									std::map<KeyRlfcPos, ValForRlfcPos>& mapRlfcPosData, std::map<KeyReltPos, ValReltPos>& mapReltData, BOOL bIsReadFile4Convett/*=FALSE*/ )
{
	// 기존 MakeElnkNewWithMlfc(T_ELNK_D& ElnkD, BOOL bFindSameMlfc) 함수 속도 개선
	// ElnkD를 하나씩 처리하지 않고 Array로 받아와 한꺼번에 처리

	for (int i = 0; i < arElnkD.GetCount(); i++)
	{
		if (bIsReadFile4Convett)
		{
			if (arElnkD[i].nSubOption != 4) return;  // 하위버전에서 변환할 때
			arElnkD[i].nSubOption = 6;              // 변환 4 ->6
			arElnkD[i].MlfcK = 0;
		}
		else
		{
			if (arElnkD[i].nSubOption != 6) return; // 위자드에서 만드는 경우
		}
	}

	CArray<T_RLFC_D, T_RLFC_D&> arRlfcD;
	arRlfcD.SetSize(arElnkD.GetCount());
	for (int i = 0; i < arRlfcD.GetCount(); i++) arRlfcD[i].Initialize();

	for (int i = 0; i < arElnkD.GetCount(); i++)
	{
		// test
		T_ELNK_D& ElnKD = arElnkD[i];
		//

		int nStatus = aStatus[i];
		int nGroupKey = arElnkD[i].GroupKey;

		//////////////////////////////////////////////////////////////////////////
		int nType = 0;  
		KeyRlfcPos Key(arElnkD[i].Node1, arElnkD[i].Node2, nType);
		auto itrFind = mapRlfcPosData.find(Key);
		if (itrFind == mapRlfcPosData.end())
		{ // 없으면

			//arRlfcD[i].FuncName = strNewRlfcName; 나중에 만든다.
			arRlfcD[i].nFuncType = 0;
			arRlfcD[i].bSymmetric = TRUE;
			arRlfcD[i].dLimDisp = arElnkD[i].dDistance[1];  // Limited Disp.
			if (nStatus == 0) // Unloaded
			{
				arRlfcD[i].dUnLoadF = arElnkD[i].dForce[1];  // UnLoaded Fmax
			}
			else if (nStatus == 1)  // Loaded(= Left + Right)
			{
				arRlfcD[i].dLoadF = arElnkD[i].dForce[1];
			}
			else if (nStatus == 2)  // Loaded Left
			{
				arRlfcD[i].dLoadF_L = arElnkD[i].dForce[1];  // Left Loaded Fmax
			}
			else if (nStatus == 3)  // Loaded Right
			{
				arRlfcD[i].dLoadF_R = arElnkD[i].dForce[1];  // Right Loaded Fmax
			}
			else
			{
				ASSERT(0);
			}


			//////////////////////////////////////////////////////////////////////////		 
			for (int j = 0; j < arElnkD[i].nGridNum; j++)
			{
				arElnkD[i].dDistance[j] = 0.0;
				arElnkD[i].dForce[j] = 0.0;
			}
			arElnkD[i].nGridNum = 0;
			//////////////////////////////////////////////////////////////////////////

			ValForRlfcPos Val;
			Val.Set(arElnkD[i], arRlfcD[i]);
			mapRlfcPosData[Key] = Val;
		}
		else
		{ // 있으면
			ValForRlfcPos& Val = itrFind->second;

			T_RLFC_D RlfcD = Val.RlfcD;

			if (nStatus == 0) // Unloaded
			{
				RlfcD.dUnLoadF = arElnkD[i].dForce[1];  // UnLoaded Fmax
			}
			else if (nStatus == 1)  // Loaded(= Left + Right)
			{
				RlfcD.dLoadF = arElnkD[i].dForce[1];
			}
			else if (nStatus == 2)  // Loaded Left
			{
				RlfcD.dLoadF_L = arElnkD[i].dForce[1];  // Left Loaded Fmax
			}
			else if (nStatus == 3)  // Loaded Right
			{
				RlfcD.dLoadF_R = arElnkD[i].dForce[1];  // Right Loaded Fmax
			}
			else
			{
				ASSERT(0);
			}

			Val.RlfcD = RlfcD;
			mapRlfcPosData[Key] = Val;
		}

		//////////////////////////////////////////////////////////////////////////
		KeyReltPos Key2(arElnkD[i].Node1, arElnkD[i].Node2, nStatus, nGroupKey);
		auto itrFind2 = mapReltData.find(Key2);
		if (itrFind2 == mapReltData.end())
		{ // 없으면

			ValReltPos Val;
			int Node1 = arElnkD[i].Node1;
			int Node2 = arElnkD[i].Node2;

			Val.Set(arElnkD[i].Node1, arElnkD[i].Node2, nStatus, nGroupKey);
			mapReltData[Key2] = Val;
		}
		else
		{ // 있으면
		  //alReltPos& Val = itrFind2->second;
		}

	} // arElnkD
}

void CAttrCtrl::SetElnktoRElnk(std::map<KeyRlfcPos, ValForRlfcPos>& mapRlfcPosData, std::map<KeyReltPos, ValReltPos>& mapReltData)
{
	std::map<KeyRlfcNamePos, ValRlfcNamePos> mapRlfcNameData;

	CMap<UINT2, UINT2, T_ELNK_K, T_ELNK_K> mapRelt;
	mapRelt.InitHashTable(1001);

	CMap<CString, LPCTSTR, T_RLFC_K, T_RLFC_K> mapRlfcFuncName;
	mapRlfcFuncName.InitHashTable(HASHSIZERLFC);

	int nCnt = 1;

	CString strNewRlfcName;
	CArray<T_ELNK_D, T_ELNK_D&> aElnkD_All_Used;
	for (auto itrMapLoop = mapRlfcPosData.begin(); itrMapLoop != mapRlfcPosData.end(); itrMapLoop++)
	{
		KeyRlfcPos key = itrMapLoop->first;
		ValForRlfcPos& data = itrMapLoop->second;
		T_ELNK_D ElnKD = data.ElnkD;
		T_RLFC_D RlfcD = data.RlfcD;

		//////////////////////////////////////////////////////////////////////////
		KeyRlfcNamePos Key(RlfcD);
		auto itrFind = mapRlfcNameData.find(Key);
		if (itrFind == mapRlfcNameData.end())
		{ // 동일한 Rlfc를 못 찾은 경우  
			strNewRlfcName.Format(_T("Rlfc-%d"), nCnt++);

			ValRlfcNamePos Val;
			Val.Set(strNewRlfcName);
			mapRlfcNameData[Key] = Val;

			// 1. RLFC Add 
			RlfcD.FuncName = strNewRlfcName;
			if (!m_pDoc->m_pEditData->AddRlfc(RlfcD)) { ASSERT(0); continue; }
		}
		else
		{ // 있으면
			ValRlfcNamePos& Val = itrFind->second;

			strNewRlfcName = Val.strNewRlfcName;
		}

		ElnKD.RlfcK = m_pDoc->m_pAttrCtrl->GetRlfcKey(strNewRlfcName);
		ElnKD.GroupKey = 3; // Base

		// 2. ELNK Add
		T_ELNK_K ElnkK = m_pDoc->m_pAttrCtrl->GetStartNumElnk();
		if (!m_pDoc->m_pEditData->AddElnk(ElnkK, ElnKD)) { ASSERT(0); continue; }

		UINT2 KeyTemp;
		KeyTemp.i1 = ElnKD.Node1;
		KeyTemp.i2 = ElnKD.Node2;
		mapRelt.SetAt(KeyTemp, ElnkK);
	}

	// 3. RELT Add
	UINT Node1, Node2;
	T_ELNK_K ElnkK;
	int nStatus = 0;
	int nGroup = 0;
	CArray<T_RELT_D, T_RELT_D&> rReltData;
	for (auto itrMapLoop2 = mapReltData.begin(); itrMapLoop2 != mapReltData.end(); itrMapLoop2++)
	{
		KeyReltPos key2 = itrMapLoop2->first;
		ValReltPos& data2 = itrMapLoop2->second;

		Node1 = data2.Node1;
		Node2 = data2.Node2;
		nStatus = data2.nStatus;
		nGroup = data2.nGroup;

		UINT2 KeyTemp;
		KeyTemp.i1 = Node1;
		KeyTemp.i2 = Node2;
		if (!mapRelt.Lookup(KeyTemp, ElnkK)) continue;
		if (ElnkK < 1) { ASSERT(0); continue; }

		T_RELT_D ReltD;
		ReltD.ElnkKey = ElnkK;
		ReltD.nStatus = (nStatus >3)? 1 : nStatus; // 0:UnLoaded, 1:Loaded  2: Left Loaded  3: Right Loaded
		ReltD.GroupKey = nGroup;

		if (!m_pDoc->m_pEditData->AddRelt(ReltD)) { ASSERT(0); continue; }
	}
}


void CAttrCtrl::DeleteMElnkData(CArray<T_ELNK_K, T_ELNK_K&>& rElnkDel, CMap<T_MLFC_K, T_MLFC_K, T_MLFC_K, T_MLFC_K>& mapMfclDel)
{
	for(int i=0; i< rElnkDel.GetSize(); i++)
	{
		if(!m_pDoc->m_pEditData->DelElnk(rElnkDel[i])) { ASSERT(0); continue; }

	}

	T_MLFC_K MlfcK;
	T_MLFC_K MlfcK2;
	POSITION pos = mapMfclDel.GetStartPosition();
	while (pos)
	{
		mapMfclDel.GetNextAssoc(pos, MlfcK, MlfcK2);
		if (!m_pDoc->m_pEditData->DelMlfc(MlfcK)) { ASSERT(0); continue; }
	}
}


