void CAttrCtrl::GetNlnkKeyList(CArray<T_NLNK_K, T_NLNK_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_NLNK_K Key;
	T_NLNK_D Data;
	pos=GetStartNlnk();
	while(pos != NULL)
	{
		GetNextNlnk(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetNlnkKeyByNodeList(CArray<T_NLNK_K, T_NLNK_K>& rKeyList, const CArray<T_NODE_K, T_NODE_K>& aNodeList)
{
	rKeyList.RemoveAll();

	CMap<T_NODE_K, T_NODE_K,BOOL,BOOL> aTempExist;
	for (int i = 0; i < aNodeList.GetSize(); i++)
	{
		aTempExist.SetAt(aNodeList[i], TRUE);
	}
	POSITION pos;
	T_NLNK_K Key;
	T_NLNK_D Data;
	pos = GetStartNlnk();
	while (pos != NULL)
	{
		GetNextNlnk(pos, Key, Data);
		if(aTempExist.PLookup(Data.Node1) && aTempExist.PLookup(Data.Node2))
			rKeyList.Add(Key);
	}
	//if (rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

int CAttrCtrl::GetNlnkKeyListBetween2Nodes(T_NODE_K NodeK1, T_NODE_K NodeK2, CArray<T_NLNK_K, T_NLNK_K>& rKeyList)
{
	rKeyList.RemoveAll();
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetList(NodeK1, pList)) return 0;
	T_NLNK_D NlnkD;
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if (ListData.nCmd == LT_NLNK_CMD)
		{
			if (!GetNlnk(ListData.nKey, NlnkD)) { ASSERT(0); continue; }
			if (NlnkD.Node1 == NodeK1 && NlnkD.Node2 == NodeK2) rKeyList.Add(ListData.nKey);
			else if (NlnkD.Node2 == NodeK1 && NlnkD.Node1 == NodeK2) rKeyList.Add(ListData.nKey);
		}
	}
	return rKeyList.GetSize();
}

BOOL CAttrCtrl::ExistNlnk(T_NLNK_K Key)
{
	T_NLNK_D Data;
	return m_pDataMemb->m_nlnk.Get(Key,Data);
}
int  CAttrCtrl::GetElnk(T_NODE_K NodeK1,CArray<T_ELNK_K, T_ELNK_K>& rKeyList)
{
	rKeyList.RemoveAll();
	NodeList* pList;
	if (!m_pDataMemb->m_node.GetList(NodeK1, pList)) return 0;
	T_ELNK_D ElnkD;
	T_LIST_DATA ListData;
	POSITION pos = pList->GetHeadPosition();
	while (pos != NULL)
	{
		ListData = pList->GetNext(pos);
		if (ListData.nCmd == LT_ELNK_CMD)
		{
			if (!GetElnk(ListData.nKey, ElnkD)) { ASSERT(0); continue; }
			if (ElnkD.Node1 == NodeK1 || ElnkD.Node2 == NodeK1)
				rKeyList.Add(ListData.nKey);
		}
	}
	return rKeyList.GetSize();
}
int CAttrCtrl::GetElnkKeyListBetween2Nodes(T_NODE_K NodeK1, T_NODE_K NodeK2, T_BNGR_K bngrK, CArray<T_ELNK_K, T_ELNK_K>& rKeyList)
{
	rKeyList.RemoveAll();
	NodeList* pList;
	if (!m_pDataMemb->m_node.GetList(NodeK1, pList)) return 0;
	T_ELNK_D ElnkD;
	T_LIST_DATA ListData;
	POSITION pos = pList->GetHeadPosition();
	while (pos != NULL)
	{
		ListData = pList->GetNext(pos);
		if (ListData.nCmd == LT_ELNK_CMD)
		{
			if (!GetElnk(ListData.nKey, ElnkD)) { ASSERT(0); continue; }
			if(ElnkD.GroupKey != bngrK)
				continue;
			if (ElnkD.Node1 == NodeK1 && ElnkD.Node2 == NodeK2) 
				rKeyList.Add(ListData.nKey);
			else if (ElnkD.Node2 == NodeK1 && ElnkD.Node1 == NodeK2) 
				rKeyList.Add(ListData.nKey);
		}
	}
	return rKeyList.GetSize();
}
BOOL CAttrCtrl::GetNlnk(T_NLNK_K Key,T_NLNK_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_nlnk.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitNlnkOut(rData);
	return bReturn;
}
int CAttrCtrl::GetElemAttr(T_ELEM_K KeyElem, int ltDataCmd, T_KEY_LIST &rKeyList)
{
	rKeyList.RemoveAll();
	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos = pList->GetHeadPosition();
	while (pos != NULL)
	{
		ListData = pList->GetNext(pos);
		if (ListData.nCmd == ltDataCmd)
		{
			rKeyList.Add(ListData.nKey);
		}
	}
	return rKeyList.GetCount();
}
int CAttrCtrl::GetNlnkList(CArray<T_NLNK_K, T_NLNK_K>& raKey, CArray<T_NLNK_D, T_NLNK_D&>& raData)
{
	GetNlnkKeyList(raKey);
	int nSize = raKey.GetSize();
	raData.SetSize(nSize);
	for (int i = 0; i < nSize; i++)
		GetNlnk(raKey[i], raData[i]);
	return nSize;
}

BOOL CAttrCtrl::GetNlnkBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, CArray<T_NLNK_K, T_NLNK_K>& raKey, CArray<T_NLNK_D, T_NLNK_D&>& raData)
{
	CChangeBaseStageAndRecoverOnReturn SetStage(m_pDoc->m_pStagCtrl, FALSE);
	if (!bAllGroup) SetStage.Set();

	//CArray<T_NLNK_D, T_NLNK_D&> aData;
	int nSize = GetNlnkList(raKey, raData);
	if (!bAllGroup) 
	{
		int nBngrKeyNum = raKeyBngr.GetSize();
		if (nBngrKeyNum == 0) { raKey.RemoveAll(); raData.RemoveAll(); return FALSE; }
		CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
		mapBngrKey.InitHashTable(HASHSIZEBNGR);
		for (int i = 0; i < nBngrKeyNum; i++)
			mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

		for (int i = raData.GetSize()-1; i >= 0; i--)
			if (!mapBngrKey.Lookup(raData[i].GroupKey, raData[i].GroupKey))
			{
				raKey.RemoveAt(i);
				raData.RemoveAt(i);
			}
			SetStage.Recover();
			if (!SetStage.IsBaseStage())
			{
				for (int i = raData.GetSize()-1; i >= 0; i--)
					if (!ExistNode(raData[i].Node1) || !ExistNode(raData[i].Node2))
					{
						raKey.RemoveAt(i);
						raData.RemoveAt(i);
					}
			}
	}
	if (raKey.GetSize() > 0) return TRUE;
	return FALSE;
}

