int CAttrCtrl::GetCglpList(CArray<T_CGLP_K, T_CGLP_K>& raKey, CArray<T_CGLP_D, T_CGLP_D&>& raData)
{
	GetCglpKeyList(raKey);
	int nSize = raKey.GetSize();
	raData.SetSize(nSize);
	for (int i = 0; i < nSize; i++)
		GetCglp(raKey[i], raData[i]);
	return nSize;
}

// Label시 사용됨 해당 그룹에 속하는 모든 Cglp 반환
// bAllGroup이면 모두 반환
BOOL CAttrCtrl::GetCglpBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, CArray<T_CGLP_K, T_CGLP_K>& raKey, CArray<T_CGLP_D, T_CGLP_D&>& raData)
{
	//CArray<T_CGLP_D, T_CGLP_D&> aData;
	int nSize = GetCglpList(raKey, raData);
	if (!bAllGroup) 
	{
		int nBngrKeyNum = raKeyBngr.GetSize();
		if (nBngrKeyNum == 0) { raKey.RemoveAll(); return FALSE; }
		CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
		mapBngrKey.InitHashTable(HASHSIZEBNGR);
		for (int i = 0; i < nBngrKeyNum; i++)
			mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

		for (int i = raData.GetSize()-1; i >= 0; i--)
			if (!mapBngrKey.Lookup(raData[i].GroupKey, raData[i].GroupKey))
			{
				raKey.RemoveAt(i);
				raData.RemoveAt(i);
			}
	}
	if (raKey.GetSize() > 0) return TRUE;
	return FALSE;
}

