////////////// frls ////////////////
BOOL CAttrCtrl::GetSerialFrls(T_ELEM_K KeyElem, T_BNGR_K KeyBngr, T_FRLS_KEY& rKeySerial)
{
	ElemList* pList;
	if(!m_pDataMemb->m_elem.GetListFromBaseDB(KeyElem, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_FRLS_CMD)
		{
			T_FRLS_K key;
			T_FRLS_D data;
			key.keymap=ListData.nKey;
			m_pDataMemb->m_frls.GetFromBaseDB(key, data);
			if(data.GroupKey == KeyBngr)
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_FRLS_K key;
	T_FRLS_D data;
	key.key.entity=KeyElem;
	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_frls.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeKeyFrls(T_ELEM_K KeyElem, T_BNGR_K KeyBngr, T_FRLS_K& rKey)
{
	rKey.key.entity=KeyElem;
	rKey.key.serial=0;

	T_FRLS_KEY KeySerial;
	if(!GetSerialFrls(KeyElem, KeyBngr, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

