{
	rKeyList.RemoveAll();

	POSITION pos;
	T_FRLS_K Key;
	T_FRLS_D Data;
	pos=GetStartFrls();
	while(pos != NULL)
	{
		GetNextFrls(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetFrlsElemKeyList(CArray<T_ELEM_K, T_ELEM_K>& rElemKeyList)
{
	rElemKeyList.RemoveAll();
	CArray<T_FRLS_K, T_FRLS_K> aFrlsKeyList;
	GetFrlsKeyList(aFrlsKeyList);
	int nNum = aFrlsKeyList.GetSize();
	if (nNum == 0) return;
	rElemKeyList.Add(aFrlsKeyList[0].key.entity);
	for (int i = 1; i < nNum; i++)
	{
		if (aFrlsKeyList[i].key.entity == aFrlsKeyList[i-1].key.entity)
			continue;
		rElemKeyList.Add(aFrlsKeyList[i].key.entity);
	}
}

