void CAttrCtrl::GetFrlsElem(T_ELEM_K KeyElem, CArray<T_FRLS_K, T_FRLS_K>& rKeyList, CArray<T_FRLS_D, T_FRLS_D&>& rDataList)
{
	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_FRLS_CMD)
		{
			T_FRLS_K key;
			T_FRLS_D data;
			key.keymap=ListData.nKey;
			GetFrls(key, data);
			rKeyList.Add(key);
			rDataList.Add(data);
		}
	}
}

BOOL CAttrCtrl::GetFrlsElem(T_ELEM_K KeyElem, T_FRLS_D& rData)
{
	CArray<T_FRLS_K, T_FRLS_K> aKey;
	CArray<T_FRLS_D, T_FRLS_D&> aData;
	GetFrlsElem(KeyElem, aKey, aData);
	int nNum = aData.GetSize();
	if (nNum == 0) return FALSE;
	rData.Initialize();
	rData.nType = aData[0].nType;
	for (int i = 0; i < nNum; i++)
	{
		for (int j = 0; j < 2; j++)
			for (int k = 0; k < FRLS_SIZE; k++)
				if (aData[i].Release[j][k] == '1') 
				{
					if(rData.nType == aData[i].nType) // nType 이 다른 경우는 ??
					{
						if (rData.Release[j][k] == '0') rData.Fixity[j][k] = aData[i].Fixity[j][k];  // Fixity값이 작은것을 선택
						else                            rData.Fixity[j][k] = __min(rData.Fixity[j][k], aData[i].Fixity[j][k]);
					}
					rData.Release[j][k] = '1';
				}
	}
	return TRUE;
}

BOOL CAttrCtrl::GetFrlsElem_Fix(T_ELEM_K KeyElem, T_FRLS_D& rData)
{
	CArray<T_FRLS_K, T_FRLS_K> aKey;
	CArray<T_FRLS_D, T_FRLS_D&> aData;
	GetFrlsElem(KeyElem, aKey, aData);
	int nNum = aData.GetSize();
	if (nNum == 0) return FALSE;
	rData.Initialize();
	rData = aData[0];
	for (int i = 0; i < nNum; i++)
	{
		for (int j = 0; j < 2; j++)
		{
			for (int k = 0; k < FRLS_SIZE; k++)
			{
				if (aData[i].Release[j][k] == '1')
				{
					rData.Release[j][k] = '1';
					if(rData.nType == aData[i].nType) // nType 이 다른 경우는 ??
					{
						rData.Fixity[j][k] = __max(rData.Fixity[j][k], aData[i].Fixity[j][k]);  // Fixity값이 큰것을 선택
					}
				}
			}
		}
	}
	for(int i = 0; i < 2; i++)
		for (int j = 0; j < FRLS_SIZE; j++)
			if (rData.Release[i][j] == '1') return TRUE;
	return FALSE;
}

BOOL CAttrCtrl::GetFrlsBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, T_ELEM_K KeyElem, T_FRLS_D& rData)
{
	if (bAllGroup) return GetFrlsElem(KeyElem, rData);

	int nBngrKeyNum = raKeyBngr.GetSize();
	if (nBngrKeyNum == 0) return FALSE;
	CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
	mapBngrKey.InitHashTable(HASHSIZEBNGR);
	for (int i = 0; i < nBngrKeyNum; i++)
		mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

	CChangeBaseStageAndRecoverOnReturn SetStage(m_pDoc->m_pStagCtrl);
	ElemList* pList;
	if(!m_pDataMemb->m_elem.GetList(KeyElem, pList))return FALSE;

	rData.Initialize();
	T_FRLS_K KeyFrls;
	T_FRLS_D DataFrls;
	T_LIST_DATA ListData;
	BOOL bFirst=TRUE;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_FRLS_CMD)
		{
			KeyFrls.keymap = ListData.nKey;
			if (KeyFrls.key.entity == KeyElem)
			{
				GetFrls(KeyFrls, DataFrls);
				if (mapBngrKey.Lookup(DataFrls.GroupKey, DataFrls.GroupKey))
				{
					if (bFirst) {rData.nType = DataFrls.nType, bFirst = FALSE;}
					for (int j = 0; j < 2; j++)
						for (int k = 0; k < FRLS_SIZE; k++)
							if (DataFrls.Release[j][k] == '1')
							{
								if(rData.nType == DataFrls.nType) // nType 이 다른 경우는 ??
								{
									if (rData.Release[j][k] == '0') rData.Fixity[j][k] = DataFrls.Fixity[j][k];  // Fixity값이 작은것을 선택
									else                            rData.Fixity[j][k] = __min(rData.Fixity[j][k], DataFrls.Fixity[j][k]);
								}
								rData.Release[j][k] = '1';
							}
				}
			}
		}
	}
	for(int i = 0; i < 2; i++)
		for (int j = 0; j < FRLS_SIZE; j++)
			if (rData.Release[i][j] == '1') return TRUE;
	return FALSE;
}

