BOOL CAttrCtrl::CalcFrlsData(CArray<T_FRLS_K, T_FRLS_K>& aFrlsK, T_FRLS_D& rData)
{
	T_FRLS_D FrlsD;
	CArray<T_FRLS_D, T_FRLS_D&> aFrlsD;

	for (int i = 0; i < aFrlsK.GetSize(); i++)
	{
		if (!GetFrls(aFrlsK[i], FrlsD)) continue;
		aFrlsD.Add(FrlsD);
	}

	if (!CalcFrlsData(aFrlsD, rData)) return FALSE;

	return TRUE;
}

BOOL CAttrCtrl::CalcFrlsData(CArray<T_FRLS_D, T_FRLS_D&>& aFrlsD, T_FRLS_D& rData)
{
	int nNum = aFrlsD.GetSize();
	if (nNum == 0) return FALSE;

	rData.Initialize();
	rData.nType = aFrlsD[0].nType;

	for (int i = 0; i < nNum; i++)
	{
		for (int j = 0; j < 2; j++)
		{
			for (int k = 0; k < FRLS_SIZE; k++)
			{
				if (aFrlsD[i].Release[j][k] == '1')
				{
					if (rData.nType == aFrlsD[i].nType) // nType 이 다른 경우는 ??
					{
						if (rData.Release[j][k] == '0') rData.Fixity[j][k] = aFrlsD[i].Fixity[j][k];  // Fixity값이 작은것을 선택
						else                            rData.Fixity[j][k] = __min(rData.Fixity[j][k], aFrlsD[i].Fixity[j][k]);
					}
					rData.Release[j][k] = '1';
				}
			}
		}
	}

	return TRUE;
}

