BOOL CAttrCtrl::CalcPrlsData(CArray<T_PRLS_K, T_PRLS_K>& aPrlsK, T_PRLS_D& rData)
{
	T_PRLS_D PrlsD;
	CArray<T_PRLS_D, T_PRLS_D&> aPrlsD;

	for (int i = 0; i < aPrlsK.GetSize(); i++)
	{
		if (!GetPrls(aPrlsK[i], PrlsD)) continue;
		aPrlsD.Add(PrlsD);
	}

	if (!CalcPrlsData(aPrlsD, rData)) return FALSE;

	return TRUE;
}

BOOL CAttrCtrl::CalcPrlsData(CArray<T_PRLS_D, T_PRLS_D&>& aPrlsD, T_PRLS_D& rData)
{
	int nNum = aPrlsD.GetSize();
	if (nNum == 0) return FALSE;

	rData.Initialize();

	for (int i = 0; i < nNum; i++)
	{
		for (int j = 0; j < 4; j++)
		{
			for (int k = 0; k < 5; k++)
			{
				if (aPrlsD[i].Release[j][k] == '1')
				{
					rData.Release[j][k] = '1';
				}
			}
		}
	}

	return TRUE;
}

