void CAttrCtrl::GetRigdKeyList(CArray<T_RIGD_K, T_RIGD_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_RIGD_K Key;
	T_RIGD_D Data;
	pos=GetStartRigd();
	while(pos != NULL)
	{
		GetNextRigd(pos, Key, Data);
		rKeyList.Add(Key);
	}
	CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::GetSerialRigd(T_NODE_K KeyMaster, unsigned int nSlaveType, T_BNGR_K KeyBngr, T_RIGD_KEY& rKeySerial)
{
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetListFromBaseDB(KeyMaster, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_RIGD_CMD)
		{
			T_RIGD_K key;
			T_RIGD_D data;
			key.keymap=ListData.nKey;
			m_pDataMemb->m_rigd.GetFromBaseDB(key, data);
			if(data.nSlaveType == nSlaveType && data.GroupKey == KeyBngr)
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_RIGD_K key;
	T_RIGD_D data;
	key.key.entity=KeyMaster;
	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_rigd.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeKeyRigd(T_NODE_K KeyMaster, unsigned int nSlaveType, T_BNGR_K KeyBngr, T_RIGD_K& rKey)
{
	rKey.key.entity=KeyMaster;
	rKey.key.serial=0;

	T_RIGD_KEY KeySerial;
	if(!GetSerialRigd(KeyMaster, nSlaveType, KeyBngr, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

