void CAttrCtrl::GetRigd(T_NODE_K KeyNode, CArray<T_RIGD_K, T_RIGD_K>& rarKey, CArray<T_RIGD_D, T_RIGD_D&>& rarData, BOOL bOnlyMaster)
{
	rarKey.RemoveAll();
	rarData.RemoveAll();

	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_RIGD_CMD)
		{
			T_RIGD_K key;
			T_RIGD_D data;
			key.keymap=ListData.nKey;
			if(bOnlyMaster && key.key.entity != KeyNode)continue;
			GetRigd(key, data);
			rarKey.Add(key);
			rarData.Add(data);
		}
	}
}

int CAttrCtrl::GetRigdList(CArray<T_RIGD_K, T_RIGD_K>& raKey, CArray<T_RIGD_D, T_RIGD_D&>& raData)
{
	GetRigdKeyList(raKey);
	int nSize = raKey.GetSize();
	raData.SetSize(nSize);
	for (int i = 0; i < nSize; i++)
		GetRigd(raKey[i], raData[i]);
	return nSize;
}

BOOL CAttrCtrl::GetRigdBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, CArray<T_RIGD_K, T_RIGD_K>& raKey, CArray<T_RIGD_D, T_RIGD_D&>& raData)
{
	CChangeBaseStageAndRecoverOnReturn SetStage(m_pDoc->m_pStagCtrl, FALSE);
	if (!bAllGroup) SetStage.Set();

	//CArray<T_RIGD_D, T_RIGD_D&> aData;
	int nSize = GetRigdList(raKey, raData);
	if (!bAllGroup) 
	{
		int nBngrKeyNum = raKeyBngr.GetSize();
		if (nBngrKeyNum == 0) { raKey.RemoveAll(); raData.RemoveAll(); return FALSE; }
		CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
		mapBngrKey.InitHashTable(HASHSIZEBNGR);
		for (int i = 0; i < nBngrKeyNum; i++)
			mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

		for (int i = raData.GetSize()-1; i >= 0; i--)
			if (!mapBngrKey.Lookup(raData[i].GroupKey, raData[i].GroupKey))
			{
				raKey.RemoveAt(i);
				raData.RemoveAt(i);
			}
			SetStage.Recover();
			if (!SetStage.IsBaseStage())
			{
				for (int i = raData.GetSize()-1; i >= 0; i--)
				{
					BOOL bRemove = FALSE;
					if (!ExistNode(raKey[i].key.entity)) bRemove = TRUE;
					if (!bRemove)
					{
						for (int j = 0; j < raData[i].arSlave.GetSize(); j++)
							if (!ExistNode(raData[i].arSlave[j]))
							{
								bRemove = TRUE;
								break;
							}
					}
					if (bRemove)
					{
						raKey.RemoveAt(i);
						raData.RemoveAt(i);
					}
				}
			}
	}
	if (raKey.GetSize() > 0) return TRUE;
	return FALSE;
}

