BOOL CAttrCtrl::GetSerialMcon(T_NODE_K KeyMaster, unsigned int nSlaveType, int nType, T_BNGR_K KeyBngr, T_MCON_KEY& rKeySerial)
{
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetListFromBaseDB(KeyMaster, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_MCON_CMD)
		{
			T_MCON_K key;
			T_MCON_D data;
			key.keymap=ListData.nKey;
			m_pDataMemb->m_mcon.GetFromBaseDB(key, data);
			if(data.GroupKey == KeyBngr && !(nType==0 && data.nType==0 && nSlaveType!=data.nSlaveType))
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_MCON_K key;
	T_MCON_D data;
	key.key.entity=KeyMaster;
	int j=0;
	while(TRUE)
	{
		j++;
		key.key.serial=j;
		if(!m_pDataMemb->m_mcon.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

