				EwsfD.EwsfSubZ.dZbotFactor = max(aData[i].EwsfSubZ.dZbotFactor, EwsfD.EwsfSubZ.dZbotFactor);    // 중립축 거리비는 가장 큰 것      

				if (aData[i].EwsfSubZ.bJ)
				{
					EwsfD.EwsfSubZ.dScaleFactor_j = min(aData[i].EwsfSubZ.dScaleFactor_j, EwsfD.EwsfSubZ.dScaleFactor_j);   // 단면 이차모멘트는 가장 작은 것
					EwsfD.EwsfSubZ.dZtopFactor_j = max(aData[i].EwsfSubZ.dZtopFactor_j, EwsfD.EwsfSubZ.dZtopFactor_j);    // 중립축 거리비는 가장 큰 것
					EwsfD.EwsfSubZ.dZbotFactor_j = max(aData[i].EwsfSubZ.dZbotFactor_j, EwsfD.EwsfSubZ.dZbotFactor_j);    // 중립축 거리비는 가장 큰 것      
					EwsfD.EwsfSubZ.bJ = TRUE;
				}
				else
				{
					EwsfD.EwsfSubZ.dScaleFactor_j = min(aData[i].EwsfSubZ.dScaleFactor, EwsfD.EwsfSubZ.dScaleFactor_j);   // 단면 이차모멘트는 가장 작은 것
					EwsfD.EwsfSubZ.dZtopFactor_j = max(aData[i].EwsfSubZ.dZtopFactor, EwsfD.EwsfSubZ.dZtopFactor_j);    // 중립축 거리비는 가장 큰 것
					EwsfD.EwsfSubZ.dZbotFactor_j = max(aData[i].EwsfSubZ.dZbotFactor, EwsfD.EwsfSubZ.dZbotFactor_j);    // 중립축 거리비는 가장 큰 것      
				}

// 				dScaleFactorMin_i = min(aData[i].dScaleFactor, dScaleFactorMin_i);   // 단면 이차모멘트는 가장 작은 것
// 				dZbotFactorMax_i  = max(aData[i].dZbotFactor,  dZbotFactorMax_i);    // 중립축 거리비는 가장 큰 것
// 				dZtopFactorMax_i  = max(aData[i].dZtopFactor,  dZtopFactorMax_i);    // 중립축 거리비는 가장 큰 것              
// 				if(aData[i].bJ)
// 				{
// 					dScaleFactorMin_j = min(aData[i].dScaleFactor_j, dScaleFactorMin_j);
// 					dZbotFactorMax_j  = max(aData[i].dZbotFactor_j,  dZbotFactorMax_j); 
// 					dZtopFactorMax_j  = max(aData[i].dZtopFactor_j,  dZtopFactorMax_j); 
// 					bJ = TRUE;
// 				}
// 				else
// 				{
