BOOL CAttrCtrl::GetEwsdBngr(BOOL bAllGroup, CArray<T_BNGR_K, T_BNGR_K>& raKeyBngr, T_ELEM_K KeyElem, T_EWSF_D& rData)
{
	if (bAllGroup) return GetEwsdElem(KeyElem, rData);

	int nBngrKeyNum = raKeyBngr.GetSize();
	if (nBngrKeyNum == 0) return FALSE;
	CMap<T_BNGR_K, T_BNGR_K, T_BNGR_K, T_BNGR_K> mapBngrKey;
	mapBngrKey.InitHashTable(HASHSIZEBNGR);
	for (int i = 0; i < nBngrKeyNum; i++)
		mapBngrKey.SetAt(raKeyBngr[i], raKeyBngr[i]);

	ElemList* pList;
	if(!m_pDataMemb->m_elem.GetList(KeyElem, pList))return FALSE;

	BOOL bFirst=TRUE;
	rData.Initialize();
	T_EWSF_K KeyEwsf;
	T_EWSF_D DataEwsf;
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_EWSD_CMD)
		{
			KeyEwsf.keymap = ListData.nKey;
			if (KeyEwsf.key.entity == KeyElem)
			{
				GetEwsf(KeyEwsf, DataEwsf);
				if (mapBngrKey.Lookup(DataEwsf.GroupKey, DataEwsf.GroupKey))
				{
					if (bFirst)
					{
						rData = DataEwsf;
						bFirst = FALSE;
					}
					else
					{
						double dScaleFactor = 0.0;

						dScaleFactor = (DataEwsf.EwsfSubY.bJ) ? (DataEwsf.EwsfSubY.dScaleFactor + DataEwsf.EwsfSubY.dScaleFactor_j) / 2.0 : DataEwsf.EwsfSubY.dScaleFactor;

						if (dScaleFactor < rData.EwsfSubY.dScaleFactor)
						{
							rData.EwsfSubY = DataEwsf.EwsfSubY;
							rData.GroupKey = DataEwsf.GroupKey;
						}

						dScaleFactor = (DataEwsf.EwsfSubZ.bJ) ? (DataEwsf.EwsfSubZ.dScaleFactor + DataEwsf.EwsfSubZ.dScaleFactor_j) / 2.0 : DataEwsf.EwsfSubZ.dScaleFactor;

						if (dScaleFactor < rData.EwsfSubZ.dScaleFactor)
						{
							rData.EwsfSubZ = DataEwsf.EwsfSubZ;
							rData.GroupKey = DataEwsf.GroupKey;
						}

// 						double dScaleFactor = (DataEwsf.bJ) ? (DataEwsf.dScaleFactor+DataEwsf.dScaleFactor_j)/2. : DataEwsf.dScaleFactor;
// 						if (dScaleFactor < rData.dScaleFactor)
// 							rData = DataEwsf;
					}
				}
			}
		}
	}
	return TRUE;
}

