void CAttrCtrl::GetStldList(CArray<CString, CString&>& rstrStldList)
{
	rstrStldList.RemoveAll();

	int nCount=GetCountStld();
	if(nCount == 0)return;

	POSITION pos;
	T_STLD_K Key;
	T_STLD_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartStld();
		while(pos != NULL)
		{
			GetNextStld(pos, Key, Data);
			if(Data.LoadCaseId == i)
			{
				rstrStldList.Add(Data.LoadCaseName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetStldKeyList(CArray<T_STLD_K, T_STLD_K>& rStldKeyList)
{
	/*
	rStldKeyList.RemoveAll();

	int nCount=GetCountStld();
	if(nCount == 0)return;

	POSITION pos;
	T_STLD_K Key;
	T_STLD_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartStld();
	while(pos != NULL)
	{
	GetNextStld(pos, Key, Data);
	if(Data.LoadCaseId == i)
	{
	rStldKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rStldKeyList.RemoveAll();
	int nCount=GetCountStld();
	if(nCount == 0)return;

	CArray<T_STLD_K, T_STLD_K> aStldKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rStldKeyList.SetSize(nCount);
	aStldKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_STLD_K Key;
	T_STLD_D Data;
	int i = 0;
	pos = GetStartStld();
	while (pos != NULL)
	{
		GetNextStld(pos, Key, Data);
		aStldKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.LoadCaseId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rStldKeyList[i] = aStldKey[ix];
	}
}

void CAttrCtrl::GetStldKeyList4Exld(CArray<T_STLD_K, T_STLD_K>& rStldKeyList)
{
	rStldKeyList.RemoveAll();
	int nCount=GetCountStld();
	if(nCount == 0)return;

	CMap <T_STLD_K, T_STLD_K, int, int> mapPtns;
	mapPtns.InitHashTable(m_pDoc->GetHashSizeElem());
	mapPtns.RemoveAll();
	int nTemp;
	T_PTNS_K KeyPtns;
	T_PTNS_D DataPtns;
	POSITION pos = GetStartPtns();
	while(pos != NULL) 
	{
		GetNextPtns(pos, KeyPtns, DataPtns);
		mapPtns.SetAt(DataPtns.LoadCaseKey, 1);
	}

	CArray<T_STLD_K, T_STLD_K> aStldKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	aStldKey.RemoveAll();
	aPosIdPair.RemoveAll();

	T_POS_INT_PAIR item;
	T_STLD_K Key;
	T_STLD_D Data;
	int nNum = 0;
	pos = GetStartStld();
	while (pos != NULL)
	{
		GetNextStld(pos, Key, Data);
		if(!mapPtns.Lookup(Key, nTemp)) continue;
		if(Data.LoadCaseType == _T("CS") || Data.LoadCaseType == _T("TCS")) continue;
		aStldKey.Add(Key);
		aPosIdPair.Add(item);
		aPosIdPair[nNum].nPos = nNum;
		aPosIdPair[nNum].nVal = Data.LoadCaseId;
		nNum++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nNum, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for (int i = 0; i < nNum; i++)
	{
		ix = aPosIdPair[i].nPos;
		rStldKeyList.Add(aStldKey[ix]);
	}
}

