BOOL CAttrCtrl::GetStld(const CString& rLoadCaseName, T_STLD_D& rData)
{
	T_STLD_K key;
	T_STLD_D data;
	CString strLoadCaseName=rLoadCaseName;
	strLoadCaseName.TrimRight();

	POSITION pos=m_pDataMemb->m_stld.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_stld.GetNext(pos,key,data);
		if(strLoadCaseName.CompareNoCase(data.LoadCaseName) == 0)
		{
			m_pUnitCtrl->ConvertUnitStldOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

