T_STLD_K CAttrCtrl::GetStldKey(CString& rLoadCaseName)
{
	rLoadCaseName.TrimRight();  // 20111025 KIMJM 러시아 번역문제로 인한 맨뒤 빈칸 추가했으므로.

	T_STLD_K key;
	T_STLD_D data;

	POSITION pos=GetStartStld();
	while(pos != NULL)
	{
		GetNextStld(pos,key,data);
		//if(rLoadCaseName.CompareNoCase(data.LoadCaseName) == 0)return key;
		if(_tcsicmp(rLoadCaseName, data.LoadCaseName) == 0) return key;
	}
	key=0;
	return key;
}

