void CAttrCtrl::GetLcomKeyListOnlySgld(int nLcomType, CArray<T_LCOM_K, T_LCOM_K>& rKeyList)
{
	T_LCOM_D LcomData;
	GetLcomKeyList(nLcomType, rKeyList);
	int nNum = rKeyList.GetSize();
	for (int i = nNum-1; i >= 0; i--)
	{
		GetLcom(nLcomType, rKeyList[i], LcomData);
		if (!IsOnlySgldComb(nLcomType, LcomData)) rKeyList.RemoveAt(i);
	}
}

