void CAttrCtrl::InitLcomMaps()
{
	m_arLcomMaps[0] = nullptr;
	m_arLcomMaps[D_LCOMTYPE_GENERAL      ] = &m_pDataMemb->m_lcom;
	m_arLcomMaps[D_LCOMTYPE_STEEL        ] = &m_pDataMemb->m_lcst;
	m_arLcomMaps[D_LCOMTYPE_CONCRETE     ] = &m_pDataMemb->m_lcco;
	m_arLcomMaps[D_LCOMTYPE_FDN          ] = &m_pDataMemb->m_lcft;
	m_arLcomMaps[D_LCOMTYPE_SRC          ] = &m_pDataMemb->m_lcsc;
	m_arLcomMaps[D_LCOMTYPE_ALUMINUM     ] = &m_pDataMemb->m_lcal;
	m_arLcomMaps[D_LCOMTYPE_STLCOMP      ] = &m_pDataMemb->m_lcscm;
	m_arLcomMaps[D_LCOMTYPE_CFSTEEL      ] = &m_pDataMemb->m_lccf;
	m_arLcomMaps[D_LCOMTYPE_SEISMIC      ] = &m_pDataMemb->m_lcsm;
	m_arLcomMaps[D_LCOMTYPE_LINEAR_EVAL  ] = &m_pDataMemb->m_lcln;
}

BOOL CAttrCtrl::GetLcom(int nLcomType, CString& rLoadCombName, T_LCOM_D& rData)
{
#if 1 // cklee@midasit.com 불필요한 조건문 제거

	T_LCOM_K key;
	T_LCOM_D data;
	CString strLoadCombName=rLoadCombName;
	strLoadCombName.TrimRight();

	POSITION pos;


	auto curlcom = m_arLcomMaps[nLcomType];
	pos = curlcom->GetStart();

	while (pos != NULL)
	{
		curlcom->GetNext(pos, key, data);
		
		if (strLoadCombName.CompareNoCase(data.LoadCombName) == 0)
		{
			m_pUnitCtrl->ConvertUnitLcomOut(data);
			rData = data;
			return TRUE;
		}
	}
	return FALSE;

#else
	T_LCOM_K key;
	T_LCOM_D data;
	CString strLoadCombName = rLoadCombName;
	strLoadCombName.TrimRight();

	POSITION pos;

	if(nLcomType == D_LCOMTYPE_GENERAL)
		pos=m_pDataMemb->m_lcom.GetStart();
	else if(nLcomType == D_LCOMTYPE_STEEL)
		pos=m_pDataMemb->m_lcst.GetStart();
	else if(nLcomType == D_LCOMTYPE_CONCRETE)
		pos=m_pDataMemb->m_lcco.GetStart();
	else if(nLcomType == D_LCOMTYPE_FDN)
		pos=m_pDataMemb->m_lcft.GetStart();
	else if(nLcomType == D_LCOMTYPE_SRC)
		pos=m_pDataMemb->m_lcsc.GetStart();
	else if(nLcomType == D_LCOMTYPE_ALUMINUM)
		pos=m_pDataMemb->m_lcal.GetStart();
	else if(nLcomType == D_LCOMTYPE_STLCOMP)
		pos=m_pDataMemb->m_lcscm.GetStart();
	else if(nLcomType == D_LCOMTYPE_CFSTEEL)
		pos=m_pDataMemb->m_lccf.GetStart();
	else if(nLcomType == D_LCOMTYPE_SEISMIC)
		pos=m_pDataMemb->m_lcsm.GetStart();
	else if(nLcomType == D_LCOMTYPE_LINEAR_EVAL)
		pos=m_pDataMemb->m_lcln.GetStart();

	else
	{
		ASSERT(FALSE);
		return FALSE;
	}
	while(pos != NULL)
	{
		if(nLcomType == D_LCOMTYPE_GENERAL)
			m_pDataMemb->m_lcom.GetNext(pos,key,data);
		else if(nLcomType == D_LCOMTYPE_STEEL)
			m_pDataMemb->m_lcst.GetNext(pos,key,data);
		else if(nLcomType == D_LCOMTYPE_CONCRETE)
			m_pDataMemb->m_lcco.GetNext(pos,key,data);
		else if(nLcomType == D_LCOMTYPE_FDN)
			m_pDataMemb->m_lcft.GetNext(pos,key,data);
		else if(nLcomType == D_LCOMTYPE_SRC)
			m_pDataMemb->m_lcsc.GetNext(pos,key,data);
		else if(nLcomType == D_LCOMTYPE_ALUMINUM)
			m_pDataMemb->m_lcal.GetNext(pos,key,data);
		else if(nLcomType == D_LCOMTYPE_STLCOMP)
			m_pDataMemb->m_lcscm.GetNext(pos,key,data);
		else if(nLcomType == D_LCOMTYPE_CFSTEEL)
			m_pDataMemb->m_lccf.GetNext(pos,key,data);
		else if(nLcomType == D_LCOMTYPE_SEISMIC)
			m_pDataMemb->m_lcsm.GetNext(pos,key,data);
		else if(nLcomType == D_LCOMTYPE_LINEAR_EVAL)
			m_pDataMemb->m_lcln.GetNext(pos,key,data);

		if(strLoadCombName.CompareNoCase(data.LoadCombName) == 0)
		{
			m_pUnitCtrl->ConvertUnitLcomOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
#endif
}

