T_LCOM_K CAttrCtrl::GetLcomKey(int nLcomType, CString& rLoadCombName)
{
	T_LCOM_K key;
	T_LCOM_D data;

	POSITION pos=GetStartLcom(nLcomType);
	while(pos != NULL)
	{
		GetNextLcom(nLcomType, pos,key,data);
		if(rLoadCombName.CompareNoCase(data.LoadCombName) == 0)return key;
	}
	key=0;
	return key;
}

