BOOL CAttrCtrl::IsMaxMinComb(T_LCOM_D& rLoadComb)
{
	if(rLoadComb.LoadCombType == 1)return TRUE;  // Envelope
	for(int i=0; i<rLoadComb.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = rLoadComb.aCombination[i];
		int nLoadCaseKey=rLcomBase.LoadCaseKey;
		if(nLoadCaseKey == 0)break;
		int nAnalType=rLcomBase.AnalType;
		if(nAnalType == D_LCOM_STATIC)
		{
		}
		else if(nAnalType == D_LCOM_SPECTRUM)
		{
		}
		else if(nAnalType == D_LCOM_SPECTRUM_ND)
		{
		}
		else if(nAnalType == D_LCOM_HISTORY || nAnalType == D_LCOM_CB_HISTORY || nAnalType ==  D_LCOM_CB_JSONFILE )
		{
			return TRUE;
		}
		else if(nAnalType == D_LCOM_STAGE)
		{
		}
		else if(nAnalType == D_LCOM_ECCENSPEC)
		{
		}
		else if(nAnalType == D_LCOM_ECCENSPEC_ND)
		{
		}
		else if(nAnalType == D_LCOM_GRIDMODEL)
		{
			T_GILC_D GilcD;
			GetGilc(rLcomBase.LoadCaseKey, GilcD);
			if (IsGilcMaxMinType(GilcD)) return TRUE;
		}
		else if (nAnalType == D_LCOM_THEX)
		{
		}
		else if (nAnalType == D_LCOM_THAM)
		{
		}
		else if (nAnalType == D_LCOM_THPO)
		{
		}
		else if(nAnalType == D_LCOM_MOVING)
		{
			return TRUE;
		}
		else if(nAnalType == D_LCOM_SETTLEMENT)
		{
			return TRUE;
		}
		else if (nAnalType == D_LCOM_CRANE)
		{
			return TRUE;
		}
		else if(nAnalType == D_LCOM_ENVELOPE)
		{
			return TRUE;
		}
		else if(nAnalType == D_LCOM_CB_GENERAL || nAnalType == D_LCOM_CB_STEEL || nAnalType == D_LCOM_CB_CONCRETE || 
			nAnalType == D_LCOM_CB_FOOTING || nAnalType == D_LCOM_CB_SRC   || nAnalType == D_LCOM_CB_ALUMINUM ||
			nAnalType == D_LCOM_CB_STLCOMP || nAnalType == D_LCOM_CB_CFSTEEL || nAnalType == D_LCOM_CB_SEISMIC ||
			nAnalType == D_LCOM_CB_LINEAR_EVAL)
		{
			int nLcomType;
			if(nAnalType == D_LCOM_CB_GENERAL )nLcomType=D_LCOMTYPE_GENERAL;
			if(nAnalType == D_LCOM_CB_STEEL   )nLcomType=D_LCOMTYPE_STEEL  ;
			if(nAnalType == D_LCOM_CB_CONCRETE)nLcomType=D_LCOMTYPE_CONCRETE;
			if(nAnalType == D_LCOM_CB_FOOTING )nLcomType=D_LCOMTYPE_FDN    ;
			if(nAnalType == D_LCOM_CB_SRC     )nLcomType=D_LCOMTYPE_SRC    ;
			if(nAnalType == D_LCOM_CB_ALUMINUM)nLcomType=D_LCOMTYPE_ALUMINUM;
			if(nAnalType == D_LCOM_CB_STLCOMP )nLcomType=D_LCOMTYPE_STLCOMP;
			if(nAnalType == D_LCOM_CB_CFSTEEL )nLcomType=D_LCOMTYPE_CFSTEEL;
			if(nAnalType == D_LCOM_CB_SEISMIC )nLcomType=D_LCOMTYPE_SEISMIC;
			if(nAnalType == D_LCOM_CB_LINEAR_EVAL)nLcomType=D_LCOMTYPE_LINEAR_EVAL;
			T_LCOM_D lcom;
			GetLcom(nLcomType, nLoadCaseKey, lcom);
			if(IsMaxMinComb(lcom))return TRUE;
		}
		else
		{
			ASSERT(FALSE);
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::IsCraneComb(T_LCOM_D& rLoadComb)
{
	// Modify by GAY. MQC:3657. ('10.10.06). 기존에 Envelop Type은 무조건 Crane Comb로 Return 하던 부분을 삭제.
	//      현재는 Envelope인 경우 무조건 Crane Comb라고 볼 수 없음.  
	//if(rLoadComb.LoadCombType == 1)return TRUE;  // Envelope
	for(int i=0; i<rLoadComb.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = rLoadComb.aCombination[i];
		int nLoadCaseKey=rLcomBase.LoadCaseKey;
		if(nLoadCaseKey == 0)break;
		int nAnalType=rLcomBase.AnalType;
		if(nAnalType == D_LCOM_CRANE)
		{
			return TRUE;
		}
		else if(nAnalType == D_LCOM_CB_GENERAL || nAnalType == D_LCOM_CB_STEEL || nAnalType == D_LCOM_CB_CONCRETE || 
			nAnalType == D_LCOM_CB_FOOTING || nAnalType == D_LCOM_CB_SRC   || nAnalType == D_LCOM_CB_ALUMINUM ||
			nAnalType == D_LCOM_CB_STLCOMP)
		{
			int nLcomType;
			if(nAnalType == D_LCOM_CB_GENERAL ) nLcomType=D_LCOMTYPE_GENERAL;
			if(nAnalType == D_LCOM_CB_STEEL   ) nLcomType=D_LCOMTYPE_STEEL  ;
			if(nAnalType == D_LCOM_CB_CONCRETE) nLcomType=D_LCOMTYPE_CONCRETE;
			if(nAnalType == D_LCOM_CB_FOOTING ) nLcomType=D_LCOMTYPE_FDN    ;
			if(nAnalType == D_LCOM_CB_SRC     ) nLcomType=D_LCOMTYPE_SRC    ;
			if(nAnalType == D_LCOM_CB_ALUMINUM)nLcomType=D_LCOMTYPE_ALUMINUM;
			if(nAnalType == D_LCOM_CB_STLCOMP )nLcomType=D_LCOMTYPE_STLCOMP;
			if(nAnalType == D_LCOM_CB_CFSTEEL )nLcomType=D_LCOMTYPE_CFSTEEL;
			if(nAnalType == D_LCOM_CB_SEISMIC )nLcomType=D_LCOMTYPE_SEISMIC;
			if(nAnalType == D_LCOM_CB_LINEAR_EVAL )nLcomType=D_LCOMTYPE_LINEAR_EVAL;
			T_LCOM_D lcom;
			GetLcom(nLcomType, nLoadCaseKey, lcom);
			if(IsCraneComb(lcom)) return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::IsConCurrentComb12(T_LCOM_D& rData)
{
	/// [GEN-7441] Gen은 moving load가 있어도 동시발생 부재력 12 set를 고려하지 않고, max/min type으로 설계합니다.
#if defined(_MGEN)
	return FALSE;
#endif

    if (rData.LoadCombType == 1) // Envelope
    {
        return TRUE;
    }
    
    T_LCOM_D LcomData;
	for (int i=0; i<rData.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = rData.aCombination[i];
		if(rLcomBase.LoadCaseKey == 0) break;
		int nAnalType = rLcomBase.AnalType;
		if(nAnalType == D_LCOM_MOVING || nAnalType == D_LCOM_SETTLEMENT || nAnalType == D_LCOM_GRIDMODEL || nAnalType == D_LCOM_HISTORY )
		{
			// Modify. Jaeoh. [3/9/2011]
			if(nAnalType == D_LCOM_GRIDMODEL)
			{
				int nLoadCaseKey = rLcomBase.LoadCaseKey;
				T_GILC_D GilcD;
				GilcD.Initialize();
				if(!GetGilc(nLoadCaseKey,GilcD))	return FALSE;
				int iLcaseType = GilcD.nLoadCaseType;
				if(iLcaseType==0 || iLcaseType==1) return FALSE;
				else if(iLcaseType==2 || iLcaseType==3 || iLcaseType==4) return TRUE;
				else { ASSERT(0); return FALSE; }
			}
			else
				return TRUE;
		}
		else if(nAnalType == D_LCOM_CB_GENERAL || nAnalType == D_LCOM_CB_STEEL || nAnalType == D_LCOM_CB_CONCRETE ||
			nAnalType == D_LCOM_CB_FOOTING || nAnalType == D_LCOM_CB_SRC   || nAnalType == D_LCOM_CB_ALUMINUM ||
			nAnalType == D_LCOM_CB_STLCOMP						)
		{
			int nLcomType;
			if(nAnalType == D_LCOM_CB_GENERAL ) nLcomType=D_LCOMTYPE_GENERAL;
			if(nAnalType == D_LCOM_CB_STEEL   ) nLcomType=D_LCOMTYPE_STEEL  ;
			if(nAnalType == D_LCOM_CB_CONCRETE) nLcomType=D_LCOMTYPE_CONCRETE;
			if(nAnalType == D_LCOM_CB_FOOTING ) nLcomType=D_LCOMTYPE_FDN    ;
			if(nAnalType == D_LCOM_CB_SRC     ) nLcomType=D_LCOMTYPE_SRC    ;
			if(nAnalType == D_LCOM_CB_ALUMINUM) nLcomType=D_LCOMTYPE_ALUMINUM;
			if(nAnalType == D_LCOM_CB_STLCOMP ) nLcomType=D_LCOMTYPE_STLCOMP;
			if(nAnalType == D_LCOM_CB_CFSTEEL )nLcomType=D_LCOMTYPE_CFSTEEL;
			if(nAnalType == D_LCOM_CB_SEISMIC )nLcomType=D_LCOMTYPE_SEISMIC;
			if(nAnalType == D_LCOM_CB_LINEAR_EVAL )nLcomType=D_LCOMTYPE_LINEAR_EVAL;
			if (!GetLcom(nLcomType, rLcomBase.LoadCaseKey, LcomData)) return FALSE;      
			if (IsConCurrentComb12(LcomData)) return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::IsEnvlopeLcom(T_LCOM_D& rLoadComb)
{
	if ( rLoadComb.LoadCombType == 1 )return TRUE;  // Envelope
	return IncludeEnvlopeLcom(rLoadComb);
}

BOOL CAttrCtrl::IncludeEnvlopeLcom(T_LCOM_D& rLoadComb)
{
	for (int i = 0; i < rLoadComb.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = rLoadComb.aCombination[i];
		int nLoadCaseKey = rLcomBase.LoadCaseKey;
		if (nLoadCaseKey == 0)break;
		int nAnalType = rLcomBase.AnalType;
		if (Get_CombType(nLoadCaseKey, nAnalType) == 1)
		{
			return TRUE;
		}
	}
	return FALSE;
}

int CAttrCtrl::Get_CombType(unsigned int nLcaseKey, int nAnalType)
{
	// Distinguish Envelope from SRSS.
	// return 0=Add(Default), 1=Envelope, 2=ABS, 3=SRSS.
	int nLcomType=0;
	if     (nAnalType==D_LCOM_CB_STEEL)			nLcomType = D_LCOMTYPE_STEEL;
	else if(nAnalType==D_LCOM_CB_CONCRETE)	nLcomType = D_LCOMTYPE_CONCRETE;
	else if(nAnalType==D_LCOM_CB_SRC)				nLcomType = D_LCOMTYPE_SRC;
	else if(nAnalType==D_LCOM_CB_ALUMINUM)	nLcomType = D_LCOMTYPE_ALUMINUM;
	else if(nAnalType==D_LCOM_CB_STLCOMP)	  nLcomType = D_LCOMTYPE_STLCOMP;
	else if(nAnalType==D_LCOM_CB_CFSTEEL)	  nLcomType = D_LCOMTYPE_CFSTEEL;
	else if(nAnalType==D_LCOM_CB_SEISMIC)	  nLcomType = D_LCOMTYPE_SEISMIC;
	else if(nAnalType==D_LCOM_CB_LINEAR_EVAL)	  nLcomType = D_LCOMTYPE_LINEAR_EVAL;
	else	return 0;

	T_LCOM_D LcomD;
	if(!m_pDoc->m_pAttrCtrl->GetLcom(nLcomType,nLcaseKey,LcomD))	{ASSERT(0); return 0;}
	return LcomD.LoadCombType;
}

BOOL CAttrCtrl::IsOnlySgldComb(int nLcomType, T_LCOM_D& rData)
{
	T_LCOM_D LcomData;
	for (int i = 0; i < rData.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = rData.aCombination[i];
		if (rLcomBase.LoadCaseKey == 0) break;
		switch(rLcomBase.AnalType)
		{
		case D_LCOM_STATIC		:
		case D_LCOM_SPECTRUM	:
		case D_LCOM_SPECTRUM_ND	:
		case D_LCOM_HISTORY		:
		case D_LCOM_MOVING		:
		case D_LCOM_SETTLEMENT	:
		case D_LCOM_CRANE		:
		case D_LCOM_PUSHOVER	:
		case D_LCOM_ENVELOPE	:
		case D_LCOM_ECCENSPEC	:
		case D_LCOM_ECCENSPEC_ND:
		case D_LCOM_GRIDMODEL	:
		case D_LCOM_THEX		:
		case D_LCOM_THAM		:
		case D_LCOM_THPO		:
			return FALSE;
		case D_LCOM_CB_GENERAL	:
		case D_LCOM_CB_STEEL	:
		case D_LCOM_CB_CONCRETE	:
		case D_LCOM_CB_FOOTING	:
		case D_LCOM_CB_SRC		:
		case D_LCOM_CB_ALUMINUM	:
		case D_LCOM_CB_STLCOMP	:
			if (!GetLcom(nLcomType, rLcomBase.LoadCaseKey, LcomData)) return FALSE;
			if (!IsOnlySgldComb(nLcomType, LcomData)) return FALSE;
			break;
		case D_LCOM_STAGE		:
			break;
		}
	}
	return TRUE;
}

BOOL CAttrCtrl::NormalizeLcom(const T_LCOM_D& rData, T_LCOM_D_UL& rNormLcom, BOOL bOnlyAdd)
{
	// Concrete SRSS Normalize 안해야 함.
	// 근데 Concrete인지 구분이 안 됨(추가 매개변수 필요)

	if (bOnlyAdd && rData.LoadCombType != 0) return FALSE;  // Add만 가능
	rNormLcom = rData;
	return NormalizeCombination(rNormLcom);
}

BOOL CAttrCtrl::NormalizeCombination(T_LCOM_D_UL& rData)
{
	int nCaseNum = rData.Combination.GetSize();
	int nPos;
	int nLcomType;
	T_LCOM_D TempLcom;
	T_LCOM_D_UL LcomUL, TempLcomUL;
	LcomUL.Combination.RemoveAll();
	for (int i = 0; i < nCaseNum; i++)
	{
		ASSERT(rData.Combination[i].LoadCaseKey != 0);

		switch(rData.Combination[i].AnalType)
		{
		case D_LCOM_CB_GENERAL  : nLcomType = D_LCOMTYPE_GENERAL;   break;
		case D_LCOM_CB_STEEL    : nLcomType = D_LCOMTYPE_STEEL;     break;
		case D_LCOM_CB_CONCRETE : nLcomType = D_LCOMTYPE_CONCRETE;  break;
		case D_LCOM_CB_SRC      : nLcomType = D_LCOMTYPE_SRC;       break;
		case D_LCOM_CB_FOOTING  : nLcomType = D_LCOMTYPE_FDN;       break;
		case D_LCOM_CB_ALUMINUM : nLcomType = D_LCOMTYPE_ALUMINUM;  break;
		case D_LCOM_CB_STLCOMP  : nLcomType = D_LCOMTYPE_STLCOMP;   break;
		case D_LCOM_CB_CFSTEEL  : nLcomType = D_LCOMTYPE_CFSTEEL;   break;
		case D_LCOM_CB_SEISMIC  : nLcomType = D_LCOMTYPE_SEISMIC;   break;
		case D_LCOM_CB_LINEAR_EVAL  : nLcomType = D_LCOMTYPE_LINEAR_EVAL;   break;
		default                 : nLcomType = -1;                   break;
		}

		if (nLcomType == -1)  // 일반 하중 Case
		{
			TempLcomUL.Combination.RemoveAll();
			TempLcomUL.Combination.SetAtGrow(0, rData.Combination[i]);
		}
		else // 하중 조합 
		{
			if (!GetLcom(nLcomType, rData.Combination[i].LoadCaseKey, TempLcom)) { ASSERT(0); return FALSE; }
			// Concrete SRSS는 Normalize안함
			// Steel,SRC도 SRSS 추가되면서 Normalize 안함
			if ((TempLcom.LoadCombType == 3 || TempLcom.LoadCombType == 1) &&
				(nLcomType == D_LCOMTYPE_CONCRETE ||
				nLcomType == D_LCOMTYPE_STEEL     ||
				nLcomType == D_LCOMTYPE_SRC       ||
				nLcomType == D_LCOMTYPE_STLCOMP   ||
				nLcomType == D_LCOMTYPE_CFSTEEL   ||
				nLcomType == D_LCOMTYPE_SEISMIC   ||
                nLcomType == D_LCOMTYPE_LINEAR_EVAL))
			{
				// 일반 하중 케이스처럼 취급
				nLcomType = -1;  
				TempLcomUL.Combination.RemoveAll();
				TempLcomUL.Combination.SetAtGrow(0, rData.Combination[i]);
			}
			else
			{
				if (TempLcom.LoadCombType != 0) return FALSE;  // Add만 가능
				TempLcomUL = TempLcom;
				if (!NormalizeCombination(TempLcomUL)) return FALSE;
			}
		}
		int nTempCaseNum = TempLcomUL.Combination.GetSize();
		for (int j = 0; j < nTempCaseNum; j++)
		{
			ASSERT(TempLcomUL.Combination[j].LoadCaseKey != 0);
			if (nLcomType != -1)  // combination에서 Normalize된 것이면 Factor 곱한다.
				TempLcomUL.Combination[j].Factor *= rData.Combination[i].Factor;
			nPos = FindCasePos(LcomUL, TempLcomUL.Combination[j].AnalType, TempLcomUL.Combination[j].LoadCaseKey);
			if (nPos == -1) // new case
			{
				LcomUL.Combination.Add(TempLcomUL.Combination[j]);
			}
			else  // existing case
			{
				LcomUL.Combination[nPos].Factor += TempLcomUL.Combination[j].Factor;
			}
		}
	}
	rData.Combination.Copy(LcomUL.Combination);
	return TRUE;
}

int CAttrCtrl::GetLcomRSESOnlyCombined(const int &nLcomType, const T_SPLC_K &SplcK, CArray<T_LCOM_K, T_LCOM_K> &raKeyList)
{
	raKeyList.RemoveAll();
	T_SPLC_D SplcD;
	if(!GetSplc(SplcK, SplcD)) return 0;
	if(!SplcD.bConsiderEccen) return 0;

	T_LCOM_K LcomK;
	T_LCOM_D LcomD;
	POSITION pos = GetStartLcom(nLcomType);
	while(pos)
	{
		GetNextLcom(nLcomType, pos, LcomK, LcomD);
		if(LcomD.aCombination.GetSize() < 2) continue;
		if(LcomD.aCombination[0].LoadCaseKey==0 || LcomD.aCombination[1].LoadCaseKey==0 /*|| LcomD.aCombination[2].LoadCaseKey!=0*/) continue;
		if(!(LcomD.aCombination[0].AnalType==D_LCOM_SPECTRUM && LcomD.aCombination[0].LoadCaseKey==SplcK) &&
			!(LcomD.aCombination[1].AnalType==D_LCOM_SPECTRUM && LcomD.aCombination[1].LoadCaseKey==SplcK))
			continue;

		if(!(LcomD.aCombination[0].AnalType==D_LCOM_ECCENSPEC && LcomD.aCombination[0].LoadCaseKey==SplcK) &&
			!(LcomD.aCombination[1].AnalType==D_LCOM_ECCENSPEC && LcomD.aCombination[1].LoadCaseKey==SplcK))
			continue;

		raKeyList.Add(LcomK);
	}
	raKeyList.FreeExtra();

	return raKeyList.GetSize();
}

CString CAttrCtrl::GetActivName4MDL(int nActive)
{
	// Gen 제품이 디폴트. Civil에 대한 처리는 사용처에서 처리되어 있음
	switch (nActive)
	{
	case EN_DGN_NONE	: return _LS(IDS_MAIN_MDL_INACTIVE);
	case EN_DGN_STRN	: return _LS(IDS_MAIN_MDL_ACTIVE);
	case EN_DGN_SERV	: return _LS(IDS_MAIN_MDL_SERVICE);
	case EN_DGN_SPEC	: return _LS(IDS_MAIN_MDL_SPECIAL);
	case EN_DGN_VERT	: return _LS(IDS_MAIN_MDL_VERTICAL);
	case EN_DGN_STRE	: return _LS(IDS_MAIN_MDL_ELASTIC_STRNGTH);
	case EN_DGN_UG_STRN	: return _LS(IDS_MAIN_MDL_UG_STRENGTH);
	case EN_DGN_UG_SERV	: return _LS(IDS_MAIN_MDL_UG_SERVICE);
	case EN_DGN_UG_SPEC	: return _LS(IDS_MAIN_MDL_UG_SPECIAL);
	default:
		ASSERT(0);
		break;
	}
	return _T("");
}

BOOL CAttrCtrl::CheckAndDeleteEccenSpecLCase(T_LCOM_D& rData)
{
	BOOL bDelete = FALSE;

	for (int i = 0; i < rData.aCombination.GetSize(); i++)
	{
		T_LCOM_BASE& rLcomBase = rData.aCombination[i];
		if (rLcomBase.LoadCaseKey == 0)break;
		if (rLcomBase.AnalType == D_LCOM_ECCENSPEC || rLcomBase.AnalType == D_LCOM_ECCENSPEC_ND)
		{
			T_SPLC_D SplcD; SplcD.Initialize();
			if (!GetSplc(rLcomBase.LoadCaseKey, SplcD)) ASSERT(0);

			if (SplcD.bConsiderEccen) continue;

			for (int j = i; j < rData.aCombination.GetSize() - 1; j++)
			{
				rData.aCombination[j] = rData.aCombination[j + 1];
			}
				
			rData.aCombination.RemoveAt(rData.aCombination.GetSize() - 1);
			i--;

			bDelete = TRUE;
		}
	}

	return bDelete;
}

BOOL CAttrCtrl::IsLCombWithWind(T_LCOM_D& LcomD)
{
	T_LCOM_D_UL LcomD_UL; LcomD_UL.Initialize();
	if (!NormalizeLcom(LcomD,LcomD_UL)) { ASSERT(0); return FALSE; }

	int nBaseSize = LcomD_UL.Combination.GetSize();
	for (int i=0; i<nBaseSize; ++i)
	{
		T_LCOM_BASE &LcomBase = LcomD_UL.Combination[i];

		T_KEY LCaseK = LcomBase.LoadCaseKey;
		T_STLD_D LCaseD;
		if(!m_pDoc->m_pPostCtrl->GetStld(LCaseK, LCaseD)) { ASSERT(0); continue; }

		if (LCaseD.LoadCaseType == _T("W"))
			return TRUE;
	}

	return FALSE;
}

BOOL CAttrCtrl::IsLCombWithEQ(T_LCOM_D& LcomD)
{
	T_LCOM_D_UL LcomD_UL; LcomD_UL.Initialize();
	if (!NormalizeLcom(LcomD,LcomD_UL)) { ASSERT(0); return FALSE; }

	int nBaseSize = LcomD_UL.Combination.GetSize();
	for (int i=0; i<nBaseSize; ++i)
	{
		T_LCOM_BASE &LcomBase = LcomD_UL.Combination[i];
		if (LcomBase.AnalType == D_LCOM_SPECTRUM ) return TRUE;
		if (LcomBase.AnalType == D_LCOM_ECCENSPEC) return TRUE;

		T_KEY LCaseK = LcomBase.LoadCaseKey;
		T_STLD_D LCaseD;
		if(!m_pDoc->m_pPostCtrl->GetStld(LCaseK, LCaseD)) { ASSERT(0); continue; }

		if (LCaseD.LoadCaseType == _T("E"))
			return TRUE;
	}

	return FALSE;
}

BOOL CAttrCtrl::IsStaticLCComb(T_LCOM_D& LcomD)
{
	T_LCOM_D_UL LcomD_UL; LcomD_UL.Initialize();
	if(!NormalizeLcom(LcomD,LcomD_UL))	{ASSERT(0); return FALSE;}

	int nBaseSize = LcomD_UL.Combination.GetSize();
	for(int k = 0; k < nBaseSize; k++)
	{
		T_LCOM_BASE LcomBase = LcomD_UL.Combination[k];
		if(LcomBase.AnalType != D_LCOM_STATIC)    
			return FALSE;
	}
	return TRUE;
}

int CAttrCtrl::FindCasePos(T_LCOM_D_UL& rData, int nAnalType, int nLoadCaseKey)
{
	int nCaseNum = rData.Combination.GetSize();
	for (int i = 0; i < nCaseNum; i++)
	{
		if (rData.Combination[i].LoadCaseKey == 0) break;
		if (rData.Combination[i].AnalType == nAnalType &&
			rData.Combination[i].LoadCaseKey == nLoadCaseKey) return i;
	}
	return -1;
}

void CAttrCtrl::GetSeizEvalLcomType(T_LCOM_D& LcomD, int& nRs, int& nTh)
{
	int nLcomType = 0;
	for (int j = 0; j < LcomD.aCombination.GetSize(); j++)
	{
		nLcomType = LcomD.aCombination[j].AnalType;
		if (nLcomType == D_LCOM_SPECTRUM || nLcomType == D_LCOM_SPECTRUM_ND)
			nRs += 1;
		else if (nLcomType == D_LCOM_HISTORY)
			nTh += 1;
	}
}


////////////// envl ////////////////
void CAttrCtrl::GetEnvlList(CArray<CString, CString&>& rstrEnvlList)
{
	rstrEnvlList.RemoveAll();

	int nCount=GetCountEnvl();
	if(nCount == 0)return;

	POSITION pos;
	T_ENVL_K Key;
	T_ENVL_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartEnvl();
		while(pos != NULL)
		{
			GetNextEnvl(pos, Key, Data);
			if(Data.EnvelopeId == i)
			{
				rstrEnvlList.Add(Data.EnvelopeName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetEnvlKeyList(CArray<T_ENVL_K, T_ENVL_K>& rEnvlKeyList)
{
	/*
	rEnvlKeyList.RemoveAll();

	int nCount=GetCountEnvl();
	if(nCount == 0)return;

	POSITION pos;
	T_ENVL_K Key;
	T_ENVL_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartEnvl();
	while(pos != NULL)
	{
	GetNextEnvl(pos, Key, Data);
	if(Data.EnvelopeId == i)
	{
	rEnvlKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rEnvlKeyList.RemoveAll();
	int nCount=GetCountEnvl();
	if(nCount == 0)return;

	CArray<T_ENVL_K, T_ENVL_K> aEnvlKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rEnvlKeyList.SetSize(nCount);
	aEnvlKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_ENVL_K Key;
	T_ENVL_D Data;
	int i = 0;
	pos = GetStartEnvl();
	while (pos != NULL)
	{
		GetNextEnvl(pos, Key, Data);
		aEnvlKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.EnvelopeId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rEnvlKeyList[i] = aEnvlKey[ix];
	}
}

BOOL CAttrCtrl::ExistEnvl(CString& rEnvelopeName)
{
	T_ENVL_D data;
	return GetEnvl(rEnvelopeName, data);
}

BOOL CAttrCtrl::ExistEnvl(T_ENVL_K Key)
{
	T_ENVL_D data;
	return GetEnvl(Key, data);
}

BOOL CAttrCtrl::GetEnvl(CString& rEnvelopeName, T_ENVL_D& rData)
{
	T_ENVL_K key;
	T_ENVL_D data;
	CString strEnvelopeName=rEnvelopeName;
	strEnvelopeName.TrimRight();

	POSITION pos;
	pos=m_pDataMemb->m_envl.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_envl.GetNext(pos,key,data);
		if(strEnvelopeName.CompareNoCase(data.EnvelopeName) == 0)
		{
			m_pUnitCtrl->ConvertUnitEnvlOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetEnvl(T_ENVL_K Key, T_ENVL_D& rData)
{
	BOOL bReturn;
	bReturn=m_pDataMemb->m_envl.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitEnvlOut(rData);
	return bReturn;
}

T_ENVL_K CAttrCtrl::GetEnvlKey(CString& rEnvelopeName)
{
	T_ENVL_K key;
	T_ENVL_D data;

	POSITION pos=GetStartEnvl();
	while(pos != NULL)
	{
		GetNextEnvl(pos,key,data);
		if(rEnvelopeName.CompareNoCase(data.EnvelopeName) == 0)return key;
	}
	key=0;
	return key;
}

