BOOL CAttrCtrl::GetLctb(CString& rLctbName, T_LCTB_D& rData)
{
	T_LCTB_K key;
	T_LCTB_D data;
	CString strLctbName=rLctbName;
	strLctbName.TrimRight();

	POSITION pos;
	pos=m_pDataMemb->m_lctb.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_lctb.GetNext(pos,key,data);
		if(strLctbName.CompareNoCase(data.strLctbName) == 0)
		{
			m_pUnitCtrl->ConvertUnitLctbOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

