T_LCTB_K CAttrCtrl::GetLctbKey(CString& rLctbName)
{
	T_LCTB_K key;
	T_LCTB_D data;

	POSITION pos=GetStartLctb();
	while(pos != NULL)
	{
		GetNextLctb(pos,key,data);
		if(rLctbName.CompareNoCase(data.strLctbName) == 0)return key;
	}
	key=0;
	return key;
}

BOOL CAttrCtrl::GetLctbKeyFromStldKey(T_STLD_K StldKey, T_LCTB_K& LctbKey)
{
	T_LCTB_K Key;
	T_LCTB_D Data;
	POSITION pos = GetStartLctb();
	while(pos)
	{
		GetNextLctb(pos, Key, Data);
		if(Data.StldKey == StldKey) 
		{
			LctbKey = Key;
			return TRUE;
		}
	}
	return FALSE;
}

