BOOL CAttrCtrl::MakeKeyBodf(T_STLD_K KeyStld,T_LDGR_K KeyLdgr,T_BODF_K& rKey)
{
	T_BODF_K Key;
	T_BODF_D Data;
	POSITION pos = GetStartBodf();
	while (pos)
	{
		GetNextBodf(pos, Key, Data);
		if (Data.LoadCaseKey == KeyStld && Data.GroupKey == KeyLdgr)
		{
			rKey = Key;
			return TRUE;
		}
	}
	rKey = GetStartNumBodf();
	return TRUE;
}

