void CAttrCtrl::CalcNbofLoad(T_NBOF_K Key,T_NBOF_D& rData, CArray<T_CNLD_UDRD_D, T_CNLD_UDRD_D&>& arNbofLoad)
{ 
	arNbofLoad.RemoveAll();
	//if(GetCountNbof() == 0) return;

	CDB_NMAS NmasPool;  
	NmasPool.m_pDoc = NULL;    
	T_NODE_K KeyNode;
	T_NODE_D DataNode;
	T_NMAS_K KeyNmas;
	T_NMAS_D DataNmas,DataNmas2;
	T_CNLD_UDRD_D DataCnld;
	POSITION pos;
	BOOL bUseBedrockLevel = m_pDoc->m_pAttrCtrl->IsUseBedrockLevel();

	T_BLDC_D BldcData;
	if(!GetBldc(BldcData)) BldcData.Initialize();

	CMap<T_NODE_K, T_NODE_K, int, int> mapSelectedNode;
	mapSelectedNode.InitHashTable(m_pDoc->GetHashSizeNode());
	mapSelectedNode.RemoveAll();
	int nTemp;
	CArray<T_NODE_K, T_NODE_K> aNodeK;
	if (rData.bUseGrup)
	{
		T_GRUP_D GrupD;
		GetGrup(rData.GrupKey, GrupD);
		aNodeK.Copy(GrupD.arKeyNode);
	}
	else aNodeK.Copy(rData.arKeyNode);
	for(int i = 0; i < aNodeK.GetSize(); i++)
	{
		KeyNode = aNodeK[i];
		if(!GetNode(KeyNode, DataNode)) continue;
		if(m_pDoc->m_pAttrCtrl->IsUseBedrockLevel())
		{
			if (DataNode.z <= BldcData.dBedrockLevel) continue;
		}
		else
		{
			if (BldcData.bUseBaseLevel)   // Ground Level 이하의 절점에 대해서는 NBOF를 생성하지 않음
				if (DataNode.z <= BldcData.dBaseLevel) continue;
		}
		
		if(!mapSelectedNode.Lookup(KeyNode, nTemp))
			mapSelectedNode.SetAt(KeyNode, 1);
	}

	T_STYP_D DataStyp;    
	if(!GetStyp(DataStyp)) 
	{
		DataStyp.Initialize();
		DataStyp.dblGravity = m_pDoc->m_pInitCtrl->DefaultGravity();
	}

	if(rData.bStructMass)  // Structure Mass
	{
		if(DataStyp.nMassType != 0)
		{
			CSelfWgt CalcWeight(m_pDoc);
			CMap<T_NODE_K, T_NODE_K, double ,double> mapMassOnNode;
			mapMassOnNode.InitHashTable(HASHSIZENODE);

			CalcWeight.CalcNodalMass(mapMassOnNode);

			double dMass;
			pos = mapMassOnNode.GetStartPosition();
			while(pos != NULL)
			{
				mapMassOnNode.GetNextAssoc(pos, KeyNode, dMass);
				if(!mapSelectedNode.Lookup(KeyNode, nTemp)) continue;
				DataNmas.Initialize();
				if(DataStyp.nMassType == 1) // Lumped Mass
				{
					if(DataStyp.bConvertSelfWeight)
					{
						if(DataStyp.nStructureMass == 1)
						{
							DataNmas.Mass[0]=dMass;
							DataNmas.Mass[1]=dMass;
							DataNmas.Mass[2]=dMass;
						}
						else if(DataStyp.nStructureMass == 2)
						{
							DataNmas.Mass[0]=dMass;
							DataNmas.Mass[1]=dMass;
						}
						else if(DataStyp.nStructureMass == 3)
						{
							DataNmas.Mass[2]=dMass;
						}
					}
				}
				else if(DataStyp.nMassType == 2)  // Consistent Mass : X, Y, Z 방향 모두 고려
				{
					DataNmas.Mass[0]=dMass;
					DataNmas.Mass[1]=dMass;
					DataNmas.Mass[2]=dMass;
				}
				if(NmasPool.Get(KeyNode, DataNmas2))
				{
					for(int i = 0; i < 3; i++) DataNmas.Mass[i] += DataNmas2.Mass[i];
				}
				NmasPool.Add(KeyNode, DataNmas, NULL);
			}
		}
	}

	if(rData.bNodalMass)  // Nodal Mass
	{
		if(GetCountNmas() > 0) 
		{
			pos = GetStartNmas();
			while(pos != NULL)
			{
				DataNmas.Initialize();
				GetNextNmas(pos, KeyNmas, DataNmas);
				KeyNode = KeyNmas;
				if(!mapSelectedNode.Lookup(KeyNode, nTemp)) continue;                
				if(NmasPool.Get(KeyNode, DataNmas2))
				{
					for(int i = 0; i < 3; i++) DataNmas.Mass[i] += DataNmas2.Mass[i];
				}      
				NmasPool.Add(KeyNode, DataNmas, NULL);
			}
		}
	}

	if(rData.bLoadToMass)    // Load to Mass
	{
		T_LTOM_D DataLtom; 
		if(GetLtom(DataLtom))
		{
			CArray<T_NMAS_UDRD_D, T_NMAS_UDRD_D&> arNmasData;
			m_pDoc->calcLoadToMass(DataLtom, arNmasData);
			int nCount = arNmasData.GetSize();
			for(int j = 0; j < nCount; j++)
			{
				DataNmas = arNmasData[j].data;
				KeyNmas  = arNmasData[j].key;
				KeyNode  = KeyNmas;
				if(!mapSelectedNode.Lookup(KeyNode, nTemp)) continue;

				if(NmasPool.Get(KeyNode, DataNmas2))
				{
					for(int i = 0; i < 3; i++) DataNmas.Mass[i] += DataNmas2.Mass[i];
				}      
				NmasPool.Add(KeyNode, DataNmas, NULL);
			}
		}
	}

	if(rData.bGridMass)  // Grid Mass
	{
		if(GetCountGmas() > 0) 
		{
			T_GMAS_K KeyGmas;
			T_GMAS_D DataGmas;
			pos = GetStartGmas();
			while(pos != NULL)
			{
				DataNmas.Initialize();
				GetNextGmas(pos, KeyGmas, DataGmas);
				KeyNode = KeyGmas;
				for(int i = 0; i < 3; i++) DataNmas.Mass[i] = DataGmas.Mass[i];
				if(!mapSelectedNode.Lookup(KeyNode, nTemp)) continue;                
				if(NmasPool.Get(KeyNode, DataNmas2))
				{
					for(int i = 0; i < 3; i++) DataNmas.Mass[i] += DataNmas2.Mass[i];
				}      
				NmasPool.Add(KeyNode, DataNmas, NULL);
			}
		}
	}

	DataCnld.data.Initialize();
	DataCnld.data.GroupKey = rData.LdgrKey;
	DataCnld.data.LoadCaseKey = rData.LoadCaseKey;
	pos = NmasPool.GetStart();
	while(pos)
	{    
		NmasPool.GetNext(pos, KeyNmas, DataNmas);
		DataCnld.key.key.entity = KeyNmas;
		DataCnld.data.Force[0] = DataNmas.Mass[0] * DataStyp.dblGravity * rData.dFactorX;
		DataCnld.data.Force[1] = DataNmas.Mass[1] * DataStyp.dblGravity * rData.dFactorY;
		DataCnld.data.Force[2] = DataNmas.Mass[2] * DataStyp.dblGravity * rData.dFactorZ;
		arNbofLoad.Add(DataCnld);    
	}

	if(arNbofLoad.GetSize() == 0) return;  
}

void CAttrCtrl::CalcNbofLoadLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, T_NBOF_K KeyNbof, CArray<T_CNLD_UDRD_D, T_CNLD_UDRD_D&>& arNbofLoad)
{
	arNbofLoad.RemoveAll();  
	if(!CheckLcomLabel(bAllLoadCase, DataLcom)) return;
	if(GetCountNbof() == 0) return;

	T_NBOF_K Key;
	T_NBOF_D DataNbof;  
	CArray<T_CNLD_UDRD_D, T_CNLD_UDRD_D&> arNbofCnld;
	CMap<T_NODE_K, T_NODE_K, T_CNLD_D, T_CNLD_D&> mapNbofLoad;
	mapNbofLoad.InitHashTable(HASHSIZESTLD); 
	POSITION pos=GetStartNbof();
	while(pos != NULL)
	{
		GetNextNbof(pos, Key, DataNbof);
		if (KeyNbof != 0 && KeyNbof != Key) continue;
		CalcNbofLoad(Key, DataNbof, arNbofCnld);		
		double dFactor=1.;
		if(bAllLoadCase)
		{
			arNbofLoad.Copy(arNbofCnld);      
		}
		else
		{
			double dStldFactor=0., dStagFactor=0.;
			if(!GetLcomStldFactor(DataNbof.LoadCaseKey, DataLcom, dStldFactor, dStagFactor)) return;  
			if(dStldFactor == 0.) continue;
			BOOL bNonZero=FALSE;
			for(int i = 0; i < arNbofCnld.GetSize(); i++)
			{        
				T_CNLD_UDRD_D DataCnld = arNbofCnld[i];
				T_CNLD_D data = arNbofCnld[i].data;        
				for(int j = 0; j < 3; j++)
				{
					data.Force[j] *= dStldFactor;
					if(data.Force[j] != 0.) bNonZero = TRUE;
				}
				DataCnld.data = data;
				if(bNonZero) arNbofLoad.Add(DataCnld);
			}      
		}
	}
}

