BOOL CAttrCtrl::GetCnldTypeList(T_STLD_K KeyStld,CArray<T_CNLD_D, T_CNLD_D &>& aData,CArray<CArrayEx<T_CNLD_KEY,T_CNLD_KEY&>, CArrayEx<T_CNLD_KEY,T_CNLD_KEY&>&>& aArrCnldK)
{
	aData.RemoveAll();
	aArrCnldK.RemoveAll();
	T_CNLD_K CnldKey;
	T_CNLD_D Data;
	CArrayEx<T_CNLD_KEY,T_CNLD_KEY&> aCnldKey;
	POSITION pos = m_pDataMemb->m_cnld.GetTypeStart();
	CString strKey;
	CnldTypeList* pData = 0;
	while(pos)
	{
		m_pDataMemb->m_cnld.GetTypeNext(pos,strKey,pData);
		ASSERT(!pData->IsEmpty());
		CnldKey.keymap = pData->GetAt(0);
		m_pDataMemb->m_cnld.Get(CnldKey,Data);
		m_pUnitCtrl->ConvertUnitCnldOut(Data);
		if(Data.LoadCaseKey == KeyStld)
		{
			aData.Add(Data);
			aCnldKey.RemoveAll();
			aCnldKey.Copy(*pData);
			aArrCnldK.Add(aCnldKey);
		}
	}
	return TRUE;
}

