BOOL CAttrCtrl::GetSdspLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, BOOL bAllLdgr, CArray<T_LDGR_K, T_LDGR_K>& raLdgrKey, T_NODE_K KeyNode, T_SDSP_D& DataSdsp)
{
	DataSdsp.Initialize();
	if(!CheckLcomLabel(bAllLoadCase, DataLcom))return FALSE;

	CMap<T_LDGR_K, T_LDGR_K, T_LDGR_K, T_LDGR_K> mapLdgr;
	if (!bAllLdgr)
	{
		mapLdgr.InitHashTable(11);
		for (int i = 0; i < raLdgrKey.GetSize(); i++)mapLdgr.SetAt(raLdgrKey[i], raLdgrKey[i]);
	}

	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_SDSP_CMD)
		{
			T_SDSP_K key;
			T_SDSP_D data;
			key.keymap=ListData.nKey;
			GetSdsp(key, data);
			if (!bAllLdgr && !mapLdgr.Lookup(data.GroupKey, data.GroupKey)) continue;
			if(bAllLoadCase)
			{
				for(int i=0; i<6; i++)
				{
					if(data.Flag[i] == '1')
					{
						DataSdsp.Flag[i]='1';
						DataSdsp.Displacement[i]+=data.Displacement[i];
					}
				}
			}
			else
			{
				double dStldFactor=0., dStagFactor=0.;
				if(!GetLcomStldFactor(data.LoadCaseKey, DataLcom, dStldFactor, dStagFactor))return FALSE;  
				T_STLD_D DataStld;
				if(dStldFactor != 0.)
				{
					for(int j=0; j<6; j++)
					{
						if(data.Flag[j] == '1')
						{
							DataSdsp.Flag[j]='1';
							DataSdsp.Displacement[j]+=data.Displacement[j]*dStldFactor;
						}
					}
				}
				if(dStagFactor != 0. && m_pDoc->m_pStagCtrl->IsActiveLdgrKey(data.GroupKey))
				{
					for(int j=0; j<6; j++)
					{
						if(data.Flag[j] == '1')
						{
							DataSdsp.Flag[j]='1';
							DataSdsp.Displacement[j]+=data.Displacement[j]*dStagFactor;
						}
					}
				}
			}
		}
	}
	for(int i=0; i<6; i++)
	{
		if(DataSdsp.Flag[i] != '0')return TRUE;
	}
	return FALSE;
}

