BOOL CAttrCtrl::MakeKeyBmld(T_ELEM_K Key,T_BMLD_K& rKey, BOOL bUseTempStore/*=FALSE*/)
{
	rKey.key.entity=Key;
	rKey.key.serial=0;

	T_BMLD_KEY KeySerial=0;
	if(bUseTempStore) CTempDataStore_GetBmldLastSerial::GetInstance()->Get(Key, KeySerial);

	if(!GetSerialBmld(Key, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	if(bUseTempStore) CTempDataStore_GetBmldLastSerial::GetInstance()->ReplaceSet(Key, KeySerial);
	return TRUE;
}

