void CAttrCtrl::GetBmld(T_ELEM_K KeyElem, CArray<T_BMLD_K, T_BMLD_K>& rarKey, CArray<T_BMLD_D, T_BMLD_D&>& rarData)
{
	rarKey.RemoveAll();
	rarData.RemoveAll();

	int nEntity = 0;
	CArray<int, int> aSerial; aSerial.RemoveAll();

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_BMLD_CMD)
		{
			T_BMLD_K key;
			key.keymap=ListData.nKey;

			nEntity = key.key.entity;
			aSerial.Add(key.key.serial);

			//       GetBmld(key, data);
			//       rarKey.Add(key);
			//       rarData.Add(data);
		}
	}

	CQSort::QSortInt((int*)aSerial.GetData(), aSerial.GetSize());

	T_BMLD_K BmldK;
	BmldK.key.entity = nEntity;
	for (int i=0; i<aSerial.GetSize(); i++)
	{
		T_BMLD_D data;
		BmldK.key.serial = aSerial[i];
		GetBmld(BmldK, data);
		rarKey.Add(BmldK);
		rarData.Add(data);
	}
}

void CAttrCtrl::GetBmldLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, BOOL bAllLdgr, CArray<T_LDGR_K, T_LDGR_K>& raLdgrKey, T_ELEM_K KeyElem, CArray<T_BMLD_D, T_BMLD_D&>& rarData)
{
	rarData.RemoveAll();
	if(!CheckLcomLabel(bAllLoadCase, DataLcom))return;

	CMap<T_LDGR_K, T_LDGR_K, T_LDGR_K, T_LDGR_K> mapLdgr;
	if (!bAllLdgr)
	{
		mapLdgr.InitHashTable(11);
		for (int i = 0; i < raLdgrKey.GetSize(); i++)mapLdgr.SetAt(raLdgrKey[i], raLdgrKey[i]);
	}

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_BMLD_CMD)
		{
			T_BMLD_K key;
			T_BMLD_D data;
			key.keymap=ListData.nKey;
			GetBmld(key, data);
			if (!bAllLdgr && !mapLdgr.Lookup(data.GroupKey, data.GroupKey)) continue;
			if(bAllLoadCase)
			{
				rarData.Add(data);
			}
			else
			{
				double dStldFactor=0., dStagFactor=0.;
				if(!GetLcomStldFactor(data.LoadCaseKey, DataLcom, dStldFactor, dStagFactor))return;  
				T_STLD_D DataStld;
				if(dStldFactor != 0.)
				{
					BOOL bNonZero=FALSE;
					T_BMLD_D DataBmld=data;
					for(int j=0; j<4; j++)
					{
						DataBmld.Force_Type[DataBmld.LoadType-1][j]=data.Force_Type[data.LoadType-1][j]*dStldFactor;
						if(DataBmld.Force_Type[DataBmld.LoadType-1][j] != 0.)bNonZero=TRUE;
					}
					if(bNonZero)rarData.Add(DataBmld);
				}
				if(dStagFactor != 0. && m_pDoc->m_pStagCtrl->IsActiveLdgrKey(data.GroupKey))
				{
					BOOL bNonZero=FALSE;
					T_BMLD_D DataBmld=data;
					for(int j=0; j<4; j++)
					{
						DataBmld.Force_Type[DataBmld.LoadType-1][j]=data.Force_Type[data.LoadType-1][j]*dStagFactor;
						if(DataBmld.Force_Type[DataBmld.LoadType-1][j] != 0.)bNonZero=TRUE;
					}
					if(bNonZero)rarData.Add(DataBmld);
				}
			}
		}
	}
	return;
}

int CAttrCtrl::GetCountBmld()
{
	return m_pDataMemb->m_bmld.GetCount();
}

POSITION CAttrCtrl::GetStartBmld()
{
	return m_pDataMemb->m_bmld.GetStart();
}

