{
	m_pDataMemb->m_bmld.GetNext(rNextPosition,rKey,rData);
	m_pUnitCtrl->ConvertUnitBmldOut(rData);
}

void CAttrCtrl::ConvertEccToLocalMoment(T_BMLD_UDRD_D& Bmld, CArray<T_BMLD_UDRD_D, T_BMLD_UDRD_D&>& arBeamLoad)
{
	T_BMLD_K KeyBmld;
	T_BMLD_D DataBmld;
	KeyBmld = Bmld.key;
	DataBmld = Bmld.data;

	// 편심 보하중 고려
	// 편심 보하중을 Moment 하중으로 추가해 준다.
	// 1. 편심을 Local 방향으로의 거리(Dx, Dy, Dz)로 계산
	// 2. 하중을 Local 방향으로의 분력(Px, Py, Pz)으로 계산
	// 3. Rx 모멘트(-Py*Dz), (Pz*Dy)
	// 4. Ry (-Pz*Dx), (Px*Dz) / Rz (-Px*Dy), (Py*Dx)
	// 5. 크기가 0이 아닌 것을 arBeamLoad에 추가
	// 이하 부분에서는 편심 고려하지 않는다. 편심은 여기서만 고려된다.
	if (Bmld.data.bEccentricity == FALSE) return;

	double Dx = 0.0, Dy = 0.0, Dz = 0.0;
	double Dxj = 0.0, Dyj = 0.0, Dzj = 0.0;
	double Px = 0.0, Py = 0.0, Pz = 0.0;
	BOOL bFLV = FALSE;
	double FrameLocalVector[3][3];
	// 편심을 Local 방향으로의 거리(Dx, Dy, Dz)로 계산
	if (DataBmld.nEccenDir < 4)
	{
		if (DataBmld.nEccenDir == 2)Dy = 1.;
		if (DataBmld.nEccenDir == 3)Dz = 1.;
	}
	else if (DataBmld.nEccenDir > 3 && DataBmld.nEccenDir < 7)
	{
		bFLV = TRUE;
		m_pDoc->calcFrameLocalVector(KeyBmld.key.entity, FrameLocalVector, TRUE);
		Dx = FrameLocalVector[0][DataBmld.nEccenDir - 4];
		Dy = FrameLocalVector[1][DataBmld.nEccenDir - 4];
		Dz = FrameLocalVector[2][DataBmld.nEccenDir - 4];
	}
	if (DataBmld.bDistJ)
	{
		Dxj = Dx * DataBmld.dDistJ;
		Dyj = Dy * DataBmld.dDistJ;
		Dzj = Dz * DataBmld.dDistJ;
		Dx *= DataBmld.dDistI;
		Dy *= DataBmld.dDistI;
		Dz *= DataBmld.dDistI;
	}
	else
	{
		Dx *= DataBmld.dDistI;
		Dy *= DataBmld.dDistI;
		Dz *= DataBmld.dDistI;
		Dxj = Dx;
		Dyj = Dy;
		Dzj = Dz;
	}

	// 하중을 Local 방향으로의 분력(Px, Py, Pz)으로 계산
	if (DataBmld.LoadDirection < 4)
	{
		if (DataBmld.LoadDirection == 1)Px = 1.;
		if (DataBmld.LoadDirection == 2)Py = 1.;
		if (DataBmld.LoadDirection == 3)Pz = 1.;
	}
	else if (DataBmld.LoadDirection > 3 && DataBmld.LoadDirection < 7)
	{
		if (!bFLV)
			m_pDoc->calcFrameLocalVector(KeyBmld.key.entity, FrameLocalVector, TRUE);
		Px = FrameLocalVector[0][DataBmld.LoadDirection - 4];
		Py = FrameLocalVector[1][DataBmld.LoadDirection - 4];
		Pz = FrameLocalVector[2][DataBmld.LoadDirection - 4];

		// Global & 분포하중 & 프로젝션인 경우 - 아래 해 주는 계산을 편심에도 적용해 줌
		if (DataBmld.LoadType == 3 && DataBmld.Projection == 1)
		{
			T_ELEM_D DataElem;
			GetElem(KeyBmld.key.entity, DataElem);
			T_NODE_D n1, n2;
			GetNode(DataElem.elnod[0], n1);
			GetNode(DataElem.elnod[1], n2);
			T_OFFS_D DataOffs;
			if (GetOffsElem(KeyBmld.key.entity, DataOffs) && DataOffs.nOffsetType == 1) // global offset
			{
				n1.x += DataOffs.Offset[0];
				n1.y += DataOffs.Offset[1];
				n1.z += DataOffs.Offset[2];
				n2.x += DataOffs.Offset[3];
				n2.y += DataOffs.Offset[4];
				n2.z += DataOffs.Offset[5];
			}
			double dx = n2.x - n1.x;
			double dy = n2.y - n1.y;
			double dz = n2.z - n1.z;

			if (DataBmld.bDistJ) // MNET:XXXX 20070530 mylee - 편심 IJ 다른경우 고려
			{
				double DxG = (Dxj - Dx)*FrameLocalVector[0][0] + (Dyj - Dy)*FrameLocalVector[1][0] + (Dzj - Dz)*FrameLocalVector[2][0];
				double DyG = (Dxj - Dx)*FrameLocalVector[0][1] + (Dyj - Dy)*FrameLocalVector[1][1] + (Dzj - Dz)*FrameLocalVector[2][1];
				double DzG = (Dxj - Dx)*FrameLocalVector[0][2] + (Dyj - Dy)*FrameLocalVector[1][2] + (Dzj - Dz)*FrameLocalVector[2][2];
				dx += DxG; // 편심 IJ 다른 경우 편심 반영
				dy += DyG;
				dz += DzG;
			}
			double bl = sqrt(dx*dx + dy * dy + dz * dz); // 수정된 거리
			double tl = 0.;
			if (DataBmld.LoadDirection == 4)tl = sqrt(dy*dy + dz * dz);
			if (DataBmld.LoadDirection == 5)tl = sqrt(dx*dx + dz * dz);
			if (DataBmld.LoadDirection == 6)tl = sqrt(dx*dx + dy * dy);

			Px *= tl / bl; // 이 세 하중값은 편심에만 영향을 주므로
			Py *= tl / bl;
			Pz *= tl / bl;
		}
	}
	// 편심에서 하중 Vector 방향은 없음

	T_BMLD_D NewBmld;
	double P1, P2, D1, D2, D1j, D2j; P1 = P2 = D1 = D2 = D1j = D2j = 0.0;

	for (int k = 0; k < 3; ++k) // 세 방향에 대해
	{
		if (k == 0) { P1 = Py; P2 = Pz; D1 = Dy; D2 = Dz; D1j = Dyj; D2j = Dzj; }  //  Local x 방향
		if (k == 1) { P1 = Pz; P2 = Px; D1 = Dz; D2 = Dx; D1j = Dzj; D2j = Dxj; }  //  Local y 방향
		if (k == 2) { P1 = Px; P2 = Py; D1 = Dx; D2 = Dy; D1j = Dxj; D2j = Dyj; }  //  Local z 방향

		NewBmld = DataBmld;
		if (DataBmld.LoadType == 1) NewBmld.LoadType = 2;
		else if (DataBmld.LoadType == 3) NewBmld.LoadType = 4;

		if (k == 0) { NewBmld.LoadDirection = 1; } // Rx
		if (k == 1) { NewBmld.LoadDirection = 2; } // Ry
		if (k == 2) { NewBmld.LoadDirection = 3; } // Rz

		NewBmld.bEccentricity = FALSE;
		memset(NewBmld.Force_Type, 0, sizeof(NewBmld.Force_Type));

		// P1, D2에 대해 Moment 계산한다.
		double dDist[4];
		for (int i = 0; i < 4; i++)
		{
			if (DataBmld.bDistJ)  dDist[i] = D2 + (D2j - D2) * DataBmld.DistanceRatio[i];
			else                  dDist[i] = D2;
		}
		BOOL bValid = FALSE;
		for(int i = 0; i < 4; i++)
		{
			if (DataBmld.LoadType == 1)
			{
				NewBmld.Force_Type[1][i] = -P1 * DataBmld.Force_Type[0][i] * dDist[i];
				if (NewBmld.Force_Type[1][i] != 0.0) bValid = TRUE;
			}
			else if (DataBmld.LoadType == 3)
			{
				NewBmld.Force_Type[3][i] = -P1 * DataBmld.Force_Type[2][i] * dDist[i];
				if (NewBmld.Force_Type[3][i] != 0.0) bValid = TRUE;
			}
		}
		if (bValid)
		{
			Bmld.key = KeyBmld;
			Bmld.data = NewBmld;
			Bmld.bLocalM = TRUE;
			arBeamLoad.Add(Bmld);
		}

		// P2, D1에 대해 Moment 계산한다.
		for(int i = 0; i < 4; i++)
		{
			if (DataBmld.bDistJ)  dDist[i] = D1 + (D1j - D1) * DataBmld.DistanceRatio[i];
			else                  dDist[i] = D1;
		}
		bValid = FALSE;
		for(int i = 0; i < 4; i++)
		{
			if (DataBmld.LoadType == 1)
			{
				NewBmld.Force_Type[1][i] = P2 * DataBmld.Force_Type[0][i] * dDist[i];
				if (NewBmld.Force_Type[1][i] != 0.0) bValid = TRUE;
			}
			else if (DataBmld.LoadType == 3)
			{
				NewBmld.Force_Type[3][i] = P2 * DataBmld.Force_Type[2][i] * dDist[i];
				if (NewBmld.Force_Type[3][i] != 0.0) bValid = TRUE;
			}
		}
		if (bValid)
		{
			Bmld.key = KeyBmld;
			Bmld.data = NewBmld;
			Bmld.bLocalM = TRUE;
			arBeamLoad.Add(Bmld);
		}
	} // End of For - 세 방향에 대해 

	Bmld.bLocalM = FALSE; // 이 함수를 벗어나서는 FALSE 처리
}

// MNET:XXXX-HSSHIM-20130731
// 7자유도 보요소의 경우는 Fy, Fz에 대해서 전단중심과 도심과의 차이로 인한 추가 torsion(Mx)를 만들어 주셔야 합니다.(from 박건태 대리)
int CAttrCtrl::ConvertEccToLocalMoment_from7thDOF(CArray<T_BMLD_UDRD_D, T_BMLD_UDRD_D&>& raBeamLoad, BOOL bConsiderSectOffset, BOOL bBeforeComposite)
{
	if (!CSectDB::IsEnable7thDOF())   return raBeamLoad.GetSize();

	double rx, ry, rz;
	T_ELEM_D ElemD;   ElemD.Initialize();
	T_SECT_D SectD;   SectD.Initialize();
	for (int iq = raBeamLoad.GetSize() - 1; iq >= 0; --iq)
	{
		T_ELEM_K ElemK = raBeamLoad[iq].key.key.entity;

		// 7자유도 보요소인가?
		if (!GetElem(ElemK, ElemD)) { ASSERT(0); continue; }
		if (!GetSect(ElemD.elpro, SectD))  continue;
		if (!SectD.SectBefore.bConsiderWarpingEffect)   continue;   // is 7th DOF Sect

																	// GCS 기준 하중으로 치환 
		T_BMLD_UDRD_D BeamLoad_temp = raBeamLoad[iq];
		if (!ConvertBmldToGCS(BeamLoad_temp, rx, ry, rz, bConsiderSectOffset, bBeforeComposite))
		{
			ASSERT(0); continue;
		}

		// Moment로 치환할 하중이 있나?
		BOOL bExistLoad = FALSE;
		if (BeamLoad_temp.data.LoadType == 1)    // 집중 하중 (최대 4개)
		{
			for (int k = 0; k < 4; ++k)
			{
				if (BeamLoad_temp.data.DistanceRatio[k] == 0. && BeamLoad_temp.data.Force_Type[BeamLoad_temp.data.LoadType - 1][k] == 0.)break;

				bExistLoad = TRUE;
				break;
			}
		}
		else if (BeamLoad_temp.data.LoadType == 3)    // 분포 하중 (최대 3개)
		{
			for (int k = 1; k < 4; ++k)
			{
				if (BeamLoad_temp.data.DistanceRatio[k] == 0. && BeamLoad_temp.data.Force_Type[BeamLoad_temp.data.LoadType - 1][k] == 0.)break;

				bExistLoad = TRUE;
				break;
			}
		}
		if (!bExistLoad)  continue;

		// 모멘트 추가 
		BOOL bSrc, bTap;
		int  nLy, nLz;
		const double dTol = 1.0e-12;
		T_SECT_STIFFNESS StiffDataI;
		T_SECT_STIFFNESS StiffDataJ;
		GetSectStiffness(ElemD.elpro, FALSE, bSrc, bTap, nLy, nLz, StiffDataI, StiffDataJ);

		// 도심 -> 전단중심까지의 편심 (local)
		double dEcc_I_y = StiffDataI.dYcy - StiffDataI.dYsy;
		double dEcc_I_z = StiffDataI.dYcz - StiffDataI.dYsz;
		double dEcc_J_y = StiffDataJ.dYcy - StiffDataJ.dYsy;
		double dEcc_J_z = StiffDataJ.dYcz - StiffDataJ.dYsz;

		// tapered인가?
		BOOL bIsTapered = FALSE;    if (SectD.nStype == D_SECT_TYPE_TAPERED) bIsTapered = TRUE;

		// tapered section group으로 묶여있나?
		BOOL bIsTaperedSectGroup = FALSE;
		T_TSGR_D TsgrD;
		double dTsgrTotLength = 0.0, dPositionI = 0.0, dPositionJ = 0.0;
		if (bIsTapered)
		{
			T_TSGR_K TsgrK = GetElemTsgrKey(ElemK);
			if (TsgrK > 0)
			{
				if (GetTsgr(TsgrK, TsgrD)) { bIsTaperedSectGroup = TRUE; }
				else { ASSERT(0); }

				CalcTsgrTotLength(TsgrD, ElemK, dTsgrTotLength, dPositionI);
				//         for(int i=0; i<TsgrD.aElemList.GetSize(); ++i)
				//         {
				//           if(TsgrD.aElemList[i]==ElemK) dPositionI = dTsgrTotLength;
				//           dTsgrTotLength += m_pDoc->calcLAVElem(TsgrD.aElemList[i]);
				//         }
				dPositionJ = dPositionI + m_pDoc->calcLAVElem(ElemD);
			}
		}

		int LoadType_cur = BeamLoad_temp.data.LoadType;      // 하중 
		int LoadType_moment = BeamLoad_temp.data.LoadType + 1;   // moment
		for (int k = 0; k < 4; ++k)
		{
			double& rdMoment = BeamLoad_temp.data.Force_Type[LoadType_moment - 1][k];
			rdMoment = 0.0;
		}

		// from 박건태 대리님. (MQC-Alpha/Beta 4632-78)
		// Fz * (yc - ys) * -1.0 = Mx ; Fy * (zc - zs) = Mx 로 비틀림 모멘트가 계산되면 됩니다. nodal load를 하중으로 입력했을때와 결과가 같으면 됩니다. 

		bExistLoad = FALSE;
		if (fabs(ry) > dTol)
		{
			for (int k = 0; k < 4; ++k)
			{
				double& rdForce = BeamLoad_temp.data.Force_Type[LoadType_cur - 1][k];
				double& rdMoment = BeamLoad_temp.data.Force_Type[LoadType_moment - 1][k];

				double dEcc_z = dEcc_I_z;
				if (bIsTaperedSectGroup)
				{
					double dDummyY = 0.0;
					double dPosition = GetInterpolateValue(dPositionI, dPositionJ, BeamLoad_temp.data.DistanceRatio[k]);
					CalcTaperedSectGroupPosValue(dDummyY, dEcc_z, dEcc_I_y, dEcc_I_z, dEcc_J_y, dEcc_J_z, SectD, TsgrD, dTsgrTotLength, dPosition);
				}
				else if (bIsTapered)
				{
					dEcc_z = GetInterpolateValue(dEcc_I_z, dEcc_J_z, BeamLoad_temp.data.DistanceRatio[k]);
				}
				rdMoment += dEcc_z * (rdForce*ry);   // (z-방향 편심) X (y-방향 하중)
			}
			bExistLoad = TRUE;
		}

		if (fabs(rz) > dTol)
		{
			for (int k = 0; k < 4; ++k)
			{
				double& rdForce = BeamLoad_temp.data.Force_Type[LoadType_cur - 1][k];
				double& rdMoment = BeamLoad_temp.data.Force_Type[LoadType_moment - 1][k];

				double dEcc_y = dEcc_I_y;
				if (bIsTaperedSectGroup)
				{
					double dDummyZ = 0.0;
					double dPosition = GetInterpolateValue(dPositionI, dPositionJ, BeamLoad_temp.data.DistanceRatio[k]);
					CalcTaperedSectGroupPosValue(dEcc_y, dDummyZ, dEcc_I_y, dEcc_I_z, dEcc_J_y, dEcc_J_z, SectD, TsgrD, dTsgrTotLength, dPosition);
				}
				else if (bIsTapered)
				{
					dEcc_y = GetInterpolateValue(dEcc_I_y, dEcc_J_y, BeamLoad_temp.data.DistanceRatio[k]);
				}
				rdMoment += dEcc_y * (rdForce*rz) * (-1);   // (y-방향 편심) X (z-방향 하중) X (-1)
			}
			bExistLoad = TRUE;
		}

		for (int k = 0; k < 4; ++k)
		{
			double& rdForce = BeamLoad_temp.data.Force_Type[LoadType_cur - 1][k];
			rdForce = 0.0;
		}
		if (!bExistLoad) continue;

		BeamLoad_temp.data.LoadDirection = 1;   // 1=LX, 2=LY, 3=LZ, 4=GX, 5=GY, 6=GZ, 7=VECTOR
		BeamLoad_temp.data.LoadType = LoadType_moment;
		BeamLoad_temp.bLocalM = TRUE;
		raBeamLoad.Add(BeamLoad_temp);
	}

	return raBeamLoad.GetSize();
}

BOOL CAttrCtrl::ConvertBmldToGCS(T_BMLD_UDRD_D& rBeamLoad, double& rx, double& ry, double& rz, BOOL bConsiderSectOffset, BOOL bBeforeComposite, BOOL bIsCS /*= FALSE*/)
{
	T_BMLD_K Key;
	T_BMLD_D Data;
	double p1, p2, x1, x2;
	//double rx, ry, rz;

	Key = rBeamLoad.key;
	Data = rBeamLoad.data;
	p1 = p2 = x1 = x2 = rx = ry = rz = 0.;

	//Camber 정보는 시공단계검토에서만 고려된다.
	T_STCT_D StctD;
	if (!GetStct(StctD)) StctD.Initialize();
	BOOL bChekCmcs = (StctD.bApplyCamber && bIsCS && (m_pDoc->m_pPostCtrl->GetPointDataCount()->m_nStageStep > 0)) ? TRUE : FALSE;

	if (Data.LoadDirection < 4)
	{
		//int nCountCmcs = m_pDoc->m_pAttrCtrl2->GetCountCmcs();

		T_ELEM_D DataElem;
		if (!GetElemFromBaseDB(Key.key.entity, DataElem))return FALSE;

		double dCoorZ = 0.0;
		T_CMCS_D tCmcs;
		if (m_pDoc->m_pAttrCtrl2->GetCmcs(DataElem.elnod[0], tCmcs))
		{
			m_pUnitCtrl->ConvertUnitCmcsIn(tCmcs);
			dCoorZ += (tCmcs.dDeform + tCmcs.dUser);
		}
		if (m_pDoc->m_pAttrCtrl2->GetCmcs(DataElem.elnod[1], tCmcs))
		{
			m_pUnitCtrl->ConvertUnitCmcsIn(tCmcs);
			dCoorZ += (tCmcs.dDeform + tCmcs.dUser);
		}

		if (bChekCmcs && fabs(dCoorZ) > 0.0)
		{
			double FrameLocalVector[3][3];
			m_pDoc->calcFrameLocalVector(Key.key.entity, FrameLocalVector, TRUE, FALSE, bChekCmcs);
			rx = FrameLocalVector[0][Data.LoadDirection - 1];
			ry = FrameLocalVector[1][Data.LoadDirection - 1];
			rz = FrameLocalVector[2][Data.LoadDirection - 1];
		}
		else
		{
			if (Data.LoadDirection == 1)rx = 1.;
			if (Data.LoadDirection == 2)ry = 1.;
			if (Data.LoadDirection == 3)rz = 1.;
		}
	}
	else if (Data.LoadDirection > 3 && Data.LoadDirection < 7)
	{
		double FrameLocalVector[3][3];
		m_pDoc->calcFrameLocalVector(Key.key.entity, FrameLocalVector, FALSE, FALSE, bChekCmcs);
		rx = FrameLocalVector[0][Data.LoadDirection - 4];
		ry = FrameLocalVector[1][Data.LoadDirection - 4];
		rz = FrameLocalVector[2][Data.LoadDirection - 4];
	}
	else if (Data.LoadDirection == 7)
	{
		double vx, vy, vz;
		double FrameLocalVector[3][3];
		m_pDoc->calcFrameLocalVector(Key.key.entity, FrameLocalVector, TRUE, FALSE, bChekCmcs);
		CMathFunc::mathNormalize(Data.Vector[0], Data.Vector[1], Data.Vector[2], vx, vy, vz);
		rx = vx * FrameLocalVector[0][0] + vy * FrameLocalVector[0][1] + vz * FrameLocalVector[0][2];
		ry = vx * FrameLocalVector[1][0] + vy * FrameLocalVector[1][1] + vz * FrameLocalVector[1][2];
		rz = vx * FrameLocalVector[2][0] + vy * FrameLocalVector[2][1] + vz * FrameLocalVector[2][2];
	}
	else
		ASSERT(FALSE);



	double dNode1Z = 0.0;
	double dNode2Z = 0.0;
	if (bChekCmcs)
	{
		T_ELEM_D DataElem;
		GetElem(Key.key.entity, DataElem);

		T_CMCS_D tCmcs;
		if (m_pDoc->m_pAttrCtrl2->GetCmcs(DataElem.elnod[0], tCmcs))
		{
			m_pUnitCtrl->ConvertUnitCmcsIn(tCmcs);
			dNode1Z = tCmcs.dDeform + tCmcs.dUser;
		}
		if (m_pDoc->m_pAttrCtrl2->GetCmcs(DataElem.elnod[1], tCmcs))
		{
			m_pUnitCtrl->ConvertUnitCmcsIn(tCmcs);
			dNode2Z = tCmcs.dDeform + tCmcs.dUser;
		}
	}


	// Project & Global & 분포하중
	if (Data.Projection == 1 && Data.LoadDirection > 3 &&
		Data.LoadDirection < 7 && (Data.LoadType == 3 || Data.LoadType == 4))
	{
		T_ELEM_D DataElem;
		GetElem(Key.key.entity, DataElem);
		T_NODE_D n1, n2;
		GetNode(DataElem.elnod[0], n1);
		GetNode(DataElem.elnod[1], n2);
		T_OFFS_D DataOffs;
		if (GetOffsElem(Key.key.entity, DataOffs) && DataOffs.nOffsetType == 1) // global offset
		{
			n1.x += DataOffs.Offset[0];
			n1.y += DataOffs.Offset[1];
			n1.z += DataOffs.Offset[2];
			n2.x += DataOffs.Offset[3];
			n2.y += DataOffs.Offset[4];
			n2.z += DataOffs.Offset[5];
		}
		double dx = n2.x - n1.x;
		double dy = n2.y - n1.y;
		double dz = (n2.z + dNode2Z) - (n1.z + dNode1Z);

		if (Data.bEccentricity && Data.bDistJ) // MNET:XXXX 20070530 mylee - 편심 IJ 다른경우 고려
		{
			double Dx = 0.0, Dy = 0.0, Dz = 0.0;
			double Dxj = 0.0, Dyj = 0.0, Dzj = 0.0;
			BOOL bFLV = FALSE;
			double FrameLocalVector[3][3];
			// MQC:3126-Seungjun-20100201 Eccen Beam Load일 경우 해석값이 0으로 나옴.
			for (int mm = 0; mm < 3; mm++)
			{
				for (int nn = 0; nn < 3; nn++)
					FrameLocalVector[mm][nn] = (mm == nn) ? 1.0 : 0.0;
			}
			// 편심을 Local 방향으로의 거리(Dx, Dy, Dz)로 계산
			if (Data.nEccenDir < 4)
			{
				if (Data.nEccenDir == 2)Dy = 1.;
				if (Data.nEccenDir == 3)Dz = 1.;
			}
			else if (Data.nEccenDir > 3 && Data.nEccenDir < 7)
			{
				bFLV = TRUE;
				m_pDoc->calcFrameLocalVector(Key.key.entity, FrameLocalVector, TRUE, FALSE, bChekCmcs);
				Dx = FrameLocalVector[0][Data.nEccenDir - 4];
				Dy = FrameLocalVector[1][Data.nEccenDir - 4];
				Dz = FrameLocalVector[2][Data.nEccenDir - 4];
			}
			Dxj = Dx * Data.dDistJ;
			Dyj = Dy * Data.dDistJ;
			Dzj = Dz * Data.dDistJ;
			Dx *= Data.dDistI;
			Dy *= Data.dDistI;
			Dz *= Data.dDistI;

			double DxG = (Dxj - Dx)*FrameLocalVector[0][0] + (Dyj - Dy)*FrameLocalVector[1][0] + (Dzj - Dz)*FrameLocalVector[2][0];
			double DyG = (Dxj - Dx)*FrameLocalVector[0][1] + (Dyj - Dy)*FrameLocalVector[1][1] + (Dzj - Dz)*FrameLocalVector[2][1];
			double DzG = (Dxj - Dx)*FrameLocalVector[0][2] + (Dyj - Dy)*FrameLocalVector[1][2] + (Dzj - Dz)*FrameLocalVector[2][2];
			dx += DxG; // 편심 IJ 다른 경우 편심 반영
			dy += DyG;
			dz += DzG;
		}

		double bl = sqrt(dx*dx + dy * dy + dz * dz); // IJ 다른 경우는 수정된 거리
		double tl = 0.;
		if (Data.LoadDirection == 4)tl = sqrt(dy*dy + dz * dz);
		if (Data.LoadDirection == 5)tl = sqrt(dx*dx + dz * dz);
		if (Data.LoadDirection == 6)tl = sqrt(dx*dx + dy * dy);
		if (Data.LoadType == 3 || Data.LoadType == 4)
		{
			for (int i = 0; i < 4; i++)Data.Force_Type[Data.LoadType - 1][i] *= tl / bl;
		}
	}

	// rBeamLoad.bLocalM : 추가된 모멘트인 경우는 local 벡터를 그대로 이용. 아래 조건문 skip

	T_OFFS_D DataOffs;
	if (!bConsiderSectOffset && !rBeamLoad.bLocalM && GetElemOffs(Key.key.entity, DataOffs, FALSE, FALSE, bBeforeComposite) && (DataOffs.nOffsetType == 1 || DataOffs.nOffsetType == 4)) // Section Offset
  //if (!bConsiderSectOffset && GetElemOffs(Key.key.entity, DataOffs, FALSE, FALSE, bBeforeComposite) && DataOffs.nOffsetType == 4) // Section Offset
	{
		GetElemOffs(Key.key.entity, DataOffs, TRUE, FALSE, bBeforeComposite);
		if (DataOffs.Offset[0] != DataOffs.Offset[3] || DataOffs.Offset[1] != DataOffs.Offset[4] || DataOffs.Offset[2] != DataOffs.Offset[5])
		{
			//방향과 크기를 Offset때문에 요소로컬이 바뀌더라도 Offset 고려전과 동일하도록 조절한다 
			T_ELEM_D DataElem;
			GetElem(Key.key.entity, DataElem);
			T_NODE_D n1, n2, n3, n4, n5;
			GetNode(DataElem.elnod[0], n1);
			GetNode(DataElem.elnod[1], n2);
			//if(DataElem.elnod[2] > 0)
			//  m_pAttrCtrl->GetNode(DataElem.elnod[2], n3);
			//else
			//{
			//  n3.x=n1.x, n3.y=n1.y, n3.z=n1.z;
			//}

			// MQC:3746 by KJH 20110223
			//          double dLocalVector1[3][3],dLocalVector2[3][3];
			//          VERIFY(m_pDoc->calcFrameLocalVector(Key.key.entity, dLocalVector1));
			//          double dLength=CMathFunc::mathLength(n1.x-n2.x, n1.y-n2.y, n1.z-n2.z);
			//          n4.x=n1.x+DataOffs.Offset[0], n4.y=n1.y+DataOffs.Offset[1], n4.z=n1.z+DataOffs.Offset[2];
			//          n5.x=n2.x+DataOffs.Offset[3], n5.y=n2.y+DataOffs.Offset[4], n5.z=n2.z+DataOffs.Offset[5];
			//          n3.x=n4.x+dLocalVector1[2][0]*dLength;
			//          n3.y=n4.y+dLocalVector1[2][1]*dLength;
			//          n3.z=n4.z+dLocalVector1[2][2]*dLength;
			//          VERIFY(m_pDoc->calcFrameLocalVector(n4, n5, n3, 1, dLocalVector2));
			double dLocalVector1[3][3], dLocalVector2[3][3];
			// 원 좌표계의 local vector
			VERIFY(m_pDoc->calcFrameLocalVector(Key.key.entity, dLocalVector1));
			// center-center로 변경된 local vector
			double coord_i[3] = { n1.x, n1.y, n1.z }, coord_j[3] = { n2.x, n2.y, n2.z };
			n4.x = coord_i[0] + DataOffs.Offset[0], n4.y = coord_i[1] + DataOffs.Offset[1], n4.z = coord_i[2] + DataOffs.Offset[2];
			n5.x = coord_j[0] + DataOffs.Offset[3], n5.y = coord_j[1] + DataOffs.Offset[4], n5.z = coord_j[2] + DataOffs.Offset[5];
			if (IsVerticalFrame(coord_i, coord_j)) // 원 좌표가 수직일때
			{ // 원 좌표가 수직인 경우는 center-center(n4, n5)로 변경하기 위해 원 좌표의 local z방향의 n3로 평면을 작성한 후 local vector를 계산한다.
				double dLength = CMathFunc::mathLength(n1.x - n2.x, n1.y - n2.y, n1.z - n2.z);
				n3.x = n4.x + dLocalVector1[2][0] * dLength;
				n3.y = n4.y + dLocalVector1[2][1] * dLength;
				n3.z = n4.z + dLocalVector1[2][2] * dLength;
				VERIFY(m_pDoc->calcFrameLocalVector(n4, n5, n3, 1, dLocalVector2));
			}
			else
			{ // 원 좌표가 수직이 아닌 경우 center-center로 변경된 local vector를 바로 사용한다.
				coord_i[0] = n4.x, coord_i[1] = n4.y, coord_i[2] = n4.z;
				coord_j[0] = n5.x, coord_j[1] = n5.y, coord_j[2] = n5.z;

				GetElem(Key.key.entity, DataElem);
				VERIFY(m_pDoc->calcFrameLocalVector(coord_i, coord_j, DataElem.angle, dLocalVector2));
			}
			// end MQC:3746 by KJH 20110223

			if (!AdjustLocalAxisByElemLocal(dLocalVector1, dLocalVector2)) { ASSERT(0); }

			double x, y, z, rx2 = 0., ry2 = 0., rz2 = 0., p;
			for (int i = 0; i < 3; i++)
			{
				x = dLocalVector1[i][0], y = dLocalVector1[i][1], z = dLocalVector1[i][2];
				CMathFunc::mathGCS2UCS(x, y, z, dLocalVector2);
				if (i == 0)p = rx;
				if (i == 1)p = ry;
				if (i == 2)p = rz;
				rx2 += p * x, ry2 += p * y, rz2 += p * z;
			}
			rx = rx2, ry = ry2, rz = rz2;
			// 분포하중일 경우에 길이변화를 고려한다
			if (Data.LoadType == 3 || Data.LoadType == 4)
			{
				double dl1 = CMathFunc::mathLength(n1.x - n2.x, n1.y - n2.y, n1.z - n2.z);  //원래 요소 길이
				double dl2 = CMathFunc::mathLength(n4.x - n5.x, n4.y - n5.y, n4.z - n5.z);  //변형된 요소 길이
				double dRatio = dl1 / dl2;
				if (DataOffs.nOffsetType == 1) dRatio = 1.0;  // Global Offset 인 경우 하중 변경 없다.
				for (int i = 0; i < 4; i++)
				{
					if (Data.DistanceRatio[i] == 0. && Data.Force_Type[Data.LoadType - 1][i] == 0.)break;
					Data.Force_Type[Data.LoadType - 1][i] *= dRatio;
				}
			}
		}
	}
	if (rx == -0.) rx = 0.; // 20080710 mylee - VISTA 에서 이상해서 넣었음
	if (ry == -0.) ry = 0.;
	if (rz == -0.) rz = 0.;

	//rBeamLoad.key = Key;
	rBeamLoad.data = Data;

	return TRUE;
}

// MNET:XXXX-HSSHIM-20130905
// CSectDB::CalcTaperedSection(...)을 참고로 만듬.
// 변단면 그룹의 특정 위치에서의 형상 값 반환.
BOOL CAttrCtrl::CalcTaperedSectGroupPosValue(double& rdRetValY, double& rdRetValZ, double dValY1, double dValZ1, double dValY2, double dValZ2, const T_SECT_D& DataSect, T_TSGR_D& DataTsgr, double dTotalLength, double dPosition)
{
	rdRetValY = 0.0;
	rdRetValZ = 0.0;

	if (DataSect.nStype != D_SECT_TYPE_TAPERED) { ASSERT(FALSE); return FALSE; }
	if (dTotalLength <= 0. || dPosition < 0.) { ASSERT(FALSE); return FALSE; }
	if (dPosition > dTotalLength + dTotalLength * 1.e-5) { ASSERT(FALSE); return FALSE; }

	double dRatio = dPosition / dTotalLength;
	double a, b, /*c,*/ p, q;

	// about y-dir ----------------------------------
	double dPositionMy = 0.;
	if (DataTsgr.nVariation_y == 1)
	{
		if (DataTsgr.nQuadEnd_y == 0)dPositionMy = -DataTsgr.dQuadDistance_y;
		else                        dPositionMy = dTotalLength + DataTsgr.dQuadDistance_y;
	}

	double dQuadExpY = DataTsgr.dQuadExp_y;
	if (DataTsgr.nVariation_y == 0) // Linear
	{
		rdRetValY = dValY1 + (dValY2 - dValY1)*dRatio;
	}
	else                           // Quadratic
	{
		m_pDoc->m_pSectDB->Quadratic_Curve(0., dValY1, dTotalLength, dValY2, dPositionMy, dQuadExpY, a, b, p, q);
		rdRetValY = a * pow(b*dPosition - p, dQuadExpY) + q;
	}

	// about z-dir ----------------------------------
	double dPositionMz = 0.;
	if (DataTsgr.nVariation_z == 1)
	{
		if (DataTsgr.nQuadEnd_z == 0)dPositionMz = -DataTsgr.dQuadDistance_z;
		else                        dPositionMz = dTotalLength + DataTsgr.dQuadDistance_z;
	}

	double dQuadExpZ = DataTsgr.dQuadExp_z;
	if (DataTsgr.nVariation_z == 0) // Linear
	{
		rdRetValZ = dValZ1 + (dValZ2 - dValZ1)*dRatio;
	}
	else                           // Quadratic
	{
		m_pDoc->m_pSectDB->Quadratic_Curve(0., dValZ1, dTotalLength, dValZ2, dPositionMz, dQuadExpZ, a, b, p, q);
		rdRetValZ = a * pow(b*dPosition - p, dQuadExpZ) + q;
	}

	return TRUE;
}

// dVal1 -> dVal2로의 선형 보간 값 (dPosRatio 위치)
// @param 0.0 <= dPosRatio <= 1.0
double CAttrCtrl::GetInterpolateValue(const double dVal1, const double dVal2, const double dPosRatio)
{
	double dRetVal = dVal1;
	dRetVal = dVal1 + (dVal2 - dVal1)*dPosRatio;

	return dRetVal;
}

// MNET:XXXX-HSSHIM-20131010. 
// 절점 좌표축과 offset된 도심 좌표축이 서로 틀어져 있음으로 인해서
// 솔버에서 계산되는 하중 및 강성 좌표축에 영향을 주는 문제를 해결하기 위해
// 정진상 이사보님과 협의하여 아래와 같이 수정 
BOOL CAttrCtrl::AdjustLocalAxisByElemLocal(const double dLocalVector1[3][3], double dLocalVector2[3][3])
{
	// <계산방법>----------------
	// 1. 절점 좌표축의 z-축상의 길이가 1인 위치의 점을 
	//    절점 좌표욱의 x-축 방향으로 
	//    도심 좌표축의 y-z 평면에 투영
	// 2. 투영된 위치 방향을 도심 좌표축의 z-방향으로 설정
	// 3. 도심 좌표축의 x-방향과 새로 설정된 z-방향을 가지고 
	//    도심 좌표축의 y-방향 계산.

	// 절점좌표축의 z-축 상의 점 
	double node_xyz[3] = { dLocalVector1[2][0], dLocalVector1[2][1], dLocalVector1[2][2] };

	// 절점 좌표축의 x-축 방향 (투영 방향)
	double vector_xyz[3] = { dLocalVector1[0][0], dLocalVector1[0][1], dLocalVector1[0][2] };

	// 투영할 대상 평면 (도심 좌표축의 y-z 평면)
	double plane_xyz1[3] = { 0.0, 0.0, 0.0 };                                                 // 원점 
	double plane_xyz2[3] = { dLocalVector2[1][0], dLocalVector2[1][1], dLocalVector2[1][2] }; // 도심 좌표축의 y축 상의 점 
	double plane_xyz3[3] = { dLocalVector2[2][0], dLocalVector2[2][1], dLocalVector2[2][2] }; // 도심 좌표축의 z축 상의 점 

																							// 투영된 위치 
	const double tolerance = 1.0e-10;
	double projected_node_xyz[3] = { 0.0, };

	if (!CMathFunc::project_on_plane_vector(node_xyz, vector_xyz, plane_xyz1, plane_xyz2, plane_xyz3, tolerance, projected_node_xyz))
	{
		// 투영 방향을 뒤집어서 다시 시도.
		vector_xyz[0] = -vector_xyz[0];
		vector_xyz[1] = -vector_xyz[1];
		vector_xyz[2] = -vector_xyz[2];
		if (!CMathFunc::project_on_plane_vector(node_xyz, vector_xyz, plane_xyz1, plane_xyz2, plane_xyz3, tolerance, projected_node_xyz))
		{
			ASSERT(0);

			// 못찾으면 도심의 z-축을 그냥 사용.
			projected_node_xyz[0] = dLocalVector2[2][0];
			projected_node_xyz[1] = dLocalVector2[2][1];
			projected_node_xyz[2] = dLocalVector2[2][2];
		}
	}

	// 도심 좌표축 z축을 다시 설정.
	dLocalVector2[2][0] = projected_node_xyz[0];
	dLocalVector2[2][1] = projected_node_xyz[1];
	dLocalVector2[2][2] = projected_node_xyz[2];
	CMathFunc::mathNormalize(dLocalVector2[2], dLocalVector2[2]);

	// 도심 좌표축의 y축을 다시 설정.
	CMathFunc::mathNormal(dLocalVector2[2], dLocalVector2[0], dLocalVector2[1]);

	return TRUE;
}

void CAttrCtrl::Consider_I_J_DifferentEcc(T_BMLD_K KeyBmld, T_BMLD_D& DataBmld)
{
	if (!(DataBmld.bEccentricity && DataBmld.bDistJ)) return; // 편심이 있고 IJ 다른경우만
	if (!(DataBmld.LoadType == 3 || DataBmld.LoadType == 4)) return; // 분포하중 & 모멘트만

	double Dx = 0.0, Dy = 0.0, Dz = 0.0;
	double Dxj = 0.0, Dyj = 0.0, Dzj = 0.0;
	double FrameLocalVector[3][3];

	// 편심을 Global 방향으로의 거리(Dx, Dy, Dz)로 계산
	if (DataBmld.nEccenDir < 4)
	{
		m_pDoc->calcFrameLocalVector(KeyBmld.key.entity, FrameLocalVector, TRUE);
		Dx = FrameLocalVector[DataBmld.nEccenDir - 1][0];
		Dy = FrameLocalVector[DataBmld.nEccenDir - 1][1];
		Dz = FrameLocalVector[DataBmld.nEccenDir - 1][2];
	}
	else if (DataBmld.nEccenDir > 3 && DataBmld.nEccenDir < 7)
	{
		if (DataBmld.nEccenDir == 4) Dx = 1.;
		else if (DataBmld.nEccenDir == 5) Dy = 1.;
		else if (DataBmld.nEccenDir == 6) Dz = 1.;
	}
	Dxj = Dx * DataBmld.dDistJ;
	Dyj = Dy * DataBmld.dDistJ;
	Dzj = Dz * DataBmld.dDistJ;
	Dx *= DataBmld.dDistI;
	Dy *= DataBmld.dDistI;
	Dz *= DataBmld.dDistI;

	// 노드간의 거리를 계산
	T_ELEM_D DataElem;
	GetElem(KeyBmld.key.entity, DataElem);
	T_NODE_D n1, n2;
	GetNode(DataElem.elnod[0], n1);
	GetNode(DataElem.elnod[1], n2);
	T_OFFS_D DataOffs;
	if (GetOffsElem(KeyBmld.key.entity, DataOffs) && DataOffs.nOffsetType == 1) // global offset
	{
		n1.x += DataOffs.Offset[0];
		n1.y += DataOffs.Offset[1];
		n1.z += DataOffs.Offset[2];
		n2.x += DataOffs.Offset[3];
		n2.y += DataOffs.Offset[4];
		n2.z += DataOffs.Offset[5];
	}
	double dx = n2.x - n1.x;
	double dy = n2.y - n1.y;
	double dz = n2.z - n1.z;
	double bl_old = dx * dx + dy * dy + dz * dz; // 원래 거리^2

	dx += Dxj - Dx; // 편심 IJ 다른 경우 편심 반영
	dy += Dyj - Dy;
	dz += Dzj - Dz;
	double bl = dx * dx + dy * dy + dz * dz; // 수정된 거리^2

	double dFactor = sqrt(bl / bl_old);

	for (int i = 0; i < 4; i++)
	{
		if (DataBmld.LoadType == 3)       DataBmld.Force_Type[2][i] *= dFactor; // 분포하중
		else if (DataBmld.LoadType == 4)  DataBmld.Force_Type[3][i] *= dFactor; // 분포모멘트
	}
}

void CAttrCtrl::ConvertEccOffsetToLocalMoment(T_BMLD_UDRD_D& Bmld, CArray<T_BMLD_UDRD_D, T_BMLD_UDRD_D&>& arBeamLoad, BOOL bPressure)
{
	T_BMLD_K KeyBmld;
	T_BMLD_D DataBmld;
	KeyBmld = Bmld.key;
	DataBmld = Bmld.data;

	// 편심 보하중 고려
	// 편심 보하중을 Moment 하중으로 추가해 준다.
	// 1. 편심을 Local 방향으로의 거리(Dx, Dy, Dz)로 계산
	// 2. 하중을 Local 방향으로의 분력(Px, Py, Pz)으로 계산
	// 3. Rx 모멘트(-Py*Dz), (Pz*Dy)
	// 4. Ry (-Pz*Dx), (Px*Dz) / Rz (-Px*Dy), (Py*Dx)
	// 5. 크기가 0이 아닌 것을 arBeamLoad에 추가
	// 이하 부분에서는 편심 고려하지 않는다. 편심은 여기서만 고려된다.
	if (Bmld.data.bEccentricity == FALSE) return;

	double Dx = 0.0, Dy = 0.0, Dz = 0.0;
	double Dxj = 0.0, Dyj = 0.0, Dzj = 0.0;
	double Px = 0.0, Py = 0.0, Pz = 0.0;
	BOOL bFLV = FALSE;
	double FrameLocalVector[3][3];
	// 편심을 Local 방향으로의 거리(Dx, Dy, Dz)로 계산
	if (DataBmld.nEccenDir < 4)
	{
		if (DataBmld.nEccenDir == 2)Dy = 1.;
		if (DataBmld.nEccenDir == 3)Dz = 1.;
	}
	else if (DataBmld.nEccenDir > 3 && DataBmld.nEccenDir < 7)
	{
		bFLV = TRUE;
		m_pDoc->calcFrameLocalVector(KeyBmld.key.entity, FrameLocalVector, TRUE);
		Dx = FrameLocalVector[0][DataBmld.nEccenDir - 4];
		Dy = FrameLocalVector[1][DataBmld.nEccenDir - 4];
		Dz = FrameLocalVector[2][DataBmld.nEccenDir - 4];
	}

	if (DataBmld.bDistJ)
	{
		Dxj = Dx * DataBmld.dDistJ;
		Dyj = Dy * DataBmld.dDistJ;
		Dzj = Dz * DataBmld.dDistJ;
		Dx *= DataBmld.dDistI;
		Dy *= DataBmld.dDistI;
		Dz *= DataBmld.dDistI;
	}
	else
	{
		Dx *= DataBmld.dDistI;
		Dy *= DataBmld.dDistI;
		Dz *= DataBmld.dDistI;
		Dxj = Dx;
		Dyj = Dy;
		Dzj = Dz;
	}

	T_ELEM_D ElemD;
	T_SECT_D SectD;
	if (!GetElem(KeyBmld.key.entity, ElemD)) return;

	if (!GetSect(ElemD.elpro, SectD)) return;

	if (!bPressure)
	{
		// MQC:3812-JHYUN-20110314
		double hi = 0., bi = 0., hj = 0., bj = 0.;
		if (!GetSectOffsetFromCentroid(SectD, hi, bi, hj, bj)) { ASSERT(0); return; }

		// Offset 을 고려한다.
		Dx += bi;
		Dy += 0;
		Dz += hi;

		Dxj += bj;
		Dyj += 0;
		Dzj += hj;
	}
	else  // MNET:5800-HSSHIM-20130507. 도심과 압력하중의 중심이 다른 경우 그 차이만큼 편심 모멘트 하중을 추가.
	{
		double hi = 0.0, bi = 0.0, hj = 0.0, bj = 0.0; // 단면 높이
		double cen_hi = 0.0, cen_bi = 0.0, cen_hj = 0.0, cen_bj = 0.0; // 도심

		T_TSGR_K TsgrK = GetElemTsgrKey(KeyBmld.key.entity);
		if (SectD.nStype == D_SECT_TYPE_TAPERED && TsgrK > 0)
		{
			T_TSGR_D TsgrD;
			if (!GetTsgr(TsgrK, TsgrD)) { ASSERT(0); return; }
			double dTsgrTotLength = 0.0, dPositionI = 0.0, dPositionJ = 0.0;

			CalcTsgrTotLength(TsgrD, KeyBmld.key.entity, dTsgrTotLength, dPositionI);
			//       for(int i=0; i<TsgrD.aElemList.GetSize(); ++i)
			//       {
			//         if(TsgrD.aElemList[i]==KeyBmld.key.entity) dPositionI = dTsgrTotLength;
			//         dTsgrTotLength += m_pDoc->calcLAVElem(TsgrD.aElemList[i]);
			//       }
			dPositionJ = dPositionI + m_pDoc->calcLAVElem(ElemD);

			double dTol = m_pDoc->m_pFlagCtrl->GetGeneralCoordinateToleranceCurrentUnit();
			if (fabs(dPositionJ - dTsgrTotLength) < dTol) dPositionJ = dTsgrTotLength;

			T_SECT_D CalcSectD;
			if (!m_pDoc->m_pSectDB->CalcTaperedSection(SectD, TsgrD, dTsgrTotLength, dPositionI, dPositionJ, 2, CalcSectD)) { ASSERT(0); return; }
			if (!GetSectCentroid(CalcSectD, cen_hi, cen_bi, cen_hj, cen_bj)) { ASSERT(0); return; }
			if (!GetSectDimen(CalcSectD, hi, bi, hj, bj)) { ASSERT(0); return; }
		}
		else
		{
			// tapered단면이 아닌경우 혹은 tapered 이지만 group이 아니거나
			if (!GetSectCentroid(SectD, cen_hi, cen_bi, cen_hj, cen_bj)) { ASSERT(0); return; }
			if (!GetSectDimen(SectD, hi, bi, hj, bj)) { ASSERT(0); return; }
		}

		// 도심과 압력하중의 중심이 다른 경우 그 차이만큼 압력하중 편심을 고려한다.
		Dx += (0.5*bi - cen_bi);
		Dy += 0.0;
		Dz += (0.5*hi - cen_hi);

		Dxj += (0.5*bj - cen_bj);
		Dyj += 0.0;
		Dzj += (0.5*hj - cen_hj);
	}

	// 하중을 Local 방향으로의 분력(Px, Py, Pz)으로 계산
	if (DataBmld.LoadDirection < 4)
	{
		if (DataBmld.LoadDirection == 1)Px = 1.;
		if (DataBmld.LoadDirection == 2)Py = 1.;
		if (DataBmld.LoadDirection == 3)Pz = 1.;
	}
	else if (DataBmld.LoadDirection > 3 && DataBmld.LoadDirection < 7)
	{
		if (!bFLV)
			m_pDoc->calcFrameLocalVector(KeyBmld.key.entity, FrameLocalVector, TRUE);
		Px = FrameLocalVector[0][DataBmld.LoadDirection - 4];
		Py = FrameLocalVector[1][DataBmld.LoadDirection - 4];
		Pz = FrameLocalVector[2][DataBmld.LoadDirection - 4];

		// Global & 분포하중 & 프로젝션인 경우 - 아래 해 주는 계산을 편심에도 적용해 줌
		if (DataBmld.LoadType == 3 && DataBmld.Projection == 1)
		{
			T_ELEM_D DataElem;
			GetElem(KeyBmld.key.entity, DataElem);
			T_NODE_D n1, n2;
			GetNode(DataElem.elnod[0], n1);
			GetNode(DataElem.elnod[1], n2);
			T_OFFS_D DataOffs;
			if (GetOffsElem(KeyBmld.key.entity, DataOffs) && DataOffs.nOffsetType == 1) // global offset
			{
				n1.x += DataOffs.Offset[0];
				n1.y += DataOffs.Offset[1];
				n1.z += DataOffs.Offset[2];
				n2.x += DataOffs.Offset[3];
				n2.y += DataOffs.Offset[4];
				n2.z += DataOffs.Offset[5];
			}
			double dx = n2.x - n1.x;
			double dy = n2.y - n1.y;
			double dz = n2.z - n1.z;

			if (DataBmld.bDistJ) // MNET:XXXX 20070530 mylee - 편심 IJ 다른경우 고려
			{
				double DxG = (Dxj - Dx)*FrameLocalVector[0][0] + (Dyj - Dy)*FrameLocalVector[1][0] + (Dzj - Dz)*FrameLocalVector[2][0];
				double DyG = (Dxj - Dx)*FrameLocalVector[0][1] + (Dyj - Dy)*FrameLocalVector[1][1] + (Dzj - Dz)*FrameLocalVector[2][1];
				double DzG = (Dxj - Dx)*FrameLocalVector[0][2] + (Dyj - Dy)*FrameLocalVector[1][2] + (Dzj - Dz)*FrameLocalVector[2][2];
				dx += DxG; // 편심 IJ 다른 경우 편심 반영
				dy += DyG;
				dz += DzG;
			}
			double bl = sqrt(dx*dx + dy * dy + dz * dz); // 수정된 거리
			double tl = 0.;
			if (DataBmld.LoadDirection == 4)tl = sqrt(dy*dy + dz * dz);
			if (DataBmld.LoadDirection == 5)tl = sqrt(dx*dx + dz * dz);
			if (DataBmld.LoadDirection == 6)tl = sqrt(dx*dx + dy * dy);

			Px *= tl / bl; // 이 세 하중값은 편심에만 영향을 주므로
			Py *= tl / bl;
			Pz *= tl / bl;
		}
	}
	// 편심에서 하중 Vector 방향은 없음

	T_BMLD_D NewBmld;
	double P1, P2, D1, D2, D1j, D2j; P1 = P2 = D1 = D2 = D1j = D2j = 0.0;

	for (int k = 0; k < 3; ++k) // 세 방향에 대해
	{
		if (k == 0) { P1 = Py; P2 = Pz; D1 = Dy; D2 = Dz; D1j = Dyj; D2j = Dzj; }  //  Local x 방향
		if (k == 1) { P1 = Pz; P2 = Px; D1 = Dz; D2 = Dx; D1j = Dzj; D2j = Dxj; }  //  Local y 방향
		if (k == 2) { P1 = Px; P2 = Py; D1 = Dx; D2 = Dy; D1j = Dxj; D2j = Dyj; }  //  Local z 방향

		NewBmld = DataBmld;
		if (DataBmld.LoadType == 1) NewBmld.LoadType = 2;
		else if (DataBmld.LoadType == 3) NewBmld.LoadType = 4;

		if (k == 0) { NewBmld.LoadDirection = 1; } // Rx
		if (k == 1) { NewBmld.LoadDirection = 2; } // Ry
		if (k == 2) { NewBmld.LoadDirection = 3; } // Rz

		NewBmld.bEccentricity = FALSE;
		memset(NewBmld.Force_Type, 0, sizeof(NewBmld.Force_Type));

		// P1, D2에 대해 Moment 계산한다.
		double dDist[4];
		for (int i = 0; i < 4; i++)
		{
			if (DataBmld.bDistJ)  dDist[i] = D2 + (D2j - D2) * DataBmld.DistanceRatio[i];
			else                  dDist[i] = D2;
		}
		BOOL bValid = FALSE;
		for(int i = 0; i < 4; i++)
		{
			if (DataBmld.LoadType == 1)
			{
				NewBmld.Force_Type[1][i] = -P1 * DataBmld.Force_Type[0][i] * dDist[i];
				if (NewBmld.Force_Type[1][i] != 0.0) bValid = TRUE;

				//         if(DataBmld.LoadDirection == 2 || DataBmld.LoadDirection == 3 || DataBmld.LoadDirection == 5 || DataBmld.LoadDirection == 6)
				//         {
				//           //if(DataBmld.Force_Type[0][i] < 0) NewBmld.Force_Type[1][i] *= -1;
				//           NewBmld.LoadDirection = 1;
				//         }
				//         else
				//         {
				//           //if(DataBmld.Force_Type[0][i] > 0) NewBmld.Force_Type[1][i] *= -1;
				//           if(k==1) NewBmld.LoadDirection = 2;
				//           if(k==2) NewBmld.LoadDirection = 3;
				//         }
			}
			else if (DataBmld.LoadType == 3)
			{
				NewBmld.Force_Type[3][i] = -P1 * DataBmld.Force_Type[2][i] * dDist[i];
				if (NewBmld.Force_Type[3][i] != 0.0) bValid = TRUE;

				//         if(DataBmld.LoadDirection == 2 || DataBmld.LoadDirection == 3 || DataBmld.LoadDirection == 5 || DataBmld.LoadDirection == 6)
				//         {
				//           //if(DataBmld.Force_Type[2][i] < 0) NewBmld.Force_Type[3][i] *= -1;
				//           NewBmld.LoadDirection = 1;
				//         }
				//         else
				//         {
				//           //if(DataBmld.Force_Type[2][i] > 0) NewBmld.Force_Type[3][i] *= -1;
				//           if(k==1) NewBmld.LoadDirection = 2;
				//           if(k==2) NewBmld.LoadDirection = 3;
				//         }
			}
		}
		if (bValid)
		{
			Bmld.key = KeyBmld;
			Bmld.data = NewBmld;
			Bmld.bLocalM = TRUE;
			arBeamLoad.Add(Bmld);
		}

		// P2, D1에 대해 Moment 계산한다.
		for(int i = 0; i < 4; i++)
		{
			if (DataBmld.bDistJ)  dDist[i] = D1 + (D1j - D1) * DataBmld.DistanceRatio[i];
			else                  dDist[i] = D1;
		}
		bValid = FALSE;
		for(int i = 0; i < 4; i++)
		{
			if (DataBmld.LoadType == 1)
			{
				NewBmld.Force_Type[1][i] = P2 * DataBmld.Force_Type[0][i] * dDist[i];
				if (NewBmld.Force_Type[1][i] != 0.0) bValid = TRUE;

				//         if(DataBmld.LoadDirection == 2 || DataBmld.LoadDirection == 3 || DataBmld.LoadDirection == 5 || DataBmld.LoadDirection == 6)
				//         {
				//           //if(DataBmld.Force_Type[0][i] < 0) NewBmld.Force_Type[1][i] *= -1;
				//           NewBmld.LoadDirection = 1;
				//         }
				//         else
				//         {
				//           //if(DataBmld.Force_Type[0][i] > 0) NewBmld.Force_Type[1][i] *= -1;
				//           if(k==1) NewBmld.LoadDirection = 2;
				//           if(k==2) NewBmld.LoadDirection = 3;
				//         }
			}
			else if (DataBmld.LoadType == 3)
			{
				NewBmld.Force_Type[3][i] = P2 * DataBmld.Force_Type[2][i] * dDist[i];
				if (NewBmld.Force_Type[3][i] != 0.0) bValid = TRUE;

				//         if(DataBmld.LoadDirection == 2 || DataBmld.LoadDirection == 3 || DataBmld.LoadDirection == 5 || DataBmld.LoadDirection == 6)
				//         {
				//           //if(DataBmld.Force_Type[2][i] < 0) NewBmld.Force_Type[3][i] *= -1;
				//           NewBmld.LoadDirection = 1;
				//         }
				//         else
				//         {
				//           //if(DataBmld.Force_Type[2][i] > 0) NewBmld.Force_Type[3][i] *= -1;
				//           if(k==1) NewBmld.LoadDirection = 2;
				//           if(k==2) NewBmld.LoadDirection = 3;
				//         }
			}
		}
		if (bValid)
		{
			Bmld.key = KeyBmld;
			Bmld.data = NewBmld;
			Bmld.bLocalM = TRUE;
			arBeamLoad.Add(Bmld);
		}
	} // End of For - 세 방향에 대해 

	Bmld.bLocalM = FALSE;  // 이 함수를 벗어나서는 FALSE 처리
}

void CAttrCtrl::ConvertEccOffsetToCentroid(T_BMLD_UDRD_D& Bmld)
{
	T_BMLD_D DataBmld = Bmld.data;

	if (DataBmld.nEccenType == 1)
	{
		T_ELEM_D ElemD;
		T_SECT_D SectD;
		if (!GetElem(Bmld.key.key.entity, ElemD)) return;
		if (!GetSect(ElemD.elpro, SectD)) return;

		// MQC:3812-JHYUN-20110314
		double hi = 0., bi = 0., hj = 0., bj = 0.;
		if (!GetSectOffsetFromCentroid(SectD, hi, bi, hj, bj)) { ASSERT(0); return; }

		if (DataBmld.nEccenDir == 2)
		{
			// Offset 을 고려한다.
			DataBmld.dDistI += bi;
			DataBmld.dDistJ += bj;
		}
		else if (DataBmld.nEccenDir == 3)
		{
			// Offset 을 고려한다.
			DataBmld.dDistI += hi;
			DataBmld.dDistJ += hj;
		}
		else if (DataBmld.nEccenDir == 4 || DataBmld.nEccenDir == 5 || DataBmld.nEccenDir == 6)
		{
			double FrameLocalVector[3][3];
			m_pDoc->calcFrameLocalVector(Bmld.key.key.entity, FrameLocalVector, TRUE);

			// 역행렬을 구한다 
			// 			double dMatrixInvers[3][3] = {0.0,};
			// 			math_lib::inverse_matrix_3x3(FrameLocalVector, dMatrixInvers);

			// 			double dDistI = dMatrixInvers[1][0]*bi + dMatrixInvers[1][1]*bi + dMatrixInvers[1][2]*bi + 
			// 				dMatrixInvers[2][0]*hi + dMatrixInvers[2][1]*hi + dMatrixInvers[2][2]*hi;
			// 			double dDistJ = dMatrixInvers[1][0]*bi + dMatrixInvers[1][1]*bi + dMatrixInvers[1][2]*bi + 
			// 				dMatrixInvers[2][0]*hi + dMatrixInvers[2][1]*hi + dMatrixInvers[2][2]*hi;

			double dDistI = 0.0;
			double dDistJ = 0.0;

			if (DataBmld.nEccenDir == 5)
			{
				dDistI = FrameLocalVector[1][0] * bi + FrameLocalVector[1][1] * bi + FrameLocalVector[1][2] * bi;
				dDistJ = FrameLocalVector[1][0] * bj + FrameLocalVector[1][1] * bj + FrameLocalVector[1][2] * bj;
			}
			else if (DataBmld.nEccenDir == 6)
			{
				dDistI = FrameLocalVector[2][0] * hi + FrameLocalVector[2][1] * hi + FrameLocalVector[2][2] * hi;
				dDistJ = FrameLocalVector[2][0] * hj + FrameLocalVector[2][1] * hj + FrameLocalVector[2][2] * hj;
			}

			DataBmld.dDistI += dDistI;
			DataBmld.dDistJ += dDistJ;
		}
	}

	Bmld.data = DataBmld;
}

////////////// fmld ////////////////
void CAttrCtrl::GetFmldKeyList(CArray<T_FMLD_K, T_FMLD_K>& rKeyList)
{
	rKeyList.RemoveAll();
	T_FMLD_K key;
	T_FMLD_D data;
	POSITION pos = m_pDataMemb->m_fmld.GetStart();
	while (pos)
	{
		m_pDataMemb->m_fmld.GetNext(pos, key, data);
		rKeyList.Add(key);
	}
}

BOOL CAttrCtrl::GetSerialFmld(T_ELEM_K Key,T_FMLD_KEY& rKeySerial)
{
	T_FMLD_K key;
	T_FMLD_D data;
	key.key.entity=Key;

	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_fmld.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeKeyFmld(T_ELEM_K Key,T_FMLD_K& rKey)
{
	rKey.key.entity=Key;
	rKey.key.serial=0;

	T_FMLD_KEY KeySerial;
	if(!GetSerialFmld(Key, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

BOOL CAttrCtrl::ExistFmld(T_FMLD_K Key)
{
	T_FMLD_D Data;
	return m_pDataMemb->m_fmld.Get(Key,Data);
}

BOOL CAttrCtrl::GetFmld(T_FMLD_K Key,T_FMLD_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_fmld.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitFmldOut(rData);
	return bReturn;
}

void CAttrCtrl::GetFmld(T_ELEM_K KeyElem, CArray<T_FMLD_K, T_FMLD_K>& rarKey, CArray<T_FMLD_D, T_FMLD_D&>& rarData)
{
	rarKey.RemoveAll();
	rarData.RemoveAll();

	int nEntity = 0;
	CArray<int, int> aSerial; aSerial.RemoveAll();

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_FMLD_CMD)
		{
			T_FMLD_K key;
			key.keymap=ListData.nKey;

			nEntity = key.key.entity;
			aSerial.Add(key.key.serial);

			//       GetFmld(key, data);
			//       rarKey.Add(key);
			//       rarData.Add(data);
		}
	}

	T_FMLD_K FmldK;
	FmldK.key.entity = nEntity;
	for (int i=0; i<aSerial.GetSize(); i++)
	{
		T_FMLD_D data;
		FmldK.key.serial = aSerial[i];
		GetFmld(FmldK, data);
		rarKey.Add(FmldK);
		rarData.Add(data);
	}
}

void CAttrCtrl::GetFmldLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, BOOL bAllLdgr, CArray<T_LDGR_K, T_LDGR_K>& raLdgrKey, T_ELEM_K KeyElem, CArray<T_FMLD_D, T_FMLD_D&>& rarData)
{
	rarData.RemoveAll();
	if(!CheckLcomLabel(bAllLoadCase, DataLcom))return;

	CMap<T_LDGR_K, T_LDGR_K, T_LDGR_K, T_LDGR_K> mapLdgr;
	if (!bAllLdgr)
	{
		mapLdgr.InitHashTable(11);
		for (int i = 0; i < raLdgrKey.GetSize(); i++)mapLdgr.SetAt(raLdgrKey[i], raLdgrKey[i]);
	}

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_FMLD_CMD)
		{
			T_FMLD_K key;
			T_FMLD_D data;
			key.keymap=ListData.nKey;
			GetFmld(key, data);
			if (!bAllLdgr && !mapLdgr.Lookup(data.GroupKey, data.GroupKey)) continue;
			if(bAllLoadCase)
			{
				rarData.Add(data);
			}
			else
			{
				double dStldFactor=0., dStagFactor=0.;
				if(!GetLcomStldFactor(data.LoadCaseKey, DataLcom, dStldFactor, dStagFactor))return;  
				T_STLD_D DataStld;
				if(dStldFactor != 0.)
				{
					T_FMLD_D DataFmld=data;
					DataFmld.dScaleFactor=data.dScaleFactor*dStldFactor;
					rarData.Add(DataFmld);
				}
				if(dStagFactor != 0. && m_pDoc->m_pStagCtrl->IsActiveLdgrKey(data.GroupKey))
				{
					T_FMLD_D DataFmld=data;
					DataFmld.dScaleFactor=data.dScaleFactor*dStagFactor;
					rarData.Add(DataFmld);
				}
			}
		}
	}
	return;
}

