void CAttrCtrl::GetFbldList(CArray<CString, CString&>& rstrFbldList)
{
	rstrFbldList.RemoveAll();

	int nCount=GetCountFbld();
	if(nCount == 0)return;

	POSITION pos;
	T_FBLD_K Key;
	T_FBLD_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartFbld();
		while(pos != NULL)
		{
			GetNextFbld(pos, Key, Data);
			if(Data.FloorLoadTypeId == i)
			{
				rstrFbldList.Add(Data.FloorLoadTypeName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetFbldKeyList(CArray<T_FBLD_K, T_FBLD_K>& rFbldKeyList)
{
	/*
	rKeyList.RemoveAll();

	int nCount=GetCountFbld();
	if(nCount == 0)return;

	POSITION pos;
	T_FBLD_K Key;
	T_FBLD_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartFbld();
	while(pos != NULL)
	{
	GetNextFbld(pos, Key, Data);
	if(Data.FloorLoadTypeId == i)
	{
	rKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rFbldKeyList.RemoveAll();
	int nCount=GetCountFbld();
	if(nCount == 0)return;

	CArray<T_FBLD_K, T_FBLD_K> aFbldKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rFbldKeyList.SetSize(nCount);
	aFbldKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_FBLD_K Key;
	T_FBLD_D Data;
	int i = 0;
	pos = GetStartFbld();
	while (pos != NULL)
	{
		GetNextFbld(pos, Key, Data);
		aFbldKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.FloorLoadTypeId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rFbldKeyList[i] = aFbldKey[ix];
	}
}

