BOOL CAttrCtrl::IsActiveFbla(CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K>& mapActiveElem, T_FBLA_D& rData)
{
	double zfirst=0.;
	double dTol=m_pDoc->m_pFlagCtrl->GetGeneralCoordinateToleranceCurrentUnit();
	int nCon=0;
	T_NODE_D DataNode;
	for(int i=0; i<D_FBLA_MAXNOD; i++)
	{
		if(rData.nConnectivity[i] == 0)break;
		if(!GetNode(rData.nConnectivity[i], DataNode))return FALSE;
		if(i == 0)zfirst=DataNode.z;
		if(fabs(zfirst - DataNode.z) > dTol)return TRUE;  // 수평면인가?
		nCon++;
	}

	NodeList* pList;
	POSITION poslist;
	T_LIST_DATA ListData;
	for(int i = 0; i<nCon; i++)
	{
		T_NODE_K KeyNode=rData.nConnectivity[i];
		VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
		poslist=pList->GetHeadPosition();
		while(poslist != NULL)
		{
			// ===== // DB_NODE_DATA
			ListData=pList->GetNext(poslist);
			if(ListData.nCmd == LT_ELEM_CMD)
			{
				T_ELEM_K key=ListData.nKey;
				T_ELEM_K keytemp;
				if(mapActiveElem.Lookup(key, keytemp))
				{
					T_ELEM_D data;
					if(!GetElem(key, data))data.Initialize();
					if(IsFrameType(data.eltyp))
					{
						T_NODE_D n1, n2;
						GetNode(data.elnod[0], n1);
						GetNode(data.elnod[1], n2);
						if(IsHorizontalFrame(n1, n2))return TRUE;
					}
					else if(IsWall(data.eltyp))
					{
						for(int j=0; j<4; j++)
						{
							if(data.elnod[j] == KeyNode && j > 1)return TRUE;
						}
					}
					// MQC 14857 : 플레이트인 경우 상단 2개 절점을 찾아내 일치하는지 비교
					else if(IsPlaneType(data.eltyp))
					{
						T_NODE_D aNodeD[4];
						for(int j=0; j<4; j++)
						{
							if(!GetNode(data.elnod[j], aNodeD[j])) 
								aNodeD[j].Initialize();
						}
						int nIdxTop1=0,nIdxTop2=0;            
						// 0,1이 같으면
						if(fabs(aNodeD[0].z-aNodeD[1].z) < m_pInitCtrl->ZeroLength())
						{
							nIdxTop1 = aNodeD[0].z > aNodeD[2].z ? 0:2;
							nIdxTop2 = aNodeD[0].z > aNodeD[2].z ? 1:3;
						}
						// 0,1이 다르면
						else
						{
							nIdxTop1 = aNodeD[0].z > aNodeD[1].z ? 0:1;
							nIdxTop2 = aNodeD[2].z > aNodeD[3].z ? 2:3;
						}

						if(data.elnod[nIdxTop1]==KeyNode || data.elnod[nIdxTop2]==KeyNode)
							return TRUE;
					}
				}
			}
		}
	}
	return FALSE;
}


