BOOL CAttrCtrl::MakeKeyStbk(T_NODE_K KeyNode1, T_NODE_K KeyNode2, T_LDGR_K KeyLdgr, T_STBK_K& rKey)
{
	T_STBK_K Key;
	T_STBK_D Data;
	POSITION pos = GetStartStbk();
	while (pos)
	{
		GetNextStbk(pos, Key, Data);
		if(Data.node1 == KeyNode1 &&
		   Data.node2 == KeyNode2 &&
		   Data.LoadGrpKey == KeyLdgr)
		{
			rKey = Key;
			return TRUE;
		}
	}
	rKey = GetStartNumStbk();
	return TRUE;
}

