void CAttrCtrl::MakeProjectionPres(T_PRES_K Key, T_PRES_D Data, T_PRES_D& rDataNew)
{
	rDataNew=Data;

	//  int LoadCommandTypeNew;  // 1=Pressure  2=Hydrostatic Pressure
	//  int LoadType;            // 1=Plate/PlaneStress/Wall Load 2=Axisymmetric/PlaneStrain 3=Solid
	//  int nSubLoadType;        // 0=Pressure(Plate,Axisymmetric/PlaneStrain,Solid), 1=Concentrated Load(Plate), 2=단위길이당 Edge Load(Plate/PlaneStress/Wall)
	//  int nEdgeFace;           // PlateFace는 사용안함, Plate(PlaneStress,Wall)Edge/Axi/PlaneStrain은 Edge 번호, Solid는 Face 번호
	//  int LoadDirectionNew;    // 0=Normal, 1=LX, 2=LY, 3=LZ, 4=GX, 5=GY, 6=GZ, 7=Vector
	// Plate(Face) : Local(1~3), Global(4~6), Vector(7)
	// Plate(Edge) : Normal(0), Local(1~3), Global(4~6), Vector(7)
	// Solid(Face) : Normal(0), Local(1~3), Global(4~6), Vector(7)
	// Plane Strain(Edge) : Normal(0), LX(1), LY(2), Vector(7)
	// Axisymmetric(Edge) : Normal(0), LX(1), LY(2), Vector(7)
	// Wall(Edge)  : Normal(0), Local(1~3), Global(4~6), Vector(7)
	//  int Projection;          // LoadDirection == Global(4, 5, 6)에만 0,1  1=Projection 
	//  double Force[5];         // PU, P1, P2, P3, P4          (nSubLoadType=0 인 경우 사용)
	//  double EdgeLoad[3];      // PU, P1, P2 단위길이당 하중  (nSubLoadType=2 인 경우 사용)
	//  double Vector[3];        // LoadDirection == Vector인 경우
	if(Data.LoadDirectionNew < 4 || Data.LoadDirectionNew > 6)return;
	if(Data.Projection == 0)return;

	T_ELEM_K KeyElem=Key.key.entity;
	T_ELEM_D DataElem;
	GetElem(KeyElem, DataElem);
	if(Data.LoadType == 1 && DataElem.eltyp != PLATE_EL && DataElem.eltyp != PLSTRS_EL)return;
	if(Data.LoadType == 3 && DataElem.eltyp != SOLID_EL)return;
	double factor=0.;
	double xyz[4][3],xyzproj[4][3];
	int nNode=GetNumNode(DataElem.eltyp, DataElem.elnod);
	if(Data.LoadType == 1)
	{
		if(Data.nSubLoadType == 0)  // Plate Face
		{
			double dArea=m_pDoc->calcLAVElem(DataElem);
			T_NODE_D DataNode;
			for(int i=0; i<nNode; i++)
			{
				GetNode(DataElem.elnod[i], DataNode);
				xyz[i][0]=DataNode.x;
				xyz[i][1]=DataNode.y;
				xyz[i][2]=DataNode.z;
				if(Data.LoadDirectionNew == 4)xyz[i][0]=0.;
				if(Data.LoadDirectionNew == 5)xyz[i][1]=0.;
				if(Data.LoadDirectionNew == 6)xyz[i][2]=0.;
			}
			double Area1=CMathFunc::mathArea(xyz[0], xyz[1], xyz[2]);
			double Area2=0.;
			if(nNode > 3)Area2=CMathFunc::mathArea(xyz[0], xyz[2], xyz[3]);
			double dAreaProj=Area1+Area2;
			factor=dAreaProj/dArea;
		}
		else if(Data.nSubLoadType == 2)  // Plate Edge
		{
			T_NODE_D DataNode1, DataNode2;
			factor=1.;
			for(int i=0; i<nNode; i++)
			{
				if(i == Data.nEdgeFace-1)
				{
					GetNode(DataElem.elnod[i          ], DataNode1);
					GetNode(DataElem.elnod[(i+1)%nNode], DataNode2);
					xyz[0][0]=DataNode1.x, xyz[0][1]=DataNode1.y, xyz[0][2]=DataNode1.z;
					xyz[1][0]=DataNode2.x, xyz[1][1]=DataNode2.y, xyz[1][2]=DataNode2.z;
					double dLength=CMathFunc::mathLength(xyz[0][0]-xyz[1][0], xyz[0][1]-xyz[1][1], xyz[0][2]-xyz[1][2]);
					if(Data.LoadDirectionNew == 4){xyz[0][0]=0.,xyz[1][0]=0.;};
					if(Data.LoadDirectionNew == 5){xyz[0][1]=0.,xyz[1][1]=0.;};
					if(Data.LoadDirectionNew == 6){xyz[0][2]=0.,xyz[1][2]=0.;};
					double dLengthProj=CMathFunc::mathLength(xyz[0][0]-xyz[1][0], xyz[0][1]-xyz[1][1], xyz[0][2]-xyz[1][2]);
					factor=dLengthProj/dLength;
				}
			}
		}
	}
	else if(Data.LoadType == 3)        // Solid Face
	{
		const int Solid4Node[4][4]={ 0, 1, 2,-1,  0, 1, 3,-1,  1, 2, 3,-1,  2, 0, 3,-1};
		const int Solid6Node[5][4]={ 0, 1, 2,-1,  3, 4, 5,-1,  0, 1, 4, 3,  1, 2, 5, 4,  2, 0, 3, 5};
		const int Solid8Node[6][4]={ 0, 1, 2, 3,  4, 5, 6, 7,  0, 1, 5, 4,  1, 2, 6, 5,  2, 3, 7, 6,  3, 0, 4, 7};
		int nVertex=4;
		if(nNode == 4 && Solid4Node[Data.nEdgeFace-1][3] == -1)nVertex=3;
		if(nNode == 6 && Solid6Node[Data.nEdgeFace-1][3] == -1)nVertex=3;
		if(nNode == 8 && Solid8Node[Data.nEdgeFace-1][3] == -1)nVertex=3;

		T_NODE_D DataNode;
		for(int i=0; i<nVertex; i++)
		{
			T_NODE_K KeyNode;
			if(nNode == 4)KeyNode=DataElem.elnod[Solid4Node[Data.nEdgeFace-1][i]];
			if(nNode == 6)KeyNode=DataElem.elnod[Solid6Node[Data.nEdgeFace-1][i]];
			if(nNode == 8)KeyNode=DataElem.elnod[Solid8Node[Data.nEdgeFace-1][i]];
			GetNode(KeyNode, DataNode);
			xyz[i][0]=DataNode.x;
			xyz[i][1]=DataNode.y;
			xyz[i][2]=DataNode.z;
			xyzproj[i][0]=DataNode.x;
			xyzproj[i][1]=DataNode.y;
			xyzproj[i][2]=DataNode.z;
			if(Data.LoadDirectionNew == 4)xyzproj[i][0]=0.;
			if(Data.LoadDirectionNew == 5)xyzproj[i][1]=0.;
			if(Data.LoadDirectionNew == 6)xyzproj[i][2]=0.;
		}
		double Area1=CMathFunc::mathArea(xyz[0], xyz[1], xyz[2]);
		double Area2=0.;
		if(nVertex > 3)Area2=CMathFunc::mathArea(xyz[0], xyz[2], xyz[3]);
		double dArea=Area1+Area2;
		double Area3=CMathFunc::mathArea(xyzproj[0], xyzproj[1], xyzproj[2]);
		double Area4=0.;
		if(nVertex > 3)Area4=CMathFunc::mathArea(xyzproj[0], xyzproj[2], xyzproj[3]);
		double dAreaProj=Area3+Area4;
		factor=dAreaProj/dArea;
	}
	for(int i=0; i<5; i++)rDataNew.Force[i]*=factor;
	for(int i=0; i<3; i++)rDataNew.EdgeLoad[i]*=factor;
}

