BOOL CAttrCtrl::GetSerialPrst(T_ELEM_K Key,T_PRST_KEY& rKeySerial)
{
	T_PRST_K key;
	T_PRST_D data;
	key.key.entity=Key;

	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_prst.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

void CAttrCtrl::GetPrstKeyList(CArray<T_PRST_K, T_PRST_K>& rKeyList)
{
    rKeyList.RemoveAll();

    POSITION pos;
    T_PRST_K Key;
    T_PRST_D Data;
    pos = GetStartPrst();
    while ( pos != NULL )
    {
        GetNextPrst(pos, Key, Data);
        rKeyList.Add(Key);
    }
    if ( rKeyList.GetSize() > 0 )CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::MakeKeyPrst(T_ELEM_K Key,T_PRST_K& rKey)
{
	rKey.key.entity=Key;
	rKey.key.serial=0;

	T_PRST_KEY KeySerial;
	if(!GetSerialPrst(Key, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

