void EquivPrestressLoad(double & Pxi,double & Pzi,double & Myi,double & Pxj,double & Pzj,double & Myj,double wx[4],double wz[4],double my[4],
						const double ei,const double ej,const double em,const double P,const double l, const int nDir)
{
	int i=0;
	Pxi=0.;Pzi=0.;Myi=0.;Pxj=0.;Pzj=0.;Myj=0.;
	for(int i = 0;i<4;i++) {
		wx[i]=0.;wz[i]=0.;my[i]=0.;
	}
	double  fact   = 1.;  ;     // Local Z    
	if(nDir==0) fact = -1.;	// Local y


	double * e      = new double[5];
	double * height = new double[5];
	for(int i = 0;i<5;i++) {
		e[0] = ei;
		e[1] = (3.*ei-ej+6.*em)/8.;
		e[2] = em;
		e[3] = (-ei+3.*ej+6.*em)/8.;
		e[4] = ej;
		height[0] = (3.*ei+ej-4.*em)*fact;
		height[1] = (2.*(ei-em))*fact;
		height[2] = (ei-ej)*fact;
		height[3] =(-2.*(ej-em))*fact;
		height[4] =(-ei-3.*ej+4.*em)*fact;
	}
	double width=l;
	for(int i = 0;i<4;i++) {
		double leg_i=0.;
		double leg_j=0.;
		double cos_theta_i=0.,sin_theta_i=0.;
		double cos_theta_j=0.,sin_theta_j=0.;
		double Px1=0.,Pz1=0.,My1=0.,Px2=0.,Pz2=0.,My2=0.;

		leg_i    = pow(width,2.)+pow(height[i],2.);
		leg_i    = pow(leg_i,.5);
		leg_j    = pow(width,2.)+pow(height[i+1],2.);
		leg_j    = pow(leg_j,.5);

		cos_theta_i = width/leg_i;
		cos_theta_j = width/leg_j;
		sin_theta_i = height[i]/leg_i;
		sin_theta_j = height[i+1]/leg_j;

		Px1 = P*cos_theta_i;
		Pz1 =-P*sin_theta_i*fact;
		My1 = Px1*e[i]*fact;
		Px2 =-P*cos_theta_j;
		Pz2 = P*sin_theta_j*fact;
		My2 = Px2*e[i+1]*fact;
		if(i==0) {
			Pxi = Px1;
			Pzi = Pz1;
			Myi = My1;
		}
		else if(i==3) {
			Pxj = Px2;
			Pzj = Pz2;
			Myj = My2;
		}
		wx[i]  =-(Px1+Px2)/(l/4.);
		wz[i]  =-(Pz1+Pz2)/(l/4.);
		my[i]  =-(My1+My2)/(l/4.)-Pz1*fact -wz[i]*(l/4.)/2.*fact;
	}
	delete[] e;
	delete[] height;
}

