BOOL CAttrCtrl::MakeKeyStmp(T_STLD_K KeyStld,T_LDGR_K KeyLdgr,T_STMP_K& rKey)
{
	T_STMP_K Key;
	T_STMP_D Data;
	POSITION pos = GetStartStmp();
	while (pos)
	{
		GetNextStmp(pos, Key, Data);
		if (Data.LoadCaseKey == KeyStld && Data.GroupKey == KeyLdgr)
		{
			rKey = Key;
			return TRUE;
		}
	}
	rKey = GetStartNumStmp();
	return TRUE;
}

void CAttrCtrl::GetStmpKeyList(CArray<T_STMP_K, T_STMP_K>& rKeyList)
{
    rKeyList.RemoveAll();

    POSITION pos;
    T_STMP_K Key;
    T_STMP_D Data;
    pos = GetStartStmp();
    while ( pos != NULL )
    {
        GetNextStmp(pos, Key, Data);
        rKeyList.Add(Key);
    }
    if ( rKeyList.GetSize() > 0 )CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::ExistStmp(T_STMP_K Key)
{
	T_STMP_D Data;
	return m_pDataMemb->m_stmp.Get(Key,Data);
}

BOOL CAttrCtrl::ExistStmp(T_STLD_K StldKey, T_LDGR_K LdgrKey)
{
	T_STMP_K key;
	T_STMP_D data;
	POSITION pos = GetStartStmp();
	while (pos)
	{
		GetNextStmp(pos, key, data);
		if (data.LoadCaseKey == StldKey && data.GroupKey == LdgrKey)
			return TRUE;
	}
	return FALSE;
}

BOOL CAttrCtrl::GetStmp(T_STMP_K Key,T_STMP_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_stmp.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitStmpOut(rData);
	return bReturn;
}

BOOL CAttrCtrl::GetStmp(T_STLD_K StldKey, CArray<T_STMP_K, T_STMP_K>& rKey, CArray<T_STMP_D, T_STMP_D&>& rData)
{
	rKey.RemoveAll();
	rData.RemoveAll();
	T_STMP_K key;
	T_STMP_D data;
	POSITION pos = GetStartStmp();
	while (pos)
	{
		GetNextStmp(pos, key, data);
		if (data.LoadCaseKey == StldKey) 
		{
			rKey.Add(key);
			rData.Add(data);
		}
	}
	if (rKey.GetSize() < 1) return FALSE;
	return TRUE;
}

