BOOL CAttrCtrl::GetSerialNtmp(T_NODE_K KeyNode,T_STLD_K KeyStld,T_LDGR_K KeyLdgr,T_NTMP_KEY& rKeySerial)
{
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetListFromBaseDB(KeyNode, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_NTMP_CMD)
		{
			T_NTMP_K key;
			T_NTMP_D data;
			key.keymap=ListData.nKey;
			m_pDataMemb->m_ntmp.GetFromBaseDB(key, data);
			if(data.LoadCaseKey == KeyStld && data.GroupKey == KeyLdgr)
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_NTMP_K key;
	T_NTMP_D data;
	key.key.entity=KeyNode;
	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_ntmp.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

void CAttrCtrl::GetNtmpKeyList(CArray<T_NTMP_K, T_NTMP_K>& rKeyList)
{
    rKeyList.RemoveAll();

    POSITION pos;
    T_NTMP_K Key;
    T_NTMP_D Data;
    pos = GetStartNtmp();
    while ( pos != NULL )
    {
        GetNextNtmp(pos, Key, Data);
        rKeyList.Add(Key);
    }
    if ( rKeyList.GetSize() > 0 )CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::MakeKeyNtmp(T_NODE_K KeyNode,T_STLD_K KeyStld,T_LDGR_K KeyLdgr,T_NTMP_K& rKey)
{
	rKey.key.entity=KeyNode;
	rKey.key.serial=0;

	T_NTMP_KEY KeySerial;
	if(!GetSerialNtmp(KeyNode, KeyStld, KeyLdgr, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

