BOOL CAttrCtrl::GetNtmpLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, BOOL bAllLdgr, CArray<T_LDGR_K, T_LDGR_K>& raLdgrKey, T_NODE_K KeyNode, T_NTMP_D& DataNtmp)
{
	DataNtmp.Initialize();
	if(!CheckLcomLabel(bAllLoadCase, DataLcom))return FALSE;

	CMap<T_LDGR_K, T_LDGR_K, T_LDGR_K, T_LDGR_K> mapLdgr;
	if (!bAllLdgr)
	{
		mapLdgr.InitHashTable(11);
		for (int i = 0; i < raLdgrKey.GetSize(); i++)mapLdgr.SetAt(raLdgrKey[i], raLdgrKey[i]);
	}

	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_NTMP_CMD)
		{
			T_NTMP_K key;
			T_NTMP_D data;
			key.keymap=ListData.nKey;
			GetNtmp(key, data);
			if (!bAllLdgr && !mapLdgr.Lookup(data.GroupKey, data.GroupKey)) continue;
			if(bAllLoadCase)
			{
				DataNtmp.dblNodalTemp+=(data.dblNodalTemp-m_pDoc->m_Styp.dblInitTemp);
			}
			else
			{
				double dStldFactor=0., dStagFactor=0.;
				if(!GetLcomStldFactor(data.LoadCaseKey, DataLcom, dStldFactor, dStagFactor))return FALSE;  
				T_STLD_D DataStld;
				if(dStldFactor != 0.)
				{
					DataNtmp.dblNodalTemp+=(data.dblNodalTemp-m_pDoc->m_Styp.dblInitTemp)*dStldFactor;
				}
				if(dStagFactor != 0. && m_pDoc->m_pStagCtrl->IsActiveLdgrKey(data.GroupKey))
				{
					DataNtmp.dblNodalTemp+=(data.dblNodalTemp-m_pDoc->m_Styp.dblInitTemp)*dStagFactor;
				}
			}
		}
	}
	if(DataNtmp.dblNodalTemp != 0.)
	{
		DataNtmp.dblNodalTemp += m_pDoc->m_Styp.dblInitTemp;
		return TRUE;
	}
	return FALSE;
}

