BOOL CAttrCtrl::GetEtmpLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, BOOL bAllLdgr, CArray<T_LDGR_K, T_LDGR_K>& raLdgrKey, T_ELEM_K KeyElem, T_ETMP_D& DataEtmp)
{
	DataEtmp.Initialize();
	if(!CheckLcomLabel(bAllLoadCase, DataLcom))return FALSE;

	CMap<T_LDGR_K, T_LDGR_K, T_LDGR_K, T_LDGR_K> mapLdgr;
	if (!bAllLdgr)
	{
		mapLdgr.InitHashTable(11);
		for (int i = 0; i < raLdgrKey.GetSize(); i++)mapLdgr.SetAt(raLdgrKey[i], raLdgrKey[i]);
	}

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_ETMP_CMD)
		{
			T_ETMP_K key;
			T_ETMP_D data;
			key.keymap=ListData.nKey;
			GetEtmp(key, data);
			if (!bAllLdgr && !mapLdgr.Lookup(data.GroupKey, data.GroupKey)) continue;
			if(bAllLoadCase)
			{
				DataEtmp.dblElemTemp+=(data.dblElemTemp-m_pDoc->m_Styp.dblInitTemp);
			}
			else
			{
				double dStldFactor=0., dStagFactor=0.;
				if(!GetLcomStldFactor(data.LoadCaseKey, DataLcom, dStldFactor, dStagFactor))return FALSE;  
				T_STLD_D DataStld;
				if(dStldFactor != 0.)
				{
					DataEtmp.dblElemTemp+=(data.dblElemTemp-m_pDoc->m_Styp.dblInitTemp)*dStldFactor;
				}
				if(dStagFactor != 0. && m_pDoc->m_pStagCtrl->IsActiveLdgrKey(data.GroupKey))
				{
					DataEtmp.dblElemTemp+=(data.dblElemTemp-m_pDoc->m_Styp.dblInitTemp)*dStagFactor;
				}
			}
		}
	}
	if(DataEtmp.dblElemTemp != 0.)
	{
		DataEtmp.dblElemTemp += m_pDoc->m_Styp.dblInitTemp;
		return TRUE;
	}
	return FALSE;
}

