int CAttrCtrl::GetElemFire(T_ELEM_K_LIST& aKey)
{
	if(!ExistStld(FIRE_LOAD_CASE_NAME))
		return FALSE;
	T_STLD_K FireStlK = GetStldKey(FIRE_LOAD_CASE_NAME);
	POSITION pos = GetStartEtmp();
	T_ETMP_K EtmpK; T_ETMP_D EtmpD;
	aKey.RemoveAll();
	while(pos)
	{
		GetNextEtmp(pos, EtmpK, EtmpD);
		if(EtmpD.LoadCaseKey == FireStlK)
			aKey.Add(EtmpK.key.entity);
	}
	return aKey.GetCount();
}

BOOL CAttrCtrl::IsExistFire(const T_ELEM_K_LIST& aKey)
{
	T_ELEM_K_LIST aFireKey;
	int nCount = GetElemFire(aFireKey);
	for(int i = 0;i < nCount;i++)
	{
		for(int j = 0;j < aKey.GetSize();j++)
			if(aKey[j] == aFireKey[i])
				return TRUE;
	}
	return FALSE;
}

