void CAttrCtrl::GetBtmpLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, BOOL bAllLdgr, CArray<T_LDGR_K, T_LDGR_K>& raLdgrKey, T_ELEM_K KeyElem, CArray<T_BTMP_D, T_BTMP_D&>& rarData)
{
	rarData.RemoveAll();
	if(!CheckLcomLabel(bAllLoadCase, DataLcom))return;

	CMap<T_LDGR_K, T_LDGR_K, T_LDGR_K, T_LDGR_K> mapLdgr;
	if (!bAllLdgr)
	{
		mapLdgr.InitHashTable(11);
		for (int i = 0; i < raLdgrKey.GetSize(); i++)mapLdgr.SetAt(raLdgrKey[i], raLdgrKey[i]);
	}

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_BTMP_CMD)
		{
			T_BTMP_K key;
			T_BTMP_D data;
			key.keymap=ListData.nKey;
			GetBtmp(key, data);
			if (!bAllLdgr && !mapLdgr.Lookup(data.GroupKey, data.GroupKey)) continue;
			if(bAllLoadCase)
			{
				// Factor가 없으므로 초기온도 고려안해도 됨
				rarData.Add(data);
			}
			else
			{
				double dStldFactor=0., dStagFactor=0.;
				if(!GetLcomStldFactor(data.LoadCaseKey, DataLcom, dStldFactor, dStagFactor))return;  
				T_STLD_D DataStld;
				if(dStldFactor != 0.)
				{
					// 초기온도와의 온도차에 factor곱하고 여기에 초기온도 더해준다.
					for (int i = 0; i < data.SectTmp.GetSize(); i++)
					{
						if (data.SectTmp[i].nMaterial == 0) break;
						data.SectTmp[i].dT1 = (data.SectTmp[i].dT1-m_pDoc->m_Styp.dblInitTemp)*dStldFactor+m_pDoc->m_Styp.dblInitTemp;
						data.SectTmp[i].dT2 = (data.SectTmp[i].dT2-m_pDoc->m_Styp.dblInitTemp)*dStldFactor+m_pDoc->m_Styp.dblInitTemp;
					}
					rarData.Add(data);
				}
				if(dStagFactor != 0. && m_pDoc->m_pStagCtrl->IsActiveLdgrKey(data.GroupKey))
				{
					// 초기온도와의 온도차에 factor곱하고 여기에 초기온도 더해준다.
					for (int i = 0; i < data.SectTmp.GetSize(); i++)
					{
						if (data.SectTmp[i].nMaterial == 0) break;
						data.SectTmp[i].dT1 = (data.SectTmp[i].dT1-m_pDoc->m_Styp.dblInitTemp)*dStagFactor+m_pDoc->m_Styp.dblInitTemp;
						data.SectTmp[i].dT2 = (data.SectTmp[i].dT2-m_pDoc->m_Styp.dblInitTemp)*dStagFactor+m_pDoc->m_Styp.dblInitTemp;
					}
					rarData.Add(data);
				}
			}
		}
	}
	return;
}

