// h1, h2를 Centroid로부터 거리로 바꾸어 주는 함수
BOOL CAttrCtrl::ConvertBtmp4Label(T_BTMP_K Key, T_BTMP_D& rData)
{
	T_ELEM_D DataElem;  
	T_SECT_D DataSect;
	double dCenhi, dCenbi, dCenhj, dCenbj, dCentroid, dCentroidOffset;
	double dDimhi, dDimbi, dDimhj, dDimbj, dDimension;
	double dH1, dH2;

	if(!GetBtmp(Key, rData)) return FALSE;
	if(!GetElem(Key.key.entity, DataElem)) return FALSE;
	if(!GetSect(DataElem.elpro, DataSect)) return FALSE;
	// Tapered Section Group 고려
	m_pDoc->calcElemSect(Key.key.entity, DataSect, 1, FALSE, FALSE);

	int nOffsetPoint = DataSect.SectBefore.nOffsetPoint;

	//if(!GetSectDimen(DataElem.elpro, dDimhi, dDimbi, dDimhj, dDimbj, NULL, FALSE)) return FALSE; 
	//if(!GetSectCentroid(DataElem.elpro, dCenhi, dCenbi, dCenhj, dCenbj)) return FALSE;
	if (!GetSectDimen(DataSect, dDimhi, dDimbi, dDimhj, dDimbj, NULL, FALSE)) return FALSE;
	if (!GetSectCentroid(DataSect, dCenhi, dCenbi, dCenhj, dCenbj)) return FALSE;
	if(rData.nDirection == 0) // Local-y
	{
		dCentroid = (dCenbi + dCenbj) / 2.0;
		dDimension = (dDimbi + dDimbj) / 2.0;
	}
	else  // Local-z
	{
		dCentroid = (dCenhi + dCenhj) / 2.0;
		dDimension = (dDimhi + dDimhj) / 2.0;
	}
	dCentroidOffset = dCentroid - dDimension / 2.;

	int nTemp=0;
	for(int i = 0; i < rData.SectTmp.GetSize(); i++)
	{
		if(rData.SectTmp[i].nMaterial == 0) break;
		nTemp=i+1;
	}
	for(int i = 0; i < nTemp; i++)
	{    
		dH1 = rData.SectTmp[i].dH1;
		dH2 = rData.SectTmp[i].dH2;
		if(rData.nType==0) // general
		{
			if(rData.nRefPosition == 1)  // + End(Top)
			{
				dH1 = dDimension - dCentroid - dH1;
				dH2 = dDimension - dCentroid - dH2;
			}
			else if(rData.nRefPosition == 2)  // - End(Bottom)
			{
				dH1 = dH1 - dCentroid;
				dH2 = dH2 - dCentroid;
			}
		}
		else // psc/composite
		{
			if(rData.SectTmp[i].nRef == 0)  // Top
			{
				dH1 = dDimension - dCentroid - dH1;
				dH2 = dDimension - dCentroid - dH2;
			}
			else // Bottom
			{
				dH1 = dH1 - dCentroid;
				dH2 = dH2 - dCentroid;
			}
		}
		dH1 += dCentroidOffset;
		dH2 += dCentroidOffset;
		/* Offset 적용은 gr에서 처리 05.01.12
		if(nOffsetPoint == 1 || nOffsetPoint == 2 || nOffsetPoint == 3)  // Top
		{
		dH1 = dH1 + dCentroidOffset - dDimension / 2.;
		dH2 = dH2 + dCentroidOffset - dDimension / 2.;
		}
		else if(nOffsetPoint == 4 || nOffsetPoint == 6)  // Center
		{
		dH1 = dH1 + dCentroidOffset;
		dH2 = dH2 + dCentroidOffset;
		}
		else if(nOffsetPoint == 7 || nOffsetPoint == 8 || nOffsetPoint == 9)  // Bottom
		{
		dH1 = dH1 + dCentroidOffset + dDimension / 2.;
		dH2 = dH2 + dCentroidOffset + dDimension / 2.;
		}
		*/

		rData.SectTmp[i].dH1 = dH1;
		rData.SectTmp[i].dH2 = dH2;
	}

	return TRUE;
}

