BOOL CAttrCtrl::CheckAllPtmpByThick(T_THIK_K KeyThik, T_THIK_D DataThik,BOOL bDelete/*= FALSE*/ )
{
	T_PTMP_K PtmpK;
	T_PTMP_D PtmpD;

	POSITION pos = GetStartPtmp();
	while (pos)
	{
		GetNextPtmp(pos, PtmpK, PtmpD);

		T_ELEM_D DataElem;
		if (!GetElem(PtmpK.key.entity, DataElem))
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_IREG_ELDT_ERR), _LS(IDS_DB_DT_PTMP), PtmpK.key.entity);
		if (DataElem.eltyp != PLATE_EL)
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_IREG_ELDT_ERR), _LS(IDS_DB_DT_PTMP), PtmpK.key.entity);

		if (KeyThik != DataElem.elpro) continue;

		if (bDelete)
			return FALSE;

		if (DataThik.nType == 0)
		{
			if (DataThik.Value.nThickType == 1)
			{
				if (DataThik.Value.ThickIn != DataThik.Value.ThickOut)
					return FALSE;
					//return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_IREG_ELDT_ERR), _LS(IDS_DB_DT_PTMP), PtmpK.key.entity);
			}
		}
		else
		{
			return FALSE;
			//return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_IREG_ELDT_ERR), _LS(IDS_DB_DT_PTMP), PtmpK.key.entity);
		}
	}

	return TRUE;
}

BOOL CAttrCtrl::CheckAllPtmpByMatl(T_MATL_K KeyMatl, T_MATL_D DataMatl, BOOL bDelete/*= FALSE*/ )
{
	T_PTMP_K PtmpK;
	T_PTMP_D PtmpD;

	POSITION pos = GetStartPtmp();
	while (pos)
	{
		GetNextPtmp(pos, PtmpK, PtmpD);

		T_ELEM_D DataElem;
		if (!GetElem(PtmpK.key.entity, DataElem))
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_IREG_ELDT_ERR), _LS(IDS_DB_DT_PTMP), PtmpK.key.entity);
		if (DataElem.eltyp != PLATE_EL)
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_IREG_ELDT_ERR), _LS(IDS_DB_DT_PTMP), PtmpK.key.entity);

		if (KeyMatl != DataElem.elmat) continue;

		if (bDelete)
			return FALSE;

		if (DataMatl.Data1.Analysis.nIsoOrtho != 0)
			return FALSE; 			//return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_IREG_ELDT_ERR), _LS(IDS_DB_DT_PTMP), PtmpK.key.entity);
	}

	return TRUE;
}


BOOL CAttrCtrl::CheckAllPtmpByElem(T_ELEM_K KeyElem, T_ELEM_D DataElem, BOOL bDelete/*= FALSE*/)
{
	T_PTMP_K PtmpK;
	T_PTMP_D PtmpD;

	POSITION pos = GetStartPtmp();
	while (pos)
	{
		GetNextPtmp(pos, PtmpK, PtmpD);
		
		if (KeyElem != PtmpK.key.entity) continue;

		if (bDelete)
			return FALSE;

		if (DataElem.eltyp != PLATE_EL)
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_DT_PTMP_ELEM_Err));

		T_MATL_D DataMatl;
		if (!GetMatl(DataElem.elmat, DataMatl))
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_DT_PTMP_MATL_Err));
		if (DataMatl.Data1.Analysis.nIsoOrtho != 0)
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_DT_PTMP_MATL_Err));

		T_THIK_D DataThik;
		if (!GetThik(DataElem.elpro, DataThik))
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_DT_PTMP_THICK_Err));
	
		if (DataThik.nType == 0)
		{
			if (DataThik.Value.nThickType == 1)
			{
				if (DataThik.Value.ThickIn != DataThik.Value.ThickOut)
					return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_DT_PTMP_THICK_Err));
			}
		}
		else
		{
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_DT_PTMP_THICK_Err));
		}
	}

	return TRUE;
}

