BOOL CAttrCtrl::GetSerialGtmp(T_ELEM_K Key,T_GTMP_KEY& rKeySerial)
{
	T_GTMP_K key;
	T_GTMP_D data;
	key.key.entity=Key;

	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_gtmp.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

void CAttrCtrl::GetGtmpKeyList(CArray<T_GTMP_K, T_GTMP_K>& rKeyList)
{
    rKeyList.RemoveAll();

    POSITION pos;
    T_GTMP_K Key;
    T_GTMP_D Data;
    pos = GetStartGtmp();
    while ( pos != NULL )
    {
        GetNextGtmp(pos, Key, Data);
        rKeyList.Add(Key);
    }
    if ( rKeyList.GetSize() > 0 )CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::MakeKeyGtmp(T_ELEM_K Key,T_GTMP_K& rKey)
{
	rKey.key.entity=Key;
	rKey.key.serial=0;

	T_GTMP_KEY KeySerial;
	if(!GetSerialGtmp(Key, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

