////////////// pnld ////////////////

void CAttrCtrl::GetPnldList(CArray<CString, CString&>& rstrPnldList)
{
	rstrPnldList.RemoveAll();

	int nCount=GetCountPnld();
	if(nCount == 0)return;

	POSITION pos;
	T_PNLD_K Key;
	T_PNLD_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartPnld();
		while(pos != NULL)
		{
			GetNextPnld(pos, Key, Data);
			if(Data.nSeq == i)
			{
				rstrPnldList.Add(Data.LoadTypeName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetPnldKeyList(CArray<T_PNLD_K, T_PNLD_K>& rPnldKeyList)
{
	/*
	rPnldKeyList.RemoveAll();

	int nCount=GetCountPnld();
	if(nCount == 0)return;

	POSITION pos;
	T_PNLD_K Key;
	T_PNLD_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartPnld();
	while(pos != NULL)
	{
	GetNextPnld(pos, Key, Data);
	if(Data.nSeq == i)
	{
	rPnldKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rPnldKeyList.RemoveAll();
	int nCount=GetCountPnld();
	if(nCount == 0)return;

	CArray<T_PNLD_K, T_PNLD_K> aPnldKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rPnldKeyList.SetSize(nCount);
	aPnldKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_PNLD_K Key;
	T_PNLD_D Data;
	int i = 0;
	pos = GetStartPnld();
	while (pos != NULL)
	{
		GetNextPnld(pos, Key, Data);
		aPnldKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nSeq;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rPnldKeyList[i] = aPnldKey[ix];
	}
}

