BOOL CAttrCtrl::GetPnld(CString& rLoadTypeName, T_PNLD_D& rData)
{
	T_PNLD_K key;
	T_PNLD_D data;
	CString strLoadTypeName=rLoadTypeName;
	strLoadTypeName.TrimRight();

	POSITION pos=m_pDataMemb->m_pnld.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_pnld.GetNext(pos,key,data);
		if(strLoadTypeName.CompareNoCase(data.LoadTypeName) == 0)
		{
			m_pUnitCtrl->ConvertUnitPnldOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

