BOOL CAttrCtrl::IsExistCranBraking()
{
	CArray<T_CRAN_K, T_CRAN_K> aCranK;
	GetCranKeyList(aCranK);
	int nSize = aCranK.GetSize();

	T_CRAN_D CranD;
	for(int i=0; i<nSize; ++i)
	{
		VERIFY(GetCran(aCranK[i], CranD));
		if(CranD.dLongitudinal!=0.0 || CranD.dTransverse!=0.0) return TRUE;
	}

	return FALSE;
}

