// 노드 리스트, CranD 안의 Tolerance, dWidth 를 입력받아 대응하는 노드를 찾아서 CranD에 채워주는 함수
BOOL CAttrCtrl::VerifyAndSaveNodes(CArray<T_NODE_K, T_NODE_K>& arList, T_CRAN_D& CranD, CString& strErr)
{
	const double dTolerance = CranD.dTolerance;
	const double dWidth = CranD.dWidth;
	if (dTolerance < 0.0) 
	{
		//GSaveHistoryFormatNF(_LS("Error : Tolerance >= 0"));
		strErr = _LS(IDS_DB_ERR_TOLERANCE);
		return FALSE; 
	}
	if (fabs(dWidth) < 1.e-7) 
	{
		//GSaveHistoryFormatNF(_LS("Error : Width cannot be 0."));
		strErr = _LS(IDS_DB_ERR_WIDTH);
		return FALSE; 
	}

	// 0. 노드 개수 체크 (>1)
	const int nCount = arList.GetSize();
	if (nCount < 2)
	{
		//GSaveHistoryFormatNF(_LS("Error : Insufficient number of nodes assigned(>=2)"));
		strErr = _LS(IDS_DB_ERR_NODE_INSUFF_AS);
		return FALSE; 
	}

	// 1. 동일 노드 체크
	for (int i=0 ; i<nCount ; ++i)
	{
		for (int j=0 ; j<nCount ; ++j)
			if (arList[i]==arList[j] && i!=j)
			{
				//GSaveHistoryFormatNF(_LS("Error : Assigned nodes are duplicated."));
				strErr = _LS(IDS_DB_ERR_NODE_DUPE);
				return FALSE;
			}
	}

	// 2. 유효한가 & 노드 데이터 가져오기
	CArray<T_NODE_D, T_NODE_D> arListD;
	arListD.RemoveAll();
	T_NODE_D NodeD;
	for (int i=0 ; i<nCount ; ++i)
	{
		if(!GetNode(arList[i], NodeD))
		{
			//GSaveHistoryFormatNF(_LS("Error : All assigned nodes are not valid."));
			strErr = _LS(IDS_DB_ERR_NODE_INVALID);
			return FALSE;
		}
		arListD.Add(NodeD);
	}

	// 3. Z 값 체크 (동일 평면)
	double dMaxZ, dMinZ;
	dMaxZ = dMinZ = arListD[0].z;
	for (int i=1 ; i<nCount ; ++i)
	{
		if (arListD[i].z > dMaxZ) dMaxZ = arListD[i].z;
		if (arListD[i].z < dMinZ) dMinZ = arListD[i].z;
	}
	if (dMaxZ-dMinZ > dTolerance)
	{
		//GSaveHistoryFormatNF(_LS("Error : All assigned nodes are not in a same XY plane."));
		strErr = _LS(IDS_DB_ERR_NODE_PLANE);
		return FALSE;
	}

	// 4. 시작점 끝점 찾기
	int idxStart=0;
	int idxEnd=0;
	int idxMinX, idxMaxX, idxMinY, idxMaxY;
	idxMinX = idxMaxX = idxMinY = idxMaxY =0;
	double dMinX, dMaxX, dMinY, dMaxY;
	dMinX = dMaxX = arListD[0].x;
	dMinY = dMaxY = arListD[0].y;
	for (int i=1 ; i<nCount ; ++i)
	{
		if (arListD[i].x > dMaxX) {dMaxX = arListD[i].x; idxMaxX=i;}
		if (arListD[i].x < dMinX) {dMinX = arListD[i].x; idxMinX=i;}
		if (arListD[i].y > dMaxY) {dMaxY = arListD[i].y; idxMaxY=i;}
		if (arListD[i].y < dMinY) {dMinY = arListD[i].y; idxMinY=i;}
	}
	BOOL bDecideByX = FALSE;
	if (dMaxX-dMinX > dMaxY-dMinY) // X 값으로 판단
	{
		bDecideByX = TRUE;
		if (arListD[1].x-arListD[0].x > 0) { idxStart=idxMinX; idxEnd=idxMaxX; }
		else { idxStart=idxMaxX; idxEnd=idxMinX; }
	}
	else // Y 값으로 판단
	{
		bDecideByX = FALSE;
		if (arListD[1].y-arListD[0].y > 0) { idxStart=idxMinY; idxEnd=idxMaxY; }
		else { idxStart=idxMaxY; idxEnd=idxMinY; }
	}

	// 5. 일직선에 있나 판별
	const double ux = arListD[idxEnd].x - arListD[idxStart].x;
	const double uy = arListD[idxEnd].y - arListD[idxStart].y;
	const double x1 = arListD[idxStart].x;
	const double y1 = arListD[idxStart].y;
	double dDist = 0.0;
	const double dDenom = ux*ux+uy*uy;
	if (dDenom == 0.0) 
	{
		//GSaveHistoryFormatNF(_LS("Error : Assigned nodes are not in correct positions."));
		strErr = _LS(IDS_DB_ERR_NODE_POS);
		return FALSE; 
	}
	for (int i=0 ; i<nCount ; ++i)
	{
		dDist = fabs(uy*(arListD[i].x-x1)-ux*(arListD[i].y-y1))/sqrt(dDenom);
		if (dDist > dTolerance)
		{
			//GSaveHistoryFormatNF(_LS("Error : All assigned nodes are not in a line."));
			strErr = _LS(IDS_DB_ERR_NODE_LINE);
			return FALSE;
		}
	}

	// 6. 대응하는 노드들 찾아서 검증
	double v[3] = {ux, uy, 0.0}; // 직선에 수직한 벡터 찾기
	CMathFunc::mathNormalize(v[0], v[1], v[0], v[1]);
	CMathFunc::mathRotateZ( 90 , v[0], v[1], v[2]);
	v[0] *= dWidth;
	v[1] *= dWidth;
	double dTargetX = 0.0;
	double dTargetY = 0.0;
	double dTargetZ = 0.0;
	CArray<T_NODE_K, T_NODE_K> arAllNode;
	CArray<T_NODE_D, T_NODE_D> arAllNodeD;
	GetNodeKeyList(arAllNode);
	int nAllCount = arAllNode.GetSize();
	if (nAllCount <= nCount) 
	{
		//GSaveHistoryFormatNF(_LS("Error : Insufficient number of nodes in the model"));
		strErr = _LS(IDS_DB_ERR_NODE_INSUFF);
		return FALSE;
	}
	for (int i=0 ; i<nAllCount ; ++i) // 전체 노드 구해오기
		if(GetNode(arAllNode[i], NodeD)) arAllNodeD.Add(NodeD);

	CArray<T_NODE_K, T_NODE_K> arResultNode; // 결과 저장되는 어레이
	arResultNode.SetSize(nCount);
	for (int i=0 ; i<nCount ; ++i) // 찾기
	{
		dTargetX = arListD[i].x + v[0];
		dTargetY = arListD[i].y + v[1];
		dTargetZ = arListD[i].z;
		BOOL bFound = FALSE;
		double dDiff = 0.0;
		double dDiffSave = 0.0;
		for (int j=0 ; j<nAllCount ; ++j)
		{
			if (arList[i] == arAllNode[j]) continue;
			if (fabs(dTargetX-arAllNodeD[j].x) > dTolerance) continue;
			if (fabs(dTargetY-arAllNodeD[j].y) > dTolerance) continue;
			if (fabs(dTargetZ-arAllNodeD[j].z) > dTolerance) continue;
			dDiff = CMathFunc::mathLength(dTargetX, dTargetY, dTargetZ, arAllNodeD[j].x, arAllNodeD[j].y, arAllNodeD[j].z);
			if (dDiff > dTolerance) continue;
			if (bFound && dDiff < dDiffSave) // 더 가까운 것 찾은 경우
			{
				dDiffSave = dDiff;
				arResultNode[i] = arAllNode[j];
			}
			else
			{
				bFound = TRUE;
				dDiffSave = dDiff;
				arResultNode[i] = arAllNode[j];
			}
		} // for j
		if (!bFound)
		{
			//CString strMsg = _LS("Error : There is no corresponding node to Node ");
			CString strMsg = _LS(IDS_DB_ERR_NODE_NOT_FOUND);
			CString strNode;
			strNode.Format(_T("%d"), arList[i]);
			strMsg += strNode;
			strErr = strMsg;
			return FALSE;
		}
	} // for i

	// 7. 순서대로 소팅
	CArray<double, double> arValue;
	CArray<int, int> arIndex;
	if (bDecideByX)
	{
		if (arListD[1].x-arListD[0].x > 0)
			for(int i=0 ; i<nCount ; ++i) { arValue.Add(arListD[i].x); arIndex.Add(i);}
		else
			for(int i=0 ; i<nCount ; ++i) { arValue.Add(arListD[i].x*(-1)); arIndex.Add(i);}
	}
	else
	{
		if (arListD[1].y-arListD[0].y > 0)
			for(int i=0 ; i<nCount ; ++i) { arValue.Add(arListD[i].y); arIndex.Add(i);}
		else
			for(int i=0 ; i<nCount ; ++i) { arValue.Add(arListD[i].y*(-1)); arIndex.Add(i);}
	}

	CQSort::QSortDblWithIndex(arIndex.GetData(), arValue.GetData(), nCount);

	// 8. CranD에 복사
	CranD.arNode.RemoveAll();
	CranD.arNode2.RemoveAll();
	for (int i=0 ; i<nCount ; ++i)
	{
		if(arIndex[i] >= nCount) {ASSERT(0); return FALSE;}
		CranD.arNode.Add(arList[ arIndex[i] ]);
		CranD.arNode2.Add(arResultNode[ arIndex[i] ]);
	}

	return TRUE;
}

