void CAttrCtrl::GetPnla(T_NODE_K KeyNode, CArray<T_PNLA_K, T_PNLA_K>& rarKey, CArray<T_PNLA_D, T_PNLA_D&>& rarData)
{
	rarKey.RemoveAll();
	rarData.RemoveAll();

	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_PNLA_CMD)
		{
			T_PNLA_K key;
			T_PNLA_D data;
			key=ListData.nKey;
			GetPnla(key, data);
			rarKey.Add(key);
			rarData.Add(data);
		}
	}
}

void CAttrCtrl::GetPnlaLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, BOOL bAllLdgr, CArray<T_LDGR_K, T_LDGR_K>& raLdgrKey, CArray<T_PNLA_D, T_PNLA_D&>& rarData)
{
	rarData.RemoveAll();
	if(!CheckLcomLabel(bAllLoadCase, DataLcom))return;

	CMap<T_LDGR_K, T_LDGR_K, T_LDGR_K, T_LDGR_K> mapLdgr;
	if (!bAllLdgr)
	{
		mapLdgr.InitHashTable(11);
		for (int i = 0; i < raLdgrKey.GetSize(); i++)mapLdgr.SetAt(raLdgrKey[i], raLdgrKey[i]);
	}

	T_PNLA_K key;
	T_PNLA_D data;
	POSITION pos=GetStartPnla();
	while(pos != NULL)
	{
		GetNextPnla(pos, key, data);
		if (!bAllLdgr && !mapLdgr.Lookup(data.GroupKey, data.GroupKey)) continue;
		if(bAllLoadCase)
		{
			rarData.Add(data);
		}
		else
		{
			double dStldFactor=0., dStagFactor=0.;
			if(!GetLcomStldFactor(data.LoadCaseKey, DataLcom, dStldFactor, dStagFactor))return;  
			if(dStldFactor != 0.)
			{
				rarData.Add(data);
			}
			else if(dStagFactor != 0. && m_pDoc->m_pStagCtrl->IsActiveLdgrKey(data.GroupKey))
			{
				rarData.Add(data);
			}
		}
	}
	return;
}

