void CAttrCtrl::CalcWindLoad(T_WIND_D& rData, CArray<T_WINDLOAD, T_WINDLOAD&>& arWindLoad, int nDir/*=0*/)
{
	arWindLoad.RemoveAll();
	if(GetCountStor() == 0)return;

	T_WINDLOAD WindLoad;
	T_STOR_D DataStor;

	double dWind_RZ = 0.;
	if(nDir==0)
	{
		BOOL bCrossWind = FALSE;
		BOOL bTosionWind = FALSE;
		if(rData.nCodeType == CH_W_2012)
		{
			if(!rData.CodeParam.CH2012.bCrossVibration)
			{
				bCrossWind = rData.CodeParam.CH2012.bCross;
				bTosionWind = rData.CodeParam.CH2012.bTorsion;
				rData.CodeParam.CH2012.bTorsion = FALSE;
				rData.CodeParam.CH2012.bCross = FALSE;
			}
		}
		else if(rData.nCodeType == CH_W_2021)
		{
			if(!rData.CodeParam.CH2019.bCrossVibration)
			{
				bCrossWind = rData.CodeParam.CH2019.bCross;
				bTosionWind = rData.CodeParam.CH2019.bTorsion;
				rData.CodeParam.CH2019.bTorsion = FALSE;
				rData.CodeParam.CH2019.bCross = FALSE;
			}
		}
		else if (rData.nCodeType == DPT_W_2007)
		{
			bCrossWind = rData.CodeParam.DPT2007.Vibr.bAcross;
			bTosionWind = rData.CodeParam.DPT2007.Vibr.bTorsion;
			rData.CodeParam.DPT2007.Vibr.bAcross = FALSE;
			rData.CodeParam.DPT2007.Vibr.bTorsion = FALSE;
		}
		CLateralLoad LateralLoad;
		LateralLoad.MakeWindLoad(rData);
		if(rData.nCodeType == CH_W_2012)
		{
			if(!rData.CodeParam.CH2012.bCrossVibration)
			{
				rData.CodeParam.CH2012.bTorsion = bCrossWind;
				rData.CodeParam.CH2012.bCross = bTosionWind;
			}
		}
		else if(rData.nCodeType == CH_W_2021)
		{
			if(!rData.CodeParam.CH2019.bCrossVibration)
			{
				rData.CodeParam.CH2019.bTorsion = bCrossWind;
				rData.CodeParam.CH2019.bCross = bTosionWind;
			}
		}
		else if (rData.nCodeType == DPT_W_2007)
		{
			rData.CodeParam.DPT2007.Vibr.bAcross = bCrossWind;
			rData.CodeParam.DPT2007.Vibr.bTorsion = bTosionWind;
		}

		int nStory=LateralLoad.m_aWindLoad_X.GetSize();
		ASSERT(nStory == LateralLoad.m_aWindLoad_Y.GetSize());
		for(int i=0; i<nStory; i++)
		{
			T_STOR_K KeyStor=LateralLoad.m_aWindLoad_X[i].KeyStory;
			ASSERT(KeyStor == LateralLoad.m_aWindLoad_Y[i].KeyStory);
			if(KeyStor == 0)continue;
			GetStor(KeyStor, DataStor);
			WindLoad.Initialize();
			WindLoad.KeyStor=KeyStor;
			WindLoad.dPosition_X=DataStor.WindCenterX;
			WindLoad.dPosition_Y=DataStor.WindCenterY;
			WindLoad.dWind_X=LateralLoad.m_aWindLoad_X[i].dWindLoad;
			WindLoad.dWind_Y=LateralLoad.m_aWindLoad_Y[i].dWindLoad;
			dWind_RZ = LateralLoad.m_aWindLoad_RZ.GetSize()>0? LateralLoad.m_aWindLoad_RZ[i].dWindLoad : 0.;
			if(rData.nCodeType==KBC_W_2016 || rData.nCodeType==KDS_W_2019 || rData.nCodeType == KDS_W_2022) dWind_RZ = 0.;
			WindLoad.dWind_RZ=dWind_RZ + LateralLoad.m_aWindLoad_X[i].dTorsion+LateralLoad.m_aWindLoad_Y[i].dTorsion;
			if(WindLoad.dWind_X != 0. || WindLoad.dWind_Y != 0. || WindLoad.dWind_RZ != 0.) arWindLoad.Add(WindLoad);
		}
	}
	else if(nDir==1)
	{
		//
		BOOL bCrossWind = FALSE;
		BOOL bTosionWind = FALSE;
		BOOL bDPTWind = (rData.nCodeType == DPT_W_2007);
		if(rData.nCodeType == CH_W_2012)
		{
			if(!rData.CodeParam.CH2012.bCrossVibration)
			{
				bCrossWind = rData.CodeParam.CH2012.bCross;
				bTosionWind = rData.CodeParam.CH2012.bTorsion;
				rData.CodeParam.CH2012.bTorsion = FALSE;
				rData.CodeParam.CH2012.bCross = FALSE;
			}
		}
		else if(rData.nCodeType == CH_W_2021)
		{
			if(!rData.CodeParam.CH2019.bCrossVibration)
			{
				bCrossWind = rData.CodeParam.CH2019.bCross;
				bTosionWind = rData.CodeParam.CH2019.bTorsion;
				rData.CodeParam.CH2019.bTorsion = FALSE;
				rData.CodeParam.CH2019.bCross = FALSE;
			}
		}
		CLateralLoad LateralLoad;
		LateralLoad.MakeWindLoad(rData);
		if(rData.nCodeType == CH_W_2012)
		{
			if(!rData.CodeParam.CH2012.bCrossVibration)
			{
				rData.CodeParam.CH2012.bTorsion = bCrossWind;
				rData.CodeParam.CH2012.bCross = bTosionWind;
			}
		}
		else if(rData.nCodeType == CH_W_2021)
		{
			if(!rData.CodeParam.CH2019.bCrossVibration)
			{
				rData.CodeParam.CH2019.bTorsion = bCrossWind;
				rData.CodeParam.CH2019.bCross = bTosionWind;
			}
		}
		int nStory=LateralLoad.m_aWindLoad_X2.GetSize();
		ASSERT(nStory == LateralLoad.m_aWindLoad_Y2.GetSize());
		for(int i=0; i<nStory; i++)
		{
			T_STOR_K KeyStor=LateralLoad.m_aWindLoad_X2[i].KeyStory;
			ASSERT(KeyStor == LateralLoad.m_aWindLoad_Y2[i].KeyStory);
			if(KeyStor == 0)continue;
			GetStor(KeyStor, DataStor);
			WindLoad.Initialize();
			WindLoad.KeyStor=KeyStor;
			WindLoad.dPosition_X=DataStor.WindCenterX;
			WindLoad.dPosition_Y=DataStor.WindCenterY;
			if (bDPTWind)
			{
				WindLoad.dWind_X = LateralLoad.m_aWindLoad_Y2[i].dWindLoad;
				WindLoad.dWind_Y = LateralLoad.m_aWindLoad_X2[i].dWindLoad;
			}
			else
			{
				WindLoad.dWind_X = LateralLoad.m_aWindLoad_X2[i].dWindLoad;
				WindLoad.dWind_Y = LateralLoad.m_aWindLoad_Y2[i].dWindLoad;
			}
			WindLoad.dWind_X=LateralLoad.m_aWindLoad_X2[i].dWindLoad;
			WindLoad.dWind_Y=LateralLoad.m_aWindLoad_Y2[i].dWindLoad;
			WindLoad.dWind_RZ=0.;
			if(WindLoad.dWind_X != 0. || WindLoad.dWind_Y != 0. || WindLoad.dWind_RZ != 0.) arWindLoad.Add(WindLoad);
		}
	}
	else if(nDir==2)
	{
		//
		BOOL bCrossWind = FALSE;
		BOOL bTosionWind = FALSE;
		if(rData.nCodeType == CH_W_2012)
		{
			if(!rData.CodeParam.CH2012.bCrossVibration)
			{
				bCrossWind = rData.CodeParam.CH2012.bCross;
				bTosionWind = rData.CodeParam.CH2012.bTorsion;
				rData.CodeParam.CH2012.bTorsion = FALSE;
				rData.CodeParam.CH2012.bCross = FALSE;
			}
		}
		else if(rData.nCodeType == CH_W_2021)
		{
			if(!rData.CodeParam.CH2019.bCrossVibration)
			{
				bCrossWind = rData.CodeParam.CH2019.bCross;
				bTosionWind = rData.CodeParam.CH2019.bTorsion;
				rData.CodeParam.CH2019.bTorsion = FALSE;
				rData.CodeParam.CH2019.bCross = FALSE;
			}
		}
		CLateralLoad LateralLoad;
		LateralLoad.MakeWindLoad(rData);
		if(rData.nCodeType == CH_W_2012)
		{
			if(!rData.CodeParam.CH2012.bCrossVibration)
			{
				rData.CodeParam.CH2012.bTorsion = bCrossWind;
				rData.CodeParam.CH2012.bCross = bTosionWind;
			}
		}
		else if(rData.nCodeType == CH_W_2021)
		{
			if(!rData.CodeParam.CH2019.bCrossVibration)
			{
				rData.CodeParam.CH2019.bTorsion = bCrossWind;
				rData.CodeParam.CH2019.bCross = bTosionWind;
			}
		}

		int nStory=LateralLoad.m_aWindLoad_RZ.GetSize();
		ASSERT(nStory == LateralLoad.m_aWindLoad_RZ2.GetSize());
		for(int i=0; i<nStory; i++)
		{
			T_STOR_K KeyStor=LateralLoad.m_aWindLoad_RZ[i].KeyStory;
			if(KeyStor == 0)continue;
			GetStor(KeyStor, DataStor);
			WindLoad.Initialize();
			WindLoad.KeyStor=KeyStor;
			WindLoad.dPosition_X=DataStor.WindCenterX;
			WindLoad.dPosition_Y=DataStor.WindCenterY;
			WindLoad.dWind_X=0.;
			WindLoad.dWind_Y=0.;
			WindLoad.dWind_RZ=LateralLoad.m_aWindLoad_RZ[i].dWindLoad+LateralLoad.m_aWindLoad_RZ2[i].dWindLoad;
			if(WindLoad.dWind_X != 0. || WindLoad.dWind_Y != 0. || WindLoad.dWind_RZ != 0.) arWindLoad.Add(WindLoad);
		}
	}
	else ASSERT(0);
}

void CAttrCtrl::CalcWindLoadLcom_forLabel(BOOL bAllLoadCase, T_LCOM_D& DataLcom, CArray<T_WINDLOAD, T_WINDLOAD&>& arWindLoad)
{
	arWindLoad.RemoveAll();
	if (GetCountStor() == 0 || GetCountWind() == 0) return;

	CMap<T_STOR_K, T_STOR_K, T_WINDLOAD, T_WINDLOAD&>mapWindLoad;
	mapWindLoad.InitHashTable(HASHSIZESTLD);

	POSITION pos = GetStartWind();
	while (pos != NULL)
	{
		T_WIND_K KeyWind;
		T_WIND_D DataWind;
		GetNextWind(pos, KeyWind, DataWind);

		double dFactor = 1.0;
		BOOL bKBC2016Across = FALSE, bKBC2016Torsion = FALSE;
		BOOL bDPTAcross = FALSE, bDPTTorsion = FALSE;

		if (!bAllLoadCase)
		{
			if (DataWind.nCodeType == DPT_W_2007)
			{
				BOOL bFind = FALSE;
				for (int i = 0; i < DataLcom.aCombination.GetSize(); ++i)
				{
					T_LCOM_BASE& LcomBase = DataLcom.aCombination[i];
					T_KEY keyWA = DataWind.CodeParam.DPT2007.keyWA;
					T_KEY keyWT = DataWind.CodeParam.DPT2007.keyWT;

					if (keyWA == LcomBase.LoadCaseKey)
					{
						bDPTAcross = TRUE;
						break;
					}
					else if (keyWT == LcomBase.LoadCaseKey)
					{
						bDPTTorsion = TRUE;
						break;
					}
					else if (KeyWind == LcomBase.LoadCaseKey)
					{
						bFind = TRUE;
						break;
					}
				}
				if (!bFind && !bDPTAcross && !bDPTTorsion) continue;
			}
			else
			{
				double dStldFactor = 0.0, dStagFactor = 0.0;
				BOOL bKDSKBCCode = (DataWind.nCodeType == KDS_W_2019 ||
					DataWind.nCodeType == KBC_W_2016 ||
					DataWind.nCodeType == KDS_W_2022);

				if (bKDSKBCCode)
				{
					if (!GetLcomStldFactor(KeyWind, DataLcom, dStldFactor, dStagFactor)) return;

					if (dStldFactor == 0.0)
					{
						T_KEY* pkeyWA = NULL;
						T_KEY* pkeyWT = NULL;

						if (DataWind.nCodeType == KDS_W_2019 || DataWind.nCodeType == KBC_W_2016)
						{
							T_WIND_KBC2015* pKBC2015 = (DataWind.nCodeType == KDS_W_2019) ?
								&DataWind.CodeParam.KDS2019 : &DataWind.CodeParam.KBC2015;
							pkeyWA = &pKBC2015->keyWA;
							pkeyWT = &pKBC2015->keyWT;
						}
						else if (DataWind.nCodeType == KDS_W_2022)
						{
							pkeyWA = &DataWind.CodeParam.KDS2021.keyWA;
							pkeyWT = &DataWind.CodeParam.KDS2021.keyWT;
						}

						if (!GetLcomStldFactor(*pkeyWA, DataLcom, dStldFactor, dStagFactor)) return;
						if (dStldFactor == 0.0)
						{
							if (!GetLcomStldFactor(*pkeyWT, DataLcom, dStldFactor, dStagFactor)) return;
							if (dStldFactor == 0.0) continue;
							bKBC2016Torsion = TRUE;
						}
						else
						{
							bKBC2016Across = TRUE;
						}
					}
				}
				else
				{
					if (!GetLcomStldFactor(KeyWind, DataLcom, dStldFactor, dStagFactor)) return;
					if (dStldFactor == 0.0) continue;
				}
				dFactor = dStldFactor;
			}
		}
		struct { BOOL bCrossVibration, bWindT, bWindC; } vibSettings = { FALSE, FALSE, FALSE };

		if (DataWind.nCodeType == CH_W_2012)
		{
			vibSettings.bCrossVibration = DataWind.CodeParam.CH2012.bCrossVibration;
			vibSettings.bWindT = DataWind.CodeParam.CH2012.bTorsion;
			vibSettings.bWindC = DataWind.CodeParam.CH2012.bCross;
			DataWind.CodeParam.CH2012.bCrossVibration = FALSE;
			DataWind.CodeParam.CH2012.bCross = FALSE;
			DataWind.CodeParam.CH2012.bTorsion = FALSE;
		}
		else if (DataWind.nCodeType == CH_W_2021)
		{
			vibSettings.bCrossVibration = DataWind.CodeParam.CH2019.bCrossVibration;
			vibSettings.bWindT = DataWind.CodeParam.CH2019.bTorsion;
			vibSettings.bWindC = DataWind.CodeParam.CH2019.bCross;
			DataWind.CodeParam.CH2019.bCrossVibration = FALSE;
			DataWind.CodeParam.CH2019.bCross = FALSE;
			DataWind.CodeParam.CH2019.bTorsion = FALSE;
		}

		CLateralLoad LateralLoad;
		LateralLoad.MakeWindLoad(DataWind);

		if (DataWind.nCodeType == CH_W_2012)
		{
			DataWind.CodeParam.CH2012.bCrossVibration = vibSettings.bCrossVibration;
			DataWind.CodeParam.CH2012.bCross = vibSettings.bWindC;
			DataWind.CodeParam.CH2012.bTorsion = vibSettings.bWindT;
		}
		else if (DataWind.nCodeType == CH_W_2021)
		{
			DataWind.CodeParam.CH2019.bCrossVibration = vibSettings.bCrossVibration;
			DataWind.CodeParam.CH2019.bCross = vibSettings.bWindC;
			DataWind.CodeParam.CH2019.bTorsion = vibSettings.bWindT;
		}

		int nStory = LateralLoad.m_aWindLoad_X.GetSize();
		ASSERT(nStory == LateralLoad.m_aWindLoad_Y.GetSize());

		for (int i = 0; i < nStory; i++)
		{
			stWindLoad windload_x, windload_y, windload_rz;
			T_STOR_K KeyStor;

			if (bKBC2016Across)
			{
				windload_x = LateralLoad.m_aWindLoad_X2[i];
				windload_y = LateralLoad.m_aWindLoad_Y2[i];
				windload_rz.dWindLoad = 0.0;
				KeyStor = windload_x.KeyStory;
			}
			else if (bDPTAcross)
			{
				windload_x = LateralLoad.m_aWindLoad_Y2[i];
				windload_y = LateralLoad.m_aWindLoad_X2[i];
				windload_rz.dWindLoad = 0.0;
				KeyStor = windload_x.KeyStory;
			}
			else if (bKBC2016Torsion || bDPTTorsion)
			{
				windload_x.dWindLoad = 0.0;
				windload_y.dWindLoad = 0.0;
				windload_x.dTorsion = 0.0;
				windload_y.dTorsion = 0.0;
				windload_rz = LateralLoad.m_aWindLoad_RZ[i];
				windload_rz.dWindLoad = LateralLoad.m_aWindLoad_RZ[i].dWindLoad +
					LateralLoad.m_aWindLoad_RZ2[i].dWindLoad;
				KeyStor = windload_rz.KeyStory;
			}
			else
			{
				windload_x = LateralLoad.m_aWindLoad_X[i];
				windload_y = LateralLoad.m_aWindLoad_Y[i];

				BOOL bZeroRZ = (DataWind.nCodeType == KBC_W_2016 ||
					DataWind.nCodeType == KDS_W_2019 ||
					DataWind.nCodeType == KDS_W_2022 ||
					DataWind.nCodeType == DPT_W_2007);

				windload_rz.dWindLoad = bZeroRZ ? 0.0 : LateralLoad.m_aWindLoad_RZ[i].dWindLoad;
				KeyStor = windload_x.KeyStory;
			}

			if (bKBC2016Across || bDPTAcross)
			{
				ASSERT(KeyStor == windload_y.KeyStory);
			}
			else if (!bKBC2016Torsion && !bDPTTorsion)
			{
				ASSERT(KeyStor == windload_y.KeyStory);
			}
			if (KeyStor == 0) continue;

			T_STOR_D DataStor;
			GetStor(KeyStor, DataStor);

			T_WINDLOAD WindLoad;
			WindLoad.Initialize();
			WindLoad.KeyStor = KeyStor;
			WindLoad.dPosition_X = DataStor.WindCenterX;
			WindLoad.dPosition_Y = DataStor.WindCenterY;
			WindLoad.dWind_X = windload_x.dWindLoad * dFactor;
			WindLoad.dWind_Y = windload_y.dWindLoad * dFactor;
			WindLoad.dWind_RZ = (windload_rz.dWindLoad + windload_x.dTorsion + windload_y.dTorsion) * dFactor;

			if (WindLoad.dWind_X != 0.0 || WindLoad.dWind_Y != 0.0 || WindLoad.dWind_RZ != 0.0)
			{
				T_WINDLOAD WindLoadOld;
				if (mapWindLoad.Lookup(KeyStor, WindLoadOld))
				{
					WindLoad.dWind_X += WindLoadOld.dWind_X;
					WindLoad.dWind_Y += WindLoadOld.dWind_Y;
					WindLoad.dWind_RZ += WindLoadOld.dWind_RZ;
				}
				mapWindLoad.SetAt(KeyStor, WindLoad);
			}
		}
	}

	CArray<T_STOR_K, T_STOR_K> StorKeyList;
	GetStorKeyList(StorKeyList);
	for (int i = 0; i < StorKeyList.GetSize(); i++)
	{
		T_WINDLOAD WindLoad;
		if (mapWindLoad.Lookup(StorKeyList[i], WindLoad))
		{
			arWindLoad.Add(WindLoad);
		}
	}
}

