void CAttrCtrl::GetWvldList(CArray<CString, CString&>& rstrNameList)
{
	rstrNameList.RemoveAll();

	T_WVLD_D Data;
	CArray<T_WVLD_K, T_WVLD_K>KeyList;
	GetWvldKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetWvld(KeyList[i], Data))
			rstrNameList.Add(Data.strName);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetWvldKeyList(CArray<T_WVLD_K, T_WVLD_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<CString, CString&>arName;

	POSITION pos;
	T_WVLD_K Key;
	T_WVLD_D Data;
	pos=GetStartWvld();
	while(pos != NULL)
	{
		GetNextWvld(pos, Key, Data);
		rKeyList.Add(Key);
		arName.Add(Data.strName);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortStringWithIndex(rKeyList.GetData(), arName.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::ExistWvld(CString& rName)
{
	T_WVLD_D data;
	return GetWvld(rName, data);
}

BOOL CAttrCtrl::ExistWvld(T_WVLD_K Key)
{
	T_WVLD_D Data;
	return m_pDataMemb->m_wvld.Get(Key,Data);
}

BOOL CAttrCtrl::GetWvld(CString& rName, T_WVLD_D& rData)
{
	T_WVLD_K key;
	T_WVLD_D data;
	CString strName=rName;
	strName.TrimRight();

	POSITION pos=m_pDataMemb->m_wvld.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_wvld.GetNext(pos,key,data);
		if(strName.CompareNoCase(data.strName) == 0)
		{
			m_pUnitCtrl->ConvertUnitWvldOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetWvld(T_WVLD_K Key,T_WVLD_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_wvld.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitWvldOut(rData);
	return bReturn;
}

T_WVLD_K CAttrCtrl::GetWvldKey(CString& rName)
{
	T_WVLD_K key;
	T_WVLD_D data;

	POSITION pos=GetStartWvld();
	while(pos != NULL)
	{
		GetNextWvld(pos,key,data);
		if(rName.CompareNoCase(data.strName) == 0)return key;
	}
	key=0;
	return key;
}

int CAttrCtrl::GetCountWvld()
{
	return m_pDataMemb->m_wvld.GetCount();
}

POSITION CAttrCtrl::GetStartWvld()
{
	return m_pDataMemb->m_wvld.GetStart();
}

void CAttrCtrl::GetNextWvld(POSITION& rNextPosition,T_WVLD_K& rKey,T_WVLD_D& rData)
{
	m_pDataMemb->m_wvld.GetNext(rNextPosition,rKey,rData);
	m_pUnitCtrl->ConvertUnitWvldOut(rData);
}

T_WVLD_K CAttrCtrl::GetLastNumWvld()
{
	return m_pDataMemb->m_wvld.m_nLastNum;
}

T_WVLD_K CAttrCtrl::GetStartNumWvld()
{
	return m_pDataMemb->m_wvld.m_nStartNum;
}

T_WVLD_K CAttrCtrl::GetNextNumWvld(T_WVLD_K StartNum)
{
	if(StartNum > GetLastNumWvld())return StartNum;
	T_WVLD_K Key=StartNum;
	T_WVLD_D Data;
	while(TRUE)
	{
		Key++;
		if(!m_pDataMemb->m_wvld.Get(Key,Data))return Key;
	}
}

void CAttrCtrl::GetDefaultWvld(T_WVLD_D &WvldD)
{
	WvldD.Initialize();

	WvldD.aCoef_s.SetSize(1), WvldD.aCoef_r.SetSize(1);
	WvldD.aOver_s.SetSize(1), WvldD.aOver_r.SetSize(1);

	if(CProduct::GetMovingType() == D_PRODUCT_MOVING_US)
	{
		WvldD.dWaterDensity = M_InitValueCurUnit(94., LBF, FT, D_UNITSYS_BASE_DENSITY);
		WvldD.aCoef_s[0].dDiameter = WvldD.aCoef_r[0].dDiameter = M_InitValueCurUnit(0.013, TON, M, D_UNITSYS_BASE_LENGTH);
	}
	else
	{
		WvldD.dWaterDensity  = M_InitValueCurUnit(1.03, TON, M, D_UNITSYS_BASE_DENSITY);
		WvldD.aCoef_s[0].dDiameter = WvldD.aCoef_r[0].dDiameter = M_InitValueCurUnit(0.013, TON, M, D_UNITSYS_BASE_LENGTH);
	}
	WvldD.aCoef_s[0].dDragCoefY = WvldD.aCoef_r[0].dDragCoefY = 0.65;
	WvldD.aCoef_s[0].dDragCoefZ = WvldD.aCoef_r[0].dDragCoefZ = 0.65;
	WvldD.aCoef_s[0].dInerCoefY = WvldD.aCoef_r[0].dInerCoefY = 1.65;
	WvldD.aCoef_s[0].dInerCoefZ = WvldD.aCoef_r[0].dInerCoefZ = 1.65;

	WvldD.aOver_s[0].GrupK      = WvldD.aOver_r[0].GrupK      = 0;
	WvldD.aOver_s[0].dDragCoefY = WvldD.aOver_r[0].dDragCoefY = 0.65;
	WvldD.aOver_s[0].dDragCoefZ = WvldD.aOver_r[0].dDragCoefZ = 0.65;
	WvldD.aOver_s[0].dInerCoefY = WvldD.aOver_r[0].dInerCoefY = 1.65;
	WvldD.aOver_s[0].dInerCoefZ = WvldD.aOver_r[0].dInerCoefZ = 1.65;
}

