void CAttrCtrl::CalcSeisLoad(T_SEIS_D& rData, CArray<T_SEISLOAD, T_SEISLOAD&>& arSeisLoad, BOOL bCalcMassCenter)
{
	arSeisLoad.RemoveAll();
	if(GetCountStor() == 0)return;

	T_SEISLOAD SeisLoad;
	T_STOR_D DataStor;
	CLateralLoad LateralLoad;
	CArray<T_STOR_K, T_STOR_K>StorKeyList;
	if(bCalcMassCenter)
	{
		GetStorKeyList(StorKeyList);
		BOOL bUseBedrockLevel=TRUE;
		LateralLoad.Calc_DiaphramCenter(bUseBedrockLevel);
	}
	LateralLoad.MakeSeismicLoad(rData);
	int nStory=LateralLoad.m_aSeisLoad_X.GetSize();
	ASSERT(nStory == LateralLoad.m_aSeisLoad_Y.GetSize());
	for(int i=0; i<nStory; i++)
	{
		T_STOR_K KeyStor=LateralLoad.m_aSeisLoad_X[i].KeyStory;
		ASSERT(KeyStor == LateralLoad.m_aSeisLoad_Y[i].KeyStory);
		if(KeyStor == 0)continue;
		GetStor(KeyStor, DataStor);
		SeisLoad.Initialize();
		SeisLoad.KeyStor=KeyStor;
		SeisLoad.dPosition_X=0.;
		SeisLoad.dPosition_Y=0.;
		if(bCalcMassCenter)
		{
			BOOL bGetCenter=FALSE;
			for(int j=0; j<StorKeyList.GetSize(); j++)
			{
				if(KeyStor == StorKeyList[j])
				{
					SeisLoad.dPosition_X=LateralLoad.m_aDiaphramCenter[j].DiaphCnt_x;
					SeisLoad.dPosition_Y=LateralLoad.m_aDiaphramCenter[j].DiaphCnt_y;
					bGetCenter=TRUE;
					break;
				}
			}
			if(!bGetCenter)ASSERT(FALSE);
		}
		SeisLoad.dSeis_X=LateralLoad.m_aSeisLoad_X[i].dSeisLoad;
		SeisLoad.dSeis_Y=LateralLoad.m_aSeisLoad_Y[i].dSeisLoad;
		SeisLoad.dSeis_RZ=LateralLoad.m_aSeisLoad_X[i].dAllTorsion+LateralLoad.m_aSeisLoad_Y[i].dAllTorsion;
		int nAddSize = rData.arAddition.GetSize();
		for(int k = 0; k < nAddSize; k++)                           // PMS:4183-HTLEE-20100525 Additional Load RZ 고려 
		{
			if(KeyStor == rData.arAddition[k].KeyStor)
			{
				SeisLoad.dSeis_RZ += rData.arAddition[k].AddR;
				break;
			}
		}
		if(SeisLoad.dSeis_X != 0. || SeisLoad.dSeis_Y != 0. || SeisLoad.dSeis_RZ != 0.) arSeisLoad.Add(SeisLoad);    
	}
}

void CAttrCtrl::CalcSeisLoadLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, CArray<T_SEISLOAD, T_SEISLOAD&>& arSeisLoad)
{
	arSeisLoad.RemoveAll();  
	if(GetCountStor() == 0)return;
	if(GetCountSeis() == 0)return;

	T_SEISLOAD SeisLoad;
	T_STOR_K KeyStor;
	T_STOR_D DataStor;
	CLateralLoad LateralLoad;

	CArray<T_NMAS_UDRD_D, T_NMAS_UDRD_D&> arNmasData_allMass;
	m_pDoc->calcAllMass(arNmasData_allMass);
	LateralLoad.Calc_DiaphramCenter(arNmasData_allMass);

	POSITION pos;
	T_SEIS_K KeySeis;
	T_SEIS_D DataSeis;
	CMap<T_STOR_K, T_STOR_K, T_SEISLOAD, T_SEISLOAD&>mapSeisLoad;
	mapSeisLoad.InitHashTable(HASHSIZESTLD);

	CArray<T_STOR_K, T_STOR_K>StorKeyList;
	GetStorKeyList(StorKeyList);
	pos=GetStartSeis();
	while(pos != NULL)
	{
		GetNextSeis(pos, KeySeis, DataSeis);
		double dFactor=1.;
		if(bAllLoadCase)
		{
		}
		else
		{
			double dStldFactor=0., dStagFactor=0.;
			if(!GetLcomStldFactor(KeySeis, DataLcom, dStldFactor, dStagFactor))return;  
			if(dStldFactor == 0.)continue;
			dFactor=dStldFactor;
		}

		LateralLoad.MakeSeismicLoad(DataSeis, FALSE, _T(""), FALSE, FALSE, arNmasData_allMass);

		int nStory=LateralLoad.m_aSeisLoad_X.GetSize();
		ASSERT(nStory == LateralLoad.m_aSeisLoad_Y.GetSize());
		for(int i=0; i<nStory; i++)
		{
			KeyStor=LateralLoad.m_aSeisLoad_X[i].KeyStory;
			ASSERT(KeyStor == LateralLoad.m_aSeisLoad_Y[i].KeyStory);
			if(KeyStor == 0)continue;
			GetStor(KeyStor, DataStor);
			SeisLoad.Initialize();
			SeisLoad.KeyStor=KeyStor;
			SeisLoad.dPosition_X=0.;
			SeisLoad.dPosition_Y=0.;
			BOOL bGetCenter=FALSE;
			for(int j=0; j<StorKeyList.GetSize(); j++)
			{
				if(KeyStor == StorKeyList[j])
				{
					SeisLoad.dPosition_X=LateralLoad.m_aDiaphramCenter[j].DiaphCnt_x;
					SeisLoad.dPosition_Y=LateralLoad.m_aDiaphramCenter[j].DiaphCnt_y;
					bGetCenter=TRUE;
					break;
				}
			}
			if(!bGetCenter)ASSERT(FALSE);
			SeisLoad.dSeis_X=LateralLoad.m_aSeisLoad_X[i].dSeisLoad*dFactor;
			SeisLoad.dSeis_Y=LateralLoad.m_aSeisLoad_Y[i].dSeisLoad*dFactor;
			SeisLoad.dSeis_RZ=(LateralLoad.m_aSeisLoad_X[i].dAllTorsion+LateralLoad.m_aSeisLoad_Y[i].dAllTorsion)*dFactor;
			int nAddSize = DataSeis.arAddition.GetSize();
			for(int k = 0; k < nAddSize; k++)                           // PMS:4183-HTLEE-20100525 Additional Load RZ 고려 
			{
				if(KeyStor == DataSeis.arAddition[k].KeyStor)
				{
					SeisLoad.dSeis_RZ += DataSeis.arAddition[k].AddR;
					break;
				}
			}

			if(SeisLoad.dSeis_X != 0. || SeisLoad.dSeis_Y != 0. || SeisLoad.dSeis_RZ != 0.)
			{
				T_SEISLOAD SeisLoadOld;
				if(mapSeisLoad.Lookup(KeyStor,SeisLoadOld))
				{
					SeisLoad.dSeis_X+=SeisLoadOld.dSeis_X;
					SeisLoad.dSeis_Y+=SeisLoadOld.dSeis_Y;
					SeisLoad.dSeis_RZ+=SeisLoadOld.dSeis_RZ;
				}
				mapSeisLoad.SetAt(KeyStor,SeisLoad);
			}
		}
	}
	for(int i=0; i<StorKeyList.GetSize(); i++)
	{
		if(mapSeisLoad.Lookup(StorKeyList[i],SeisLoad)) arSeisLoad.Add(SeisLoad);
	}
}
//[SeisCode] 추가시 수정
double CAttrCtrl::CalcFundamentalPeriod(int nCodeType, int nMethod, double dPeriodAnal, double dPeriodAppr)
{
	double dPeriodFinal = 0.;    

	CString strMsg;
	BOOL bSuccess = TRUE;

	switch(nCodeType)
	{
	case 12: // Taiwan86
		{
			if(nMethod == 0)  // Analytical : 해석에 의한 주기를 이용할 경우에는, 이 값을 기준으로 하고 근사주기의 1.4배를 넘지 않도로 한다. 
				dPeriodFinal = min(dPeriodAnal, dPeriodAppr * 1.4);
			else if(nMethod == 1)  // Approximate 
				dPeriodFinal = dPeriodAppr;  // 근사주기에 의할 경우에는 이 값을 사용한다.
		} break;
	case 13: // KBC2005
		{
			if(nMethod == 0)  // Analytical : 해석에 의한 주기를 이용할 경우에는, 이 값을 기준으로 하고 근사주기의 1.2배를 넘지 않도로 한다. 
				dPeriodFinal = min(dPeriodAnal, dPeriodAppr * 1.2);
			else if(nMethod == 1)  // Approximate 
				dPeriodFinal = dPeriodAppr;  // 근사주기에 의할 경우에는 이 값을 사용한다.
		} break; 
	}

	return dPeriodFinal;
}

double CAttrCtrl::CalcFundamentalPeriod2(int nCodeType, double dSD1, int nMethod, double dPeriodAnal, double dPeriodAppr)
{
	double dPeriodFinal = 0.;    

	CString strMsg;
	BOOL bSuccess = TRUE;

	switch(nCodeType)
	{
	case TAIWAN_E_2006:
		{      
			double dCu;           //주기제한 계수 Cu
			if     (dSD1>=0.4) dCu = 1.2;
			else if(dSD1<=0.3) dCu = 1.3;
			else               dCu = -dSD1 + 1.6;

			if(nMethod == 0)  
				dPeriodFinal = min(dPeriodAnal, dPeriodAppr * dCu);
			else if(nMethod == 1)  
				dPeriodFinal = dPeriodAppr; 
		} break;
	case TAIWAN_E_2011:
	case TAIWAN_E_2022:
		{      
			double dCu = 1.4;    // PARKHJ-20111009 : 주기에 상관 없이 고정값!

			if(nMethod == 0)  
				dPeriodFinal = min(dPeriodAnal, dPeriodAppr * dCu);
			else if(nMethod == 1)  
				dPeriodFinal = dPeriodAppr; 
		} break;
	}

	return dPeriodFinal;
}

double CAttrCtrl::CalcFundamentalPeriodKBC2009(int nCodeType, int nMethod, double dPeriodAnal, double dPeriodAppr, double dCu)
{
	double dPeriodFinal = 0.;

	switch(nCodeType)
	{
	case KBC_E_2009: // KBC2009
	case KBC_E_2016: // KBC2015
	case KDS_E_2019:
		{
			if(nMethod == 0)  // Analytical : 해석에 의한 주기를 이용할 경우에는, 이 값을 기준으로 하고 근사주기의 1.2배를 넘지 않도로 한다. 
				dPeriodFinal = min(dPeriodAnal, dPeriodAppr * dCu);
			else if(nMethod == 1)  // Approximate 
				dPeriodFinal = dPeriodAppr;  // 근사주기에 의할 경우에는 이 값을 사용한다.
		} break; 
	}

	return dPeriodFinal;
}

BOOL CAttrCtrl::CalcKBC2005SdsSd1(int nSeismicZone, int nSiteClass, double& dSds, double& dSd1)
{
	if(nSeismicZone < 0 || nSeismicZone > 1) return FALSE;
	if(nSiteClass < 0 || nSiteClass > 4) return FALSE;

	static double T_Sds[5][2] = {{2.0, 1.8}, {2.5, 2.5}, {3.0, 3.0}, {3.6, 4.0}, {5.0, 6.0}};
	static double T_Sd1[5][2] = {{0.8, 0.7}, {1.0, 1.0}, {1.6, 1.6}, {2.3, 2.3}, {3.4, 3.4}};
	static double T_A[2] = {0.11, 0.07};
	double dM = 1.33;

	dSds = T_Sds[nSiteClass][nSeismicZone] * dM * T_A[nSeismicZone];
	dSd1 = T_Sd1[nSiteClass][nSeismicZone] * dM * T_A[nSeismicZone];

	CString str;
	str.Format(_T("%-10.5g"), dSds);
	dSds = _ttof(str);

	str.Format(_T("%-10.5g"), dSd1);
	dSd1 = _ttof(str);

	return TRUE;
}

BOOL CAttrCtrl::CalcKBC2015Fa(double dZoneFactor, int nSiteClass, double dDepth2MR, double& dFa)
{
	if(nSiteClass < 0 || nSiteClass > 4) return FALSE;

	// Fa : Acceleration-based site coefficient	
	double dSs = dZoneFactor * 2.5;

	// nSiteClass -> 0:Sa, 1:Sb, 2:Sc, 3:Sd, 4:Se
	if      (nSiteClass == 0) dFa = 0.8; 
	else if (nSiteClass == 1) dFa = 1.0;
	else
	{
		const int STD_NUM = 3;
		CArray<double, double> aStdCond;
		CArray<double, double> aStdCoeff;
		aStdCond.SetSize(STD_NUM);
		aStdCoeff.SetSize(STD_NUM);

		aStdCond[0] = 0.25;
		aStdCond[1] = 0.5;
		aStdCond[2] = 0.75;

		if(nSiteClass==2)
		{
			double dValue = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(0, D_UNITSYS_LENGTH_INDEX_M,D_UNITSYS_BASE_LENGTH, 20.0); // 20m
			if(dDepth2MR<dValue)
			{
				aStdCoeff[0] = 1.4; aStdCoeff[1] = 1.4; aStdCoeff[2] = 1.3;
			}
			else
			{
				aStdCoeff[0] = 1.2; aStdCoeff[1] = 1.2; aStdCoeff[2] = 1.1;
			}
		}
		else if(nSiteClass == 3)
		{
			double dValue = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(0, D_UNITSYS_LENGTH_INDEX_M,D_UNITSYS_BASE_LENGTH, 20.0); // 20m
			if(dDepth2MR<dValue)
			{
				aStdCoeff[0] = 1.7; aStdCoeff[1] = 1.5; aStdCoeff[2] = 1.3;
			}
			else
			{
				aStdCoeff[0] = 1.6; aStdCoeff[1] = 1.4; aStdCoeff[2] = 1.2;
			}
		}
		else
		{
			aStdCoeff[0] = 2.5; aStdCoeff[1] = 1.9; aStdCoeff[2] = 1.3;
		}

		if (CCompFunc::CompReal(dSs, aStdCond[0]) < 1) dFa = aStdCoeff[0];
		else if(!m_pDoc->m_pAttrCtrl2->GetLineInterPValue(aStdCond, aStdCoeff, dSs, dFa)) ASSERT(0);
	}
	return TRUE;
}

BOOL CAttrCtrl::CalcKBC2009Fa(double dZoneFactor, int nSeismicZone, int nSiteClass, double& dFa)
{
	if(nSeismicZone < 0 || nSeismicZone > 1)      {  ASSERT(0);		return FALSE;	}
	if(nSiteClass < 0 || nSiteClass > 4) return FALSE;

	// Fa : Acceleration-based site coefficient
	//double dZoneFactor = (nSeismicZone == 0)?   0.22:   0.14;   // PMS:4428-HSSHIM-20120104. ZoneFactor에 의한 보간방법을 사용하도록 변경
	double dSs = dZoneFactor * 2.5;

	// nSiteClass -> 0:Sa, 1:Sb, 2:Sc, 3:Sd, 4:Se
	if      (nSiteClass == 0) dFa = 0.8; 
	else if (nSiteClass == 1) dFa = 1.0;
	else if (nSiteClass == 2)
	{
		if      (dSs <= 0.5)  dFa = 1.2;
		else if (dSs >= 0.75) dFa = 1.1;
		else                  dFa = (-0.4 * dSs) + 1.4;
	}
	else if (nSiteClass == 3)
	{
		if      (dSs <= 0.25) dFa = 1.6;
		else if (dSs >= 0.75) dFa = 1.2;
		else                  dFa = (-0.8 * dSs) + 1.8;
	}
	else 
	{
		if      (dSs <= 0.25) dFa = 2.5;
		else if (dSs >= 0.75) dFa = 1.3;
		else                  dFa = (-2.4 * dSs) + 3.1;
	}
	return TRUE;
}

BOOL CAttrCtrl::CalcKBC2015Fv(double dZoneFactor, int nSiteClass, double dDepth2MR, double& dFv)
{
	if(nSiteClass < 0 || nSiteClass > 4) return FALSE;

	// Fv : Velocity-based site coefficient
	// nSiteClass -> 0:Sa, 1:Sb, 2:Sc, 3:Sd, 4:Se
	if      (nSiteClass == 0) dFv = 0.8;
	else if (nSiteClass == 1) dFv = 1.0;
	else
	{
		const int STD_NUM = 3;
		CArray<double, double> aStdCond;
		CArray<double, double> aStdCoeff;
		aStdCond.SetSize(STD_NUM);
		aStdCoeff.SetSize(STD_NUM);

		aStdCond[0] = 0.1;
		aStdCond[1] = 0.2;
		aStdCond[2] = 0.3;

		if(nSiteClass==2)
		{
			double dValue = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(0, D_UNITSYS_LENGTH_INDEX_M,D_UNITSYS_BASE_LENGTH, 20.0); // 20m
			if(dDepth2MR<dValue)
			{
				aStdCoeff[0] = 1.5; aStdCoeff[1] = 1.4; aStdCoeff[2] = 1.3;
			}
			else
			{
				aStdCoeff[0] = 1.7; aStdCoeff[1] = 1.6; aStdCoeff[2] = 1.5;
			}
		}
		else if(nSiteClass == 3)
		{
			double dValue = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(0, D_UNITSYS_LENGTH_INDEX_M,D_UNITSYS_BASE_LENGTH, 20.0); // 20m
			if(dDepth2MR<dValue)
			{
				aStdCoeff[0] = 1.7; aStdCoeff[1] = 1.6; aStdCoeff[2] = 1.5;
			}
			else
			{
				aStdCoeff[0] = 2.4; aStdCoeff[1] = 2.0; aStdCoeff[2] = 1.8;
			}
		}
		else
		{
			aStdCoeff[0] = 3.5; aStdCoeff[1] = 3.2; aStdCoeff[2] = 2.8;
		}

		if (CCompFunc::CompReal(dZoneFactor, aStdCond[0]) < 1) dFv = aStdCoeff[0];
		else if(!m_pDoc->m_pAttrCtrl2->GetLineInterPValue(aStdCond, aStdCoeff, dZoneFactor, dFv)) ASSERT(0);
	}
	return TRUE;
}

BOOL CAttrCtrl::CalcKBC2009Fv(double dZoneFactor, int nSeismicZone, int nSiteClass, double& dFv)
{
	if(nSeismicZone < 0 || nSeismicZone > 1)      {  ASSERT(0);		return FALSE;	}
	if(nSiteClass < 0 || nSiteClass > 4) return FALSE;

	// Fv : Velocity-based site coefficient
	// nSiteClass -> 0:Sa, 1:Sb, 2:Sc, 3:Sd, 4:Se
	//double dZoneFactor = (nSeismicZone == 0)?   0.22:   0.14;   // PMS:4428-HSSHIM-20120104. ZoneFactor에 의한 보간방법을 사용하도록 변경
	if      (nSiteClass == 0) dFv = 0.8;
	else if (nSiteClass == 1) dFv = 1.0;
	else if (nSiteClass == 2)
	{
		if      (dZoneFactor <= 0.1) dFv = 1.7;
		else if (dZoneFactor >= 0.3) dFv = 1.5;
		else                         dFv = (-1.0 * dZoneFactor) + 1.8;
	}
	else if (nSiteClass == 3)
	{
		if      (dZoneFactor <= 0.1) dFv = 2.4;
		else if (dZoneFactor >= 0.3) dFv = 1.8;
		else if (dZoneFactor == 0.2) dFv = 2.0;
		else if (dZoneFactor > 0.1 && dZoneFactor < 0.2) dFv = (-4.0 * dZoneFactor) + 2.8;
		else dFv = (-2.0 * dZoneFactor) + 2.4;
	}
	else
	{
		if      (dZoneFactor <= 0.1) dFv = 3.5;
		else if (dZoneFactor >= 0.3) dFv = 2.8;
		else if (dZoneFactor == 0.2) dFv = 3.2;
		else if (dZoneFactor > 0.1 && dZoneFactor < 0.2) dFv = (-3.0 * dZoneFactor) + 3.8;
		else dFv = (-4.0 * dZoneFactor) + 4.0;
	}
	return TRUE;
}

BOOL CAttrCtrl::CalcKSCE2019Fa(double dZoneFactor, int nSiteClass, double& dFa)
{
	// nSiteClass -> 0:S1, 1:S2, 2:S3, 3:S4, 4:S5, 5:S6
	if(nSiteClass < 0 || nSiteClass > 5) return FALSE;

	double dSs = dZoneFactor; // = Z * I

	if (nSiteClass == 0) dFa = 1.3; 
	else
	{
		const int STD_NUM = 3;
		CArray<double, double> aStdCond;
		CArray<double, double> aStdCoeff;
		aStdCond.SetSize(STD_NUM);
		aStdCoeff.SetSize(STD_NUM);

		aStdCond[0] = 0.1;
		aStdCond[1] = 0.2;
		aStdCond[2] = 0.3;

		if     (nSiteClass==1) { aStdCoeff[0] = 1.4; aStdCoeff[1] = 1.4; aStdCoeff[2] = 1.3;  }  // S2
		else if(nSiteClass==2) { aStdCoeff[0] = 1.7; aStdCoeff[1] = 1.5; aStdCoeff[2] = 1.3;  }  // S3
		else if(nSiteClass==3) { aStdCoeff[0] = 1.6; aStdCoeff[1] = 1.4; aStdCoeff[2] = 1.2;  }  // S4
		else if(nSiteClass==4) { aStdCoeff[0] = 1.8; aStdCoeff[1] = 1.3; aStdCoeff[2] = 1.3;  }  // S5
		else if(nSiteClass==5) { aStdCoeff[0] = 1.8; aStdCoeff[1] = 1.3; aStdCoeff[2] = 1.3;  }  // S6 일때 우선 S5로 검토
		else ASSERT(0);


		if (CCompFunc::CompReal(dSs, aStdCond[0]) < 1) dFa = aStdCoeff[0];
		else if(!m_pDoc->m_pAttrCtrl2->GetLineInterPValue(aStdCond, aStdCoeff, dSs, dFa)) ASSERT(0);
	}
	return TRUE;
}

BOOL CAttrCtrl::CalcKSCE2019Fv(double dZoneFactor, int nSiteClass, double& dFv)
{
	// nSiteClass -> 0:S1, 1:S2, 2:S3, 3:S4, 4:S5, 5:S6
	if(nSiteClass < 0 || nSiteClass > 6) return FALSE; 

	double dSs = dZoneFactor; // = Z * I

	if     (nSiteClass == 0) dFv = 1.3; 
	else
	{
		const int STD_NUM = 3;
		CArray<double, double> aStdCond;
		CArray<double, double> aStdCoeff;
		aStdCond.SetSize(STD_NUM);
		aStdCoeff.SetSize(STD_NUM);

		aStdCond[0] = 0.1;
		aStdCond[1] = 0.2;
		aStdCond[2] = 0.3;

		if     (nSiteClass==1) { aStdCoeff[0] = 1.5; aStdCoeff[1] = 1.4; aStdCoeff[2] = 1.3;  }  // S2
		else if(nSiteClass==2) { aStdCoeff[0] = 1.7; aStdCoeff[1] = 1.6; aStdCoeff[2] = 1.5;  }  // S3
		else if(nSiteClass==3) { aStdCoeff[0] = 2.2; aStdCoeff[1] = 2.0; aStdCoeff[2] = 1.8;  }  // S4
		else if(nSiteClass==4) { aStdCoeff[0] = 3.0; aStdCoeff[1] = 2.7; aStdCoeff[2] = 2.4;  }  // S5 
		else if(nSiteClass==5) { aStdCoeff[0] = 3.0; aStdCoeff[1] = 2.7; aStdCoeff[2] = 2.4;  }  // S6 일때 우선 S5로 검토
		else ASSERT(0);

		if (CCompFunc::CompReal(dSs, aStdCond[0]) < 1) dFv = aStdCoeff[0];
		else if(!m_pDoc->m_pAttrCtrl2->GetLineInterPValue(aStdCond, aStdCoeff, dSs, dFv)) ASSERT(0);
	}
	return TRUE;
}

BOOL CAttrCtrl::CalcKDS2017Fa(double dZoneFactor, int nSiteClass, double& dFa)
{
	// nSiteClass -> 0:S1, 1:S2, 2:S3, 3:S4, 4:S5, 5:S6
	if (nSiteClass < 0 || nSiteClass > 4) return FALSE;

	double dSs = dZoneFactor; // = Z * I

	if (nSiteClass == 0) dFa = 1.0;
	else
	{
		const int STD_NUM = 3;
		CArray<double, double> aStdCond;
		CArray<double, double> aStdCoeff;
		aStdCond.SetSize(STD_NUM);
		aStdCoeff.SetSize(STD_NUM);

		aStdCond[0] = 0.1;
		aStdCond[1] = 0.2;
		aStdCond[2] = 0.3;

		if      (nSiteClass == 1) { aStdCoeff[0] = 1.4; aStdCoeff[1] = 1.4; aStdCoeff[2] = 1.3; }  // S2
		else if (nSiteClass == 2) { aStdCoeff[0] = 1.7; aStdCoeff[1] = 1.5; aStdCoeff[2] = 1.3; }  // S3
		else if (nSiteClass == 3) { aStdCoeff[0] = 1.6; aStdCoeff[1] = 1.4; aStdCoeff[2] = 1.2; }  // S4
		else if (nSiteClass == 4) { aStdCoeff[0] = 1.8; aStdCoeff[1] = 1.3; aStdCoeff[2] = 1.3; }  // S5
		//else if (nSiteClass == 5) { aStdCoeff[0] = 1.8; aStdCoeff[1] = 1.3; aStdCoeff[2] = 1.3; }  // S6 일때 우선 S5로 검토
		else ASSERT(0);

		if (CCompFunc::CompReal(dSs, aStdCond[0]) < 1) dFa = aStdCoeff[0];
		else if (!m_pDoc->m_pAttrCtrl2->GetLineInterPValue(aStdCond, aStdCoeff, dSs, dFa)) ASSERT(0);
	}
	return TRUE;
}
BOOL CAttrCtrl::CalcKDS2017Fv(double dZoneFactor, int nSiteClass, double& dFv)
{
	// nSiteClass -> 0:S1, 1:S2, 2:S3, 3:S4, 4:S5, 5:S6
	if (nSiteClass < 0 || nSiteClass > 4) return FALSE;

	double dSs = dZoneFactor; // = Z * I

	if (nSiteClass == 0) dFv = 1.0;
	else
	{
		const int STD_NUM = 3;
		CArray<double, double> aStdCond;
		CArray<double, double> aStdCoeff;
		aStdCond.SetSize(STD_NUM);
		aStdCoeff.SetSize(STD_NUM);

		aStdCond[0] = 0.1;
		aStdCond[1] = 0.2;
		aStdCond[2] = 0.3;

		if      (nSiteClass == 1) { aStdCoeff[0] = 1.5; aStdCoeff[1] = 1.4; aStdCoeff[2] = 1.3; }  // S2
		else if (nSiteClass == 2) { aStdCoeff[0] = 1.7; aStdCoeff[1] = 1.6; aStdCoeff[2] = 1.5; }  // S3
		else if (nSiteClass == 3) { aStdCoeff[0] = 2.2; aStdCoeff[1] = 2.0; aStdCoeff[2] = 1.8; }  // S4
		else if (nSiteClass == 4) { aStdCoeff[0] = 3.0; aStdCoeff[1] = 2.7; aStdCoeff[2] = 2.4; }  // S5 
		//else if (nSiteClass == 5) { aStdCoeff[0] = 3.0; aStdCoeff[1] = 2.7; aStdCoeff[2] = 2.4; }  // S6 일때 우선 S5로 검토
		else ASSERT(0);

		if (CCompFunc::CompReal(dSs, aStdCond[0]) < 1) dFv = aStdCoeff[0];
		else if (!m_pDoc->m_pAttrCtrl2->GetLineInterPValue(aStdCond, aStdCoeff, dSs, dFv)) ASSERT(0);
	}
	return TRUE;
}

BOOL CAttrCtrl::CalcKDS2019Fa(double dZoneFactor, int nSiteClass, double& dFa)
{
	// nSiteClass -> 0:S1, 1:S2, 2:S3, 3:S4, 4:S5, 5:S6
	// S6은 사용자 입력 값 사용.
	if(nSiteClass < 0 || nSiteClass > 4) return FALSE;

	double dSs = dZoneFactor;

	const int STD_NUM = 3;
	CArray<double, double> aStdCond;
	CArray<double, double> aStdCoeff;
	aStdCond.SetSize(STD_NUM);
	aStdCoeff.SetSize(STD_NUM);

	aStdCond[0] = 0.1;
	aStdCond[1] = 0.2;
	aStdCond[2] = 0.3;

	if     (nSiteClass==0) { aStdCoeff[0] = 1.12;	aStdCoeff[1] = 1.12;	aStdCoeff[2] = 1.12; }  // S1
	else if(nSiteClass==1) { aStdCoeff[0] = 1.4;	aStdCoeff[1] = 1.4;		aStdCoeff[2] = 1.3;  }  // S2
	else if(nSiteClass==2) { aStdCoeff[0] = 1.7;	aStdCoeff[1] = 1.5;		aStdCoeff[2] = 1.3;  }  // S3
	else if(nSiteClass==3) { aStdCoeff[0] = 1.6;	aStdCoeff[1] = 1.4;		aStdCoeff[2] = 1.2;  }  // S4
	else if(nSiteClass==4) { aStdCoeff[0] = 1.8;	aStdCoeff[1] = 1.3;		aStdCoeff[2] = 1.3;  }  // S5
	else ASSERT(0);

	if (CCompFunc::CompReal(dSs, aStdCond[0]) < 1) dFa = aStdCoeff[0];
	else if(!m_pDoc->m_pAttrCtrl2->GetLineInterPValue(aStdCond, aStdCoeff, dSs, dFa)) ASSERT(0);

	return TRUE;
}

BOOL CAttrCtrl::CalcKDS2019Fv(double dZoneFactor, int nSiteClass, double& dFv)
{
	// nSiteClass -> 0:S1, 1:S2, 2:S3, 3:S4, 4:S5, 5:S6
	// S6은 사용자 입력 값 사용.
	if(nSiteClass < 0 || nSiteClass > 4) return FALSE; 

	double dSs = dZoneFactor;

	const int STD_NUM = 3;
	CArray<double, double> aStdCond;
	CArray<double, double> aStdCoeff;
	aStdCond.SetSize(STD_NUM);
	aStdCoeff.SetSize(STD_NUM);

	aStdCond[0] = 0.1;
	aStdCond[1] = 0.2;
	aStdCond[2] = 0.3;

	if     (nSiteClass==0) { aStdCoeff[0] = 0.84;	aStdCoeff[1] = 0.84;	aStdCoeff[2] = 0.84; }  // S1
	else if(nSiteClass==1) { aStdCoeff[0] = 1.5;	aStdCoeff[1] = 1.4;		aStdCoeff[2] = 1.3;  }  // S2
	else if(nSiteClass==2) { aStdCoeff[0] = 1.7;	aStdCoeff[1] = 1.6;		aStdCoeff[2] = 1.5;  }  // S3
	else if(nSiteClass==3) { aStdCoeff[0] = 2.2;	aStdCoeff[1] = 2.0;		aStdCoeff[2] = 1.8;  }  // S4
	else if(nSiteClass==4) { aStdCoeff[0] = 3.0;	aStdCoeff[1] = 2.7;		aStdCoeff[2] = 2.4;  }  // S5
	else ASSERT(0);

	if (CCompFunc::CompReal(dSs, aStdCond[0]) < 1) dFv = aStdCoeff[0];
	else if(!m_pDoc->m_pAttrCtrl2->GetLineInterPValue(aStdCond, aStdCoeff, dSs, dFv)) ASSERT(0);

	return TRUE;
}

BOOL CAttrCtrl::CalcKBC2009Sds(double dZoneFactor, double& dFa, double& dSds)
{
	// Sds : Design Spectral Response Acc. at short periods
	dSds = (2./3.) * dZoneFactor * 2.5 * dFa;
	return TRUE;
}

BOOL CAttrCtrl::CalcKBC2009Sd1(double dZoneFactor, double& dFv, double& dSd1)
{
	// Sd1 : Design Spectral Response Acc. at 1 s periods
	dSd1 = (2./3.) * dZoneFactor * dFv;
	return TRUE;
}

BOOL CAttrCtrl::CalcKBC2009Cu(double& dSd1, double& dCu)
{
	// Cu : The coefficient for upper limit in calculated period, upper limit coefficient
	if      (dSd1 >= 0.3) dCu = 1.4;
	else if (dSd1 <= 0.1) dCu = 1.7;
	else if (dSd1 < 0.3 && dSd1 > 0.2) dCu = (-1 * dSd1) + 1.7;
	else if (dSd1 == 0.2) dCu = 1.5;
	else                               dCu = (-2 * dSd1) + 1.9;
	return TRUE;
}

