BOOL CAttrCtrl::CalcKBC2005SeisDesignCategory(int nSeisUseGroup, double dSds, double dSd1,
											  CString& SDC_S, CString& SDC_1, CString& SDC)
{
	if(nSeisUseGroup < 0 || nSeisUseGroup > 2) return FALSE;
	if(dSds <= 0.) return FALSE;
	if(dSd1 <= 0.) return FALSE;

	CString T_SDC[4] = {_T("A"), _T("B"), _T("C"), _T("D")};

	static int T_SDC_S[4][3] = {{3, 3, 3}, {3, 2, 2}, {2, 1, 1}, {0, 0, 0}};
	static int T_SDC_1[4][3] = {{3, 3, 3}, {3, 2, 2}, {2, 1, 1}, {0, 0, 0}};

	int nIndexSds = 0;
	if(dSds >= 0.5) nIndexSds = 0;
	else if(dSds >= 0.33 && dSds < 0.50) nIndexSds = 1;
	else if(dSds >= 0.17 && dSds < 0.33) nIndexSds = 2;
	else if(dSds >  0.00 && dSds < 0.17) nIndexSds = 3;

	int nIndexSd1 = 0;
	if(dSd1 >= 0.2) nIndexSd1 = 0;
	else if(dSd1 >= 0.14 && dSd1 < 0.20) nIndexSd1 = 1;
	else if(dSd1 >= 0.07 && dSd1 < 0.14) nIndexSd1 = 2;
	else if(dSd1 >  0.00 && dSd1 < 0.07) nIndexSd1 = 3;

	int nSDC_S = T_SDC_S[nIndexSds][nSeisUseGroup];
	int nSDC_1 = T_SDC_1[nIndexSd1][nSeisUseGroup];
	int nSDC   = max(nSDC_S, nSDC_1);
	SDC_S = T_SDC[nSDC_S];
	SDC_1 = T_SDC[nSDC_1];
	SDC   = T_SDC[nSDC];
	return TRUE;
}

