void CAttrCtrl::GetSeisKeyList(CArray<T_SEIS_K, T_SEIS_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_SEIS_K Key;
	T_SEIS_D Data;
	pos=GetStartSeis();
	while(pos != NULL)
	{
		GetNextSeis(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

T_SEIS_D CAttrCtrl::GetSeis_InitializedByNation()
{
	T_SEIS_D SeisD;
	SeisD.Initialize();    
	SeisD.ScaleFactor_X = 1.0;
	SeisD.ScaleFactor_Y = 1.0;

	int nMovingType = CProduct::GetMovingType();
    switch ( nMovingType )
    {
    case D_PRODUCT_MOVING_US:
    case D_PRODUCT_MOVING_RUS:
        {
            if ( CProduct::IsIndia() )
            {
                SeisD.nCodeType = IS_E_2002;
            }
            else if ( CProduct::IsTaiwan() )
            {
                SeisD.nCodeType = TAIWAN_E_2011;
            }
            else
            {
                SeisD.nCodeType = IBC_E_2012;
            }
        }
        break;
    case D_PRODUCT_MOVING_JP:
        {
            SeisD.nCodeType = JIS_E_YY;
        }
        break;
    case D_PRODUCT_MOVING_CH:
        {
            SeisD.nCodeType = CH_E_2001;
        }
        break;
    default:
        {
            SeisD.nCodeType = KBC_E_2016;
        }
        break;
    }

	return SeisD;
}

////////////// ssei : superstructure seismic load ///////////////////

BOOL CAttrCtrl::ExistSsei(T_SSEI_K Key)
{
	T_SSEI_D Data;
	return m_pDataMemb->m_ssei.Get(Key,Data);
}

BOOL CAttrCtrl::GetSsei(T_SSEI_K Key,T_SSEI_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_ssei.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitSseiOut(rData);
	return bReturn;
}

int CAttrCtrl::GetCountSsei()
{
	return m_pDataMemb->m_ssei.GetCount();
}

POSITION CAttrCtrl::GetStartSsei()
{
	return m_pDataMemb->m_ssei.GetStart();
}

