void CAttrCtrl::CalcSseiLoad(T_SSEI_K Key,T_SSEI_D& rData, CArray<T_BMLD_UDRD_D, T_BMLD_UDRD_D&>& arSseiLoad, BOOL bAnal)
{ 
	arSseiLoad.RemoveAll();
	if(GetCountSsei() == 0) return;

	T_BMLD_UDRD_D DataBmld;
	T_ELEM_K KeyElem;
	T_ELEM_D DataElem;
	T_SECT_D DataSect;
	T_MATL_D DataMatl;
	double dEndLoad[2], dVector[3];
	double vx, vy, vz, dWgt1, dWgt2;

	CMap<T_NODE_K, T_NODE_K, int, int> mapUsedNode;
	mapUsedNode.InitHashTable(m_pDoc->GetHashSizeNode());
	mapUsedNode.RemoveAll();
	int nTemp;

	CSelfWgt CalcWeight(m_pDoc);
	CStoryLoad CalcBeamLoad;

	// MQC:2734 mylee 20090715
	CMap<UINT, UINT, UINT, UINT> mapSectKeyCscsAssigned;
	T_CSCS_K TempCscsK;
	T_CSCS_D TempCscsD;
	POSITION pos = GetStartCscs();
	while (pos != 0)
	{
		GetNextCscs(pos, TempCscsK, TempCscsD);
		mapSectKeyCscsAssigned.SetAt(TempCscsD.SectKey, TempCscsK);
	}

	for(int i = 0; i < rData.arKeyElem.GetSize(); i++)
	{
		KeyElem = rData.arKeyElem.GetAt(i);
		if(!GetElem(KeyElem, DataElem)) continue;
		if(!IsFrameType(DataElem.eltyp)) continue;

		double dPI = 3.141592654;
		dVector[0] = cos(dPI * rData.dAngle / 180.);
		dVector[1] = sin(dPI * rData.dAngle / 180.);
		dVector[2] = 0.;
		for(int j = 0; j < 3; j++)
		{
			if(fabs(dVector[j]) <= 1.0e-8) dVector[j] = 0.;
		}
		CMathFunc::mathNormalize(dVector[0], dVector[1], dVector[2], vx, vy, vz);    

		// 부재의 자중을 Beam Load(분포하중)로 전환    
		CalcWeight.CalcBeamTrussWgt(KeyElem, DataElem, dWgt1, dWgt2, mapSectKeyCscsAssigned);
		if(dWgt1 != 0. || dWgt2 != 0.)
		{
			dEndLoad[0] = dWgt1 * rData.dKh;
			dEndLoad[1] = dWgt2 * rData.dKh;        

			DataBmld.key.key.entity = KeyElem;
			DataBmld.data.Initialize();
			DataBmld.data.LoadCaseKey = Key;    
			DataBmld.data.LoadCommandType = 6; // Line Load
			DataBmld.data.LoadType = 3;        // Distributed Load 
			DataBmld.data.LoadDirection = 7;   // Vector Direction
			DataBmld.data.Vector[0] = vx;
			DataBmld.data.Vector[1] = vy;
			DataBmld.data.Vector[2] = vz;
			DataBmld.data.Projection = 0;      // No porjection 
			DataBmld.data.GroupKey = 0;
			DataBmld.data.DistanceRatio[0] = 0.;
			DataBmld.data.DistanceRatio[1] = 1.;    
			DataBmld.data.Force_Type[DataBmld.data.LoadType-1][0] = dEndLoad[0];
			DataBmld.data.Force_Type[DataBmld.data.LoadType-1][1] = dEndLoad[1];
			arSseiLoad.Add(DataBmld);    
		}

		if(rData.bAdditionDeadLoad)
		{
			BOOL bNodeI = FALSE;
			BOOL bNodeJ = FALSE;
			if(!mapUsedNode.Lookup(DataElem.elnod[0], nTemp)) 
			{
				bNodeI = TRUE;
				mapUsedNode.SetAt(DataElem.elnod[0], 1);
			}
			if(!mapUsedNode.Lookup(DataElem.elnod[1], nTemp)) 
			{
				bNodeJ = TRUE;
				mapUsedNode.SetAt(DataElem.elnod[1], 1);
			}
			// 부가사하중을 Beam Load(양 절점의 집중하중 형태)로 전환(집중하중 및 Beam Load)    
			CalcBeamLoad.CalcSseiNodalBmld(KeyElem, DataElem, rData.StldKey, rData.bBeamLoad, 
				rData.bNodalLoad, bNodeI, bNodeJ, dWgt1, dWgt2);
			if(dWgt1 != 0. || dWgt2 != 0.)
			{
				dEndLoad[0] = dWgt1 * rData.dKh;
				dEndLoad[1] = dWgt2 * rData.dKh;   

				DataBmld.key.key.entity = KeyElem;
				DataBmld.data.Initialize();
				DataBmld.data.LoadCaseKey = Key;    
				DataBmld.data.LoadCommandType = 6; // Line Load
				DataBmld.data.LoadType = 1;        // Concentrated Force
				DataBmld.data.LoadDirection = 7;   // Vector Direction
				DataBmld.data.Vector[0] = vx;
				DataBmld.data.Vector[1] = vy;
				DataBmld.data.Vector[2] = vz;
				DataBmld.data.Projection = 0;      // No porjection 
				DataBmld.data.GroupKey = 0;
				DataBmld.data.DistanceRatio[0] = 0.;
				DataBmld.data.DistanceRatio[1] = 1.;    

				if(bAnal && !bNodeI && bNodeJ)
				{
					DataBmld.data.Force_Type[DataBmld.data.LoadType-1][0] = dEndLoad[1];
					DataBmld.data.Force_Type[DataBmld.data.LoadType-1][1] = dEndLoad[0];
				}
				else
				{
					DataBmld.data.Force_Type[DataBmld.data.LoadType-1][0] = dEndLoad[0];
					DataBmld.data.Force_Type[DataBmld.data.LoadType-1][1] = dEndLoad[1];
				}

				arSseiLoad.Add(DataBmld);   
			}
		}
	}  
}

void CAttrCtrl::CalcSseiLoadLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, T_SSEI_K KeySsei, CArray<T_BMLD_UDRD_D, T_BMLD_UDRD_D&>& arSseiLoad)
{
	arSseiLoad.RemoveAll();  
	if(!CheckLcomLabel(bAllLoadCase, DataLcom))return;
	if(GetCountSsei() == 0)return;

	T_SSEI_K Key;
	T_SSEI_D DataSsei;  
	CArray<T_BMLD_UDRD_D, T_BMLD_UDRD_D&> arSseiBmld;
	CMap<T_ELEM_K, T_ELEM_K, T_BMLD_D, T_BMLD_D&>mapSseiLoad;
	mapSseiLoad.InitHashTable(HASHSIZESTLD); 
	POSITION pos=GetStartSsei();
	while(pos != NULL)
	{
		GetNextSsei(pos, Key, DataSsei);
		CalcSseiLoad(Key, DataSsei, arSseiBmld);
		if(KeySsei != 0 && KeySsei != Key) continue;  
		double dFactor=1.;
		if(bAllLoadCase)
		{
			arSseiLoad.Copy(arSseiBmld);      
		}
		else
		{
			double dStldFactor=0., dStagFactor=0.;
			if(!GetLcomStldFactor(Key, DataLcom, dStldFactor, dStagFactor))return;  
			if(dStldFactor == 0.)continue;
			BOOL bNonZero=FALSE;
			for(int i = 0; i < arSseiBmld.GetSize(); i++)
			{        
				T_BMLD_UDRD_D DataBmld = arSseiBmld[i];
				T_BMLD_D data = arSseiBmld[i].data;        
				for(int j = 0; j < 4; j++)
				{
					data.Force_Type[data.LoadType - 1][j] *= dStldFactor;
					if(data.Force_Type[data.LoadType-1][j] != 0.) bNonZero=TRUE;
				}
				DataBmld.data = data;
				if(bNonZero) arSseiLoad.Add(DataBmld);
			}      
		}
	}
}

BOOL CAttrCtrl::CalcSWtoBeamLoad(T_BODF_D& Bdata, T_GRUP_D& Gdata)
{ 
	T_BMLD_D BmldD;

	T_ELEM_K KeyElem;
	T_ELEM_D DataElem;
	T_SECT_D SectD;
	double dEndLoad[2];

	CSelfWgt CalcWeight(m_pDoc);

	CArray<T_ELEM_K, T_ELEM_K>arKeyElem; arKeyElem.Copy(Gdata.arKeyElem);
	if(arKeyElem.GetSize() > 0) CQSort::QSortUInt(arKeyElem.GetData(), arKeyElem.GetSize());

	CArray<T_BMLD_K, T_BMLD_K> rBmldKey; rBmldKey.RemoveAll();
	CArray<T_BMLD_D, T_BMLD_D&> rBmldData; rBmldData.RemoveAll();
	for(int i = 0; i < arKeyElem.GetSize(); i++)
	{
		KeyElem = arKeyElem.GetAt(i);
		if(!GetElem(KeyElem, DataElem)) continue;
		if(!IsFrameType(DataElem.eltyp)) continue;

		T_ELEM_WEIGHT rData;
		//if(!CalcWeight.GetElemWeight_Frame(KeyElem, rData, FALSE, FALSE)) continue;
		if(!CalcWeight.GetElemWeight4BeamLoad(KeyElem, rData)) continue;

		if(rData.dWeightI != 0. || rData.dWeightJ != 0.)
		{
			int LoadDirection=0;
			double dFactor=0.0;
			for(int j=0; j<3; j++)
			{
				if(j==0 && fabs(Bdata.SX)<1.0e-10) continue; 
				if(j==1 && fabs(Bdata.SY)<1.0e-10) continue; 
				if(j==2 && fabs(Bdata.SZ)<1.0e-10) continue; 

				if     (j==0) {LoadDirection = 4;  dFactor=Bdata.SX;}
				else if(j==1) {LoadDirection = 5;  dFactor=Bdata.SY;}
				else if(j==2) {LoadDirection = 6;  dFactor=Bdata.SZ;}
				else ASSERT(0);

				dEndLoad[0] = rData.dWeightI*dFactor;
				dEndLoad[1] = rData.dWeightJ*dFactor;        

				BmldD.Initialize();
				BmldD.LoadCaseKey = Bdata.LoadCaseKey;    
				BmldD.LoadCommandType = 6; // Line Load
				BmldD.LoadType = 3;        // Distributed Load 
				BmldD.LoadDirection = LoadDirection;  
				BmldD.GroupKey = Bdata.GroupKey;  // Load Group Key
				BmldD.DistanceRatio[0] = 0.;
				BmldD.DistanceRatio[1] = 1.;    
				BmldD.Force_Type[BmldD.LoadType-1][0] = dEndLoad[0];
				BmldD.Force_Type[BmldD.LoadType-1][1] = dEndLoad[1];

				T_BMLD_K BmldK;
				if(!m_pDoc->m_pAttrCtrl->MakeKeyBmld(KeyElem, BmldK)) { ASSERT(0); return FALSE;}
				rBmldKey.Add(BmldK);
				rBmldData.Add(BmldD);
			}
		}
	}  

	BOOL bOK = m_pDoc->m_pDataCtrl->AddBmld(rBmldKey,rBmldData);

	return bOK;
}

