BOOL CAttrCtrl::GetSerialTdpl(T_TDNA_K KeyTdna,T_STLD_K KeyStld,T_LDGR_K KeyLdgr,T_TDPL_KEY& rKeySerial)
{
	T_TDPL_K key;
	T_TDPL_D data;
	POSITION pos = m_pDataMemb->m_tdpl.GetStartFromBaseDB();
	while(pos != NULL)
	{
		m_pDataMemb->m_tdpl.GetNextFromBaseDB(pos, key, data);
		if (key.key.entity != KeyTdna) continue;
		if(data.LoadCaseKey == KeyStld && data.GroupKey == KeyLdgr)
		{
			rKeySerial=key.key.serial;
			return TRUE;
		}
	}

	key.key.entity=KeyTdna;
	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_tdpl.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

