BOOL CAttrCtrl::MakeKeyTdpl(T_TDNA_K KeyTdna,T_STLD_K KeyStld,T_LDGR_K KeyLdgr,T_TDPL_K& rKey)
{
	rKey.key.entity=KeyTdna;
	rKey.key.serial=0;

	T_TDPL_KEY KeySerial;
	if(!GetSerialTdpl(KeyTdna, KeyStld, KeyLdgr, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

