void CAttrCtrl::GetTdplLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, BOOL bAllLdgr, CArray<T_LDGR_K, T_LDGR_K>& raLdgrKey, T_TDNA_K KeyTdna, CArray<T_TDPL_D, T_TDPL_D&>& rarData)
{
	rarData.RemoveAll();
	if(!CheckLcomLabel(bAllLoadCase, DataLcom))return;

	CMap<T_LDGR_K, T_LDGR_K, T_LDGR_K, T_LDGR_K> mapLdgr;
	if (!bAllLdgr)
	{
		mapLdgr.InitHashTable(11);
		for (int i = 0; i < raLdgrKey.GetSize(); i++)mapLdgr.SetAt(raLdgrKey[i], raLdgrKey[i]);
	}

	T_TDPL_K key;
	T_TDPL_D data;

	POSITION pos=GetStartTdpl();
	while(pos != NULL)
	{
		GetNextTdpl(pos, key, data);
		if(key.key.entity == KeyTdna)
		{
			if (!bAllLdgr && !mapLdgr.Lookup(data.GroupKey, data.GroupKey)) continue;

			if(bAllLoadCase)
			{
				rarData.Add(data);
			}
			else
			{
				double dStldFactor=0., dStagFactor=0.;
				BOOL bTDPL=TRUE;
				if(!GetLcomStldFactor(data.LoadCaseKey, DataLcom, dStldFactor, dStagFactor, bTDPL))return;  
				T_STLD_D DataStld;
				if(dStldFactor != 0.)
				{
					T_TDPL_D DataTdpl=data;
					DataTdpl.dValueBegin[data.nValueType]=data.dValueBegin[data.nValueType]*dStldFactor;
					DataTdpl.dValueEnd[data.nValueType]=data.dValueEnd[data.nValueType]*dStldFactor;
					rarData.Add(DataTdpl);
				}
				if(dStagFactor != 0. && m_pDoc->m_pStagCtrl->IsActiveLdgrKey(data.GroupKey))
				{
					T_TDPL_D DataTdpl=data;
					DataTdpl.dValueBegin[data.nValueType]=data.dValueBegin[data.nValueType]*dStagFactor;
					DataTdpl.dValueEnd[data.nValueType]=data.dValueEnd[data.nValueType]*dStagFactor;
					rarData.Add(DataTdpl);
				}
			}
		}
	}
	return;
}

