BOOL CAttrCtrl::CheckStageTdplData(BOOL bError /*= FALSE*/)
{
 	CMap <UINT2, UINT2, int, int> mapTdpl;
 	mapTdpl.InitHashTable(11);
	UINT2 StagTdplK;

	//T_STAG_K StagKey;
	T_STAG_D StagData;
	CArray<T_STAG_K, T_STAG_K> aStagKey;
	int nActiveNum;
	//int nDeactiveNum;
	T_KEY2 StagLdgrKey;
	T_LIST_DATA ListData;
	LdgrList *pList;
	POSITION pos;

	T_TDPL_K KeyTdpl;
	T_TDPL_D DataTdpl;
	T_TDNA_K KeyTdna;
	T_TDNA_D DataTdna;
	T_TDNT_D DataTdnt;

	BOOL bChkTdpl = TRUE;
	int nTemp = 0;

	m_pDoc->m_pAttrCtrl->GetStagKeyList(aStagKey);
	int nStagCount = aStagKey.GetSize();
	for (int i = 0; i < nStagCount; i++)
	{
		StagLdgrKey.k1 = aStagKey[i];
		m_pDoc->m_pAttrCtrl->GetStag(StagLdgrKey.k1, StagData);
		nActiveNum = StagData.aActiveLoad.GetSize();
		for (int j = 0; j < nActiveNum; j++)
		{
			StagLdgrKey.k2 = StagData.aActiveLoad[j].LdgrKey;
			m_pDoc->m_memb->m_ldgr.GetList(StagLdgrKey.k2, pList);
			pos = pList->GetHeadPosition();
			while (pos)
			{
				ListData = pList->GetNext(pos);
				switch (ListData.nCmd)
				{
				case LT_TDPL_CMD:
					KeyTdpl.keymap= ListData.nKey;  
					m_pDoc->m_pAttrCtrl->GetTdpl(KeyTdpl, DataTdpl);
					KeyTdna = KeyTdpl.key.entity;
					if (!m_pDoc->m_pAttrCtrl->GetTdna(KeyTdna, DataTdna)) { ASSERT(0); continue;}
					if(!m_pDoc->m_pAttrCtrl->GetTdnt(DataTdna.TendonTypeKey, DataTdnt)) ASSERT(0);

					if(DataTdnt.nTendonType == 1 && DataTdnt.nLoadType == 0) // Internal(= Pretension)
					{
						StagTdplK.i1 = KeyTdna;
						StagTdplK.i2 = DataTdna.TendonTypeKey;
						
						if(mapTdpl.Lookup(StagTdplK, nTemp))
						{
							bChkTdpl = FALSE;
							break;
						}
						else
						{
							mapTdpl.SetAt(StagTdplK, nTemp);
						}							
					}	
					break;
				default:
					break;

				}
			}
		} // nActiveNum
	}

	if (!bChkTdpl)
	{
		if (bError)
		{
			GSaveHistoryFormatNF(_LS(IDS_DB_STAGE_TDPL_ERROR));
		}
		else
		{
			GSaveHistoryFormatNF(_LS(IDS_DB_STAGE_TDPL_WARNING));
		}
	}

	return bChkTdpl;
}

