void CAttrCtrl::GetImpfElemKeyList(CArray<T_ELEM_K, T_ELEM_K>& rElemKeyList)
{
	rElemKeyList.RemoveAll();
	CArray<T_IMPF_K, T_IMPF_K> aImpfKeyList;
	GetImpfKeyList(aImpfKeyList);
	int nNum = aImpfKeyList.GetSize();
	if (nNum == 0) return;
	rElemKeyList.Add(aImpfKeyList[0].key.entity);
	for (int i = 1; i < nNum; i++)
	{
		if (aImpfKeyList[i].key.entity == aImpfKeyList[i-1].key.entity)
			continue;
		rElemKeyList.Add(aImpfKeyList[i].key.entity);
	}
}

BOOL CAttrCtrl::ExistImpf(T_IMPF_K Key)
{
	T_IMPF_D Data;
	return m_pDataMemb->m_pimpf->Get(Key,Data);
}

BOOL CAttrCtrl::GetImpf(T_IMPF_K Key,T_IMPF_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_pimpf->Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitImpfOut(rData);
	return bReturn;
}

void CAttrCtrl::GetImpfElem(T_ELEM_K KeyElem, CArray<T_IMPF_K, T_IMPF_K>& rKeyList, CArray<T_IMPF_D, T_IMPF_D&>& rDataList)
{
	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	ElemList* pList;
	if(!m_pDataMemb->m_elem.GetList(KeyElem, pList)) return;
	//VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_IMPF_CMD)
		{
			T_IMPF_K key;
			T_IMPF_D data;
			key.keymap=ListData.nKey;
			GetImpf(key, data);
			rKeyList.Add(key);
			rDataList.Add(data);
		}
	}
}

