void CAttrCtrl::GetLlanKeyList(CArray<T_LLAN_K, T_LLAN_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<CString, CString&>arLaneName;

	POSITION pos;
	T_LLAN_K Key;
	T_LLAN_D Data;
	pos=GetStartLlan();
	while(pos != NULL)
	{
		GetNextLlan(pos, Key, Data);
		rKeyList.Add(Key);
		arLaneName.Add(Data.LineLaneName);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortStringWithIndex(rKeyList.GetData(), arLaneName.GetData(), rKeyList.GetSize());
}

