void CAttrCtrl::ConvertLlanoptoLlan(T_LLANop_D& LlanopD, double dOffset, T_LLAN_D& LlanD)
{
	LlanD.Initialize();

	LlanD.LineLaneName = LlanopD.LineLaneName;
	LlanD.LineLaneId = LlanopD.LineLaneId;
	LlanD.nLoadDistribution = LlanopD.nLoadDistribution;
	LlanD.ElemGroup = LlanopD.ElemGroup;
	LlanD.dSkewStart = LlanopD.dSkewStart;
	LlanD.dSkewEnd = LlanopD.dSkewEnd;
	LlanD.nMovingDir = LlanopD.nMovingDir;
	LlanD.dLineWidth = LlanopD.dLaneWidth;
	LlanD.dWheelSpace = LlanopD.dWheelSpace; 
	LlanD.bAutoOptimize = FALSE;
	LlanD.dAllowWidth = 0.0;
	LlanD.nLaneType = LlanopD.nLaneType;

	int nSize = LlanopD.arLaneData.GetSize();
	LlanD.arLaneData.SetSize(nSize);
	for(int i=0; i<nSize; i++)
	{
		LlanD.arLaneData[i].KeyElem = LlanopD.arLaneData[i].KeyElem;
		LlanD.arLaneData[i].Eccentricity = LlanopD.arLaneData[i].Eccentricity + dOffset;
		LlanD.arLaneData[i].fact = LlanopD.arLaneData[i].fact;
		LlanD.arLaneData[i].bSpanStart = LlanopD.arLaneData[i].bSpanStart;
		LlanD.arLaneData[i].dEccenVertLoad = 0.0;
		LlanD.arLaneData[i].dCentF = LlanopD.arLaneData[i].dCentF;
	}
}

void CAttrCtrl::ConvertLlanoptoLlanch(T_LLANop_D& LlanopD, double dOffset, T_LLANch_D& LlanchD)
{
	LlanchD.Initialize();

	LlanchD.LineLaneName = LlanopD.LineLaneName;
	LlanchD.LineLaneId = LlanopD.LineLaneId;
	LlanchD.nLoadDistribution = LlanopD.nLoadDistribution;
	LlanchD.ElemGroup = LlanopD.ElemGroup;
	LlanchD.dSkewStart = LlanopD.dSkewStart;
	LlanchD.dSkewEnd = LlanopD.dSkewEnd;
	LlanchD.nMovingDir = LlanopD.nMovingDir;
	LlanchD.dWheelSpace = LlanopD.dWheelSpace; 
	LlanchD.dLineWidth = LlanopD.dLaneWidth;	
	LlanchD.bAutoOptimize = FALSE;
	LlanchD.dAllowWidth = 0.0;

	int nSize = LlanopD.arLaneData.GetSize();
	LlanchD.arLaneData.SetSize(nSize);
	for(int i=0; i<nSize; i++)
	{
		LlanchD.arLaneData[i].KeyElem = LlanopD.arLaneData[i].KeyElem;
		LlanchD.arLaneData[i].Eccentricity = LlanopD.arLaneData[i].Eccentricity + dOffset;
		LlanchD.arLaneData[i].dSpan = LlanopD.arLaneData[i].dSpan;
		LlanchD.arLaneData[i].bSpanStart = LlanopD.arLaneData[i].bSpanStart;
		LlanchD.arLaneData[i].dScaleFactor = LlanopD.arLaneData[i].dScaleFactor;
	}
}

