void CAttrCtrl::GetMlspKeyList(CArray<T_MLSP_K, T_MLSP_K>& rKeyList)
{
	rKeyList.RemoveAll();

	CArray<UINT, UINT> aKeymapList;

	POSITION pos;
	T_MLSP_K Key;
	T_MLSP_D Data;
	pos=GetStartMlsp();
	while(pos != NULL)
	{
		GetNextMlsp(pos, Key, Data);
		aKeymapList.Add(Key.keymap);
	}
	if(aKeymapList.GetSize() > 0)CQSort::QSortUInt(aKeymapList.GetData(), aKeymapList.GetSize());

	const int nSize = aKeymapList.GetSize();
	T_MLSP_K MlspK;
	for(int i=0 ; i<nSize ; ++i)
	{
		MlspK.keymap = aKeymapList[i];
		rKeyList.Add(MlspK);
	}


	//if(rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

int CAttrCtrl::GetMlstKeyListByType(const int &nType, CArray<T_MLSP_K, T_MLSP_K>& rKeyList)
{
	rKeyList.RemoveAll();

	CArray<T_MLSP_K, T_MLSP_K> aMlspK;
	GetMlspKeyList(aMlspK);
	int nSize = aMlspK.GetSize();
	if(nSize<1) return 0;

	for(int i=0; i<nSize; ++i)
	{
		if(aMlspK[i].key.serial!=nType) continue;
		rKeyList.Add(aMlspK[i]);
	}
	rKeyList.FreeExtra();

	return rKeyList.GetSize();
}

