BOOL CAttrCtrl::IsUsePlateConcurrentCode()
{
	BOOL bUse = FALSE;

	T_MVCD_D MvcdD; MvcdD.Initialize();
	if(!GetMvcd(MvcdD)) bUse = FALSE;

	if     (MvcdD.nCodeType == D_MOVE_CODE_KOREA          ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_KOREA_LRFD_2011) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_AASHTO_STAN    ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_AASHTO_LRFD    ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_TAIWAN         ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_CANADA         ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_PENDOT         ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_AUSTRALIA      ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_BS             ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_EURO_BS        ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_POLAND         ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_SOUTH_AFRICA   ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_FRANCE         ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_NEWZEALAND     ) bUse = TRUE;
	else if(MvcdD.nCodeType == D_MOVE_CODE_BRAZIL         ) bUse = TRUE;
	else                                                    bUse = FALSE;  

	return bUse;
}

