BOOL CAttrCtrl::IsMvCombindStressResult()
{
	T_MVCT_D   rData;    rData.Initialize();
	T_MVCTjp_D rData_jp; rData_jp.Initialize();
	T_MVCTch_D rData_ch; rData_ch.Initialize();
	T_MVCTid_D rData_id; rData_id.Initialize();
	T_MVCTtr_D rData_tr; rData_tr.Initialize();
	T_MVCTbs_D rData_bs; rData_bs.Initialize();
	T_MVCTfr_D rData_fr; rData_fr.Initialize();

	BOOL bStressCalcFrame = TRUE; // 기본값을  TRUE 로 변경
	if     (m_pDoc->m_pAttrCtrl->GetMvct(rData))      bStressCalcFrame = rData.bStressCalcFrame;
	else if(m_pDoc->m_pAttrCtrl->GetMvctjp(rData_jp)) bStressCalcFrame = rData_jp.bStressCalcFrame;
	else if(m_pDoc->m_pAttrCtrl->GetMvctch(rData_ch)) bStressCalcFrame = rData_ch.bStressCalcFrame;
	else if(m_pDoc->m_pAttrCtrl->GetMvctid(rData_id)) bStressCalcFrame = rData_id.bStressCalcFrame;
	else if(m_pDoc->m_pAttrCtrl->GetMvcttr(rData_tr)) bStressCalcFrame = rData_tr.bCombinedStress;
	else if(m_pDoc->m_pAttrCtrl->GetMvctbs(rData_bs)) bStressCalcFrame = rData_bs.bStressCalcFrame;
	else if(m_pDoc->m_pAttrCtrl->GetMvctfr(rData_fr)) bStressCalcFrame = rData_fr.bStressCalcFrame;

	return bStressCalcFrame;
}


////////////// mvhl ////////////////
void CAttrCtrl::GetMvhlList(CArray<CString, CString&>& rstrLoadList)
{
	rstrLoadList.RemoveAll();

	T_MVHL_D Data;
	CArray<T_MVHL_K, T_MVHL_K>KeyList;
	GetMvhlKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetMvhl(KeyList[i], Data))
			rstrLoadList.Add(Data.VehicleLoadName);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetMvhlKeyList(CArray<T_MVHL_K, T_MVHL_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<CString, CString&>arLoadName;

	POSITION pos;
	T_MVHL_K Key;
	T_MVHL_D Data;
	pos=GetStartMvhl();
	while(pos != NULL)
	{
		GetNextMvhl(pos, Key, Data);
		rKeyList.Add(Key);
		arLoadName.Add(Data.VehicleLoadName);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortStringWithIndex(rKeyList.GetData(), arLoadName.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::ExistMvhl(CString& rLoadName)
{
	T_MVHL_D data;
	return GetMvhl(rLoadName, data);
}

BOOL CAttrCtrl::ExistMvhl(T_MVHL_K Key)
{
	T_MVHL_D Data;
	return m_pDataMemb->m_pmvhl->Get(Key,Data);
}

BOOL CAttrCtrl::GetMvhl(CString& rLoadName, T_MVHL_D& rData)
{
	T_MVHL_K key;
	T_MVHL_D data;
	CString strLoadName=rLoadName;
	strLoadName.TrimRight();

	POSITION pos=m_pDataMemb->m_pmvhl->GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_pmvhl->GetNext(pos,key,data);
		if(strLoadName.CompareNoCase(data.VehicleLoadName) == 0)
		{
			m_pUnitCtrl->ConvertUnitMvhlOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetMvhl(T_MVHL_K Key,T_MVHL_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_pmvhl->Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitMvhlOut(rData);
	return bReturn;
}

T_MVHL_K CAttrCtrl::GetMvhlKey(const CString& rLoadName)
{
	T_MVHL_K key;
	T_MVHL_D data;

	POSITION pos=GetStartMvhl();
	while(pos != NULL)
	{
		GetNextMvhl(pos,key,data);
		if(rLoadName.CompareNoCase(data.VehicleLoadName) == 0)return key;
	}
	key=0;
	return key;
}

