BOOL CAttrCtrl::IsPatchLoadVehicle(T_MVHL_D& MvhlD)
{

	T_MVCD_D MvcdD; MvcdD.Initialize();
	if (!m_pDoc->m_pAttrCtrl->GetMvcd(MvcdD)) return FALSE;
	if (MvcdD.nCodeType == D_MOVE_CODE_EURO_BS || MvcdD.nCodeType == D_MOVE_CODE_BS) return TRUE;

	if (MvcdD.nCodeType != D_MOVE_CODE_AASHTO_LRFD && MvcdD.nCodeType != D_MOVE_CODE_NEWZEALAND && MvcdD.nCodeType != D_MOVE_CODE_BRAZIL && MvcdD.nCodeType != D_MOVE_CODE_KOREA_LRFD_2011) return FALSE;

	if (MvhlD.bStandard)
	{
		if (MvhlD.nStandardCode == D_MVHL_AASHTO_LRFD)
		{
			if (MvhlD.VehicleTypeName == _T("HL-93TRK") ||
				MvhlD.VehicleTypeName == _T("HL-93TDM") ||
				MvhlD.VehicleTypeName == _T("HS20-FTG") ||
				MvhlD.VehicleTypeName == _T("KYHL-93TRK") ||
				MvhlD.VehicleTypeName == _T("KYHL-93TDM"))
				return TRUE;
		}
		else if (MvhlD.nStandardCode == D_MVHL_KSCE_LSD15)
		{
			if (MvhlD.VehicleTypeName == _T("KL-510TRK") ||
				MvhlD.VehicleTypeName == _T("KL-510FTG") ||
				MvhlD.VehicleTypeName == _T("KL-510LNE"))
				return TRUE;
		}
		else if (MvhlD.nStandardCode == D_MVHL_TRAFFIC_LOAD_NZ)
		{
			if (MvhlD.VehicleTypeName == _T("HN (normal) loading") ||
				MvhlD.VehicleTypeName == _T("HO (overload) loading (a)") ||
				MvhlD.VehicleTypeName == _T("HO (overload) loading (b)"))
				return TRUE;
		}
		else if (MvhlD.nStandardCode == D_MVHL_DECK_EVALUATION ||
			MvhlD.nStandardCode == D_MVHL_FATIGUE_NZ)
		{
			return TRUE;
		}
		else if (MvhlD.nStandardCode == D_MVHL_AASHTO_IADOT || MvhlD.nStandardCode == D_MVHL_AASHTO_ILDOT ||
			MvhlD.nStandardCode == D_MVHL_AASHTO_LADOT || MvhlD.nStandardCode == D_MVHL_AASHTO_MODOT || MvhlD.nStandardCode == D_MVHL_AASHTO_OHDOT ||
			MvhlD.nStandardCode == D_MVHL_AASHTO_RIDOT || MvhlD.nStandardCode == D_MVHL_AASHTO_VADOT || MvhlD.nStandardCode == D_MVHL_AASHTO_WIDOT ||
			MvhlD.nStandardCode >= D_MVHL_ALABAMA && MvhlD.nStandardCode <= D_MVHL_ALASKA)
		{
			if (MvhlD.VehicleTypeName == _T("HL-93TRK") ||
				MvhlD.VehicleTypeName == _T("HL-93TDM") ||
				MvhlD.VehicleTypeName == _T("HS20-FTG") ||
				MvhlD.VehicleTypeName == _T("KYHL-93TRK") ||
				MvhlD.VehicleTypeName == _T("KYHL-93TDM"))
				return TRUE;
		}
		else if (MvhlD.nStandardCode == D_MVHL_NBR7188_ROADWAY || MvhlD.nStandardCode == D_MVHL_NBR7189_RAILWAY)
		{
			return TRUE;
		}
	}
	else if (MvcdD.nCodeType == D_MOVE_CODE_BRAZIL)
	{
		return TRUE;
	}
	else
	{
		if (MvhlD.PatchLoad.bPatchLoad)
		{
			return TRUE;
		}
		else
		{
			if (MvhlD.nLoadType == 0)
				return TRUE;
		}
	}

	return FALSE;
}

////////////// vehicle load for transverse moving load ////////////////
void CAttrCtrl::GetMvhltrList(CArray<CString, CString&>& rstrLoadList)
{
	rstrLoadList.RemoveAll();

	T_MVHLtr_D Data;
	CArray<T_MVHLtr_K, T_MVHLtr_K>KeyList;
	GetMvhltrKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetMvhltr(KeyList[i], Data))
			rstrLoadList.Add(Data.VehicleLoadName);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetMvhltrKeyList(CArray<T_MVHLtr_K, T_MVHLtr_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<CString, CString&>arLoadName;

	POSITION pos;
	T_MVHLtr_K Key;
	T_MVHLtr_D Data;
	pos=GetStartMvhltr();
	while(pos != NULL)
	{
		GetNextMvhltr(pos, Key, Data);
		rKeyList.Add(Key);
		arLoadName.Add(Data.VehicleLoadName);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortStringWithIndex(rKeyList.GetData(), arLoadName.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::ExistMvhltr(CString& rLoadName)
{
	T_MVHLtr_D data;
	return GetMvhltr(rLoadName, data);
}

BOOL CAttrCtrl::ExistMvhltr(T_MVHLtr_K Key)
{
	T_MVHLtr_D Data;
	return m_pDataMemb->m_pmvhltr->Get(Key,Data);
}

BOOL CAttrCtrl::GetMvhltr(CString& rLoadName, T_MVHLtr_D& rData)
{
	T_MVHLtr_K key;
	T_MVHLtr_D data;
	CString strLoadName=rLoadName;
	strLoadName.TrimRight();

	POSITION pos=m_pDataMemb->m_pmvhltr->GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_pmvhltr->GetNext(pos,key,data);
		if(strLoadName.CompareNoCase(data.VehicleLoadName) == 0)
		{
			m_pUnitCtrl->ConvertUnitMvhltrOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetMvhltr(T_MVHLtr_K Key,T_MVHLtr_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_pmvhltr->Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitMvhltrOut(rData);
	return bReturn;
}

T_MVHLtr_K CAttrCtrl::GetMvhltrKey(CString& rLoadName)
{
	T_MVHLtr_K key;
	T_MVHLtr_D data;

	POSITION pos=GetStartMvhltr();
	while(pos != NULL)
	{
		GetNextMvhltr(pos,key,data);
		if(rLoadName.CompareNoCase(data.VehicleLoadName) == 0)return key;
	}
	key=0;
	return key;
}

