	case D_MOVE_CODE_CHINA:
		m_pDoc->m_pAttrCtrl->GetMvldchList(rstrMvldList);
		break;
	case D_MOVE_CODE_INDIA:
		m_pDoc->m_pAttrCtrl->GetMvldidList(rstrMvldList);
