void CAttrCtrl::GetMvldListCommon(CArray<T_MVLD_K, T_MVLD_K>& KeyList, CArray<CString, CString&>& rstrMvldList)
{
	rstrMvldList.RemoveAll();

	T_MVCD_D MvcdD;
	if (!m_pDoc->m_pAttrCtrl->GetMvcd(MvcdD)) return;
	switch (MvcdD.nCodeType)
	{
	case D_MOVE_CODE_NONE:
		break;
	case D_MOVE_CODE_KOREA:
	case D_MOVE_CODE_AASHTO_STAN:
	case D_MOVE_CODE_AASHTO_LRFD:
	case D_MOVE_CODE_PENDOT:
	case D_MOVE_CODE_TAIWAN:
	case D_MOVE_CODE_CANADA:
	case D_MOVE_CODE_EURO_BS:
	case D_MOVE_CODE_RUSSIA:
	case D_MOVE_CODE_KOREA_LRFD_2011:
	case D_MOVE_CODE_AUSTRALIA:
	case D_MOVE_CODE_POLAND:
	case D_MOVE_CODE_SOUTH_AFRICA:
	case D_MOVE_CODE_JAPAN_RAIL:
	case D_MOVE_CODE_NEWZEALAND:
	case D_MOVE_CODE_BRAZIL:
	{
		T_MVLD_D MvldD;
		for (int i = 0; i < KeyList.GetSize(); i++)
		{
			if (!GetMvld(KeyList[i], MvldD)) continue;

			rstrMvldList.Add(MvldD.LoadCaseName);
		}
	}
	break;
	case D_MOVE_CODE_JAPAN:
	{
		T_MVLDjp_D MvldD;
		for (int i = 0; i < KeyList.GetSize(); i++)
		{
			if (!GetMvldjp(KeyList[i], MvldD)) continue;

			rstrMvldList.Add(MvldD.LoadCaseName);
		}
	}
	break;
	case D_MOVE_CODE_CHINA:
	{
		T_MVLDch_D MvldD;
		for (int i = 0; i < KeyList.GetSize(); i++)
		{
			if (!GetMvldch(KeyList[i], MvldD)) continue;

			rstrMvldList.Add(MvldD.LoadCaseName);
		}
	}
	break;
	case D_MOVE_CODE_INDIA:
	{
		T_MVLDid_D MvldD;
		for (int i = 0; i < KeyList.GetSize(); i++)
		{
			if (!GetMvldid(KeyList[i], MvldD)) continue;

			rstrMvldList.Add(MvldD.LoadCaseName);
		}
	}
	break;
	case D_MOVE_CODE_BS:
	{
		T_MVLDbs_D MvldD;
		for (int i = 0; i < KeyList.GetSize(); i++)
		{
			if (!GetMvldbs(KeyList[i], MvldD)) continue;

			rstrMvldList.Add(MvldD.LoadCaseName);
		}
	}
	break;
	case D_MOVE_CODE_FRANCE:
	{
		T_MVLDfr_D MvldD;
		for (int i = 0; i < KeyList.GetSize(); i++)
		{
			if (!GetMvldfr(KeyList[i], MvldD)) continue;

			rstrMvldList.Add(MvldD.LoadCaseName);
		}
	}
	break;
	case D_MOVE_CODE_TRANS:
	{
		T_MVLDtr_D MvldD;
		for (int i = 0; i < KeyList.GetSize(); i++)
		{
			if (!GetMvldtr(KeyList[i], MvldD)) continue;

			rstrMvldList.Add(MvldD.LoadCaseName);
		}
	}
	break;
	default:
		ASSERT(0);
		break;
	}
}

