void CAttrCtrl::GetMvldList(CArray<CString, CString&>& rstrMvldList)
{
	rstrMvldList.RemoveAll();

	int nCount=GetCountMvld();
	if(nCount == 0)return;

	POSITION pos;
	T_MVLD_K Key;
	T_MVLD_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartMvld();
		while(pos != NULL)
		{
			GetNextMvld(pos, Key, Data);
			if(Data.LoadCaseId == i)
			{
				rstrMvldList.Add(Data.LoadCaseName);
				break;
			}
		}
	}
}

