void CAttrCtrl::InitializeMvldjp(T_MVLDjp_D& rData)
{
	rData.LoadCaseName.Empty();
	rData.Description.Empty();
	rData.LoadCaseId = 0;
	rData.nLiveLoadType = 0;
	rData.bImpactCoeff = TRUE;
	rData.nBridgeType = 0;
	rData.nCoeffNumerator = 10;
	rData.nCoeffDenominator = 25;

	rData.LLoad.dSubMainRatio = 0.5;
	rData.LLoad.P1_dLength = 0.0;
	rData.LLoad.P1_nMethod = 0;
	rData.LLoad.P1_dUniformLoadMovement = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.P1_dUniformLoadMovement, 0.1);
	rData.LLoad.P1_dMomentCalcLoad = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.P1_dMomentCalcLoad, 10);
	rData.LLoad.P1_dShearCalcLoad = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.P1_dShearCalcLoad, 12);
	rData.LLoad.P2_dL1 = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.P2_dL1, 80);
	rData.LLoad.P2_dL2 = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.P2_dL2, 130);
	rData.LLoad.P2_dP2L1 = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.P2_dP2L1, 3.5);
	rData.LLoad.P2_dP2L1L2_1 = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.P2_dP2L1L2_1, 4.3);
	rData.LLoad.P2_dP2L1L2_2 = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.P2_dP2L1L2_2, 0.01);
	rData.LLoad.P2_dP2L2 = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.P2_dP2L2, 3.0);
	rData.LLoad.P2_dCrowdL1 = rData.LLoad.P2_dP2L1;
	rData.LLoad.P2_dCrowdL1L2_1 = rData.LLoad.P2_dP2L1L2_1;
	rData.LLoad.P2_dCrowdL1L2_2 = rData.LLoad.P2_dP2L1L2_2;
	rData.LLoad.P2_dCrowdL2 = rData.LLoad.P2_dP2L2;

	rData.MLoad.bLoading = FALSE;
	rData.MLoad.dMovingDistance = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.dMovingDistance, 1);
	rData.MLoad.dTotalLength = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.dTotalLength, 16);
	rData.MLoad.nLoadNum = 0;
	for (int i = 0; i < T_MVLDjp_NUM_MVLDjp_MLOAD; i++)
		rData.MLoad.Load[i].dLocation = rData.MLoad.Load[i].dLoadValue = 0.0;
	rData.MLoad.dSubMainRatio = 0.5;
	rData.MLoad.P2_dL1 = rData.LLoad.P2_dL1;
	rData.MLoad.P2_dL2 = rData.LLoad.P2_dL2;
	rData.MLoad.P2_dP2L1 = rData.LLoad.P2_dP2L1;
	rData.MLoad.P2_dP2L1L2_1 = rData.LLoad.P2_dP2L1L2_1;
	rData.MLoad.P2_dP2L1L2_2 = rData.LLoad.P2_dP2L1L2_2;
	rData.MLoad.P2_dP2L2 = rData.LLoad.P2_dP2L2;
	rData.MLoad.P2_dCrowdL1 = rData.LLoad.P2_dCrowdL1;
	rData.MLoad.P2_dCrowdL1L2_1 = rData.LLoad.P2_dCrowdL1L2_1;
	rData.MLoad.P2_dCrowdL1L2_2 = rData.LLoad.P2_dCrowdL1L2_2;
	rData.MLoad.P2_dCrowdL2 = rData.LLoad.P2_dCrowdL2;

	rData.TLoad.dLoadStiffness = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KN, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_MVLDjp_UNIT.dLoadStiffness, 200.0);
	rData.TLoad.bExtraCoeff = FALSE;
}

void CAttrCtrl::GetMvldjpList(CArray<CString, CString&>& rstrMvldList)
{
	rstrMvldList.RemoveAll();

	int nCount=GetCountMvldjp();
	if(nCount == 0)return;

	POSITION pos;
	T_MVLDjp_K Key;
	T_MVLDjp_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartMvldjp();
		while(pos != NULL)
		{
			GetNextMvldjp(pos, Key, Data);
			if(Data.LoadCaseId == i)
			{
				rstrMvldList.Add(Data.LoadCaseName);
				break;
			}
		}
	}
}

