BOOL CAttrCtrl::IsFatigueMvld(T_MVLDch_K Key)
{
	T_MVLDch_D Data; Data.Initialize();
	if(!GetMvldch(Key, Data)) return FALSE;

	return IsFatigueMvld(Data);
}

BOOL CAttrCtrl::IsFatigueMvld(T_MVLDch_D& Data)
{
	BOOL bFatigue = FALSE;

	T_MVHC_D MvhcD; MvhcD.Initialize();
	T_MVHL_D MvhlD; MvhlD.Initialize();

	if(Data.bAutoOptimize)
	{
		for(int i=0; i<Data.aOptimize.GetSize(); i++)
		{
			if(Data.aOptimize[i].nVehicleType == 1) // Vehicle Class 
			{
				if(!GetMvhc(Data.aOptimize[i].VehicleK, MvhcD)) continue;

				for(int j=0; j<MvhcD.arVehicleLoad.GetSize(); j++)
				{
					if(!GetMvhl(MvhcD.arVehicleLoad[j], MvhlD)) continue;

					if(MvhlD.VehicleTypeName == _T("CH-PL1") || 
						MvhlD.VehicleTypeName == _T("CH-PL2") || 
						MvhlD.VehicleTypeName == _T("CH-PL3"))
					{
						bFatigue = TRUE;
					}
				}		
			}
			else // Vehicle
			{
				if(!GetMvhl(Data.aOptimize[i].VehicleK, MvhlD)) continue;

				if(MvhlD.VehicleTypeName == _T("CH-PL1") || 
					MvhlD.VehicleTypeName == _T("CH-PL2") || 
					MvhlD.VehicleTypeName == _T("CH-PL3"))
				{
					bFatigue = TRUE;
				}			
			}
		}
	}
	else
	{
		for(int i=0; i<Data.arSubLoadData.GetSize(); i++)
		{
			if(Data.arSubLoadData[i].nVehicleType == 1) // Vehicle Class 
			{
				if(!GetMvhc(Data.arSubLoadData[i].VehicleKey, MvhcD)) continue;

				for(int j=0; j<MvhcD.arVehicleLoad.GetSize(); j++)
				{
					if(!GetMvhl(MvhcD.arVehicleLoad[j], MvhlD)) continue;

					if(MvhlD.VehicleTypeName == _T("CH-PL1") || 
						MvhlD.VehicleTypeName == _T("CH-PL2") || 
						MvhlD.VehicleTypeName == _T("CH-PL3"))
					{
						bFatigue = TRUE;
					}
				}		
			}
			else // Vehicle
			{
				if(!GetMvhl(Data.arSubLoadData[i].VehicleKey, MvhlD)) continue;

				if(MvhlD.VehicleTypeName == _T("CH-PL1") || 
					MvhlD.VehicleTypeName == _T("CH-PL2") || 
					MvhlD.VehicleTypeName == _T("CH-PL3"))
				{
					bFatigue = TRUE;
				}			
			}
		}
	}

	return bFatigue;
}

