int CAttrCtrl::GetNumEigv()
{
	T_EIGV_D Data;
	if(m_pDataMemb->m_eigv.Get(Data))return GetNumEigv(Data);
	return 0;
}

int CAttrCtrl::GetNumEigv(T_EIGV_D& rData)
{
	if(rData.nType == 0 || rData.nType == 2 || rData.nType == 3 || rData.nType == 4)
	{
		return rData.nNumMode;
	}
	else if(rData.nType == 1)
	{
		int nRitz=0;
		for(int i=0; i<D_EIGV_NUMLC; i++)
		{
			if(rData.Ritz.LC[i].LoadCaseKey == 0)break;
			nRitz+=rData.Ritz.LC[i].nCount;
		}
		if(rData.Ritz.bIncludeForceVectors)nRitz+=CalcEigvNlnkForceVectors()*rData.Ritz.nGenerationNum;
		return nRitz;
	}
	else
	{
		ASSERT(FALSE);
		return rData.nNumMode;
	}
}

int CAttrCtrl::CalcEigvNlnkForceVectors()
{
	int nCount=0;
	T_NLNK_K key;
	T_NLNK_D data;
	T_NLLP_D nllp;
	POSITION pos = GetStartNlnk();
	while (pos)
	{
		GetNextNlnk(pos, key, data);
		VERIFY(GetNllp(data.PropKey, nllp));
		for (int i = 0; i < 6; i++)
			if (nllp.NDP_cDir[i] == '1') nCount++;
	}
	return nCount;
}

