void CAttrCtrl::GetAtypList(CArray<CString, CString&>& rstrAtypList)
{
	rstrAtypList.RemoveAll();

	int nCount=GetCountAtyp();
	if(nCount == 0)return;

	POSITION pos;
	T_ATYP_K Key;
	T_ATYP_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartAtyp();
		while(pos != NULL)
		{
			GetNextAtyp(pos, Key, Data);
			if(Data.nSeq == i)
			{
				rstrAtypList.Add(Data.strName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetAtypKeyList(CArray<T_ATYP_K, T_ATYP_K>& rAtypKeyList)
{
	rAtypKeyList.RemoveAll();
	int nCount=GetCountAtyp();
	if(nCount == 0)return;

	CArray<T_ATYP_K, T_ATYP_K> aAtypKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rAtypKeyList.SetSize(nCount);
	aAtypKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_ATYP_K Key;
	T_ATYP_D Data;
	int i = 0;
	pos = GetStartAtyp();
	while (pos != NULL)
	{
		GetNextAtyp(pos, Key, Data);
		aAtypKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nSeq;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rAtypKeyList[i] = aAtypKey[ix];
	}
}

