// 그룹에 속하는 Element의 Bottom Node List를 Return.
BOOL CAttrCtrl::GetBottomNodeList(T_GRUP_K nGrupK, CArray<UINT,UINT>& aNode, CString& strMsg)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint(); 
	ASSERT(pDoc);

	if(nGrupK<=0)
	{
		ASSERT(0); return FALSE;
	}

	T_GRUP_D GrupD; GrupD.Initialize();
	if(!pDoc->m_pAttrCtrl->GetGrup(nGrupK, GrupD))
		return FALSE;

	return GetBottomNodeList(GrupD, aNode, strMsg);
}

// Return Value : aNode, strMsg
BOOL CAttrCtrl::GetBottomNodeList(T_GRUP_D& GrupD, CArray<UINT,UINT>& aNode, CString& strMsg)
{
	aNode.RemoveAll();
	strMsg = _T("");

	// 1. 그룹의 Element들을 수집한다.
	CArray<UINT,UINT> aElemK; aElemK.RemoveAll();
	aElemK.Copy(GrupD.arKeyElem);

	T_ELEM_K ElemK=0;
	T_ELEM_D ElemD; ElemD.Initialize();
	CArray<T_ELEM_K,T_ELEM_K> aWrongElemK; aWrongElemK.RemoveAll();

	int nElem = aElemK.GetSize();
	for(int i=nElem-1; i>=0; i--)
	{
		ElemK = aElemK[i];
		if(!GetElem(ElemK, ElemD))
		{
			aWrongElemK.Add(ElemK);
			aElemK.RemoveAt(i);
			continue;
		}

		// Element가 Frame type이 아닌 것은 에러처리.
		if(!IsFrameType(ElemD.eltyp))
		{
			aWrongElemK.Add(ElemK);
			aElemK.RemoveAt(i);
		}
	}

	// 2. 잘못된 Element들은 메세지 박스에 표시해준다.
	CString strErrElems=_T(""), strTmp=_T(""), strErr=_T("");
	int nWrong = aWrongElemK.GetSize();
	for(int i = 0; i<nWrong; i++)
	{
		if(i!=nWrong-1)
			strTmp.Format(_T("%d, "), aWrongElemK[i]);
		else
			strTmp.Format(_T("%d"), aWrongElemK[i]);
		strErrElems += strTmp;
	}
	if(strErrElems!=_T(""))
	{
		aNode.RemoveAll();
		strErr.Format(_LS(IDS_DB_DT_SBCT_INCORRECT_ELEM), strErrElems);
		strMsg = strErr;
		return FALSE;
	}


	// 3. Connected Element 그룹들을 수집한다. (Connected Element들이 있으면 그 중 z좌표가 제일 낮은 노드를 찾기 위해)
	const int NODENUM = 2;
	CArray<CArray<UINT, UINT>, CArray<UINT, UINT>&> aResult; // Final Result

	CMap<UINT, UINT, int, int> mapDone; // Already Done
	int nTmp=0;

	for(int i=0 ; i<aElemK.GetSize() ; ++i)
	{
		if(mapDone.Lookup(aElemK[i], nTmp)) continue;

		CArray<UINT, UINT> aCurResult; // Result (This Time)
		CMap<UINT, UINT, int, int> mapCurNodeK; // Temp NodeK Map for (This Time)

		UINT SeedElemK = aElemK[i];
		aCurResult.Add(SeedElemK); // 1) add
		mapDone.SetAt(SeedElemK, 1);

		T_ELEM_D ElemD; ElemD.Initialize();
		if(!GetElem(SeedElemK, ElemD)) continue;
		for(int j=0 ; j<NODENUM ; ++j)
			mapCurNodeK.SetAt(ElemD.elnod[j], 1); // 2) register node

		while(true)
		{
			int nAdded = 0;

			for(int j=0 ; j<aElemK.GetSize() ; ++j)
			{
				if(i==j) continue;
				if(mapDone.Lookup(aElemK[j], nTmp)) continue;
				if(!GetElem(aElemK[j], ElemD)) continue;

				BOOL bConnected = FALSE;
				// check if dupe node exist
				for(int k=0 ; k<NODENUM ; ++k)
				{
					if(mapCurNodeK.Lookup(ElemD.elnod[k], nTmp)) { bConnected=TRUE; break; }
				}
				if(bConnected)
				{
					aCurResult.Add(aElemK[j]); // 1) add
					mapDone.SetAt(aElemK[j], 1);
					for(int k=0 ; k<NODENUM ; ++k)
						mapCurNodeK.SetAt(ElemD.elnod[k], 1); // 2) register node

					nAdded++;
				}
			}

			if(nAdded==0) break;
		}

		if(aCurResult.GetSize() > 0)
		{
			int n = aResult.GetSize();
			aResult.SetSize(n+1);
			aResult[n].Copy(aCurResult);
		}
	}

	// 3. Connected Element들이 있으면 그 중 z좌표가 제일 낮은 노드(Bottom Node)를 찾는다.
	// find low node Key (from aResult(connected Elem Grup K)
	CArray<UINT, UINT> aFinalNodeK;
	for(int i=0 ; i<aResult.GetSize() ; ++i)
	{
		// 1) make node count map
		CArray<UINT, UINT> aCurGroup;
		aCurGroup.Copy(aResult[i]);
		CMap<UINT, UINT, int, int> mapNodeKCount;

		for(int j=0 ; j<aCurGroup.GetSize() ; ++j)
		{
			T_ELEM_D ElemD; ElemD.Initialize();
			if(!GetElem(aCurGroup[j], ElemD)) continue;
			for(int k=0 ; k<NODENUM ; ++k)
			{
				int nCount = 0;
				mapNodeKCount.Lookup(ElemD.elnod[k], nCount);
				mapNodeKCount.SetAt(ElemD.elnod[k], nCount+1);
			}

		}

		// 2) find end node
		CArray<UINT, UINT> aEndNodeK;
		POSITION pos = mapNodeKCount.GetStartPosition();
		while(pos)
		{
			int nCount;
			UINT NodeK;
			mapNodeKCount.GetNextAssoc(pos, NodeK, nCount);
			if(nCount == 1) aEndNodeK.Add(NodeK);
		}

		// 3) find lowest node
		UINT LowNodeK = 0;
		double dZ = 0.;
		if(aEndNodeK.GetSize() > 0)
		{
			for(int j=0 ; j<aEndNodeK.GetSize() ; ++j)
			{
				T_NODE_D NodeD; NodeD.Initialize();
				if(!GetNode(aEndNodeK[j], NodeD)) continue;
				if(j==0) { LowNodeK = aEndNodeK[j]; dZ = NodeD.z; }
				else
				{
					if(NodeD.z < dZ) { LowNodeK = aEndNodeK[j]; dZ = NodeD.z; }
				}
			}

		}

		// 4) add to result
		aFinalNodeK.Add(LowNodeK);
	}
	aNode.Copy(aFinalNodeK);

	// 4. 중복된 Node는 허용하지 않는다.
	CArray<UINT,UINT> aWrongNodeK; aWrongNodeK.RemoveAll();
	CArray<UINT,UINT> aNodeCopy;
	aNodeCopy.Copy(aNode);
	int nNum=0;
	int nNode = aNode.GetSize();
	for(int i = 0; i<nNode; i++)
	{
		nNum = 0;
		for(int k=0; k<aNodeCopy.GetSize(); k++)
		{
			if(aNode[i]==aNodeCopy[k])
			{
				++nNum;
				if(nNum>1)
				{
					aWrongNodeK.Add(aNode[i]);
					aNodeCopy.RemoveAt(k);
					k--;
				}
			}
		}
	}

	strErrElems=_T(""), strTmp=_T(""), strErr=_T("");
	nWrong=0;
	nWrong = aWrongNodeK.GetSize();
	for(int i = 0; i<nWrong; i++)
	{
		if(i!=nWrong-1)
			strTmp.Format(_T("%d, "), aWrongNodeK[i]);
		else
			strTmp.Format(_T("%d"), aWrongNodeK[i]);
		strErrElems += strTmp;
	}
	if(strErrElems!=_T(""))
	{
		aNode.RemoveAll();
		strErr.Format(_LS(IDS_DB_DT_SBCT_INCORRECT_NODE), strErrElems);
		strMsg = strErr;
		return FALSE;
	}

	// 5. Node List를 x좌표가 낮은 순으로 정렬한다.
	T_NODE_K NodeKI=0;
	T_NODE_D NodeDI; NodeDI.Initialize();;

	CArray<double,double> aXDisp; aXDisp.RemoveAll();
	nNode = aNode.GetSize();
	for(int i = 0; i<nNode; i++)
	{
		NodeKI = aNode[i];
		if(!GetNode(NodeKI, NodeDI)) continue;
		aXDisp.Add(NodeDI.x);
	}

	CArray<double,double> aXDispCopy;
	aXDispCopy.Copy(aXDisp);
	qsort((void*)aXDispCopy.GetData(), aXDispCopy.GetSize(), sizeof(double), CCompFunc::doubleAsc);

	int nXDisp = aXDisp.GetSize();
	ASSERT(nNode==nXDisp);

	CArray<int,int> aIndex;
	aIndex.RemoveAll();
	aIndex.SetSize(nNode);

	CMap<UINT,UINT,int,int> mIndex;
	nTmp=0;
	for(int i = 0; i<nXDisp; i++)
	{
		for(int k=0; k<nXDisp; k++)
		{
			if(aXDispCopy[i]==aXDisp[k] && !mIndex.Lookup(k, nTmp))
			{
				aIndex[i] = k;
				mIndex.SetAt(k, 1);
				break;
			}
		}
	}

	aNodeCopy.RemoveAll();
	aNodeCopy.Copy(aNode);
	int nIndex=0;

	for(int i = 0; i<nNode; i++)
	{
		nIndex = aIndex[i];
		aNode[i] = aNodeCopy[nIndex];
	}

	return TRUE;
}

// Return Value
// 0: rDisp를 변경하지 않음 (변경전 그룹과 동일한 데이터)
// 1: 변경함 (새 그룹에 해당하는 데이터로)
// 2: 새 그룹에 따른 데이터가 잘못된 데이터로 T_SBCT_DISP를 삭제해야 함.
// T_SBCT_DISP& rDisp : 변경될 Hanger Data
int CAttrCtrl::UpdateHangerData(T_SBCT_D& OldSbctD, T_GRUP_K GrupK, T_GRUP_D& NewGrupD, T_SBCT_DISP& rDisp)
{
	rDisp.Initialize();

	// 1. New Group Data로 인한 Bottom Node List를 찾는다.
	CArray<T_NODE_K,T_NODE_K> aNewNode; aNewNode.RemoveAll();
	BOOL bRet=FALSE;
	CString strErr=_T("");
	//bRet = GetBottomNodeList(NewGrupD, aNewNode, strErr);
	bRet = m_pDoc->m_pAttrCtrl2->GetNodeListByXorder(NewGrupD, aNewNode, strErr); // Hanger Group 추가, 20111201 KIMJM
	if(!bRet || aNewNode.GetSize() <= 0)
		return 2;

	// 2. 기존에 등록된 데이터와 중복된 Node 체크한다.
	T_SBCT_DISP OldDisp; OldDisp.Initialize();
	CArray<T_NODE_K,T_NODE_K> aResNode; aResNode.RemoveAll();
	int nCount = OldSbctD.aHangerZDisp.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(OldSbctD.aHangerZDisp[i].nGrupK==GrupK)
		{
			OldDisp = OldSbctD.aHangerZDisp[i];

			aResNode.RemoveAll();
			CArrayUtil::IntersectUINT(aNewNode, OldSbctD.aHangerZDisp[i].aNode, aResNode);

			if(aResNode.GetSize() > 0 && aResNode.GetSize()==aNewNode.GetSize() && aResNode.GetSize()==OldSbctD.aHangerZDisp[i].aNode.GetSize())
				return 0; // node list가 이전과 동일하면 변경하지 않음.
			else
				continue;
		}

		aResNode.RemoveAll();
		CArrayUtil::IntersectUINT(aNewNode, OldSbctD.aHangerZDisp[i].aNode, aResNode);

		if(aResNode.GetSize() > 0)
			return 2;
	}

	// 3. New Node에 매칭되는 ZDisp데이터를 세팅한다.
	CArray<double,double> aNewZDisp; aNewZDisp.RemoveAll();
	int nNode = aNewNode.GetSize();
	aNewZDisp.SetSize(nNode); 
	for(int i = 0; i<nNode; i++)
		aNewZDisp[i] = 0.0;

	int nOldNode = OldDisp.aNode.GetSize();
	for(int i = 0; i<nNode; i++)
	{
		for(int n=0; n<nOldNode; n++)
		{
			if(aNewNode[i] == OldDisp.aNode[n])
			{
				aNewZDisp[i] = OldDisp.aZDisp[n];
			}
		}
	}
	aNewNode.FreeExtra();
	aNewZDisp.FreeExtra();

	// 4. 변경된 T_SBCT_DISP를 구성한다.
	rDisp = OldDisp;
	rDisp.aNode.Copy(aNewNode);
	rDisp.aZDisp.Copy(aNewZDisp);

	return 1;
}

// Node의 벡터를 적용한 교축방향 거리를 return.
void CAttrCtrl::GetRealDispList(CArray<UINT,UINT>& aNode, double dVec[2], CArray<double,double>& aXDisp)
{
	aXDisp.RemoveAll();

	T_NODE_K NodeK=0;
	T_NODE_D NodeD; NodeD.Initialize();
	double dXDisp=0.;

	if(dVec[0]==0. && dVec[1]==0.)
	{
		dVec[0] = 1.0;
		dVec[1] = 0.0;
	}

	int nNode = aNode.GetSize();
	aXDisp.SetSize(nNode);

	for(int i=0; i<nNode; i++)
	{
		NodeK = aNode[i];
		if(!GetNode(NodeK, NodeD)) 
		{
			ASSERT(0); continue;
		}

		dXDisp = NodeD.x;
		dXDisp = (NodeD.x*dVec[0] + NodeD.y*dVec[1]) / sqrt(dVec[0]*dVec[0]+dVec[1]*dVec[1]);
		aXDisp[i] = dXDisp;
	}
}

