double CAttrCtrl::CalcIfgsInitForce(T_ELEM_K ElemK, const T_IFGS_D& crIfgsD)
{
	double dInitForce = crIfgsD.InitForce;
	if(crIfgsD.nDirection > 0)
	{
		double FrameLocalVector[3][3];
		m_pDoc->calcFrameLocalVector(ElemK, FrameLocalVector);
		if(fabs(FrameLocalVector[0][crIfgsD.nDirection-1]) > 1.e-5)
			dInitForce/=fabs(FrameLocalVector[0][crIfgsD.nDirection-1]);
		else
			dInitForce=0.;
	}
	return dInitForce;
}
