BOOL CAttrCtrl::GetEseqId(CArray<T_ELEM_K, T_ELEM_K>& arElemKey, CArray<int, int>& arEseqModel, CArray<int, int>& arEseqLoad)
{
	arEseqModel.RemoveAll();
	arEseqLoad.RemoveAll();
	T_ESEQ_D DataEseq;
	if(!GetEseq(DataEseq))return FALSE;
	int nStep=DataEseq.arEseq.GetSize();
	if(nStep == 0)return FALSE;

	CMap<T_ELEM_K, T_ELEM_K, T_STOR_K, T_STOR_K>mapStorKey;
	mapStorKey.InitHashTable(m_pDoc->GetHashSizeElem());

	CArray<T_STOR_K, T_STOR_K>arKeyStor;
	GetStorKeyList(arKeyStor);
	CArray<T_ELEM_K, T_ELEM_K>arKeyStorElem;
	for(int i=0; i<arKeyStor.GetSize(); i++)
	{
		// nSelectionType == 0   // 해당층과 층하부로 연결된 절점, 요소
		//                == 1   // 해당층과 층상부로 연결된 절점, 요소
		//                == 2   // 해당층과 층상부와 층하부로 연결된 모든 절점, 요소
		//                == 3   // 해당층과 층하부의 모든 절점, 요소
		//                == 4   // 해당층과 층상부의 모든 절점, 요소
		//                == 5   // 해당층만
		int nSelectionType = 1;
		GetKeyListStorUser(arKeyStor[i], nSelectionType, NULL, &arKeyStorElem);
		for(int j=0; j<arKeyStorElem.GetSize(); j++)
		{
			mapStorKey.SetAt(arKeyStorElem[j], arKeyStor[i]);
		}
	}
	for(int i = 0; i<arElemKey.GetSize(); i++)
	{
		T_ELEM_K KeyElem=arElemKey[i];
		T_ELEM_D DataElem;
		GetElem(KeyElem, DataElem);
		T_STOR_K KeyStor;
		int nStepLoad=0;
		int nStepModel=0;
		if(!mapStorKey.Lookup(KeyElem, KeyStor))KeyStor=0;
		if(KeyStor != 0)
		{
			int nMatl=DataElem.elmat;
			T_MATL_D DataMatl;
			if(!GetMatl(nMatl, DataMatl))DataMatl.Initialize();
			for(int j=DataEseq.arEseq.GetSize()-1; j>=0; j--)
			{
				if(DataEseq.arEseq[j].KeyStorLoad != 0 && KeyStor <= DataEseq.arEseq[j].KeyStorLoad)nStepLoad=j+1;
				for(int k=0; k<D_ESEQ_NUMESEQ; k++)
				{
					if(DataEseq.arEseq[j].EseqSel[k].nType == 0)break;
					if(DataEseq.arEseq[j].EseqSel[k].KeyStorModel != 0 && KeyStor <= DataEseq.arEseq[j].EseqSel[k].KeyStorModel)
					{
						if(DataEseq.arEseq[j].EseqSel[k].nType == 1)
						{
							if(DataEseq.arEseq[j].EseqSel[k].KeyMatl == 1)nStepModel=j+1;
							if(DataEseq.arEseq[j].EseqSel[k].KeyMatl == 2 && DataMatl.Type == _T("S"))nStepModel=j+1;
							if(DataEseq.arEseq[j].EseqSel[k].KeyMatl == 3 && DataMatl.Type == _T("C"))nStepModel=j+1;
							if(DataEseq.arEseq[j].EseqSel[k].KeyMatl == 4 && DataMatl.Type == _LS(IDS_DBLIB__ADDED__SRC))nStepModel=j+1;
							if(DataEseq.arEseq[j].EseqSel[k].KeyMatl == 5 && DataMatl.Type == _T("U"))nStepModel=j+1; //sjhuh-2013-09-30
							if(DataEseq.arEseq[j].EseqSel[k].KeyMatl == 5 && DataMatl.Type == _T("A"))nStepModel=j+1; 
						}
						else if(DataEseq.arEseq[j].EseqSel[k].nType == 2)
						{
							if(DataEseq.arEseq[j].EseqSel[k].KeyMatl == nMatl)nStepModel=j+1;
						}
					}
				}
			}
		}
		arEseqModel.Add(nStepModel);
		arEseqLoad.Add(nStepLoad);
	}
	return TRUE;
}

