void CAttrCtrl::CalcFlueTemp(T_FLUE_D& rData)
{
	if(rData.nType == 1)
		return;
	int n = int(rData.dTime * 60 / 5.0) + 1;
	rData.arFlueFunData.RemoveAll();
	rData.arFlueFunData.SetSize(n);
	double dPer = 0.0;
	rData.arFlueFunData[0].dblPeriod = 0.0;
	rData.arFlueFunData[0].dblValue = 0.0;
	if(rData.nSubType == 0)
	{
		for(int i = 1;i < n;i++)
		{
			dPer = (i+1) * 5.0;
			rData.arFlueFunData[i].dblPeriod = dPer;
			rData.arFlueFunData[i].dblValue = 20 + 345.0 * log10(8 / 60.0 * dPer  + 1);
		}
	}
	else
	{
		for(int i = 1;i < n;i++)
		{
			dPer = (i+1) * 5.0;
			rData.arFlueFunData[i].dblPeriod = dPer;
			rData.arFlueFunData[i].dblValue = 20. + 1080.0 * (1 - 0.325 * exp(-dPer/60.0/6) - 0.675 * exp(-2.5*dPer / 60.0));
		}
	}
}

double CAttrCtrl::GetFlueTemp(int nTime,T_FLUE_K FlueK)
{
	T_FLUE_D FlueD;
	if(!GetFlue(FlueK,FlueD) || FlueD.arFlueFunData.IsEmpty())
		return 20.0;
	const CArray<T_FLUE_BASE, T_FLUE_BASE&>& rdata = FlueD.arFlueFunData;
	int i = 0;
	for(;i < rdata.GetSize();i++)
	{
		if(rdata[i].dblPeriod == nTime)
			return rdata[i].dblValue;
		else if(rdata[i].dblPeriod > nTime)
		{
			if(i == 0)
				return 20.0;
			else
				break;
		}
	}
	if(i == rdata.GetSize())
		return rdata[i-1].dblValue;
	else
	{
		return rdata[i-1].dblValue + (nTime - rdata[i].dblPeriod)*(rdata[i].dblValue-rdata[i-1].dblValue)/(rdata[i].dblPeriod-rdata[i-1].dblPeriod);
	}
	return 20.0;
}

