void CAttrCtrl::MakeFssf(T_FSSF_K rKey,T_FSSF_D& FssfD)
{
	double ret = 0.0;
	if(FssfD.bAutoCalc)
	{
		FssfD.dFactor = CalcFssf(rKey,FssfD.nAutoType);
	}
}

double CAttrCtrl::CalcFssf(T_FSSF_K Key,int nType)
{
	T_ELEM_D ElemD;
	T_SECT_D sectD;
	VERIFY(m_pDoc->m_pAttrCtrl->GetElem(Key,ElemD));
	VERIFY(m_pDoc->m_pAttrCtrl->GetSectDesign(ElemD.elpro,sectD));
	m_pUnitCtrl->ConvertUnitSectIn(sectD);
	double dh,dt,dB1,dB2,dA,dr1,df1,df2;
	if(sectD.SectBefore.Shape == D_SECT_SHAPE_REG_C)
	{
		dh	= sectD.SectBefore.SectI.Size[0];
		dB1 = sectD.SectBefore.SectI.Size[1];
		dt	= sectD.SectBefore.SectI.Size[2];
		df1 = sectD.SectBefore.SectI.Size[3];
		dB2 = sectD.SectBefore.SectI.Size[4];
		if(dB2 < 1e-9)
			dB2 = dB1;
		df2 = sectD.SectBefore.SectI.Size[5];
		dA = sectD.SectBefore.SectI.Stiffness.Area;
		if(nType == 1 || nType == 5)
			return (2*(dB1 + dB2 + dh) - df1 - df2 - 2*dt)/dA;
		else if(nType == 2 || nType == 6)
			return (2*(dB2 + dh) + dB1 - df1 - df2 - 2*dt)/dA;
		else if(nType == 3)
			return (2*dB1 + 2*dh)/dA;
		else if(nType == 4)
			return (dB1 + 2*dh)/dA;
	}
	else if(sectD.SectBefore.Shape == D_SECT_SHAPE_REG_H)
	{
		dh = sectD.SectBefore.SectI.Size[0];
		dB1 = sectD.SectBefore.SectI.Size[1];
		dt = sectD.SectBefore.SectI.Size[2];
		dB2 = sectD.SectBefore.SectI.Size[4];
		if(dB2 < 1e-9)
			dB2 = dB1;
		dr1 = sectD.SectBefore.SectI.Size[6];
		dA = sectD.SectBefore.SectI.Stiffness.Area;

		if(nType == 2 || nType == 6)
			return (2*(dB2 + dh - dt) + dB1 + (PI - 8)*dr1)/dA;
		if(nType == 1 || nType == 5)
			return (2*(dB2 + dB1 + dh - dt) + (PI - 8)*dr1)/dA;
		else if(nType == 3)
			return 2*(dB1 + dh)/dA;
		else if(nType == 4)
			return (dB1 + 2*dh)/dA;
	}
	else if(sectD.SectBefore.Shape == D_SECT_SHAPE_REG_B || sectD.SectBefore.Shape == D_SECT_SHAPE_REG_SB
		|| sectD.SectBefore.Shape == D_SECT_SHAPE_REG_T || sectD.SectBefore.Shape == D_SECT_SHAPE_REG_L)
	{
		dh = sectD.SectBefore.SectI.Size[0];
		dB1 = sectD.SectBefore.SectI.Size[1];
		dA = sectD.SectBefore.SectI.Stiffness.Area;
		if(nType == 1 || nType == 3 || nType == 5)
			return 2*(dB1 + dh)/dA;
		else if(nType == 2 || nType == 4 || nType == 6)
			return (dB1 + 2*dh)/dA;
	}
	else if(sectD.SectBefore.Shape == D_SECT_SHAPE_REG_2C || sectD.SectBefore.Shape == D_SECT_SHAPE_REG_2L)
	{
		dh = sectD.SectBefore.SectI.Size[0];
		dB1 = sectD.SectBefore.SectI.Size[1];
		dB2 = sectD.SectBefore.SectI.Size[4];
		if(dB2 < 1e-9)
			dB2 = dB1;
		dA = sectD.SectBefore.SectI.Stiffness.Area;
		if(nType == 1 || nType == 5)
			return 2*(2*dB1 + dh)/dA;
		else if(nType == 2 || nType == 6)
			return 2*(dB1 + dh)/dA;
		else if(nType == 3)
			return (2*dB1 + 2*dB2 + 2*dh)/dA;
		else if(nType == 4)
			return (2*dB1 + 2*dB2 + 2*dh)/dA;
	}
	else if(sectD.SectBefore.Shape == D_SECT_SHAPE_REG_P || sectD.SectBefore.Shape == D_SECT_SHAPE_REG_SR)
	{
		dB1 = sectD.SectBefore.SectI.Size[0];
		dA = sectD.SectBefore.SectI.Stiffness.Area;
		if(nType == 1 || nType == 5)
			return dB1 * PI / dA;
		else if(nType == 2 || nType == 6)
			return 0.75 * dB1 * PI / dA;
		else if(nType == 3)
			return 4 * dB1 / dA;
		else if(nType == 4)
			return  3 * dB1 / dA;
	}
	//ASSERT(FALSE);
	return 1.0;
}

