void CAttrCtrl::GetSpfcList(CArray<CString, CString&>& rstrSpfcList)
{
	rstrSpfcList.RemoveAll();

	int nCount=GetCountSpfc();
	if(nCount == 0)return;

	POSITION pos;
	T_SPFC_K Key;
	T_SPFC_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartSpfc();
		while(pos != NULL)
		{
			GetNextSpfc(pos, Key, Data);
			if(Data.nSpecFuncId == i)
			{
				rstrSpfcList.Add(Data.SpecFuncName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetSpfcKeyList(CArray<T_SPFC_K, T_SPFC_K>& rSpfcKeyList)
{
	/*
	rKeyList.RemoveAll();

	int nCount=GetCountSpfc();
	if(nCount == 0)return;

	POSITION pos;
	T_SPFC_K Key;
	T_SPFC_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartSpfc();
	while(pos != NULL)
	{
	GetNextSpfc(pos, Key, Data);
	if(Data.nSpecFuncId == i)
	{
	rKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rSpfcKeyList.RemoveAll();
	int nCount=GetCountSpfc();
	if(nCount == 0)return;

	CArray<T_SPFC_K, T_SPFC_K> aSpfcKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rSpfcKeyList.SetSize(nCount);
	aSpfcKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_SPFC_K Key;
	T_SPFC_D Data;
	int i = 0;
	pos = GetStartSpfc();
	while (pos != NULL)
	{
		GetNextSpfc(pos, Key, Data);
		aSpfcKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nSpecFuncId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rSpfcKeyList[i] = aSpfcKey[ix];
	}
}

