BOOL CAttrCtrl::GetSpfc(CString& rSpecFuncName, T_SPFC_D& rData)
{
	T_SPFC_K key;
	T_SPFC_D data;
	CString strSpecFuncName=rSpecFuncName;
	strSpecFuncName.TrimRight();

	POSITION pos=m_pDataMemb->m_spfc.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_spfc.GetNext(pos,key,data);
		if(strSpecFuncName.CompareNoCase(data.SpecFuncName) == 0)
		{
			m_pUnitCtrl->ConvertUnitSpfcOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetSpfc(T_SPFC_K Key, T_SPFC_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_spfc.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitSpfcOut(rData);
	return bReturn;
}

T_SPFC_K CAttrCtrl::GetSpfcKey(CString& rSpecFuncName)
{
	T_SPFC_K key;
	T_SPFC_D data;

	POSITION pos=GetStartSpfc();
	while(pos != NULL)
	{
		GetNextSpfc(pos,key,data);
		if(rSpecFuncName.CompareNoCase(data.SpecFuncName) == 0)return key;
	}
	key=0;
	return key;
}

