void CAttrCtrl::GetThisList(CArray<CString, CString&>& rstrThisList)
{
	rstrThisList.RemoveAll();

	int nCount=GetCountThis();
	if(nCount == 0)return;

	POSITION pos;
	T_THIS_K Key;
	T_THIS_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartThis();
		while(pos != NULL)
		{
			GetNextThis(pos, Key, Data);
			if(Data.LoadCaseId == i)
			{
				rstrThisList.Add(Data.LoadCaseName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetThisKeyList(CArray<T_THIS_K, T_THIS_K>& rThisKeyList, BOOL bNeedThgcInitLoad/*=TRUE*/)
{
	/*
	rThisKeyList.RemoveAll();

	int nCount=GetCountThis();
	if(nCount == 0)return;

	POSITION pos;
	T_THIS_K Key;
	T_THIS_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartThis();
	while(pos != NULL)
	{
	GetNextThis(pos, Key, Data);
	if(Data.LoadCaseId == i)
	{
	rThisKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rThisKeyList.RemoveAll();
	int nCount=GetCountThis();
	if(nCount == 0)return;

	CArray<T_THIS_K, T_THIS_K> aThisKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rThisKeyList.SetSize(nCount);
	aThisKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_THIS_K Key;
	T_THIS_D Data;
	int i = 0;
	pos = GetStartThis();
	while (pos != NULL)
	{
		GetNextThis(pos, Key, Data);
		aThisKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.LoadCaseId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rThisKeyList[i] = aThisKey[ix];
	}

	if(CTestEnvMgr::GetTestEnvST(_LSX(ShowThgcInitLoad)) == _LSX(yes))
		bNeedThgcInitLoad=TRUE;

	T_THGC_D ThgcD;
	m_pDoc->m_pAttrCtrl2->GetThgc(ThgcD);
	if(!bNeedThgcInitLoad && m_pDoc->m_pAttrCtrl2->HasThgcDummyInitLoad() && ExistThis(ThgcD.ThisK_DummyInitLoad))
	{
		for (int i=rThisKeyList.GetSize()-1; i>=0; i--)
		{
			if(rThisKeyList[i]==ThgcD.ThisK_DummyInitLoad)
				rThisKeyList.RemoveAt(i);
		}
	}
}

int CAttrCtrl::GetTimeStep(T_THIS_K Key, CArray<double, double>& rarTimeStep)
{
	rarTimeStep.RemoveAll();
	T_THIS_D Data;
	if(GetThis(Key, Data))
	{
		if(Data.dEndTime == 0. || Data.dDelta == 0. || Data.nOut == 0)
		{
			ASSERT(FALSE);
			return 0;
		}

		double dEndTime = Data.dEndTime;
		if(Data.nAnalMethod == 3) dEndTime = double(Data.nIncrementStep);  // Static
		double dTemp = (dEndTime/Data.dDelta)+1.E-05; // solver와 동일한 계산방법 사용, MQC1646-JHKIM-20080226
		int nNt = (int)dTemp;
		int nStep=nNt/Data.nOut;
		for(int i=1; i<=nStep; i++)
		{
			double timestep=i*Data.dDelta*Data.nOut;
			rarTimeStep.Add(timestep);
		}
	}
	return rarTimeStep.GetSize();
}

