BOOL CAttrCtrl::GetThis(CString& rLoadCaseName, T_THIS_D& rData)
{
	T_THIS_K key;
	T_THIS_D data;
	CString strLoadCaseName=rLoadCaseName;
	strLoadCaseName.TrimRight();

	POSITION pos=m_pDataMemb->m_this.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_this.GetNext(pos,key,data);
		if(strLoadCaseName.CompareNoCase(data.LoadCaseName) == 0)
		{
			m_pUnitCtrl->ConvertUnitThisOut(data);
			rData=data;
			return TRUE;
		}
	}
#ifdef _MEC
	T_THIS_K DummyInitThisKey = m_pDoc->GetDummyInitThisKey(rLoadCaseName);
	if (DummyInitThisKey > 0)
	{
		return m_pDoc->GetDummyInitThisByDummyKey(DummyInitThisKey, rData);
	}
#endif
	return FALSE;
}

BOOL CAttrCtrl::GetThis(T_THIS_K Key, T_THIS_D& rData)
{
#ifdef _MEC
	if (m_pDoc->IsDummyInitLoadThis(Key))
	{
		return m_pDoc->GetDummyInitThisByDummyKey(Key, rData);
	}
#else
	T_THGC_D ThgcD;
	m_pDoc->m_pAttrCtrl2->GetThgc(ThgcD);
	if(m_pDoc->m_pAttrCtrl2->HasThgcDummyInitLoad() && Key==ThgcD.ThisK_DummyInitLoad)
		return GetThgcInitLoadThis(rData);
#endif
	BOOL bReturn=m_pDataMemb->m_this.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitThisOut(rData);
	return bReturn;
}

T_THIS_K CAttrCtrl::GetThisKey(CString& rLoadCaseName)
{
	T_THIS_K key;
	T_THIS_D data;

	POSITION pos=GetStartThis();
	while(pos != NULL)
	{
		GetNextThis(pos,key,data);
		if(rLoadCaseName.CompareNoCase(data.LoadCaseName) == 0)return key;
	}
#ifdef _MEC
	return m_pDoc->GetDummyInitThisKey(rLoadCaseName);
#endif
	key=0;
	return key;
}

