CString CAttrCtrl::GetErrorStrForThisSubsequent(T_THIS_D& rData, BOOL bSkipSubSeq/* = FALSE*/)
{
	CString strError;
	BOOL bSubSeq = FALSE;
	if (rData.nInitLoadMethod == D_THIS_INITMETHOD_ORDER_IN_SEQLOAD && rData.nInitCondition == 1)  // Subsequent to인 경우
		bSubSeq = TRUE;

	if (!bSubSeq) return strError;

	if (rData.nSubsequentType < 0 || rData.nSubsequentType > 3) return _LS(IDS_CMD_THIS_SUBSEQUENT_TYPE); // msg
	if (rData.nGeomNonlinearType == 0 && rData.nSubsequentType == 2) return _LS(IDS_CMD_THIS_SUBSEQUENT_TYPE);
	if (rData.nGeomNonlinearType >= 1 && rData.nSubsequentType == 1) return _LS(IDS_CMD_THIS_SUBSEQUENT_TYPE);
	if (rData.nSubsequentType == 0) // Load Case
	{
		if (rData.nSubLoadCaseType == 0)  // static load case
		{
			T_STLD_D DataStld;
			if (!m_pDoc->m_pAttrCtrl->GetStld(rData.KeyFinalState, DataStld)) return _LS(IDS_DB_FINAL_STATE);
			DataStld.LoadCaseType.MakeUpper();
			if (DataStld.LoadCaseType == _T("CS") || DataStld.LoadCaseType == _T("TCS")) return _LS(IDS_CMD_THIS_LOAD_CASE_TYPE);
		}
		else if (rData.nSubLoadCaseType == 1)   // construction stage load case
		{
			if (!(rData.KeyFinalState == 1 || rData.KeyFinalState == 2)) return _LS(IDS_CMD_THIS_LOAD_CASE_TYPE);
		}
		else if (rData.nSubLoadCaseType == 2)  // Time History Load Case
		{
			T_THIS_D DataFinalState;    // Final State of Previous Load Case
			DataFinalState.Initialize();
			if (!m_pDoc->m_pAttrCtrl->GetThis(rData.KeyFinalState, DataFinalState)) return _LS(IDS_DB_FINAL_STATE);
			if (DataFinalState.LoadCaseId >= rData.LoadCaseId)   return _LS(IDS_DB_FINAL_STATE);
			if (rData.nAnalType != DataFinalState.nAnalType)
			{
				strError.Format(_LS(IDS_DB_ANAL_TYPE_MISMATCH), rData.LoadCaseName, DataFinalState.LoadCaseName);
				return strError;   // 시간이력해석 데이터(이름 : %s)와 이의 Initial Condition 데이터(이름 : %s)의 Analysis Type이 일치하지 않습니다.
			}
			if ((rData.nAnalMethod == 1 && (DataFinalState.nAnalMethod == 2 || DataFinalState.nAnalMethod == 3)) ||
				((rData.nAnalMethod == 2 || rData.nAnalMethod == 3) && DataFinalState.nAnalMethod == 1))
			{
				strError.Format(_LS(IDS_DB_ANAL_METHOD_MISMATCH), rData.LoadCaseName, DataFinalState.LoadCaseName);
				return strError; // 시간이력해석 데이터(이름 : %s)와 이의 Initial Condition 데이터(이름 : %s)의 Analysis Method가 일치하지 않습니다.
			}
			BOOL bSubSeqTable = (DataFinalState.nSubsequentType == 1 && !bSkipSubSeq) ? TRUE : FALSE;
			if (DataFinalState.nInitLoadMethod == D_THIS_INITMETHOD_ORDER_IN_SEQLOAD &&
				 DataFinalState.nInitCondition == 1 &&  // Subsequent to
				(DataFinalState.nSubsequentType == 0  || bSubSeqTable) && //nSubsequentType : 0=Load case  1=Initial Element force(Table)
				(DataFinalState.nSubLoadCaseType == 0 || DataFinalState.nSubLoadCaseType == 1))
			{ // 시간이력해석 데이터(이름 : %s)의 Initial Condition 데이터(이름 : %s)는 정적하중 또는 시공단계 하중조건이 될 수 없습니다.
				#if defined(_US) || defined(_RUS)
					strError.Format(_LS(IDS_DB_THIS_SUBLOAD_MISMATCH), DataFinalState.LoadCaseName, rData.LoadCaseName);
				#else
					strError.Format(_LS(IDS_DB_THIS_SUBLOAD_MISMATCH), rData.LoadCaseName, DataFinalState.LoadCaseName);
				#endif
				return strError;
			}
			else if (DataFinalState.nInitLoadMethod == D_THIS_INITMETHOD_INITIALLOAD &&  DataFinalState.bUseInitial &&  // Initial Load Global && Use Initial Load
				    !bSkipSubSeq)  
			{
				T_THGC_D ThgcD;
				if(!m_pDoc->m_pAttrCtrl2->GetThgc(ThgcD)) ASSERT(0);

				if (ThgcD.nInitLoadMethod == 1 && ThgcD.aInitLoad.GetSize() > 0) // 1:Import Static Analysis
				{
					for (int nL = 0; nL < ThgcD.aInitLoad.GetSize(); nL++)
					{
						T_STLD_D DataStld;
						if (!m_pDoc->m_pAttrCtrl->GetStld(ThgcD.aInitLoad[nL].LoadCaseKey, DataStld)) return _LS(IDS_DB_FINAL_STATE);

					#if defined(_US) || defined(_RUS)
						strError.Format(_LS(IDS_DB_THIS_SUBLOAD_MISMATCH), DataStld.LoadCaseName, rData.LoadCaseName);
					#else
						strError.Format(_LS(IDS_DB_THIS_SUBLOAD_MISMATCH), rData.LoadCaseName, DataStld.LoadCaseName);
					#endif
						return strError;
					}
				}
			}
		}
		else return _LS(IDS_CMD_THIS_LOAD_CASE_TYPE);  // msg
	}
	else if (rData.nSubsequentType == 3) 
	{ // Grid Model 
		T_GILC_D GilcData;
		for (int j = 0; j < rData.aGilcCase.GetSize(); j++)
		{
			if (!m_pDoc->m_pAttrCtrl->GetGilc(rData.aGilcCase[j], GilcData))
				return _LS(IDS_DB_STCT_GILC_KEY);
			if (GilcData.nLoadCaseType != D_GILC_TYPE_DEAD && GilcData.nLoadCaseType != D_GILC_TYPE_DEADOTHR)
				return _LS(IDS_DB_STCT_GILC_KEY);
		}
	}
	return strError;
}

void CAttrCtrl::ConvertThis_IntegParam_BounaryNL(T_THIS_D& rData)
{

	if (rData.nAnalMethod == D_THIS_ANALMETHOD_DIRECT)
	{
		rData.nTimeIntegrationParam = 1; // Newmark-beta
	}
	else  // (rData.nAnalMethod == D_THIS_ANALMETHOD_MODAL || rData.nAnalMethod == D_THIS_ANALMETHOD_STATIC)
	{
		//Do nothing, already initialized
		//rData.nTimeIntegrationParam = 0; // HHT-alpha, but not used in the solver for this method
	}

	rData.BoundaryNL.nMaxIterNum = rData.BoundaryNL_Old.nMaxIterNum;

	if (rData.BoundaryNL_Old.nDampingMatrixUpdate == 0) rData.BoundaryNL.nDampingMatrixUpdate = 0; // no update
	else                                                rData.BoundaryNL.nDampingMatrixUpdate = 2; // update every step & iteration

	rData.BoundaryNL.bDispNorm = rData.BoundaryNL_Old.bDispNorm;
	rData.BoundaryNL.bForceNorm = rData.BoundaryNL_Old.bForceNorm;
	rData.BoundaryNL.bEnergyNorm = rData.BoundaryNL_Old.bEnergyNorm;
	rData.BoundaryNL.dDispNorm = rData.BoundaryNL_Old.dDispNorm;
	rData.BoundaryNL.dForceNorm = rData.BoundaryNL_Old.dForceNorm;
	rData.BoundaryNL.dEnergyNorm = rData.BoundaryNL_Old.dEnergyNorm;

	rData.BoundaryNL.bPerformIteration = rData.BoundaryNL_Old.bPerformIteration;
	rData.BoundaryNL.bPermitConvergence = rData.BoundaryNL_Old.bPermitConvergence;
	rData.BoundaryNL.bEnableLineSearch = rData.BoundaryNL_Old.bUseLineSearch;
	rData.BoundaryNL.nNumSearch = rData.BoundaryNL_Old.nNumSearch;
	rData.BoundaryNL.nMaxLineSearch = 10;
	rData.BoundaryNL.dLineSearchTol = 0.05;
	rData.BoundaryNL.nLineSearchOption = NTIS_BOUNDARY::UserDefined;

	rData.BoundaryNL.nStiffUpdateScheme = 1;
	rData.BoundaryNL.nIterStiffUpdate = 1;

	rData.BoundaryNL.nMaxBisectLevel = 0;

	if (rData.BoundaryNL_Old.nRungeKuttaMethod == 0 || rData.BoundaryNL_Old.nRungeKuttaMethod == 1)
	{
		rData.BoundaryNL.nRungeKuttaMethod = rData.BoundaryNL_Old.nRungeKuttaMethod;
	}

	if (rData.nAnalType == D_THIS_ANALTYPE_NONLINEAR && rData.nAnalMethod == D_THIS_ANALMETHOD_STATIC)
	{
		if (rData.BoundaryNL_Old.nMaxNumSubStep > 0)
		{
			rData.BoundaryNL.nMaxBisectLevel = math_lib::round_up(log10(1.0 / rData.BoundaryNL_Old.nMaxNumSubStep) / log10(0.5));
		}
	}
	else
	{
		if (rData.BoundaryNL_Old.dMinSubStepSize > 0)
		{
			rData.BoundaryNL.nMaxBisectLevel = math_lib::round_up(log10(1.0 / (rData.dDelta / rData.BoundaryNL_Old.dMinSubStepSize)) / log10(0.5));
		}
	}

	if (rData.BoundaryNL.nMaxBisectLevel < 0) rData.BoundaryNL.nMaxBisectLevel = 0;
	if (rData.BoundaryNL.nMaxBisectLevel > 20) rData.BoundaryNL.nMaxBisectLevel = 20;
	rData.BoundaryNL.bSmartBisection = FALSE;

	rData.BoundaryNL.nDiverThreshold = 3;
}

