BOOL CAttrCtrl::GetThfc(CString& rThisFuncName, T_THFC_D& rData)
{
	T_THFC_K key;
	T_THFC_D data;
	CString strThisFuncName=rThisFuncName;
	strThisFuncName.TrimRight();

	POSITION pos=m_pDataMemb->m_thfc.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_thfc.GetNext(pos,key,data);
		if(strThisFuncName.CompareNoCase(data.ThisFuncName) == 0)
		{
			m_pUnitCtrl->ConvertUnitThfcOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

