T_THFC_K CAttrCtrl::GetThfcKey(CString& rThisFuncName)
{
	T_THFC_K key;
	T_THFC_D data;

	POSITION pos=GetStartThfc();
	while(pos != NULL)
	{
		GetNextThfc(pos,key,data);
		if(rThisFuncName.CompareNoCase(data.ThisFuncName) == 0)return key;
	}
	key=0;
	return key;
}

