BOOL CAttrCtrl::GetSerialThms(T_NODE_K KeyNode,T_THIS_K KeyThis,T_THMS_KEY& rKeySerial)
{
	NodeList* pList;
	if(!m_pDataMemb->m_node.GetList(KeyNode, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_THMS_CMD)
		{
			T_THMS_K key;
			T_THMS_D data;
			key.keymap=ListData.nKey;
			GetThms(key, data);
			if(data.ThisKey == KeyThis)
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_THMS_K key;
	T_THMS_D data;
	key.key.entity=KeyNode;
	int j=0;
	while(TRUE)
	{
		j++;
		key.key.serial=j;
		if(!m_pDataMemb->m_thms.Get(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeKeyThms(T_NODE_K KeyNode, T_THIS_K KeyThis, T_THMS_K& rKey)
{
	rKey.key.entity=KeyNode;
	rKey.key.serial=0;

	T_THMS_KEY KeySerial;
	if(!GetSerialThms(KeyNode, KeyThis, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;

	return TRUE;
}

