{
	T_THMS_D Data;
	return m_pDataMemb->m_thms.Get(Key,Data);
}

void CAttrCtrl::GetThmsKeyList(CArray<T_THMS_K, T_THMS_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_THMS_K Key;
	T_THMS_D Data;
	pos = GetStartThms();
	while (pos != NULL)
	{
		GetNextThms(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if (rKeyList.GetSize() > 0)CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());

}

BOOL CAttrCtrl::GetThms(T_THMS_K Key,T_THMS_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_thms.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitThmsOut(rData);
	return bReturn;
}

void CAttrCtrl::GetThms(T_NODE_K KeyNode, CArray<T_THMS_K, T_THMS_K>& rarKey, CArray<T_THMS_D, T_THMS_D&>& rarData)
{
	rarKey.RemoveAll();
	rarData.RemoveAll();

	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_THMS_CMD)
		{
			T_THMS_K key;
			T_THMS_D data;
			key.keymap=ListData.nKey;
			GetThms(key, data);
			rarKey.Add(key);
			rarData.Add(data);
		}
	}
}

void CAttrCtrl::GetThmsLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, T_NODE_K KeyNode, CArray<T_THMS_D, T_THMS_D&>& rarData)
{
	rarData.RemoveAll();
	if(!CheckLcomLabelThis(bAllLoadCase, DataLcom))return;

	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_THMS_CMD)
		{
			T_THMS_K key;
			T_THMS_D data;
			key.keymap=ListData.nKey;
			GetThms(key, data);
			if(bAllLoadCase)
			{
				rarData.Add(data);
			}
			else
			{
				double dThisFactor=0.;
				if(!GetLcomThisFactor(data.ThisKey, DataLcom, dThisFactor))return;
				if(dThisFactor != 0.)
				{
					rarData.Add(data);
				}
			}
		}
	}
	return;
}

