BOOL CAttrCtrl::GetThrd(CString& rName, T_THRD_D& rData)
{
	T_THRD_K key;
	T_THRD_D data;
	CString strName=rName;
	strName.TrimRight();

	POSITION pos=m_pDataMemb->m_thrd.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_thrd.GetNext(pos,key,data);
		if(strName.CompareNoCase(data.Name) == 0)
		{
			m_pUnitCtrl->ConvertUnitThrdOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

