T_THRD_K CAttrCtrl::GetNextNumThrd(T_THRD_K StartNum)
{
	if(StartNum > GetLastNumThrd())return StartNum;
	T_THRD_K Key=StartNum;
	T_THRD_D Data;
	while(TRUE)
	{
		Key++;
		if(!m_pDataMemb->m_thrd.Get(Key,Data))return Key;
	}
}

////////////// grdp ////////////////

BOOL CAttrCtrl::ExistGrdp()
{
	T_GRDP_D Data;
	return m_pDataMemb->m_grdp.Get(Data);
}

BOOL CAttrCtrl::GetGrdp(T_GRDP_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_grdp.Get(rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitGrdpOut(rData);

	if(!rData.bMassPropDefault)   rData.dMassCoefDefault = 0.;
	if(!rData.bStiffPropDefault)   rData.dStifCoefDefault = 0.;

	// Material이 변경 되었을 수도 있어서 값을 다시 채워준다.
	if(bReturn && rData.bExistElement)
	{
		int nGrdpBase = rData.aGrupDamping.GetSize();
		for(int i = 0; i < nGrdpBase; i++)
		{
			T_GRDP_BASE& GrdpBase = rData.aGrupDamping[i];
			if(GrdpBase.nGrupType == 2 && GrdpBase.nDirectCalc == 1 && GrdpBase.nDampInputType == 0)
			{
				T_MATL_D MatlD;
				if(!GetMatl(GrdpBase.GrupBngrKey, MatlD))     {  ASSERT(0);		continue ;	}
				GrdpBase.dDampingRatio = GrdpBase.dDampingRatio2 = MatlD.dDampingRatio;

				T_THIS_D ThisD;     ThisD.Initialize();
				ThisD.PropDamping.nFreqPeriod = GrdpBase.nFreqPeriod + 1;
				ThisD.PropDamping.bMassProp   = GrdpBase.bMassProp;
				ThisD.PropDamping.bStiffProp  = GrdpBase.bStiffProp;
				ThisD.PropDamping.dFreqOne    = GrdpBase.dFreqOne;
				ThisD.PropDamping.dFreqTwo    = GrdpBase.dFreqTwo;
				ThisD.PropDamping.dPeriodOne  = GrdpBase.dPeriodOne;
				ThisD.PropDamping.dPeriodTwo  = GrdpBase.dPeriodTwo;
				ThisD.PropDamping.dDampingOne = GrdpBase.dDampingRatio;
				ThisD.PropDamping.dDampingTwo = GrdpBase.dDampingRatio2;

				if(!m_pDoc->m_pEditData->AutoCalcThisCoef(ThisD.PropDamping, ThisD.PropDamping.dRm, ThisD.PropDamping.dRk))    ThisD.PropDamping.Initialize();
				GrdpBase.dMassCoef = ThisD.PropDamping.dRm;
				GrdpBase.dStifCoef = ThisD.PropDamping.dRk;
			}
		}
	}
	if(bReturn && rData.bExistStrain)
	{
		int nGrdpBase = rData.aStrainGrupDamping.GetSize();
		for(int i = 0; i < nGrdpBase; i++)
		{
			T_GRDP_BASE& GrdpBase = rData.aStrainGrupDamping[i];
			if(GrdpBase.nGrupType == 2 && GrdpBase.nDampInputType == 0)
			{
				T_MATL_D MatlD;
				if(!GetMatl(GrdpBase.GrupBngrKey, MatlD))     {  ASSERT(0);		continue ;	}
				GrdpBase.dDampingRatio = MatlD.dDampingRatio;
			}
		}
	}
	return bReturn;
}

