BOOL CAttrCtrl::MakeInmfData(T_ELEM_K Key, double dInitForce, T_INMF_D& rInmfD)
{
	T_ELEM_D ElemD;
	rInmfD.Initialize();
	VERIFY(m_pDoc->m_pAttrCtrl->GetElem(Key, ElemD));
	if (IsTruss(ElemD.eltyp)) rInmfD.nType = 1;
	else if (IsBeam(ElemD.eltyp)) rInmfD.nType = 2;
	else { ASSERT(0); return FALSE; }
	rInmfD.ElemKey = Key;
	rInmfD.dElemForce[0][0] = dInitForce;
	rInmfD.dElemForce[1][0] = dInitForce;
	return TRUE;
}

