////////////// sclm ////////////////
void CAttrCtrl::InitializeSclm(T_SCLM_D& rData)
{
	rData.csName.Empty();
	rData.dX = rData.dY = 0.0;
	rData.dTol = m_pDoc->m_pFlagCtrl->GetGeneralCoordinateToleranceCurrentUnit();
	rData.nDispType = 0;
	rData.nConstStage = 0;
}

BOOL CAttrCtrl::GetSclmNodeList(CString& rName, CArray<T_NODE_K, T_NODE_K>& raNodeKey, CArray<T_STAG_K, T_STAG_K>& raStagKey)
{
	T_SCLM_D data;
	if (!GetSclm(rName, data)) return FALSE;
	return GetSclmNodeList(data, raNodeKey, raStagKey);
}

// 기존에 GetActivatedStageOfNode()로 각 절점이 처음 activate되는 stage를 가져왔으나 개선
// 위쪽에 다른절점이 생기기 직전 stage를 가저옴 // MQC:4214-HTLEE-20111011
// 1,2번 절점이이 stage1에서, 3번이 stage3에서 생성되면 2번 절점 결과를 stage1에서 가져와서 문제 생기기 때문
BOOL CAttrCtrl::GetSclmNodeList(T_SCLM_D& data, CArray<T_NODE_K, T_NODE_K>& raNodeKey, CArray<T_STAG_K, T_STAG_K>& raStagKey)
{
	raNodeKey.RemoveAll();
	raStagKey.RemoveAll();

	if (m_pDoc->m_pStagCtrl->GetCurStag() == 0) return FALSE; // Base Stage인 경우 에러

	m_pUnitCtrl->ConvertUnitSclmIn(data);

	CArray<double,double> aLevel;
	double dTol2 = data.dTol*data.dTol;

	T_NODE_K NodeKey;
	T_NODE_D NodeData;
	POSITION pos = m_pDataMemb->m_node.GetStart();
	while (pos)
	{
		m_pDataMemb->m_node.GetNext(pos, NodeKey, NodeData);
		double dx = fabs(NodeData.x - data.dX);
		double dy = fabs(NodeData.y - data.dY);

		if (dx > data.dTol) continue;
		if (dy > data.dTol) continue;
		if (dx*dx + dy*dy > dTol2) continue;

		raNodeKey.Add(NodeKey);
		aLevel.Add(NodeData.z);
	}

	int nNode = raNodeKey.GetSize();
	if(nNode < 1)   return TRUE;
	CQSort::QSortDblWithIndex(raNodeKey.GetData(), aLevel.GetData(), nNode);

	raStagKey.SetSize(nNode);
	for(int k = 0; k < nNode; k++)    raStagKey[k] = m_pDoc->m_pStagCtrl->GetActivatedStageOfNode(raNodeKey[k]);

	CArray<T_STAG_K,T_STAG_K> aAllStagK;
	m_pDoc->m_pAttrCtrl->GetStagKeyList(aAllStagK);
	int nStag = aAllStagK.GetSize();
	CMapEx<T_STAG_K,T_STAG_K,int,int> mStagK2Index;
	for(int k = 0; k < nStag; k++)    mStagK2Index.SetAt(aAllStagK[k], k);

	int nIndex1 = 0, nIndex2 = 0;
	for(int k = 0; k < nNode-1; k++)
	{
		if(!mStagK2Index.Lookup(raStagKey[k], nIndex1))     {  ASSERT(0);		continue ;	}
		if(!mStagK2Index.Lookup(raStagKey[k+1], nIndex2))     {  ASSERT(0);		continue ;	}

		if(nIndex2 - nIndex1 > 1)   raStagKey[k] = aAllStagK[nIndex2-1];
	}

	return TRUE;
}

