T_NUCS_K CAttrCtrl::GetNucsKeyForGCS()
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();

	CString strGCS;
	strGCS = _T("GCS");

	T_NUCS_K NucsK;
	NucsK = pDoc->m_pAttrCtrl->GetNucsKey(strGCS);

	if (NucsK == 0)
	{
		T_NUCS_D NucsD; NucsD.Initialize();
		NucsD.UcsName = strGCS;
		NucsD.dOrg[0] = 0.0;
		NucsD.dOrg[1] = 0.0;
		NucsD.dOrg[2] = 0.0;
		NucsD.dVx[0] = 1.0;
		NucsD.dVx[1] = 0.0;
		NucsD.dVx[2] = 0.0;
		NucsD.dVy[0] = 0.0;
		NucsD.dVy[1] = 1.0;
		NucsD.dVy[2] = 0.0;

		if (!pDoc->m_pEditData->AddNucs(NucsD))
		{
			ASSERT(0);
			return FALSE;
		}

		NucsK = pDoc->m_pAttrCtrl->GetNucsKey(strGCS);
	}

	return NucsK;
}

