void CAttrCtrl::GetHsptNode(T_NODE_K KeyNode, CArray<T_HSPT_K, T_HSPT_K>& rKeyList, CArray<T_HSPT_D, T_HSPT_D&>& rDataList)
{
	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(KeyNode, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_HSPT_CMD)
		{
			T_HSPT_K key;
			T_HSPT_D data;
			key.keymap=ListData.nKey;
			GetHspt(key, data);
			rKeyList.Add(key);
			rDataList.Add(data);
		}
	}
}

BOOL CAttrCtrl::GetHsptNode(T_NODE_K KeyNode, T_HSPT_D& rData)
{
	CArray<T_HSPT_K, T_HSPT_K> aKey;
	CArray<T_HSPT_D, T_HSPT_D&> aData;
	GetHsptNode(KeyNode, aKey, aData);
	int nNum = aData.GetSize();
	if (nNum == 0) return FALSE;
	rData.Initialize();
	for (int i = 0; i < nNum; i++)
	{
		rData.dTemper += aData[i].dTemper;
	}
	return TRUE;
}

