void CAttrCtrl::GetHpceList(CArray<CString, CString&>& rstrNameList)
{
	rstrNameList.RemoveAll();

	T_HPCE_D Data;
	CArray<T_HPCE_K, T_HPCE_K>KeyList;
	GetHpceKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetHpce(KeyList[i], Data))
			rstrNameList.Add(Data.strName);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetHpceKeyList(CArray<T_HPCE_K, T_HPCE_K>& rKeyList)
{
	/*
	rKeyList.RemoveAll();
	CArray<CString, CString&>aName;

	POSITION pos;
	T_HPCE_K Key;
	T_HPCE_D Data;
	pos=GetStartHpce();
	while(pos != NULL)
	{
	GetNextHpce(pos, Key, Data);
	rKeyList.Add(Key);
	aName.Add(Data.strName);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortStringWithIndex(rKeyList.GetData(), aName.GetData(), rKeyList.GetSize());
	*/

	// KYE-HONG-20040721
	// SeqId로 Sorting
	rKeyList.RemoveAll();
	int nCount=this->GetCountHpce();
	if(nCount == 0)return;

	CArray<T_HPCE_K, T_HPCE_K> aHpceKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rKeyList.SetSize(nCount);
	aHpceKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_HPCE_K Key;
	T_HPCE_D Data;
	int i = 0;
	pos = GetStartHpce();
	while (pos != NULL)
	{
		GetNextHpce(pos, Key, Data);
		aHpceKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nSeq;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rKeyList[i] = aHpceKey[ix];
	}
}

