BOOL CAttrCtrl::GetSerialHecb(T_ELEM_K KeyElem,int nFaceNo,T_BNGR_K KeyBngr,T_HECB_KEY& rKeySerial)
{
	ElemList* pList;
	if(!m_pDataMemb->m_elem.GetListFromBaseDB(KeyElem, pList))return FALSE;

	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_HECB_CMD)
		{
			T_HECB_K key;
			T_HECB_D data;
			key.keymap=ListData.nKey;
			m_pDataMemb->m_hecb.GetFromBaseDB(key, data);
			if(data.nFaceNo == nFaceNo && data.GroupKey == KeyBngr)
			{
				rKeySerial=key.key.serial;
				return TRUE;
			}
		}
	}

	T_HECB_K key;
	T_HECB_D data;
	key.key.entity=KeyElem;
	int j=0;
	while(TRUE)
	{
		j++;
		//      if(j > ???)return FALSE;
		key.key.serial=j;
		if(!m_pDataMemb->m_hecb.GetFromBaseDB(key,data))
		{
			rKeySerial=j;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeKeyHecb(T_ELEM_K KeyElem,int nFaceNo,T_BNGR_K KeyBngr,T_HECB_K& rKey)
{
	rKey.key.entity=KeyElem;
	rKey.key.serial=0;

	T_HECB_KEY KeySerial;
	if(!GetSerialHecb(KeyElem, nFaceNo, KeyBngr, KeySerial))return FALSE;
	rKey.key.serial=KeySerial;
	return TRUE;
}

