void CAttrCtrl::GetHecb(T_ELEM_K KeyElem, CArray<T_HECB_K, T_HECB_K>& rarKey, CArray<T_HECB_D, T_HECB_D&>& rarData)
{
	rarKey.RemoveAll();
	rarData.RemoveAll();

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_HECB_CMD)
		{
			T_HECB_K key;
			T_HECB_D data;
			key.keymap=ListData.nKey;
			GetHecb(key, data);
			rarKey.Add(key);
			rarData.Add(data);
		}
	}
}

