BOOL CAttrCtrl::GetNlctLcaseOption(T_NLCT_K Key, T_NLCT_DATA& rLcaseData)
{
	T_NLCT_D NlctD;
	NlctD.Initialize();
	if (!GetNlct(NlctD))
	{
		return FALSE;
	}

	if (NlctD.nGlobalOrLcase == 0)
	{
		rLcaseData = NlctD.GlobalData;
		return TRUE;
	}
	else
	{
		for (int i = 0; i < NlctD.aLCaseData.GetSize(); i++)
		{
			if (NlctD.aLCaseData[i].StldK == Key)
			{
				rLcaseData = NlctD.aLCaseData[i].NlctData;
				return TRUE;
			}
		}
		return FALSE;
	}
	ASSERT(0);
	return TRUE;
}

