BOOL CAttrCtrl::IsBoundaryGroup4SoilPressure(T_NODE_K KeyNode, int nLcomAnalType, int nLoadCaseKey, CArray<UINT, UINT>& aBngrKey, BOOL& bExistBngrGrupAssign)
{
	T_BCCT_D BcctD;
	if(!GetBcct(BcctD) || BcctD.cSelect[1] != '1') { bExistBngrGrupAssign=FALSE; return TRUE; } // Bcoundary Change Asssignment 데이터가 없거나 Point Spring 가 꺼져 있으면 return TRUE;

	bExistBngrGrupAssign=TRUE;
	// Point Spring에 할당된 boundary key 찾기
	CArray<T_NSPR_K, T_NSPR_K> rKeyList; rKeyList.RemoveAll();
	CArray<T_NSPR_D, T_NSPR_D&> rDataList; rDataList.RemoveAll();
	CArray<UINT, UINT> aBngrKey4node; aBngrKey4node.RemoveAll();
	GetNsprNode(KeyNode, rKeyList, rDataList);
	for(int i=0; i< rDataList.GetSize(); i++)
	{
		T_NSPR_D NsprD = rDataList[i];
		if (NsprD.nFromType != 1)  continue;  
		aBngrKey4node.Add(NsprD.GroupKey);
	}

	aBngrKey.RemoveAll();
	int nLoadCaseType=0;
	if(nLcomAnalType == D_LCOM_STATIC) nLoadCaseType=0;
	else                               nLoadCaseType=1;
	if(nLoadCaseType == 1)
	{
		if     (nLcomAnalType == D_LCOM_SPECTRUM)   nLoadCaseKey=1;
		else if(nLcomAnalType == D_LCOM_HISTORY)    nLoadCaseKey=2;
		else if(nLcomAnalType == D_LCOM_PUSHOVER)   nLoadCaseKey=3;
		else if(nLcomAnalType == D_LCOM_MOVING)     nLoadCaseKey=4;
		else if(nLcomAnalType == D_LCOM_SETTLEMENT) nLoadCaseKey=5;
		else {ASSERT(FALSE); return 0;}
	}

	CArray<UINT, UINT> aBngrKeyTemp; aBngrKeyTemp.RemoveAll();
	for(int i=0; i<BcctD.aBcctBase.GetSize(); i++)
	{
		if(BcctD.aBcctBase[i].nLoadCaseType != nLoadCaseType)continue;
		if(BcctD.aBcctBase[i].LoadCaseKey   != nLoadCaseKey) continue;

		if(BcctD.aBcctBase[i].BcctCombIndex!=-1)
		{
#ifdef _MEC
			T_BCCD_D BccdD;
			T_BCCD_K BccdK = BcctD.aBcctBase[i].BcctCombIndex + 1;
			GetBccd(BccdK, BccdD);
			for (int j = 0; j < BccdD.aBngrKey.GetSize(); j++)
			{
				UINT BngrKey = BccdD.aBngrKey[j];
				for (int k = 0; k < aBngrKey4node.GetSize(); k++)
				{
					if (BngrKey == aBngrKey4node[k])
					{
						aBngrKeyTemp.Add(BngrKey); break;
					}
				}
			}
#else
			//aBngrKey.Copy(BcctD.aBcctComb[BcctD.aBcctBase[i].BcctCombIndex].aBngrKey);

			for(int j=0; j<BcctD.aBcctComb[BcctD.aBcctBase[i].BcctCombIndex].aBngrKey.GetSize(); j++) 
			{
				UINT BngrKey = BcctD.aBcctComb[BcctD.aBcctBase[i].BcctCombIndex].aBngrKey[j];
				for(int k=0; k<aBngrKey4node.GetSize(); k++)
				{
					if(BngrKey == aBngrKey4node[k]) 
					{
						aBngrKeyTemp.Add(BngrKey); break;
					}
				}
			}
#endif
			if(aBngrKeyTemp.GetSize()>0) aBngrKey.Copy(aBngrKeyTemp);
			else                         aBngrKey.Add(0);
		}
		else
		{
			// Unchanged인 경우도 Soil Pressure 출력 되도록
			aBngrKey.Add(0);
			bExistBngrGrupAssign = FALSE;
		}

		return TRUE;
	}

	return FALSE;
}

BOOL CAttrCtrl::GetBcctBngrTypeItem(CArray<T_LIST_BOX_ITEM_MEC, T_LIST_BOX_ITEM_MEC>& rData, CArray<BOOL, BOOL>& aItemChecked)
{

	T_LIST_BOX_ITEM_MEC aListBoxItem[] = {
		{_LS(IDS_TM_DT_SECF), D_BNGR_SECF, D_PROD_GEN + D_PROD_CVL},  // Section Stiffness Scale Factor
		{_LS(IDS_TM_DT_ESSF), D_BNGR_ESSF, D_PROD_GEN             },  // Element Stiffness Scale Factor
		{_LS(IDS_TM_DT_EWSF), D_BNGR_EWSF, D_PROD_GEN + D_PROD_CVL},  // Effective Width Scale Factor 
		{_LS(IDS_TM_DT_PSSF), D_BNGR_PSSF, D_PROD_GEN + D_PROD_CVL},  // Plate Stiffness Scale Factor
		{_LS(IDS_TM_DT_WSSF), D_BNGR_WSSF, D_PROD_GEN             },  // Wall Stiffness Scale Factor 

		{_LS(IDS_TM_DT_CONS), D_BNGR_CONS, D_PROD_GEN + D_PROD_CVL},  // Support
		{_LS(IDS_TM_DT_NSPR), D_BNGR_NSPR, D_PROD_GEN + D_PROD_CVL},  // Point Spring support
		{_LS(IDS_TM_DT_GSPR), D_BNGR_GSPR, D_PROD_GEN + D_PROD_CVL},  // General Spring support
		{_LS(IDS_TM_NC_SSPS), D_BNGR_SSPS, D_PROD_GEN + D_PROD_CVL},  // Surface Spring Support

		{_LS(IDS_TM_DT_ELNK), D_BNGR_ELNK, D_PROD_GEN + D_PROD_CVL},  // Elastic Link
		{_LS(IDS_TM_DT_RIGD), D_BNGR_RIGD, D_PROD_GEN + D_PROD_CVL},  // Rigid Link
		{_LS(IDS_TM_DT_NLNK), D_BNGR_NLNK, D_PROD_GEN + D_PROD_CVL},  // General Link
		{_LS(IDS_TM_DT_CGLK), D_BNGR_CGLP, D_PROD_GEN + D_PROD_CVL},  // Change General Link Property

		{_LS(IDS_TM_DT_FRLS), D_BNGR_FRLS, D_PROD_GEN + D_PROD_CVL},  // Beam end release
		{_LS(IDS_TM_DT_OFFS), D_BNGR_OFFS, D_PROD_GEN + D_PROD_CVL},  // Beam end offset
		{_LS(IDS_TM_DT_PRLS), D_BNGR_PRLS, D_PROD_GEN + D_PROD_CVL},  // Plate release
		{_LS(IDS_TM_DT_MCON), D_BNGR_MCON, D_PROD_GEN + D_PROD_CVL},  // Linear Constraint
	};

	int nMask = 0;
#if defined(_MGEN)
	nMask = D_PROD_GEN;
#elif defined(_CIVIL)
	nMask = D_PROD_CVL;
#else
#error "Unknown Product Definition!"
#endif

	rData.RemoveAll();
	aItemChecked.RemoveAll();

	int i, nCount, ix = 0;
	nCount = sizeof(aListBoxItem) / sizeof(T_LIST_BOX_ITEM_MEC);
	for (i = 0; i < nCount; i++)
	{
		rData.Add(aListBoxItem[i]);
		if ((nMask & aListBoxItem[i].nMask) == 0) // ���ܵ�
		{
			aItemChecked.Add(0);
		}
		else
		{
			aItemChecked.Add(1);
			ix++;
		}
	}

	return TRUE;
}

BOOL CAttrCtrl::ConvertBcct_960ToMec(T_BCCT_D& BcctMaster, T_BCCT_D& BcctMec)
{
	// FES BCCT 데이터 유지
	BcctMec = BcctMaster;

	// MEC
	// 	1		sect					      T_SECF_K					
	// 	2		elem					      T_ESSF_K				Gen	
	// 	3		effective width			      T_EWSF_K					
	// 	4		plate					      T_PSSF_K					
	// 	5		wall					      T_WSSF_K				Gen	
	// 	6		support					      T_CONS_K					
	// 	7		Point Spring			      T_NSPR_K					
	// 	8		General Spring			      T_GSPR_K					
	// 	9		Surface Spring			      T_SSPS_K					
	// 	10		Elastic Link			      T_ELNK_K					
	// 	11		rigid link				      T_RIGD_K					
	// 	12		General link			      T_NLNK_K					
	// 	13		Change General Link Property  T_CGLP_K					
	// 	14		beam end release			  T_FRLS_K					
	// 	15		beam end offset				  T_OFFS_K					
	// 	16		plate release				  T_PRLS_K					
	// 	17		Linear Constraint			  T_MCON_K					

	// MODS
	// 0=Support, 1=Point Spring, 2=General Spring, 3=Change General Link Property, 4=SECF, 5=WSSF, 6=PSSF, 7 = FRLS, 8 = ESSF

	BcctMec.aSelect.SetSize(D_BNGR_SIZE);
	BcctMec.aSelect[D_BNGR_SECF] = (BcctMaster.cSelect[4] == '1') ? TRUE : FALSE; // 0  sect scale factor					    
	BcctMec.aSelect[D_BNGR_ESSF] = (BcctMaster.cSelect[8] == '1') ? TRUE : FALSE; // 1  elem scale factor					    
	BcctMec.aSelect[D_BNGR_EWSF] = FALSE;                                          // 2  effective width  scale factor			     
	BcctMec.aSelect[D_BNGR_PSSF] = (BcctMaster.cSelect[6] == '1') ? TRUE : FALSE; // 3  plate scale factor					    
	BcctMec.aSelect[D_BNGR_WSSF] = (BcctMaster.cSelect[5] == '1') ? TRUE : FALSE; // 4  wall  scale factor					    
	BcctMec.aSelect[D_BNGR_CONS] = (BcctMaster.cSelect[0] == '1') ? TRUE : FALSE; // 5  support					    
	BcctMec.aSelect[D_BNGR_NSPR] = (BcctMaster.cSelect[1] == '1') ? TRUE : FALSE; // 6  Point Spring			    
	BcctMec.aSelect[D_BNGR_GSPR] = (BcctMaster.cSelect[2] == '1') ? TRUE : FALSE; // 7  General Spring			    
	BcctMec.aSelect[D_BNGR_SSPS] = FALSE;                                          // 8  Surface Spring			    
	BcctMec.aSelect[D_BNGR_ELNK] = FALSE;                                          // 9  Elastic Link			    
	BcctMec.aSelect[D_BNGR_RIGD] = FALSE;                                          // 10 rigid link				    
	BcctMec.aSelect[D_BNGR_NLNK] = FALSE;                                          // 11 General link			    
	BcctMec.aSelect[D_BNGR_CGLP] = (BcctMaster.cSelect[3] == '1') ? TRUE : FALSE; // 12 Change General Link Property
	BcctMec.aSelect[D_BNGR_FRLS] = (BcctMaster.cSelect[7] == '1') ? TRUE : FALSE; // 13 beam end release			
	BcctMec.aSelect[D_BNGR_OFFS] = FALSE;                                          // 14 beam end offset				
	BcctMec.aSelect[D_BNGR_PRLS] = FALSE;                                          // 15 plate release				
	BcctMec.aSelect[D_BNGR_MCON] = FALSE;                                          // 16 Linear Constraint		

	CArray<BOOL, BOOL> aBccdSel;

	aBccdSel.SetSize(D_BNGR_SIZE);
	for (int i = 0; i < aBccdSel.GetSize(); i++)
	{
		aBccdSel[i] = TRUE;
	}

	for (int i = 0; i < BcctMaster.aBcctComb.GetSize(); i++)
	{
		T_BCCT_COMB BcctComb = BcctMaster.aBcctComb[i];

		T_BCCD_D Bccd;
		Bccd.strCombName = BcctComb.strCombName;
		Bccd.aBngrKey.Copy(BcctComb.aBngrKey);

		if (!m_pDoc->m_pEditData->AddBccd(Bccd)) { ASSERT(0);  return FALSE; }
	}

	//////////////////////////////////////////////////////////////////////////

	// 1. static load case
	std::unordered_set<T_STLD_K> setUseStld;

	for (int i = 0; i < BcctMaster.aBcctBase.GetSize(); i++)
	{
		T_BCCT_BASE_MEC BcctBase_MEC; 
		BcctBase_MEC = BcctMaster.aBcctBase[i];
		if (BcctBase_MEC.nLoadCaseType == T_BCCT_BASE::StaicLoad)
		{
			setUseStld.insert(BcctBase_MEC.LoadCaseKey);

			BcctMec.aBcctBase_MEC.Add(BcctBase_MEC);
		}
	}

	// ������������ ����� ������ �־ ����Ȱ� �ʱⰪ���� ä���ش�.
	CArray<T_STLD_K, T_STLD_K> aStldK;
	m_pDoc->m_pAttrCtrl->GetStldKeyList(aStldK);

	for (int i = 0; i < aStldK.GetSize(); i++)
	{
		if (setUseStld.find(aStldK[i]) == setUseStld.end())
		{
			T_BCCT_BASE_MEC BcctBase_MEC;
			BcctBase_MEC.nLoadCaseType = T_BCCT_BASE_MEC::StaicLoad;
			BcctBase_MEC.LoadCaseKey = aStldK[i];
			BcctBase_MEC.BcctCombIndex = -1;

			BcctMec.aBcctBase_MEC.Add(BcctBase_MEC);
		}
	}

	// 2. Other
	int nInex_THRSEV = -1;
	int nInex_THNS = -1;
	int nInex_PO = -1;
	int aIndex[5] = { -1,-1,-1,-1,-1 };
	for (int i = 0; i < BcctMaster.aBcctBase.GetSize(); i++)
	{
		T_BCCT_BASE BcctBaseMater = BcctMaster.aBcctBase[i];
		if (BcctBaseMater.nLoadCaseType != T_BCCT_BASE::Other) continue;

		if (BcctBaseMater.LoadCaseKey == T_BCCT_BASE::THRSEV)
			nInex_THRSEV = BcctBaseMater.BcctCombIndex;
		else if (BcctBaseMater.LoadCaseKey == T_BCCT_BASE::THNS)
			nInex_THNS = BcctBaseMater.BcctCombIndex;
		else if (BcctBaseMater.LoadCaseKey == T_BCCT_BASE::PO)
			nInex_PO = BcctBaseMater.BcctCombIndex;
		else if (BcctBaseMater.LoadCaseKey == T_BCCT_BASE::MV)
			aIndex[T_BCCT_BASE_MEC::MV] = BcctBaseMater.BcctCombIndex;
		else if (BcctBaseMater.LoadCaseKey == T_BCCT_BASE::SM)
			aIndex[T_BCCT_BASE_MEC::SM] = BcctBaseMater.BcctCombIndex;
	}
	T_BCCT_BASE_MEC BcctBase_MEC;
	BcctBase_MEC.nLoadCaseType = T_BCCT_BASE_MEC::Other;

	BcctBase_MEC.LoadCaseKey = T_BCCT_BASE_MEC::MV; BcctBase_MEC.BcctCombIndex = aIndex[T_BCCT_BASE_MEC::MV];
	BcctMec.aBcctBase_MEC.Add(BcctBase_MEC);
	BcctBase_MEC.LoadCaseKey = T_BCCT_BASE_MEC::SM; BcctBase_MEC.BcctCombIndex = aIndex[T_BCCT_BASE_MEC::SM];
	BcctMec.aBcctBase_MEC.Add(BcctBase_MEC);
	BcctBase_MEC.LoadCaseKey = T_BCCT_BASE_MEC::EIG; BcctBase_MEC.BcctCombIndex = nInex_THRSEV; // aIndex[T_BCCT_BASE::EIG];
	BcctMec.aBcctBase_MEC.Add(BcctBase_MEC);
	BcctBase_MEC.LoadCaseKey = T_BCCT_BASE_MEC::RS; BcctBase_MEC.BcctCombIndex = nInex_THRSEV; // aIndex[T_BCCT_BASE::RS ]; 
	BcctMec.aBcctBase_MEC.Add(BcctBase_MEC);
	BcctBase_MEC.LoadCaseKey = T_BCCT_BASE_MEC::LTH; BcctBase_MEC.BcctCombIndex = nInex_THRSEV; // aIndex[T_BCCT_BASE::LTH];
	BcctMec.aBcctBase_MEC.Add(BcctBase_MEC);

	// 3. Nonlinear Time History Analysis
	CArray<T_THIS_K, T_THIS_K> aThisK;
	m_pDoc->m_pAttrCtrl->GetNLThisKeyList(aThisK);

	for (int i = 0; i < aThisK.GetSize(); i++)
	{
		T_THIS_D rData;	rData.Initialize();
		m_pDoc->m_pAttrCtrl->GetThis(aThisK[i], rData);

		if (rData.nAnalType == D_THIS_ANALTYPE_LINEAR) continue;

		if (rData.nAnalType == D_THIS_ANALTYPE_NONLINEAR &&
			rData.nAnalMethod == D_THIS_ANALMETHOD_STATIC)
		{
			T_BCCT_BASE_MEC BcctBase_MEC;
			BcctBase_MEC.nLoadCaseType = T_BCCT_BASE_MEC::NTH;
			BcctBase_MEC.LoadCaseKey = aThisK[i];
			BcctBase_MEC.BcctCombIndex = nInex_THNS;
			BcctMec.aBcctBase_MEC.Add(BcctBase_MEC);
		}
		else
		{
			T_BCCT_BASE_MEC BcctBase_MEC;
			BcctBase_MEC.nLoadCaseType = T_BCCT_BASE_MEC::NTH;
			BcctBase_MEC.LoadCaseKey = aThisK[i];
			BcctBase_MEC.BcctCombIndex = nInex_THRSEV;
			BcctMec.aBcctBase_MEC.Add(BcctBase_MEC);
		}
	}

	// 4.Pushover Analysis
	CArray<T_POLC_K, T_POLC_K> aPolcK;
	m_pDoc->m_pAttrCtrl->GetPolcKeyList(aPolcK);

	for (int i = 0; i < aPolcK.GetSize(); i++)
	{
		T_BCCT_BASE_MEC BcctBase_MEC;
		BcctBase_MEC.nLoadCaseType = T_BCCT_BASE_MEC::PO;
		BcctBase_MEC.LoadCaseKey = aPolcK[i];
		BcctBase_MEC.BcctCombIndex = nInex_PO;
		BcctMec.aBcctBase_MEC.Add(BcctBase_MEC);
	}

	// CVLRMT BCCT 기존 데이터 유지를 위해 아래 주석처리함.
	//BcctMec.aBcctComb.RemoveAll();
	//for (int i = 0; i < 16; i++) BcctMec.cSelect[i] = '0';
	//BcctMec.bApplyDisp = FALSE;

	return TRUE;
}

BOOL CAttrCtrl::ConvertBcctCombForMEC(T_BCCT_D& BcctMec)
{
	if (BcctMec.aBcctBase.GetSize() == 0) return FALSE;

	BcctMec.aBcctComb.RemoveAll();
	T_BCCT_COMB BcctComb;

	CArray<T_BCCD_K, T_BCCD_K> aBccdK;
	GetBccdKeyList(aBccdK);
	for (int i = 0; i < aBccdK.GetSize(); i++)
	{
		T_BCCD_D Bccd;
		if (!GetBccd(aBccdK[i], Bccd)) { ASSERT(0); continue; }

		BcctComb.Initialize();
		BcctComb.strCombName = Bccd.strCombName;
		BcctComb.aBngrKey.Copy(Bccd.aBngrKey);

		BcctMec.aBcctComb.Add(BcctComb);
	}

	return TRUE;
}
