void CAttrCtrl::GetHngtList(CArray<CString, CString&>& rstrHngtList)
{
	rstrHngtList.RemoveAll();

	int nCount=GetCountHngt();
	if(nCount == 0)return;

	POSITION pos;
	T_HNGT_K Key;
	T_HNGT_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartHngt();
		while(pos != NULL)
		{
			GetNextHngt(pos, Key, Data);
			if(Data.nSeq == i)
			{
				rstrHngtList.Add(Data.strTypeName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetHngtKeyList(CArray<T_HNGT_K, T_HNGT_K>& rHngtKeyList)
{
	/*
	rKeyList.RemoveAll();

	int nCount=GetCountHngt();
	if(nCount == 0)return;

	POSITION pos;
	T_HNGT_K Key;
	T_HNGT_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartHngt();
	while(pos != NULL)
	{
	GetNextHngt(pos, Key, Data);
	if(Data.nSeq == i)
	{
	rKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rHngtKeyList.RemoveAll();
	int nCount=GetCountHngt();
	if(nCount == 0)return;

	CArray<T_HNGT_K, T_HNGT_K> aHngtKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rHngtKeyList.SetSize(nCount);
	aHngtKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_HNGT_K Key;
	T_HNGT_D Data;
	int i = 0;
	pos = GetStartHngt();
	while (pos != NULL)
	{
		GetNextHngt(pos, Key, Data);
		aHngtKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nSeq;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rHngtKeyList[i] = aHngtKey[ix];
	}
}

