BOOL CAttrCtrl::GetHngt(CString& rstrTypeName, T_HNGT_D& rData)
{
	T_HNGT_K key;
	T_HNGT_D data;
	CString strTypeName=rstrTypeName;
	strTypeName.TrimRight();

	POSITION pos=m_pDataMemb->m_hngt.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_hngt.GetNext(pos,key,data);
		if(strTypeName.CompareNoCase(data.strTypeName) == 0)
		{
			m_pUnitCtrl->ConvertUnitHngtOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

