T_HNGT_K CAttrCtrl::GetHngtKey(CString& rstrTypeName)
{
	T_HNGT_K key;
	T_HNGT_D data;

	POSITION pos=GetStartHngt();
	while(pos != NULL)
	{
		GetNextHngt(pos,key,data);
		if(rstrTypeName.CompareNoCase(data.strTypeName) == 0)return key;
	}
	key=0;
	return key;
}

