void CAttrCtrl::GetPolcKeyList(CArray<T_POLC_K, T_POLC_K>& rPolcKeyList)
{
	rPolcKeyList.RemoveAll();
	int nCount=GetCountPolc();
	if(nCount == 0)return;

	CArray<T_POLC_K, T_POLC_K> aPolcKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rPolcKeyList.SetSize(nCount);
	aPolcKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_POLC_K Key;
	T_POLC_D Data;
	int i = 0;
	pos = GetStartPolc();
	while (pos != NULL)
	{
		GetNextPolc(pos, Key, Data);
		aPolcKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.LoadCaseId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rPolcKeyList[i] = aPolcKey[ix];
	}
}

