BOOL CAttrCtrl::GetPolc(CString& rLoadCaseName, T_POLC_D& rData)
{
	T_POLC_K key;
	T_POLC_D data;
	CString strLoadCaseName=rLoadCaseName;
	strLoadCaseName.TrimRight();

	POSITION pos=m_pDataMemb->m_polc.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_polc.GetNext(pos,key,data);
		if(strLoadCaseName.CompareNoCase(data.strName) == 0)
		{
			m_pUnitCtrl->ConvertUnitPolcOut(data);
			rData=data;
			return TRUE;
		}
	}
#ifdef _MEC
	T_POLC_K DummyInitPlocKey = m_pDoc->GetDummyInitPolcKey(rLoadCaseName);
	if (DummyInitPlocKey > 0)
	{
		return m_pDoc->GetDummyInitPolcByDummyKey(DummyInitPlocKey, rData);
	}
#endif
	return FALSE;
}

BOOL CAttrCtrl::GetPolc(T_POLC_K Key, T_POLC_D& rData)
{
#ifdef _MEC
	if (m_pDoc->IsDummyInitLoadPolc(Key))
	{
		return m_pDoc->GetDummyInitPolcByDummyKey(Key, rData);
	}
#endif
	BOOL bReturn=m_pDataMemb->m_polc.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitPolcOut(rData);
	return bReturn;
}

T_POLC_K CAttrCtrl::GetPolcKey(CString& rLoadCaseName)
{
	T_POLC_K key;
	T_POLC_D data;

	POSITION pos=GetStartPolc();
	while(pos != NULL)
	{
		GetNextPolc(pos,key,data);
		if(rLoadCaseName.CompareNoCase(data.strName) == 0)return key;
	}
#ifdef _MEC
	return m_pDoc->GetDummyInitPolcKey(rLoadCaseName);
#endif
	key=0;
	return key;
}

