////////////// pofc ////////////////
void CAttrCtrl::GetPofcList(CArray<CString, CString&>& rstrPofcList)
{
	rstrPofcList.RemoveAll();

	int nCount=GetCountPofc();
	if(nCount == 0)return;

	POSITION pos;
	T_POFC_K Key;
	T_POFC_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartPofc();
		while(pos != NULL)
		{
			GetNextPofc(pos, Key, Data);
			if(Data.FunctionId == i)
			{
				rstrPofcList.Add(Data.strName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetPofcKeyList(CArray<T_POFC_K, T_POFC_K>& rPofcKeyList)
{
	rPofcKeyList.RemoveAll();
	int nCount=GetCountPofc();
	if(nCount == 0)return;

	CArray<T_POFC_K, T_POFC_K> aPofcKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rPofcKeyList.SetSize(nCount);
	aPofcKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_POFC_K Key;
	T_POFC_D Data;
	int i = 0;
	pos = GetStartPofc();
	while (pos != NULL)
	{
		GetNextPofc(pos, Key, Data);
		aPofcKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.FunctionId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rPofcKeyList[i] = aPofcKey[ix];
	}
}

