////////////// hnge ////////////////
int CAttrCtrl::GetHngePos(T_HNGE_D& rHngeData)
{
	int nNewPos = 0;
	if (rHngeData.nHingeLocation == 1) nNewPos = 1; // I
	else if (rHngeData.nHingeLocation == 3) nNewPos = 2;  // J
	else
	{
		T_HNGT_D hngt;
		if (!GetHngt(rHngeData.HingeType, hngt)) return 0;
		if (hngt.nDataType == 0) nNewPos = 3; // CP
		else if (hngt.nDataType == 2) nNewPos = 4;  // CV
		else if (hngt.nDataType == 4)
		{
			if (hngt.nHingeType == 0) nNewPos = 3; // CP
			else if (hngt.nHingeType == 2) nNewPos = 4; // CV
			else if (hngt.nHingeType == 4) nNewPos = 5; // CT
		}
	}
	return nNewPos;
}

BOOL CAttrCtrl::GetSerialHnge(T_ELEM_K KeyElem, T_HNGE_D& rHngeData, T_HNGE_KEY& rKeySerial)
{
	rKeySerial = GetHngePos(rHngeData);
	if (rKeySerial == 0) return FALSE;
	return TRUE;
}

BOOL CAttrCtrl::MakeKeyHnge(T_ELEM_K KeyElem, T_HNGE_D& rHngeData, T_HNGE_K& rKey)
{
	rKey.key.entity=KeyElem;
	rKey.key.pos=0;

	T_HNGE_KEY KeySerial;
	if(!GetSerialHnge(KeyElem, rHngeData, KeySerial))return FALSE;
	rKey.key.pos=KeySerial;
	return TRUE;
}

void CAttrCtrl::GetHngeKeyList(CArray<T_HNGE_K, T_HNGE_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_HNGE_K Key;
	T_HNGE_D Data;
	pos=GetStartHnge();
	while(pos != NULL)
	{
		GetNextHnge(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetHngeElemKeyList(CArray<T_ELEM_K, T_ELEM_K>& rElemKeyList)
{
	rElemKeyList.RemoveAll();
	CArray<T_HNGE_K, T_HNGE_K> aHngeKeyList;
	GetHngeKeyList(aHngeKeyList);
	int nNum = aHngeKeyList.GetSize();
	if (nNum == 0) return;
	rElemKeyList.Add(aHngeKeyList[0].key.entity);
	for (int i = 1; i < nNum; i++)
	{
		if (aHngeKeyList[i].key.entity == aHngeKeyList[i-1].key.entity)
			continue;
		rElemKeyList.Add(aHngeKeyList[i].key.entity);
	}
}

