void CAttrCtrl::GetHngeElem(T_ELEM_K KeyElem, CArray<T_HNGE_K, T_HNGE_K>& rKeyList, CArray<T_HNGE_D, T_HNGE_D&>& rDataList)
{
	rKeyList.RemoveAll();
	rDataList.RemoveAll();

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(KeyElem, pList));
	T_LIST_DATA ListData;
	POSITION pos=pList->GetHeadPosition();
	while(pos != NULL)
	{
		ListData=pList->GetNext(pos);
		if(ListData.nCmd == LT_HNGE_CMD)
		{
			T_HNGE_K key;
			T_HNGE_D data;
			key.keymap=ListData.nKey;
			GetHnge(key, data);
			rKeyList.Add(key);
			rDataList.Add(data);
		}
	}
}

