BOOL CAttrCtrl::CalcPushMeshData(int nMatl, int nProp, _PUSH_MESH_DATA& p_m_d)
{
	CPMInterCurve PMInterCurve;
	// Add by ZINU.('02.4.9). For create rebar data by current unit.
	T_UNIT_INDEX CurIndex;
	m_pUnitCtrl->GetUnitIndexCurrent(CurIndex);
	T_MATD_D MatlData;
	MatlData.Initialize();
	if(GetMatlDesign((T_MATL_K)nMatl,MatlData))
	{
		if(MatlData.Type==_T("SRC"))    m_pDoc->m_pMatlDB->Create_RebarData(CurIndex.nBase_Length, CurIndex.nBase_Force, FALSE);
		else if(MatlData.Type==_T("C")) m_pDoc->m_pMatlDB->Create_RebarData(CurIndex.nBase_Length, CurIndex.nBase_Force, TRUE);
		return PMInterCurve.Get_MeshGen(nMatl, nProp, p_m_d);
	}
	else  m_pDoc->m_pMatlDB->Create_RebarData(CurIndex.nBase_Length, CurIndex.nBase_Force, TRUE); // if nMatl=0, Wall.

	return FALSE;
}


BOOL CAttrCtrl::CalcGhng(T_HNGE_K key, T_HNGT_D& data,_PUSH_MESH_DATA& p_m_d)
{
	T_ELEM_K elem_k = key.key.entity;
	T_ELEM_D elem_d;
	T_MATL_D matl_d;
	int nPos;
	switch(key.key.pos)//1:I, 2:J, 3:CP, 4:CV, 5:CT
	{
	case 1:
		nPos = 0;
		break;
	case 2:
		nPos = 2;
		break;
	case 3: case 4: case 5:
		nPos = 1;
		break;
	}

	//CPMVTStrength DesignParamModule;

	GetElem(elem_k,elem_d);
	GetMatl(elem_d.elmat,matl_d);
	BOOL bWall = IsWall(elem_d.eltyp);
	int nMemberType = GetMemberType(elem_k);
	BOOL bBeam = (nMemberType == 2)? TRUE:FALSE;
	BOOL bMyOnly = bBeam || bWall; // 20050720, from 최원호(Wall, Beam인 경우 My, Mz의 max, min에서 My값만을 사용하도록 변경)
	//1=column(수직-1/100 오차허용), 2=beam(수평-1/100 오차허용), 3=brace 0=Frame 요소가 아닐때

	if(data.nHingeType == 0)// Axial
	{
		//double dTableY[9] = {-0.2,-0.2,-1,-1,0,1,1.33,0.8,0.8};
		double dTableY[9] = {-0.2,-0.2,-1,-1,0,1,1.1,0.8,0.8};// MNET:1926-1 20060123 JHKIM
		double dTableX[9] = {-9,-1.01,-1.01,-1,0,1,12,12,15};
		double IO_LS_CP_p[3] = {1,8,10};
		double IO_LS_CP_n[3] = {-1,-6,-8};

		SetGhngPropData(data,dTableY,dTableX,IO_LS_CP_p,IO_LS_CP_n);
	}
	else
	{
		if(matl_d.Type.CompareNoCase(_T("C")) == 0 || matl_d.Type.CompareNoCase(_T("SRC")) == 0)
		{
			double dTableY[9];
			double dTableX[9];
			double IO_LS_CP_p[3];
			double IO_LS_CP_n[3];

			if(data.nHingeType == 1 || data.nHingeType == 3) // Moment || PMM
			{

				double dTableY_B[9] = {-0.2,-0.2,-1.1,-1,0,1,1.1,0.2,0.2};
				double dTableX_B[9] = {-0.035,-0.02,-0.02,0,0,0,0.02,0.02,0.035};
				double dTableY_C[9] = {-0.2,-0.2,-1.1,-1,0,1,1.1,0.2,0.2};
				double dTableX_C[9] = {-0.025,-0.015,-0.015,0,0,0,0.015,0.015,0.025};
				//double dTableY_W[9] = {-0.6,-0.6,-1.1,-1,0,1,1.1,0.6,0.6};
				//double dTableX_W[9] = {-0.010,-0.005,-0.005,0,0,0,0.005,0.005,0.010};
				// 20050721, from 최원호(default변경)
				double dTableY_W[9] = {-0.5125,-0.5125,-1.1,-1,0,1,1.1,0.5125,0.5125};
				double dTableX_W[9] = {-0.01425,-0.00975,-0.00975,0,0,0,0.00975,0.00975,0.01425};

				double IO_LS_CP_p_B[3] = {0.005,0.01,0.02};
				double IO_LS_CP_n_B[3] = {-0.005,-0.01,-0.02};
				double IO_LS_CP_p_C[3] = {0.0025,0.0075,0.015};
				double IO_LS_CP_n_C[3] = {-0.0025,-0.0075,-0.015};
				//double IO_LS_CP_p_W[3] = {0.001,0.003,0.005};
				//double IO_LS_CP_n_W[3] = {-0.001,-0.003,-0.005};
				// 20050720, from 최원호(default변경)
				double IO_LS_CP_p_W[3] = { 0.00325, 0.00625, 0.00925};
				double IO_LS_CP_n_W[3] = {-0.00325,-0.00625,-0.00925};

				if(bWall) 
					for(int l=0; l<9; l++)
					{
						dTableY[l] = dTableY_W[l];
						dTableX[l] = dTableX_W[l];
					}
				else if(bBeam)
					for(int l=0; l<9; l++)
					{
						dTableY[l] = dTableY_B[l];
						dTableX[l] = dTableX_B[l];
					}
				else
					for(int l=0; l<9; l++)
					{
						dTableY[l] = dTableY_C[l];
						dTableX[l] = dTableX_C[l];
					}

					if(bWall) 
						for(int l=0; l<3; l++)
						{
							IO_LS_CP_p[l] = IO_LS_CP_p_W[l];
							IO_LS_CP_n[l] = IO_LS_CP_n_W[l];
						}
					else if(bBeam)
						for(int l=0; l<3; l++)
						{
							IO_LS_CP_p[l] = IO_LS_CP_p_B[l];
							IO_LS_CP_n[l] = IO_LS_CP_n_B[l];
						}
					else
						for(int l=0; l<3; l++)
						{
							IO_LS_CP_p[l] = IO_LS_CP_p_C[l];
							IO_LS_CP_n[l] = IO_LS_CP_n_C[l];
						}

						SetGhngPropData(data,dTableY,dTableX,IO_LS_CP_p,IO_LS_CP_n,TRUE,bMyOnly);
			}
			else if(data.nHingeType == 2) // Shear
			{
				double dTableY_BC[9] = {-0.45,-0.45,-1.1,-1,0,1,1.1,0.45,0.45};
				//double dTableX_BC[9] = {-0.015,-0.001,-0.001,0,0,0,0.001,0.001,0.015};
				double dTableX_BC[9] = {-0.025,-0.015,-0.015,0,0,0,0.015,0.015,0.025};// MNET:1926-2 20060123 JHKIM
				double dTableY_W[9] = {-0.4,-0.4,-1.1,-1,0,1,1.1,0.4,0.4};
				double dTableX_W[9] = {-0.02,-0.0075,-0.0075,0,0,0,0.0075,0.0075,0.02};

				//double IO_LS_CP_p_BC[3] = {0.001,0.001,0.001};
				//double IO_LS_CP_n_BC[3] = {-0.001,-0.001,-0.001};
				double IO_LS_CP_p_BC[3] = {0.005,0.01,0.0125};   // MNET:1926-2 20060123 JHKIM
				double IO_LS_CP_n_BC[3] = {-0.005,-0.01,-0.0125};// MNET:1926-2 20060123 JHKIM
				double IO_LS_CP_p_W[3] = {0.004,0.006,0.0075};
				double IO_LS_CP_n_W[3] = {-0.004,-0.006,-0.0075};

				if(bWall) 
					for(int l=0; l<9; l++)
					{
						dTableY[l] = dTableY_W[l];
						dTableX[l] = dTableX_W[l];
					}
				else // Beam or Column
					for(int l=0; l<9; l++)
					{
						dTableY[l] = dTableY_BC[l];
						dTableX[l] = dTableX_BC[l];
					}

					if(bWall) 
						for(int l=0; l<3; l++)
						{
							IO_LS_CP_p[l] = IO_LS_CP_p_W[l];
							IO_LS_CP_n[l] = IO_LS_CP_n_W[l];
						}
					else // Beam or Column
						for(int l=0; l<3; l++)
						{
							IO_LS_CP_p[l] = IO_LS_CP_p_BC[l];
							IO_LS_CP_n[l] = IO_LS_CP_n_BC[l];
						}

						SetGhngPropData(data,dTableY,dTableX,IO_LS_CP_p,IO_LS_CP_n,TRUE, bMyOnly);

			} 
			else if(data.nHingeType == 3) // PMM
			{
				double dTableY[9] = {-0.2,-0.2,-1.1,-1,0,1,1.1,0.2,0.2};
				double dTableX[9] = {-0.025,-0.015,-0.015,0,0,0,0.015,0.015,0.025};
				double IO_LS_CP_p[3] = {0.0025,0.0075,0.015};
				double IO_LS_CP_n[3] = {-0.0025,-0.0075,-0.015};

				SetGhngPropData(data,dTableY,dTableX,IO_LS_CP_p,IO_LS_CP_n,TRUE,bMyOnly);
			}
		}
		else if(matl_d.Type.CompareNoCase(_T("S")) == 0)
		{
			if(data.nHingeType == 1) // Moment 
			{

				double dTableY[9] = {-0.4,-0.4,-1.195,-1,0,1,1.195,0.4,0.4};
				double dTableX[9] = {-9.5,-7.5,-7.5,-1,0,1,7.5,7.5,9.5};
				double IO_LS_CP_p[3] = {2.5,6,7.5};
				double IO_LS_CP_n[3] = {-2.5,-6,-7.5};

				SetGhngPropData(data,dTableY,dTableX,IO_LS_CP_p,IO_LS_CP_n);
			}
			else if(data.nHingeType == 2) // Shear
			{
				//double dTableY[9] = {-0.4,-0.4,-1.45,-1,0,1,1.45,0.4,0.4};
				double dTableY[9] = {-0.8,-0.8,-1.45,-1,0,1,1.45,0.8,0.8};// MNET:1926-3 20060123 JHKIM
				double dTableX[9] = {-18,-16,-16,-1,0,1,16,16,18};
				double IO_LS_CP_p[3] = {1.5,12,15};
				double IO_LS_CP_n[3] = {-1.5,-12,-15};

				SetGhngPropData(data,dTableY,dTableX,IO_LS_CP_p,IO_LS_CP_n);
			} 
			else if(data.nHingeType == 3) // PMM
			{
				double dTableY[9] = {-0.4,-0.4,-1.195,-1,0,1,1.195,0.4,0.4};
				double dTableX[9] = {-9.5,-7.5,-7.5,-1,0,1,7.5,7.5,9.5};
				double IO_LS_CP_p[3] = {2.5,6,7.5};
				double IO_LS_CP_n[3] = {-2.5,-6,-7.5};

				SetGhngPropData(data,dTableY,dTableX,IO_LS_CP_p,IO_LS_CP_n);
			}
		}
		else if(matl_d.Type.CompareNoCase(_T("USER")) == 0 || matl_d.Type.CompareNoCase(_T("A")) == 0 || matl_d.Type.CompareNoCase(_T("T")) == 0) //sjhuh-2013-09-30
		{
			GSaveHistoryFormatNF(_LS(IDS_DB_PUSHOVER_NO_USER_MATERIAL_ALLOWED));
			return FALSE;
		}
	} 
	return TRUE; 
}

void CAttrCtrl::SetGhngPropData(T_HNGT_D& data, double dTableY[9],double dTableX[9],
								double dIO_LS_CP_p[3],double dIO_LS_CP_n[3],
								BOOL bConvertPtoY, BOOL bMyOnly)
{
	// Y Axis
	for(int i=0; i<9; i++)
	{
		data.Prop.dForceMoment[0][i] = dTableY[i];
		data.Prop.dForceMoment[1][i] = dTableY[i];
	}

	// X Axis
	if(bConvertPtoY)
	{
		for(int i=0; i<4; i++) // Negative -E~-B
		{
			data.Prop.dDisplRotation[0][i] = -(dTableX[i] + data.Prop.dYieldRotation[1])/data.Prop.dYieldRotation[1]; // Yield Rotation - Y
			data.Prop.dDisplRotation[1][i] = -(dTableX[i] + data.Prop.dYieldRotation[3])/data.Prop.dYieldRotation[3]; // Yield Rotation - Z
		}
		for(int i=5; i<9; i++) // Positive B~E excluding A
		{
			data.Prop.dDisplRotation[0][i] = (dTableX[i] + data.Prop.dYieldRotation[0])/data.Prop.dYieldRotation[0]; // Yield Rotation + Y
			data.Prop.dDisplRotation[1][i] = (dTableX[i] + data.Prop.dYieldRotation[2])/data.Prop.dYieldRotation[2]; // Yield Rotation + Z
		}
	}
	else
	{
		for(int i=0; i<9; i++)
		{
			data.Prop.dDisplRotation[0][i] = dTableX[i];
			data.Prop.dDisplRotation[1][i] = dTableX[i];
		}
	}

	if(bConvertPtoY)
	{
		// 20050720, from 최원호(Wall, Beam인 경우 My, Mz의 max, min에서 My값만을 사용하도록 변경)
		double dTheta_p = data.Prop.dYieldRotation[0];
		double dTheta_n = data.Prop.dYieldRotation[1];
		if(!bMyOnly) // column
		{
			dTheta_p = __max(data.Prop.dYieldRotation[0],data.Prop.dYieldRotation[2]);
			dTheta_n = __min(data.Prop.dYieldRotation[1],data.Prop.dYieldRotation[3]);
		}

		data.Prop.dIO[0] =  (dIO_LS_CP_p[0] + dTheta_p)/dTheta_p;
		data.Prop.dLS[0] =  (dIO_LS_CP_p[1] + dTheta_p)/dTheta_p;
		data.Prop.dCP[0] =  (dIO_LS_CP_p[2] + dTheta_p)/dTheta_p;
		data.Prop.dIO[1] = -(dIO_LS_CP_n[0] + dTheta_n)/dTheta_n;
		data.Prop.dLS[1] = -(dIO_LS_CP_n[1] + dTheta_n)/dTheta_n;
		data.Prop.dCP[1] = -(dIO_LS_CP_n[2] + dTheta_n)/dTheta_n;
	}
	else
	{
		data.Prop.dIO[0] = dIO_LS_CP_p[0];
		data.Prop.dLS[0] = dIO_LS_CP_p[1];
		data.Prop.dCP[0] = dIO_LS_CP_p[2];
		data.Prop.dIO[1] = dIO_LS_CP_n[0];
		data.Prop.dLS[1] = dIO_LS_CP_n[1];
		data.Prop.dCP[1] = dIO_LS_CP_n[2];
	}

}

BOOL CAttrCtrl::SetGhngPropData2(_PUSH_MESH_DATA& p_m_d,T_HNGT_D& data,T_MATL_K matl_k,UINT prop_k,T_ELEM_K elem_k,int nPos)
{
	CPMVTStrength DesignParamModule;
	CPMInterCurve PMMParamModule;
	double Pn_pos,Pn_neg;
	double Dt_pos,Dt_neg;
	double Tn;
	double Phi;

	double Mny_pos,Mny_neg,Mnz_pos,Mnz_neg;
	double ThetaY_pos,ThetaY_neg,ThetaZ_pos,ThetaZ_neg;
	double Vny_pos,Vny_neg,Vnz_pos,Vnz_neg;
	double LamdaY_pos,LamdaY_neg,LamdaZ_pos,LamdaZ_neg;

	switch(data.nHingeType)
	{
	case 0: // Axial
		if(!DesignParamModule.Get_Pn(matl_k,prop_k,elem_k,nPos,Pn_pos,Pn_neg)) return FALSE;
		if(!DesignParamModule.Get_Delta(matl_k,prop_k,elem_k,Pn_pos,Dt_pos)) return FALSE;
		if(!DesignParamModule.Get_Delta(matl_k,prop_k,elem_k,Pn_neg,Dt_neg)) return FALSE;
		data.Prop.dYieldForce[0] = Pn_pos;
		data.Prop.dYieldForce[1] = Pn_neg;
		data.Prop.dYieldLength[0] = Dt_pos;
		data.Prop.dYieldLength[1] = Dt_neg;
		break;

	case 1: // Moment
		if(!DesignParamModule.Get_Mn(matl_k,prop_k,elem_k,nPos,p_m_d,Mny_pos,Mny_neg,Mnz_pos,Mnz_neg)) return FALSE;
		if(!DesignParamModule.Get_Theta(matl_k,prop_k,elem_k,Mny_pos,Mnz_pos,ThetaY_pos,ThetaZ_pos)) return FALSE;
		if(!DesignParamModule.Get_Theta(matl_k,prop_k,elem_k,Mny_neg,Mnz_neg,ThetaY_neg,ThetaZ_neg)) return FALSE;

		data.Prop.dYieldMoment[0] = Mny_pos;
		data.Prop.dYieldMoment[1] = Mny_neg;
		data.Prop.dYieldMoment[2] = Mnz_pos;
		data.Prop.dYieldMoment[3] = Mnz_neg;
		data.Prop.dYieldRotation[0] = ThetaY_pos;
		data.Prop.dYieldRotation[1] = ThetaY_neg;
		data.Prop.dYieldRotation[2] = ThetaZ_pos;
		data.Prop.dYieldRotation[3] = ThetaZ_neg;
		break;
	case 3: // PMM

		if(!PMMParamModule.Get_PMInterCurve(matl_k,prop_k,elem_k,nPos,!data.Prop.bUseCalcValue,p_m_d,data.Prop)) return FALSE;

		Mny_pos = data.Prop.dYieldMoment[0];
		Mny_neg = data.Prop.dYieldMoment[1];
		Mnz_pos = data.Prop.dYieldMoment[2];
		Mnz_neg = data.Prop.dYieldMoment[3];

		if(!DesignParamModule.Get_Theta(matl_k,prop_k,elem_k,Mny_pos,Mnz_pos,ThetaY_pos,ThetaZ_pos)) return FALSE;
		if(!DesignParamModule.Get_Theta(matl_k,prop_k,elem_k,Mny_neg,Mnz_neg,ThetaY_neg,ThetaZ_neg)) return FALSE;

		data.Prop.dYieldRotation[0] = ThetaY_pos;
		data.Prop.dYieldRotation[1] = ThetaY_neg;
		data.Prop.dYieldRotation[2] = ThetaZ_pos;
		data.Prop.dYieldRotation[3] = ThetaZ_neg;
		break;

	case 2: // Shear

		if(!DesignParamModule.Get_Vn(matl_k,prop_k,elem_k,nPos,Vny_pos,Vny_neg,Vnz_pos,Vnz_neg)) return FALSE;
		if(!DesignParamModule.Get_Lambda(matl_k,prop_k,elem_k,Vny_pos,Vnz_pos,LamdaY_pos,LamdaZ_pos)) return FALSE;
		if(!DesignParamModule.Get_Lambda(matl_k,prop_k,elem_k,Vny_neg,Vnz_neg,LamdaY_neg,LamdaZ_neg)) return FALSE;

		data.Prop.dYieldForce[0] = Vny_pos;
		data.Prop.dYieldForce[1] = Vny_neg;
		data.Prop.dYieldForce[2] = Vnz_pos;
		data.Prop.dYieldForce[3] = Vnz_neg;
		data.Prop.dYieldRotation[0] = LamdaY_pos;
		data.Prop.dYieldRotation[1] = LamdaY_neg;
		data.Prop.dYieldRotation[2] = LamdaZ_pos;
		data.Prop.dYieldRotation[3] = LamdaZ_neg;
		break;

	case 4: // Torsion

		if(!DesignParamModule.Get_Tn(matl_k,prop_k,elem_k,nPos,Tn)) return FALSE;
		if(!DesignParamModule.Get_Phi(matl_k,prop_k,elem_k,Tn,Phi)) return FALSE;
		data.Prop.dYieldMoment[0] = Tn;
		data.Prop.dYieldMoment[1] = -Tn;
		data.Prop.dYieldRotation[0] = Phi;
		data.Prop.dYieldRotation[1] = -Phi;
		break;
	}

	return TRUE;
}

