int CAttrCtrl::GetYscoPQElemK()
{
	T_YSCO_D YscoD;
	GetYsco(YscoD);
	if(!YscoD.bSelectElemStep)
		return 0;

	T_ELEM_K ElemK = YscoD.ElemK_Detail;
	T_ELEM_D ElemD;
	GetElem(ElemK, ElemD);

	// 이 요소에 PQ 타입 힌지가 할당되어있는지 확인
	T_PHGE_K PhgeK;
	PhgeK.key.type = IsBeam(ElemD.eltyp) ? 1:2;
	PhgeK.key.objK=YscoD.ElemK_Detail;
	T_PHGE_D PhgeD;
	if(!GetPhge(PhgeK,PhgeD))
		return 0;
	T_PHGT_D PhgtD;
	GetPhgt(PhgeD.HingeTypeK, PhgtD);
	if(PhgtD.nASInteractionType==0)
		return 0;

	return YscoD.ElemK_Detail;
}

int CAttrCtrl::GetYscoPQStep()
{
	T_YSCO_D YscoD;
	GetYsco(YscoD);
	if(!YscoD.bSelectElemStep)
		return 0;

	return YscoD.nStep_Detail;
}

