void CAttrCtrl::GetPordList(CArray<CString, CString&>& rstrNameList)
{
	rstrNameList.RemoveAll();

	T_PORD_D Data;
	CArray<T_PORD_K, T_PORD_K>KeyList;
	GetPordKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetPord(KeyList[i], Data))
			rstrNameList.Add(Data.Name);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetPordKeyList(CArray<T_PORD_K, T_PORD_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<CString, CString&>arName;

	POSITION pos;
	T_PORD_K Key;
	T_PORD_D Data;
	pos=GetStartPord();
	while(pos != NULL)
	{
		GetNextPord(pos, Key, Data);
		rKeyList.Add(Key);
		arName.Add(Data.Name);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortStringWithIndex(rKeyList.GetData(), arName.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::ExistPord(CString& rName)
{
	T_PORD_D data;
	return GetPord(rName, data);
}

BOOL CAttrCtrl::ExistPord(T_PORD_K Key)
{
	T_PORD_D Data;
	return m_pDataMemb->m_pord.Get(Key,Data);
}

BOOL CAttrCtrl::GetPord(CString& rName, T_PORD_D& rData)
{
	T_PORD_K key;
	T_PORD_D data;
	CString strName=rName;
	strName.TrimRight();

	POSITION pos=m_pDataMemb->m_pord.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_pord.GetNext(pos,key,data);
		if(strName.CompareNoCase(data.Name) == 0)
		{
			m_pUnitCtrl->ConvertUnitPordOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetPord(T_PORD_K Key,T_PORD_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_pord.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitPordOut(rData);
	return bReturn;
}

T_PORD_K CAttrCtrl::GetPordKey(CString& rName)
{
	T_PORD_K key;
	T_PORD_D data;

	POSITION pos=GetStartPord();
	while(pos != NULL)
	{
		GetNextPord(pos,key,data);
		if(rName.CompareNoCase(data.Name) == 0)return key;
	}
	key=0;
	return key;
}

