{
	return m_pDataMemb->m_pord.GetCount();
}

POSITION CAttrCtrl::GetStartPord()
{
	return m_pDataMemb->m_pord.GetStart();
}

void CAttrCtrl::GetNextPord(POSITION& rNextPosition,T_PORD_K& rKey,T_PORD_D& rData)
{
	m_pDataMemb->m_pord.GetNext(rNextPosition,rKey,rData);
	m_pUnitCtrl->ConvertUnitPordOut(rData);
}

T_PORD_K CAttrCtrl::GetLastNumPord()
{
	return m_pDataMemb->m_pord.m_nLastNum;
}

T_PORD_K CAttrCtrl::GetStartNumPord()
{
	return m_pDataMemb->m_pord.m_nStartNum;
}

T_PORD_K CAttrCtrl::GetNextNumPord(T_PORD_K StartNum)
{
	if(StartNum > GetLastNumPord())return StartNum;
	T_PORD_K Key=StartNum;
	T_PORD_D Data;
	while(TRUE)
	{
		Key++;
		if(!m_pDataMemb->m_pord.Get(Key,Data))return Key;
	}
}

////////////// ieth ////////////////
void CAttrCtrl::GetIethList(CArray<CString, CString&>& rstrIethList)
{
	rstrIethList.RemoveAll();

	int nCount=GetCountIeth();
	if(nCount == 0)return;

	POSITION pos;
	T_IETH_K Key;
	T_IETH_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartIeth();
		while(pos != NULL)
		{
			GetNextIeth(pos, Key, Data);
			if(Data.LoadCaseId == i)
			{
				rstrIethList.Add(Data.LoadCaseName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetIethKeyList(CArray<T_IETH_K, T_IETH_K>& rIethKeyList)
{
	rIethKeyList.RemoveAll();
	int nCount=GetCountIeth();
	if(nCount == 0)return;

	CArray<T_IETH_K, T_IETH_K> aIethKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rIethKeyList.SetSize(nCount);
	aIethKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_IETH_K Key;
	T_IETH_D Data;
	int i = 0;
	pos = GetStartIeth();
	while (pos != NULL)
	{
		GetNextIeth(pos, Key, Data);
		aIethKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.LoadCaseId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rIethKeyList[i] = aIethKey[ix];
	}
}

