////////////// iehp ////////////////
void CAttrCtrl::GetIehpList(CArray<CString, CString&>& rstrIehpList)
{
	rstrIehpList.RemoveAll();

	CArray<T_IEHP_K, T_IEHP_K> aIehpK;
	GetIehpKeyList(aIehpK);
	T_IEHP_D IehpD;
	for(int i=0; i<aIehpK.GetSize(); i++)
	{    
		if(!GetIehp(aIehpK[i],IehpD))
			continue;

		rstrIehpList.Add(IehpD.strName);
	}
}

void CAttrCtrl::GetIehpKeyList(CArray<T_IEHP_K, T_IEHP_K>& rIehpKeyList)
{
	rIehpKeyList.RemoveAll();
	int nCount=GetCountIehp();
	if(nCount == 0)return;

	CArray<T_IEHP_K, T_IEHP_K> aIehpKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rIehpKeyList.SetSize(nCount);
	aIehpKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_IEHP_K Key;
	T_IEHP_D Data;
	int i = 0;
	pos = GetStartIehp();
	while (pos != NULL)
	{
		GetNextIehp(pos, Key, Data);
		aIehpKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nSeq;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rIehpKeyList[i] = aIehpKey[ix];
	}
}

BOOL CAttrCtrl::ExistIehp(CString& rstrName)
{
	T_IEHP_D data;
	return GetIehp(rstrName, data);
}

BOOL CAttrCtrl::ExistIehp(T_IEHP_K Key)
{
	T_IEHP_D data;
	return GetIehp(Key, data);
}

BOOL CAttrCtrl::GetIehp(CString& rstrName, T_IEHP_D& rData)
{
	T_IEHP_K key;
	T_IEHP_D data;
	CString strName=rstrName;
	strName.TrimRight();

	POSITION pos=m_pDataMemb->m_iehp.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_iehp.GetNext(pos,key,data);
		if(strName.CompareNoCase(data.strName) == 0)
		{
			m_pUnitCtrl->ConvertUnitIehpOut(data, data.AllProp.PROP, TRUE);
			m_pUnitCtrl->ConvertUnitIehpOut(data, data.AllSubProp.PROP, FALSE);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetIehp(T_IEHP_K Key, T_IEHP_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_iehp.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitIehpOut(rData,rData.AllProp.PROP, TRUE);
	if(bReturn)m_pUnitCtrl->ConvertUnitIehpOut(rData,rData.AllSubProp.PROP, FALSE);
	return bReturn;
}

const T_IEHP_D* CAttrCtrl::GetIehpConstPtr(T_IEHP_K Key)
{
	return m_pDataMemb->m_iehp.GetConstPtr(Key);
}

T_IEHP_K CAttrCtrl::GetIehpKey(CString& rstrName)
{
	T_IEHP_K key;
	T_IEHP_D data;

	POSITION pos=GetStartIehp();
	while(pos != NULL)
	{
		GetNextIehp(pos,key,data);
		if(rstrName.CompareNoCase(data.strName) == 0)return key;
	}
	key=0;
	return key;
}

