			dCrkMnus = pHM->dCrackMoment[1];
			dYldPlus = pHM->dYieldMoment[0];
			dYldMnus = pHM->dYieldMoment[1];
			dUltPlus = pHM->dUltimateMoment[0];
			dUltMnus = pHM->dUltimateMoment[1];
			dDisp1Plus = pHM->dYieldRotn1st[0];
			dDisp1Mnus = pHM->dYieldRotn1st[1];
			dDisp2Plus = pHM->dYieldRotn2nd[0];
