T_IEHG_K CAttrCtrl::MakeElemIehgK(T_ELEM_K ElemK)
{
	T_IEHG_K IehgK;

	T_ELEM_D ElemD;
	GetElem(ElemK, ElemD);
	switch (ElemD.eltyp)
	{
	case BEAM_EL: IehgK.key.type = D_IEHG_TYPE_BEAMCOLUMN; break;
	case TRUSS_EL: IehgK.key.type = D_IEHG_TYPE_TRUSS; break;
	case WALL_EL: IehgK.key.type = D_IEHG_TYPE_WALL; break;
	}

	IehgK.key.objK = ElemK;
	return IehgK;
}

bool CAttrCtrl::ConvertNlnk2IehgBeforeNS(const T_NLNK_K& NlnkK, T_IEHG_K& IehgK, T_IEHG_D& IehgD) const
{
	T_NLNK_D NlnkD;
	if (!m_pDoc->m_pAttrCtrl->GetNlnk(NlnkK, NlnkD))
	{
		ASSERT(0); return false;
	}
	if (NlnkD.IehpKey == 0)
	{
		return false;
	}

	IehgK.key.type = D_IEHG_TYPE_GLINK;
	IehgK.key.objK = NlnkK;
	IehgD.IehpKey = NlnkD.IehpKey;

	return true;
}

T_IEHP_K CAttrCtrl::GetIehpKeyByIehgObj(const int& nType, T_KEY ObjKey)
{
	T_IEHG_K IehgK;
	T_IEHG_D IehgD;
	if (!GetIehgObj(nType, ObjKey, IehgK, IehgD))
	{
		return 0;
	}

	return IehgD.IehpKey;
}

