void CAttrCtrl::ConvertTriModel_AlphaToEpsilon(double dS1, double dS2, double dS3, double dK1, double dK2K1, double dK3K1, double& dE1, double& dE2, double& dE3)
{
	dE1 = 0.0;
	dE2 = 0.0;
	dE3 = 0.0;

	double dK2 = dK2K1 * dK1;
	double dK3 = dK3K1 * dK1;

	if (dK1 == 0. || dK2 == 0. || dK3 == 0.) return;

	if (dK1 == 0.) dE1 = 0.;
	else dE1 = dS1 / dK1;
	if (dK2 == 0.) dE2 = dE1;
	else dE2 = dE1 + (dS2 - dS1) / dK2;
	if (dK3 == 0.) dE3 = 0.;
	else dE3 = dE2 + (dS3 - dS2) / dK3;

}


