void CAttrCtrl::CalcFiberAreaConsiderRebar(CArray<T_FIBR_BASE, T_FIBR_BASE&>& aFibrBase)
{
	// Rebar 전체 Area를  Rebar 를 포함하는 Fiber 수만큼 나누어서... 그 Fiber 에서 빼줌.. 결과적으로 Fiber 총 합에서 Rebar Area 만큼 빠지는 결과가 나옴
	
	CArray<T_FIBR_BASE*, T_FIBR_BASE*> aRebar;
	CArray<T_FIBR_BASE*, T_FIBR_BASE*> aFiber;
	int nSize;
	nSize = aFibrBase.GetSize();
	for (int i = 0; i < nSize ; i++)
	{
		if(aFibrBase[i].bRebar)
		{
			aRebar.Add(&aFibrBase[i]);
		}
		else
		{
			aFiber.Add(&aFibrBase[i]);
		}
	}

	std::set<int> setRebarFiberIdx;
	int nRebarFiberNum;
	nRebarFiberNum = 0;
	nSize = aFiber.GetSize();
	for(int i = 0; i < nSize; i++)
	{
		if(IsRebarFiber(*aFiber[i], aRebar))
		{
			setRebarFiberIdx.insert(i);
			nRebarFiberNum++;
		}
	}

	if(nRebarFiberNum == 0)
	{
		nSize = aFiber.GetSize();
		for(int i = 0; i < nSize; i++)
		{
			aFiber[i]->dAreaConsiderRebar = aFiber[i]->dArea;
		}

		return;
	}

	double dRebarAreaShare = 0.0;
	nSize = aRebar.GetSize();
	for(int i = 0; i < nSize; i++)
	{
		dRebarAreaShare += aRebar[i]->dArea;
	}
	dRebarAreaShare /= (double)nRebarFiberNum;

	nSize = aFiber.GetSize();
	for(int i = 0; i < nSize; i++)
	{
		aFiber[i]->dAreaConsiderRebar = aFiber[i]->dArea;
		if(setRebarFiberIdx.find(i) != setRebarFiberIdx.end())
		{
			aFiber[i]->dAreaConsiderRebar -= dRebarAreaShare; 
		}
	}
}

T_FIBW_K CAttrCtrl::GetFibwKeyByWallID(int WallID, T_STOR_K StorK, int nAssignType)
{
	CArray<T_FIBW_K, T_FIBW_K> aFibwK;
	GetFibwKeyList(aFibwK);
	int nCount = aFibwK.GetSize();
	if (nCount == 0)return 0;

	T_FIBW_D Data;
	for (int i = 0; i < nCount; i++)
	{
		T_FIBW_K Key = aFibwK[i];
		
		if (!GetFibw(Key, Data)) { ASSERT(0); continue; }
			if (Data.nAssignType == nAssignType && Data.nWallID == WallID && Data.StorK == StorK)
			return Key;
	}
	
	return 0;
}

BOOL CAttrCtrl::IsRebarFiber(const T_FIBR_BASE& Fiber, CArray<T_FIBR_BASE*, T_FIBR_BASE*>& aRebar)
{
	//return TRUE;
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	double dZero = pDoc->m_pInitCtrl->GetPreferenceRegardZero();

	//Step1. Rebar 와 Fiber 의 선이 만나면 TRUE	(선과 점의 길이로 계산하면 Rebar 보다 Mesh 가 작은경우도 계산이 됨. Mesh Size가 작으면 에러처리 하므로 거의 발생할일 없는 상황이기도 함)
	T_POINT2D CentP;
	double dDia, dDist;	
	int nSize, nSizeJ;
	nSize = aRebar.GetSize();
	double dIdxTo;
	for (int i = 0; i < nSize ; i++)
	{
		const T_FIBR_BASE& Rebar = *aRebar[i];		
		dDia = sqrt(Rebar.dArea / CMathFunc::m_pi);

		ASSERT(Fiber.aPointY.GetSize() == Fiber.aPointZ.GetSize());

		nSizeJ = Fiber.aPointY.GetSize();
		for (int j = 0; j < nSizeJ ; j++)
		{	
			dIdxTo = j + 1;
			if(j == nSizeJ - 1)
			{
				dIdxTo = 0;
			}
			dDist = CMathFunc::mathDistanceToLine2D(Fiber.aPointY[j], Fiber.aPointZ[j], Fiber.aPointY[dIdxTo], Fiber.aPointZ[dIdxTo], Rebar.dCenterY, Rebar.dCenterZ);
			if(dDist < dDia || fabs(dDist - dDia) < dZero)
			{
				return TRUE;
			}
		}
	}

	//Step2. Rebar 가 Fiber 안에 들어가면 TRUE
	int nV = Fiber.aPointY.GetSize();
	double (*coor2D)[2];
	coor2D = new double[nV][2];
	for(int i=0 ; i<nV ; i++)
	{
		coor2D[i][0] = Fiber.aPointY[i];
		coor2D[i][1] = Fiber.aPointZ[i];
	}
	T_POINT2D BoundingBox[2];
	BoundingBox[0].x = DBL_MAX;
	BoundingBox[0].y = DBL_MAX;
	BoundingBox[1].x = -DBL_MAX;
	BoundingBox[1].y = -DBL_MAX;
	for(int i=0 ; i<nV ; i++)
	{
		if(BoundingBox[0].x > coor2D[i][0])
		{
			BoundingBox[0].x = coor2D[i][0];
		}
		if(BoundingBox[0].y > coor2D[i][1])
		{
			BoundingBox[0].y = coor2D[i][1];
		}

		if(BoundingBox[1].x < coor2D[i][0])
		{
			BoundingBox[1].x = coor2D[i][0];
		}
		if(BoundingBox[1].y < coor2D[i][1])
		{
			BoundingBox[1].y = coor2D[i][1];
		}
	}

	double dPRebar[2];
	nSize = aRebar.GetSize();
	for (int i = 0; i < nSize ; i++)
	{
		const T_FIBR_BASE& Rebar = *aRebar[i];		
		CentP.x = Rebar.dCenterY;
		CentP.y = Rebar.dCenterZ;

		// 조금이라도 더 빠르게 계산하기 위해서 CMathFunc::mathIsInsidePoint2D 를 부르기 전에 Bounding Box 체크부터 함
		if(BoundingBox[0].x > CentP.x && fabs(BoundingBox[0].x - CentP.x) > dZero) continue;
		if(BoundingBox[0].y > CentP.y && fabs(BoundingBox[0].y - CentP.y) > dZero) continue;
		if(BoundingBox[1].x < CentP.x && fabs(BoundingBox[1].x - CentP.x) > dZero) continue;
		if(BoundingBox[1].y < CentP.y && fabs(BoundingBox[1].y - CentP.y) > dZero) continue;

		dPRebar[0] = CentP.x;
		dPRebar[1] = CentP.y;
		if(CMathFunc::mathIsInsidePoint2D(dPRebar, nV, coor2D, FALSE))
		{
			return TRUE;
		}
	}

	delete [] coor2D;

	return FALSE;
}

