int CAttrCtrl::GetCountFibw(int nAssignType/*=-1*/)
{
	if(nAssignType<0)
		return m_pDataMemb->m_fibw.GetCount();

	int nCount = 0;
	auto Pair = m_pDataMemb->m_fibw.PGetFirstAssoc();
	while (Pair != NULL)
	{
		if(Pair->value.nAssignType== nAssignType)
			nCount++;
		Pair = m_pDataMemb->m_fibw.PGetNext(Pair);
	}
	return nCount;
}

