void CAttrCtrl::GetStagList(CArray<CString, CString&>& rstrStageList)
{
	rstrStageList.RemoveAll();

	int nCount=GetCountStag();
	if(nCount == 0)return;

	POSITION pos;
	T_STAG_K Key;
	T_STAG_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartStag();
		while(pos != NULL)
		{
			GetNextStag(pos, Key, Data);
			if(Data.nStageId == i)
			{
				rstrStageList.Add(Data.StageName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetStagKeyList(CArray<T_STAG_K, T_STAG_K>& rStagKeyList)
{
	/*
	rStagKeyList.RemoveAll();

	int nCount=GetCountStag();
	if(nCount == 0)return;

	POSITION pos;
	T_STAG_K Key;
	T_STAG_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartStag();
	while(pos != NULL)
	{
	GetNextStag(pos, Key, Data);
	if(Data.nStageId == i)
	{
	rStagKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rStagKeyList.RemoveAll();
	int nCount=GetCountStag();
	if(nCount == 0)return;

	CArray<T_STAG_K, T_STAG_K> aStagKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rStagKeyList.SetSize(nCount);
	aStagKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_STAG_K Key;
	T_STAG_D Data;
	int i = 0;
	pos = GetStartStag();
	while (pos != NULL)
	{
		GetNextStag(pos, Key, Data);
		aStagKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nStageId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rStagKeyList[i] = aStagKey[ix];
	}
}

