BOOL CAttrCtrl::IsConstStag(T_STAG_K Key, T_STAG_D& rData)
{
	T_HSTG_K HstgKey = MakeHstgKeyFromStagKey(Key);
	T_HSTG_D HstgData;
	if (Key <= D_HSTG_STAG_START_KEY) return TRUE;
	if (!GetHstg(HstgKey, HstgData)) return TRUE;
	if (HstgData.StageName != rData.StageName) return TRUE;
	if (HstgData.aStep.GetSize() != rData.aUserDefStep.GetSize()) return TRUE;
	if (HstgData.aActiveElem.GetSize() != rData.aActiveElem.GetSize()) return TRUE;
	if (HstgData.aActiveBndr.GetSize() != rData.aActiveBndr.GetSize()) return TRUE;
	if (HstgData.aDeactiveBndr.GetSize() != rData.aDeactiveBndr.GetSize()) return TRUE;
	if (HstgData.nStageId != rData.nStageId) return TRUE;
	return FALSE;
}

void CAttrCtrl::GetStagCurActiveGr(T_STAG_D& StagData,
								   CMap<T_GRUP_K, T_GRUP_K, UINT, UINT>& mapGrup,
								   CMap<T_BNGR_K, T_BNGR_K, UINT, UINT>& mapBngr,
								   CMap<T_LDGR_K, T_LDGR_K, UINT, UINT>& mapLdgr )
{
	mapGrup.RemoveAll();
	mapBngr.RemoveAll();
	mapLdgr.RemoveAll();

	int  nNum;
	nNum = StagData.aActiveElem.GetSize();
	for(int i = 0; i < nNum; i++)
		mapGrup.SetAt(StagData.aActiveElem[i].GrupKey, 0);
	nNum = StagData.aActiveBndr.GetSize();
	for(int i = 0; i < nNum; i++)
		mapBngr.SetAt(StagData.aActiveBndr[i].BngrKey, 0);
	nNum = StagData.aActiveLoad.GetSize();
	for(int i = 0; i < nNum; i++)
		mapLdgr.SetAt(StagData.aActiveLoad[i].LdgrKey, 0);
}

void CAttrCtrl::GetStagActiveGr(int nStageId, 
								CMap<T_GRUP_K, T_GRUP_K, UINT, UINT>& mapGrup,
								CMap<T_BNGR_K, T_BNGR_K, UINT, UINT>& mapBngr,
								CMap<T_LDGR_K, T_LDGR_K, UINT, UINT>& mapLdgr )
{
	mapGrup.RemoveAll();
	mapBngr.RemoveAll();
	mapLdgr.RemoveAll();

	int i, nNum;
	T_STAG_D StagData;
	CArray<T_STAG_K, T_STAG_K> aStagKey;
	m_pDoc->m_pAttrCtrl->GetStagKeyList(aStagKey);
	int nSize = aStagKey.GetSize();
	for (int n = 0; n < nSize; n++)
	{
		GetStag(aStagKey[n], StagData);
		if (StagData.nStageId > nStageId) break;

		nNum = StagData.aActiveElem.GetSize();
		for( i = 0; i < nNum; i++)
			mapGrup.SetAt(StagData.aActiveElem[i].GrupKey, 0);
		nNum = StagData.aDeactiveElem.GetSize();
		for( i = 0; i < nNum; i++)
			mapGrup.RemoveKey(StagData.aDeactiveElem[i].GrupKey);

		nNum = StagData.aActiveBndr.GetSize();
		for( i = 0; i < nNum; i++)
			mapBngr.SetAt(StagData.aActiveBndr[i].BngrKey, 0);
		nNum = StagData.aDeactiveBndr.GetSize();
		for( i = 0; i < nNum; i++)
			mapBngr.RemoveKey(StagData.aDeactiveBndr[i]);

		nNum = StagData.aActiveLoad.GetSize();
		for( i = 0; i < nNum; i++)
			mapLdgr.SetAt(StagData.aActiveLoad[i].LdgrKey, 0);
		nNum = StagData.aDeactiveLoad.GetSize();
		for( i = 0; i < nNum; i++)
			mapLdgr.RemoveKey(StagData.aDeactiveLoad[i].LdgrKey);
	}
}

void CAttrCtrl::GetStagActiveList(int nStageId, T_STAG_D& rStagData,
								  CArray<T_NODE_K, T_NODE_K>* paNode,
								  CArray<T_ELEM_K, T_ELEM_K>* paElem,
								  CArray<T_BNGR_K, T_BNGR_K>* paBngr,
								  CArray<T_LDGR_K, T_LDGR_K>* paLdgr)
{
	T_STAG_K CurStag = m_pDoc->m_pStagCtrl->GetCurStag();
	m_pDoc->m_pStagCtrl->ChangeCurStagWithoutUpdateNotify(0);

	CMap<T_NODE_K, T_NODE_K, int, int> mapNode;
	CMap<T_ELEM_K, T_ELEM_K, int, int> mapElem;
	CMap<T_BNGR_K, T_BNGR_K, int, int> mapBngr;
	CMap<T_LDGR_K, T_LDGR_K, int, int> mapLdgr;

	if (paNode) 
	{
		paNode->RemoveAll();
		mapNode.InitHashTable(HASHSIZENODE);
	}
	if (paElem) 
	{
		paElem->RemoveAll();
		// 뒤에서
	}
	if (paBngr) 
	{
		paBngr->RemoveAll();
		mapBngr.InitHashTable(HASHSIZEBNGR);
	}
	if (paLdgr) 
	{
		paLdgr->RemoveAll();
		mapLdgr.InitHashTable(HASHSIZELDGR);
	}
	if (paNode || paElem) 
	{
		mapElem.InitHashTable(HASHSIZEELEM);
	}

	int i;
	int nTemp;
	int nActiveNum, nDeactiveNum;
	int nNodeNum, nElemNum;
	POSITION pos;

	T_STAG_D StagData;
	CArray<T_STAG_K, T_STAG_K> aStagKey;

	T_NODE_K NodeKey;
	T_ELEM_K ElemKey;

	T_GRUP_D GrupData;
	T_ELEM_D ElemData;

	m_pDoc->m_pAttrCtrl->GetStagKeyList(aStagKey);
	int nSize = aStagKey.GetSize();
	for (int n = 0; n < nSize+1; n++)
	{
		if (n == nSize) StagData = rStagData;
		else 
		{
			GetStag(aStagKey[n], StagData);
			if (StagData.nStageId > nStageId) 
			{
				StagData = rStagData;
				n = nSize;  // 다음 루프에서 루프 탈출하도록 설정
			}
		}

		if (paNode || paElem)
		{
			// 새로 Active된 요소를 map에 추가한다.
			nActiveNum = StagData.aActiveElem.GetSize();
			for (int j = 0; j < nActiveNum; j++)
			{
				GetGrup(StagData.aActiveElem[j].GrupKey, GrupData);

				if (paNode)
				{
					nNodeNum = GrupData.arKeyNode.GetSize();
					for (int k = 0; k < nNodeNum; k++)
						mapNode.SetAt(GrupData.arKeyNode[k], 0);
				}
				if (paNode || paElem)
				{
					nElemNum = GrupData.arKeyElem.GetSize();
					for (int k = 0; k < nElemNum; k++)
						mapElem.SetAt(GrupData.arKeyElem[k], 0);
				}
			}

			// Deactive된 요소를 map에서 제거한다.
			nDeactiveNum = StagData.aDeactiveElem.GetSize();
			for (int j = 0; j < nDeactiveNum; j++)
			{
				GetGrup(StagData.aDeactiveElem[j].GrupKey, GrupData);

				if (paNode)
				{
					nNodeNum = GrupData.arKeyNode.GetSize();
					for (int k = 0; k < nNodeNum; k++)
						mapNode.RemoveKey(GrupData.arKeyNode[k]);
				}
				if (paNode || paElem)
				{
					nElemNum = GrupData.arKeyElem.GetSize();
					for (int k = 0; k < nElemNum; k++)
						mapElem.RemoveKey(GrupData.arKeyElem[k]);
				}
			}

			// 요소에 사용된 절점 모두 Active
			if (paNode)
			{
				pos = mapElem.GetStartPosition();
				while (pos)
				{
					mapElem.GetNextAssoc(pos, ElemKey, nTemp);
					GetElem(ElemKey, ElemData);
					for (int i = 0; i < D_ELEM_MAXNOD; i++)
						if (ElemData.elnod[i] != 0) mapNode.SetAt(ElemData.elnod[i], 0);
				}
			}
		}

		if (paBngr)
		{
			nActiveNum = StagData.aActiveBndr.GetSize();
			for(int i = 0; i < nActiveNum; i++)
				mapBngr.SetAt(StagData.aActiveBndr[i].BngrKey, 0);
			nDeactiveNum = StagData.aDeactiveBndr.GetSize();
			for(int i = 0; i < nDeactiveNum; i++)
				mapBngr.RemoveKey(StagData.aDeactiveBndr[i]);
		}

		if (paLdgr)
		{
			nActiveNum = StagData.aActiveLoad.GetSize();
			for(int i = 0; i < nActiveNum; i++)
				mapLdgr.SetAt(StagData.aActiveLoad[i].LdgrKey, 0);
			nDeactiveNum = StagData.aDeactiveLoad.GetSize();
			for(int i = 0; i < nDeactiveNum; i++)
				mapLdgr.RemoveKey(StagData.aDeactiveLoad[i].LdgrKey);
		}
	}

	if (paNode)
	{
		pos = mapNode.GetStartPosition();
		while (pos)
		{
			mapNode.GetNextAssoc(pos, NodeKey, nTemp);
			if (ExistNode(NodeKey)) paNode->Add(NodeKey);
		}
		qsort(paNode->GetData(), paNode->GetSize(), sizeof(T_NODE_K), CCompFunc::UINTAsc);
	}
	if (paElem)
	{
		pos = mapElem.GetStartPosition();
		while (pos)
		{
			mapElem.GetNextAssoc(pos, ElemKey, nTemp);
			if (ExistElem(ElemKey)) paElem->Add(ElemKey);
		}
		qsort(paElem->GetData(), paElem->GetSize(), sizeof(T_ELEM_K), CCompFunc::UINTAsc);
	}
	if (paBngr)
	{
		T_BNGR_K BngrKey;
		T_BNGR_D BngrData;
		CArray<T_UINT_POS, T_UINT_POS&> aKeyId;
		aKeyId.SetSize(mapBngr.GetCount());
		i = 0;
		pos = mapBngr.GetStartPosition();
		while (pos)
		{
			mapBngr.GetNextAssoc(pos, BngrKey, nTemp);
			GetBngr(BngrKey, BngrData);
			aKeyId[i].uINT = BngrKey;
			aKeyId[i].nPos = BngrData.nGroupId;
			i++;
		}
		if (aKeyId.GetSize() > 0)
		{
			qsort(aKeyId.GetData(), aKeyId.GetSize(), sizeof(T_UINT_POS), T_UINT_POS::CompByPOS);
			paBngr->SetSize(aKeyId.GetSize());
			for(int i = 0; i < aKeyId.GetSize(); i++)
				paBngr->SetAt(i, aKeyId[i].uINT);
		}
	}
	if (paLdgr)
	{
		T_LDGR_K LdgrKey;
		T_LDGR_D LdgrData;
		CArray<T_UINT_POS, T_UINT_POS&> aKeyId;
		aKeyId.SetSize(mapLdgr.GetCount());
		i = 0;
		pos = mapLdgr.GetStartPosition();
		while (pos)
		{
			mapLdgr.GetNextAssoc(pos, LdgrKey, nTemp);
			GetLdgr(LdgrKey, LdgrData);
			aKeyId[i].uINT = LdgrKey;
			aKeyId[i].nPos = LdgrData.nGroupId;
			i++;
		}
		if (aKeyId.GetSize() > 0)
		{
			qsort(aKeyId.GetData(), aKeyId.GetSize(), sizeof(T_UINT_POS), T_UINT_POS::CompByPOS);
			paLdgr->SetSize(aKeyId.GetSize());
			for(int i = 0; i < aKeyId.GetSize(); i++)
				paLdgr->SetAt(i, aKeyId[i].uINT);
		}
	}

	m_pDoc->m_pStagCtrl->ChangeCurStagWithoutUpdateNotify(CurStag);
}

BOOL CAttrCtrl::GetStagStepInfo(T_STAG_K Key, T_STAG_STEP_INFO& rStepInfo)
{
	T_STAG_D Stag;
	if (!GetStag(Key, Stag)) return FALSE;

	T_STCT_D StctD; StctD.Initialize();
	if(!GetStct(StctD)) StctD.Initialize();

	rStepInfo.Initialize();
	rStepInfo.StagKey = Key;
	rStepInfo.dDuration = Stag.dDuration;
	rStepInfo.dDurationInfo = Stag.dDuration; // dDuration=0.0 이더라도 First, Last 구분이 필요해서 dDurationInfo 사용
	rStepInfo.bSaveResultStage = Stag.bSaveResultStage;
	rStepInfo.bSaveResultStep = Stag.bSaveResultStep;

#ifdef _MEC
	rStepInfo.bIncreStep = TRUE;
	rStepInfo.nIncreStep = StctD.NlCtrl.nNumOfIncre;
	if (StctD.nIncludeNonLinearAnalysis == D_STCT_NL_ANAL_MATERIAL || StctD.nIncludeNonLinearAnalysis == D_STCT_NL_ANAL_GEOM_MAT)
	{
		if (Stag.bIncreStep)
			rStepInfo.nIncreStep = Stag.nIncreStep;
	}
#else
	if(StctD.nIncludeNonLinearAnalysis == D_STCT_NL_ANAL_MATERIAL)
	{
		rStepInfo.bIncreStep = TRUE;
		if(Stag.bIncreStep) rStepInfo.nIncreStep = Stag.nIncreStep;
		else                rStepInfo.nIncreStep = StctD.nNumLoadStep;
	}
#endif
	rStepInfo.aInfo.RemoveAll();

	T_STAG_STEP_INFO_BASE sinfo;
	sinfo.Initialize();
	sinfo.nStepType = 0;

	CMap<double, double, int, int> mapDayStep;
	mapDayStep.InitHashTable(11);

	// fist
	sinfo.dDay = 0.0;
	rStepInfo.aInfo.Add(sinfo);
	mapDayStep.SetAt(sinfo.dDay, 0);

	// user
	int nUserDefStep = Stag.aUserDefStep.GetSize();
	for (int i = 0; i < nUserDefStep; i++)
	{
		sinfo.dDay = Stag.aUserDefStep[i];
		rStepInfo.aInfo.Add(sinfo);
		mapDayStep.SetAt(sinfo.dDay, i+1);
	}
	// last
	sinfo.dDay = Stag.dDuration;
	rStepInfo.aInfo.Add(sinfo);
	mapDayStep.SetAt(-1.0, -1);

	int nStepIx;
	// load step(active)
	int nLoad = Stag.aActiveLoad.GetSize();
	for(int i = 0; i < nLoad; i++)
	{
		VERIFY(mapDayStep.Lookup(Stag.aActiveLoad[i].dDay, nStepIx));
		if (nStepIx == -1) nStepIx = nUserDefStep+1;  // last step
		rStepInfo.aInfo[nStepIx].nStepType = 1;  // 하중에 의한 step으로 설정
		rStepInfo.aInfo[nStepIx].aActiveLdgrKey.Add(Stag.aActiveLoad[i].LdgrKey);
	}
	// load step(deactive)
	nLoad = Stag.aDeactiveLoad.GetSize();
	for(int i = 0; i < nLoad; i++)
	{
		VERIFY(mapDayStep.Lookup(Stag.aDeactiveLoad[i].dDay, nStepIx));
		if (nStepIx == -1) nStepIx = nUserDefStep+1;  // last step
		rStepInfo.aInfo[nStepIx].nStepType = 1;  // 하중에 의한 step으로 설정
		rStepInfo.aInfo[nStepIx].aDeactiveLdgrKey.Add(Stag.aDeactiveLoad[i].LdgrKey);
	}

	int nStep = rStepInfo.aInfo.GetSize();

	if (rStepInfo.dDuration == 0.0)
	{
		BOOL bFirst = FALSE;
		BOOL bLast  = FALSE;
		nLoad = Stag.aActiveLoad.GetSize();
		for (int i = 0; i < nLoad; i++)
		{
			if (Stag.aActiveLoad[i].dDay ==  0.0) bFirst = TRUE;
			if (Stag.aActiveLoad[i].dDay == -1.0) bLast = TRUE;
		}
		nLoad = Stag.aDeactiveLoad.GetSize();
		for (int i = 0; i < nLoad; i++)
		{
			if (Stag.aDeactiveLoad[i].dDay ==  0.0) bFirst = TRUE;
			if (Stag.aDeactiveLoad[i].dDay == -1.0) bLast = TRUE;
		}

		if (bFirst && bLast)
		{
			rStepInfo.dDurationInfo = 1.0;
		}
	}

	if (rStepInfo.dDurationInfo == 0.0)
	{
		ASSERT(nStep == 2); // First, Last만
		sinfo = rStepInfo.aInfo[1];
		for(int i = 0; i < sinfo.aActiveLdgrKey.GetSize(); i++)
			rStepInfo.aInfo[0].aActiveLdgrKey.Add(sinfo.aActiveLdgrKey[i]);
		for(int i = 0; i < sinfo.aDeactiveLdgrKey.GetSize(); i++)
			rStepInfo.aInfo[0].aDeactiveLdgrKey.Add(sinfo.aDeactiveLdgrKey[i]);
		if (sinfo.nStepType == 1) rStepInfo.aInfo[0].nStepType = 1;
		rStepInfo.aInfo.RemoveAt(1);  // delete last
	}

	BOOL bOrgStag = ExistConstStag();
	if (!bOrgStag)  // last, first 제거
	{
		ASSERT(nStep > 2);
		rStepInfo.aInfo.RemoveAt(nStep-1);  // last
		rStepInfo.aInfo.RemoveAt(0);  // first
	}

	return TRUE;
}

BOOL CAttrCtrl::GetFirstResultStag(T_STAG_K& rKey)
{
	T_STAG_D StagData;
	CArray<T_STAG_K, T_STAG_K> aStagKey;
	GetStagKeyList(aStagKey);
	int nStage = aStagKey.GetSize();
	for (int i = 0; i < nStage; i++)
	{
		GetStag(aStagKey[i], StagData);
		if (StagData.bSaveResultStage) 
		{
			rKey = aStagKey[i];
			return TRUE;
		}
	}
	rKey = D_MIN_MAX_STAGE_KEY;
	return TRUE;
}

BOOL CAttrCtrl::GetFirstResultStep(T_STAG_K Key, int& nStep)
{
	if (Key == D_MIN_MAX_STAGE_KEY)
	{
		nStep = 0;
		return TRUE;
	}
	T_STAG_STEP_INFO StepInfo;
	if (!GetStagStepInfo(Key, StepInfo)) return FALSE;
	if (!StepInfo.bSaveResultStage) return FALSE;
	//if (StepInfo.bSaveResultStep) nStep = 1;
	//else nStep = StepInfo.aInfo.GetSize();
	nStep = StepInfo.aInfo.GetSize();
	return TRUE;
}

BOOL CAttrCtrl::GetLastResultStag(T_STAG_K& rKey)
{
	T_STAG_D StagData;
	CArray<T_STAG_K, T_STAG_K> aStagKey;
	GetStagKeyList(aStagKey);
	int nStage = aStagKey.GetSize();
	for (int i = nStage-1; i >= 0; i--)
	{
		GetStag(aStagKey[i], StagData);
		if (StagData.bSaveResultStage) 
		{
			rKey = aStagKey[i];
			return TRUE;
		}
	}
	rKey = D_MIN_MAX_STAGE_KEY;
	return TRUE;
}

BOOL CAttrCtrl::GetLastResultStep(T_STAG_K Key, int& nStep)
{
	if (Key == D_MIN_MAX_STAGE_KEY)
	{
		nStep = 0;
		return TRUE;
	}
	T_STAG_STEP_INFO StepInfo;
	if (!GetStagStepInfo(Key, StepInfo)) return FALSE;
	if (!StepInfo.bSaveResultStage) return FALSE;
	nStep = StepInfo.aInfo.GetSize();
	return TRUE;
}

BOOL CAttrCtrl::GetStepSaveFlag(T_STAG_K Key, int nStepNo, BOOL& bSaveFlag)
{
	T_STAG_STEP_INFO StepInfo;
	if (!GetStagStepInfo(Key, StepInfo)) return FALSE;
	return GetStepSaveFlag(StepInfo, nStepNo, bSaveFlag);
}

BOOL CAttrCtrl::GetStepSaveFlag(T_STAG_STEP_INFO& rStepInfo, int nStepNo, BOOL& bSaveFlag)
{
	if (nStepNo < 1 || nStepNo > rStepInfo.aInfo.GetSize()) return FALSE;

	if (nStepNo == rStepInfo.aInfo.GetSize()) bSaveFlag = rStepInfo.bSaveResultStage;
	else bSaveFlag = rStepInfo.bSaveResultStep;
	return TRUE;
}

T_STAG_K CAttrCtrl::GetFinalStag()
{
	if (!ExistConstStag()) 
	{
		// Hydration Stage가 있으면 마지막 Stage 번호
		if (GetCountHstg() != 0) 
		{
			T_HHCT_D HhctData;
			if (GetHhct(HhctData))
			{
				if (HhctData.nFinalStage == 1)  // 특정 Stage
					return MakeStagKeyFromHstgKey(HhctData.FinalHstgKey);
			}
			// 마지막 Stage
			return m_pDataMemb->m_stag.GetLastStag();
		}
		else return 0;
	}

	T_STCT_D StctData;
	if (GetStct(StctData))
	{
		if (StctData.nFinalStage == 1)  // 특정 Stage
			return StctData.FinalStagKey;
	}
	// 마지막 Stage
	return m_pDataMemb->m_stag.GetLastStag();
}

T_STAG_K CAttrCtrl::GetLastStagByUser()
{
	// 사용자 입력 마지막 Stage
	return m_pDataMemb->m_stag.GetLastStag();
}

BOOL CAttrCtrl::MakeElemRedistributionMap(CMap<T_ELEM_K, T_ELEM_K, double, double>& rElemRedistributionMap)
{
	T_STAG_K CurStag = m_pDoc->m_pStagCtrl->GetCurStag();
	if (CurStag == 0) return FALSE;
	T_STAG_D StagData;
	if (!GetStag(CurStag, StagData)) return FALSE;
	rElemRedistributionMap.RemoveAll();

	double dRedistribution;
	T_GRUP_D GrupData;
	for (int i = 0; i < StagData.aDeactiveElem.GetSize(); i++)
	{
		if (!GetGrup(StagData.aDeactiveElem[i].GrupKey, GrupData)) return FALSE;
		for (int j = 0; j < GrupData.arKeyElem.GetSize(); j++)
		{
			if (ExistElem(GrupData.arKeyElem[j])) continue;
			if (rElemRedistributionMap.Lookup(GrupData.arKeyElem[j], dRedistribution)) continue;
			rElemRedistributionMap.SetAt(GrupData.arKeyElem[j], StagData.aDeactiveElem[i].dRedistribution);
		}
	}
	return TRUE;
}

T_STAG_K CAttrCtrl::MakeStagKeyFromHstgKey(T_HSTG_K Key)
{
	return Key + D_HSTG_STAG_START_KEY;
}

T_HSTG_K CAttrCtrl::MakeHstgKeyFromStagKey(T_STAG_K Key)
{
	return Key - D_HSTG_STAG_START_KEY;
}

CString CAttrCtrl::GetStageStepName(T_STAG_K Key, int nCurStep)
{
	CString strStep;

	T_STAG_STEP_INFO stage_info;
	if(!GetStagStepInfo(Key, stage_info)) return strStep;		

	int nIncreStep = 1;
	if(stage_info.bIncreStep) nIncreStep = stage_info.nIncreStep;

	div_t div_result;
	div_result = div( nCurStep, nIncreStep );

	int nquot = div_result.quot;
	int nrem = div_result.rem;

	if(nIncreStep == 1)
	{
		if(stage_info.bSaveResultStep && stage_info.dDurationInfo > 0.0)
		{
			if(nCurStep == 1)	strStep = _LS(IDS_DB_SGLD_FIRST);
			else if(nCurStep < stage_info.aInfo.GetSize()-1)
				strStep.Format(_T("%s_%d"),_LS(IDS_DB_SGLD_USER),nCurStep-1);
		}
		if(nCurStep == stage_info.aInfo.GetSize())
			strStep = _LS(IDS_DB_SGLD_LAST);
	}
	else
	{
		if(stage_info.bSaveResultStep && stage_info.dDurationInfo > 0.0)
		{
			if(nquot == 1)
			{
				strStep.Format(_T("%s-%d"),_LS(IDS_DB_SGLD_FIRST), nrem);
			}
			else if(nquot<stage_info.aInfo.GetSize()-1)
			{
				strStep.Format(_T("%s_%d-%d"),_LS(IDS_DB_SGLD_USER), nCurStep-1, nrem);
			}
		}
		if(nquot == stage_info.aInfo.GetSize())
		{
			strStep.Format(_T("%s-%d"),_LS(IDS_DB_SGLD_LAST), nrem);
		}
	}

	return strStep;
}

void CAttrCtrl::GetDummyStage(CArray<BOOL, BOOL>& aDummyStage)
{
	aDummyStage.RemoveAll();

	BOOL bHydration=FALSE;
	if(m_pDoc->m_pAttrCtrl->GetCountHstg() > 0) bHydration=TRUE;
	if(bHydration) return;

	BOOL bDummyStage = FALSE;
	T_STCT_D DataStct;
	if(!m_pDoc->m_pAttrCtrl->GetStct(DataStct))DataStct.Initialize();

	int nInitTangentDisp = 0; // 0 = All, 1 = Group

	if (DataStct.nIncludeNonLinearAnalysis == 0 && DataStct.nNonlAnalType == 1) // Linear Analysis & Accumulative Stage
	{
		if (DataStct.bInitTangentDisp)
		{
			bDummyStage = TRUE;
			nInitTangentDisp = DataStct.nInitTangentDisp;
		}
	}
	else if (DataStct.nIncludeNonLinearAnalysis == 1 && DataStct.nNonlAnalType == 1) // Non Linear Analysis & Accumulative Stage
	{
		// Non Linear Analysis & Accumulative Stage 이 경우면 사용자 입력과 상관없이 All Type 으로 Dummy Stage 생성
		bDummyStage = TRUE;
		nInitTangentDisp = 0;
	}

	if (bDummyStage)
	{
		CArray<T_STAG_K, T_STAG_K> aStagK;
		m_pDoc->m_pAttrCtrl->GetStagKeyList(aStagK);

		int nTemp = 0;
		T_STAG_D StagD;
		T_GRUP_D GrupD;

		T_NODE_K NodeK;
		T_ELEM_K ElemK;
		T_ELEM_D ElemD;

		POSITION pos;

		CMap<UINT, UINT, int, int> *pmGrupNode;
		CMap<UINT, UINT, int, int> *pmGrupElem;
		CMap<UINT, UINT, int, int> *pmActiveNodePre;
		CMap<UINT, UINT, int, int> *pmActiveNodeCur;
		CMap<UINT, UINT, int, int> *pmActiveElemCur;

		pmGrupNode = new CMap<UINT, UINT, int, int>;
		pmGrupElem = new CMap<UINT, UINT, int, int>;
		pmActiveNodePre = new CMap<UINT, UINT, int, int>;
		pmActiveNodeCur = new CMap<UINT, UINT, int, int>;
		pmActiveElemCur = new CMap<UINT, UINT, int, int>;
		pmGrupNode->InitHashTable(HASHSIZENODE);
		pmGrupElem->InitHashTable(HASHSIZEELEM);
		pmActiveNodePre->InitHashTable(HASHSIZENODE);
		pmActiveNodeCur->InitHashTable(HASHSIZENODE);
		pmActiveElemCur->InitHashTable(HASHSIZEELEM);

		if (nInitTangentDisp == 1) // Group
		{
			pmGrupNode->RemoveAll();
			pmGrupElem->RemoveAll();

			// Group 에 사용된 절점, 요소를 map에 추가한다.
			m_pDoc->m_pAttrCtrl->GetGrup(DataStct.KeyGrup, GrupD);

			for (int k = 0; k < GrupD.arKeyNode.GetSize(); k++)
				pmGrupNode->SetAt(GrupD.arKeyNode[k], 0);
			for (int k = 0; k < GrupD.arKeyElem.GetSize(); k++)
				pmGrupElem->SetAt(GrupD.arKeyElem[k], 0);

			// 요소에 사용된 절점 모두 Active
			pos = pmGrupElem->GetStartPosition();
			while (pos)
			{
				pmGrupElem->GetNextAssoc(pos, ElemK, nTemp);
				if (!m_pDoc->m_pAttrCtrl->GetElem(ElemK, ElemD)) { ASSERT(0); continue; }

				for (int k = 0; k < D_ELEM_MAXNOD; k++)
				{
					if (ElemD.elnod[k] != 0)
					{
						if (!pmGrupNode->Lookup(ElemD.elnod[k], nTemp))
							pmGrupNode->SetAt(ElemD.elnod[k], 0);
					}
				}
			}
		}

		pmActiveNodePre->RemoveAll();

		for (int i = 0; i < aStagK.GetSize(); i++)
		{
			if (!m_pDoc->m_pAttrCtrl->GetStag(aStagK[i], StagD)) { ASSERT(0); continue; }

			pmActiveNodeCur->RemoveAll();
			pmActiveElemCur->RemoveAll();

			// Active된 절점, 요소를 map에 추가한다.
			int nActiveNum = StagD.aActiveElem.GetSize();
			for (int j = 0; j < nActiveNum; j++)
			{
				m_pDoc->m_pAttrCtrl->GetGrup(StagD.aActiveElem[j].GrupKey, GrupD);

				for (int k = 0; k < GrupD.arKeyNode.GetSize(); k++)
					pmActiveNodeCur->SetAt(GrupD.arKeyNode[k], 0);
				for (int k = 0; k < GrupD.arKeyElem.GetSize(); k++)
					pmActiveElemCur->SetAt(GrupD.arKeyElem[k], 0);
			}

			// 요소에 사용된 절점 모두 Active
			pos = pmActiveElemCur->GetStartPosition();
			while (pos)
			{
				pmActiveElemCur->GetNextAssoc(pos, ElemK, nTemp);
				if (!m_pDoc->m_pAttrCtrl->GetElem(ElemK, ElemD)) { ASSERT(0); continue; }

				for (int k = 0; k < D_ELEM_MAXNOD; k++)
				{
					if (ElemD.elnod[k] != 0)
					{
						if (!pmActiveNodeCur->Lookup(ElemD.elnod[k], nTemp))
							pmActiveNodeCur->SetAt(ElemD.elnod[k], 0);
					}
				}
			}

			if (i == 0)
			{
				aDummyStage.Add(FALSE);
			}
			else
			{
				BOOL bFind = FALSE;

				if (nInitTangentDisp == 0) // All
				{
					pos = pmActiveNodeCur->GetStartPosition();
					while (pos)
					{
						pmActiveNodeCur->GetNextAssoc(pos, NodeK, nTemp);

						if (pmActiveNodePre->Lookup(NodeK, nTemp)) continue;

						bFind = TRUE;
						break;
					}

					aDummyStage.Add(bFind);
				}
				else
				{
					// Initial Tangent Displacement for Erected Structures 과 비교
					pos = pmGrupNode->GetStartPosition();
					while (pos)
					{
						pmGrupNode->GetNextAssoc(pos, NodeK, nTemp);

						if (pmActiveNodePre->Lookup(NodeK, nTemp)) continue;
						if (pmActiveNodeCur->Lookup(NodeK, nTemp))
						{
							bFind = TRUE;
							break;
						}
					}

					aDummyStage.Add(bFind);
				}
			}

			// 이전 단계에 Update
			pos = pmActiveNodeCur->GetStartPosition();
			while (pos)
			{
				pmActiveNodeCur->GetNextAssoc(pos, NodeK, nTemp);

				if (!pmActiveNodePre->Lookup(NodeK, nTemp))
					pmActiveNodePre->SetAt(NodeK, 0);
			}
		}
	}
}

void CAttrCtrl::CheckStageSelfWeightData(BOOL bSamePos /*= FALSE*/)
{
	CMap <T_BODF_K, T_BODF_K, T_LDGR_K, T_LDGR_K> mapBodf;
	mapBodf.InitHashTable(7);

	//T_STAG_K StagKey;
	T_STAG_D StagData;
	CArray<T_STAG_K, T_STAG_K> aStagKey;
	int nActiveNum;
	int nDeactiveNum;
	T_KEY2 StagLdgrKey;
	T_LIST_DATA ListData;
	LdgrList *pList;
	POSITION pos;

	BOOL bChkBodf = FALSE;

	m_pDoc->m_pAttrCtrl->GetStagKeyList(aStagKey);
	int nStagCount = aStagKey.GetSize();
	for (int i = 0; i < nStagCount; i++)
	{
		StagLdgrKey.k1 = aStagKey[i];
		m_pDoc->m_pAttrCtrl->GetStag(StagLdgrKey.k1, StagData);
		nActiveNum = StagData.aActiveLoad.GetSize();
		for (int j = 0; j < nActiveNum; j++)
		{
			StagLdgrKey.k2 = StagData.aActiveLoad[j].LdgrKey;
			m_pDoc->m_memb->m_ldgr.GetList(StagLdgrKey.k2, pList);
			pos = pList->GetHeadPosition();
			while (pos)
			{
				ListData = pList->GetNext(pos);
				switch (ListData.nCmd)
				{
				case LT_BODF_CMD:
					mapBodf.SetAt(ListData.nKey, StagLdgrKey.k2);
					break;
				default:
					break;

				}
			}
		} // nActiveNum

		nDeactiveNum = StagData.aDeactiveLoad.GetSize();
		for (int j = 0; j < nDeactiveNum; j++)
		{
			StagLdgrKey.k2 = StagData.aDeactiveLoad[j].LdgrKey;
			m_pDoc->m_memb->m_ldgr.GetList(StagLdgrKey.k2, pList);
			pos = pList->GetHeadPosition();
			while (pos)
			{
				ListData = pList->GetNext(pos);
				switch (ListData.nCmd)
				{
				case LT_BODF_CMD:
					T_BODF_K  BodfKTemp;
					if (mapBodf.Lookup(ListData.nKey, BodfKTemp))
					{
						bChkBodf = TRUE;
					}
				default:
					break;

				}
			}
		}
	}

	if (bChkBodf)
	{
		if (bSamePos)
		{
			GSaveHistoryFormatNFSamePos(_LS(IDS_DB_STAGE_BODF_WARNING));
		}
		else         
		{
			GSaveHistoryFormatNF(_LS(IDS_DB_STAGE_BODF_WARNING));
			GSaveHistoryFormatNF(_T("")); // 메세지 남기기 위함.
		}
	}
}


////////////// tdmf ////////////////
void CAttrCtrl::GetTdmfList(CArray<CString, CString&>& rstrTdmfList)
{
	rstrTdmfList.RemoveAll();

	int nCount=GetCountTdmf();
	if(nCount == 0)return;

	POSITION pos;
	T_TDMF_K Key;
	T_TDMF_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartTdmf();
		while(pos != NULL)
		{
			GetNextTdmf(pos, Key, Data);
			if(Data.nMatlFuncId == i)
			{
				rstrTdmfList.Add(Data.MatlFuncName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetTdmfKeyList(CArray<T_TDMF_K, T_TDMF_K>& rTdmfKeyList)
{
	/*
	rKeyList.RemoveAll();

	int nCount=GetCountTdmf();
	if(nCount == 0)return;

	POSITION pos;
	T_TDMF_K Key;
	T_TDMF_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartTdmf();
	while(pos != NULL)
	{
	GetNextTdmf(pos, Key, Data);
	if(Data.nMatlFuncId == i)
	{
	rKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rTdmfKeyList.RemoveAll();
	int nCount=GetCountTdmf();
	if(nCount == 0)return;

	CArray<T_TDMF_K, T_TDMF_K> aTdmfKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rTdmfKeyList.SetSize(nCount);
	aTdmfKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_TDMF_K Key;
	T_TDMF_D Data;
	int i = 0;
	pos = GetStartTdmf();
	while (pos != NULL)
	{
		GetNextTdmf(pos, Key, Data);
		aTdmfKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nMatlFuncId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rTdmfKeyList[i] = aTdmfKey[ix];
	}
}

