// nCode : CEB-FIP(0)   Korean Standard(1)   Chinese Standard(2)   Japanese Standard(3)
BOOL CAttrCtrl::calcNotationalSize(int nCode, double dA, CArray<T_ELEM_K, T_ELEM_K>& aElemList, CArray<double, double>& aNotSize)
{
	aNotSize.RemoveAll();
	int nElem=aElemList.GetSize();
	if(nElem == 0)return FALSE;

	T_ELEM_D DataElem;
	T_SECT_D DataSect;
	int i = 0;
	for(i=0; i<nElem; i++)
	{
		if(!GetElem(aElemList[i], DataElem))goto BAD;
		if(!IsNeedSect(DataElem.eltyp))goto BAD;
		// nCalcOption(PSC단면계산시간절약을위한) : =0:단면치수만 계산  =1:Torsion을 뺀 나머지 계산 2:정상적인 강성계산을 함 ; PSC단면이외에는 1, 2 동일
		if(!m_pDoc->calcElemSect(aElemList[i], DataSect, 1, FALSE))goto BAD;
		int nSecType=DataSect.nStype;
		double dPeri_I=0., dPeri_J=0., dArea_I=0., dArea_J=0.;
		switch(nSecType)
		{
		case D_SECT_TYPE_REGULAR:
		case D_SECT_TYPE_USER:
		case D_SECT_TYPE_COLDFORMED:
		case D_SECT_TYPE_PSC:
		case D_SECT_TYPE_STLG_B:
		case D_SECT_TYPE_STLG_I:
		case D_SECT_TYPE_STLG_MCELL:
			dArea_I = dArea_J = DataSect.SectBefore.SectI.Stiffness.Area;
			dPeri_I = dPeri_J = DataSect.SectBefore.SectI.PeriIn*dA+DataSect.SectBefore.SectI.PeriOut;
			break;
		case D_SECT_TYPE_SRC:
			dArea_I = dArea_J = DataSect.SectBefore.SectJ.Stiffness.Area; // concrete 단면적 사용.
			dPeri_I = dPeri_J = DataSect.SectBefore.PeriIn*dA+DataSect.SectBefore.PeriOut;
			break;
		case D_SECT_TYPE_COMBINED:
		case D_SECT_TYPE_COMPO_B:
		case D_SECT_TYPE_COMPO_I:
		case D_SECT_TYPE_COMPO_TUB:	
		case D_SECT_TYPE_COMPO_STLG_B:
		case D_SECT_TYPE_COMPO_STLG_I:
		case D_SECT_TYPE_COMPO_STLG_TUB:	
		case D_SECT_TYPE_COMPO_CI:
		case D_SECT_TYPE_COMPO_CT:
		case D_SECT_TYPE_COMPO_PC:
		case D_SECT_TYPE_COMPO_G:
			dArea_I = dArea_J = DataSect.SectBefore.Stiffness.Area;
			dPeri_I = dPeri_J = DataSect.SectBefore.PeriIn*dA+DataSect.SectBefore.PeriOut;
			break;
		case D_SECT_TYPE_TAPERED:
		case D_SECT_TYPE_TAP_REG:  //시공단면일 경우 
		case D_SECT_TYPE_TAP_USER: // 시공단면일 경우
			// MNET:3964-CJJEONG-20090320 (Tel : 2124) 
			// Tapered 에 Composite General 을 추가하기 위해 처리
			if (nSecType==D_SECT_TYPE_TAPERED && DataSect.SectBefore.nStype==D_SECT_TYPE_COMPO_G) goto BAD;
			dArea_I = DataSect.SectBefore.SectI.Stiffness.Area;
			dPeri_I = DataSect.SectBefore.SectI.PeriIn*dA+DataSect.SectBefore.SectI.PeriOut;
			dArea_J = DataSect.SectBefore.SectJ.Stiffness.Area;
			dPeri_J = DataSect.SectBefore.SectJ.PeriIn*dA+DataSect.SectBefore.SectJ.PeriOut;
			break;
		default: 
			ASSERT(FALSE);
			goto BAD;
			break;
		}
		// 일본기준에서 h=Ac/u, 나머지 기준에서는 h=2*Ac/u
		double h_I=0., h_J=0., dCoef=0;
		if(nCode == 3) dCoef=1.;    // 일본기준
		else           dCoef=2.;    
		if(dPeri_I != 0.)h_I=dCoef*dArea_I/dPeri_I;
		if(dPeri_J != 0.)h_J=dCoef*dArea_J/dPeri_J;
		//GSaveHistoryFormatNF("Element No.=%6d, Section No.=%4d, Area=%10g,%10g, Perimeter=%10g,%10g, h(2Ac/u)=%10g,%10g", 
		//  aElemList[i], DataElem.elpro, dArea_I, dArea_J, dPeri_I, dPeri_J, h_I, h_J);
		aNotSize.Add((h_I+h_J)*0.5);
	}
	return TRUE;
BAD:
	//GSaveHistoryFormatNF("Element No.=%6d, Section No.=%4d, Area=%10g,%10g, Perimeter=%10g,%10g, h(2Ac/u)=%10g,%10g", 
	//  aElemList[i], DataElem.elpro, dArea_I, dArea_J, dPeri_I, dPeri_J, h_I, h_J);
	GSaveHistoryFormatNF(_LS(IDS_DB_ATTRCTRL_____CalcNotationalSizeErrorMessage),aElemList[i]);
	return FALSE;
}

