////////////// mpct ////////////////
void CAttrCtrl::GetMpctList(CArray<CString, CString&>& rstrMpctList)
{
	rstrMpctList.RemoveAll();

	int nCount=GetCountMpct();
	if(nCount == 0)return;

	POSITION pos;
	T_MPCT_K Key;
	T_MPCT_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartMpct();
		while(pos != NULL)
		{
			GetNextMpct(pos, Key, Data);
			if(Data.nSeq == i)
			{
				rstrMpctList.Add(Data.strName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetMpctKeyList(CArray<T_MPCT_K, T_MPCT_K>& rMpctKeyList)
{
	rMpctKeyList.RemoveAll();
	int nCount=GetCountMpct();
	if(nCount == 0)return;

	CArray<T_MPCT_K, T_MPCT_K> aMpctKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rMpctKeyList.SetSize(nCount);
	aMpctKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_MPCT_K Key;
	T_MPCT_D Data;
	int i = 0;
	pos = GetStartMpct();
	while (pos != NULL)
	{
		GetNextMpct(pos, Key, Data);
		aMpctKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nSeq;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rMpctKeyList[i] = aMpctKey[ix];
	}
}

BOOL CAttrCtrl::ExistMpct(CString& rstrName)
{
	T_MPCT_D data;
	return GetMpct(rstrName, data);
}

BOOL CAttrCtrl::ExistMpct(T_MPCT_K Key)
{
	T_MPCT_D data;
	return GetMpct(Key, data);
}

BOOL CAttrCtrl::GetMpct(CString& rstrName, T_MPCT_D& rData)
{
	T_MPCT_K key;
	T_MPCT_D data;
	CString strName=rstrName;
	strName.TrimRight();

	POSITION pos=m_pDataMemb->m_mpct.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_mpct.GetNext(pos,key,data);
		if(strName.CompareNoCase(data.strName) == 0)
		{
			m_pUnitCtrl->ConvertUnitMpctOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetMpct(T_MPCT_K Key, T_MPCT_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_mpct.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitMpctOut(rData);
	return bReturn;
}

T_MPCT_K CAttrCtrl::GetMpctKey(CString& rstrName)
{
	T_MPCT_K key;
	T_MPCT_D data;

	POSITION pos=GetStartMpct();
	while(pos != NULL)
	{
		GetNextMpct(pos,key,data);
		if(rstrName.CompareNoCase(data.strName) == 0)return key;
	}
	key=0;
	return key;
}

