void CAttrCtrl::GetMgdrList(CArray<CString, CString&>& rstrGirderList)
{
	rstrGirderList.RemoveAll();

	T_MGDR_D Data;
	CArray<T_MGDR_K, T_MGDR_K>KeyList;
	GetMgdrKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetMgdr(KeyList[i], Data))
			rstrGirderList.Add(Data.Name);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetMgdrKeyList(CArray<T_MGDR_K, T_MGDR_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<int, int>aSeq;

	POSITION pos;
	T_MGDR_K Key;
	T_MGDR_D Data;
	pos=GetStartMgdr();
	while(pos != NULL)
	{
		GetNextMgdr(pos, Key, Data);
		rKeyList.Add(Key);
		aSeq.Add(Data.nSeq);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortIntWithIndex((int*)rKeyList.GetData(), aSeq.GetData(), rKeyList.GetSize());
}

