void CAttrCtrl::GetGilcKeyListFromBaseDB(CArray<T_GILC_K, T_GILC_K>& rGilcKeyList)
{
	rGilcKeyList.RemoveAll();
	int nCount=GetCountGilc();
	if(nCount == 0)return;

	CArray<T_GILC_K, T_GILC_K> aGilcKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rGilcKeyList.SetSize(nCount);
	aGilcKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_GILC_K Key;
	T_GILC_D Data;
	int i = 0;
	pos = m_pDataMemb->m_gilc.GetStartFromBaseDB();
	while (pos != NULL)
	{
		m_pDataMemb->m_gilc.GetNextFromBaseDB(pos, Key, Data);
		aGilcKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.LoadCaseId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rGilcKeyList[i] = aGilcKey[ix];
	}
}

BOOL CAttrCtrl::GetGilcFromBaseDB(T_GILC_K Key, T_GILC_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_gilc.GetFromBaseDB(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitGilcOut(rData);
	return bReturn;
}

void CAttrCtrl::GetGilcList(CArray<CString, CString&>& rstrGilcList)
{
	rstrGilcList.RemoveAll();

	int nCount=GetCountGilc();
	if(nCount == 0)return;

	POSITION pos;
	T_GILC_K Key;
	T_GILC_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartGilc();
		while(pos != NULL)
		{
			GetNextGilc(pos, Key, Data);
			if(Data.LoadCaseId == i)
			{
				rstrGilcList.Add(Data.LoadCaseName);
				break;
			}
		}
	}
}

