BOOL CAttrCtrl::IsGilcMaxMinType(T_GILC_D& rGilcD)
{
	// 활하중은 MaxMin Type, 사하중은 Single Type
	if (rGilcD.nLoadCaseType == 0 || rGilcD.nLoadCaseType == 1) return FALSE;
	return TRUE;
}

