void CAttrCtrl::GetNextGild(POSITION& rNextPosition,T_GILD_K& rKey,T_GILD_D& rData)
{
	m_pDataMemb->m_gild.GetNext(rNextPosition,rKey,rData);
	m_pUnitCtrl->ConvertUnitGildOut(rData);
}

void CAttrCtrl::GetGildLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, T_GILD_K KeyGild, T_GILD_D& rData)
{
	rData.Initialize();
	if (!CheckLcomLabelGilc(bAllLoadCase, DataLcom)) return;
	if (!GetGild(KeyGild, rData)) return;

	if(bAllLoadCase)
	{
		return;
	}
	else
	{
		double dGilcFactor = 0.0;
		if (!GetLcomGilcFactor(KeyGild, DataLcom, dGilcFactor))return;
		if (dGilcFactor == 0.0) { rData.Initialize(); return; }
		if (dGilcFactor == 1.0) return;
		for (int i = 0; i < rData.aData.GetSize(); i++)
		{
			rData.aData[i].dLoad *= dGilcFactor;
			rData.aData[i].dStartLoad *= dGilcFactor;
			rData.aData[i].dEndLoad *= dGilcFactor;
		}
	}
	return;  
}

void CAttrCtrl::GetGildKeyList(CArray<T_GILD_K, T_GILD_K>& raKeyList)
{
	GetGilcKeyList(raKeyList);
	for (int i = raKeyList.GetSize()-1; i >= 0; i--)
		if (!ExistGild(raKeyList[i])) raKeyList.RemoveAt(i);
	return;
}

