void CAttrCtrl::GetBspnKeyList(CArray<T_BSPN_K, T_BSPN_K>& rKeyList)
{
	rKeyList.RemoveAll();

	int nCount=GetCountBspn();
	if(nCount == 0)return;

	POSITION pos;
	T_BSPN_K Key;
	T_BSPN_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartBspn();
		while(pos != NULL)
		{
			GetNextBspn(pos, Key, Data);
			if(Data.nSeq == i)
			{
				rKeyList.Add(Key);
				break;
			}
		}
	}
}

