BOOL CAttrCtrl::GetMovingElemData4Cjfg(BOOL& bForce, int& nForcFilter, T_GRUP_K& ForcGrupK)
{
	ForcGrupK = 0;
	bForce = FALSE;
	nForcFilter = 0;  // 0=All 1=Group;

	T_MVCT_D   rData;    rData.Initialize();
	T_MVCTjp_D rData_jp; rData_jp.Initialize();
	T_MVCTch_D rData_ch; rData_ch.Initialize();
	T_MVCTid_D rData_id; rData_id.Initialize();
	T_MVCTtr_D rData_tr; rData_tr.Initialize();
	T_MVCTbs_D rData_bs; rData_bs.Initialize();
	T_MVCTfr_D rData_fr; rData_fr.Initialize();

	if      (GetMvct(rData))      { bForce = rData.bStressCalcFrame;	nForcFilter = rData.nForcFilter;     ForcGrupK = rData.ForcGrup;    }
	else if (GetMvctjp(rData_jp)) { bForce = rData_jp.bStressCalcFrame;	nForcFilter = rData_jp.nForcFilter;  ForcGrupK = rData_jp.ForcGrup; }
	else if (GetMvctch(rData_ch)) { bForce = rData_ch.bStressCalcFrame;	nForcFilter = rData_ch.nForcFilter;  ForcGrupK = rData_ch.ForcGrup; }
	else if (GetMvctid(rData_id)) { bForce = rData_id.bStressCalcFrame;	nForcFilter = rData_id.nForcFilter;  ForcGrupK = rData_id.ForcGrup; }
	else if (GetMvcttr(rData_tr)) { bForce = rData_tr.bCombinedStress;	nForcFilter = 0;                     ForcGrupK = 0;                 }
	else if (GetMvctbs(rData_bs)) { bForce = rData_bs.bStressCalcFrame;	nForcFilter = rData_bs.nForcFilter;  ForcGrupK = rData_bs.ForcGrup; }
	else if (GetMvctfr(rData_fr)) { bForce = rData_fr.bStressCalcFrame;	nForcFilter = rData_fr.nForcFilter;  ForcGrupK = rData_fr.ForcGrup; }

	return TRUE;
}

////////////// cref ////////////////

void CAttrCtrl::GetCrefList(CArray<CString, CString&>& rstrReferenceList)
{
	rstrReferenceList.RemoveAll();

	T_CREF_D Data;
	CArray<T_CREF_K, T_CREF_K>KeyList;
	GetCrefKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetCref(KeyList[i], Data))
			rstrReferenceList.Add(Data.Name);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetCrefKeyList(CArray<T_CREF_K, T_CREF_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<int, int>aSeq;

	POSITION pos;
	T_CREF_K Key;
	T_CREF_D Data;
	pos=GetStartCref();
	while(pos != NULL)
	{
		GetNextCref(pos, Key, Data);
		rKeyList.Add(Key);
		aSeq.Add(Data.nSeq);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortIntWithIndex((int*)rKeyList.GetData(), aSeq.GetData(), rKeyList.GetSize());
}

BOOL CAttrCtrl::ExistCref(CString& rReferenceName)
{
	T_CREF_D data;
	return GetCref(rReferenceName, data);
}

BOOL CAttrCtrl::ExistCref(T_CREF_K Key)
{
	T_CREF_D Data;
	return m_pDataMemb->m_cref.Get(Key,Data);
}

BOOL CAttrCtrl::GetCref(CString& rReferenceName, T_CREF_D& rData)
{
	T_CREF_K key;
	T_CREF_D data;
	CString strReferenceName=rReferenceName;
	strReferenceName.TrimRight();

	POSITION pos=m_pDataMemb->m_cref.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_cref.GetNext(pos,key,data);
		if(strReferenceName.CompareNoCase(data.Name) == 0)
		{
			m_pUnitCtrl->ConvertUnitCrefOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetCref(T_CREF_K Key,T_CREF_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_cref.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitCrefOut(rData);
	return bReturn;
}

T_CREF_K CAttrCtrl::GetCrefKey(CString& rReferenceName)
{
	T_CREF_K key;
	T_CREF_D data;

	POSITION pos=GetStartCref();
	while(pos != NULL)
	{
		GetNextCref(pos,key,data);
		if(rReferenceName.CompareNoCase(data.Name) == 0)return key;
	}
	key=0;
	return key;
}

