void CAttrCtrl::GetSpanLengthByElementLength(T_SPAN_D& SpanD, CArray<double, double>& aElemSpan)
{
	aElemSpan.RemoveAll();

	int nElem=SpanD.aElemBase.GetSize();

	BOOL bJEnd = FALSE;
	double dTotLength=0.;
	for(int i=0; i<nElem; ++i)
	{
		double dLength=m_pDoc->calcLAVElem(SpanD.aElemBase[i].ElemK);
		if(SpanD.aElemBase[i].nSupport==1 && i>0 && !bJEnd)
		{
			if(dTotLength>0.) aElemSpan.Add(dTotLength);
			dTotLength = 0.0;
		}
		dTotLength += dLength;
		bJEnd = FALSE;
		if(SpanD.aElemBase[i].nSupport==2)
		{
			if(dTotLength>0.) aElemSpan.Add(dTotLength);
			dTotLength = 0.0;
			bJEnd = TRUE;
		}
	}
	if(dTotLength>0.) aElemSpan.Add(dTotLength);
}

