void CAttrCtrl::GetSpavList(CArray<CString, CString&>& rstrSpavList)
{
	rstrSpavList.RemoveAll();

	T_SPAV_D Data;
	CArray<T_SPAV_K, T_SPAV_K>KeyList;
	GetSpavKeyList(KeyList);
	int nCount = KeyList.GetSize();
	for (int i = 0; i < nCount; i++)
	{
		if (GetSpav(KeyList[i], Data))
			rstrSpavList.Add(Data.Name);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetSpavKeyList(CArray<T_SPAV_K, T_SPAV_K>& rKeyList, int nSectType)
{
	rKeyList.RemoveAll();
	CArray<int, int>aSeq;

	POSITION pos;
	T_SPAV_K Key;
	T_SPAV_D Data;
	pos = GetStartSpav();
	while (pos != NULL)
	{
		GetNextSpav(pos, Key, Data);
		if (nSectType == Data.nSectType)
		{
			rKeyList.Add(Key);
			aSeq.Add(Data.nSeq);
		}
	}
	if (rKeyList.GetSize() > 0)CQSort::QSortIntWithIndex((int*)rKeyList.GetData(), aSeq.GetData(), rKeyList.GetSize());
}

