void CAttrCtrl::GetSpanOrSpavKeyList(CArray<T_SPAV_K, T_SPAV_K>& rKeyList, BOOL bVirtual/* = FALSE*/)
{
	if (bVirtual)
	{
		GetSpavKeyList(rKeyList);
	}
	else
	{
		GetSpanKeyList(rKeyList);
	}
}

BOOL CAttrCtrl::GetSpanOrSpav(T_SPAN_K Key, T_SPAN_D& rData, BOOL bVirtual/* = FALSE*/)
{
	BOOL bRet = FALSE;
	if (bVirtual)
	{
		T_SPAV_D SpavD; SpavD.Initialize();
		bRet = GetSpav(Key, SpavD);
		rData=SpavD;
	}
	else
	{
		bRet = GetSpan(Key, rData);
	}

	return bRet;
}

void CAttrCtrl::GetSpanOrSpavKeyList(CArray<T_SPAN_K, T_SPAN_K>& rKeyList, int nSectType, BOOL bVirtual)
{
	rKeyList.RemoveAll();
	CArray<int, int>aSeq;
	POSITION pos;

	if (bVirtual)
	{
		T_SPAV_K Key;
		T_SPAV_D Data;
		pos = GetStartSpav();
		while (pos != NULL)
		{
			GetNextSpav(pos, Key, Data);
			if (nSectType == Data.nSectType)
			{
				rKeyList.Add(Key);
				aSeq.Add(Data.nSeq);
			}
		}
		if (rKeyList.GetSize() > 0)CQSort::QSortIntWithIndex((int*)rKeyList.GetData(), aSeq.GetData(), rKeyList.GetSize());

	}
	else
	{
		GetSpanKeyList(rKeyList, nSectType);
	}
}


