BOOL CAttrCtrl::ExistDgml(unsigned int AnalType, unsigned int LoadCaseKey)
{
	CArray<T_DGML_K,T_DGML_K> DgmlKeyList;
	GetDgmlKeyList(DgmlKeyList);
	BOOL bRet=FALSE;
	for(int i=0;i<DgmlKeyList.GetSize();i++)
	{
		T_DGML_D DgmlData;
		if(!GetDgml(DgmlKeyList[i],DgmlData))ASSERT(0);
		if(DgmlData.AnalType==AnalType && DgmlData.LoadCaseKey == LoadCaseKey)
		{
			bRet = TRUE;
			break;
		}
	}
	return bRet;
}
BOOL CAttrCtrl::GetDgmlKey(unsigned int AnalType, unsigned int LoadCaseKey, T_DGML_K& Key)
{
	CArray<T_DGML_K,T_DGML_K> DgmlKeyList;
	GetDgmlKeyList(DgmlKeyList);
	BOOL bRet=FALSE;
	Key=0;
	for(int i=0;i<DgmlKeyList.GetSize();i++)
	{
		T_DGML_D DgmlData;
		if(!GetDgml(DgmlKeyList[i],DgmlData))ASSERT(0);
		if(DgmlData.AnalType==AnalType && DgmlData.LoadCaseKey == LoadCaseKey)
		{
			Key = DgmlKeyList[i];
			bRet = TRUE;
			break;
		}
	}
	return bRet;

}

