void CAttrCtrl::InitializeTdnt(T_TDNT_D& rData)
{
	rData.Initialize();
	rData.dWobbleFactor = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KG, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_TDNT_UNIT.dWobbleFactor, 0.0066);
	rData.dUltimateStrength = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KG, D_UNITSYS_LENGTH_INDEX_MM,
		CUnitCtrl::m_TDNT_UNIT.dUltimateStrength, 190.);
	rData.dYieldStrength = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KG, D_UNITSYS_LENGTH_INDEX_MM,
		CUnitCtrl::m_TDNT_UNIT.dYieldStrength, 160.);
	rData.dAnchoSlipBegin = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KG, D_UNITSYS_LENGTH_INDEX_MM,
		CUnitCtrl::m_TDNT_UNIT.dAnchoSlipBegin, 6.0);
	rData.dAnchoSlipEnd = rData.dAnchoSlipBegin;

	rData.dWobbleAngle = m_pUnitCtrl->ConvertTgtUnitData2CurUnit(
		D_UNITSYS_FORCE_INDEX_KG, D_UNITSYS_LENGTH_INDEX_M,
		CUnitCtrl::m_TDNT_UNIT.dWobbleAngle, 0.005);


	rData.LongTermStressLossData.nLongTermLossType = 0;
	rData.LongTermStressLossData.nStrandType       = 0;
	rData.LongTermStressLossData.dEstForce         = 0.0;
	rData.LongTermStressLossData.dConcAge          = 10.0;
	rData.LongTermStressLossData.dConcElasticity   = M_InitValueCurUnit(2.7E+7, KN, M, D_UNITSYS_BASE_STRESS);
	rData.LongTermStressLossData.dRelativeHumidity = 70.0;
	rData.LongTermStressLossData.dVSRatio          = 1.0;
	rData.LongTermStressLossData.dAvgPreComp       = 0.0;
	rData.LongTermStressLossData.dUltCreepCoef     = 2.0;
	rData.LongTermStressLossData.dTensFactor       = 0.5;
	rData.LongTermStressLossData.dShrinkageConst   = 0.7;
	rData.LongTermStressLossData.bAuto             = FALSE;
	rData.LongTermStressLossData.dRelaxConst       = M_InitValueCurUnit(30000.0, KN, M, D_UNITSYS_BASE_STRESS);
	rData.LongTermStressLossData.dRelaxReduct      = 0.35;

}

void CAttrCtrl::CalcXiTB(T_TDNT_D& DataTdnt)
{
	T_MATL_D MatlD;
	GetMatl(DataTdnt.MatlKey, MatlD);

	if (MatlD.Data1.CodeName == _ULS('TB05(S)'))
	{
		if (MatlD.Data1.CodeMatlName==_ULS('Wire1470') || MatlD.Data1.CodeMatlName==_ULS('Wire1570') ||
			MatlD.Data1.CodeMatlName==_ULS('Wire1670') || MatlD.Data1.CodeMatlName==_ULS('Wire1770') ||
			MatlD.Data1.CodeMatlName==_ULS('Wire1860') ) // case 1
		{
			if(DataTdnt.bLowRelax) DataTdnt.dJTG04Factor = -2;
			else                   DataTdnt.dJTG04Factor = -1; // JTG04 변수 재활용 - 사용자 입력 값
		}
		else if (MatlD.Data1.CodeMatlName==_ULS('Strand1470') || MatlD.Data1.CodeMatlName==_ULS('Strand1570') ||
				 MatlD.Data1.CodeMatlName==_ULS('Strand1670') || MatlD.Data1.CodeMatlName==_ULS('Strand1720') ||
				 MatlD.Data1.CodeMatlName==_ULS('Strand1770') || MatlD.Data1.CodeMatlName==_ULS('Strand1820') ||
				 MatlD.Data1.CodeMatlName==_ULS('Strand1860') ) // case 2
		{
			DataTdnt.dJTG04Factor = -2;
		}
		else if (MatlD.Data1.CodeMatlName==_ULS('PSB830')) // case 3-1 : PSB830 재질인 경우
		{
			DataTdnt.dJTG04Factor = (DataTdnt.bOverStressRedFactor ? 0.035: 0.05);
		}
		else // case 3-2 : TB05 의 기타 재질인 경우
		{
			// 사용자 입력 값 유지, 양수만 가능
			if (DataTdnt.dJTG04Factor < 0) DataTdnt.dJTG04Factor=0.0;
		}
	}
	else if (MatlD.Data1.CodeName == _ULS('TB10092-17(S)'))
	{
		if (MatlD.Data1.CodeMatlName==_ULS('Wire1470') || MatlD.Data1.CodeMatlName==_ULS('Wire1570') ||
			MatlD.Data1.CodeMatlName==_ULS('Wire1670') || MatlD.Data1.CodeMatlName==_ULS('Wire1770') ||
			MatlD.Data1.CodeMatlName==_ULS('Wire1860') ) // case 1
		{
			if(DataTdnt.bLowRelax) DataTdnt.dJTG04Factor = -2;
			else                   DataTdnt.dJTG04Factor = -1; // JTG04 변수 재활용 - 사용자 입력 값
		}
		else if (MatlD.Data1.CodeMatlName==_ULS('Strand1470') || MatlD.Data1.CodeMatlName==_ULS('Strand1570') ||
				 MatlD.Data1.CodeMatlName==_ULS('Strand1670') || MatlD.Data1.CodeMatlName==_ULS('Strand1720') ||
				 MatlD.Data1.CodeMatlName==_ULS('Strand1770') || MatlD.Data1.CodeMatlName==_ULS('Strand1820') ||
				 MatlD.Data1.CodeMatlName==_ULS('Strand1860') || MatlD.Data1.CodeMatlName==_ULS('Strand1960') ) // case 2
		{
			DataTdnt.dJTG04Factor = -2;
		}
		else if (MatlD.Data1.CodeMatlName==_ULS('PSB830') || MatlD.Data1.CodeMatlName==_ULS('PSB980')) // case 3-1
		{
			DataTdnt.dJTG04Factor = (DataTdnt.bOverStressRedFactor ? 0.035: 0.05);
		}
		else // case 3-2 : 기타 재질인 경우
		{
			// 사용자 입력 값 유지, 양수만 가능
			if (DataTdnt.dJTG04Factor < 0) DataTdnt.dJTG04Factor=0.0;
		}
	}
	else if (MatlD.Data1.CodeName == _ULS('Q/CR 9300-18(S)'))
	{
		if (MatlD.Data1.CodeMatlName==_ULS('Wire1470') || MatlD.Data1.CodeMatlName==_ULS('Wire1570') ||
			MatlD.Data1.CodeMatlName==_ULS('Wire1670') || MatlD.Data1.CodeMatlName==_ULS('Wire1770') ||
			MatlD.Data1.CodeMatlName==_ULS('Wire1860') ) // case 1
		{
			if(DataTdnt.bLowRelax) DataTdnt.dJTG04Factor = -2;
			else                   DataTdnt.dJTG04Factor = -1; // JTG04 변수 재활용 - 사용자 입력 값
		}
		else if (MatlD.Data1.CodeMatlName==_ULS('Strand1470') || MatlD.Data1.CodeMatlName==_ULS('Strand1570') ||
			MatlD.Data1.CodeMatlName==_ULS('Strand1670') || MatlD.Data1.CodeMatlName==_ULS('Strand1720') ||
			MatlD.Data1.CodeMatlName==_ULS('Strand1770') || MatlD.Data1.CodeMatlName==_ULS('Strand1820') ||
			MatlD.Data1.CodeMatlName==_ULS('Strand1860') || MatlD.Data1.CodeMatlName==_ULS('Strand1960') ) // case 2
		{
			DataTdnt.dJTG04Factor = -2;
		}
		else if (MatlD.Data1.CodeMatlName==_ULS('PSB830') || MatlD.Data1.CodeMatlName==_ULS('PSB980')) // case 3-1
		{
			DataTdnt.dJTG04Factor = (DataTdnt.bOverStressRedFactor ? 0.035: 0.05);
		}
		else // case 3-2 : 기타 재질인 경우
		{
			// 사용자 입력 값 유지, 양수만 가능
			if (DataTdnt.dJTG04Factor < 0) DataTdnt.dJTG04Factor=0.0;
		}
	}
	else // case 3-3 : TB05, TB10092-17(S) 재질이 아닌 경우
	{
		// 사용자 입력 값 유지, 양수만 가능
		if (DataTdnt.dJTG04Factor < 0) DataTdnt.dJTG04Factor=0.0;
	}
}

BOOL CAttrCtrl::GetTdnt(T_TDNT_K Key, double dTendonNum, T_TDNT_D& rData, double& dDiaTndn4, double& dDiaDuct4)
{
	if(!GetTdnt(Key,rData))	return FALSE;
	if(dTendonNum <= 0.0)	return FALSE;
	double dPi = CMathFunc::m_pi;
	double dDiaTndn = sqrt(rData.dTendonArea*(4./dPi));
	double dDiaDuct = rData.dDuctArea;
	dDiaTndn4 = pow(dTendonNum*pow(dDiaTndn,4),0.25);	// Tendon Dia for Iyy, Izz.
	dDiaDuct4 = pow(dTendonNum*pow(dDiaDuct,4),0.25);	// Duct Dia for Iyy, Izz.
	rData.dTendonArea *= dTendonNum;			// Tendon Area.
	rData.dDuctArea *= sqrt(dTendonNum);	// Duct Dia.
	return TRUE;
}

