void T_TDNA_BASE::Convert501(T_TDNA_BASE_501& rData)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	pDoc->m_pAttrCtrl->calcTdnaRelativeToAbsolute(rData);
	x = rData.dCoord[0];
	y = rData.dCoord[1];
	z = rData.dCoord[2];
	bFix = rData.bAlpha;
	dRy = rData.dAlphaY;
	dRz = rData.dAlphaZ;
	dRadius = 0.0;  
}

void T_TDNA_D::Convert501(T_TDNA_D_501& rData)
{
	TendonName = rData.TendonName;
	TendonTypeKey = rData.TendonTypeKey;
	aElemList.Copy(rData.aElemList);
	dBeginLength = rData.dBeginLength;
	dEndLength = rData.dEndLength;
	aProfile.SetSize(rData.aProfile.GetSize());
	for (int i = 0; i < rData.aProfile.GetSize(); i++)
		aProfile[i].Convert501(rData.aProfile[i]);
	aProfileY.RemoveAll();
	aProfileZ.RemoveAll();
	nTendonShape = 0;
	dInsertPointX = 0.0;
	dInsertPointY = 0.0;
	dInsertPointZ = 0.0;
	nXAxisDirection = 0;
	dVectorX = 0.0;
	dVectorY = 0.0;
	dCenterX = 0.0;
	dCenterY = 0.0;
	dOffset = 0.0;
	nCurveDir = 0;
	dXAxisRotAngle = 0.0;
	bProjection = TRUE;
	nGradRotAxis = 1;
	dGradRotAngle = 0.0;
	nInputType    = 1;
	nInsertPoint = 0;
	InsertElemKey = 0;
	nXAxisDirectionIJ = 0;
	dOffsetY = 0.;
	dOffsetZ = 0.;
}

void CAttrCtrl::ConvTdna501(T_TDNA_D_501& rData501, T_TDNA_D& rData)
{
	rData.Initialize();
	rData.Convert501(rData501);
}

void CAttrCtrl::GetTdnaList(CArray<CString, CString&>& rstrTdnaList)
{
	rstrTdnaList.RemoveAll();

	int nCount=GetCountTdna();
	if(nCount == 0)return;

	POSITION pos;
	T_TDNA_K Key;
	T_TDNA_D Data;
	pos=GetStartTdna();
	while(pos != NULL)
	{
		GetNextTdna(pos, Key, Data);
		rstrTdnaList.Add(Data.TendonName);
	}
	qsort(rstrTdnaList.GetData(), nCount, sizeof(CString), CCompFunc::stringAsc);
}
