BOOL CAttrCtrl::calcPttnSlabTendonProfile(T_PTTN_D& PttnD,  CArray<T_NODE_D, T_NODE_D&>& aTendonProfile, CArray<BOOL, BOOL>& aProfileInputPoint, int nDivide,
											BOOL bOnlyTendonLocalCoor, BOOL bOnlyControlPoint, BOOL bOnlyElementLocalCoor,
											CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xy, CArray<BOOL, BOOL>* paProfileInputPoint_xy,
											CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xz, CArray<BOOL, BOOL>* paProfileInputPoint_xz)
{
	if (PttnD.aInfo.GetSize() < 1) { ASSERT(0); return FALSE; }

	T_TDPF_D TdpfD;
	if (!m_pDoc->m_pAttrCtrl2->GetTdpf(PttnD.TdpfK, TdpfD)) { ASSERT(0); return FALSE; }
	if (TdpfD.nElemType != 1) { ASSERT(0); return FALSE; }
	if (TdpfD.aInfo.GetSize() == 0) { ASSERT(0); return FALSE; }

	// Span 순서로 
	int nCount = PttnD.aInfo.GetSize();

	T_NODE_D Data1;
	T_NODE_D Data2;
	double dTotLength = 0.;
	BOOL bJEnd = FALSE;
	CArray<double, double> aElemSpan;

	// 쌍 배열
	CArray<NODE_PAIR, NODE_PAIR&> arPairs;
	CArray<POS_PAIR, POS_PAIR&> arPairPos;
	for (int i = 0; i < PttnD.aInfo.GetSize(); ++i)
	{
		T_PTTN_Base Base = PttnD.aInfo[i];
		NODE_PAIR pair;
		pair.nStart = Base.Node1; 
		pair.nEnd   = Base.Node2; 
		arPairs.Add(pair);

		// 지점 절점의 좌표
		POS_PAIR PairPos;
		PairPos.StartPos = Base.Data1;
		PairPos.EndPos   = Base.Data2;
		arPairPos.Add(PairPos);
	}

	T_SPAN_PT  SpanPT;
	SpanPT.Initialize();
	T_SPAN_PT_BASE PTbase;
	CMap<T_NODE_K, T_NODE_K, int, int> mapSupport;
	for (int i = 0; i < arPairs.GetSize(); ++i)  // Span별 Node로 가정됨.
	{
		T_NODE_K NodeK1 = arPairs[i].nStart;
		T_NODE_K NodeK2 = arPairs[i].nEnd;
		Data1 = arPairPos[i].StartPos;
		Data2 = arPairPos[i].EndPos;

		double dLength = CMathFunc::mathLength(Data1.x - Data2.x, Data1.y - Data2.y, Data1.z - Data2.z);
		int nSupport   = GetSupportInfoPTBeam(NodeK1, NodeK2, mapSupport, TRUE);  //0=None, 1=I, 2=J 3=I,J

		if (nSupport == 1 && i > 0 && !bJEnd)
		{
			if (dTotLength > 1.e-7)
			{
				aElemSpan.Add(dTotLength);
				SpanPT.aSpanPTBase.Add(PTbase);
			}
			dTotLength = 0.0;
			PTbase.Initialize();
		}
		dTotLength += dLength;
		PTbase.arPairs.Add(arPairs[i]);
		PTbase.arPairPos.Add(arPairPos[i]);

		bJEnd = FALSE;
		if (nSupport == 2 || nSupport == 3)
		{
			if (dTotLength > 1.e-7)
			{
				aElemSpan.Add(dTotLength);
				SpanPT.aSpanPTBase.Add(PTbase);
			}
			dTotLength = 0.0;
			PTbase.Initialize();
			bJEnd = TRUE;
		}
	}
	if (dTotLength > 1.e-7)
	{
		aElemSpan.Add(dTotLength);
		SpanPT.aSpanPTBase.Add(PTbase);
	}
	aElemSpan.FreeExtra();

	/// SpanPT data
	ASSERT(aElemSpan.GetSize() == SpanPT.aSpanPTBase.GetSize());

	nCount = SpanPT.aSpanPTBase.GetSize();
	for (int i = 0; i < nCount; ++i)
	{
		SpanPT.aSpanPTBase[i].nDirection  = 0;// TdslD.nDirection;
		SpanPT.aSpanPTBase[i].dOffset     = 0.0;// PTTN 저장시엔 항상 0
		SpanPT.aSpanPTBase[i].dSpanLength = aElemSpan[i];
		SpanPT.aSpanPTBase[i].nSpanID = i + 1;

		int nNode = SpanPT.aSpanPTBase[i].arPairs.GetSize();
		T_NODE_K NodeK1 = SpanPT.aSpanPTBase[i].arPairs[0].nStart;
		T_NODE_K NodeK2 = SpanPT.aSpanPTBase[i].arPairs[nNode - 1].nEnd;

		int nTemp;
		BOOL bFind1 = FALSE, bFind2 = FALSE;
		if (mapSupport.Lookup(NodeK1, nTemp)) bFind1 = TRUE;
		if (mapSupport.Lookup(NodeK2, nTemp)) bFind2 = TRUE;

		int nSupportPT = 0;
		if (bFind1 && bFind2)  nSupportPT = 3;
		else if (bFind1)      nSupportPT = 1;
		else if (bFind2)      nSupportPT = 2;
		else                  nSupportPT = 0;

		SpanPT.aSpanPTBase[i].nSupportPT = nSupportPT;
	}

	SpanPT.bPTSlab = TRUE;

	/// SpanPT Tendon Profile
	T_TDNT_K TendonTypeKey = PttnD.TdntK;
	BOOL bRet = calPostTensionTendonProfileDetail_Slab(TdpfD, SpanPT, TendonTypeKey, nDivide, aTendonProfile, aProfileInputPoint,
													bOnlyTendonLocalCoor, bOnlyControlPoint, bOnlyElementLocalCoor,
													paTendonProfile_xy, paProfileInputPoint_xy, paTendonProfile_xz, paProfileInputPoint_xz);
	return bRet;
}

BOOL CAttrCtrl::MakePttnFromTdsl(T_TDSL_D& TdslD, CArray<T_PTTN_D, T_PTTN_D&>& aPttnDTotal)
{
	if (TdslD.aNodeK.GetSize() < 2) { ASSERT(0); return FALSE; }

	CArray<double, double> aPosWidth;
	m_pDoc->m_pAttrCtrl->PostTensionTendonPosition(TdslD, aPosWidth);

	CArray<T_PTTN_D, T_PTTN_D&> aPttnD;
	for (int i = 0; i < aPosWidth.GetSize(); ++i)
	{
		aPttnD.RemoveAll();
		if (!MakePttnData(TdslD, aPosWidth[i], aPttnD)) { ASSERT(0); continue; }

		aPttnDTotal.Append(aPttnD);
	}

	return TRUE;
}

BOOL CAttrCtrl::MakePttnData(T_TDSL_D& TdslD, double dPosition, CArray<T_PTTN_D, T_PTTN_D&>& aPttnD, T_SPAN_PT* pNewSpanPT/*=NULL*/)
{
	if (TdslD.aNodeK.GetSize() < 2) { ASSERT(0); return FALSE; }

	T_TDPF_D TdpfD;
	if (!m_pDoc->m_pAttrCtrl2->GetTdpf(TdslD.TdpfK, TdpfD)) { ASSERT(0); return FALSE; }
	if (TdpfD.nElemType != 1) { ASSERT(0); return FALSE; }
	if (TdpfD.aInfo.GetSize() == 0) { ASSERT(0); return FALSE; }

	// node 순서 = 진행 방향으로 정렬됨 
	int nCount = TdslD.aNodeK.GetSize();

	T_NODE_D Data1;
	T_NODE_D Data2;
	double dTotLength = 0.;
	BOOL bJEnd = FALSE;
	CArray<double, double> aElemSpan;

	// 쌍 배열
	CArray<NODE_PAIR, NODE_PAIR&> arPairs;
	CArray<POS_PAIR, POS_PAIR&> arPairPos;
	for (int i = 0; i < TdslD.aNodeK.GetSize() - 1; ++i)
	{
		NODE_PAIR pair;
		pair.nStart = TdslD.aNodeK[i];
		pair.nEnd = TdslD.aNodeK[i + 1];
		arPairs.Add(pair);

		// 지점 절점의 좌표
		POS_PAIR PairPos;
		GetNodeFromBaseDB(pair.nStart, Data1);
		GetNodeFromBaseDB(pair.nEnd, Data2);
		PairPos.StartPos = Data1;
		PairPos.EndPos = Data2;
		arPairPos.Add(PairPos);
	}

	if (pNewSpanPT)
	{
		if (arPairPos.GetSize() != pNewSpanPT->aSpanPTBase.GetSize())
		{
			ASSERT(0);
			return FALSE;
		}

		for (int i = 0; i < arPairs.GetSize(); ++i)
		{
			arPairPos[i].StartPos = pNewSpanPT->aSpanPTBase[i].arPairPos[0].StartPos;
			arPairPos[i].EndPos   = pNewSpanPT->aSpanPTBase[i].arPairPos[0].EndPos;

		}
	}

	T_SPAN_PT  SpanPT;
	SpanPT.Initialize();
	T_SPAN_PT_BASE PTbase;
	CMap<T_NODE_K, T_NODE_K, int, int> mapSupport;
	for (int i = 0; i < arPairs.GetSize(); ++i)  // Span별 Node로 가정됨.
	{
		T_NODE_K NodeK1 = arPairs[i].nStart;
		T_NODE_K NodeK2 = arPairs[i].nEnd;
		Data1 = arPairPos[i].StartPos;
		Data2 = arPairPos[i].EndPos;

		double dLength = CMathFunc::mathLength(Data1.x - Data2.x, Data1.y - Data2.y, Data1.z - Data2.z);
		int nSupport = GetSupportInfoPTBeam(NodeK1, NodeK2, mapSupport, TRUE);  //0=None, 1=I, 2=J 3=I,J

		if (nSupport == 1 && i > 0 && !bJEnd)
		{
			if (dTotLength > 1.e-7)
			{
				aElemSpan.Add(dTotLength);
				SpanPT.aSpanPTBase.Add(PTbase);
			}
			dTotLength = 0.0;
			PTbase.Initialize();
		}
		dTotLength += dLength;
		PTbase.arPairs.Add(arPairs[i]);
		PTbase.arPairPos.Add(arPairPos[i]);

		bJEnd = FALSE;
		if (nSupport == 2 || nSupport == 3)
		{
			if (dTotLength > 1.e-7)
			{
				aElemSpan.Add(dTotLength);
				SpanPT.aSpanPTBase.Add(PTbase);
			}
			dTotLength = 0.0;
			PTbase.Initialize();
			bJEnd = TRUE;
		}
	}
	if (dTotLength > 1.e-7)
	{
		aElemSpan.Add(dTotLength);
		SpanPT.aSpanPTBase.Add(PTbase);
	}
	aElemSpan.FreeExtra();

	/// SpanPT data
	ASSERT(aElemSpan.GetSize() == SpanPT.aSpanPTBase.GetSize());
	nCount = SpanPT.aSpanPTBase.GetSize();
	if (nCount < 1) { ASSERT(0); return FALSE; }

	for (int i = 0; i < nCount; ++i)
	{
		SpanPT.aSpanPTBase[i].nDirection  = TdslD.nDirection;
		SpanPT.aSpanPTBase[i].dOffset     = dPosition;
		SpanPT.aSpanPTBase[i].dSpanLength = aElemSpan[i];
		SpanPT.aSpanPTBase[i].nSpanID     = i + 1;

		int nNode = SpanPT.aSpanPTBase[i].arPairs.GetSize();
		T_NODE_K NodeK1 = SpanPT.aSpanPTBase[i].arPairs[0].nStart;
		T_NODE_K NodeK2 = SpanPT.aSpanPTBase[i].arPairs[nNode - 1].nEnd;

		int nTemp;
		BOOL bFind1 = FALSE, bFind2 = FALSE;
		if (mapSupport.Lookup(NodeK1, nTemp)) bFind1 = TRUE;
		if (mapSupport.Lookup(NodeK2, nTemp)) bFind2 = TRUE;

		int nSupportPT = 0;
		if (bFind1 && bFind2)  nSupportPT = 3;
		else if (bFind1)       nSupportPT = 1;
		else if (bFind2)       nSupportPT = 2;
		else                   nSupportPT = 0;

		SpanPT.aSpanPTBase[i].nSupportPT = nSupportPT;
	}

	SpanPT.bPTSlab = TRUE;

	T_PTTN_D PttnD;
	//////////
	PttnD.Initialize();
	PttnD.TdntK = TdslD.TdntK;
	PttnD.TdpfK = TdslD.TdpfK;
	PttnD.TdstK = TdslD.TdstK;
	PttnD.nEndType = TdslD.nEndType;
	PttnD.bUser = FALSE;
	PttnD.nTendonLineNo = TdslD.nTendonLineNo;
	//////////

	// span index와 x 좌표를 키로 하는 map으로 span별 구분 저장
	std::map<std::pair<int, double>, T_NODE_D> mapProfile;
	CArray<T_TDNA_BASE, T_TDNA_BASE> aProfile;
	T_TDNA_D DataTdna;
	CString strBoundaryCondition;

	for (int i = 0; i < nCount; ++i)
	{
		T_SPAN_PT_BASE PTbase = SpanPT.aSpanPTBase[i];

		if (i == 0) // Span 1
		{
			strBoundaryCondition = _T("First");
		}
		else if (i == nCount - 1) // Span end
		{
			strBoundaryCondition = _T("Last");
		}
		else
		{
			strBoundaryCondition = _T("Middle");
		}

		// 2.
		double dCzp = 0.0;
		double dCzm = 0.0;
		if (SpanPT.bPTSlab)
		{
			//////////////////////////////////////////////////////////////////////////
			// 수정 필요
			CArray<T_ELEM_K, T_ELEM_K> aElemList;
			GetConnectedElem(PTbase.arPairs[0].nStart, aElemList);
			if (aElemList.GetSize() == 0) { ASSERT(0); return FALSE; }

			T_ELEM_D ElemD;
			BOOL bChk = FALSE;
			for (int nPl = 0; nPl < aElemList.GetSize(); ++nPl)
			{
				if (!GetElem(aElemList[nPl], ElemD)) continue;
				if (!IsPlaneType(ElemD.eltyp)) continue;

				bChk = TRUE;
				break;
			}
			if (!bChk) { ASSERT(0); return FALSE; }
			//////////////////////////////////////////////////////////////////////////

			T_THIK_D ThikD;
			GetThik(ElemD.elpro, ThikD);
			double dThickness = ThikD.Value.ThickIn;
			dCzp = dThickness / 2.0;
			dCzm = dThickness / 2.0;
		}
		else // PT Beam
		{
			ASSERT(0);
		}

		BOOL bFind = FALSE;
		T_TDPF_INFO TdpfInfo;
		int nTdpfSize = TdpfD.aInfo.GetSize();
		for (int j = 0; j < nTdpfSize; ++j)
		{
			TdpfInfo = TdpfD.aInfo[j];
			if (TdpfInfo.strBoundaryCondition == strBoundaryCondition)
			{
				bFind = TRUE;
				break;
			}
		}
		if (!bFind) { ASSERT(0); continue; }

		BOOL bSpline = TRUE;
		CArray<T_TDNA_BASE, T_TDNA_BASE&> aProfile;
		if (!calPostTensionTendonProfileDetailSub(TdpfInfo, PTbase, dCzp, dCzm, aProfile, bSpline)) { ASSERT(0); continue; }

		int nSlabType = 0;
		DataTdna.Initialize();
		if (SpanPT.bPTSlab)
		{
			if (pNewSpanPT)  // Distrubuted
				nSlabType = 2;
			else
				nSlabType = 1;

			// Node_K
			int nPair = PTbase.arPairs.GetSize();
			for (int j = 0; j < nPair; ++j)
			{
				DataTdna.aElemList.Add(PTbase.arPairs[j].nStart);
				if (j == nPair - 1)
				{
					DataTdna.aElemList.Add(PTbase.arPairs[j].nEnd);
				}
			}

			// Node_D
			T_TDNA_BASE_2D BaseY, BaseZ;
			nPair = PTbase.arPairPos.GetSize();
			for (int j = 0; j < nPair; ++j)
			{
				T_NODE_D NODE1 = PTbase.arPairPos[j].StartPos;
				T_NODE_D NODE2 = PTbase.arPairPos[j].EndPos;

				BaseY.x = NODE1.x; 	BaseY.yz = NODE1.y;
				BaseZ.x = NODE1.x; 	BaseZ.yz = NODE1.z;
				DataTdna.aProfileY.Add(BaseY);
				DataTdna.aProfileZ.Add(BaseZ);
				if (j == nPair - 1)
				{
					BaseY.x = NODE2.x; 	BaseY.yz = NODE2.y;
					BaseZ.x = NODE2.x; 	BaseZ.yz = NODE2.z;
					DataTdna.aProfileY.Add(BaseY);
					DataTdna.aProfileZ.Add(BaseZ);
				}
			}

			DataTdna.TendonTypeKey = TdslD.TdntK;
			DataTdna.nCurveType    = (bSpline) ? 0 : 1; // 0:Spline, 1:Round(직선 그릴때)
			DataTdna.nTendonShape  = 2;                 // 2:Element
			DataTdna.InsertElemKey = 0;
			DataTdna.nInputType    = 1;                 // 3D
			DataTdna.aProfile.Append(aProfile);
		}
		else
		{
			ASSERT(0);
		}

		CArray<T_NODE_D, T_NODE_D&> aCPoints;
		CArray<BOOL, BOOL> aInputPointFlag;

		int nDivide = 36;
		CTendonProfile TendonProfile(m_pDoc);
		TendonProfile.SetPTSlabFlag(nSlabType);
		BOOL bOnlyTendonLocalCoord = FALSE;
		BOOL bOnlyControlPoint = TRUE;
		if (!TendonProfile.calcTendonProfile(DataTdna, aCPoints, aInputPointFlag, 36, bOnlyTendonLocalCoord, bOnlyControlPoint))
		{
			ASSERT(0); continue;
		}

		int nCPoint = aCPoints.GetSize();
		//span별 구분 저장
		for (int j = 0; j < nCPoint; j++)
		{
			mapProfile[std::make_pair(i, aCPoints[j].x)] = aCPoints[j];
		}

		//////////
		T_PTTN_Base PttnBase;
		PttnBase.Info = TdpfInfo;
		PttnBase.Node1 = PTbase.arPairs[0].nStart;
		PttnBase.Node2 = PTbase.arPairs[0].nEnd;
		//
		PttnBase.Data1.x = aCPoints[0].x;  
		PttnBase.Data1.y = aCPoints[0].y;
		PttnBase.Data1.z = PTbase.arPairPos[0].StartPos.z;
		//
		PttnBase.Data2.x = aCPoints[nCPoint - 1].x;  
		PttnBase.Data2.y = aCPoints[nCPoint - 1].y;
		PttnBase.Data2.z = PTbase.arPairPos[0].EndPos.z;

		PttnD.aInfo.Add(PttnBase);
		//////////

	} // i


	CArray<double, double> aX;
	CArray<double, double> aY;
	CArray<int , int> aIdx;
	// map에서 중복 x, y 제거하며 데이터 생성
	std::map<std::pair<double, double>, std::pair<int, T_NODE_D>> mapUniqueXY;
	for (std::map<std::pair<int, double>, T_NODE_D>::iterator it = mapProfile.begin(); it != mapProfile.end(); ++it)
	{
		int spanIdx = it->first.first;
		double xCoord = it->first.second;
		T_NODE_D nodeData = it->second;
		std::pair<double, double> xyKey = std::make_pair(nodeData.x, nodeData.y);
		mapUniqueXY[xyKey] = std::make_pair(spanIdx, nodeData);
	}
	
	for (std::map<std::pair<double, double>, std::pair<int, T_NODE_D>>::iterator it = mapUniqueXY.begin(); it != mapUniqueXY.end(); ++it)
	{
		aIdx.Add(it->second.first);
		aX.Add(it->second.second.x);
		aY.Add(it->second.second.y);
	}

	//////////
	PttnD.aX.Copy(aX);
	PttnD.aY.Copy(aY);
	PttnD.aIdx.Copy(aIdx);

	T_PTTN_K key = m_pDoc->m_pAttrCtrl2->GetStartNumPttn();
	CString TendonName;
	//TendonName.Format(_T("(TendonS-%d)"), key);  // 이름은 나중에..
	PttnD.strName = TendonName;
	//////////

	aPttnD.Add(PttnD);

	return TRUE;
}

BOOL CAttrCtrl::MakePttnData4Read(T_PTTN_D& PttnD)
{
	if (PttnD.aInfo.GetSize() < 1) { ASSERT(0); return FALSE; }

	T_TDPF_D TdpfD;
	if (!m_pDoc->m_pAttrCtrl2->GetTdpf(PttnD.TdpfK, TdpfD)) { ASSERT(0); return FALSE; }
	if (TdpfD.nElemType != 1) { ASSERT(0); return FALSE; }
	if (TdpfD.aInfo.GetSize() == 0) { ASSERT(0); return FALSE; }

	// Span 순서로 
	int nCount = PttnD.aInfo.GetSize();

	T_NODE_D Data1;
	T_NODE_D Data2;
	double dTotLength = 0.;
	BOOL bJEnd = FALSE;
	CArray<double, double> aElemSpan;

	// 쌍 배열
	CArray<NODE_PAIR, NODE_PAIR&> arPairs;
	CArray<POS_PAIR, POS_PAIR&> arPairPos;
	for (int i = 0; i < PttnD.aInfo.GetSize(); ++i)
	{
		T_PTTN_Base Base = PttnD.aInfo[i];
		NODE_PAIR pair;
		pair.nStart = Base.Node1;
		pair.nEnd = Base.Node2;
		arPairs.Add(pair);

		// 지점 절점의 좌표
		POS_PAIR PairPos;
		PairPos.StartPos = Base.Data1;
		PairPos.EndPos = Base.Data2;
		arPairPos.Add(PairPos);
	}

	T_SPAN_PT  SpanPT;
	SpanPT.Initialize();
	T_SPAN_PT_BASE PTbase;
	CMap<T_NODE_K, T_NODE_K, int, int> mapSupport;
	for (int i = 0; i < arPairs.GetSize(); ++i)  // Span별 Node로 가정됨.
	{
		T_NODE_K NodeK1 = arPairs[i].nStart;
		T_NODE_K NodeK2 = arPairs[i].nEnd;
		Data1 = arPairPos[i].StartPos;
		Data2 = arPairPos[i].EndPos;

		double dLength = CMathFunc::mathLength(Data1.x - Data2.x, Data1.y - Data2.y, Data1.z - Data2.z);
		int nSupport = GetSupportInfoPTBeam(NodeK1, NodeK2, mapSupport, TRUE);  //0=None, 1=I, 2=J 3=I,J

		if (nSupport == 1 && i > 0 && !bJEnd)
		{
			if (dTotLength > 1.e-7)
			{
				aElemSpan.Add(dTotLength);
				SpanPT.aSpanPTBase.Add(PTbase);
			}
			dTotLength = 0.0;
			PTbase.Initialize();
		}
		dTotLength += dLength;
		PTbase.arPairs.Add(arPairs[i]);
		PTbase.arPairPos.Add(arPairPos[i]);

		bJEnd = FALSE;
		if (nSupport == 2 || nSupport == 3)
		{
			if (dTotLength > 1.e-7)
			{
				aElemSpan.Add(dTotLength);
				SpanPT.aSpanPTBase.Add(PTbase);
			}
			dTotLength = 0.0;
			PTbase.Initialize();
			bJEnd = TRUE;
		}
	}
	if (dTotLength > 1.e-7)
	{
		aElemSpan.Add(dTotLength);
		SpanPT.aSpanPTBase.Add(PTbase);
	}
	aElemSpan.FreeExtra();

	/// SpanPT data
	ASSERT(aElemSpan.GetSize() == SpanPT.aSpanPTBase.GetSize());

	nCount = SpanPT.aSpanPTBase.GetSize();
	for (int i = 0; i < nCount; ++i)
	{
		SpanPT.aSpanPTBase[i].nDirection = 0;// TdslD.nDirection;
		SpanPT.aSpanPTBase[i].dOffset = 0.0;// PTTN 저장시엔 항상 0
		SpanPT.aSpanPTBase[i].dSpanLength = aElemSpan[i];
		SpanPT.aSpanPTBase[i].nSpanID = i + 1;

		int nNode = SpanPT.aSpanPTBase[i].arPairs.GetSize();
		T_NODE_K NodeK1 = SpanPT.aSpanPTBase[i].arPairs[0].nStart;
		T_NODE_K NodeK2 = SpanPT.aSpanPTBase[i].arPairs[nNode - 1].nEnd;

		int nTemp;
		BOOL bFind1 = FALSE, bFind2 = FALSE;
		if (mapSupport.Lookup(NodeK1, nTemp)) bFind1 = TRUE;
		if (mapSupport.Lookup(NodeK2, nTemp)) bFind2 = TRUE;

		int nSupportPT = 0;
		if (bFind1 && bFind2)  nSupportPT = 3;
		else if (bFind1)      nSupportPT = 1;
		else if (bFind2)      nSupportPT = 2;
		else                  nSupportPT = 0;

		SpanPT.aSpanPTBase[i].nSupportPT = nSupportPT;
	}

	SpanPT.bPTSlab = TRUE;

	// span index와 x 좌표를 키로 하는 map으로 span별 구분 저장
	std::map<std::pair<int, double>, T_NODE_D> mapProfile;
	CArray<T_TDNA_BASE, T_TDNA_BASE> aProfile;
	T_TDNA_D DataTdna;
	CString strBoundaryCondition;

	for (int i = 0; i < nCount; ++i)
	{
		T_SPAN_PT_BASE PTbase = SpanPT.aSpanPTBase[i];

		if (i == 0) // Span 1
		{
			strBoundaryCondition = _T("First");
		}
		else if (i == nCount - 1) // Span end
		{
			strBoundaryCondition = _T("Last");
		}
		else
		{
			strBoundaryCondition = _T("Middle");
		}

		// 2.
		double dCzp = 0.0;
		double dCzm = 0.0;
		if (SpanPT.bPTSlab)
		{
			//////////////////////////////////////////////////////////////////////////
			// 수정 필요
			CArray<T_ELEM_K, T_ELEM_K> aElemList;
			GetConnectedElem(PTbase.arPairs[0].nStart, aElemList);
			if (aElemList.GetSize() == 0) { ASSERT(0); return FALSE; }

			T_ELEM_D ElemD;
			BOOL bChk = FALSE;
			for (int nPl = 0; nPl < aElemList.GetSize(); ++nPl)
			{
				if (!GetElem(aElemList[nPl], ElemD)) continue;
				if (!IsPlaneType(ElemD.eltyp)) continue;

				bChk = TRUE;
				break;
			}
			if (!bChk) { ASSERT(0); return FALSE; }
			//////////////////////////////////////////////////////////////////////////

			T_THIK_D ThikD;
			GetThik(ElemD.elpro, ThikD);
			double dThickness = ThikD.Value.ThickIn;
			dCzp = dThickness / 2.0;
			dCzm = dThickness / 2.0;
		}
		else // PT Beam
		{
			ASSERT(0);
		}

		BOOL bFind = FALSE;
		T_TDPF_INFO TdpfInfo;
		int nTdpfSize = TdpfD.aInfo.GetSize();
		for (int j = 0; j < nTdpfSize; ++j)
		{
			TdpfInfo = TdpfD.aInfo[j];
			if (TdpfInfo.strBoundaryCondition == strBoundaryCondition)
			{
				bFind = TRUE;
				break;
			}
		}
		if (!bFind) { ASSERT(0); continue; }

		BOOL bSpline = TRUE;
		CArray<T_TDNA_BASE, T_TDNA_BASE&> aProfile;
		if (!calPostTensionTendonProfileDetailSub(TdpfInfo, PTbase, dCzp, dCzm, aProfile, bSpline)) { ASSERT(0); continue; }

		int nSlabType = 0;
		DataTdna.Initialize();
		if (SpanPT.bPTSlab)
		{
// 			if (pNewSpanPT)  // Distrubuted
// 				nSlabType = 2;
// 			else
				nSlabType = 1;

			// Node_K
			int nPair = PTbase.arPairs.GetSize();
			for (int j = 0; j < nPair; ++j)
			{
				DataTdna.aElemList.Add(PTbase.arPairs[j].nStart);
				if (j == nPair - 1)
				{
					DataTdna.aElemList.Add(PTbase.arPairs[j].nEnd);
				}
			}

			// Node_D
			T_TDNA_BASE_2D BaseY, BaseZ;
			nPair = PTbase.arPairPos.GetSize();
			for (int j = 0; j < nPair; ++j)
			{
				T_NODE_D NODE1 = PTbase.arPairPos[j].StartPos;
				T_NODE_D NODE2 = PTbase.arPairPos[j].EndPos;

				BaseY.x = NODE1.x; 	BaseY.yz = NODE1.y;
				BaseZ.x = NODE1.x; 	BaseZ.yz = NODE1.z;
				DataTdna.aProfileY.Add(BaseY);
				DataTdna.aProfileZ.Add(BaseZ);
				if (j == nPair - 1)
				{
					BaseY.x = NODE2.x; 	BaseY.yz = NODE2.y;
					BaseZ.x = NODE2.x; 	BaseZ.yz = NODE2.z;
					DataTdna.aProfileY.Add(BaseY);
					DataTdna.aProfileZ.Add(BaseZ);
				}
			}

			DataTdna.TendonTypeKey = PttnD.TdntK;
			DataTdna.nCurveType    = (bSpline) ? 0 : 1; // 0:Spline, 1:Round(직선 그릴때)
			DataTdna.nTendonShape  = 2;                 // 2:Element
			DataTdna.InsertElemKey = 0;
			DataTdna.nInputType    = 1;                 // 3D
			DataTdna.aProfile.Append(aProfile);
		}
		else
		{
			ASSERT(0);
		}

		CArray<T_NODE_D, T_NODE_D&> aCPoints;
		CArray<BOOL, BOOL> aInputPointFlag;

		int nDivide = 36;
		CTendonProfile TendonProfile(m_pDoc);
		TendonProfile.SetPTSlabFlag(nSlabType);
		BOOL bOnlyTendonLocalCoord = FALSE;
		BOOL bOnlyControlPoint = TRUE;
		if (!TendonProfile.calcTendonProfile(DataTdna, aCPoints, aInputPointFlag, 36, bOnlyTendonLocalCoord, bOnlyControlPoint))
		{
			ASSERT(0); continue;
		}

		int nCPoint = aCPoints.GetSize();
		//span별 구분 저장
		for (int j = 0; j < nCPoint; j++)
		{
			mapProfile[std::make_pair(i, aCPoints[j].x)] = aCPoints[j];
		}

// 		//////////
// 		T_PTTN_Base PttnBase;
// 		PttnBase.Info = TdpfInfo;
// 		PttnBase.Node1 = PTbase.arPairs[0].nStart;
// 		PttnBase.Node2 = PTbase.arPairs[0].nEnd;
// 		//
// 		PttnBase.Data1.x = aCPoints[0].x;
// 		PttnBase.Data1.y = aCPoints[0].y;
// 		PttnBase.Data1.z = PTbase.arPairPos[0].StartPos.z;
// 		//
// 		PttnBase.Data2.x = aCPoints[nCPoint - 1].x;
// 		PttnBase.Data2.y = aCPoints[nCPoint - 1].y;
// 		PttnBase.Data2.z = PTbase.arPairPos[0].EndPos.z;
// 
// 		PttnD.aInfo.Add(PttnBase);
// 		//////////

	} // i


	CArray<double, double> aX;
	CArray<double, double> aY;
	CArray<int, int> aIdx;
	// map에서 중복 x, y 제거하며 데이터 생성
	std::map<std::pair<double, double>, std::pair<int, T_NODE_D>> mapUniqueXY;
	for (std::map<std::pair<int, double>, T_NODE_D>::iterator it = mapProfile.begin(); it != mapProfile.end(); ++it)
	{
		int spanIdx = it->first.first;
		double xCoord = it->first.second;
		T_NODE_D nodeData = it->second;
		std::pair<double, double> xyKey = std::make_pair(nodeData.x, nodeData.y);
		mapUniqueXY[xyKey] = std::make_pair(spanIdx, nodeData);
	}

	for (std::map<std::pair<double, double>, std::pair<int, T_NODE_D>>::iterator it = mapUniqueXY.begin(); it != mapUniqueXY.end(); ++it)
	{
		aIdx.Add(it->second.first);
		aX.Add(it->second.second.x);
		aY.Add(it->second.second.y);
	}

	//////////
	PttnD.aX.Copy(aX);
	PttnD.aY.Copy(aY);
	PttnD.aIdx.Copy(aIdx);

// 	T_PTTN_K key = m_pDoc->m_pAttrCtrl2->GetStartNumPttn();
// 	CString TendonName;
// 	//TendonName.Format(_T("(TendonS-%d)"), key);  // 이름은 나중에..
// 	PttnD.strName = TendonName;
// 	//////////
// 
// 	aPttnD.Add(PttnD);

	return TRUE;
}


BOOL CAttrCtrl::MakePttnFromTdsl_Distributed(T_TDSL_D& TdslD, CArray<T_PTTN_D, T_PTTN_D&>& aPttnDTotal)
{
	if (TdslD.aLine1.GetSize() < 2) { ASSERT(0); return FALSE; }
	if (TdslD.aLine2.GetSize() < 2) { ASSERT(0); return FALSE; }

	if (TdslD.aLine1.GetSize() != TdslD.aLine2.GetSize()) { ASSERT(0); return FALSE; }

	T_TDPF_D TdpfD;
	if (!m_pDoc->m_pAttrCtrl2->GetTdpf(TdslD.TdpfK, TdpfD)) { ASSERT(0); return FALSE; }
	if (TdpfD.nElemType != 1) { ASSERT(0); return FALSE; }
	if (TdpfD.aInfo.GetSize() == 0) { ASSERT(0); return FALSE; }

	CArray<T_NODE_D, T_NODE_D&> aCPoints1, aCPoints2;
	CArray<BOOL, BOOL>          aInputPointFlag1, aInputPointFlag2;
 
	BOOL bOnlyTendonLocalCoord = FALSE;
	BOOL bOnlyControlPoint     = TRUE;

	//////////////////////////////////////////////////////////////////////////
	T_TDSL_D TdslD1;
	TdslD1 = TdslD;
	TdslD1.nLayoutType = 0;     // single
	TdslD1.aNodeK.RemoveAll();
	TdslD1.aNodeK.Copy(TdslD.aLine1);

	T_SPAN_PT SpanPT1;
	if (!calcPTSlabTendonProfile(TdslD1, 0.0/*dPosition*/, SpanPT1, aCPoints1, aInputPointFlag1, 36, bOnlyTendonLocalCoord, bOnlyControlPoint))
		return FALSE;

	T_TDSL_D TdslD2;
	TdslD2 = TdslD;
	TdslD2.nLayoutType = 0;     // single
	TdslD2.aNodeK.RemoveAll();
	TdslD2.aNodeK.Copy(TdslD.aLine2);

	T_SPAN_PT SpanPT2;
	if (!calcPTSlabTendonProfile(TdslD2, 0.0/*dPosition*/, SpanPT2, aCPoints2, aInputPointFlag2, 36, bOnlyTendonLocalCoord, bOnlyControlPoint))
		return FALSE;

	if(aCPoints1.GetSize() != aCPoints2.GetSize())
	{
		ASSERT(0);
		return FALSE;
	}
	//////////////////////////////////////////////////////////////////////////

	CArray<T_PTTN_D, T_PTTN_D&> aPttnD;
	aPttnD.RemoveAll();

	T_SPAN_PT NewSpanPT = SpanPT1;

	CArray<T_SPAN_PT_BASE, T_SPAN_PT_BASE&> aSpanPTBase;
	if(TdslD.nArrangement == 0) // Spacing
	{
		double dMinVal = 1.0E+12; // A, B 사이 최소값
		for (int i = 0; i < aCPoints1.GetSize(); i++)
		{
			double dLength = CMathFunc::mathLength(aCPoints1[i].x - aCPoints2[i].x,
												   aCPoints1[i].y - aCPoints2[i].y,
												   aCPoints1[i].z - aCPoints2[i].z);
			dMinVal = min(dMinVal, dLength);
		}

		int nIdx = 0;
		while (TRUE)
		{
			aPttnD.RemoveAll();

			double dVal = nIdx * TdslD.dArrSpacing;

			for (int i = 0; i < SpanPT1.aSpanPTBase.GetSize(); i++)
			{
				const T_SPAN_PT_BASE& A = SpanPT1.aSpanPTBase[i];
				const T_SPAN_PT_BASE& B = SpanPT2.aSpanPTBase[i];

				T_SPAN_PT_BASE BaseNew = NewSpanPT.aSpanPTBase[i];
				BaseNew.arPairPos.RemoveAll();

				int nPairN = A.arPairPos.GetSize();
				for (int j = 0; j < A.arPairPos.GetSize(); j++)
				{
					POS_PAIR PairNew;
					PairNew.StartPos = LinearInterpolNode(A.arPairPos[j].StartPos, B.arPairPos[j].StartPos, 1, dVal);
					PairNew.EndPos   = LinearInterpolNode(A.arPairPos[j].EndPos,   B.arPairPos[j].EndPos,   1, dVal);

					BaseNew.arPairPos.Add(PairNew);
					BaseNew.dSpanLength = CMathFunc::mathLength(PairNew.StartPos.x - PairNew.EndPos.x,
																PairNew.StartPos.y - PairNew.EndPos.y,
																PairNew.StartPos.z - PairNew.EndPos.z);
				}
				NewSpanPT.aSpanPTBase[i] = BaseNew;
			} // i

			// TdslD1 : 대표값., NewSpanPT 를 이용해 새로운 Tendon Profile 생성
			T_SPAN_PT* pNewSpanPT = &NewSpanPT;
			MakePttnData(TdslD1, 0.0, aPttnD, pNewSpanPT);
			aPttnDTotal.Append(aPttnD);

			if(dVal >= dMinVal )
			{
				break;
			}
			nIdx++;
		}
	}
	else if(TdslD.nArrangement == 1) // TendonLineNo
	{
		int nNum = TdslD.nArrTendonLineNo;
		for (int nN = 0; nN <= nNum-1; nN++)
		{
			aPttnD.RemoveAll();

			double dRat = 0.0;
			if (nNum == 1)
				dRat = 0.5;
			else
				dRat = (double)nN / (double)(nNum-1);

			for (int i = 0; i < SpanPT1.aSpanPTBase.GetSize(); i++)
			{
				const T_SPAN_PT_BASE& A = SpanPT1.aSpanPTBase[i];
				const T_SPAN_PT_BASE& B = SpanPT2.aSpanPTBase[i];

				T_SPAN_PT_BASE BaseNew  = NewSpanPT.aSpanPTBase[i];
				BaseNew.arPairPos.RemoveAll();

				int nPairN = A.arPairPos.GetSize();
				for (int j = 0; j < A.arPairPos.GetSize(); j++)
				{
					POS_PAIR PairNew;
					PairNew.StartPos = LinearInterpolNode(A.arPairPos[j].StartPos, B.arPairPos[j].StartPos, 0, dRat);
					PairNew.EndPos   = LinearInterpolNode(A.arPairPos[j].EndPos,   B.arPairPos[j].EndPos,   0, dRat);

					BaseNew.arPairPos.Add(PairNew);
					BaseNew.dSpanLength = CMathFunc::mathLength(PairNew.StartPos.x - PairNew.EndPos.x, 
																PairNew.StartPos.y - PairNew.EndPos.y, 
																PairNew.StartPos.z - PairNew.EndPos.z);
				}
				NewSpanPT.aSpanPTBase[i] = BaseNew;
			}

			// TdslD1 : 대표값., NewSpanPT 를 이용해 새로운 Tendon Profile 생성
			T_SPAN_PT* pNewSpanPT = &NewSpanPT;
			MakePttnData(TdslD1, 0.0, aPttnD, pNewSpanPT);

			aPttnDTotal.Append(aPttnD);
		} // nN
	}
	else 
		ASSERT(0);

	return TRUE;
}

BOOL CAttrCtrl::calcPTSlabTendonProfile_Distribute(T_TDSL_D& TdslD, double dPosition, T_SPAN_PT& NewSpanPT, CArray<T_NODE_D, T_NODE_D&>& aTendonProfile, CArray<BOOL, BOOL>& aProfileInputPoint, int nDivide,
											BOOL bOnlyTendonLocalCoor, BOOL bOnlyControlPoint, BOOL bOnlyElementLocalCoor,
											CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xy, CArray<BOOL, BOOL>* paProfileInputPoint_xy,
											CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xz, CArray<BOOL, BOOL>* paProfileInputPoint_xz)
{
	if (TdslD.aNodeK.GetSize() < 2) { ASSERT(0); return FALSE; }

	T_TDPF_D TdpfD;
	if (!m_pDoc->m_pAttrCtrl2->GetTdpf(TdslD.TdpfK, TdpfD)) { ASSERT(0); return FALSE; }
	if (TdpfD.nElemType != 1) { ASSERT(0); return FALSE; }
	if (TdpfD.aInfo.GetSize() == 0) { ASSERT(0); return FALSE; }

	/// SpanPT Tendon Profile
	T_TDNT_K TendonTypeKey = TdslD.TdntK;
	BOOL bRet = calPostTensionTendonProfileDetail_Distribute(TdpfD, NewSpanPT, TendonTypeKey, nDivide, aTendonProfile, aProfileInputPoint,
											  	 bOnlyTendonLocalCoor, bOnlyControlPoint, bOnlyElementLocalCoor,
												 paTendonProfile_xy, paProfileInputPoint_xy, paTendonProfile_xz, paProfileInputPoint_xz);

	return bRet;

}

void CAttrCtrl::PostTensionTendonPosition(T_TDSL_D& TdslD, CArray<double, double>& aPosWidth)
{
	aPosWidth.RemoveAll();
	double dOffset = TdslD.dOffset;
	if (TdslD.nLayoutType == 0) // single
	{
		aPosWidth.Add(dOffset);
	}
	else if (TdslD.nLayoutType == 1) // Banded
	{
		double dL = TdslD.dBandWidth;
		int nN = TdslD.nTendonLineNo;
		if (nN == 1)
		{
			aPosWidth.Add(dOffset);
		}
		else
		{
			double dSpacing = dL / (nN - 1);
			double dSpacing_1 = -dL / 2.0;
			double dPos = dSpacing_1 + dOffset;
			aPosWidth.Add(dPos);
			for (int i = 1; i < nN; ++i)
			{
				dPos  = dSpacing_1 + i * dSpacing ;
				dPos += dOffset;
				aPosWidth.Add(dPos);
			}
		}
	}
	else if (TdslD.nLayoutType == 2) // Distributed
	{
		ASSERT(0);
		aPosWidth.Add(0.0);
	}
}

int CAttrCtrl::GetSupportInfoPTBeam(T_NODE_K NodeK1, T_NODE_K NodeK2, CMap<T_NODE_K, T_NODE_K, int, int>& mapSupport, BOOL bSlab/*=FALSE*/)
{
	BOOL bFind1 = FALSE, bFind2 = FALSE;

	CArray<T_ELEM_K, T_ELEM_K> aElemList;

	int nInfo = 0;

	// slab에서는 입력된 절점은 항성 지점부로 파단
	if (bSlab)
	{
		mapSupport.SetAt(NodeK1, 1); nInfo += 1;
		mapSupport.SetAt(NodeK2, 2); nInfo += 2;
		return nInfo;
	}

	aElemList.RemoveAll();
	GetConnectedElem4BeamTruss(NodeK1, aElemList);
	int nCount = aElemList.GetSize();
	for (int i = 0; i < nCount; ++i)
	{
		T_ELEM_K ElemK = aElemList.GetAt(i);
		T_ELEM_D ElemD;
		if (!GetElem(ElemK, ElemD)) { continue; }

		T_NODE_D DataNodeI, DataNodeJ;
		VERIFY(GetNode(ElemD.elnod[0], DataNodeI));
		VERIFY(GetNode(ElemD.elnod[1], DataNodeJ));
		if (IsVerticalFrame(DataNodeI, DataNodeJ))
		{
			bFind1 = TRUE;
			mapSupport.SetAt(NodeK1, 1);
			nInfo += 1;
			break;
		}
	}

	//
	aElemList.RemoveAll();
	GetConnectedElem4BeamTruss(NodeK2, aElemList);
	nCount = aElemList.GetSize();
	for (int i = 0; i < nCount; ++i)
	{
		T_ELEM_K ElemK = aElemList.GetAt(i);
		T_ELEM_D ElemD;
		if (!GetElem(ElemK, ElemD)) { continue; }

		T_NODE_D DataNodeI, DataNodeJ;
		VERIFY(GetNode(ElemD.elnod[0], DataNodeI));
		VERIFY(GetNode(ElemD.elnod[1], DataNodeJ));
		if (IsVerticalFrame(DataNodeI, DataNodeJ))
		{
			bFind2 = TRUE;
			mapSupport.SetAt(NodeK2, 2);
			nInfo += 2;
			break;
		}
	}

	return nInfo;
}

BOOL CAttrCtrl::GetElemListLinked(CArray<T_ELEM_K, T_ELEM_K>* paKey, CMap<T_ELEM_K, T_ELEM_K, BOOL, BOOL>* pmSelKey, CArray<T_ELEM_K, T_ELEM_K>& arElemK)
{
	arElemK.RemoveAll();

	ASSERT(paKey && pmSelKey);

	CMap<T_ELEM_K, T_ELEM_K, BOOL, BOOL> mUsedElemK;
	mUsedElemK.InitHashTable(53);
	BOOL bTmp = TRUE, bIJError = FALSE;

	int nElemSize = paKey->GetSize();
	for (int i = 0; i < nElemSize; ++i)
	{
		T_ELEM_K ElemK = paKey->GetAt(i);
		T_ELEM_D ElemD;
		if (!m_pDoc->m_pAttrCtrl->GetElem(ElemK, ElemD)) continue;
		if (mUsedElemK.Lookup(ElemK, bTmp)) break; // 동일한 방향으로 연결된 요소 list중 하나만 사용할 것임.
		else
		{
			arElemK.Add(ElemK);
			mUsedElemK.SetAt(ElemK, TRUE);
		}

		// j node 방향으로 연결된 요소에 대해 작업한다.
		CArray<T_ELEM_K, T_ELEM_K> aConnectedElemK;
		BOOL bNextInclude = TRUE;
		while (bNextInclude)
		{
			m_pDoc->m_pAttrCtrl->GetElemKeyListConnectedToNode(ElemD.elnod[1], aConnectedElemK);
			int nConnectedElemSize = aConnectedElemK.GetSize();
			if (nConnectedElemSize < 1) bNextInclude = FALSE;
			for (int j = 0; j < nConnectedElemSize; ++j)
			{
				bNextInclude = FALSE;
				T_ELEM_K ElemK_c = aConnectedElemK.GetAt(j);
				if (ElemK_c == ElemK) continue;                   // 현재 요소가 기준 요소와 다르고 

				if (mUsedElemK.Lookup(ElemK_c, bTmp)) continue;   // 기존에 한번이라도 Member로 지정되지 않고
				if (!pmSelKey->Lookup(ElemK_c, bTmp)) continue;   // 현재 요소가 선택된 프레임 요소 리스트에 속하고

				T_ELEM_D NextElemD;
				if (!m_pDoc->m_pAttrCtrl->GetElem(ElemK_c, NextElemD)) continue;  // 현재 요소의 데이터가 정의되어 있고
				if (ElemD.elnod[1] != NextElemD.elnod[0]) { bIJError = TRUE; continue; } // 기준 요소와 현재 요소의 node i, j 순서가 동일하고
				//if(mapUsedNode.Lookup(NextElemD.elnod[1], KeyNode)) continue;  // 선택된 요소들이 폐곡선을 이루지 않아야 한다.  

				arElemK.Add(ElemK_c);
				mUsedElemK.SetAt(ElemK_c, TRUE);

				//mapUsedNode.SetAt(DElemNext.elnod[1], DElemNext.elnod[1]);    // 현재 요소의 j노드를 사용된 노드 map에 추가한다.
				ElemK = aConnectedElemK.GetAt(j);      // 현재 추가된 요소를 기준 요소로 설정
				ElemD.elnod[1] = NextElemD.elnod[1];   // 현재 추가된 요소의 j절점이 새로운 기준요소의 i절점이 된다.
				bNextInclude = TRUE;                   // 새로운 기준요소의 j절점에 대해 작업을 계속함을 의미                        
				break;
			}
		}

		// i node 방향으로 연결된 요소에 대해 작업한다.
		bNextInclude = TRUE;
		while (bNextInclude)   // i node 방향으로 연결된 요소에 대해 작업한다.
		{
			m_pDoc->m_pAttrCtrl->GetElemKeyListConnectedToNode(ElemD.elnod[0], aConnectedElemK);
			int nConnectedElemSize = aConnectedElemK.GetSize();
			if (nConnectedElemSize < 1) bNextInclude = FALSE;
			for (int j = 0; j < nConnectedElemSize; ++j)
			{
				bNextInclude = FALSE;
				T_ELEM_K ElemK_c = aConnectedElemK.GetAt(j);
				if (ElemK_c == ElemK) continue;                   // 현재 요소가 기준 요소와 다르고 

				if (mUsedElemK.Lookup(ElemK_c, bTmp)) continue;   // 기존에 한번이라도 Member로 지정되지 않고
				if (!pmSelKey->Lookup(ElemK_c, bTmp))  continue;   // 현재 요소가 선택된 프레임 요소 리스트에 속하고

				T_ELEM_D NextElemD;
				if (!m_pDoc->m_pAttrCtrl->GetElem(ElemK_c, NextElemD)) continue;  // 현재 요소의 데이터가 정의되어 있고
				if (ElemD.elnod[0] != NextElemD.elnod[1]) { bIJError = TRUE; continue; } // 기준 요소와 현재 요소의 node i, j 순서가 동일하고
				//if(mapUsedNode.Lookup(NextElemD.elnod[0], KeyNode)) continue;  // 선택된 요소들이 폐곡선을 이루지 않아야 한다.  

				arElemK.Add(ElemK_c);
				mUsedElemK.SetAt(ElemK_c, TRUE);

				//mapUsedNode.SetAt(DElemNext.elnod[1], DElemNext.elnod[1]);    // 현재 요소의 i노드를 사용된 노드 map에 추가한다.
				ElemK = aConnectedElemK.GetAt(j);      // 현재 추가된 요소를 기준 요소로 설정
				ElemD.elnod[0] = NextElemD.elnod[0];   // 현재 추가된 요소의 i절점이 새로운 기준요소의 i절점이 된다.
				bNextInclude = TRUE;                   // 새로운 기준요소의 i절점에 대해 작업을 계속함을 의미                        
				break;
			}
		}
	}
	if (bIJError)
	{
		AfxMessageBox(_LS(IDS_SW_WARNING___INCLUDE_DIFF_IJ));
	}

	arElemK.FreeExtra();
	nElemSize = arElemK.GetSize();
	if (nElemSize < 1) { ASSERT(0); return FALSE; }

	if (!AlignElemListInOrderLinked(arElemK)) return FALSE;

	for (int i = 0; i < nElemSize - 1; ++i)
	{
		T_ELEM_D ElemD1, ElemD2;
		GetElem(arElemK[i], ElemD1);
		GetElem(arElemK[i + 1], ElemD2);
		if (ElemD1.elnod[1] != ElemD2.elnod[0])
		{
			arElemK.RemoveAt(i + 1, nElemSize - i - 1);
			break;
		}
	}

	return TRUE;
}

BOOL CAttrCtrl::AlignElemListInOrderLinked(CArray<T_ELEM_K, T_ELEM_K>& arElemK)
{
	int nElemSize = arElemK.GetSize();
	if (nElemSize < 1) return FALSE;

	CMap<T_NODE_K, T_NODE_K, T_ELEM_K, T_ELEM_K> mapNodeiElem; mapNodeiElem.InitHashTable(53); mapNodeiElem.RemoveAll();
	CMap<T_NODE_K, T_NODE_K, T_ELEM_K, T_ELEM_K> mapNodejElem; mapNodejElem.InitHashTable(53); mapNodejElem.RemoveAll();
	CMap<T_NODE_K, T_NODE_K, int, int> mapInnerNode;           mapInnerNode.InitHashTable(53); mapInnerNode.RemoveAll();

	T_ELEM_K ElemK;
	T_ELEM_D ElemD;
	CArray<T_ELEM_D, T_ELEM_D&> aElemD; aElemD.RemoveAll();
	for (int i = 0; i < nElemSize; i++)
	{
		if (GetElem(arElemK[i], ElemD)) aElemD.Add(ElemD);
	}
	ASSERT(nElemSize == aElemD.GetSize());

	int nMaxNum = nElemSize * 2;
	int* nNodeIndex = new int[nMaxNum];
	for (int i = 0; i < nMaxNum; ++i) nNodeIndex[i] = 0;
	for (int i = 0; i < nElemSize; ++i)
	{
		ElemK = arElemK.GetAt(i);
		T_ELEM_D ElemD;
		GetElem(ElemK, ElemD);
		nNodeIndex[2 * i] = ElemD.elnod[0];
		nNodeIndex[2 * i + 1] = ElemD.elnod[1];
		mapNodeiElem.SetAt(ElemD.elnod[0], ElemK);
		mapNodejElem.SetAt(ElemD.elnod[1], ElemK);
	}

	int nNumNode = 2 * nElemSize;
	for (int i = 0; i < nNumNode; ++i) // 현재 Member의 내부 절점을 구한다.
	{
		for (int j = i; j < nNumNode; ++j)
		{
			if (j != i && nNodeIndex[i] == nNodeIndex[j]) { mapInnerNode.SetAt(nNodeIndex[i], 0); break; }
		}
	}

	int nStartNode, nLastNode, nTemp;  // 연속성을 파악할 첫번째 요소의 i 노드 및 마지막 요소의 j 노드
	for (int i = 0; i < nElemSize; i++)
	{
		GetElem(arElemK[i], ElemD);
		if (!mapInnerNode.Lookup(ElemD.elnod[0], nTemp)) nStartNode = ElemD.elnod[0];
		if (!mapInnerNode.Lookup(ElemD.elnod[1], nTemp)) nLastNode = ElemD.elnod[1];
	}

	BOOL bSuccess = FALSE;
	arElemK.RemoveAll(); arElemK.SetSize(nElemSize);
	mapNodeiElem.Lookup(nStartNode, ElemK);  // 멤버의 첫번째 요소를 찾는다.
	arElemK[0] = ElemK; // 첫번째 요소를 설정한다.  
	for (int i = 0; i < nElemSize; ++i)
	{
		GetElem(ElemK, ElemD);
		if (i < nElemSize - 1)
		{
			mapNodeiElem.Lookup(ElemD.elnod[1], ElemK);
			arElemK[i + 1] = ElemK;
		}
		if (i == nElemSize - 1 && ElemD.elnod[1] == nLastNode) bSuccess = TRUE;
	}
	delete[]nNodeIndex;
	return bSuccess;
}

BOOL CAttrCtrl::calPostTensionTendonProfileDetail_Beam(T_TDPF_D& TdpfD, T_SPAN_PT& SpanPT, T_TDNT_K TendonTypeKey, int nDivide, CArray<T_NODE_D, T_NODE_D&>& aTendonProfile, CArray<BOOL, BOOL>& aProfileInputPoint,
												 BOOL bOnlyTendonLocalCoor, BOOL bOnlyControlPoint, BOOL bOnlyElementLocalCoor,		
												 CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xy, CArray<BOOL, BOOL>* paProfileInputPoint_xy, 
												 CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xz, CArray<BOOL, BOOL>* paProfileInputPoint_xz)
{
	aTendonProfile.RemoveAll();
	aProfileInputPoint.RemoveAll();
	if (paTendonProfile_xy     != NULL)paTendonProfile_xy->RemoveAll();
	if (paProfileInputPoint_xy != NULL)paProfileInputPoint_xy->RemoveAll();
	if (paTendonProfile_xz     != NULL)paTendonProfile_xz->RemoveAll();
	if (paProfileInputPoint_xz != NULL)paProfileInputPoint_xz->RemoveAll();

	int nCount = SpanPT.aSpanPTBase.GetSize();
	if (nCount < 1) { ASSERT(0); return FALSE; }

	CArray<T_TDNA_BASE, T_TDNA_BASE> aProfile;
	T_TDNA_D DataTdna; 
	CString strBoundaryCondition;

	DataTdna.Initialize();
	
	// x 좌표를 키로 하는 map으로 중복 제거
	std::map<double, T_TDNA_BASE> mapProfile;
	double dLastX = 0.0;
	for (int i = 0; i < nCount; ++i)
	{
		T_SPAN_PT_BASE PTbase = SpanPT.aSpanPTBase[i];

		// 1. strBoundaryCondition
		if (i == 0) // Span 1
		{
			strBoundaryCondition = _T("First");
		}
		else if (i == nCount - 1) // Span end
		{
			strBoundaryCondition = _T("Last");
		}
		else
		{
			strBoundaryCondition = _T("Middle");
		}

		// 2.
		double dCzp = 0.0;
		double dCzm = 0.0;

		T_ELEM_D ElemD;
		if (!GetElem(PTbase.aElemK[0], ElemD)) ASSERT(0);
		T_SECT_D SectD;
		if (!GetSect(ElemD.elpro, SectD)) ASSERT(0);
		dCzp = SectD.SectBefore.SectI.Stiffness.Czp;
		dCzm = SectD.SectBefore.SectI.Stiffness.Czm;

		BOOL bFind = FALSE;
		T_TDPF_INFO TdpfInfo;
		int nTdpfSize = TdpfD.aInfo.GetSize();
		for (int j = 0; j < nTdpfSize; ++j)
		{
			TdpfInfo = TdpfD.aInfo[j];
			if (TdpfInfo.strBoundaryCondition == strBoundaryCondition)
			{
				bFind = TRUE;
				break;
			}
		}
		if (!bFind) { ASSERT(0); continue; }
		

		BOOL bSpline = TRUE;
		CArray<T_TDNA_BASE, T_TDNA_BASE&> aProfile;
		if(!calPostTensionTendonProfileDetailSub(TdpfInfo, PTbase, dCzp, dCzm, aProfile, bSpline) ) { ASSERT(0); continue; }

		// Beam type은 Spline / Round 둘중 하나만 되도록 함 
		if (i == 0)
		{
			DataTdna.TendonTypeKey = TendonTypeKey;
			DataTdna.nCurveType    = (bSpline) ? 0 : 1;   // 0:Spline, 1:Round(직선 그릴때)
			DataTdna.nTendonShape  = 2;                   // 2:Element
			DataTdna.InsertElemKey = PTbase.aElemK[0];
			DataTdna.nInputType    = 0;                   // 2D

			dLastX = aProfile[aProfile.GetSize() - 1].x;
		}
		else
		{
			for (int j = 0; j < aProfile.GetSize(); ++j)
			{
				aProfile[j].x += dLastX;
			}

			dLastX = aProfile[aProfile.GetSize() - 1].x;
		}

		// aProfile을 map에 저장 (x 좌표가 같으면 덮어씀)
		for (int j = 0; j < aProfile.GetSize(); ++j)
		{
			mapProfile[aProfile[j].x] = aProfile[j];
		}

		DataTdna.aElemList.Append(PTbase.aElemK);

	} // i

	// map에서 aProfileY, aProfileZ 생성
	for (std::map<double, T_TDNA_BASE>::iterator it = mapProfile.begin(); it != mapProfile.end(); ++it)
	{
		T_TDNA_BASE_2D ProfileY, ProfileZ;
		ProfileY.Initiaize();
		ProfileZ.Initiaize();
		
		ProfileY.x       = it->second.x;
		ProfileY.yz      = it->second.y;
		ProfileY.bFix    = it->second.bFix;
		ProfileY.dR      = it->second.dRy;
		ProfileY.dRadius = it->second.dRadius;
		
		ProfileZ.x       = it->second.x;
		ProfileZ.yz      = it->second.z;
		ProfileZ.bFix    = it->second.bFix;
		ProfileZ.dR      = it->second.dRz;
		ProfileZ.dRadius = it->second.dRadius;
		
		DataTdna.aProfileY.Add(ProfileY);
		DataTdna.aProfileZ.Add(ProfileZ);
	}

	CArray<T_NODE_D, T_NODE_D&> aTendonProfileTemp;
	CArray<BOOL, BOOL> aProfileInputPointTemp;
	CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xyTemp; CArray<BOOL, BOOL>* paProfileInputPoint_xyTemp;
	CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xzTemp; CArray<BOOL, BOOL>* paProfileInputPoint_xzTemp;

	if (paTendonProfile_xy	   == NULL) paTendonProfile_xyTemp     = NULL;
	if (paTendonProfile_xz	   == NULL) paTendonProfile_xzTemp     = NULL;
	if (paProfileInputPoint_xy == NULL) paProfileInputPoint_xyTemp = NULL;
	if (paProfileInputPoint_xz == NULL) paProfileInputPoint_xzTemp = NULL;

	int nSlabType = 0; // Beam
	CTendonProfile TendonProfile(m_pDoc);
	TendonProfile.SetPTSlabFlag(nSlabType);
	BOOL bChk = TendonProfile.calcTendonProfile(DataTdna, aTendonProfileTemp, aProfileInputPointTemp, nDivide, bOnlyTendonLocalCoor, bOnlyControlPoint, bOnlyElementLocalCoor,
								   			    paTendonProfile_xyTemp, paProfileInputPoint_xyTemp, paTendonProfile_xzTemp, paProfileInputPoint_xzTemp);
	if (!bChk) { ASSERT(0); }

	aTendonProfile.Append(aTendonProfileTemp);
	aProfileInputPoint.Append(aProfileInputPointTemp);
	if (paTendonProfile_xy     && paTendonProfile_xyTemp    ) paTendonProfile_xy    ->Append(*paTendonProfile_xyTemp);
	if (paProfileInputPoint_xy && paProfileInputPoint_xyTemp) paProfileInputPoint_xy->Append(*paProfileInputPoint_xyTemp);
	if (paTendonProfile_xz     && paTendonProfile_xzTemp    ) paTendonProfile_xz    ->Append(*paTendonProfile_xzTemp);
	if (paProfileInputPoint_xz && paProfileInputPoint_xzTemp) paProfileInputPoint_xz->Append(*paProfileInputPoint_xzTemp);

	return bChk;
}

BOOL CAttrCtrl::calPostTensionTendonProfileDetail_Slab(T_TDPF_D& TdpfD, T_SPAN_PT& SpanPT, T_TDNT_K TendonTypeKey, int nDivide, CArray<T_NODE_D, T_NODE_D&>& aTendonProfile, CArray<BOOL, BOOL>& aProfileInputPoint,
												 BOOL bOnlyTendonLocalCoor, BOOL bOnlyControlPoint, BOOL bOnlyElementLocalCoor,		
												 CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xy, CArray<BOOL, BOOL>* paProfileInputPoint_xy, 
												 CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xz, CArray<BOOL, BOOL>* paProfileInputPoint_xz)
{
	aTendonProfile.RemoveAll();
	aProfileInputPoint.RemoveAll();
	if (paTendonProfile_xy     != NULL)paTendonProfile_xy->RemoveAll();
	if (paProfileInputPoint_xy != NULL)paProfileInputPoint_xy->RemoveAll();
	if (paTendonProfile_xz     != NULL)paTendonProfile_xz->RemoveAll();
	if (paProfileInputPoint_xz != NULL)paProfileInputPoint_xz->RemoveAll();

	int nCount = SpanPT.aSpanPTBase.GetSize();
	if (nCount < 1) { ASSERT(0); return FALSE; }

	CArray<T_TDNA_BASE, T_TDNA_BASE> aProfile;
	T_TDNA_D DataTdna; 
	CString strBoundaryCondition;

	for (int i = 0; i < nCount; ++i)
	{
		T_SPAN_PT_BASE PTbase = SpanPT.aSpanPTBase[i];

		// 1. strBoundaryCondition
		strBoundaryCondition = _T("First");

		if (i == 0) // Span 1
		{
			strBoundaryCondition = _T("First");
		}
		else if (i == nCount-1) // Span end
		{
			strBoundaryCondition = _T("Last");
		}
		else
		{
			strBoundaryCondition = _T("Middle");
		}

		// 2.
		double dCzp = 0.0;
		double dCzm = 0.0;
		if (SpanPT.bPTSlab)
		{
			//////////////////////////////////////////////////////////////////////////
			// 수정 필요
			CArray<T_ELEM_K, T_ELEM_K> aElemList;
			GetConnectedElem(PTbase.arPairs[0].nStart, aElemList);
			if (aElemList.GetSize() == 0) { ASSERT(0); return FALSE; }

			T_ELEM_D ElemD;
			BOOL bChk = FALSE;
			for (int nPl = 0; nPl < aElemList.GetSize(); ++nPl)
			{
				if (!GetElem(aElemList[nPl], ElemD)) continue;
				if (!IsPlaneType(ElemD.eltyp) ) continue;

				bChk = TRUE;
				break;
			}
			if (!bChk) { ASSERT(0); return FALSE;}
			//////////////////////////////////////////////////////////////////////////

			T_THIK_D ThikD;
			GetThik(ElemD.elpro, ThikD);
			double dThickness = ThikD.Value.ThickIn;
			dCzp = dThickness / 2.0;
			dCzm = dThickness / 2.0;
		}
		else // PT Beam
		{
			ASSERT(0);
		}

		BOOL bFind = FALSE;
		T_TDPF_INFO TdpfInfo;
		int nTdpfSize = TdpfD.aInfo.GetSize();
		for (int j = 0; j < nTdpfSize; ++j)
		{
			TdpfInfo = TdpfD.aInfo[j];
			if (TdpfInfo.strBoundaryCondition == strBoundaryCondition)
			{
				bFind = TRUE;
				break;
			}
		}
		if (!bFind) { ASSERT(0); continue; }
		

		BOOL bSpline = TRUE;
		CArray<T_TDNA_BASE, T_TDNA_BASE&> aProfile;
		if(!calPostTensionTendonProfileDetailSub(TdpfInfo, PTbase, dCzp, dCzm, aProfile, bSpline) ) { ASSERT(0); continue; }

		int nSlabType = 0;
		DataTdna.Initialize();
		if (SpanPT.bPTSlab)
		{
			nSlabType = 2;
			if (PTbase.arPairs.GetSize() != PTbase.arPairPos.GetSize())
			{
				ASSERT(0); continue;
			}

			// Node_K 
			int nPair = PTbase.arPairs.GetSize();
			for (int j = 0; j < nPair; ++j)
			{
				DataTdna.aElemList.Add(PTbase.arPairs[j].nStart);
				if (j == nPair - 1)
				{
					DataTdna.aElemList.Add(PTbase.arPairs[j].nEnd);
				}
			}

			// Node_D
			T_TDNA_BASE_2D BaseY, BaseZ;
			nPair = PTbase.arPairPos.GetSize();
			for (int j = 0; j < nPair; ++j)
			{
				T_NODE_D NODE1 = PTbase.arPairPos[j].StartPos;
				T_NODE_D NODE2 = PTbase.arPairPos[j].EndPos;

				BaseY.x = NODE1.x; 	BaseY.yz = NODE1.y;
				BaseZ.x = NODE1.x; 	BaseZ.yz = NODE1.z;
				DataTdna.aProfileY.Add(BaseY);
				DataTdna.aProfileZ.Add(BaseZ);
				if (j == nPair - 1)
				{
					BaseY.x = NODE2.x; 	BaseY.yz = NODE2.y;
					BaseZ.x = NODE2.x; 	BaseZ.yz = NODE2.z;
					DataTdna.aProfileY.Add(BaseY);
					DataTdna.aProfileZ.Add(BaseZ);
				}
			}
			
			DataTdna.TendonTypeKey = TendonTypeKey;
			DataTdna.nCurveType    = (bSpline) ? 0 : 1; // 0:Spline, 1:Round(직선 그릴때)
			DataTdna.nTendonShape  = 2;                 // 2:Element
			DataTdna.InsertElemKey = 0;
			DataTdna.nInputType    = 1;                 // 3D
			DataTdna.aProfile.Append(aProfile);
		}
		else
		{
			ASSERT(0);
		}

		CArray<T_NODE_D, T_NODE_D&> aTendonProfileTemp;
		CArray<BOOL, BOOL> aProfileInputPointTemp;
		CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xyTemp; CArray<BOOL, BOOL>* paProfileInputPoint_xyTemp;
		CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xzTemp; CArray<BOOL, BOOL>* paProfileInputPoint_xzTemp;

		if (paTendonProfile_xy	   == NULL) paTendonProfile_xyTemp     = NULL;
		if (paTendonProfile_xz	   == NULL) paTendonProfile_xzTemp     = NULL;
		if (paProfileInputPoint_xy == NULL) paProfileInputPoint_xyTemp = NULL;
		if (paProfileInputPoint_xz == NULL) paProfileInputPoint_xzTemp = NULL;

		CTendonProfile TendonProfile(m_pDoc);
		TendonProfile.SetPTSlabFlag(nSlabType);
		BOOL bChk = TendonProfile.calcTendonProfile(DataTdna, aTendonProfileTemp, aProfileInputPointTemp, nDivide, bOnlyTendonLocalCoor, bOnlyControlPoint, bOnlyElementLocalCoor,
								   			    	paTendonProfile_xyTemp, paProfileInputPoint_xyTemp, paTendonProfile_xzTemp, paProfileInputPoint_xzTemp);
		if (!bChk) { ASSERT(0); continue; }

		aTendonProfile.Append(aTendonProfileTemp);
		aProfileInputPoint.Append(aProfileInputPointTemp);
		if (paTendonProfile_xy     && paTendonProfile_xyTemp    ) paTendonProfile_xy    ->Append(*paTendonProfile_xyTemp);
		if (paProfileInputPoint_xy && paProfileInputPoint_xyTemp) paProfileInputPoint_xy->Append(*paProfileInputPoint_xyTemp);
		if (paTendonProfile_xz     && paTendonProfile_xzTemp    ) paTendonProfile_xz    ->Append(*paTendonProfile_xzTemp);
		if (paProfileInputPoint_xz && paProfileInputPoint_xzTemp) paProfileInputPoint_xz->Append(*paProfileInputPoint_xzTemp);

	} // i

	return TRUE;
}

BOOL CAttrCtrl::calPostTensionTendonProfileDetail_Distribute(T_TDPF_D& TdpfD, T_SPAN_PT& NewSpanPT, T_TDNT_K TendonTypeKey, int nDivide,
													 CArray<T_NODE_D, T_NODE_D&>& aTendonProfile, CArray<BOOL, BOOL>& aProfileInputPoint,
													 BOOL bOnlyTendonLocalCoor, BOOL bOnlyControlPoint, BOOL bOnlyElementLocalCoor,		
													 CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xy, CArray<BOOL, BOOL>* paProfileInputPoint_xy, 
													 CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xz, CArray<BOOL, BOOL>* paProfileInputPoint_xz)
{
	aTendonProfile.RemoveAll();
	aProfileInputPoint.RemoveAll();
	if (paTendonProfile_xy     != NULL)paTendonProfile_xy->RemoveAll();
	if (paProfileInputPoint_xy != NULL)paProfileInputPoint_xy->RemoveAll();
	if (paTendonProfile_xz     != NULL)paTendonProfile_xz->RemoveAll();
	if (paProfileInputPoint_xz != NULL)paProfileInputPoint_xz->RemoveAll();

	int nCount = NewSpanPT.aSpanPTBase.GetSize(); // Span별 데이터
	if (nCount < 1) { ASSERT(0); return FALSE; }

	CArray<T_TDNA_BASE, T_TDNA_BASE> aProfile;
	T_TDNA_D DataTdna; 
	CString strBoundaryCondition;

	for (int i = 0; i < nCount; ++i)
	{
		T_SPAN_PT_BASE PTbase = NewSpanPT.aSpanPTBase[i];

		// 1. strBoundaryCondition
		strBoundaryCondition = _T("1-Span(First-Last)");

		if (i == 0) // Span 1
		{
			if (nCount == 1)
			{
				strBoundaryCondition = _T("1-Span(First-Last)");
			}
			else
			{
				switch (PTbase.nSupportPT)
				{
				case 2: strBoundaryCondition = _T("Cantilever(First)");     break;
				case 3: strBoundaryCondition = _T("End-Continuous(First)"); break;
				default:
					ASSERT(0); // 검토 필요
				}
			}	
		}
		else if (i == nCount-1) // Span end
		{
			switch (PTbase.nSupportPT)
			{
			case 1: strBoundaryCondition = _T("Cantilever(Last)");     break;
			case 3: strBoundaryCondition = _T("Continuous-End(Last)"); break;
			default:
				ASSERT(0); // 검토 필요
			}
		}
		else
		{
			strBoundaryCondition = _T("Both Continuous");
		}

		// 2.
		double dCzp = 0.0;
		double dCzm = 0.0;
		if (NewSpanPT.bPTSlab)
		{
			//////////////////////////////////////////////////////////////////////////
			// 수정 필요
			CArray<T_ELEM_K, T_ELEM_K> aElemList;
			GetConnectedElem(PTbase.arPairs[0].nStart, aElemList);  // Node -> Elem
			if (aElemList.GetSize() == 0) { ASSERT(0); return FALSE; }

			T_ELEM_D ElemD;
			BOOL bChk = FALSE;
			for (int nPl = 0; nPl < aElemList.GetSize(); ++nPl)
			{
				if (!GetElem(aElemList[nPl], ElemD)) continue;
				if (!IsPlaneType(ElemD.eltyp) ) continue;

				bChk = TRUE;
				break;
			}
			if (!bChk) { ASSERT(0); return FALSE;}
			//////////////////////////////////////////////////////////////////////////

			T_THIK_D ThikD;
			GetThik(ElemD.elpro, ThikD);
			double dThickness = ThikD.Value.ThickIn;
			dCzp = dThickness / 2.0;
			dCzm = dThickness / 2.0;
		}
		else // PT Beam
		{
			T_ELEM_D ElemD;
			if (!GetElem(PTbase.aElemK[0], ElemD)) ASSERT(0);
			T_SECT_D SectD;
			if (!GetSect(ElemD.elpro, SectD)) ASSERT(0);
			dCzp = SectD.SectBefore.SectI.Stiffness.Czp;
			dCzm = SectD.SectBefore.SectI.Stiffness.Czm;
		}

		BOOL bFind = FALSE;
		T_TDPF_INFO TdpfInfo;
		int nTdpfSize = TdpfD.aInfo.GetSize();
		for (int j = 0; j < nTdpfSize; ++j)
		{
			TdpfInfo = TdpfD.aInfo[j];
			if (TdpfInfo.strBoundaryCondition == strBoundaryCondition)
			{
				bFind = TRUE;
				break;
			}
		}
		if (!bFind) { ASSERT(0); continue; }
		

		BOOL bSpline = TRUE;
		CArray<T_TDNA_BASE, T_TDNA_BASE&> aProfile;
		if(!calPostTensionTendonProfileDetailSub(TdpfInfo, PTbase, dCzp, dCzm, aProfile, bSpline) ) { ASSERT(0); continue; }

		int nSlabType = 0;
		DataTdna.Initialize();
		if (NewSpanPT.bPTSlab)
		{
			nSlabType = 2;

			if (PTbase.arPairs.GetSize() != PTbase.arPairPos.GetSize())
			{
				ASSERT(0); continue;
			}

			// Node_K 
			int nPair = PTbase.arPairs.GetSize();
			for (int j = 0; j < nPair; ++j)
			{
				DataTdna.aElemList.Add(PTbase.arPairs[j].nStart);
				if (j == nPair - 1)
				{
					DataTdna.aElemList.Add(PTbase.arPairs[j].nEnd);
				}
			}

			// Node_D -> 변수 추가는 어떤가...
			T_TDNA_BASE_2D BaseY, BaseZ;
			nPair = PTbase.arPairPos.GetSize();
			for (int j = 0; j < nPair; ++j)
			{
				T_NODE_D NODE1 = PTbase.arPairPos[j].StartPos;
				T_NODE_D NODE2 = PTbase.arPairPos[j].EndPos;

				BaseY.x  = NODE1.x; 	BaseY.yz = NODE1.y;
				BaseZ.x  = NODE1.x; 	BaseZ.yz = NODE1.z;
				DataTdna.aProfileY.Add(BaseY);
				DataTdna.aProfileZ.Add(BaseZ);
				if (j == nPair - 1)
				{
					BaseY.x = NODE2.x; 	BaseY.yz = NODE2.y;
					BaseZ.x = NODE2.x; 	BaseZ.yz = NODE2.z;
					DataTdna.aProfileY.Add(BaseY);
					DataTdna.aProfileZ.Add(BaseZ);
				}
			}

			DataTdna.TendonTypeKey = TendonTypeKey;
			DataTdna.nCurveType    = (bSpline) ? 0 : 1; // 0:Spline, 1:Round(직선 그릴때)
			DataTdna.nTendonShape  = 2;                 // 2:Element
			DataTdna.InsertElemKey = 0;
			DataTdna.nInputType    = 1;                 // 3D
			DataTdna.aProfile.Append(aProfile);
		}
		else  // PT beam
		{
			nSlabType = 0;

			ASSERT(0);
			DataTdna.aElemList.Append(PTbase.aElemK);

			DataTdna.TendonTypeKey = TendonTypeKey;
			DataTdna.nCurveType    = (bSpline) ? 0 : 1;   // 0:Spline, 1:Round(직선 그릴때)
			DataTdna.nTendonShape  = 2;                   // 2:Element
			DataTdna.InsertElemKey = PTbase.aElemK[0];
			DataTdna.nInputType    = 1;                   // 3D
			DataTdna.aProfile.Append(aProfile);
		}

		CArray<T_NODE_D, T_NODE_D&> aTendonProfileTemp;
		CArray<BOOL, BOOL> aProfileInputPointTemp;
		CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xyTemp; CArray<BOOL, BOOL>* paProfileInputPoint_xyTemp;
		CArray<T_NODE_D, T_NODE_D&>* paTendonProfile_xzTemp; CArray<BOOL, BOOL>* paProfileInputPoint_xzTemp;

		if (paTendonProfile_xy	   == NULL) paTendonProfile_xyTemp     = NULL;
		if (paTendonProfile_xz	   == NULL) paTendonProfile_xzTemp     = NULL;
		if (paProfileInputPoint_xy == NULL) paProfileInputPoint_xyTemp = NULL;
		if (paProfileInputPoint_xz == NULL) paProfileInputPoint_xzTemp = NULL;

		CTendonProfile TendonProfile(m_pDoc);
		TendonProfile.SetPTSlabFlag(nSlabType);
		BOOL bChk = TendonProfile.calcTendonProfile(DataTdna, aTendonProfileTemp, aProfileInputPointTemp, nDivide, bOnlyTendonLocalCoor, bOnlyControlPoint, bOnlyElementLocalCoor,
								   			    	paTendonProfile_xyTemp, paProfileInputPoint_xyTemp, paTendonProfile_xzTemp, paProfileInputPoint_xzTemp);
		if (!bChk) { ASSERT(0); continue; }

		aTendonProfile.Append(aTendonProfileTemp);
		aProfileInputPoint.Append(aProfileInputPointTemp);
		if (paTendonProfile_xy     && paTendonProfile_xyTemp    ) paTendonProfile_xy    ->Append(*paTendonProfile_xyTemp);
		if (paProfileInputPoint_xy && paProfileInputPoint_xyTemp) paProfileInputPoint_xy->Append(*paProfileInputPoint_xyTemp);
		if (paTendonProfile_xz     && paTendonProfile_xzTemp    ) paTendonProfile_xz    ->Append(*paTendonProfile_xzTemp);
		if (paProfileInputPoint_xz && paProfileInputPoint_xzTemp) paProfileInputPoint_xz->Append(*paProfileInputPoint_xzTemp);

	} // i

	return TRUE;
}


double CAttrCtrl::NodeDot(const T_NODE_D& a, const T_NODE_D& b)
{
	return a.x * b.x + a.y * b.y + a.z * b.z;
}
T_NODE_D CAttrCtrl::NodeCross(const T_NODE_D& a, const T_NODE_D& b)
{
	return {
		a.y * b.z - a.z * b.y,
		a.z * b.x - a.x * b.z,
		a.x * b.y - a.y * b.x
	};
}
double CAttrCtrl::NodeLength(const T_NODE_D& v)
{
	double dDot = v.x * v.x + v.y * v.y + v.z * v.z;
	return sqrt(dDot);
}
T_NODE_D CAttrCtrl::NodeNormalize(const T_NODE_D& v)
{
	double len = NodeLength(v);
	if (len <= 1e-12)
		return { 0.0, 0.0, 0.0 };
	return { v.x / len, v.y / len, v.z / len };
}
// Data1을 t=0, Data2를 t=1 로 기준화한 파라미터 값 계산 (선분 투영)
double CAttrCtrl::paramT(const T_NODE_D& p, const T_NODE_D& Data1, const T_NODE_D& Data2)
{
	T_NODE_D d = Data2 - Data1;   // 방향 벡터
	T_NODE_D v = p - Data1;       // 시작점 기준으로 p까지 벡터
	double dd = NodeDot(d, d);
	if (dd == 0.0) return 0.0;     // Data1 == Data2 예외 처리
	return NodeDot(v, d) / dd;         // 선분 내 상대 위치 (0 ~ 1)
}
bool CAttrCtrl::ExistsInProfile(const CArray<T_NODE_D, T_NODE_D&>& arr, const T_NODE_D& p)
{
	for (int i = 0; i < arr.GetSize(); ++i)
	{
		const T_NODE_D& q = arr[i];
		if (q.x == p.x && q.y == p.y && q.z == p.z)
			return true;
	}
	return false;
}

void CAttrCtrl::FindPointsBetweenNode(T_NODE_D& Data1, T_NODE_D& Data2,	CArray<T_NODE_D, T_NODE_D&>& aCPointsR, CArray<T_NODE_D, T_NODE_D&>& arResult)
{
	CArray<T_NODE_D, T_NODE_D&> arResult01;
	arResult01.RemoveAll();
	for (int i = 0; i < aCPointsR.GetSize(); ++i)
	{
		T_NODE_D& p = aCPointsR[i];
		double t = paramT(p, Data1, Data2);

		if (t < 0.0)      continue;   // Data1 이전 → skip
		if (t > 1.0)      break;      // Data2 이후 → 더 이상 검사 불필요 (정렬 가정)

		arResult01.Add(p);              // Data1 ≤ p ≤ Data2
	}

	auto NearlyEqual = [](double a, double b, double eps = 1e-9)
	{
		return fabs(a - b) <= eps;
	};

	auto IsDuplicate = [&](const CArray<T_NODE_D, T_NODE_D&>& arr, const T_NODE_D& p) -> bool
	{
		for (int i = 0; i < arr.GetSize(); ++i)
		{
			const T_NODE_D& q = arr[i];
			if (NearlyEqual(q.x, p.x) &&
				NearlyEqual(q.y, p.y) &&
				NearlyEqual(q.z, p.z))
				return true;
		}
		return false;
	};

	// 중복 제거
	arResult.RemoveAll();
	for (int i = 0; i < arResult01.GetSize(); ++i)
	{
		T_NODE_D& p = arResult01[i];
		if (!IsDuplicate(arResult, p))
		{
			arResult.Add(p);
		}
	}
}

// ----------------------------------------
// 3D 공간에서 Up 벡터 기준 좌측 단위벡터 계산
// t : 선분 AB 방향 단위벡터
// up: "위쪽" 기준 벡터 (필수: t와 평행하면 안 됨)
// left = normalize( up × t )
// ----------------------------------------
T_NODE_D CAttrCtrl::ComputeLeftFromUpAndT(const T_NODE_D& up_raw, const T_NODE_D& t)
{
	T_NODE_D up = NodeNormalize(up_raw);
	T_NODE_D left = NodeCross(up, t);  // up × t

	double len = NodeLength(left);
	if (len <= 1e-12)
	{
		// up이 t와 거의 평행한 경우: 다른 임의 up 사용 (예: 세계좌표 Z축)
		T_NODE_D fallbackUp = { 0.0, 0.0, 1.0 };
		left = NodeCross(fallbackUp, t);
		len = NodeLength(left);
		if (len <= 1e-12)
		{
			// 그래도 평행이면 X축을 써본다
			fallbackUp = { 1.0, 0.0, 0.0 };
			left = NodeCross(fallbackUp, t);
			len = NodeLength(left);
			if (len <= 1e-12)
			{
				// 정말 최악의 경우: 임의로 Y축 반환
				return { 0.0, 1.0, 0.0 };
			}
		}
	}
	return { left.x / len, left.y / len, left.z / len };
}

// right = normalize( t × up )
T_NODE_D CAttrCtrl::ComputeRightFromUpAndT(const T_NODE_D& up_raw, const T_NODE_D& t)
{
	T_NODE_D up = NodeNormalize(up_raw);
	T_NODE_D right = NodeCross(t, up);  // t × up (오른쪽 방향)

	double len = NodeLength(right);
	if (len <= 1e-12)
	{
		// up이 t와 거의 평행한 경우: 다른 임의 up 사용 (예: Z축)
		T_NODE_D fallbackUp = { 0.0, 0.0, 1.0 };
		right = NodeCross(t, fallbackUp);
		len = NodeLength(right);

		if (len <= 1e-12)
		{
			// 그래도 평행이면 X축을 사용
			fallbackUp = { 1.0, 0.0, 0.0 };
			right = NodeCross(t, fallbackUp);
			len = NodeLength(right);

			if (len <= 1e-12)
			{
				// 최악의 상황: 임의 방향 리턴 (Y축)
				return { 0.0, -1.0, 0.0 };
			}
		}
	}

	return { right.x / len, right.y / len, right.z / len };
}

// ------------------------------------------
// A, B 와 팔 길이(좌/우) + Up 벡터를 받아서
// C1,C2,D1,D2 및 5등분 단면 선분들을 구한다.
// ------------------------------------------
//
// nDiv: 등분 개수 (문제 조건: 5)
// up  : "위쪽" 기준 벡터 (예: {0,0,1})
//
void CAttrCtrl::BuildOffsetSections3D(const T_NODE_D& A, const T_NODE_D& B,
									  double LA1, double LB1,   // A점에서 좌/우 팔 길이
									  double LA2, double LB2,   // B점에서 좌/우 팔 길이
									  CArray<T_DSPS_K, T_DSPS_K>& aDspsK,
									  std::vector<std::pair<T_NODE_D, T_NODE_D>>& outSegments,  // 각 단면을 (left, right) 점 쌍으로 저장
									  std::vector<std::pair<double, double>>& aArms,
									  CArray<T_NODE_D, T_NODE_D&>& aCenterNodeD)
{
	outSegments.clear();
	aArms.clear();
	aCenterNodeD.RemoveAll();

	// 1) AB 방향 단위벡터 t
	T_NODE_D AB = B - A;
	T_NODE_D t = NodeNormalize(AB);
	if (NodeLength(t) <= 1e-12)
	{
		// A와 B가 같은 점이면 단면 생성 불가
		return;
	}

	// 2) Up 벡터 기준 좌/우 단위벡터
	T_NODE_D up{ 0.0, 0.0, 1.0 };                // 3D에서의 "위쪽" 기준 벡터
	T_NODE_D nL = ComputeLeftFromUpAndT(up, t);  // 좌측
	T_NODE_D nR = ComputeRightFromUpAndT(up, t); // 우측

	// 3) A, B 에서의 좌/우 점 계산
	T_NODE_D C1 = A + nL * LA1;    // A에서 좌측
	T_NODE_D C2 = A + nR * LB1;    // A에서 우측

	T_NODE_D D1 = B + nL * LA2;    // B에서 좌측
	T_NODE_D D2 = B + nR * LB2;    // B에서 우측

	int nDiv = aDspsK.GetSize();
	for (int i = 0; i < nDiv; ++i)
	{
		T_DSPS_D DspsD;
		if (!m_pDoc->m_pAttrCtrl2->GetDsps(aDspsK[i], DspsD)) { ASSERT(0); continue; }

		// 4) C1-D1, C2-D2 사이를 nDiv 등분
		//    t = 0, 1/nDiv, ..., 1 에서 단면 생성
		double dRatio = DspsD.dDist; // (double)i / (double)(nDiv);

		T_NODE_D left  = LinearInterpolNode(C1, D1, 0, dRatio);   // 왼쪽 선 위의 점
		T_NODE_D right = LinearInterpolNode(C2, D2, 0, dRatio);  // 오른쪽 선 위의 점
		outSegments.emplace_back(left, right);

		// 5) 단면 중심점 저장
		T_NODE_D Center = LinearInterpolNode(A, B, 0, dRatio);
		aCenterNodeD.Add(Center);

		// 6) 팔 길이 저장
		double dL = NodeLength(left - Center);
		double dR = NodeLength(right - Center);
		aArms.emplace_back(dL, dR);
	}
}

void CAttrCtrl::ComputeLeftRightFromCenter(	const T_NODE_D& Center,
											const T_NODE_D& vec,      // Dstr Sect 단위벡터
											double dL, double dR,     // 좌/우 팔 길이
											T_NODE_D& left,
											T_NODE_D& right)
{
    // 좌/우 단위벡터
	T_NODE_D up{ 0.0, 0.0, 1.0 };                   // 3D에서의 "위쪽" 기준 벡터
    T_NODE_D nL = ComputeLeftFromUpAndT(up, vec);   // 좌측 방향 단위벡터
    T_NODE_D nR = ComputeRightFromUpAndT(up, vec);  // 우측 방향 단위벡터

    // 팔 길이만큼 이동해서 좌/우 점 계산
    left  = Center + nL * dL;
    right = Center + nR * dR;
}

