// 			bSpline = FALSE;
// 			break;
// 
// 		case ProfileType::Straight2: // (C)Straight Type2 : 직선 (0, dYa) -> (dXa, dYa) -> (dL, dYc)
// 			setPF({ {0.0, dYa}, {dXa, dYa}, {dL, dYc} });
// 			bSpline = FALSE;
// 			break;
// 
// 		default:
