BOOL CAttrCtrl::GetStctForAnalysis(T_STCT_D& rData)
{
	if (!GetStct(rData)) return FALSE;

	int nAnalType     = rData.nIncludeNonLinearAnalysis; // nAnalType     = Linear / Nonlinear / Material Nonlinear     
	int nNonlAnalType = rData.nNonlAnalType;             // nNonlAnalType = Independent / Accumulative
	if(nAnalType == 0)
	{
		if(nNonlAnalType == 0)
		{
			// Cable-Pretension Force Control
			rData.nCablePretensionExternalOpt = 0;  // 0:Add, 1:Replace       

			// Initial Force Control

			// Initial Displacement for C.S.
			rData.bInitTangentDisp = FALSE;
			rData.nInitTangentDisp = 0;
			rData.bLackofFitForce = 0;

			// Initial Displacement for C.S - Camber.

			// Consider Stress Decrease at Transfer Length Zone by Post-tension

			// Frame Output
			rData.bCalcConcurrentForce = FALSE;
			//rData.bCalcCompSectionPart = FALSE;
			rData.bSelfCons = FALSE;
			// Save Output of Current Stage(Beam/Truss)
			rData.bSaveCurStageOutput = FALSE;
		}
		else if (nNonlAnalType == 1)
		{
			// Cable-Pretension Force Control
			// Initial Force Control
			// Initial Displacement for C.S.
			// Initial Displacement for C.S - Camber.
			// Consider Stress Decrease at Transfer Length Zone by Post-tension
			// Beam Section Property Changes
			// Frame Output
			// Save Output of Current Stage(Beam/Truss)
		}
	}
	else if (nAnalType == 1)
	{
		if (nNonlAnalType == 0)
		{
			// Cable-Pretension Force Control
			rData.nCablePretensionExternalOpt = 0;  // 0:Add, 1:Replace       

			// Initial Force Control

			// Initial Displacement for C.S.
			rData.bInitTangentDisp = FALSE;
			rData.nInitTangentDisp = 0;
			rData.bLackofFitForce = 0;

			// Initial Displacement for C.S - Camber.

			// Consider Stress Decrease at Transfer Length Zone by Post-tension
			rData.bConsiderEndPartStress = FALSE;
			rData.nEndPartStress = 0;
			rData.dStressRatio = 0.0;

			// Beam Section Property Changes

			// Frame Output
			rData.bCalcConcurrentForce = FALSE;
			rData.bCalcCompSectionPart = FALSE;
			rData.bSelfCons = FALSE;

			// Save Output of Current Stage(Beam/Truss)
			rData.bSaveCurStageOutput = FALSE;
		}
		else if (nNonlAnalType == 1)
		{
			// Cable-Pretension Force Control
			// Initial Force Control
			// Initial Displacement for C.S.
			// Initial Displacement for C.S - Camber.

			// Consider Stress Decrease at Transfer Length Zone by Post-tension
			rData.bConsiderEndPartStress = FALSE;
			rData.nEndPartStress = 0;
			rData.dStressRatio = 0.0;

			// Beam Section Property Changes
			// Frame Output
			
			// Save Output of Current Stage(Beam/Truss)
			rData.bSaveCurStageOutput = FALSE;
		}

	}
	else if (nAnalType == 2)
	{
		// Cable-Pretension Force Control
		rData.nCablePretensionForceCtrl   = 0;  // 0:Internal, 1:External
		rData.nCablePretensionExternalOpt = 0;  // 0:Add, 1:Replace       

		// Initial Force Control
		rData.bConvFinalStageMemberForce = FALSE;
		rData.bConvBeam  = FALSE;
		rData.bConvTruss = FALSE;
		rData.bChangeCableElementForPostCS = FALSE;
		rData.bApplyInitMemberForce        = FALSE;

		// Initial Displacement for C.S.
		rData.bInitTangentDisp = FALSE;
		rData.nInitTangentDisp = 0;
		rData.bLackofFitForce  = 0;
		// Initial Displacement for C.S - Camber.
		rData.bApplyCamber     = FALSE;

		// Consider Stress Decrease at Transfer Length Zone by Post-tension
		rData.bConsiderEndPartStress = FALSE;
		rData.nEndPartStress = 0;
		rData.dStressRatio = 0.0;

		// Beam Section Property Changes - 대화창에서 입력된 상태 넘기기
		//rData.nBeamSectionChange = 1;

		// Frame Output
		rData.bCalcConcurrentForce = FALSE;
		rData.bCalcCompSectionPart = FALSE; 
		rData.bSelfCons = FALSE;
		// Save Output of Current Stage(Beam/Truss)
		rData.bSaveCurStageOutput = FALSE;
	}
	else
	{
		ASSERT(0);
	}
		
	// Time Dependent Effect 
	if (rData.bIncludeTimeDependentEffect)
	{
		if (!rData.bCreepShrinkage)
		{
			rData.bOnlyUserCreepCoeff = FALSE;
			rData.bInternalTimeStep = FALSE;
			rData.bAutoTimeStep = FALSE;
			rData.bTTLECreepShrinkage = FALSE;
			rData.bConsiderConfinement = FALSE;
		}

		if (!rData.bVariation)
		{
			rData.bApplyTDElastic = FALSE;
		}
	}
	else
	{
		rData.bCreepShrinkage = FALSE;

		rData.bOnlyUserCreepCoeff = FALSE;
		rData.bInternalTimeStep = FALSE;
		rData.bAutoTimeStep = FALSE;
		rData.bTTLECreepShrinkage = FALSE;
		rData.bConsiderConfinement = FALSE;

		rData.bVariation = FALSE;
		rData.bApplyTDElastic = FALSE;

		rData.bTTLEElasticShortening = FALSE;
	}

	return TRUE;
}

