BOOL CAttrCtrl::IsRestartPrevStag4Rcsa(T_STAG_K CurStagK)
{
	T_RCSA_D RcsaD;
	if(!GetRcsa(RcsaD)) return FALSE;

	CArray<T_STAG_K, T_STAG_K> aStagK;
	GetStagKeyList(aStagK);
	int nStagSize = aStagK.GetSize();
	if(nStagSize<1) return FALSE;

	int nRestartStagIndex = 0, nCurStagIndex = 0;
	//T_STAG_K StagK;
	for(int i=0; i<nStagSize; ++i)
	{
		if(aStagK[i]==CurStagK) nCurStagIndex = i;
		if(aStagK[i]==RcsaD.RestartStagK) nRestartStagIndex = i;
	}

	return (nCurStagIndex<nRestartStagIndex);
}

BOOL CAttrCtrl::IsRestartStag4Rcsa(T_STAG_K CurStagK)
{
	T_RCSA_D RcsaD;
	if(!GetRcsa(RcsaD)) return FALSE;

	return (RcsaD.RestartStagK==CurStagK);
}

T_STAG_K CAttrCtrl::GetRestartPrevStagKey(T_STAG_K CurRestartStagK)
{
	if(CurRestartStagK<1) return 0;
	CArray<T_STAG_K, T_STAG_K> aStagK;
	GetStagKeyList(aStagK);
	int nSize = aStagK.GetSize();
	for(int i=0; i<nSize; ++i)
	{
		if(i>0 && aStagK[i]==CurRestartStagK) return aStagK[i-1];
	}
	return 0;
}

// Erection Load 및 CS로 정의된 것만 보여주기(Tendon 제외).
BOOL CAttrCtrl::GetErectionSelected(CMap<T_SGLD_K, T_SGLD_K, int, int>& mapErect)
{
	mapErect.InitHashTable(11);

#if defined(_CIVIL)
	int n = 0;
	T_STCT_D DataStct; DataStct.Initialize();
	BOOL bStct = GetStct(DataStct);

	for (n = 0; n < DataStct.aErection.GetSize(); n++)
	{
		T_SGLD_K Key = D_SGLD_ER1_CVL + n;
		mapErect.SetAt(Key, n);
	}

	mapErect.SetAt(D_SGLD_TP_CVL, n);  // Tendon은 무조건 포함.
	mapErect.SetAt(D_SGLD_TS_CVL, n);

	if (DataStct.bIncludeTimeDependentEffect)
	{
		if (DataStct.nType == 1)
		{
			mapErect.SetAt(D_SGLD_CP_CVL, n);
			mapErect.SetAt(D_SGLD_CS_CVL, n);
		}
		else if (DataStct.nType == 2)
		{
			mapErect.SetAt(D_SGLD_SP_CVL, n);
			mapErect.SetAt(D_SGLD_SS_CVL, n);
		}
		else if (DataStct.nType == 3)
		{
			mapErect.SetAt(D_SGLD_CP_CVL, n);
			mapErect.SetAt(D_SGLD_CS_CVL, n);
			mapErect.SetAt(D_SGLD_SP_CVL, n);
			mapErect.SetAt(D_SGLD_SS_CVL, n);
		}
	}
#else
	int n = 0;
	T_STCT_D DataStct; DataStct.Initialize();
	BOOL bStct = GetStct(DataStct);

	for (n = 0; n < DataStct.aErection.GetSize(); n++)
	{
		T_SGLD_K Key = D_SGLD_ER1_GEN + n;
		mapErect.SetAt(Key, n);
	}

	mapErect.SetAt(D_SGLD_TP_GEN, n);  // Tendon은 무조건 포함.
	mapErect.SetAt(D_SGLD_TS_GEN, n);

	if (DataStct.bIncludeTimeDependentEffect)
	{
		if (DataStct.nType == 1)
		{
			mapErect.SetAt(D_SGLD_CR_GEN, n);
		}
		else if (DataStct.nType == 2)
		{
			mapErect.SetAt(D_SGLD_SH_GEN, n);
		}
		else if (DataStct.nType == 3)
		{
			mapErect.SetAt(D_SGLD_CR_GEN, n);
			mapErect.SetAt(D_SGLD_SH_GEN, n);
		}
	}
#endif

	return TRUE;
}

int CAttrCtrl::GetBeamSectionChage()
{
	if (GetCountStag() > 0)
	{
		T_STCT_D StctD; StctD.Initialize();
		GetStct(StctD);
		return StctD.nBeamSectionChange;
	}
	else
	{
		T_ACTL_D ActlD; ActlD.Initialize();
		GetActl(ActlD);
		return ActlD.nBeamSectionChange;
	}

	return 0;
}

