////////////// rpos ////////////////
void CAttrCtrl::GetRposList(CArray<CString, CString&>& rstrRposList)
{
	rstrRposList.RemoveAll();

	int nCount=GetCountRpos();
	if(nCount == 0)return;

	POSITION pos;
	T_RPOS_K Key;
	T_RPOS_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartRpos();
		while(pos != NULL)
		{
			GetNextRpos(pos, Key, Data);
			if(Data.nSeq == i)
			{
				rstrRposList.Add(Data.Name);
				break;
			}
		}
	}
}

void CAttrCtrl::GetRposKeyList(CArray<T_RPOS_K, T_RPOS_K>& rRposKeyList)
{
	/*
	rKeyList.RemoveAll();

	int nCount=GetCountRpos();
	if(nCount == 0)return;

	POSITION pos;
	T_RPOS_K Key;
	T_RPOS_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartRpos();
	while(pos != NULL)
	{
	GetNextRpos(pos, Key, Data);
	if(Data.nSeq == i)
	{
	rKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rRposKeyList.RemoveAll();
	int nCount=GetCountRpos();
	if(nCount == 0)return;

	CArray<T_RPOS_K, T_RPOS_K> aRposKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rRposKeyList.SetSize(nCount);
	aRposKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_RPOS_K Key;
	T_RPOS_D Data;
	int i = 0;
	pos = GetStartRpos();
	while (pos != NULL)
	{
		GetNextRpos(pos, Key, Data);
		aRposKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.nSeq;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rRposKeyList[i] = aRposKey[ix];
	}
}

BOOL CAttrCtrl::ExistRpos(CString& rPosName)
{
	T_RPOS_D data;
	return GetRpos(rPosName, data);
}

BOOL CAttrCtrl::ExistRpos(T_RPOS_K Key)
{
	T_RPOS_D data;
	return GetRpos(Key, data);
}

BOOL CAttrCtrl::GetRpos(CString& rPosName, T_RPOS_D& rData)
{
	T_RPOS_K key;
	T_RPOS_D data;
	CString strPosName=rPosName;
	strPosName.TrimRight();

	POSITION pos=m_pDataMemb->m_rpos.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_rpos.GetNext(pos,key,data);
		if(strPosName.CompareNoCase(data.Name) == 0)
		{
			m_pUnitCtrl->ConvertUnitRposOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetRpos(T_RPOS_K Key, T_RPOS_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_rpos.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitRposOut(rData);
	return bReturn;
}

T_RPOS_K CAttrCtrl::GetRposKey(CString& rPosName)
{
	T_RPOS_K key;
	T_RPOS_D data;

	POSITION pos=GetStartRpos();
	while(pos != NULL)
	{
		GetNextRpos(pos,key,data);
		if(rPosName.CompareNoCase(data.Name) == 0)return key;
	}
	key=0;
	return key;
}

