void CAttrCtrl::InitializeMtbg(T_MTBG_D& rData)
{
	CDBDoc* pDoc = CDBDoc::GetDocPoint();
	rData.MainPost    = pDoc->m_pAttrCtrl->GetGrupKey(CString(_LS(IDS_DB_TOWER_MAIN_POST))   );
	rData.MainBracing = pDoc->m_pAttrCtrl->GetGrupKey(CString(_LS(IDS_DB_TOWER_MAIN_BRACING)));
	rData.ArmPost     = pDoc->m_pAttrCtrl->GetGrupKey(CString(_LS(IDS_DB_TOWER_ARM_POST))    );
	rData.ArmDiagonal = pDoc->m_pAttrCtrl->GetGrupKey(CString(_LS(IDS_DB_TOWER_ARM_DIAGONAL)));
	rData.ArmTie      = pDoc->m_pAttrCtrl->GetGrupKey(CString(_LS(IDS_DB_TOWER_ARM_TIE))     );
	rData.Redundant   = pDoc->m_pAttrCtrl->GetGrupKey(CString(_LS(IDS_DB_TOWER_REDUNDANT))   );
}

