void CAttrCtrl::InitializeBolt(T_BOLT_D& rData)
{
	rData.Post[0].dThickness = 0.005;   // 5mm
	rData.Post[1].dThickness = 0.0075;  // 7.5
	rData.Post[2].dThickness = 0.01;    // 10
	rData.Post[3].dThickness = 0.015;   // 15
	rData.Post[4].dThickness = 0.02;    // 20
	rData.Post[5].dThickness = 0.03;    // 30
	rData.Post[6].dThickness = 0.0;
	rData.Etc[0].dThickness = 0.005;    // 5mm
	rData.Etc[1].dThickness = 0.0075;   // 7.5
	rData.Etc[2].dThickness = 0.01;     // 10
	rData.Etc[3].dThickness = 0.015;    // 15
	rData.Etc[4].dThickness = 0.02;     // 20
	rData.Etc[5].dThickness = 0.03;     // 30
	rData.Etc[6].dThickness = 0.0;

	int aRowOfHole[] = { 1, 1, 2, 2, 2, 3, 3 };
	for (int i = 0; i < 7; i++)
	{
		rData.Post[i].nFlangeConnection = 1;
		rData.Post[i].nRowOfHole = aRowOfHole[i];
		rData.Etc[i].nFlangeConnection = 0;
		rData.Etc[i].nRowOfHole = aRowOfHole[i];
	}
	m_pUnitCtrl->ConvertUnitBoltOut(rData);
}

