BOOL CAttrCtrl::IsDcon_CrackForAASHTO()
{
	// AASHTO07 기준 이상 Corrosion, High Corrosion => Hide 
	T_DCON_D DConD;
	if (GetDcon(DConD))
	{
		if (DConD.DesignCode == CONCODE_AASHTO_LRFD07) { return TRUE; }
		if (DConD.DesignCode == CONCODE_AASHTO_LRFD12) { return TRUE; }
		if (DConD.DesignCode == CONCODE_AASHTO_LRFD16) { return TRUE; }
		if (DConD.DesignCode == CONCODE_AASHTO_LRFD17) { return TRUE; }
		if (DConD.DesignCode == CONCODE_AASHTO_LRFD20) { return TRUE; }
		if (DConD.DesignCode == CONCODE_AASHTO_LRFD24) { return TRUE; }
		if (DConD.DesignCode == CONCODE_AREMA_2023) { return TRUE; }
	}

	return FALSE;
}

