BOOL CAttrCtrl::GetRebbByElemK(UINT ElemK, T_REBB_D& rData)
{
	T_MEMB_K MembK;
	T_MEMB_D MembD;

	if(GetMembAssigned(ElemK, MembK))
	{
		if(!GetMemb(MembK, MembD))      {  ASSERT(0);		return 0;	}
		if(MembD.aElemList.GetSize() < 1)     {  ASSERT(0);		return FALSE;	}
		ElemK = MembD.aElemList[0];
	}

	T_MREB_D MrebD;
	if(GetMreb(ElemK, MrebD))
	{
		return GetRebb(MrebD.RebbK, rData);
	}
	else
	{
		T_ELEM_D ElemD;
		if(!m_pDataMemb->m_elem.Get(ElemK, ElemD)) return FALSE;
		return GetRebb(ElemD.elpro, rData);
	}  
}

T_REBB_K CAttrCtrl::GetRebbByElemK(T_ELEM_K ElemK)
{
    T_REBB_K rKey;
    rKey.keymap = 0;

    T_MEMB_K MembK;
    T_MEMB_D MembD;

    if ( GetMembAssigned(ElemK, MembK) )
    {
        if ( !GetMemb(MembK, MembD) ) { ASSERT(0);		return rKey; }
        if ( MembD.aElemList.GetSize() < 1 ) { ASSERT(0);		return rKey; }
        ElemK = MembD.aElemList[0];
    }

    T_MREB_D MrebD;
    if ( GetMreb(ElemK, MrebD) )
    {
        rKey = MrebD.RebbK;
    }
    else
    {
        T_ELEM_D ElemD;
        if ( !m_pDataMemb->m_elem.Get(ElemK, ElemD) ) return rKey;
        rKey.key.sectK = ElemD.elpro;
        rKey.key.subSectK = 0;
    }

    return rKey;
}

