BOOL CAttrCtrl::ExistWallID(int WallID)
{
	T_ELEM_K KeyElem;
	T_ELEM_D DataElem;
	POSITION pos = GetStartElem();
	while (pos != NULL)
	{
		GetNextElem(pos, KeyElem, DataElem);
		if (DataElem.eltyp == WALL_EL)
		{
			if (DataElem.nWallId == WallID) return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::ExistRebw(T_REBW_K Key)
{
	T_REBW_D Data;
	return m_pDataMemb->m_pRebw->Get(Key,Data);
}

BOOL CAttrCtrl::ExistRebwData(T_REBW_K Key)
{
	T_REBW_D Data;
	return GetRebw(Key,Data);
}

BOOL CAttrCtrl::GetRebw(T_REBW_K Key,T_REBW_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_pRebw->Get(Key,rData);
	if(bReturn)
	{
		m_pUnitCtrl->ConvertUnitRebwOut(rData);
		return TRUE;
	}

	UINT WallID = Key.key.wallid;
	UINT StorK = Key.key.storid;

	POSITION Pos = GetStartRebw();
	while(Pos)
	{
		GetNextRebw(Pos, Key, rData);
		if(Key.key.wallid != WallID)    continue;

		int nStorSize = rData.aStorK.GetSize();
		for(int i = 0; i < nStorSize; i++)
		{
			if(rData.aStorK[i] == StorK)        return TRUE;
		}
	}

	Key.key.wallid = WallID;
	Key.key.storid = 0;
	bReturn = m_pDataMemb->m_pRebw->Get(Key,rData);
	if(bReturn)    m_pUnitCtrl->ConvertUnitRebwOut(rData);

	return bReturn;
}

