int CAttrCtrl::GetRebwKeyListUsingWallID(int nWallID, CArray<T_REBW_K, T_REBW_K>& rKeyList)
{
	rKeyList.RemoveAll();

	CArray<UINT,UINT> aTempKey;

	POSITION pos;
	T_REBW_K Key;
	T_REBW_D Data;
	pos=GetStartRebw();
	while(pos != NULL)
	{
		GetNextRebw(pos, Key, Data);
		if(Key.key.wallid != nWallID)   continue;
		aTempKey.Add(Key.keymap);
	}

	int nKeySize = aTempKey.GetSize();
	if(nKeySize > 0)CQSort::QSortUInt(aTempKey.GetData(), aTempKey.GetSize());

	rKeyList.SetSize(nKeySize);
	for(int i = 0; i < nKeySize; i++)
	{
		rKeyList[i].keymap = aTempKey[i];
	}

	return nKeySize;
}

