T_RBMW_K CAttrCtrl::GetNextNumRbmw(T_RBMW_K StartNum)
{
	if(StartNum > GetLastNumRbmw())return StartNum;
	T_RBMW_K Key=StartNum;
	T_RBMW_D Data;
	while(TRUE)
	{
		Key++;
		if(!m_pDataMemb->m_pRbmw->Get(Key,Data))
		{
			if(Key < 1 || Key > 9999)
				return GetStartNumRbmw();
			else
				return Key;
		}
	}
}

