BOOL CAttrCtrl::GetRbmsByElemK(T_ELEM_K ElemK, int nLayer, T_RBMS_D& rData)
{
	T_MREB_D MrebD;
	if(!GetMreb(ElemK, MrebD)) return FALSE;
	if(MrebD.nMembType != MREB_MSLAB)   return FALSE;

	for (int i=0; i<MrebD.aRbmsK.GetSize(); i++)
	{
		T_RBMS_K RbmsK = MrebD.aRbmsK[i];
		if(!GetRbms(RbmsK, rData)) { ASSERT(0);	rData.Initialize();	return FALSE;	}    
		if(rData.nLayerType == nLayer) return TRUE;
	}

	ASSERT(0);
	return FALSE;
}

