int CAttrCtrl::GetElemKeyListUseRbsl(T_RBSL_K RbslK, CArray<T_ELEM_K, T_ELEM_K>& rKeyList)
{
	rKeyList.RemoveAll();

	if(!ExistRbsl(RbslK))     return 0;

	T_MREB_D MrebD;
	CArray<T_MREB_K, T_MREB_K> aMrebK;
	GetMrebKeyList(aMrebK);
	for (int i=0; i<aMrebK.GetSize(); i++)
	{
		GetMreb(aMrebK[i], MrebD);  
		if(MrebD.nMembType != MREB_SHELL) continue;
		for (int j=0; j<MrebD.aRbslK.GetSize(); j++)
		{
			if(RbslK == MrebD.aRbslK[j])
			{
				rKeyList.Add(aMrebK[i]);
				break;
			}
		}
	}

	int nSize = rKeyList.GetSize();
	if(nSize > 0)   CQSort::QSortUInt(rKeyList.GetData(), nSize);
	return nSize;
}

// nLayer : 0=Top-Dir1, 1=Bot-Dir1, 2=Top-Dir2, 3=Bot-Dir2
BOOL CAttrCtrl::GetRbslByElemK(T_ELEM_K ElemK, int nLayer, T_RBSL_D& rData)
{
	T_MREB_D MrebD;
	if(!GetMreb(ElemK, MrebD)) return FALSE;
	if(MrebD.nMembType != MREB_SHELL)   return FALSE;

	for (int i=0; i<MrebD.aRbslK.GetSize(); i++)
	{
		T_RBSL_K RbslK = MrebD.aRbslK[i];
		if(!GetRbsl(RbslK, rData)) { ASSERT(0);	rData.Initialize();	return FALSE;	}    
		if(rData.nLayerType == nLayer) return TRUE;
	}

	ASSERT(0);
	return FALSE;
}

BOOL CAttrCtrl::ChangeRbslInMreb(T_MREB_D& MrebD, T_RBSL_K RbslK)
{
	T_RBSL_D RbslD;
	if(!GetRbsl(RbslK, RbslD)) {ASSERT(0); return FALSE;} 

	for(int i=0; i<MrebD.aRbslK.GetSize(); i++)
	{
		T_RBSL_D Data;
		if(!GetRbsl(MrebD.aRbslK[i], Data)) {ASSERT(0); return FALSE;} 
		if(Data.nLayerType == RbslD.nLayerType)
		{
			MrebD.aRbslK[i] = RbslK;
			return TRUE;
		}
	}

	return FALSE;
}

BOOL CAttrCtrl::GetRbslPosInMreb(T_MREB_D& MrebD, BOOL bRbslPos[4])
{
	for (int i=0; i<4; i++) bRbslPos[i] = FALSE;
	for (int i=0; i<MrebD.aRbslK.GetSize(); i++)
	{
		T_RBSL_D RbslD;
		if(!GetRbsl(MrebD.aRbslK[i], RbslD)) {ASSERT(0); return FALSE;}
		if     (RbslD.nLayerType == 0) bRbslPos[0] = TRUE;
		else if(RbslD.nLayerType == 1) bRbslPos[1] = TRUE;
		else if(RbslD.nLayerType == 2) bRbslPos[2] = TRUE;
		else if(RbslD.nLayerType == 3) bRbslPos[3] = TRUE;
		else {ASSERT(0); return FALSE;}
	}
	return TRUE;
}  

////////////// wmak ////////////////
void CAttrCtrl::GetWmakList(CArray<CString, CString&>& rstrWmakList)
{
	rstrWmakList.RemoveAll();

	int nCount=GetCountWmak();
	if(nCount == 0)return;

	POSITION pos;
	T_WMAK_K Key;
	T_WMAK_D Data;
	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartWmak();
		while(pos != NULL)
		{
			GetNextWmak(pos, Key, Data);
			if(Data.MarkId == i)
			{
				rstrWmakList.Add(Data.MarkName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetWmakKeyList(CArray<T_WMAK_K, T_WMAK_K>& rWmakKeyList)
{
	/*
	rWmakKeyList.RemoveAll();

	int nCount=GetCountWmak();
	if(nCount == 0)return;

	POSITION pos;
	T_WMAK_K Key;
	T_WMAK_D Data;
	for(int i=1; i<=nCount; i++)
	{
	pos=GetStartWmak();
	while(pos != NULL)
	{
	GetNextWmak(pos, Key, Data);
	if(Data.MarkId == i)
	{
	rWmakKeyList.Add(Key);
	break;
	}
	}
	}
	*/
	rWmakKeyList.RemoveAll();
	int nCount=GetCountWmak();
	if(nCount == 0)return;

	CArray<T_WMAK_K, T_WMAK_K> aWmakKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	rWmakKeyList.SetSize(nCount);
	aWmakKey.SetSize(nCount);
	aPosIdPair.SetSize(nCount);

	POSITION pos;
	T_WMAK_K Key;
	T_WMAK_D Data;
	int i = 0;
	pos = GetStartWmak();
	while (pos != NULL)
	{
		GetNextWmak(pos, Key, Data);
		aWmakKey[i] = Key;
		aPosIdPair[i].nPos = i;
		aPosIdPair[i].nVal = Data.MarkId;
		i++;
	}

	// sort and copy
	int ix;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		ix = aPosIdPair[i].nPos;
		rWmakKeyList[i] = aWmakKey[ix];
	}
}

