T_RCHK_K CAttrCtrl::GetRchkByElemK(T_ELEM_K ElemK)
{
    T_RCHK_K rKey(0);

    T_MEMB_K MembK;
    T_MEMB_D MembD;

    if (GetMembAssigned(ElemK, MembK))
    {
        if (!GetMemb(MembK, MembD)) { ASSERT(0);		return rKey; }
        if (MembD.aElemList.GetSize() < 1) { ASSERT(0);		return rKey; }
        ElemK = MembD.aElemList[0];
    }

    T_ELEM_D ElemD;
    if (!m_pDataMemb->m_elem.Get(ElemK, ElemD)) return rKey;
    rKey = ElemD.elpro;

    return rKey;
}

