void CAttrCtrl::GetKeyListMembUser(CArray<T_MEMB_K, T_MEMB_K>* pKeyMemb,
								   CArray<T_NODE_K, T_NODE_K>* pKeyNode, CArray<T_ELEM_K, T_ELEM_K>* pKeyElem)
{
	if(pKeyNode != NULL)pKeyNode->RemoveAll();
	if(pKeyElem != NULL)pKeyElem->RemoveAll();
	if(pKeyNode == NULL && pKeyElem == NULL)return;
	int nCount=pKeyMemb->GetSize();
	if(nCount == 0)return;

	CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K>KeyElemMap;
	KeyElemMap.InitHashTable(m_pDoc->GetHashSizeElem());

	T_MEMB_D DataMemb;
	int nCountKeyMemb = pKeyMemb->GetSize();
	for(int i = 0; i < nCountKeyMemb; i++)
	{
		if(GetMemb(pKeyMemb->GetAt(i), DataMemb))
		{
			int nCountElem = DataMemb.aElemList.GetSize();
			for(int j = 0; j < nCountElem; j++)
				KeyElemMap.SetAt(DataMemb.aElemList[j], DataMemb.aElemList[j]);
		}
	}

	GetKeyListNodeElem(KeyElemMap, pKeyNode, pKeyElem);
}

