int  CAttrCtrl::GetMembNodeList(const T_MEMB_DT &lstElemInMemb, T_KEY_LIST &lstSortNode)
{
	lstSortNode.RemoveAll();    
	if(lstElemInMemb.GetCount() == 0)
		return 0;    
	T_ELEM_D Elem_1;
	if(!GetElem(lstElemInMemb[0], Elem_1))
		return 0;
	if(lstElemInMemb.GetCount() == 1)
	{
		lstSortNode.Add(Elem_1.elnod[0]);
		lstSortNode.Add(Elem_1.elnod[1]);
		return 2;
	}

	for(int i=1; i<lstElemInMemb.GetCount(); i++)
	{
		T_KEY NextK = lstElemInMemb[i];
		T_ELEM_D Elem_Next;
		if(!GetElem(NextK, Elem_Next))
			break; 
		if(i==1)
		{
			if(Elem_1.elnod[0] == Elem_Next.elnod[0] || Elem_1.elnod[0] == Elem_Next.elnod[1])
			{ 
				lstSortNode.Add(Elem_1.elnod[1]);
				lstSortNode.Add(Elem_1.elnod[0]);           
			}
			else if(Elem_1.elnod[1] == Elem_Next.elnod[0] || Elem_1.elnod[1] == Elem_Next.elnod[1])
			{
				lstSortNode.Add(Elem_1.elnod[0]);
				lstSortNode.Add(Elem_1.elnod[1]);
			}
			else
				break;
		}

		if(Elem_Next.elnod[0] == Elem_1.elnod[0] || Elem_Next.elnod[0] == Elem_1.elnod[1])
			lstSortNode.Add(Elem_Next.elnod[1]);        
		else if(Elem_Next.elnod[1] == Elem_1.elnod[0] || Elem_Next.elnod[1] == Elem_1.elnod[1])
			lstSortNode.Add(Elem_Next.elnod[0]);
		else
			break;
		Elem_1 = Elem_Next;
	}
	return lstSortNode.GetCount();
}

