BOOL CAttrCtrl::CheckMembCompatibility(T_MEMB_K Key, T_MEMB_D& rData, BOOL bTargetCH)
{  
	BOOL bReturn=m_pDataMemb->m_pMemb->Get(Key, rData);
	if(bReturn)
	{
		if(rData.aElemList.GetSize() == 0) return FALSE;
		if(!AlignMembElemList(Key, rData)) return FALSE;
		if(!IsMatchDirectionAttribute(rData,bTargetCH)) return FALSE;    
	}
	return bReturn;
}

BOOL CAttrCtrl::AlignMembElemList(T_MEMB_K Key, T_MEMB_D& rData)
{
	T_ELEM_K KeyElem;
	T_MEMB_K KeyMemb;
	T_ELEM_D DataElem;
	T_MEMB_D DataMemb;
	CMap<T_NODE_K, T_NODE_K, T_ELEM_K, T_ELEM_K> mapNodeiElem;
	CMap<T_NODE_K, T_NODE_K, T_ELEM_K, T_ELEM_K> mapNodejElem;
	CMap<T_NODE_K, T_NODE_K, int, int> mapInnerNode;         
	mapNodeiElem.InitHashTable(51);
	mapNodejElem.InitHashTable(51);
	mapInnerNode.InitHashTable(51);
	mapNodeiElem.RemoveAll();
	mapNodejElem.RemoveAll();
	mapInnerNode.RemoveAll();  
	int i, j, nTemp;
	int nElem = rData.aElemList.GetSize();
	BOOL bSuccess = FALSE;

	for( i = 0; i < nElem; i++)
	{        
		if(!GetElem(rData.aElemList[i], DataElem)) 
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_UDEF_DT_ELEM), _LS(IDS_DB_DT_MEMB), rData.aElemList[i]);    
		if(!IsFrameType(DataElem.eltyp))
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_IREG_DT_ELEM), rData.aElemList[i], _LS(IDS_DB_DT_MEMB));
	}  

	// 요소는 2개 이상의 Member에 포함될 수 없음(한개의 Member에만 포함)
	for( i = 0; i < nElem; i++)
	{
		POSITION pos=m_pDataMemb->m_pMemb->GetStart();
		while(pos)
		{
			DataMemb.Initialize();
			m_pDataMemb->m_pMemb->GetNext(pos, KeyMemb, DataMemb);
			if(Key != KeyMemb)
			{
				for(j = 0; j < DataMemb.aElemList.GetSize(); j++)
				{
					if(rData.aElemList.GetAt(i) == DataMemb.aElemList.GetAt(j)) 
					{
						GSaveHistoryFormatNF(_LS(IDS_DB_ERR_MEMB_USED), rData.aElemList[i]);  //"Error! Element %d is already used as a constituent of Member"
						return FALSE;
					}
				}
			}
		}    
	}

	int nMaxNum = nElem*2;
	if(nMaxNum<=0) {ASSERT(0); return FALSE;}
	int *nNodeIndex = new int[nMaxNum];   
	for( i = 0; i < nMaxNum; i++) nNodeIndex[i] = 0;    
	for( i = 0; i < nElem; i++)
	{    
		GetElem(rData.aElemList[i], DataElem);
		{
			nNodeIndex[2 * i] = DataElem.elnod[0];
			nNodeIndex[2 * i + 1] = DataElem.elnod[1];
			mapNodeiElem.SetAt(DataElem.elnod[0], rData.aElemList[i]);
			mapNodejElem.SetAt(DataElem.elnod[1], rData.aElemList[i]);
		}    
	}

	int nNumNode = 2 * rData.aElemList.GetSize();
	for( i = 0; i < nNumNode - 1; i++)    // 현재 Member의 내부 절점을 구한다.
	{
		for(j = i + 1; j < nNumNode; j++)
		{
			if(nNodeIndex[i] == nNodeIndex[j]) {mapInnerNode.SetAt(nNodeIndex[i], 0); break;}
		}
	}            

	if(mapNodeiElem.GetCount() != mapNodejElem.GetCount() ||  // 하나의 절점에 3개 이상의 요소가 연결된 경우
		mapNodeiElem.GetCount() != nElem ||   // 일부 요소의 방향이 다른 경우
		mapNodejElem.GetCount() != nElem ||   // 일부 요소의 방향이 다른 경우
		mapInnerNode.GetCount() != nElem - 1) // 멤버를 이루는 요소가 연결되어 있지 않거나 폐쇄형 일 경우
	{ 
		GSaveHistoryFormatNF(_LS(IDS_DB_ERR_MEMB_GEOMETRY)); //[오류] Member의 기하학적 형상이 올바르지 않습니다.     
		delete []nNodeIndex;
		return FALSE;
	}

	int nStartNode, nLastNode;  // 연속성을 파악할 첫번째 요소의 i 노드 및 마지막 요소의 j 노드
	for( i = 0; i < nElem; i++)
	{
		GetElem(rData.aElemList[i], DataElem);
		if(!mapInnerNode.Lookup(DataElem.elnod[0], nTemp)) nStartNode = DataElem.elnod[0];
		if(!mapInnerNode.Lookup(DataElem.elnod[1], nTemp)) nLastNode = DataElem.elnod[1];
	}

	for(i = 0; i < nElem; i++)  rData.aElemList[i] = 0;  // 멤버의 요소 리스트를 초기화한다.
	mapNodeiElem.Lookup(nStartNode, KeyElem);  // 멤버의 첫번째 요소를 찾는다.
	rData.aElemList[0] = KeyElem;    // 멤버의 첫번째 요소를 설정한다.  

	for( i = 0; i < nElem; i++)
	{
		GetElem(KeyElem, DataElem);
		if(i < nElem - 1) 
		{
			mapNodeiElem.Lookup(DataElem.elnod[1], KeyElem);
			rData.aElemList[i + 1] = KeyElem;
		}
		if(i == nElem - 1 && DataElem.elnod[1] == nLastNode) bSuccess = TRUE;
	}

	delete []nNodeIndex;
	return bSuccess;
}

BOOL CAttrCtrl::IsMatchDirectionAttribute(T_MEMB_D& rData, BOOL bTargetCH )
{  
	for(int i = 0; i < rData.aElemList.GetSize() - 1; i++)
	{
		//    if(!CompareElemDirection(rData.aElemList[i], rData.aElemList[i+1])) return FALSE;  // member의 직선여부는 체크하지 않음
		if(!CompareElemAttribute(rData.aElemList[i], rData.aElemList[i+1],bTargetCH)) return FALSE;
	}
	return TRUE;
}

BOOL CAttrCtrl::CompareElemDirection(T_ELEM_K KeyRef, T_ELEM_K KeyNew)
{
	T_ELEM_D DataElem;    
	double ux1, uy1, uz1, ux2, uy2, uz2;  // directional vector of element

	if(GetElem(KeyRef, DataElem)) GetFrmDirectionVector(DataElem, ux1, uy1, uz1);
	else return FALSE;
	if(GetElem(KeyNew, DataElem)) GetFrmDirectionVector(DataElem, ux2, uy2, uz2);	  
	else return FALSE;

	double Vec1[3], Vec2[3]; 
	Vec1[0] = ux1, Vec1[1] = uy1, Vec1[2] = uz1;
	Vec2[0] = ux2, Vec2[1] = uy2, Vec2[2] = uz2;
	double dAngle = CMathFunc::mathCrossAngle(Vec1, Vec2);

	if(fabs(dAngle) <= 1) return TRUE;
	else return FALSE;
}

BOOL CAttrCtrl::IsInterval45DegElemDirection(T_ELEM_K KeyRef, T_ELEM_K KeyNew)
{
	T_ELEM_D DataElem;    
	double ux1, uy1, uz1, ux2, uy2, uz2;  // directional vector of element

	if(GetElem(KeyRef, DataElem)) GetFrmDirectionVector(DataElem, ux1, uy1, uz1);
	else return FALSE;
	if(GetElem(KeyNew, DataElem)) GetFrmDirectionVector(DataElem, ux2, uy2, uz2);	  
	else return FALSE;

	double Vec1[3], Vec2[3]; 
	Vec1[0] = ux1, Vec1[1] = uy1, Vec1[2] = uz1;
	Vec2[0] = ux2, Vec2[1] = uy2, Vec2[2] = uz2;
	double dAngle = fabs(CMathFunc::mathCrossAngle(Vec1, Vec2));

	if (dAngle < 45.0 || dAngle > 135.0)
	{
		return FALSE;
	}

	return TRUE;
}

BOOL CAttrCtrl::IsInterval45DegVsecDirection(T_VSEC_D VsecD, T_ELEM_K KeyNew)
{
	T_ELEM_D DataElem;
	double ux1, uy1, uz1, ux2, uy2, uz2;  // directional vector of element

	ux1 = VsecD.dNormalVecX;
	uy1 = VsecD.dNormalVecY; 
	uz1 = VsecD.dNormalVecZ;

	if (GetElem(KeyNew, DataElem)) GetFrmDirectionVector(DataElem, ux2, uy2, uz2);
	else return FALSE;

	double Vec1[3], Vec2[3];
	Vec1[0] = ux1, Vec1[1] = uy1, Vec1[2] = uz1;
	Vec2[0] = ux2, Vec2[1] = uy2, Vec2[2] = uz2;
	double dAngle = fabs(CMathFunc::mathCrossAngle(Vec1, Vec2));

	if (dAngle < 45.0 || dAngle > 135.0)
	{
		return FALSE;
	}
	return TRUE;
}

BOOL CAttrCtrl::CompareElemAttribute(T_ELEM_K KeyRef, T_ELEM_K KeyNew, BOOL bTargetCH)
{
	T_ELEM_D DataElemRef, DataElemNew;

	int nType[2];
	UINT Key[2] = {KeyRef, KeyNew};
	T_MBTP_D rData;
	for(int i = 0; i < 2; i++)
	{
		if(ExistMbtp(Key[i]))
		{    
			rData.Initialize();
			GetMbtp(Key[i], rData);						// 사용자 정의방식
			nType[i] = rData.nMbType;
		}
		else nType[i] = GetMemberType(Key[i]);	// 일반적인 방식
	}

	if(GetElem(KeyRef, DataElemRef) && GetElem(KeyNew, DataElemNew))
	{ 
		if(DataElemRef.eltyp != DataElemNew.eltyp) {GSaveHistoryFormatNF(_LS(IDS_DB_ERR_MEMB_ELTYP)); return FALSE;} //[오류] 타입이 다른 요소를 하나의 Member로 지정할 수 없습니다.
		if(DataElemRef.elmat != DataElemNew.elmat) {GSaveHistoryFormatNF(_LS(IDS_DB_ERR_MEMB_ELMAt)); return FALSE;} //[오류] 재질이 다른 요소를 하나의 Member로 지정할 수 없습니다.
#ifdef _MGEN_CH
		if (CProduct::GetMovingType() != D_PRODUCT_MOVING_CH || !bTargetCH)
			if (DataElemRef.elpro != DataElemNew.elpro) { GSaveHistoryFormatNF(_LS(IDS_DB_ERR_MEMB_TAR_SECTTIP));} //[오류] 단면이 다른 요소를 하나의 Member로 지정할 수 없습니다.
#else
		if (CProduct::GetMovingType() != D_PRODUCT_MOVING_CH || !bTargetCH)
			if (DataElemRef.elpro != DataElemNew.elpro) { GSaveHistoryFormatNF(_LS(IDS_DB_ERR_MEMB_ELPRO)); return FALSE; } //[오류] 단면이 다른 요소를 하나의 Member로 지정할 수 없습니다.
#endif		
		if(fabs(DataElemRef.angle - DataElemNew.angle - (int)((DataElemRef.angle - DataElemNew.angle)/360.)*360.) > 1.0e-6 &&
			fabs(DataElemRef.angle - (int)(DataElemRef.angle/360.)*360. - DataElemNew.angle + (int)(DataElemNew.angle/360.)*360.) > 1.0e-6) 
		{GSaveHistoryFormatNF(_LS(IDS_DB_ERR_MEMB_ANGLE)); return FALSE;} //[오류] Beta Angle이 다른 요소를 하나의 Member로 지정할 수 없습니다.
		if(nType[0] != nType[1]) {GSaveHistoryFormatNF(_LS(IDS_DB_ERR_MEMB_TYPE)); return FALSE;} //[오류] Member Type이 다른 요소를 하나의 Member로 지정할 수 없습니다.
		if (DataElemRef.nSubType != DataElemNew.nSubType) { GSaveHistoryFormatNF(_LS(IDS_DB_ELEM_ERROR_MEMB_DIFF_SUB_TYPE)); return FALSE; }
	}
	else return FALSE;
	return TRUE;
}

void CAttrCtrl::GetFrmDirectionVector(T_ELEM_D& DataElem, double& Ux, double& Uy, double& Uz)
{
	T_NODE_D DataNode;
	DataNode.Initialize();

	double Coor_i[3], Coor_j[3], Vec[3], NormVec[3];
	if(GetNodeFromBaseDB(DataElem.elnod[0], DataNode))
	{Coor_i[0]=DataNode.x;	  Coor_i[1]=DataNode.y;	  Coor_i[2]=DataNode.z;}
	if(GetNodeFromBaseDB(DataElem.elnod[1], DataNode))
	{Coor_j[0]=DataNode.x;	  Coor_j[1]=DataNode.y;	  Coor_j[2]=DataNode.z;}

	for(int i= 0; i < 3; i++) Vec[i] = (Coor_j[i] - Coor_i[i]);
	CMathFunc::mathNormalize(Vec, NormVec);
	Ux = NormVec[0];
	Uy = NormVec[1];
	Uz = NormVec[2];
}

BOOL CAttrCtrl::IsNegativeMomentMember(T_ELEM_K ElemKey)
{
	T_MEMB_K MembK;
	T_MEMB_D MembD;
	if (GetMembAssigned(ElemKey, MembK))
	{
		if (!GetMemb(MembK, MembD)) { ASSERT(0); return FALSE; }
	}
	else
	{
		MembD.Initialize();
		MembD.aElemList.Add(ElemKey);
	}
	return IsNegativeMomentMember(MembD);
}

BOOL CAttrCtrl::IsNegativeMomentMember(T_MEMB_D& rMembD)
{
	T_NODE_K NodeK_I;
	T_NODE_K NodeK_J;
	T_ELEM_D ElemD;
	if (!GetElem(rMembD.aElemList[0], ElemD)) { ASSERT(0); return FALSE; }
	NodeK_I = ElemD.elnod[0];
	if (!GetElem(rMembD.aElemList[rMembD.aElemList.GetSize()-1], ElemD)) { ASSERT(0); return FALSE; }
	NodeK_J = ElemD.elnod[1];

	if (!IsColumnBraceWallAttachedUnder(NodeK_I)) return FALSE;
	if (!IsColumnBraceWallAttachedUnder(NodeK_J)) return FALSE;

	return TRUE;
}

BOOL CAttrCtrl::IsColumnBraceWallAttachedUnder(T_NODE_K NodeK)
{
	NodeList* pList;
	VERIFY(m_pDataMemb->m_node.GetList(NodeK, pList));
	if (pList->GetCount() == 0) return FALSE;
	T_LIST_DATA ListData;
	T_CONS_K ConsK;
	T_CONS_D ConsD;
	POSITION pos=pList->GetHeadPosition();
	while (pos != NULL)
	{
		// ===== // DB_NODE_DATA
		ListData = pList->GetNext(pos);
		if (ListData.nCmd == LT_CONS_CMD)
		{
			ConsK.keymap = ListData.nKey;
			if (!GetCons(ConsK, ConsD)) continue;
			if (ConsD.Constraint[2] == '1') return TRUE;
		}
	}

	CArray<T_ELEM_K, T_ELEM_K> aElemK;
	GetConnectedElem(NodeK, aElemK);
	int nElem = aElemK.GetSize();
	if (nElem < 1) return FALSE;

	T_NODE_D RefNodeD, TestNodeD;
	T_ELEM_D ElemD;
	if (!GetNode(NodeK, RefNodeD)) { ASSERT(0); return FALSE; }

	for (int i = 0; i < nElem; i++)
	{
		if (!GetElem(aElemK[i], ElemD)) { ASSERT(0); return FALSE; }
		if (IsWall(ElemD.eltyp))
		{
			if (ElemD.elnod[2] == NodeK || ElemD.elnod[3] == NodeK) return TRUE;
		}
		else if (IsFrameType(ElemD.eltyp))
		{
			int nMbtp = GetMemberType(aElemK[i]);
			if (nMbtp == 1 || nMbtp == 3)
			{
				if (ElemD.elnod[0] == NodeK) GetNode(ElemD.elnod[1], TestNodeD);
				else GetNode(ElemD.elnod[0], TestNodeD);
				if (TestNodeD.z < RefNodeD.z) return TRUE;
			}
		}
	}
	return FALSE;
}

// [06.01.04] by Hong,JS
// for DrawingShop Member Kind
int CAttrCtrl::GetBeamMemberKind( T_MEMB_D MembD )
{
	// Return value
	// 0: Not Beam Member
	// 1: G  (Girder)
	// 2: B  (Beam)
	// 3: CG (Cantilever Girder)
	// 4: CB (Cantilever Beam)

	// < 2. Check I Connected Member >

	int connectI = 10; // 10:None, 20: Column or Brace or Wall, 30 : Girder or Beam
	T_NODE_K NodeK;
	T_ELEM_K ElemK = 0;
	T_ELEM_D ElemD;  ElemD.Initialize();

	ElemK = MembD.aElemList.GetAt(0);
	if( !GetElem( ElemK, ElemD ) ) return 0;

	if( GetMemberType( ElemK ) != 2 ) return 0; // MemberType 2 is Beam.

	NodeK = ElemD.elnod[0];

	CArray<T_ELEM_K, T_ELEM_K> connElemList;
	GetConnectedElem( NodeK, connElemList );

	BOOL isWall = FALSE;
	int otherK;

	if( connElemList.GetSize() > 1 ) 
	{
		for( int i=0; i<connElemList.GetSize(); i++)
		{
			otherK = connElemList[i];
			if( otherK == ElemK )
				continue;

			GetElem( otherK, ElemD );

			isWall = IsWall( ElemD.eltyp );

			int type = GetMemberType( otherK );
			if( type == 1 || type == 3 || isWall )
			{
				connectI = 20;
				break;
			}
			else if( type == 2 )
				connectI = 30;
		}
	}
	else
	{
		connectI = 10; // Only 1 member
	}

	// < 3. Check J Connect Member >
	int connectJ = 1; // 1:None, 2: Column or Brace or Walll 3 : Girder or Beam

	ElemK = MembD.aElemList.GetAt( MembD.aElemList.GetSize() -1 );

	if( !GetElem( ElemK, ElemD ) ) return 0;

	NodeK = ElemD.elnod[1];
	GetConnectedElem( NodeK, connElemList );

	if( connElemList.GetSize() > 1 ) 
	{
		for( int i=0; i<connElemList.GetSize(); i++)
		{
			otherK = connElemList[i];
			if( otherK == ElemK )
				continue;

			GetElem( otherK, ElemD );

			isWall = IsWall( ElemD.eltyp );

			int type = GetMemberType( otherK );
			if( type == 1 || type == 3 || isWall )
			{
				connectJ= 2;
				break;
			}
			else if( type == 2 )
				connectJ = 3;
		}
	}
	else
	{
		connectJ = 1; // Only 1 member
	}

	// < 4. Decide Type of Current Member >
	int curMembType = 0;
	int connectIJ = connectI + connectJ;
	switch( connectIJ )
	{
	case 11: // none-none
		curMembType = 0;
		break;

	case 12: // none-column(brace)
	case 21: // column-none
		curMembType = 3; // CG
		break;

	case 13: // none-girder(beam)
	case 31: // beam-none
		curMembType = 4; // CB
		break;

	case 22: // column-column
		curMembType = 1; // G
		break;

	case 23: // column-beam
	case 32: // beam-column
		curMembType = 3; //CG
		break;

	case 33: // beam-beam
		curMembType = 2; //B
		break;
	}

	return curMembType;
}


