void CAttrCtrl::GetPsegKeyList(CArray<T_PSEG_K, T_PSEG_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_PSEG_K Key;
	T_PSEG_D Data;
	pos=GetStartPseg();
	while(pos != NULL)
	{
		GetNextPseg(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetKeyListPsegUser(CArray<T_PSEG_K, T_PSEG_K>* pKeyPseg,
								   CArray<T_NODE_K, T_NODE_K>* pKeyNode, CArray<T_ELEM_K, T_ELEM_K>* pKeyElem)
{
	if(pKeyNode != NULL)pKeyNode->RemoveAll();
	if(pKeyElem != NULL)pKeyElem->RemoveAll();
	if(pKeyNode == NULL && pKeyElem == NULL)return;
	int nCount=pKeyPseg->GetSize();
	if(nCount == 0)return;

	CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K>KeyElemMap;
	KeyElemMap.InitHashTable(m_pDoc->GetHashSizeElem());

	T_PSEG_D DataPseg;
	int nCountKeyPseg = pKeyPseg->GetSize();
	for(int i = 0; i < nCountKeyPseg; i++)
	{
		if(GetPseg(pKeyPseg->GetAt(i), DataPseg))
		{
			int nCountElem = DataPseg.aElemList.GetSize();
			for(int j = 0; j < nCountElem; j++)
				KeyElemMap.SetAt(DataPseg.aElemList[j], DataPseg.aElemList[j]);
		}
	}

	GetKeyListNodeElem(KeyElemMap, pKeyNode, pKeyElem);
}

