BOOL CAttrCtrl::CheckPsegCompatibility(T_PSEG_K Key, T_PSEG_D& rData)
{  
	BOOL bReturn=m_pDataMemb->m_pPseg->Get(Key, rData);
	if(bReturn)
	{
		if(rData.aElemList.GetSize() == 0) return FALSE;
		if(!AlignPsegElemList(Key, rData)) return FALSE;
		//if(!IsMatchDirectionAttribute(rData)) return FALSE;    
	}
	return bReturn;
}

BOOL CAttrCtrl::AlignPsegElemList(T_PSEG_K Key, T_PSEG_D& rData)
{
	T_PSEG_K KeyPseg;
	T_ELEM_D DataElem;
	T_PSEG_D DataPseg;
	CArray<T_ELEM_D, T_ELEM_D&> aElem;
	int i, j;

	int nElem = rData.aElemList.GetSize();

	// 요소가 존재 해야 함
	for(int i = 0; i < nElem; i++)
	{        
		if(!GetElem(rData.aElemList[i], DataElem)) 
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_UDEF_DT_ELEM), _LS(IDS_DB_DT_PSEG), rData.aElemList[i]);    
		if(!IsFrameType(DataElem.eltyp))
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_IREG_DT_ELEM), rData.aElemList[i], _LS(IDS_DB_DT_PSEG));

		aElem.Add(DataElem);
	}  

	// 한 Segment 를 구성하는 요소들의 특성은 같아야 함
	for(int i = 0; i < nElem-1; i++)
	{ 
		const T_ELEM_D& DataElemRef = aElem[i];
		const T_ELEM_D& DataElemNew = aElem[i+1];

		if(DataElemRef.eltyp != DataElemNew.eltyp) {GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_ELTYP)); return FALSE;} //[오류] 타입이 다른 요소를 하나의 Member로 지정할 수 없습니다.
		if(DataElemRef.elmat != DataElemNew.elmat) {GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_ELMAt)); return FALSE;} //[오류] 재질이 다른 요소를 하나의 Member로 지정할 수 없습니다.
		//if(DataElemRef.elpro != DataElemNew.elpro) {GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_ELPRO)); return FALSE;} //[오류] 단면이 다른 요소를 하나의 Member로 지정할 수 없습니다.

		// PSC 단면일경우만 허용. 
		T_SECT_K SectRefK = DataElemRef.elpro;
		T_SECT_K SectNewK = DataElemNew.elpro;
		T_SECT_D SectRefD, SectNewD;
		if(!GetSect(SectRefK,SectRefD)) return FALSE;
		if(!GetSect(SectNewK,SectNewD)) return FALSE;

        switch ( SectRefD.nStype )
        {
        case D_SECT_TYPE_TAPERED:
            if ( SectRefD.SectBefore.nStype != D_SECT_TYPE_PSC )
            {
                GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_ELPRO)); //[오류] 단면이 다른 요소를 하나의 Member로 지정할 수 없습니다.
                return FALSE;
            }
            break;
        case D_SECT_TYPE_PSC:
        case D_SECT_TYPE_COMPO_CI:
        case D_SECT_TYPE_COMPO_CT:
        case D_SECT_TYPE_COMPO_PC:
        case D_SECT_TYPE_COMPO_G:
        case D_SECT_TYPE_COMPO_TUB:
            break;
        default:
            GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_ELPRO)); //[오류] 단면이 다른 요소를 하나의 Member로 지정할 수 없습니다.
            return FALSE;
            break;
        }

        switch ( SectNewD.nStype )
        {
        case D_SECT_TYPE_TAPERED:
            if ( SectNewD.SectBefore.nStype != D_SECT_TYPE_PSC )
            {
                GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_ELPRO)); //[오류] 단면이 다른 요소를 하나의 Member로 지정할 수 없습니다.
                return FALSE;
            }
            break;
        case D_SECT_TYPE_PSC:
        case D_SECT_TYPE_COMPO_CI:
        case D_SECT_TYPE_COMPO_CT:
        case D_SECT_TYPE_COMPO_PC:
        case D_SECT_TYPE_COMPO_G:
        case D_SECT_TYPE_COMPO_TUB:
            break;
        default:
            GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_ELPRO)); //[오류] 단면이 다른 요소를 하나의 Member로 지정할 수 없습니다.
            return FALSE;
            break;
        }

		if(fabs(DataElemRef.angle - DataElemNew.angle - (int)((DataElemRef.angle - DataElemNew.angle)/360.)*360.) > 1.0e-6 &&
			fabs(DataElemRef.angle - (int)(DataElemRef.angle/360.)*360. - DataElemNew.angle + (int)(DataElemNew.angle/360.)*360.) > 1.0e-6) 
		{GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_ANGLE)); return FALSE;} //[오류] Beta Angle이 다른 요소를 하나의 Member로 지정할 수 없습니다.
	}

	// 연속성 파악
	CArray<UINT, UINT> aNode;
	for(int i = 0; i < nElem-1; i++)
	{
		const T_ELEM_D& Elem1 = aElem[i];
		const T_ELEM_D& Elem2 = aElem[i+1];

		int nCount = 0;
		for(int j=0 ; j<2 ; ++j)
		{
			for(int k=0 ; k<2 ; ++k)
			{
				if(Elem1.elnod[j]==Elem2.elnod[k])
				{
					nCount++;
					if(i==0) aNode.Add(Elem1.elnod[(j==0?1:0)]); // 첫점
					aNode.Add(Elem1.elnod[j]);
					if(i==nElem-2) aNode.Add(Elem2.elnod[(k==0?1:0)]); // 끝점
				}
			}
		}
		if(nCount != 1) // 각 요소간의 접점은 1 개 이어야 한다
		{
			GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_GEOMETRY)); //[오류] segment의 기하학적 형상이 올바르지 않습니다.     
			return FALSE;
		}
	}
	CMap<UINT, UINT, int, int> aMapForCheck; // 절점들이 중복되어서는 안된다
	int nTmp;
	for(i = 0 ; i<aNode.GetSize() ; ++i)
	{
		if(!aMapForCheck.Lookup(aNode[i], nTmp))
		{
			aMapForCheck.SetAt(aNode[i], 1);
		}
		else
		{
			GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_GEOMETRY)); //[오류] segment의 기하학적 형상이 올바르지 않습니다.     
			return FALSE;
		}
	}

	// 요소는 2개 이상의 segment 에 포함될 수 없음(한개의 segment 에만 포함)
	for(int i = 0; i < nElem; i++)
	{
		POSITION pos=m_pDataMemb->m_pPseg->GetStart();
		while(pos)
		{
			DataPseg.Initialize();
			m_pDataMemb->m_pPseg->GetNext(pos, KeyPseg, DataPseg);
			if(Key != KeyPseg)
			{
				for(j = 0; j < DataPseg.aElemList.GetSize(); j++)
				{
					if(rData.aElemList.GetAt(i) == DataPseg.aElemList.GetAt(j)) 
					{
						GSaveHistoryFormatNF(_LS(IDS_DB_ERR_PSEG_USED), rData.aElemList[i]);  //"Error! Element %d is already used as a constituent of segment"
						return FALSE;
					}
				}
			}
		}    
	}

	return TRUE;
}

