void CAttrCtrl::GetHcbmKeyList(CArray<T_HCBM_K, T_HCBM_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_HCBM_K Key;
	T_HCBM_D Data;
	pos=GetStartHcbm();
	while(pos != NULL)
	{
		GetNextHcbm(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetKeyListHcbmUser(CArray<T_HCBM_K, T_HCBM_K>* pKeyHcbm,
								   CArray<T_NODE_K, T_NODE_K>* pKeyNode, CArray<T_ELEM_K, T_ELEM_K>* pKeyElem)
{
	if(pKeyNode != NULL)pKeyNode->RemoveAll();
	if(pKeyElem != NULL)pKeyElem->RemoveAll();
	if(pKeyNode == NULL && pKeyElem == NULL)return;
	int nCount=pKeyHcbm->GetSize();
	if(nCount == 0)return;

	CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K>KeyElemMap;
	KeyElemMap.InitHashTable(m_pDoc->GetHashSizeElem());

	T_HCBM_D DataHcbm;
	int nCountKeyHcbm = pKeyHcbm->GetSize();
	for(int i = 0; i < nCountKeyHcbm; i++)
	{
		if(GetHcbm(pKeyHcbm->GetAt(i), DataHcbm))
		{
			for(int j = 0; j < 3; j++)
			{
				int nCountElem = DataHcbm.aElemListPart[j].GetSize();
				for(int k = 0; k < nCountElem; k++)
					KeyElemMap.SetAt(DataHcbm.aElemListPart[j].GetAt(k), DataHcbm.aElemListPart[j].GetAt(k));
			}
		}
	}

	GetKeyListNodeElem(KeyElemMap, pKeyNode, pKeyElem);
}

BOOL CAttrCtrl::ExistHcbm(T_HCBM_K Key)
{
	T_HCBM_D Data;
	return m_pDataMemb->m_pHcbm->Get(Key,Data);
}

BOOL CAttrCtrl::GetHcbm(T_HCBM_K Key,T_HCBM_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_pHcbm->Get(Key,rData);
	if(bReturn) m_pUnitCtrl->ConvertUnitHcbmOut(rData);
	return bReturn;
}

int CAttrCtrl::GetCountHcbm()
{
	return m_pDataMemb->m_pHcbm->GetCount();
}

POSITION CAttrCtrl::GetStartHcbm()
{
	return m_pDataMemb->m_pHcbm->GetStart();
}

void CAttrCtrl::GetNextHcbm(POSITION& rNextPosition,T_HCBM_K& rKey,T_HCBM_D& rData)
{
	m_pDataMemb->m_pHcbm->GetNext(rNextPosition,rKey,rData);
	m_pUnitCtrl->ConvertUnitHcbmOut(rData);
}

T_HCBM_K CAttrCtrl::GetStartNumHcbm()
{
	return m_pDataMemb->m_pHcbm->m_nStartNum;
}

T_HCBM_K CAttrCtrl::GetLastNumHcbm()
{
	return m_pDataMemb->m_pHcbm->m_nLastNum;
}

BOOL CAttrCtrl::ExistHcbmAssigned(T_ELEM_K KeyElem)
{
	T_HCBM_K rKeyHcbm;
	return m_pDataMemb->m_pHcbm->GetHcbmAssigned(KeyElem, rKeyHcbm);
}

BOOL CAttrCtrl::GetHcbmAssigned(T_ELEM_K KeyElem,T_HCBM_K& rKeyHcbm)
{
	BOOL bReturn=m_pDataMemb->m_pHcbm->GetHcbmAssigned(KeyElem, rKeyHcbm);  
	return bReturn;
}

BOOL CAttrCtrl::CheckHcbmCompatibility(T_HCBM_K Key, T_HCBM_D& rData)
{  
	BOOL bReturn=GetHcbm(Key, rData);		// 현재 단위계로 가지고 와야 한다.....계산시 필요....
	if(bReturn)
	{
		for(int i=0; i<3; i++)
			if(rData.aElemListPart[i].GetSize() == 0) return FALSE;
		if(!AlignHcbmElemList(Key, rData)) return FALSE;
		if(!IsMatchDirectionAttribute4Hcbm(rData)) return FALSE;    
	}
	return bReturn;
}

BOOL CAttrCtrl::AlignHcbmElemList(T_HCBM_K Key, T_HCBM_D& rData)
{
	T_ELEM_K KeyElem;
	T_ELEM_D DataElem;
	T_HCBM_K KeyHcbm;  
	T_HCBM_D DataHcbm;
	CMap<T_NODE_K, T_NODE_K, T_ELEM_K, T_ELEM_K> mapNodeiElem;
	CMap<T_NODE_K, T_NODE_K, T_ELEM_K, T_ELEM_K> mapNodejElem;
	CMap<T_NODE_K, T_NODE_K, int, int> mapInnerNode;         
	mapNodeiElem.InitHashTable(51);
	mapNodejElem.InitHashTable(51);
	mapInnerNode.InitHashTable(51);
	mapNodeiElem.RemoveAll();
	mapNodejElem.RemoveAll();
	mapInnerNode.RemoveAll();  
	int i, j, k, nTemp;

	// Beam Type 인지 먼저 검사한다...
	for(int i = 0; i<3; i++) for(j = 0; j < rData.aElemListPart[i].GetSize(); j++)
	{        
		if(!GetElem(rData.aElemListPart[i].GetAt(j), DataElem)) 
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_UDEF_DT_ELEM), _LS(IDS_DB_DT_HCBM), rData.aElemListPart[i].GetAt(j));    
		if(!IsBeam(DataElem.eltyp))
			return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_IREG_DT_ELEM), rData.aElemListPart[i].GetAt(j), _LS(IDS_DB_DT_HCBM));
	}  

	// 요소는 2개 이상의 Hcbm에 포함될 수 없음(한개의 Hcbm에만 포함)
	for(int i = 0; i<3; i++)
	{
		for(j = 0; j < rData.aElemListPart[i].GetSize(); j++)
		{
			POSITION pos=m_pDataMemb->m_pHcbm->GetStart();
			while(pos)
			{
				DataHcbm.Initialize();
				m_pDataMemb->m_pHcbm->GetNext(pos, KeyHcbm, DataHcbm);
				if(Key != KeyHcbm)
				{
					for(int z=0; z<3; z++)
						for(k = 0; k < DataHcbm.aElemListPart[z].GetSize(); k++)
						{
							if(rData.aElemListPart[i].GetAt(j) == DataHcbm.aElemListPart[z].GetAt(k)) 
							{
								GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_USED), DataHcbm.aElemListPart[z].GetAt(k));  //"[오류] 요소 %d은(는) Haunched Beam의 구성요소로 사용중입니다."
								return FALSE;
							}
						}
				}
			}   
		}
	}

	int nTotalElemList = rData.aElemListPart[0].GetSize() + rData.aElemListPart[1].GetSize() + rData.aElemListPart[2].GetSize();
	int nMaxNum = 2 * nTotalElemList;
	if(nMaxNum<=0) {ASSERT(0); return FALSE;}
	int *nNodeIndex = new int[nMaxNum];   
	for(int i = 0; i < nMaxNum; i++) nNodeIndex[i] = 0;

	k = 0;
	for(int i = 0; i < 3 ; i++)
	{
		for(j = 0; j < rData.aElemListPart[i].GetSize(); j++)
		{    
			GetElem(rData.aElemListPart[i].GetAt(j), DataElem);
			{
				nNodeIndex[2 * k] = DataElem.elnod[0];
				nNodeIndex[2 * k++ + 1] = DataElem.elnod[1];
				mapNodeiElem.SetAt(DataElem.elnod[0], rData.aElemListPart[i].GetAt(j));
				mapNodejElem.SetAt(DataElem.elnod[1], rData.aElemListPart[i].GetAt(j));
			}    
		}
	}

	// Part A, C가 tapered section인지 확인....
	for(i=0 ; i<3; i+=2)
	{
		for(j=0 ; j<rData.aElemListPart[i].GetSize(); j++)
		{
			T_ELEM_D ElemData;
			T_SECT_D DataSect;
			if(!GetElem(rData.aElemListPart[i].GetAt(j), ElemData))
			{
				delete []nNodeIndex;
				return FALSE;
			}
			if(!GetSect(ElemData.elpro, DataSect))
			{
				GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_SECT_NOT_ASSIGNED));  // "[오류] Section이 지정되어 있지 않습니다."
				delete []nNodeIndex;
				return FALSE;
			}
			if(DataSect.nStype != D_SECT_TYPE_TAPERED)			
			{
				GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_NOT_TAPERED_GRUP));  // "[오류] 분할된 요소가 Tapered Section으로 지정 되어야 합니다."
				delete []nNodeIndex;
				return FALSE; 
			}
			// Tapered Section Group 이 지정되어 있는지 확인.....
			if(GetElemTsgrKey(rData.aElemListPart[i].GetAt(j)) != 0)
			{
				GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_ASSIGNED_TAPERED_GRUP));  // "[오류] 분할된 요소가 Tapered Section group으로 지정 되어있습니다."
				delete []nNodeIndex;
				return FALSE; 
			}
		}
	}


	//int nTotalElemList = rData.aElemListPart[0].GetSize() + rData.aElemListPart[1].GetSize() + rData.aElemListPart[2].GetSize();
	//int nNumNode = 2 * nTotalElemList;
	for(int i = 0; i < nMaxNum - 1; i++)    // 현재 Haunched Beam의 내부 절점을 구한다.
	{
		for(j = i + 1; j < nMaxNum; j++)
		{
			if(nNodeIndex[i] == nNodeIndex[j]) {mapInnerNode.SetAt(nNodeIndex[i], 0); break;}
		}
	}  

	if(mapNodeiElem.GetCount() != mapNodejElem.GetCount())  // 하나의 절점에 3개 이상의 요소가 연결된 경우     
	{ 
		GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_GEOMETRY)); //[오류] Haunched Beam의 기하학적 형상이 올바르지 않습니다.     
		delete []nNodeIndex;
		return FALSE;
	}
	if(mapNodeiElem.GetCount() != nTotalElemList ||						// 일부 요소의 방향이 다른 경우
		mapNodejElem.GetCount() != nTotalElemList)							// 일부 요소의 방향이 다른 경우
	{ 
		GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_DIRECTION)); //[오류] Haunched Beam을 이루고 있는 일부 요소들의 방향이 다릅니다.     
		delete []nNodeIndex;
		return FALSE;
	}
	if(mapInnerNode.GetCount() != nTotalElemList - 1)					// 헌치를 이루는 요소가 연결되어 있지 않거나 폐쇄형 일 경우
	{ 
		GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_NOT_LINKED)); //[오류] Haunched Beam을 이루고 있는 요소들이 연결되어 있지 않거나 패쇄형입니다.     
		delete []nNodeIndex;
		return FALSE;
	}

	BOOL bReverse = FALSE;
	int nStartNode, nLastNode;  // 연속성을 파악할 첫번째 요소의 i 노드 및 마지막 요소의 j 노드
	for(int i = 0; i < 3 ; i++)
	{
		for(j = 0; j < rData.aElemListPart[i].GetSize(); j++)
		{
			GetElem(rData.aElemListPart[i].GetAt(j), DataElem);
			if(!mapInnerNode.Lookup(DataElem.elnod[0], nTemp)) nStartNode = DataElem.elnod[0];
			if(!mapInnerNode.Lookup(DataElem.elnod[1], nTemp))
			{
				nLastNode = DataElem.elnod[1];
				if(i==0) bReverse = TRUE;
			}
		}
	}

	if(bReverse)
	{
		int nSize_A = rData.aElemListPart[0].GetSize();
		int nSize_C = rData.aElemListPart[2].GetSize();

		rData.aElemListPart[0].SetSize(nSize_C);
		rData.aElemListPart[2].SetSize(nSize_A);

		double dTempL = rData.dL1;
		rData.dL1 = rData.dL2;
		rData.dL2 = dTempL;
	}

	for(int i = 0; i < 3 ; i++)
		for(j = 0; j < rData.aElemListPart[i].GetSize(); j++)
			rData.aElemListPart[i].SetAt(j, 0);				// 헌치의 요소 리스트를 초기화한다.

	// Haunched Beam을 순서대로 정렬한다...
	mapNodeiElem.Lookup(nStartNode, KeyElem);		// 헌치의 첫번째 요소를 찾는다.

	// 나머지 헌치빔 부분의 요소들을 차례로 설정한다...
	for(int i = 0; i < 3 ; i++)
	{
		for(j = 0; j < rData.aElemListPart[i].GetSize(); j++)
		{
			if(i==0 && j==0)
				rData.aElemListPart[i].SetAt(j, KeyElem);		// 헌치의 첫번째 요소를 설정한다.    
			else
			{
				GetElem(KeyElem, DataElem);
				mapNodeiElem.Lookup(DataElem.elnod[1], KeyElem);
				rData.aElemListPart[i].SetAt(j, KeyElem);
			}
		}
	}

	delete []nNodeIndex;

	GetElem(KeyElem, DataElem);
	if(DataElem.elnod[1] != nLastNode) return FALSE;

	return TRUE;
}

BOOL CAttrCtrl::IsMatchDirectionAttribute4Hcbm(T_HCBM_D& rData)
{  
	BOOL bIsHaunchPart = FALSE;
	double dLPartA, dLPartC, dL;
	int i, j ;
	dLPartA=dLPartC=dL=0 ;

	for( i = 0;  i < 3; i++)
		for(j = 0;  j < rData.aElemListPart[i].GetSize() - 1; j++)
		{
			if(i==0 || i==3) bIsHaunchPart = TRUE;
			if(!CompareElemAttribute4Hcbm(rData.aElemListPart[i].GetAt(j), rData.aElemListPart[i].GetAt(j+1), bIsHaunchPart)) return FALSE;
		}

		///////////////////////////////////////////////////////////////////////////////////
		// 길이에 대해서는 Error check 해야 한다....
		// L> l1 > 0, L> l2 > 0, L > l1 + l2 > 0,
		// Default 길이는 1/2 이다... 이것도 check  해야 함....	
		for( i = 0;  i < 3; i++)
			for(j = 0;  j < rData.aElemListPart[i].GetSize(); j++)
			{
				// 헌치부분의 길이 구함...
				dL += m_pDoc->calcLAVElem(rData.aElemListPart[i].GetAt(j));
				if(i==0)	dLPartA += m_pDoc->calcLAVElem(rData.aElemListPart[i].GetAt(j));
				if(i==2)	dLPartC += m_pDoc->calcLAVElem(rData.aElemListPart[i].GetAt(j));
				/*
				// 설계 쪽에서 검토한다....
				if(i!=1)
				{
				//if(!CheckSectShape4Hcbm(rData.aElemListPart[i].GetAt(j))) return FALSE;
				}
				*/
			}

			// Modify by GAY. MQC:1373. ('07.09.21). Consider Tolerance for Checking Length.
			const double dZero = CDBDoc::GetDocPoint()->m_pInitCtrl->GetPreferenceRegardZero();

			if(rData.nDesignPosition == 1) // User Defined...
			{
				if(dLPartA <= rData.dL1 || rData.dL1 <= 0 ||
					dLPartC <= rData.dL2 || rData.dL2 <= 0)
					return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_DT_HCBM_LENGTH));
			}
			else if(rData.nDesignPosition == 0) // AUTO...
			{
				if(fabs(dLPartA - 2.0*rData.dL1) > dZero || fabs(dLPartC - 2.0*rData.dL2) > dZero )
					return m_pDoc->DisplayHistoryMessage(_LS(IDS_DB_DT_HCBM_LENGTH));
			}
			///////////////////////////////////////////////////////////////////////////////////

			// Haunched Beam의 연결부의 단면 검토...
			// Part A와 B, Part B와 C 연결부의 단면은 반드시 같아야 한다...
			// 만약 Part A, C에 Tapered Section이외의 것들을 허용한다면 여기도 수정, 삭제 되어야 한다...
			T_ELEM_D DataElemRef, DataElemNew;
			int nLast;
			for( i = 0; i<2; i++)
			{
				nLast = rData.aElemListPart[i].GetSize() - 1;	
				if(GetElem(rData.aElemListPart[i].GetAt(nLast), DataElemRef) && GetElem(rData.aElemListPart[i+1].GetAt(0), DataElemNew))
				{
					T_SECT_D	DataSectRef;
					T_SECT_D	DataSectNew;

					if(!GetSect(DataElemRef.elpro, DataSectRef) || !GetSect(DataElemNew.elpro, DataSectNew))
					{
						GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_SECT_NOT_ASSIGNED));  // "[오류] Section이 지정되어 있지 않습니다."
						return FALSE;
					}
					if (DataSectRef.SectBefore.Shape !=	DataSectNew.SectBefore.Shape)
					{			
						GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_NOT_SAME_ELPRO)); // [오류] 연결부의 단면이 일치하지 않습니다.
						return FALSE; 
					} 
				}
				else { ASSERT(0); return FALSE; }
			}

			return TRUE;
}

