BOOL CAttrCtrl::CompareElemAttribute4Hcbm(T_ELEM_K KeyRef, T_ELEM_K KeyNew, BOOL bIsHaunchPart)
{
	T_ELEM_D DataElemRef, DataElemNew;

	// Haunched Beam의 타입, 재질, Beta Angle, 단면등을 검토....
	if(GetElem(KeyRef, DataElemRef) && GetElem(KeyNew, DataElemNew))
	{ 
		if(DataElemRef.eltyp != DataElemNew.eltyp) {GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_ELTYP)); return FALSE;} //[오류] 타입이 다른 요소를 하나의 Haunched Beam으로 지정할 수 없습니다.
		if(DataElemRef.elmat != DataElemNew.elmat) {GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_ELMAt)); return FALSE;} //[오류] 재질이 다른 요소를 하나의 Haunched Beam으로 지정할 수 없습니다.
		// 헌치 부분이면 검사할 필요 없다........
		if(!bIsHaunchPart && DataElemRef.elpro != DataElemNew.elpro) {GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_ELPRO)); return FALSE;} //[오류] 단면이 다른 요소를 하나의 Haunched Beam으로 지정할 수 없습니다.
		if(fabs(DataElemRef.angle - DataElemNew.angle - (int)((DataElemRef.angle - DataElemNew.angle)/360.)*360.) > 1.0e-6 &&
			fabs(DataElemRef.angle - (int)(DataElemRef.angle/360.)*360. - DataElemNew.angle + (int)(DataElemNew.angle/360.)*360.) > 1.0e-6) 
		{GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_ANGLE)); return FALSE;} //[오류] Beta Angle이 다른 요소를 하나의 Haunched Beam으로 지정할 수 없습니다.

		// Part A와 Part B 부분의 단면검토, 형상이 다른 단변이 존재하면 안된다.
		if(bIsHaunchPart)
		{
			T_SECT_D	DataSectRef;
			T_SECT_D	DataSectNew;
			if(!GetSect(DataElemRef.elpro, DataSectRef) || !GetSect(DataElemNew.elpro, DataSectNew))
			{
				GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_SECT_NOT_ASSIGNED));  // "[오류] Section이 지정되어 있지 않습니다."
				return FALSE;
			}
			if (DataSectRef.SectBefore.Shape !=	DataSectNew.SectBefore.Shape)
			{			
				GSaveHistoryFormatNF(_LS(IDS_DB_ERR_HCBM_NOT_SAME_SHAPE)); // [오류] 분할된 요소의 단면형상이 일치하지 않습니다.
				return FALSE; 
			} 
		}
		/////////////////////////
	}
	else return FALSE;
	return TRUE;
}


