BOOL CAttrCtrl::ExistHdct()
{
	T_HDCT_D Data;
	return m_pDataMemb->m_pHdct->Get(Data);
}

BOOL CAttrCtrl::GetHdct(T_HDCT_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_pHdct->Get(rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitHdctOut(rData);
	return bReturn;
}

