void CNewlyActivatedElemInStag::Initialize(CAttrCtrl* pAttrCtrl)
{
	if (m_bInit)
	{
		m_aStagK.RemoveAll();
		m_mStagK2Id.RemoveAll();
		m_mStagId2Elem.RemoveAll();
		m_mElemK2Id.RemoveAll();
	}
	else
	{
		m_mStagK2Id.InitHashTable(HASHSIZESTAG);
		m_mStagId2Elem.InitHashTable(HASHSIZESTAG);
		m_mElemK2Id.InitHashTable(HASHSIZEELEM);
		m_bInit = TRUE;
	}
	VERIFY(pAttrCtrl);
	m_pAttrCtrl = pAttrCtrl;
	m_nLastStageId = 0;
	pAttrCtrl->GetStagKeyList(m_aStagK);
	for (int i = 0; i < m_aStagK.GetSize(); i++)
		m_mStagK2Id.SetAt(m_aStagK[i], i+1);
}

BOOL CNewlyActivatedElemInStag::GetNewlyActivatedElemList(int nElemType, T_STAG_K StagK, CArray<T_ELEM_K, T_ELEM_K>& raElem)
{
	raElem.RemoveAll();
	if (!m_bInit) return FALSE; // remember to call Initialize first.

	int nStageId;
	if (!m_mStagK2Id.Lookup(StagK, nStageId)) { ASSERT(0); return FALSE; }

	if (nStageId > m_nLastStageId) MakeNewlyActivatedElemList(nStageId);
	T_NEWLY_ACTIVATED_ELEM ActElem;
	VERIFY(m_mStagId2Elem.Lookup(nStageId, ActElem));

	if (nElemType == 0) raElem.Copy(ActElem.aElem);
	else
	{
		for (int i = 0; i < ActElem.aElem.GetSize(); i++)
			if (ActElem.aElemType[i] == nElemType) raElem.Add(ActElem.aElem[i]);
	}
	return TRUE;
}

BOOL CNewlyActivatedElemInStag::MakeNewlyActivatedElemList(int nStageId)
{
	T_STAG_D StagD;
	T_GRUP_D GrupD;
	int nTempStageId;
	CMap<T_ELEM_K, T_ELEM_K, int, int> mNewlyActivatedElem; // 현재 Stage에서 Active된 요소 빨리 찾기 위해
	mNewlyActivatedElem.InitHashTable(1001);
	for (int sid = m_nLastStageId+1; sid <= nStageId; sid++)
	{
		T_NEWLY_ACTIVATED_ELEM ActElem;
		ActElem.nStageId = sid;
		mNewlyActivatedElem.RemoveAll();

		m_pAttrCtrl->GetStag(m_aStagK[sid-1], StagD);
		// Active Group에 포함된 요소 Active 시킴
		int i = 0;
		for (i = 0; i < StagD.aActiveElem.GetSize(); i++)
		{
			m_pAttrCtrl->GetGrup(StagD.aActiveElem[i].GrupKey, GrupD);
			for (int j = 0; j < GrupD.arKeyElem.GetSize(); j++)
			{
				if (!m_mElemK2Id.Lookup(GrupD.arKeyElem[j], nTempStageId))
				{
					m_mElemK2Id.SetAt(GrupD.arKeyElem[j], sid);
					mNewlyActivatedElem.SetAt(GrupD.arKeyElem[j], 0);
				}
			}
		}
		// Deactive Group에 포함된 요소 Deactive 시킴
		for(i = 0; i < StagD.aDeactiveElem.GetSize(); i++)
		{
			m_pAttrCtrl->GetGrup(StagD.aDeactiveElem[i].GrupKey, GrupD);
			for (int j = 0; j < GrupD.arKeyElem.GetSize(); j++)
			{
				if (m_mElemK2Id.Lookup(GrupD.arKeyElem[j], nTempStageId))
					m_mElemK2Id.RemoveKey(GrupD.arKeyElem[j]);
				if (mNewlyActivatedElem.Lookup(GrupD.arKeyElem[j], nTempStageId))
					mNewlyActivatedElem.RemoveKey(GrupD.arKeyElem[j]);
			}
		}
		i = 0;
		int nCount = mNewlyActivatedElem.GetCount();
		if (nCount > 0) 
		{
			ActElem.aElem.SetSize(nCount);
			ActElem.aElemType.SetSize(nCount);
			T_ELEM_K ElemK;
			T_ELEM_D ElemD;

			POSITION pos = mNewlyActivatedElem.GetStartPosition();
			while (pos)
			{
				mNewlyActivatedElem.GetNextAssoc(pos, ElemK, nTempStageId);
				ActElem.aElem[i++] = ElemK;
			}
			CQSort::QSortUInt(ActElem.aElem.GetData(), nCount);
			for(i = 0; i < nCount; i++)
			{
				m_pAttrCtrl->GetElem(ActElem.aElem[i], ElemD);
				ActElem.aElemType[i] = ElemD.eltyp;
			}
		}
		m_mStagId2Elem.SetAt(sid, ActElem);
		m_nLastStageId = sid;
	}
	if (m_nLastStageId == m_aStagK.GetSize())
	{
		// 각 단계마다 새로 Active된 요소 다 구했으므로 필요 없으니 
		// 지운다.
		// 향후에 이 데이타가 필요하면 이 블록을 제거하면 된다.
		m_mElemK2Id.RemoveAll();
	}
	return TRUE;
}

