void CAttrCtrl::GetPhgtList(CArray<CString, CString&>& rstrPhgtList)
{
	rstrPhgtList.RemoveAll();

	int nCount=GetCountPhgt();
	if(nCount == 0)return;

	POSITION pos;
	T_PHGT_K Key;
	T_PHGT_D Data;

	for(int i=1; i<=nCount; i++)
	{
		pos=GetStartPhgt();
		while(pos != NULL)
		{
			GetNextPhgt(pos, Key, Data);
			if(Data.nSeq == i)
			{
				rstrPhgtList.Add(Data.strName);
				break;
			}
		}
	}
}

void CAttrCtrl::GetPhgtKeyList(CArray<T_PHGT_K, T_PHGT_K>& rPhgtKeyList)
{
	rPhgtKeyList.RemoveAll();

	POSITION pos;
	T_PHGT_K Key;
	T_PHGT_D Data;
	pos=GetStartPhgt();
	while(pos != NULL)
	{
		GetNextPhgt(pos, Key, Data);
		rPhgtKeyList.Add(Key);
	}
	if(rPhgtKeyList.GetSize() > 0)CQSort::QSortUInt(rPhgtKeyList.GetData(), rPhgtKeyList.GetSize());
}

