BOOL CAttrCtrl::GetPhgt(CString& rstrTypeName, T_PHGT_D& rData)
{
	T_PHGT_K key;
	T_PHGT_D data;
	CString strTypeName=rstrTypeName;
	strTypeName.TrimRight();

	POSITION pos=m_pDataMemb->m_phgt.GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_phgt.GetNext(pos,key,data);
		if(strTypeName.CompareNoCase(data.strName) == 0)
		{
			m_pUnitCtrl->ConvertUnitPhgtOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

