int CAttrCtrl::GetPhgtListByElemType(const int nElemType, CArray<T_PHGT_K, T_PHGT_K> &raKey, CStringArray &raName)
{
	// nElemType = 0 : All
	// nElemType = 1 : D_PHGE_BEAMCOLUMN
	// nElemType = 2 : D_PHGE_WALL      
	// nElemType = 3 : D_PHGE_TRUSS     
	// nElemType = 4 : D_PHGE_GLINK 
	// nElemType = 5 : D_PHGE_PSPR 

	raKey.RemoveAll();
	raName.RemoveAll();
	int nCount=GetCountPhgt();
	if(nCount==0) return 0;

	CArray<T_PHGT_K, T_PHGT_K> aPhgtKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPosIdPair;
	CStringArray aPhgtName;

	T_POS_INT_PAIR pair;

	T_PHGT_K Key;
	T_PHGT_D Data;
	POSITION pos = GetStartPhgt();
	while (pos != NULL)
	{
		GetNextPhgt(pos, Key, Data);
		if(nElemType==0 ||
			(Data.nElemType == 0 && nElemType == D_PHGE_BEAMCOLUMN) ||
			(Data.nElemType == 1 && nElemType == D_PHGE_WALL)  ||
			(Data.nElemType == 2 && nElemType == D_PHGE_TRUSS) ||
			(Data.nElemType == 3 && nElemType == D_PHGE_GLINK) ||
			(Data.nElemType == 4 && nElemType == D_PHGE_PSPR))
		{
			pair.nPos = aPhgtKey.Add(Key);
			pair.nVal = Data.nSeq;
			aPhgtName.Add(Data.strName);
			aPosIdPair.Add(pair);
		}
	}
	aPhgtKey.FreeExtra();
	aPhgtName.FreeExtra();
	nCount = aPhgtKey.GetSize();

	raKey.SetSize(nCount);
	raName.SetSize(nCount);

	// sort and copy
	int ix = 0;
	qsort((void*)aPosIdPair.GetData(), nCount, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);
	for(int i = 0; i < nCount; i++)
	{
		pair = aPosIdPair[i];
		raKey[i]  = aPhgtKey[pair.nPos];
		raName[i] = aPhgtName[pair.nPos];
	}

	return nCount;
}

BOOL CAttrCtrl::UpdateInitStiffMethod(T_PHGT_D &PhgtD)
{ // PhgtD의 nInitStiffMethod가 부적절한 경우 적절한 값으로 바꿔주는 함수
	BOOL bMThetaType = FALSE;
	BOOL bMPhiType   = FALSE;
	if(PhgtD.nElemType==0 || PhgtD.nElemType== 1)
	{
		if(PhgtD.nMaterial!=2)
		{
			if(PhgtD.nDefinition==D_PHGT_DEFINITION_MTHETA_LUMP) //(My, Mz일 경우만 Elastic이면 안된다.)      
				bMThetaType = TRUE;      
			else    //xEI/L 이면 안된다.
				bMPhiType = TRUE;
		}
		else
			bMThetaType = TRUE;
	}
	else if(PhgtD.nElemType== 3) // General Link는 M-Phi처럼 설정
	{
		bMPhiType = TRUE;
	}
	for(int k=0; k<6; ++k)
	{
		if(!PhgtD.bDOF[k]) continue;
		BOOL bChange1=FALSE, bChange2=FALSE;
		int nInitStiffMethod    = PhgtD.Skcv[k].nInitStiffMethod;
		int nInitStiffMethodSub = PhgtD.SkcvSub[k].nInitStiffMethod;
		if(bMThetaType && k>3)
		{      
			if(m_pDoc->IsPOSkcvMultiLinear(PhgtD.nSkcvType[k] < D_SKCV_FEMA))
			{          
				if(PhgtD.Skcv   [k].Multi.nInputType==0) bChange1 = TRUE;//Ratio 입력
				if(PhgtD.SkcvSub[k].Multi.nInputType==0) bChange2 = TRUE;          
			}
			else
			{
				bChange1 = bChange2 = TRUE;
			}
			if(bChange1 && nInitStiffMethod   ==4)     PhgtD.Skcv[k].nInitStiffMethod = 0;
			if(bChange2 && nInitStiffMethodSub==4)  PhgtD.SkcvSub[k].nInitStiffMethod = 0;
		}
		if(bMPhiType && k>3)
		{
			if(m_pDoc->IsPOSkcvMultiLinear(PhgtD.nSkcvType[k] < D_SKCV_FEMA))
			{          
				if(PhgtD.Skcv   [k].Multi.nInputType==0) bChange1 = TRUE;//Ratio 입력
				if(PhgtD.SkcvSub[k].Multi.nInputType==0) bChange2 = TRUE;          
			}
			else
			{
				bChange1 = bChange2 = TRUE;
			}
			if(bChange1 && (nInitStiffMethod==0 || nInitStiffMethod==1 || nInitStiffMethod==2))
				PhgtD.Skcv[k].nInitStiffMethod = 4;
			if(bChange2 && (nInitStiffMethodSub==0 || nInitStiffMethodSub==1 || nInitStiffMethodSub==2))
				PhgtD.SkcvSub[k].nInitStiffMethod = 4;
		}    
	}
	return TRUE;
}

BOOL CAttrCtrl::GetPhgeAutoCalcPosition(T_PHGT_D &PhgtData, int nAutoCalcPosition[6])
{
	// nAutoCalcPosition[] : D_PHGT_LOCATION
	// Pmcv.Cal_PmcvPhge 에서 항복강도와 항복변형을 계산해야 하는 경우 그 위치에 대한 정보를 넘김
	// nAutoCalcPosition[] ==0 : 자동계산 대상이 아니다.
	//                     ==1 : I-end
	//                     ==2 : J-end, 
	//                     ==3 : Middle(Center), 
	//                     ==4 : I-end & J-end (각각 계산 필요)
	// PhgtD - Lumped(Distributed가 아닌 경우)  nLoc으로 위치 판단     
	// PhgtD - Distributed                      PogdD 로 위치 판단

	T_PHGT_D& PhgtD = PhgtData;
	//if(!GetPhgt(PhgeD.HingeTypeK, PhgtD)) return FALSE;

	if(PhgtD.nMaterial==2) return FALSE;  // Masonry 는 여기 올 애가 아니다.

	// #0. 초기화
	for(int nDof=D_DOF_FX; nDof<=D_DOF_MZ ; ++nDof) nAutoCalcPosition[nDof] = D_PHGT_LOCATION_NONE;

	// #1. Truss 일 경우 
	if(PhgtD.nElemType==2)
	{
		if(PhgtD.bDOF[0])  
		{
			if(PhgtData.Skcv[0].nCalcMethod== D_PHGT_CALC_AUTO)
				nAutoCalcPosition[0] = D_PHGT_LOCATION_CENTER;      
		}
		return TRUE;
	}

	// #2. Beam/Column, Wall 일 경우
	if(PhgtD.nElemType!=0 && PhgtD.nElemType!=1) return FALSE;

	T_POGD_D PogdD;  
	int nLocOfBeamColum =0, nLocOfWall =0;  
	BOOL bDistributed = FALSE;
	if(PhgtD.nDefinition==D_PHGT_DEFINITION_MPHI_DIST)  bDistributed = TRUE;
	if(bDistributed)
	{
		if(!GetPogd(PogdD))
		{//"Distributed Type의 힌지를 자동계산하려면 Pushover Global Control Data를 입력해야 합니다."
			GSaveHistoryFormatNF(_LS(IDS_DB_PO_AUTO_CALC_Distributed));
			return FALSE;
		}
		nLocOfBeamColum = PogdD.nLocOfBeam;   // 0:I, 1:J, 2:Center
		nLocOfWall      = PogdD.nLocOfColumn; // 0:I, 1:J
	}
	if(!bDistributed)
	{
		// Lumped 일 경우
		for(int nDof=D_DOF_FX; nDof<=D_DOF_MZ ; ++nDof)
		{
			if(!PhgtD.bDOF[nDof]) continue;
			BOOL bAutoCalc= FALSE;
			if(nDof>=D_DOF_MY) // My, Mz
			{
				if(PhgtD.nInteractionType!=D_PHGT_INTERCTION_PM)
				{
					if(PhgtData.Skcv[nDof].nCalcMethod==D_PHGT_CALC_AUTO)  bAutoCalc = TRUE;          
				}
				else
				{
					if(PhgtData.YieldSurface.nCalcMethod==D_PHGT_CALC_AUTO) bAutoCalc = TRUE;
				}
			}
			else
			{
				if(PhgtData.Skcv[nDof].nCalcMethod==D_PHGT_CALC_AUTO) bAutoCalc=TRUE;        
			}
			// 20080331 mylee - EC8 인 경우, User 이어도 DeformCheck 가 없으면 계산하도록.
			if(!bAutoCalc && PhgtData.nSkcvType[nDof]==D_SKCV_EC8 &&
				(!PhgtData.Skcv[nDof].FEMA.bUserDefineYieldDeform || !PhgtData.SkcvSub[nDof].FEMA.bUserDefineYieldDeform))
			{
				bAutoCalc = TRUE;
			}
			if(bAutoCalc)
			{
				nAutoCalcPosition[nDof] = PhgtD.nLoc[nDof];
			}
		}
		return TRUE;
	}
	else 
	{
		// Distributed 일 경우
		int nPosition = D_PHGT_LOCATION_NONE;
		if     (PhgtD.nElemType == 0 || PhgtD.nElemType==1)
		{ // Beam/Column
			if     (nLocOfBeamColum==0) nPosition=D_PHGT_LOCATION_I;
			else if(nLocOfBeamColum==1) nPosition=D_PHGT_LOCATION_J;
			else if(nLocOfBeamColum==2) nPosition=D_PHGT_LOCATION_CENTER;
		}

		for(int nDof=D_DOF_FX; nDof<=D_DOF_MZ ; ++nDof)
		{
			if(!PhgtD.bDOF[nDof]) continue;      
			BOOL bAutoCalc= FALSE;
			if(nDof>=D_DOF_MY) // My, Mz
			{
				if(PhgtD.nInteractionType!=D_PHGT_INTERCTION_PM)
				{
					if(PhgtData.Skcv[nDof].nCalcMethod==D_PHGT_CALC_AUTO)  bAutoCalc = TRUE;          
				}
				else
				{
					if(PhgtData.YieldSurface.nCalcMethod==D_PHGT_CALC_AUTO) bAutoCalc = TRUE;
				}
			}
			else
			{
				if(PhgtData.Skcv[nDof].nCalcMethod==D_PHGT_CALC_AUTO) bAutoCalc=TRUE;

			}
			if(bAutoCalc)
				nAutoCalcPosition[nDof] = nPosition;      
		}
		return TRUE;
	}
	return FALSE;
}

BOOL CAttrCtrl::MakeSkcvStrength4YieldSurface(const T_PHGT_D &PhgtD, T_PHGT_YLDS &rYldsD, const int &nDOF, T_PHGT_SKCV &rSkcvD, T_PHGT_SKCV &rSkcvSubD)
{// Yield Surface 에 따라 SkcvTabDlg, SkcvTabFemaDlg 에 특정 Yield Strength 를 계산하여 보여준다.
	// 특정 Yield Strength 란 Axial Force==0 일 경우의 Moment 값을 의미함.
	if(PhgtD.nInteractionType!=1) return FALSE;

	BOOL bRCMaterial = TRUE;
	if     (PhgtD.nMaterial==0) bRCMaterial=TRUE;  // RC
	else if(PhgtD.nMaterial==1) bRCMaterial=FALSE; // Steel
	else ASSERT(0);

	int nCase=1;
	if     (PhgtD.nSkcvType[4]==D_SKCV_STD_TRI) nCase = 1; //Trilinear
	else if(PhgtD.nSkcvType[4]==D_SKCV_STD_BI ) nCase = 2; //Bilinear
	else if(m_pDoc->IsPOSkcvFEMAEC8(PhgtD.nSkcvType[4])) nCase = 3; //FEMA & EC8

	BOOL bNeedJend = FALSE;
	if(PhgtD.nDefinition!=D_PHGT_DEFINITION_MPHI_DIST)
	{
		if(PhgtD.nLoc[4]==D_PHGT_LOCATION_IJ) bNeedJend=TRUE;
	}

	double dMY0P[2], dMY0M[2];
	for(int nTab=0; nTab<2; ++nTab) // 0:I-end, 1:J-end
	{
		if(nTab==1 && !bNeedJend) continue;

		CalcMY0ForYieldSurface(rYldsD, nTab, dMY0P, dMY0M);
		double dMY0_Y[2] = {dMY0P[0], dMY0M[0]};
		double dMY0_Z[2] = {dMY0P[1], dMY0M[1]};

		double dMY01[2] = {0., 0.};
		double dMY0_Y1[2], dMY0_Z1[2];
		if(!bRCMaterial && nCase==1)
		{//Steel Trilinear는 1st Surface에서 찾아야 한다.
			double dMY0P1[2], dMY0M1[2];
			CalcMY0ForYieldSurface(rYldsD, nTab, dMY0P1, dMY0M1, FALSE);        
			dMY0_Y1[0] = dMY0P1[0];
			dMY0_Y1[1] = dMY0M1[0];
			dMY0_Z1[0] = dMY0P1[1];
			dMY0_Z1[1] = dMY0M1[1];
		}
		T_PHGT_SKCV SkcvD;
		T_PHGT_YLDP YldpD;

		if     (nTab==0) { SkcvD = rSkcvD;     YldpD = rYldsD.YieldSurfaceProp;    }
		else if(nTab==1) { SkcvD = rSkcvSubD;  YldpD = rYldsD.YieldSurfacePropSub; }
		else ASSERT(0);

		double dMoment1[2];
		double dMY0[2];

		for(int k=0; k<2; ++k)    // +, -
		{
			if(nDOF==4)      
			{ 
				dMoment1[k] = YldpD.dMomentY[k][0];
				dMY0[k]     = dMY0_Y[k];        
				dMY01[k]    = dMY0_Y1[k];
			}
			else    
			{      
				dMoment1[k] = YldpD.dMomentZ[k][0];
				dMY0[k]     = dMY0_Z[k];
				dMY01[k]    = dMY0_Z1[k];
			}


			if(bRCMaterial)
			{//RC
				switch(nCase)
				{
				case 1://Trilinear
					SkcvD.Multi.dMoment[k][0] = dMoment1[k];
					SkcvD.Multi.dMoment[k][1] = dMY0[k];
					break;
				case 2://Bilinear
					SkcvD.Multi.dMoment[k][0] = dMoment1[k];
					SkcvD.Multi.dMoment[k][1] = dMY0[k];          
					break;
				case 3:
					SkcvD.FEMA.dYieldMoment[k] = dMY0[k];
					break;
				}        
			}
			else
			{//Steel        
				switch(nCase)
				{
				case 1://Trilinear          
					SkcvD.Multi.dMoment[k][0] = dMY01[k];
					SkcvD.Multi.dMoment[k][1] = dMY0[k];
					break;
				case 2://Bilinear
					SkcvD.Multi.dMoment[k][0] = dMoment1[k];
					SkcvD.Multi.dMoment[k][1] = dMY0[k];          
					break;
				case 3:
					SkcvD.FEMA.dYieldMoment[k] = dMY0[k];
					break;
				}
			}
			if     (nTab==0) rSkcvD    = SkcvD;
			else if(nTab==1) rSkcvSubD = SkcvD;
		}//End of +,-


	}
	return TRUE;
}

BOOL CAttrCtrl::CalcMY0ForYieldSurface(T_PHGT_YLDS &YldsD, const int &nTab, double dMY0P[2], double dMY0M[2], BOOL bFind2ndSurface/*TRUE*/)
{//항복면의 가로축(Moment축)의 절편을 계산하는 함수
	T_PHGT_YLDP YldpD;
	if(nTab==0)  YldpD = YldsD.YieldSurfaceProp;
	else         YldpD = YldsD.YieldSurfacePropSub;

	double dMY0_Z[2], dMY0_Y[2];
	int nChangeY[2], nChangeZ[2];
	for(int k=0; k<2; ++k)  // +, -
	{
		nChangeY[k]=10; // 부호가 - => + 되는 시점
		nChangeZ[k]=10;
		BOOL bFindY=FALSE, bFindZ=FALSE;
		if(bFind2ndSurface)
		{
			for(int j=10; j>=0; --j)
			{
				if(!bFindY && YldpD.d2ndSurface_RatioPY[k][j] > 0.) { nChangeY[k]=j; bFindY=TRUE; }
				if(!bFindZ && YldpD.d2ndSurface_RatioPZ[k][j] > 0.) { nChangeZ[k]=j; bFindZ=TRUE; }
				if(bFindY && bFindZ) break;
			}
		}
		else
		{
			for(int j=10; j>=0; --j)
			{
				if(!bFindY && YldpD.d1stSurface_RatioPY[k][j] > 0.) { nChangeY[k]=j; bFindY=TRUE; }
				if(!bFindZ && YldpD.d1stSurface_RatioPZ[k][j] > 0.) { nChangeZ[k]=j; bFindZ=TRUE; }
				if(bFindY && bFindZ) break;
			}
		}

		double dP[2]; 
		double dM[2];   
		if(YldpD.d2ndSurface_RatioPY[k][10] >=0.)  dMY0_Y[k] = 0.;    
		else
		{
			if(bFind2ndSurface)
			{
				dP[1] = YldpD.d2ndSurface_RatioPY[k][nChangeY[k]+1];
				dP[0] = YldpD.d2ndSurface_RatioPY[k][nChangeY[k]];
				dM[1] = YldpD.d2ndSurface_RatioMY[k][nChangeY[k]+1];
				dM[0] = YldpD.d2ndSurface_RatioMY[k][nChangeY[k]];
			}
			else
			{
				dP[1] = YldpD.d1stSurface_RatioPY[k][nChangeY[k]+1];
				dP[0] = YldpD.d1stSurface_RatioPY[k][nChangeY[k]];
				dM[1] = YldpD.d1stSurface_RatioMY[k][nChangeY[k]+1];
				dM[0] = YldpD.d1stSurface_RatioMY[k][nChangeY[k]];
			}

			dMY0_Y[k] = fabs(dM[1] - ((dM[1]-dM[0])/(dP[1]-dP[0]) * dP[1]));//y
		}

		if(YldpD.d2ndSurface_RatioPZ[k][10] >=0.)  dMY0_Z[k] = 0.;
		else
		{
			if(bFind2ndSurface)
			{
				dP[1] = YldpD.d2ndSurface_RatioPZ[k][nChangeZ[k]+1];
				dP[0] = YldpD.d2ndSurface_RatioPZ[k][nChangeZ[k]];
				dM[1] = YldpD.d2ndSurface_RatioMZ[k][nChangeZ[k]+1];
				dM[0] = YldpD.d2ndSurface_RatioMZ[k][nChangeZ[k]];
			}
			else
			{
				dP[1] = YldpD.d1stSurface_RatioPZ[k][nChangeZ[k]+1];
				dP[0] = YldpD.d1stSurface_RatioPZ[k][nChangeZ[k]];
				dM[1] = YldpD.d1stSurface_RatioMZ[k][nChangeZ[k]+1];
				dM[0] = YldpD.d1stSurface_RatioMZ[k][nChangeZ[k]];
			}

			dMY0_Z[k] = fabs(dM[1] - ((dM[1]-dM[0])/(dP[1]-dP[0]) * dP[1]));
		}    
	}

	// Seungjun-20130131 : MQC.4645
	// 항복곡면에 따라 다른 값을 써야함.
	if(bFind2ndSurface)
	{
		dMY0P[0] = dMY0_Y[0]*YldpD.dMomentY[0][1];   dMY0P[1] = dMY0_Z[0]*YldpD.dMomentZ[0][1];
		dMY0M[0] = dMY0_Y[1]*YldpD.dMomentY[1][1];   dMY0M[1] = dMY0_Z[1]*YldpD.dMomentZ[1][1];
	}
	else
	{
		dMY0P[0] = dMY0_Y[0]*YldpD.dMomentY[0][0];   dMY0P[1] = dMY0_Z[0]*YldpD.dMomentZ[0][0];
		dMY0M[0] = dMY0_Y[1]*YldpD.dMomentY[1][0];   dMY0M[1] = dMY0_Z[1]*YldpD.dMomentZ[1][0];
	}

	return TRUE;
}

////////////// phge ////////////////
BOOL CAttrCtrl::MakeKeyPhge(const UINT ElemType, T_ELEM_K KeyElem, T_PHGE_K& rKey)
{
	rKey.key.objK = KeyElem;
	rKey.key.type = ElemType;  
	return TRUE;
}

void CAttrCtrl::GetPhgeKeyList(CArray<T_PHGE_K, T_PHGE_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_PHGE_K Key;
	T_PHGE_D Data;
	pos=GetStartPhge();
	while(pos != NULL)
	{
		GetNextPhge(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortKey20Serial12((unsigned int*)rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetPhgeKeyListSolOrd(CArray<T_PHGE_K, T_PHGE_K>& rKeyList)
{
	rKeyList.RemoveAll();

	CArray<T_ELEM_K, T_ELEM_K> rElemKeyList;
	CArray<T_NLNK_K, T_NLNK_K> rNlnkKeyList;
	CArray<T_NODE_K, T_NODE_K> rNodeKeyList;

	CMap<T_ELEM_K,T_ELEM_K,T_PHGE_K,T_PHGE_K&> mapElemPhgeK;
	CMap<T_NLNK_K,T_NLNK_K,T_PHGE_K,T_PHGE_K&> mapNlnkPhgeK;
	CMap<T_NODE_K,T_NODE_K,T_PHGE_K,T_PHGE_K&> mapNodePhgeK;

	POSITION pos;
	T_PHGE_K Key;
	T_PHGE_D Data;

	pos=GetStartPhge();
	while(pos != NULL)
	{
		GetNextPhge(pos, Key, Data);
		if(Key.key.type==D_PHGE_GLINK)
		{
			rNlnkKeyList.Add(Key.key.objK);
			mapNlnkPhgeK.SetAt(Key.key.objK,Key);
		}
		else if(Key.key.type==D_PHGE_PSPR)
		{
			rNodeKeyList.Add(Key.key.objK);
			mapNodePhgeK.SetAt(Key.key.objK,Key);
		}
		else
		{
			rElemKeyList.Add(Key.key.objK);
			mapElemPhgeK.SetAt(Key.key.objK,Key);
		}
	}

	CQSort::QSortUInt(rElemKeyList.GetData(), rElemKeyList.GetSize());
	for(int i=0; i<rElemKeyList.GetSize(); i++)
	{
		mapElemPhgeK.Lookup(rElemKeyList[i],Key);
		rKeyList.Add(Key);
	}
	CQSort::QSortUInt(rNlnkKeyList.GetData(), rNlnkKeyList.GetSize());
	for(int i = 0; i<rNlnkKeyList.GetSize(); i++)
	{
		mapNlnkPhgeK.Lookup(rNlnkKeyList[i],Key);
		rKeyList.Add(Key);
	}
	CQSort::QSortUInt(rNodeKeyList.GetData(), rNodeKeyList.GetSize());
	for(int i = 0; i<rNodeKeyList.GetSize(); i++)
	{
		mapNodePhgeK.Lookup(rNodeKeyList[i],Key);
		rKeyList.Add(Key);
	}
}

void CAttrCtrl::GetPhgeObjKeyList(const int &nType, CArray<T_KEY, T_KEY>& rKeyList)
{
	//rKeyList 에는 Beam, Column, Wall, Truss, General Link 가 들어갈 수 있음.
	// nType = D_PHGE_XXXX(DB_ST_DT_POVR)
	rKeyList.RemoveAll();
	CArray<T_PHGE_K, T_PHGE_K> aPhgeKeyList;
	GetPhgeKeyList(aPhgeKeyList);

	int nNum = aPhgeKeyList.GetSize();
	T_PHGE_K PhgeK;
	for(int i=0; i<nNum; ++i)
	{
		PhgeK = aPhgeKeyList[i];
		if(PhgeK.key.type ==nType)
			rKeyList.Add(PhgeK.key.objK);
	}
}

void CAttrCtrl::GetPhgeElemKeyList(CArray<T_ELEM_K, T_ELEM_K>& rKeyList)
{
	//rKeyList 에 Beam, Column, Wall, Truss 키를 넣어줌.
	// nType = D_PHGE_XXXX(DB_ST_DT_POVR)
	rKeyList.RemoveAll();
	CArray<T_PHGE_K, T_PHGE_K> aPhgeKeyList;
	GetPhgeKeyList(aPhgeKeyList);

	int nNum = aPhgeKeyList.GetSize();
	T_PHGE_K PhgeK;
	for(int i=0; i<nNum; ++i)
	{
		PhgeK = aPhgeKeyList[i];
		if(PhgeK.key.type !=D_PHGE_GLINK &&PhgeK.key.type !=D_PHGE_PSPR)
			rKeyList.Add(PhgeK.key.objK);
	}
}

BOOL CAttrCtrl::ExistPhge(T_PHGE_K Key)
{
	T_PHGE_D Data;
	return m_pDataMemb->m_phge.Get(Key,Data);
}

BOOL CAttrCtrl::GetPhge(T_PHGE_K Key,T_PHGE_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_phge.Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitPhgeOut(rData);
	return bReturn;
}

BOOL CAttrCtrl::GetPhgeObj(const int &nType, T_KEY ObjKey, T_PHGE_K& rKey, T_PHGE_D& rData)
{  
	if(nType!=D_PHGE_GLINK && nType!=D_PHGE_PSPR)
	{
		ElemList* pList;
		VERIFY(m_pDataMemb->m_elem.GetList(ObjKey, pList));
		T_LIST_DATA ListData;
		POSITION pos=pList->GetHeadPosition();
		while(pos != NULL)
		{
			ListData=pList->GetNext(pos);
			if(ListData.nCmd == LT_PHGE_CMD)
			{
				MakeKeyPhge(nType, ObjKey, rKey);
				if (GetPhge(rKey, rData))
				{
					return TRUE;
				}
			}      
		}
	}
	else if(nType==D_PHGE_PSPR)
	{
		MakeKeyPhge(nType, ObjKey, rKey);
		if (GetPhge(rKey, rData))
		{
			return TRUE;
		}
	}
	else  
	{
		T_NLNK_K NlnkK;
		T_NLNK_D NlnkD;
		POSITION pos=m_pDataMemb->m_nlnk.GetStart();
		while(pos != NULL)
		{
			m_pDataMemb->m_nlnk.GetNext(pos, NlnkK, NlnkD);
			if(NlnkK == ObjKey)
			{
				MakeKeyPhge(nType, ObjKey, rKey);
				if (GetPhge(rKey, rData))
				{
					return TRUE;
				}
			}
		}
	}

	return FALSE;
}

