BOOL CAttrCtrl::GetGhngName(T_PHGE_K PhgeK, CString& rstrGhngName)
{
	if(PhgeK.key.type <1 || PhgeK.key.type >5) return FALSE;

	T_PHGE_D PhgeD;  if(!GetPhge(PhgeK, PhgeD)) return FALSE;
	T_PHGT_D PhgtD;  if(!GetPhgt(PhgeD.HingeTypeK, PhgtD)) return FALSE;

	CString strType;
	if(PhgeK.key.type != D_PHGE_GLINK && PhgeK.key.type != D_PHGE_PSPR)
	{
		T_ELEM_D Elem;
		if (!GetElem(PhgeK.key.objK, Elem)) return FALSE;
		if      (Elem.eltyp == BEAM_EL) strType = _LSX(B);
		else if (Elem.eltyp == TRUSS_EL || Elem.eltyp == TRTENS_EL || Elem.eltyp == TRCOMP_EL) strType = _LSX(T);
		else if (Elem.eltyp == WALL_EL)  strType = _LSX(W);
		else return FALSE;
	}
	else if(PhgeK.key.type == D_PHGE_PSPR)
	{
		strType=_LSX(N);  // Node  
	}
	else
	{
		strType=_LSX(SPR);  // Spring    
	}
	rstrGhngName.Format(_T("%s%d_%s"), strType, PhgeK.key.objK, PhgtD.strName);
	return TRUE;
}

BOOL CAttrCtrl::GetGhngName(const T_PHGE_K &PhgeK, const CString &strPhgtName, CString& rstrGhngName)
{
	rstrGhngName.Empty();
	if(PhgeK.key.type <1 || PhgeK.key.type >5) return FALSE;

	CString strType = _T("");
	if(PhgeK.key.type != D_PHGE_GLINK && PhgeK.key.type != D_PHGE_PSPR)
	{
		T_ELEM_D ElemD;
		if (!GetElem(PhgeK.key.objK, ElemD)) return FALSE;
		if      (ElemD.eltyp == BEAM_EL) strType = _LSX(B);
		else if (ElemD.eltyp == TRUSS_EL || ElemD.eltyp == TRTENS_EL || ElemD.eltyp == TRCOMP_EL) strType = _LSX(T);
		else if (ElemD.eltyp == WALL_EL)  strType = _LSX(W);
		else return FALSE;
	}
	else if(PhgeK.key.type == D_PHGE_PSPR)
	{
		strType=_LSX(N);  // Node  
	}
	else
	{
		strType=_LSX(SPR);  // Spring    
	}

	rstrGhngName.Format(_T("%s%d_%s"), strType, PhgeK.key.objK, strPhgtName);

	return TRUE;
}

BOOL CAttrCtrl::ExistMasonry()
{
	CMap<T_PHGT_K,T_PHGT_K,T_PHGT_D,T_PHGT_D&> mapPhgtData;
	//mapPhgtData.InitHashTable(m_pDoc->GetHashSizeElem());

	T_PHGT_K PhgtK;  T_PHGT_D PhgtD;
	T_PHGE_K PhgeK;  T_PHGE_D PhgeD;
	CArray<T_PHGT_K, T_PHGT_K> arPhgtKeyList;
	CArray<T_PHGE_K, T_PHGE_K> arPhgeKeyList;
	GetPhgtKeyList(arPhgtKeyList);
	GetPhgeKeyList(arPhgeKeyList);

	for(int i=0; i<arPhgtKeyList.GetSize(); i++)
	{
		PhgtK = arPhgtKeyList[i];
		GetPhgt(PhgtK,PhgtD);
		mapPhgtData.SetAt(PhgtK,PhgtD);
	}

	for(int i = 0; i<arPhgeKeyList.GetSize(); i++)
	{
		PhgeK = arPhgeKeyList[i];
		GetPhge(PhgeK,PhgeD);

		PhgtK = PhgeD.HingeTypeK;
		mapPhgtData.Lookup(PhgtK,PhgtD);

		if(PhgtD.nMaterial==2)  //2=Masonry
			return TRUE;
	}

	return FALSE;
}

BOOL CAttrCtrl::MakePOHingeAssignedMembKList(int& nMaxElemSize__POHingeAssignedMemb, CArray<T_MEMB_K, T_MEMB_K>& aMembK_POHingeAssigned)
{
	nMaxElemSize__POHingeAssignedMemb = 0;
	aMembK_POHingeAssigned.RemoveAll();
	CArray<T_MEMB_K,T_MEMB_K> aMembK;
	GetMembKeyList(aMembK);
	for(int i=0; i<aMembK.GetSize(); i++)
	{
		T_MEMB_D MembD;
		GetMemb(aMembK[i], MembD);

		// Single Member는 제외
		if(MembD.aElemList.GetSize()<=1) 
			continue;

		T_PHGE_K PhgeK;
		PhgeK.key.type = 1; // Beam/Column
		PhgeK.key.objK = MembD.aElemList[0];
		if(ExistPhge(PhgeK))
		{
			T_PHGE_D PhgeD;
			T_PHGT_D PhgtD;
			GetPhge(PhgeK, PhgeD);
			GetPhgt(PhgeD.HingeTypeK, PhgtD);
			if(PhgtD.nDefinition!=D_PHGT_DEFINITION_MTHETA_LUMP)
				continue;

			aMembK_POHingeAssigned.Add(aMembK[i]);

			if(nMaxElemSize__POHingeAssignedMemb < MembD.aElemList.GetSize())
				nMaxElemSize__POHingeAssignedMemb = MembD.aElemList.GetSize();
		}
	}

	return aMembK_POHingeAssigned.IsEmpty()==FALSE;
}

