void CAttrCtrl::GetRcplList(CArray<CString, CString&>& rstrNameList)
{
	rstrNameList.RemoveAll();

	T_RCPL_D Data;
	CArray<T_RCPL_K, T_RCPL_K>KeyList;
	GetRcplKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetRcpl(KeyList[i], Data))
			rstrNameList.Add(Data.strName);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetRcplKeyList(CArray<T_RCPL_K, T_RCPL_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<CString, CString&>arName;

	POSITION pos;
	T_RCPL_K Key;
	T_RCPL_D Data;
	pos=GetStartRcpl();
	while(pos != NULL)
	{
		GetNextRcpl(pos, Key, Data);
		rKeyList.Add(Key);
		arName.Add(Data.strName);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortStringWithIndex(rKeyList.GetData(), arName.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetRcplKeyListHasElem(T_ELEM_K ElemKey, CArray<T_RCPL_K, T_RCPL_K>& rKeyList) // Elem 을 가진 RCPL
{
	rKeyList.RemoveAll();

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(ElemKey, pList));
	T_LIST_DATA ListData;
	POSITION pos = pList->GetHeadPosition();
	while (pos)
	{
		ListData = pList->GetNext(pos);
		if (ListData.nCmd == LT_RCPL_CMD) rKeyList.Add(ListData.nKey);
	}
}

BOOL CAttrCtrl::ExistRcpl(CString& rName)
{
	T_RCPL_D data;
	return GetRcpl(rName, data);
}

BOOL CAttrCtrl::ExistRcpl(T_RCPL_K Key)
{
	T_RCPL_D Data;
	return m_pDataMemb->m_pRcpl->Get(Key,Data);
}

BOOL CAttrCtrl::GetRcpl(CString& rName, T_RCPL_D& rData)
{
	T_RCPL_K key;
	T_RCPL_D data;
	CString strName=rName;
	strName.TrimRight();

	POSITION pos=m_pDataMemb->m_pRcpl->GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_pRcpl->GetNext(pos,key,data);
		if(strName.CompareNoCase(data.strName) == 0)
		{
			m_pUnitCtrl->ConvertUnitRcplOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

