T_RCPL_K CAttrCtrl::GetNextNumRcpl(T_RCPL_K StartNum)
{
	if(StartNum > GetLastNumRcpl())return StartNum;
	T_RCPL_K Key=StartNum;
	T_RCPL_D Data;
	while(TRUE)
	{
		Key++;
		if(!m_pDataMemb->m_pRcpl->Get(Key,Data))return Key;
	}
}

