BOOL CAttrCtrl::ConvertPoctPplc2Pogd(const T_POCT_D *pPoctD, const T_PPLC_D *pPplcD, T_POGD_D *pPogdD)
{
	if(pPogdD==NULL) return FALSE;
	if(pPoctD==NULL && pPplcD==NULL)
	{
		pPogdD->Initialize();
		return TRUE;
	}

	if(pPoctD)
	{
		pPogdD->nMaxIterNum = pPoctD->nMaxIterNum;
		pPogdD->bDisplNorm  = pPoctD->bDisplNorm ;
		pPogdD->bForceNorm  = pPoctD->bForceNorm ;
		pPogdD->bEnergyNorm = pPoctD->bEnergyNorm;
		pPogdD->dDisplNorm  = pPoctD->dDisplNorm ;
		pPogdD->dForceNorm  = pPoctD->dForceNorm ;
		pPogdD->dEnergyNorm = pPoctD->dEnergyNorm;
	}
	if(pPplcD)
	{
		int nSize = pPplcD->aLoadPattern.GetSize();
		pPogdD->aInitLoad.SetSize(nSize);
		for(int i=0; i<nSize; ++i)
		{
			pPogdD->aInitLoad[i].LoadCaseType = D_LOADCASE_STATIC;
			pPogdD->aInitLoad[i].LoadCaseKey  = pPplcD->aLoadPattern[i].LoadCaseKey;
			pPogdD->aInitLoad[i].dScaleFactor = pPplcD->aLoadPattern[i].dScaleFactor;
		}
	}
	pPogdD->bAssignByMember = FALSE;

	return TRUE;
}

BOOL CAttrCtrl::ConvertPold2Polc(const T_POLD_D *pPoldD, const int &nStepNum, T_POLC_D *pPolcD)
{
	if(pPolcD==NULL) { ASSERT(0); return TRUE; }
	pPolcD->Initialize();

	if(pPoldD==NULL) return TRUE;

	pPolcD->LoadCaseId       = pPoldD->LoadCaseId;
	pPolcD->strName          = pPoldD->LoadCaseName;
	pPolcD->strDescription   = pPoldD->Description;
	if(nStepNum>0) pPolcD->nStepNum = nStepNum;
	pPolcD->bUseInitial      = pPoldD->bUsePrevPold;
	pPolcD->bConsiderPDelta  = (pPoldD->nAnalysisOption!=0);
	pPolcD->nIncrementMethod = pPoldD->nIncrementMethod;
	pPolcD->nDispCtrlOption  = pPoldD->nControlOption-1;
	pPolcD->dOverallMaxDisp  = pPoldD->dOverallMaxDisp;
	pPolcD->MasterNode       = pPoldD->MasterNode;
	pPolcD->MasterDirection  = pPoldD->MasterDirection;
	pPolcD->dMasterMaxDisp   = pPoldD->dMasterMaxDisp;
	pPolcD->dIntStorDeformValue = pPoldD->dNewInterStoryDeformAngle;
	pPolcD->nLoadPattern     = pPoldD->nLoadPatternType;
	int nSize = pPoldD->aLoadPattern.GetSize();
	pPolcD->aLoadPattern.SetSize(nSize);
	for(int i=0; i<nSize; ++i)
	{
		pPolcD->aLoadPattern[i].LoadCaseKey  = pPoldD->aLoadPattern[i].LoadCaseKey;
		pPolcD->aLoadPattern[i].dScaleFactor = pPoldD->aLoadPattern[i].dScaleFactor;
	}

	// MNET:4103-SHJUNG-20100722 : Init Load 사용시, 기존 해석 옵션을 맞춰주기 위해 반력 누적 옵션을 셋팅한다.
	if(pPolcD->bUseInitial)
		pPolcD->bReacOutput = TRUE;

	return TRUE;
}

