void CAttrCtrl::GetDefaultRlco(T_RLCO_D& rData)
{
	ASSERT_ONCE(0); // 이 함수를 쓰게 되면 MpgbD.nEarthquakeType 가 MPHG 로 옮겨간 것에 대한 처리를 해 주어야 함
	T_MPGB_D MpgbD;
	if(!GetMpgb(MpgbD)) MpgbD.Initialize();
	rData.Initialize();	
	rData.bEarthquakeTypeI  = (MpgbD.nEarthquakeType == 0);
	rData.bEarthquakeTypeII = (MpgbD.nEarthquakeType != 0);		
	rData.nInitialForce     = MpgbD.nInitialForce;
}

////////////// rlcc ////////////////

void CAttrCtrl::GetRlccList(CArray<CString, CString&>& rstrNameList)
{
	rstrNameList.RemoveAll();

	T_RLCC_D Data;
	CArray<T_RLCC_K, T_RLCC_K>KeyList;
	GetRlccKeyList(KeyList);
	int nCount=KeyList.GetSize();
	for(int i=0; i<nCount; i++)
	{
		if(GetRlcc(KeyList[i], Data))
			rstrNameList.Add(Data.strName);
		else
			ASSERT(FALSE);
	}
}

void CAttrCtrl::GetRlccKeyList(CArray<T_RLCC_K, T_RLCC_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<CString, CString&>arName;

	POSITION pos;
	T_RLCC_K Key;
	T_RLCC_D Data;
	pos=GetStartRlcc();
	while(pos != NULL)
	{
		GetNextRlcc(pos, Key, Data);
		rKeyList.Add(Key);
		arName.Add(Data.strName);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortStringWithIndex(rKeyList.GetData(), arName.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetRlccKeyListHasElem(T_ELEM_K ElemKey, CArray<T_RLCC_K, T_RLCC_K>& rKeyList) // Elem 을 가진 RLCC
{
	rKeyList.RemoveAll();

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(ElemKey, pList));
	T_LIST_DATA ListData;
	POSITION pos = pList->GetHeadPosition();
	while (pos)
	{
		ListData = pList->GetNext(pos);
		if (ListData.nCmd == LT_RLCC_CMD) rKeyList.Add(ListData.nKey);
	}
}

BOOL CAttrCtrl::ExistRlcc(CString& rName)
{
	T_RLCC_D data;
	return GetRlcc(rName, data);
}

BOOL CAttrCtrl::ExistRlcc(T_RLCC_K Key)
{
	T_RLCC_D Data;
	return m_pDataMemb->m_pRlcc->Get(Key,Data);
}

BOOL CAttrCtrl::GetRlcc(CString& rName, T_RLCC_D& rData)
{
	T_RLCC_K key;
	T_RLCC_D data;
	CString strName=rName;
	strName.TrimRight();

	POSITION pos=m_pDataMemb->m_pRlcc->GetStart();
	while(pos != NULL)
	{
		m_pDataMemb->m_pRlcc->GetNext(pos,key,data);
		if(strName.CompareNoCase(data.strName) == 0)
		{
			m_pUnitCtrl->ConvertUnitRlccOut(data);
			rData=data;
			return TRUE;
		}
	}
	return FALSE;
}

BOOL CAttrCtrl::GetRlcc(T_RLCC_K Key,T_RLCC_D& rData)
{
	BOOL bReturn=m_pDataMemb->m_pRlcc->Get(Key,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitRlccOut(rData);
	return bReturn;
}

T_RLCC_K CAttrCtrl::GetRlccKey(CString& rName)
{
	T_RLCC_K key;
	T_RLCC_D data;

	POSITION pos=GetStartRlcc();
	while(pos != NULL)
	{
		GetNextRlcc(pos,key,data);
		if(rName.CompareNoCase(data.strName) == 0)return key;
	}
	key=0;
	return key;
}

int CAttrCtrl::GetCountRlcc()
{
	return m_pDataMemb->m_pRlcc->GetCount();
}

POSITION CAttrCtrl::GetStartRlcc()
{
	return m_pDataMemb->m_pRlcc->GetStart();
}

void CAttrCtrl::GetNextRlcc(POSITION& rNextPosition,T_RLCC_K& rKey,T_RLCC_D& rData)
{
	m_pDataMemb->m_pRlcc->GetNext(rNextPosition,rKey,rData);
	m_pUnitCtrl->ConvertUnitRlccOut(rData);
}

T_RLCC_K CAttrCtrl::GetLastNumRlcc()
{
	return m_pDataMemb->m_pRlcc->m_nLastNum;
}

T_RLCC_K CAttrCtrl::GetStartNumRlcc()
{
	return m_pDataMemb->m_pRlcc->m_nStartNum;
}

T_RLCC_K CAttrCtrl::GetNextNumRlcc(T_RLCC_K StartNum)
{
	if(StartNum > GetLastNumRlcc())return StartNum;
	T_RLCC_K Key=StartNum;
	T_RLCC_D Data;
	while(TRUE)
	{
		Key++;
		if(!m_pDataMemb->m_pRlcc->Get(Key,Data))return Key;
	}
}

