void CAttrCtrl::GetMrebKeyList(CArray<T_MREB_K, T_MREB_K>& rKeyList)
{
	rKeyList.RemoveAll();
	CArray<CString, CString&>arName;

	POSITION pos;
	T_MREB_K Key;
	T_MREB_D Data;
	pos=GetStartMreb();
	while(pos != NULL)
	{
		GetNextMreb(pos, Key, Data);
		rKeyList.Add(Key);
	}
}

int CAttrCtrl::GetElemKeyListUseRebb(T_REBB_K RebbK, CArray<T_ELEM_K, T_ELEM_K>& rKeyList)
{
	rKeyList.RemoveAll();

	if(RebbK.key.subSectK > 0)
	{
		if(!ExistRebb(RebbK))     return 0;
		RebbList* pList;
		VERIFY(m_pDataMemb->m_pRebb->GetList(RebbK, pList));
		T_LIST_DATA ListData;
		POSITION pos = pList->GetHeadPosition();
		while (pos)
		{
			ListData = pList->GetNext(pos);
			if (ListData.nCmd == LT_MREB_CMD) rKeyList.Add(ListData.nKey);
		}
	}
	else
	{
		T_SECT_K SectK = RebbK.key.sectK;
		T_ELEM_K ElemK;
		T_ELEM_D ElemD;
		T_MREB_D MrebD;

		POSITION pos=GetStartElem();
		while(pos != NULL)
		{
			GetNextElem(pos, ElemK, ElemD);
			if(ElemD.elpro != SectK)    continue;
			if(GetMemberType(ElemK) != D_MBTP_BEAM)   continue;

			T_MEMB_K MembK;      
			if(GetMembAssigned(ElemK, MembK))
			{
				T_MEMB_D MembD;
				if(!GetMemb(MembK, MembD))      {  ASSERT(0);		return 0;	}
				if(MembD.aElemList.GetSize() < 1)     {  ASSERT(0);		return FALSE;	}
				if(ElemK != MembD.aElemList[0])   continue;
			}
			if(GetMreb(ElemK, MrebD))
			{
				if(MrebD.RebbK.keymap != RebbK.keymap) continue;
			}

			rKeyList.Add(ElemK);
		}
	}

	int nSize = rKeyList.GetSize();
	if(nSize > 0)   CQSort::QSortUInt(rKeyList.GetData(), nSize);
	return nSize;
}

int CAttrCtrl::GetAllElemKeyListUseRebb(T_REBB_K RebbK, CArray<T_ELEM_K, T_ELEM_K>& rKeyList)
{
	rKeyList.RemoveAll();

	if(RebbK.key.subSectK > 0)
	{
		if(!ExistRebb(RebbK))     return 0;
		RebbList* pList;
		VERIFY(m_pDataMemb->m_pRebb->GetList(RebbK, pList));
		T_LIST_DATA ListData;
		POSITION pos = pList->GetHeadPosition();
		while (pos)
		{
			ListData = pList->GetNext(pos);
			if (ListData.nCmd == LT_MREB_CMD)
			{
				T_MEMB_K MembK;      
				if(GetMembAssigned(ListData.nKey, MembK))
				{
					T_MEMB_D MembD;
					if(!GetMemb(MembK, MembD))      {  ASSERT(0);		return 0;	}
					rKeyList.Append(MembD.aElemList);
				}
				else  rKeyList.Add(ListData.nKey);
			}
		}
	}
	else
	{
		T_SECT_K SectK = RebbK.key.sectK;
		T_ELEM_K ElemK;
		T_ELEM_D ElemD;
		T_MREB_D MrebD;

		POSITION pos=GetStartElem();
		while(pos != NULL)
		{
			GetNextElem(pos, ElemK, ElemD);
			if(ElemD.elpro != SectK)    continue;
			if(GetMemberType(ElemK) != D_MBTP_BEAM)   continue;

			T_MEMB_K MembK;      
			if(GetMembAssigned(ElemK, MembK))
			{
				T_MEMB_D MembD;
				if(!GetMemb(MembK, MembD))      {  ASSERT(0);		return 0;	}
				if(MembD.aElemList.GetSize() < 1)     {  ASSERT(0);		return FALSE;	}
				if(GetMreb(MembD.aElemList[0], MrebD))
				{
					if(MrebD.RebbK.keymap != RebbK.keymap) continue;
				}
			}
			else
			{
				if(GetMreb(ElemK, MrebD))
				{
					if(MrebD.RebbK.keymap != RebbK.keymap) continue;
				}
			}

			rKeyList.Add(ElemK);
		}
	}

	int nSize = rKeyList.GetSize();
	if(nSize > 0)   CQSort::QSortUInt(rKeyList.GetData(), nSize);
	return nSize;
}

