int CAttrCtrl::GetElemKeyListUseRbms(T_RBMS_K RbmsK, CArray<T_ELEM_K, T_ELEM_K>& rKeyList)
{
	rKeyList.RemoveAll();

	if(!ExistRbms(RbmsK))     return 0;

	T_MREB_D MrebD;
	CArray<T_MREB_K, T_MREB_K> aMrebK;
	GetMrebKeyList(aMrebK);
	for (int i=0; i<aMrebK.GetSize(); i++)
	{
		GetMreb(aMrebK[i], MrebD);  
		if(MrebD.nMembType != MREB_MSLAB) continue;
		for (int j=0; j<MrebD.aRbmsK.GetSize(); j++)
		{
			if(RbmsK == MrebD.aRbmsK[j])
			{
				rKeyList.Add(aMrebK[i]);
				break;
			}
		}
	}

	int nSize = rKeyList.GetSize();
	if(nSize > 0)   CQSort::QSortUInt(rKeyList.GetData(), nSize);
	return nSize;
}

