{
	BOOL bReturn=m_pDataMemb->m_pMlcb->Get(rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitMlcbOut(rData);
	return bReturn;
}

BOOL CAttrCtrl::Get_DefaultMlcb(T_MLCB_D& rMlcbD)
{
	BOOL bSkipMlcbDB = CDBLib::GetConCodeName() != CONCODE_SP_63_13330_2018;
	if (bSkipMlcbDB)
	{
		if (GetMlcb(rMlcbD))    return TRUE;
	}

	rMlcbD.Initialize();
	CArray<T_LCOM_K,T_LCOM_K> aLcomK;
	GetLcomKeyList(D_LCOMTYPE_CONCRETE, aLcomK);
	int nLcomSize = aLcomK.GetSize();

    enum class EN_SERV_LCOM
    {
        GENERAL = 0,
        SUBLCOM,
		ALL_SERV,
    };

    auto L_GetServLcomType =[](const CString& strConCode) -> EN_SERV_LCOM
    {
        if ( strConCode == CONCODE_ACI318_05  ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_ACI318_08  ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_ACI318_11  ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_ACI318_14  ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_ACI318M_14 ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_ACI318_19  ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_ACI318M_19 ) { return EN_SERV_LCOM::GENERAL; }
		if ( strConCode == CONCODE_ACI318_25  ) { return EN_SERV_LCOM::GENERAL; }
		if ( strConCode == CONCODE_ACI318M_25 ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_NSR_10     ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_NSCP_2015  ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_KCI_USD12  ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_IS456_2000 ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_EC2_04     ) { return EN_SERV_LCOM::SUBLCOM; }
        if ( strConCode == CONCODE_EC2_2_05   ) { return EN_SERV_LCOM::SUBLCOM; }
        if ( strConCode == CONCODE_GB50010_10 ) { return EN_SERV_LCOM::SUBLCOM; }
		if ( strConCode == CONCODE_GB50010_19 ) { return EN_SERV_LCOM::SUBLCOM; }
		if ( strConCode == CONCODE_BS5400_90  ) { return EN_SERV_LCOM::SUBLCOM; }
		if ( strConCode == CONCODE_TMH07_89  ) { return EN_SERV_LCOM::SUBLCOM; }
		if ( strConCode == CONCODE_AIJ_WSD99  ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_KDS_41_30_2018 ) { return EN_SERV_LCOM::GENERAL; }
        if ( strConCode == CONCODE_KDS_41_20_2022 ) { return EN_SERV_LCOM::GENERAL; }
		if ( strConCode == CONCODE_NTC_DCEC_2017 ) { return EN_SERV_LCOM::GENERAL; }
		if ( strConCode == CONCODE_NTC_DCEC_2023 ) { return EN_SERV_LCOM::GENERAL; }
		if ( strConCode == CONCODE_TWN_USD112 ) { return EN_SERV_LCOM::GENERAL; }
		if (strConCode == CONCODE_SP_63_13330_2018) { return EN_SERV_LCOM::ALL_SERV; }

        ASSERT(0);
        return EN_SERV_LCOM::GENERAL;
    };
    
    const EN_SERV_LCOM enServLcom = L_GetServLcomType(CDBLib::GetConCodeName());
    
	T_LCOM_D LcomD;
	T_LCOM_D_UL LcomD_UL;
	for(int i = 0; i < nLcomSize; i++)
	{
		T_LCOM_K LcomK = aLcomK[i];
		if(!GetLcom(D_LCOMTYPE_CONCRETE, LcomK, LcomD))      {  ASSERT(0);		continue;	}
		if(LcomD.nActive != 1 && LcomD.nActive != 2)    continue;    
		if(!NormalizeLcom(LcomD,LcomD_UL))
		{
			LcomD_UL = LcomD;
		}

		if(LcomD_UL.nActive == 1)
		{
			rMlcbD.aWallStreK.Add(LcomK);
			rMlcbD.aSlabStreK.Add(LcomK);
			rMlcbD.aShellStreK.Add(LcomK);
		}
		else if(LcomD_UL.nActive == 2)
		{
            switch (enServLcom)
            {
            case EN_SERV_LCOM::GENERAL:
			{
				if (!IsLCombWithWind(LcomD) && !IsLCombWithEQ(LcomD))
				{
					rMlcbD.aSlabServK.Add(LcomK);

					if (IsStaticLCComb(LcomD))
						rMlcbD.aSlabCracK.Add(LcomK);
				}
			}
            break;
            case EN_SERV_LCOM::SUBLCOM:
			{
				if (LcomD_UL.nServLcomType == 1 || LcomD_UL.nServLcomType == 2 || LcomD_UL.nServLcomType == 3)
					rMlcbD.aSlabServK.Add(LcomK);

				if (IsStaticLCComb(LcomD) && LcomD_UL.nServLcomType == 1)
					rMlcbD.aSlabCracK.Add(LcomK);
			}
			break;
			case EN_SERV_LCOM::ALL_SERV:
			{
				rMlcbD.aSlabServK.Add(LcomK);
				rMlcbD.aSlabCracK.Add(LcomK);
			}
			break;
            default:
			{
				ASSERT(0);
			}
			break;
            }			
		}

		// [2009-09-24] Kim, Geun Young (Tel: 2042, gykim@midasit.com)
		// Default를 모든 하중 조합으로 변경.
		/*    
		BOOL bAdd = FALSE;
		int nBaseSize = LcomD_UL.Combination.GetSize();
		for(int k = 0; k < nBaseSize; k++)
		{
		T_LCOM_BASE LcomBase = LcomD_UL.Combination[k];
		if(LcomBase.AnalType != D_LCOM_STATIC)      {   bAdd = FALSE;     break;    }

		T_STLD_D StldD; StldD.Initialize();
		if(!GetStld(LcomBase.LoadCaseKey, StldD)) {ASSERT(0); continue;}
		BOOL bLongTypeLc = (CDBLib::IsStldDL(StldD.LoadCaseType) ||
		StldD.LoadCaseType=="L"              ||
		StldD.LoadCaseType=="LR"             ||
		CDBLib::IsStldTL(StldD.LoadCaseType) ? TRUE : FALSE);
		if(!bLongTypeLc)    {   bAdd = FALSE;     break;    }

		// 온도하중만 존재하는 경우를 판단하기 위해
		if(!CDBLib::IsStldTL(StldD.LoadCaseType)) bAdd = TRUE;
		}    
		if(bAdd && LcomD_UL.nActive == 1)      rMlcbD.aSlabStreK.Add(LcomK);
		else if(bAdd && LcomD_UL.nActive == 2) rMlcbD.aSlabServK.Add(LcomK);
		*/
	}

	return TRUE;
}

