void CAttrCtrl::GetRsdmKeyList(CArray<T_RSDM_K, T_RSDM_K>& rKeyList)
{
	rKeyList.RemoveAll();

	T_RSDM_K Key;
	T_RSDM_D Data;
	POSITION pos=GetStartRsdm();
	while(pos != NULL)
	{
		GetNextRsdm(pos, Key, Data);
		rKeyList.Add(Key);
	}
	//if(rKeyList.GetSize()>0) CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

void CAttrCtrl::GetRsdmKeyList(int nOType,CArray<T_RSDM_K, T_RSDM_K>& rKeyList)
{
	rKeyList.RemoveAll();

	CArray<T_RSDM_K, T_RSDM_K> aKey;
	CArray<T_POS_INT_PAIR, T_POS_INT_PAIR&> aPair;
	T_POS_INT_PAIR pair;
	int i=0;

	T_RSDM_K Key;
	T_RSDM_D Data;
	POSITION pos=GetStartRsdm();
	while(pos)
	{
		GetNextRsdm(pos, Key, Data);
		if(Key.key.OType!=nOType) continue;
		pair.nPos = i++;
		pair.nVal = Key.key.OKey;
		aPair.Add(pair);
		aKey.Add(Key);
	}
	int nSize = aPair.GetSize();
	if(nSize>0)
	{
		qsort((void*)aPair.GetData(), nSize, sizeof(T_POS_INT_PAIR), CCompFunc::ComparePosIntPairA);

		rKeyList.SetSize(nSize);
		for(int i=0; i<nSize; ++i)
		{
			rKeyList[i] = aKey[aPair[i].nPos];
		}
	}
}

