void CAttrCtrl::GetRsdlKeyListHasElem(T_ELEM_K ElemKey, CArray<T_RSDL_K, T_RSDL_K>& rKeyList) // Elem 을 가진 RSDL
{
	rKeyList.RemoveAll();

	ElemList* pList;
	VERIFY(m_pDataMemb->m_elem.GetList(ElemKey, pList));
	T_LIST_DATA ListData;
	POSITION pos = pList->GetHeadPosition();
	while (pos)
	{
		ListData = pList->GetNext(pos);
		if (ListData.nCmd == LT_RSDL_CMD) rKeyList.Add(ListData.nKey);
	}
}

