int CAttrCtrl::GetSmspList(CArray<T_SMSP_K, T_SMSP_K>& raKey, CArray<T_SMSP_D, T_SMSP_D&>& raData)
{
	GetSmspKeyList(raKey);
	int nSize = raKey.GetSize();
	raData.SetSize(nSize);
	for (int i = 0; i < nSize; i++)
		GetSmsp(raKey[i], raData[i]);
	return nSize;
}

