BOOL CAttrCtrl::IsSmsp(T_ELEM_K Key)
{
	T_ELEM_D ElemD;

	GetElem(Key, ElemD);
	if(!IsFrameType(ElemD.eltyp))
		return FALSE;

	int nDesignType = m_pDoc->m_pAttrCtrl2->GetElemDesignType(ElemD);

	if(nDesignType != 1) //steel인 요소들만
		return FALSE;

	T_SECT_K SectK = ElemD.elpro; // sect or thik
	if(!IsSmspWithSectShape(SectK))
		return FALSE;

	return TRUE;
}

BOOL CAttrCtrl::IsSmspWithSectShape(T_SECT_K rKey)
{
	T_SECT_D SectD;

	GetSect(rKey, SectD);

	return (SectD.SectBefore.Shape == D_SECT_SHAPE_REG_SR || SectD.SectBefore.Shape == D_SECT_SHAPE_REG_P);
}

