void CAttrCtrl::CalcPsllLoad(T_PSLL_D& rData, CArray<T_SEISLOAD, T_SEISLOAD&>& arPsllLoad, BOOL bCalcMassCenter)
{
	arPsllLoad.RemoveAll();
	if(GetCountStor() == 0)return;

	T_SEISLOAD PsllLoad;
	T_STOR_D DataStor;
	CLateralLoad LateralLoad;
	CArray<T_STOR_K, T_STOR_K>StorKeyList;
	if(bCalcMassCenter)
	{
		GetStorKeyList(StorKeyList);
		BOOL bUseBedrockLevel=TRUE;
		LateralLoad.Calc_DiaphramCenter(bUseBedrockLevel);
	}
	LateralLoad.MakePseudoSeismicForce(rData);
	int nStory=LateralLoad.m_aSeisLoad_X.GetSize();
	ASSERT(nStory == LateralLoad.m_aSeisLoad_Y.GetSize());
	for(int i=0; i<nStory; i++)
	{
		T_STOR_K KeyStor=LateralLoad.m_aSeisLoad_X[i].KeyStory;
		ASSERT(KeyStor == LateralLoad.m_aSeisLoad_Y[i].KeyStory);
		if(KeyStor == 0)continue;
		GetStor(KeyStor, DataStor);
		PsllLoad.Initialize();
		PsllLoad.KeyStor=KeyStor;
		PsllLoad.dPosition_X=0.;
		PsllLoad.dPosition_Y=0.;
		if(bCalcMassCenter)
		{
			BOOL bGetCenter=FALSE;
			for(int j=0; j<StorKeyList.GetSize(); j++)
			{
				if(KeyStor == StorKeyList[j])
				{
					PsllLoad.dPosition_X=LateralLoad.m_aDiaphramCenter[j].DiaphCnt_x;
					PsllLoad.dPosition_Y=LateralLoad.m_aDiaphramCenter[j].DiaphCnt_y;
					bGetCenter=TRUE;
					break;
				}
			}
			if(!bGetCenter)ASSERT(FALSE);
		}
		PsllLoad.dSeis_X=LateralLoad.m_aSeisLoad_X[i].dSeisLoad;
		PsllLoad.dSeis_Y=LateralLoad.m_aSeisLoad_Y[i].dSeisLoad;
		PsllLoad.dSeis_RZ=0.0;
		int nAddSize = rData.arAddition.GetSize();
		for(int k = 0; k < nAddSize; k++)                           // PMS:4183-HTLEE-20100525 Additional Load RZ 고려 
		{
			if(KeyStor == rData.arAddition[k].KeyStor)
			{
				PsllLoad.dSeis_RZ += rData.arAddition[k].AddR;
				break;
			}
		}
		if(PsllLoad.dSeis_X != 0. || PsllLoad.dSeis_Y != 0. || PsllLoad.dSeis_RZ != 0.) arPsllLoad.Add(PsllLoad);    
	}
}

void CAttrCtrl::CalcPsllLcom(BOOL bAllLoadCase, T_LCOM_D& DataLcom, CArray<T_SEISLOAD, T_SEISLOAD&>& arPsllLoad)
{
	arPsllLoad.RemoveAll();  
	if(GetCountStor() == 0)return;
	if(GetCountPsll() == 0)return;

	T_SEISLOAD PsllLoad;
	T_STOR_K KeyStor;
	T_STOR_D DataStor;
	CLateralLoad LateralLoad;

	CArray<T_NMAS_UDRD_D, T_NMAS_UDRD_D&> arNmasData_allMass;
	m_pDoc->calcAllMass(arNmasData_allMass);
	LateralLoad.Calc_DiaphramCenter(arNmasData_allMass);

	POSITION pos;
	T_PSLL_K KeyPsll;
	T_PSLL_D DataPsll;
	CMap<T_STOR_K, T_STOR_K, T_SEISLOAD, T_SEISLOAD&> mapPsllLoad;
	mapPsllLoad.InitHashTable(HASHSIZESTLD);

	CArray<T_STOR_K, T_STOR_K>StorKeyList;
	GetStorKeyList(StorKeyList);
	pos=GetStartPsll();
	while(pos != NULL)
	{
		GetNextPsll(pos, KeyPsll, DataPsll);
		double dFactor=1.;
		if(bAllLoadCase)
		{
		}
		else
		{
			double dStldFactor=0., dStagFactor=0.;
			if(!GetLcomStldFactor(KeyPsll, DataLcom, dStldFactor, dStagFactor))return;  
			if(dStldFactor == 0.)continue;
			dFactor=dStldFactor;
		}

		LateralLoad.MakePseudoSeismicForce(DataPsll, FALSE, _T(""), FALSE, FALSE, arNmasData_allMass);

		int nStory=LateralLoad.m_aSeisLoad_X.GetSize();
		ASSERT(nStory == LateralLoad.m_aSeisLoad_Y.GetSize());
		for(int i=0; i<nStory; i++)
		{
			KeyStor=LateralLoad.m_aSeisLoad_X[i].KeyStory;
			ASSERT(KeyStor == LateralLoad.m_aSeisLoad_Y[i].KeyStory);
			if(KeyStor == 0)continue;
			GetStor(KeyStor, DataStor);
			PsllLoad.Initialize();
			PsllLoad.KeyStor=KeyStor;
			PsllLoad.dPosition_X=0.;
			PsllLoad.dPosition_Y=0.;
			BOOL bGetCenter=FALSE;
			for(int j=0; j<StorKeyList.GetSize(); j++)
			{
				if(KeyStor == StorKeyList[j])
				{
					PsllLoad.dPosition_X=LateralLoad.m_aDiaphramCenter[j].DiaphCnt_x;
					PsllLoad.dPosition_Y=LateralLoad.m_aDiaphramCenter[j].DiaphCnt_y;
					bGetCenter=TRUE;
					break;
				}
			}
			if(!bGetCenter)ASSERT(FALSE);
			PsllLoad.dSeis_X=LateralLoad.m_aSeisLoad_X[i].dSeisLoad*dFactor;
			PsllLoad.dSeis_Y=LateralLoad.m_aSeisLoad_Y[i].dSeisLoad*dFactor;
			PsllLoad.dSeis_RZ=0.0;
			int nAddSize = DataPsll.arAddition.GetSize();
			for(int k = 0; k < nAddSize; k++)                           // PMS:4183-HTLEE-20100525 Additional Load RZ 고려 
			{
				if(KeyStor == DataPsll.arAddition[k].KeyStor)
				{
					PsllLoad.dSeis_RZ += DataPsll.arAddition[k].AddR;
					break;
				}
			}

			if(PsllLoad.dSeis_X != 0. || PsllLoad.dSeis_Y != 0. || PsllLoad.dSeis_RZ != 0.)
			{
				T_SEISLOAD SeisLoadOld;
				if(mapPsllLoad.Lookup(KeyStor,SeisLoadOld))
				{
					PsllLoad.dSeis_X+=SeisLoadOld.dSeis_X;
					PsllLoad.dSeis_Y+=SeisLoadOld.dSeis_Y;
					PsllLoad.dSeis_RZ+=SeisLoadOld.dSeis_RZ;
				}
				mapPsllLoad.SetAt(KeyStor,PsllLoad);
			}
		}
	}
	for(int i=0; i<StorKeyList.GetSize(); i++)
	{
		if(mapPsllLoad.Lookup(StorKeyList[i],PsllLoad)) arPsllLoad.Add(PsllLoad);
	}
}

void CAttrCtrl::GetPsllKeyList(CArray<T_PSLL_K, T_PSLL_K>& rKeyList)
{
	rKeyList.RemoveAll();

	POSITION pos;
	T_PSLL_K Key;
	T_PSLL_D Data;
	pos=GetStartPsll();
	while(pos != NULL)
	{
		GetNextPsll(pos, Key, Data);
		rKeyList.Add(Key);
	}
	if(rKeyList.GetSize() > 0)CQSort::QSortUInt(rKeyList.GetData(), rKeyList.GetSize());
}

