BOOL CAttrCtrl::GetSeew_default(T_SEEW_K Key,T_SEEW_D& rData)
{
	if(GetSeew(Key, rData))
		return TRUE;

	T_STOR_D StorD;
	if(!GetStor(Key,StorD))
		return FALSE;

	rData.dWeight    = M_InitValueCurUnit(10.0, KN, M, D_UNITSYS_BASE_ELAST);
	rData.dFloorArea = StorD.WindWidthX * StorD.WindWidthY;
	return TRUE;
}

