double CAttrCtrl::GetRsmf_C(T_RSMF_K Key)
{
	// 최대 비탄성변위와 선형탄성변위의 보정을 위한 수정계수 (내진성능평가)
	if (GetCountRsmf() == 0) return 1.0;

	T_RSMF_D Data;
	if(GetRsmf(Key, Data)) return Data.dC;
	return GetDefaultC4Rsmf();
}

double CAttrCtrl::GetDefaultC4Rsmf()
{
	// Evaluation Method (평가방법 선택 및 설정) 대화상자의 System 설정 및 층정보에 따른 Default 값 제공
	// 표 4.2.1 최대 비탄성변위와 선형탄성변위의 보정을 위한 수정계수 C 참고
	T_SEME_D SemeD;
	m_pDoc->m_pAttrCtrl2->GetSeme(SemeD);
	int nStorCnt = GetCountStor() - 1;

	if( SemeD.data.eval.nResistSystem == D_SEME_RESIST_RC_MFRAME)
	{
		if(nStorCnt==1)       return 1.3;
		else if(nStorCnt==2)  return 1.1;
		else if(nStorCnt==3)  return 1.0;
		else if(nStorCnt>3)   return 1.0;
	}
	else if( SemeD.data.eval.nResistSystem == D_SEME_RESIST_RC_WALL)
	{
		if(nStorCnt==1)       return 1.4;
		else if(nStorCnt==2)  return 1.2;
		else if(nStorCnt==3)  return 1.1;
		else if(nStorCnt>3)   return 1.0;
	}

	// 층이 없는 경우도 1.0
	return 1.0;
}

