// 데이터 없는 경우 Data에 기본값 채움
BOOL CAttrCtrl::GetLfcaDefault(T_LFCA_K Key,T_LFCA_D& rData)
{
	if(GetLfca(Key,rData))
		return TRUE;

	// C
	// Default : 1단계 상세평가 Pseudo Seismic Force, RS Define Modification Factor에서 입력한 C 값
	// 1단계 상세평가 Pseudo Seismic Force, RS Load Case에서 입력하지 않은 경우 Default : 1.0
	if(Key.key.type==D_LFCA_TYPE_PSLL)
	{
		T_PSLL_D PsllD;
		if(GetPsll(Key.key.objK, PsllD))
		{
			switch(PsllD.nCodeType)
			{
			case D_SEME_METHOD_KISTEC2013:
				rData.dC = PsllD.code.KISTEC2013.dC;
				break;
			case D_SEME_METHOD_MOE2018:
			case D_SEME_METHOD_MOE2019:
				rData.dC = PsllD.code.Moe2018.dC;
				break;
			case D_SEME_METHOD_KISTEC2019:
				rData.dC = PsllD.code.KISTEC2019.dC;
				break;
			}
		}
	}
	else
	{
		rData.dC = GetRsmf_C(Key.key.objK);
	}

	// J
	// Evaluation Method (평가방법 선택 및 설정) 대화상자의 Seismic Zone 설정에 따른 Default 값 제공
	// 1인 경우 : 2.0
	// 2인 경우 : 1.5
	T_SEME_D SemeD;
	m_pDoc->m_pAttrCtrl2->GetSeme(SemeD);
	rData.dJ = SemeD.data.eval.nSeismicZone==D_SEME_ZONE_1 ? 2.0 : 1.5;

	return TRUE;
}

