BOOL CAttrCtrl::IsNodeOnWallLine(T_NODE_K KeyNode)
{
	BOOL bIsNodeOnWallLine=FALSE;
	if(CTempDataStore_IsNodeOnWallLine::GetInstance()->Get(KeyNode, bIsNodeOnWallLine))
		return bIsNodeOnWallLine;

	CArray<T_ELEM_K,T_ELEM_K> aElemK;
	GetElemKeyList(aElemK);
	for(int i=0; i<aElemK.GetSize(); i++)
	{
		T_ELEM_D ElemD;
		GetElem(aElemK[i], ElemD);
		if (!IsWall(ElemD.eltyp)) continue;

        auto L_isTargetNodeBetweenIAndJ= [&](T_NODE_K NodeK_I, T_NODE_K NodeK_J, T_NODE_K NodeK_Target) -> BOOL
		{
			T_NODE_D NodeD_I, NodeD_J, NodeD_T;
			GetNode(NodeK_I, NodeD_I);
			GetNode(NodeK_J, NodeD_J);
            GetNode(NodeK_Target, NodeD_T);

            double dMaxX = __max(NodeD_I.x, NodeD_J.x);
            double dMaxY = __max(NodeD_I.y, NodeD_J.y);
            double dMaxZ = __max(NodeD_I.z, NodeD_J.z);
            double dMinX = __min(NodeD_I.x, NodeD_J.x);
            double dMinY = __min(NodeD_I.y, NodeD_J.y);
            double dMinZ = __min(NodeD_I.z, NodeD_J.z);

            const double dTol = m_pDoc->m_pFlagCtrl->GetGeneralCoordinateToleranceCurrentUnit();
            if (NodeD_T.x > dMaxX+dTol) return false;
            if (NodeD_T.y > dMaxY+dTol) return false;
            if (NodeD_T.z > dMaxZ+dTol) return false;
            if (NodeD_T.x < dMinX-dTol) return false;
            if (NodeD_T.y < dMinY-dTol) return false;
            if (NodeD_T.z < dMinZ-dTol) return false;

            double dNodeI[3] = { NodeD_I.x, NodeD_I.y, NodeD_I.z };
            double dNodeJ[3] = { NodeD_J.x, NodeD_J.y, NodeD_J.z };
            double dNodeT[3] = { NodeD_T.x, NodeD_T.y, NodeD_T.z };
            double dDist = math_lib::distance_segment_point_3d(dNodeI, dNodeJ, dNodeT);
            if (fabs(dDist) < dTol) return true;
            
            return false;
		};

		T_NODE_K NodeK_lower[2], NodeK_upper[2];
		NodeK_lower[0] = ElemD.elnod[0];
		NodeK_lower[1] = ElemD.elnod[1];
		NodeK_upper[0] = ElemD.elnod[2];
		NodeK_upper[1] = ElemD.elnod[3];

		if(L_isTargetNodeBetweenIAndJ(NodeK_lower[0],NodeK_lower[1],KeyNode) || L_isTargetNodeBetweenIAndJ(NodeK_upper[0],NodeK_upper[1],KeyNode))
		{
			bIsNodeOnWallLine=TRUE;
			break;
		}
	}

	CTempDataStore_IsNodeOnWallLine::GetInstance()->Set(KeyNode, bIsNodeOnWallLine);
	return bIsNodeOnWallLine;
}

BOOL CAttrCtrl::IsThis_Nonlinear_DiSt(const T_THIS_D& ThisD)
{
	return ThisD.nAnalType==2 && (ThisD.nAnalMethod==2 || ThisD.nAnalMethod==3);
}

BOOL CAttrCtrl::GetThgcInitLoadThis(T_THIS_D& rData)
{
	rData.Initialize();

	T_THGC_D ThgcD;
	m_pDoc->m_pAttrCtrl2->GetThgc(ThgcD);
	if(m_pDoc->m_pAttrCtrl2->HasThgcDummyInitLoad()==FALSE) return FALSE;
	if(ThgcD.ThisK_DummyInitLoad==0)  return FALSE;

	BOOL bReturn=m_pDataMemb->m_this.Get(ThgcD.ThisK_DummyInitLoad,rData);
	if(bReturn)m_pUnitCtrl->ConvertUnitThisOut(rData);
	if(!bReturn) return FALSE;

	rData.LoadCaseName = _LS(IDS_DB_THIS_THGC_INITLOAD);
	rData.nIncrementStep = ThgcD.nIncrementStep;
	rData.nOut           = ThgcD.nIncrResult==D_THGC_INC_OUTPUT_FINAL_STEP? ThgcD.nIncrementStep : ThgcD.nIncrResultUserInputStep;
	rData.nGeomNonlinearType = ThgcD.nGeomNonlinearType;
	rData.BoundaryNL_Old.bPermitConvergence = ThgcD.bPermitFail;
	rData.BoundaryNL_Old.nMaxIterNum    = ThgcD.nMaxIterNum;
	rData.BoundaryNL_Old.nMaxNumSubStep = ThgcD.nSubstep;
	rData.BoundaryNL_Old.bDispNorm   = ThgcD.bDisplNorm;
	rData.BoundaryNL_Old.bForceNorm  = ThgcD.bForceNorm;
	rData.BoundaryNL_Old.bEnergyNorm = ThgcD.bEnergyNorm;
	rData.BoundaryNL_Old.dDispNorm   = ThgcD.dDisplNorm;
	rData.BoundaryNL_Old.dForceNorm  = ThgcD.dForceNorm;
	rData.BoundaryNL_Old.dEnergyNorm = ThgcD.dEnergyNorm;
	rData.BoundaryNL_Old.bUseLineSearch = ThgcD.bUseLineSearch;
	rData.BoundaryNL_Old.nNumSearch     = ThgcD.nNumSearch;

	return TRUE;
}

