double CAttrCtrl::GetStrengthCoef(double dC0, T_MHTP_D& MhtpD)
{
	double dEta_sT = 0.0;
	if (MhtpD.nMatlType == 1)
		dEta_sT = MhtpD.nStlType==1 ? GetStructureStlStrengthCoef(dC0) : GetFireStlStrengthCoef(dC0);
	else
	{
		double dValuemin = 1e6;
		int nCount = MhtpD.aFuncData.GetCount();
		int nIndes = -1;
		for (int i=1; i<nCount; i++)
		{
			if (MhtpD.aFuncData[i].nC0-dC0 > 0 && MhtpD.aFuncData[i-1].nC0-dC0 < 0)
				nIndes = i;
			else
				continue;
			dEta_sT = MhtpD.aFuncData[i-1].dComp + (MhtpD.aFuncData[i].dComp-MhtpD.aFuncData[i-1].dComp)/(MhtpD.aFuncData[i].nC0-MhtpD.aFuncData[i-1].nC0)* (dC0-MhtpD.aFuncData[i-1].nC0);
			dEta_sT *= MhtpD.dScaleFactor;
		}

	}
	return dEta_sT;
}

double CAttrCtrl::GetElastCoef(double dC0, T_MHTP_D& MhtpD)
{
	double dX_sT = 0.0;
	if (MhtpD.nMatlType == 1)
		dX_sT = MhtpD.nStlType==1 ? GetStructureStlElastCoef(dC0) : GetFireStlElastCoef(dC0);
	else
	{
		double dValuemin = 1e6;
		int nCount = MhtpD.aFuncData.GetCount();
		int nIndes = -1;
		for (int i=1; i<nCount; i++)
		{
			if (MhtpD.aFuncData[i].nC0-dC0 > 0 && MhtpD.aFuncData[i-1].nC0-dC0 < 0)
				nIndes = i;
			else
				continue;
			dX_sT = MhtpD.aFuncData[i-1].dElast + (MhtpD.aFuncData[i].dElast-MhtpD.aFuncData[i-1].dElast)/(MhtpD.aFuncData[i].nC0-MhtpD.aFuncData[i-1].nC0)* (dC0-MhtpD.aFuncData[i-1].nC0);
			dX_sT *= MhtpD.dScaleFactor;
		}

	}
	return dX_sT;
}

double CAttrCtrl::GetStructureStlStrengthCoef(double dC0)
{
	double dEta_sT = 0.0;
	if (dC0>=0 && dC0<=300)
		dEta_sT = 1.0;
	else if (dC0>300 && dC0<800)
		dEta_sT = 1.24*1.0e-8*pow(dC0,3) - 2.096*1.0e-5*pow(dC0,2) + 9.228*1.0e-3*dC0 - 0.2168;
	else if (dC0 <= 1000)
		dEta_sT = 0.5 - dC0/2000;

	return dEta_sT;
}

double CAttrCtrl::GetStructureStlElastCoef(double dC0)
{
	double dX_sT = 0.0;
	if (dC0>=0 && dC0<20)
		dX_sT = 1.0;
	else if (dC0>=20 && dC0<600)
		dX_sT = (7*dC0-4780)/(6*dC0-4760);
	else if (dC0>=600 && dC0<=1000)
		dX_sT = (1000-dC0)/(6*dC0-2800);

	return dX_sT;
}

double CAttrCtrl::GetFireStlStrengthCoef(double dC0)
{
	double dEta_sT = 0.0;
	if (dC0>=0 && dC0<20)
		dEta_sT = 1.0;
	else if (dC0>=20 && dC0<700)
		dEta_sT = 6*(dC0-768)/(5*(dC0-918));
	else if (dC0>=700 && dC0<=1000)
		dEta_sT = (1000-dC0)/(8*(dC0-600));

	return dEta_sT;
}

double CAttrCtrl::GetFireStlElastCoef(double dC0)
{
	double dX_sT = 0.0;
	if (dC0>=0 && dC0<20)
		dX_sT = 1.0;
	else if (dC0>=20 && dC0<650)
		dX_sT = 1-(dC0-20)/2520;
	else if (dC0>=650 && dC0<900)
		dX_sT = 0.75-7*(dC0-650)/2500;
	else if (dC0>=900 && dC0<=1000)
		dX_sT = 0.5-0.0005*dC0;
	return dX_sT;
}


