BOOL CAttrCtrl::CheckHingeResultExists(T_ELEM_K ElemK)
{
	T_THGC_D ThgcD;
	m_pDoc->m_pAttrCtrl2->GetThgc(ThgcD);

	switch(ThgcD.nHingeOutput)
	{
	// 힌지가 존재하면 모두 출력
	case D_THGC_OUTPUT_OPT_ALL: return ExistIehg(MakeElemIehgK(ElemK));

	// Siho 입력되어 있으면 출력
	case D_THGC_OUTPUT_OPT_SEL: return ExistIehg(MakeElemIehgK(ElemK)) && ExistSiho(ElemK);

	// max min 외 개별힌지값은 출력 안 함
	case D_THGC_OUTPUT_OPT_MAXMIN: return FALSE; 
	}
	ASSERT(0);
	return FALSE;
}

BOOL CAttrCtrl::CheckFiberResultExists(T_ELEM_K ElemK)
{
	T_THGC_D ThgcD;
	m_pDoc->m_pAttrCtrl2->GetThgc(ThgcD);

	switch(ThgcD.nHingeOutput)
	{
		// 힌지가 존재하면 모두 출력
	case D_THGC_OUTPUT_OPT_ALL: 
		{
			if(ThgcD.nFiberOutput == D_THGC_OUTPUT_OPT_SEL)
			{
				T_SIHO_D SihoD;
				GetSiho(ElemK, SihoD);
				return ExistIehg(MakeElemIehgK(ElemK)) && SihoD.bFiberResult;
			}
			else
			{
				return ExistIehg(MakeElemIehgK(ElemK));
			}
		}

		// Siho 입력되어 있으면 출력
	case D_THGC_OUTPUT_OPT_SEL: 
		{
			T_SIHO_D SihoD;
			GetSiho(ElemK, SihoD);
			return ExistIehg(MakeElemIehgK(ElemK)) && SihoD.bFiberResult;
		}

		// max min 외 개별힌지값은 출력 안 함
	case D_THGC_OUTPUT_OPT_MAXMIN: return FALSE; 
	}
	ASSERT(0);
	return FALSE;
}

