T_RFST_K CAttrCtrl::GetLastNumRfst()
{
	return m_pDataMemb->m_pRfst->m_nLastNum;
}

T_RFST_K CAttrCtrl::GetStartNumRfst()
{
	return m_pDataMemb->m_pRfst->m_nStartNum;
}

T_RFST_K CAttrCtrl::GetNextNumRfst(T_RFST_K StartNum)
{
	if(StartNum > GetLastNumRfst())return StartNum;
	T_RFST_K Key = StartNum;
	T_RFST_D Data;
	while(TRUE)
	{
		Key++;
		if(!m_pDataMemb->m_pRfst->Get(Key, Data))
		{
			if(Key < D_SECT_MINNUM || Key > D_SECT_MAXNUM)
				return GetStartNumRfst();
			else
				return Key;
		}
	}
}

T_RFST_K CAttrCtrl::GetLastNumRfstUnused()
{
	T_RFST_K KeyLast = m_pDataMemb->m_pRfst->m_nLastNum;
	while(TRUE)
	{
		if(!IsUsedRfst(KeyLast) && !ExistRfst(KeyLast))
		{
			if(KeyLast < D_SECT_MINNUM || KeyLast > D_SECT_MAXNUM)
				return GetStartNumRfstUnused();
			else
				return KeyLast;
		}
		KeyLast++;
	}
}

T_RFST_K CAttrCtrl::GetStartNumRfstUnused()
{
	T_RFST_K KeyStart = m_pDataMemb->m_pRfst->m_nStartNum;
	while(TRUE)
	{
		if(!IsUsedRfst(KeyStart) && !ExistRfst(KeyStart))return KeyStart;
		KeyStart++;
	}
}

T_RFST_K CAttrCtrl::GetNextNumRfstUnused(T_RFST_K StartNum)
{
	if(StartNum > GetLastNumRfstUnused())return StartNum;
	T_RFST_K KeyNext = StartNum + 1;
	while(TRUE)
	{
		if(!IsUsedRfst(KeyNext) && !ExistRfst(KeyNext))return KeyNext;
		KeyNext++;
	}
}

void CAttrCtrl::GetKeyListRfstUser(CArray<T_RFST_K, T_RFST_K>* pKeyRfst, CArray<T_NODE_K, T_NODE_K>* pKeyNode /*= NULL*/, CArray<T_ELEM_K, T_ELEM_K>* pKeyElem /*= NULL*/)
{
	if (pKeyNode != NULL)pKeyNode->RemoveAll();
	if (pKeyElem != NULL)pKeyElem->RemoveAll();
	if (pKeyNode == NULL && pKeyElem == NULL)return;
	if (pKeyRfst == NULL)
	{
		ASSERT(0); return;
	}
	int nCount = pKeyRfst->GetSize();
	if (nCount == 0)return;

	CMap<T_ELEM_K, T_ELEM_K, T_ELEM_K, T_ELEM_K>KeyElemMap;
	KeyElemMap.InitHashTable(m_pDoc->GetHashSizeElem());

	POSITION pos;
	T_ARST_K KeyArst;
	T_ARST_D DataArst;

	pos = GetStartArst();
	while (pos != NULL)
	{
		GetNextArst(pos, KeyArst, DataArst);
		for (int i = 0; i < nCount; i++)
		{
			if (DataArst.ReinforceSectKey == pKeyRfst->GetAt(i))
			{
				KeyElemMap.SetAt(KeyArst, KeyArst);
			}
		}
	}
	GetKeyListNodeElem(KeyElemMap, pKeyNode, pKeyElem);
}

bool CAttrCtrl::InsertPlateDeckElem(const std::map<double, PC_GIRDER_VEC_PLATE_DECK>& mapPlateDeck, const unsigned int matlKey, const double thickness, const CString& grupName) const
{
	// thickness <= 0 -> false
	// Node 좌표가 나누어 떨어지게 하기 위해 현재 단위계에 따라 톨러런스를 다르게 줌
	T_UNIT_INDEX CurIndex;
	m_pDoc->m_pUnitCtrl->GetUnitIndexCurrent(CurIndex);
	CString strUnitLen;
	double dMergeTol = 0.0;
	if (CurIndex.nBase_Length == D_UNITSYS_LENGTH_INDEX_IN || CurIndex.nBase_Length == D_UNITSYS_LENGTH_INDEX_FT)
	{
		dMergeTol = M_InitValueCurUnit(1.e-3/*PC_GIRDER_MERGE_TOR*/, KIP, IN, D_UNITSYS_BASE_LENGTH);
	}
	else
	{
		dMergeTol = M_InitValueCurUnit(1.e-3/*PC_GIRDER_MERGE_TOR*/, N, M, D_UNITSYS_BASE_LENGTH);
	}

	//////////////////////////////////////////////////////////////////////////
	// GetPlateDeckAll
	std::vector<double> aStation;
	std::vector<PC_GIRDER_VEC_UINT> aVecPlateDeckNodeK;
	std::vector<PC_GIRDER_VEC_DBL>  aVecStationEachNode;

	std::vector<T_NODE_K> aGirderNodeK;
	std::vector<T_NODE_K> aPlateDeckNodeK;

	aStation.resize(mapPlateDeck.size());
	aVecPlateDeckNodeK.resize(mapPlateDeck.size());
	aVecStationEachNode.resize(mapPlateDeck.size());
	for (int i = 0; i < mapPlateDeck.size(); i++)
	{
		aVecPlateDeckNodeK[i].aUi.clear();
		aVecStationEachNode[i].aDbl.clear();
	}

	int nCnt = 0;
	for (auto itrMap = mapPlateDeck.begin(); itrMap != mapPlateDeck.end(); itrMap++)
	{
		PC_GIRDER_VEC_PLATE_DECK PlateDeck = itrMap->second;

		aStation[nCnt] = PlateDeck.Station;
		ASSERT(itrMap->first == PlateDeck.Station);

		for (int j = 0; j < PlateDeck.aPoint3dDistSort.size(); j++)
		{
			PlateDeck.aPoint3dDistSort[j].RefPnt = PlateDeck.aPoint3dDistSort[j].pos;
			PlateDeck.aPoint3dDistSort[j].nType  = 0;
			PlateDeck.aPoint3dDistSort[j].NodeK  = GetOrAddNodeToPlateDeckDB(PlateDeck.aPoint3dDistSort[j].pos, dMergeTol);
			PlateDeck.aPoint3dDistSort[j].dStationEachNode = 0.;

			aVecPlateDeckNodeK[nCnt].aUi.push_back(PlateDeck.aPoint3dDistSort[j].NodeK);
			aVecStationEachNode[nCnt].aDbl.push_back(PlateDeck.aPoint3dDistSort[j].dStationEachNode);

			if (PlateDeck.aPoint3dDistSort[j].LinkNodeK > 0)
			{
				aGirderNodeK.push_back(PlateDeck.aPoint3dDistSort[j].LinkNodeK);  // master
				aPlateDeckNodeK.push_back(PlateDeck.aPoint3dDistSort[j].NodeK);   // slave
			}
		}
		nCnt++;
	}

	std::map<int, PC_GIRDER_VEC_UINT> mapSpritNoToArElemk;

	std::vector<UINT> aPlateDeckElemK;
	int nElemAddCnt = 0;
	T_ELEM_K ElemKAdded;
	BOOL bCantAdd;
	for (int i = 0; i < (int)aVecPlateDeckNodeK.size() - 1; i++)
	{
		aPlateDeckElemK.clear();
		ASSERT(aVecPlateDeckNodeK[i].aUi.size() == aVecPlateDeckNodeK[i + 1].aUi.size());
		ElemKAdded = -1;
		for (int j = 0; j < (int)aVecPlateDeckNodeK[i].aUi.size() - 1; j++)
		{
			nElemAddCnt = 0;
			bCantAdd = FALSE;

			// Merge된 경우(False가 return 되면 Merge된 경우임)엔 merge된 Node에서 생성된 Elem을 중복적으로 넣어줘야 Elem Get함수에서 재대로 동작한다...Merge가 되면 Skip하면서 counting했다가 제일 최근에 DB에 넣은 ElemK를 Merge된만큼 중복 입력 시킨다.
			while (!AddPlateDeckElem(GetPlateID(), matlKey, GetOrAddPlateDeckThikToDB(thickness),
				aVecPlateDeckNodeK[i].aUi[j + 1], aVecPlateDeckNodeK[i + 1].aUi[j + 1], aVecPlateDeckNodeK[i + 1].aUi[j], aVecPlateDeckNodeK[i].aUi[j], ElemKAdded, 0.0))
			{
				nElemAddCnt++;
				j++;
				if (j >= (int)aVecPlateDeckNodeK[i].aUi.size() - 1)
				{
					bCantAdd = TRUE; // 제일 끝Node의 Merge가 아니면 DB에 들어간 상황도 추가 되므로 +1 이고, 제일 끝 Node의 Merge인 경우엔 이미 puch_back된 ElemKAdded이므로 +1을 안한다.
					if (ElemKAdded == -1)
					{
						ASSERT(false);
						continue; // 한줄이 통채로 안들어갔음
					}
					break;
				}
			}
			if (bCantAdd == FALSE)
			{
				nElemAddCnt++;
			}
			for (int k = 0; k < nElemAddCnt; k++)
			{
				aPlateDeckElemK.push_back(ElemKAdded);
			}

			mapSpritNoToArElemk[-1].aUi.push_back(ElemKAdded); // 한방에 넣음
		}
	}

	//////////////////////////////////////////////////////////////////////////
	// Deck Group
	for (auto itrMap = mapSpritNoToArElemk.begin(); itrMap != mapSpritNoToArElemk.end(); itrMap++)
	{
		std::vector<unsigned int>& aElemK = itrMap->second.aUi;
		AppendPlateDeckElemToGrup(grupName, aElemK);
	}

	//////////////////////////////////////////////////////////////////////////
	// PlateDeck와 Girder를 RigidLink로 연결
	T_NODE_K GirderTopNodeK;
	CString strGrupNameForRigd;  
	strGrupNameForRigd.Format(_LS(IDS_SW_GIRDER_s_RIGID), grupName);
	std::vector<T_NODE_K> aDeckNodeK; aDeckNodeK.resize(1);
	for (int i = 0; i < aPlateDeckNodeK.size(); i++)
	{
		GirderTopNodeK = aGirderNodeK[i];
		aDeckNodeK[0] = aPlateDeckNodeK[i];
		if (!AddPlateDeckRigidLink(GirderTopNodeK, aDeckNodeK, strGrupNameForRigd))
		{
			ASSERT(false);
			return false;
		}
	}

	return true;

}

BOOL CAttrCtrl::AddPlateDeckElem(int eltyp, T_MATL_K MatlK, UINT PropK, T_NODE_K NodeK1, T_NODE_K NodeK2, T_NODE_K NodeK3, T_NODE_K NodeK4, T_ELEM_K& ElemKAdded, double dAngle /*= 0.0*/) const
{
	std::set<T_NODE_K> setNodeK;
	setNodeK.insert(NodeK1);
	setNodeK.insert(NodeK2);
	setNodeK.insert(NodeK3);
	setNodeK.insert(NodeK4);
	if (setNodeK.size() < 3) // Set은 중복될 경우 덮어써 버리기 때문에 집어 넣었을때 size가 작아 지면 중복이 있었단 의미임..
	{
		return FALSE;
	}

	T_ELEM_D ElemD;
	ElemD.Initialize();

	if (setNodeK.size() == 4)
	{
		ElemD.elnod[0] = NodeK1;
		ElemD.elnod[1] = NodeK2;
		ElemD.elnod[2] = NodeK3;
		ElemD.elnod[3] = NodeK4;
	}
	else if (setNodeK.size() == 3)
	{
		// 삼각형 Elem 구성
		T_NODE_K aNodeK[4];
		aNodeK[0] = NodeK1;
		aNodeK[1] = NodeK2;
		aNodeK[2] = NodeK3;
		aNodeK[3] = NodeK4;

		setNodeK.clear();
		int nCnt = 0;
		for (int i = 0; i < 4; i++)
		{
			if (setNodeK.find(aNodeK[i]) == setNodeK.end())
			{
				setNodeK.insert(aNodeK[i]);
				ElemD.elnod[nCnt++] = aNodeK[i];
			}
		}
		ASSERT(nCnt == 4);
	}

// 	T_POINT3D pos1, pos2, pos3, pos4;
// 	pos1 = NodeKToPos(NodeK1);
// 	pos2 = NodeKToPos(NodeK2);
// 	pos3 = NodeKToPos(NodeK3);
// 	pos4 = NodeKToPos(NodeK4);

	ElemD.eltyp = eltyp;
	ElemD.elmat = MatlK;
	ElemD.elpro = PropK;
	ElemD.angle = dAngle; // 각도 반영
	ElemKAdded = m_pDoc->m_pDataCtrl->GetElemKey();
	if (!m_pDoc->m_pEditData->AddElem(ElemKAdded, ElemD, FALSE, TRUE))
	{
		return FALSE;
	}
	return TRUE;
}

T_THIK_K CAttrCtrl::GetOrAddPlateDeckThikToDB(double dThickness) const
{
	// Thickness Key를 찾거나 새로 등록한다.
	T_THIK_K DpanThik = FindThickness(dThickness);
	if (DpanThik != -1)
		return DpanThik;

	T_THIK_K KeyThik, lastThikKey = 0;
	T_THIK_D DataThik;
	CArray<T_THIK_K, T_THIK_K>  aThikKey;
	m_pDoc->m_pAttrCtrl->GetThikKeyList(aThikKey);
	if (aThikKey.GetSize()) lastThikKey = aThikKey[aThikKey.GetSize() - 1];

	DataThik.Initialize();
	DataThik.nType = 0;
	DataThik.Value.nThickType = 0;
	DataThik.Value.ThickIn = dThickness;
	DataThik.Value.ThickOut = 0.;
	KeyThik = 1 + lastThikKey;
	if (!m_pDoc->m_pEditData->AddThik(KeyThik, DataThik)) { ASSERT(0); return FALSE; }

	return KeyThik;
}

BOOL CAttrCtrl::AppendPlateDeckElemToGrup(CString strGrupName, std::vector<T_ELEM_K>& aElemK) const
{
	// hslee : 이거 매번 Appent하지말고 Map에다가 쌓아놨다가 한번에 DB에 넣으면 많이 빨라 질 듯... bracing은 매번 부르기 떄문에 영향이 제법 있을것 같음...
	if (aElemK.size() == 0)
	{
		return TRUE;
	}

	int nCnt;
	std::set<T_NODE_K> setNodeK; // 중복제거용
	T_ELEM_D ElemD;
	for (int i = 0; i < aElemK.size(); i++)
	{
		m_pDoc->m_pAttrCtrl->GetElem(aElemK[i], ElemD);

		nCnt = 0;
		while (ElemD.elnod[nCnt])
		{
			setNodeK.insert(ElemD.elnod[nCnt]);
			nCnt++;
		}
	}

	T_GRUP_D GrupD;
	T_GRUP_K GrupK;
	GrupK = m_pDoc->m_pAttrCtrl->GetGrupKey(strGrupName);
	if (GrupK == 0)
	{
		ASSERT(0);
		return FALSE;
	}
	if (!m_pDoc->m_pAttrCtrl->GetGrup(GrupK, GrupD))
	{
		ASSERT(0);
		return FALSE;
	}

	// SetElem
	CArray<T_ELEM_K, T_ELEM_K> caElemK;
	caElemK.SetSize(aElemK.size());
	for (int i = 0; i < aElemK.size(); i++)
	{
		caElemK[i] = aElemK[i];
	}
	GrupD.arKeyElem.Append(caElemK);

	// SetNode
	for (int i = 0; i < GrupD.arKeyNode.GetSize(); i++)
	{
		setNodeK.insert(GrupD.arKeyNode[i]);
	}
	GrupD.arKeyNode.SetSize(setNodeK.size());
	nCnt = 0;
	for (auto itrSet = setNodeK.begin(); itrSet != setNodeK.end(); itrSet++)
	{
		GrupD.arKeyNode[nCnt++] = *itrSet;
	}

	if (!m_pDoc->m_pEditData->ModifyGrup(GrupK, GrupD))
	{
		ASSERT(0);
		return FALSE;
	}

	return TRUE;
}

BOOL CAttrCtrl::AddPlateDeckRigidLink(T_NODE_K MastNodeK, std::vector<T_NODE_K> aDeckNodeKey, CString strGrupName, BOOL bReplace) const
{
	T_RIGD_K key;
	T_RIGD_D data;
	data.Initialize();
	data.arSlave.RemoveAll();
	for (int i = 0; i < aDeckNodeKey.size(); i++)
	{
		if (aDeckNodeKey[i] != MastNodeK)
		{
			data.arSlave.Add(aDeckNodeKey[i]);
		}
	}

	if (aDeckNodeKey.size() == 1 && MastNodeK == aDeckNodeKey[0])
	{
		return TRUE;
	}

	if (data.arSlave.GetSize() < 1)
	{
		return FALSE;
	}

	// Slave Type : Rigid body
	data.nSlaveType = 111111;

	// Make rigid link key
	data.GroupKey = m_pDoc->m_pAttrCtrl->GetBngrKey(strGrupName);
	m_pDoc->m_pAttrCtrl->MakeKeyRigd(MastNodeK, data.nSlaveType, data.GroupKey, key);
	if (!m_pDoc->m_pEditData->AddRigd(key, data, bReplace)) { ASSERT(0); return FALSE; }

	return TRUE;
}

T_NODE_K CAttrCtrl::GetOrAddNodeToPlateDeckDB(T_POINT3D posNode, double dMergeTol) const
{
	posNode.x = TRUNC_PlateDeck(posNode.x, dMergeTol);
	posNode.y = TRUNC_PlateDeck(posNode.y, dMergeTol);
	posNode.z = TRUNC_PlateDeck(posNode.z, dMergeTol);

	T_NODE_D NodeTempD;
	NodeTempD.x = posNode.x;
	NodeTempD.y = posNode.y;
	NodeTempD.z = posNode.z;

	T_NODE_K NewNodeKey = m_pDoc->m_pDataCtrl->GetNodeKey();
	m_pDoc->m_pEditData->AddNode(NewNodeKey, NodeTempD);

	return NewNodeKey;
}

double CAttrCtrl::TRUNC_PlateDeck(double x, double dMergeTol) const
{
	// 버림한 수와 올림한 수 중 가까운 녀석을 취함.. 이렇게 하면 PC_GIRDER_MERGE_TOR를 기준으로 반올림한 것과 같은 결과가 됨 (미터 기준)
	double dFloor, dUpper;
	dFloor = (double)(floor(x / dMergeTol)) * dMergeTol;
	dUpper = (double)((floor(x / dMergeTol)) + 1) * dMergeTol;

	double dReturnVal = (x - dFloor < dUpper - x) ? dFloor : dUpper;
	return dReturnVal;
}

// 요소 평면의 법선으로부터 투영 평면 선택
static ProjPlane chooseProjectionPlane(const std::vector<T_NODE_D>& vN3) {
	// vN3: 요소 노드들의 3D 좌표
	if (vN3.size() < 3) return ProjPlane::XY;
	// 에지 벡터 두 개로 법선 근사
	double ux = vN3[1].x - vN3[0].x, uy = vN3[1].y - vN3[0].y, uz = vN3[1].z - vN3[0].z;
	double vx = vN3.back().x - vN3[0].x, vy = vN3.back().y - vN3[0].y, vz = vN3.back().z - vN3[0].z;
	double nx = uy * vz - uz * vy;
	double ny = uz * vx - ux * vz;
	double nz = ux * vy - uy * vx;
	double ax = fabs(nx), ay = fabs(ny), az = fabs(nz);
	// 가장 큰 성분을 버리는 투영
	if (az >= ax && az >= ay) return ProjPlane::XY; // Z가 큼 → XY에 투영
	if (ax >= ay && ax >= az) return ProjPlane::YZ; // X가 큼 → YZ에 투영 (x 버림)
	return ProjPlane::XZ;                            // Y가 큼 → XZ에 투영 (y 버림)
}

// 3D → 선택 평면으로 2D 투영
static inline void projectPoint(const T_NODE_D& p, ProjPlane plane, double& u, double& v)
{
	// 항상 ProjPlane::XY
	u = p.x; v = p.y;
	// 	switch (plane) {
	// 	case ProjPlane::XY: u = p.x; v = p.y; break;
	// 	case ProjPlane::XZ: u = p.x; v = p.z; break;
	// 	case ProjPlane::YZ: u = p.y; v = p.z; break;
	// 	}
}

enum class EdgeOwnershipPolicy
{
	RightTop,   // 기본: Edge-2, 3 소유
	LeftBottom  // 폴백: Edge-1, 4 소유
};

static bool processElementPass(
	const ElementD& elem,
	const std::map<int, T_NODE_D>& mapNodes,
	const T_NODE_D& A,    // 선분 AB의 시작점 (3D)
	const T_NODE_D& B,    // 선분 AB의 끝점   (3D)
	ElementPass& outPass,
	EdgeOwnershipPolicy policy,
	double EPS = 1e-10)
{
	const int m = (int)elem.vNodes.size();
	if (m < 3) return false;

	// 요소 노드의 3D 좌표 모음
	std::vector<T_NODE_D> vPoly3;
	vPoly3.reserve(m);
	for (int nid : elem.vNodes) {
		auto it = mapNodes.find(nid);
		if (it == mapNodes.end()) return false;
		vPoly3.push_back(it->second);
	}

	// 투영 평면 선택
	ProjPlane plane = chooseProjectionPlane(vPoly3);

	// 투영 2D 좌표 구성
	std::vector<std::pair<double, double>> vPoly2;
	vPoly2.reserve(m);
	for (const auto& p : vPoly3) {
		double u, v; projectPoint(p, plane, u, v);
		vPoly2.emplace_back(u, v);
	}

	// AB 3D 벡터/길이
	const double rX = B.x - A.x, rY = B.y - A.y, rZ = B.z - A.z;
	const double rLen = norm3(rX, rY, rZ);
	if (rLen < EPS) return false;

	// AB 투영 2D
	double Au, Av, Bu, Bv;
	projectPoint(A, plane, Au, Av);
	projectPoint(B, plane, Bu, Bv);

	struct Hit { double t; int edgeId; double x, y, z; }; // 3D 교차점 저장
	std::vector<Hit> vhits; vhits.reserve(4);

	auto pushUnique = [&](double t, int edgeId, double px, double py, double pz)
	{
		for (auto& h : vhits)
			if (fabs(h.t - t) < 1e-12) return;
		vhits.push_back({ t, edgeId, px, py, pz });
	};

	// 2D: 선분-선분 교차 (파라미터 t는 AB상)
	auto segmentSegmentIntersect2D = [&](double Cx, double Cy, double Dx, double Dy,
		double& t, double& u)->bool
	{
		const double rXu = Bu - Au, rYu = Bv - Av;
		const double sXu = Dx - Cx, sYu = Dy - Cy;
		const double denom = rXu * sYu - rYu * sXu;
		if (fabs(denom) < EPS) return false; // 평행

		const double qpx = Cx - Au, qpy = Cy - Av;
		t = (qpx * sYu - qpy * sXu) / denom;   // AB(투영) 상 파라미터
		u = (qpx * rYu - qpy * rXu) / denom;   // Edge(투영) 상 파라미터
		return (t >= -EPS && t <= 1.0 + EPS && u >= -EPS && u < 1.0 - EPS);
	};

// 	// half-open 규칙: 오른쪽/윗쪽(Edge-2, Edge-3)만 포함
// 	auto keepEdgeOwner = [&](int edgeId)->bool {
// 		return (edgeId == 2 || edgeId == 3);
// 	};

	// 소유권 규칙
	auto keepEdgeOwner = [&](int edgeId)->bool
	{
		switch (policy)
		{
		case EdgeOwnershipPolicy::RightTop:
			// 오른쪽/위쪽 엣지만 소유 (보통 Edge-2/3)
			return (edgeId == 2 || edgeId == 3);
		case EdgeOwnershipPolicy::LeftBottom:
			// 왼쪽/아래쪽 엣지만 소유 (보통 Edge-1/4)
			return (edgeId == 1 || edgeId == 4);
		}
		return true;
	};

	// A/B 내부 판정: 투영 2D에서 다각형 내부 여부
	auto inside2D = [&](double x, double y)->bool {
		return pointInPolygon(x, y, vPoly2);
	};
	const bool Ainside = inside2D(Au, Av);
	const bool Binside = inside2D(Bu, Bv);

	// 각 에지와의 교차/겹침 수집 (투영 2D에서 수행)
	for (int e = 0; e < m; ++e) {
		const int eNext = (e + 1) % m;
		const double Cu = vPoly2[e].first, Cv = vPoly2[e].second;
		const double Du = vPoly2[eNext].first, Dv = vPoly2[eNext].second;

		double t2d, u2d;
		if (segmentSegmentIntersect2D(Cu, Cv, Du, Dv, t2d, u2d)) {
			// t를 [0,1]로 보정
			double tt = t2d;
			if (tt < 0.0) tt = 0.0;
			else if (tt > 1.0) tt = 1.0;

			// 3D 교차점
			const double Px = A.x + rX * tt;
			const double Py = A.y + rY * tt;
			const double Pz = A.z + rZ * tt;
			pushUnique(tt, e + 1, Px, Py, Pz);
			continue;
		}

		// 평행/겹침 케이스: 투영 2D에서 collinear overlap 여부 판단
		if (segCollinearOverlap(Au, Av, Bu, Bv, Cu, Cv, Du, Dv, EPS)) {
			// 에지의 두 끝점 → AB(2D) 파라미터로 투영
			const double rXu = Bu - Au, rYu = Bv - Av;
			const double len2u = rXu * rXu + rYu * rYu;
			auto projT2D = [&](double px, double py) {
				return ((px - Au) * rXu + (py - Av) * rYu) / len2u;
			};
			double tC = projT2D(Cu, Cv), tD = projT2D(Du, Dv);
			double ta = max(0.0, min(tC, tD));
			double tb = min(1.0, max(tC, tD));
			if (tb - ta > 1e-12) {
				if (!keepEdgeOwner(e + 1)) return false; // 반대쪽 요소는 제외
				// 3D 교차점 두 개
				const double Pax = A.x + rX * ta, Pay = A.y + rY * ta, Paz = A.z + rZ * ta;
				const double Pbx = A.x + rX * tb, Pby = A.y + rY * tb, Pbz = A.z + rZ * tb;
				pushUnique(ta, e + 1, Pax, Pay, Paz);
				double tb_adj = std::nextafter(tb, -std::numeric_limits<double>::infinity());
				if (tb_adj > ta + 1e-12) {
					const double Pbx2 = A.x + rX * tb_adj, Pby2 = A.y + rY * tb_adj, Pbz2 = A.z + rZ * tb_adj;
					pushUnique(tb_adj, e + 1, Pbx2, Pby2, Pbz2);
				}
			}
		}
	}

	// A/B가 내부면 t=0/1 키포인트 추가 (3D 좌표 그대로)
	if (Ainside) pushUnique(0.0, 0, A.x, A.y, A.z);
	if (Binside) pushUnique(1.0, 0, B.x, B.y, B.z);

	if (vhits.size() < 2) return false;

	// t 기준 정렬 후, 가장 긴 구간 선택
	std::sort(vhits.begin(), vhits.end(),
		[](const Hit& a, const Hit& b) { return a.t < b.t; });

	double bestLen = -1.0;
	Hit K0{}, K1{};
	for (size_t i = 0; i + 1 < vhits.size(); ++i) {
		double len = std::fabs(vhits[i + 1].t - vhits[i].t);
		if (len > bestLen) { bestLen = len; K0 = vhits[i]; K1 = vhits[i + 1]; }
	}
	if (bestLen < 1e-12) return false;

	// Edge 시작점 3D 좌표
	auto edgeStartP3 = [&](int edgeId, T_NODE_D& E0, T_NODE_D& E1) {
		if (edgeId <= 0) { E0 = { 0,0,0 }; E1 = { 0,0,0 }; return; }
		const int k0 = edgeId - 1;
		const int k1 = (edgeId % m);
		const int n0 = elem.vNodes[k0];
		const int n1 = elem.vNodes[k1];
		auto it0 = mapNodes.find(n0);
		auto it1 = mapNodes.find(n1);
		if (it0 == mapNodes.end() || it1 == mapNodes.end()) { E0 = { 0,0,0 }; E1 = { 0,0,0 }; return; }
		E0 = it0->second; E1 = it1->second;
	};

	// 시작/끝 edgeId 가 같으면, K1.edgeId 만 같은 코너의 다른 edge 로 변경
	double dSamePos = norm3(K0.x - K1.x, K0.y - K1.y, K0.z - K1.z);
	if (K0.edgeId > 0 && K0.edgeId == K1.edgeId)
	{
		int cornerIdx = -1;

		// K1 위치와 가장 가까운 코너 노드 찾기 (vPoly3: elem의 노드 3D 좌표)
		double bestDist = 1e30;
		for (int k = 0; k < m; ++k)
		{
			const auto& V = vPoly3[k];
			double d = norm3(K1.x - V.x, K1.y - V.y, K1.z - V.z);
			if (d < bestDist)
			{
				bestDist = d;
				cornerIdx = k;
			}
		}

		if (cornerIdx >= 0)
		{
			// 이 코너에 붙어 있는 두 개의 edge ID 계산
			//  - edgeA : cornerIdx   -> cornerIdx+1      (1-based: cornerIdx+1)
			//  - edgeB : cornerIdx-1 -> cornerIdx        (1-based: cornerIdx==0 ? m : cornerIdx)
			int edgeA = cornerIdx + 1;             // 1 .. m
			int edgeB = (cornerIdx == 0) ? m : cornerIdx;

			// K0.edgeId 는 그대로 두고, K1.edgeId 만 "다른" edge 로 변경
			if (K1.edgeId == edgeA)
				K1.edgeId = edgeB;
			else if (K1.edgeId == edgeB)
				K1.edgeId = edgeA;
			else
			{
				// 이론상 여기 들어올 일은 거의 없지만, 방어적으로
				// 코너와 인접한 edge 중 하나로 그냥 교체
				K1.edgeId = edgeA;
			}
		}
	}

	// dEdgeStart/dEdgeEnd: 엣지 시작점→교차점 3D 거리, dDistStart/dDistEnd: A→교차점 3D 거리
	T_NODE_D E0{}, E1{};
	double dEdgeStart = 0.0, dEdgeEnd = 0.0;
	if (K0.edgeId > 0) {
		edgeStartP3(K0.edgeId, E0, E1);
		dEdgeStart = norm3(K0.x - E0.x, K0.y - E0.y, K0.z - E0.z);
	}
	if (K1.edgeId > 0) {
		edgeStartP3(K1.edgeId, E0, E1);
		dEdgeEnd = norm3(K1.x - E0.x, K1.y - E0.y, K1.z - E0.z);
	}

	const double D0 = K0.t * rLen; // t∈[0,1]
	const double D1 = K1.t * rLen;

	// 결과 채움
	outPass.nElemId = elem.id;

	outPass.nEdgeStart = K0.edgeId;
	outPass.dEdgeStart = dEdgeStart;
	outPass.dDistStart = D0;
	outPass.dx0 = K0.x;
	outPass.dy0 = K0.y;
	outPass.dz0 = K0.z;
	outPass.dt0 = K0.t;

	outPass.nEdgeEnd = K1.edgeId;
	outPass.dEdgeEnd = dEdgeEnd;
	outPass.dDistEnd = D1;
	outPass.dx1 = K1.x;
	outPass.dy1 = K1.y;
	outPass.dz1 = K1.z;
	outPass.dt1 = K1.t;

	// 전체 시작점 기준 거리 dPositionI/J 가 필요하면 여기서 함께 채워도 됨
	// outPass.dPositionI = D0 (또는 외부 누적 오프셋 더해 세팅)
	// outPass.dPositionJ = D1

	return true;
}

// ====== 메인: 전체 요소에 대해 선분(시작노드→끝노드)을 추적 ======
std::vector<ElementPass> CAttrCtrl::traceSegmentThroughMesh_Map(const std::map<int, T_NODE_D>& mapNodes,
																const std::map<int, ElementD>& mapElems,
																const T_NODE_D& startNode, 	const T_NODE_D& endNode)
{
	std::vector<ElementPass> vPasses;
	vPasses.reserve(mapElems.size());

	const T_NODE_D& A = startNode;
	const T_NODE_D& B = endNode;

	// 1차: 오른쪽/위쪽(Edge-2,3) 기준
	for (const auto& kv : mapElems)
	{
		const ElementD& elem = kv.second;
		ElementPass pass{};
		if (processElementPass(elem, mapNodes, startNode, endNode, pass, EdgeOwnershipPolicy::RightTop))
		{
			vPasses.push_back(pass);
		}
	}

	if (vPasses.empty())
	{
		// 2차: 아무 것도 안 걸린 경우 → 왼쪽/아래쪽(Edge-1,4) 기준으로 재시도
		for (const auto& kv : mapElems)
		{
			const ElementD& elem = kv.second;
			ElementPass pass{};
			if (processElementPass(elem, mapNodes, startNode, endNode, pass, EdgeOwnershipPolicy::LeftBottom))
			{
				vPasses.push_back(pass);
			}
		}
	}

	// 선분 시작점 기준으로 결과를 정렬
	std::sort(vPasses.begin(), vPasses.end(), [](const ElementPass& a, const ElementPass& b)
	{
		return a.dt0 < b.dt0;
	});

	return vPasses;
}

// 2D 벡터 외적 (z성분만 쓰는 스칼라 외적)
static double Cross2D(double ax, double ay, double bx, double by)
{
	return ax * by - ay * bx;
}
// E: 교점 tAB: AB에서의 비율 (0~1)
BOOL CAttrCtrl::IntersectSegmentAB_CD(const T_NODE_D& A, const T_NODE_D& B, const T_NODE_D& C, const T_NODE_D& D,
									  T_NODE_D& cross, double& tAB, double eps/* = 1e-10*/)
{
	// r = B - A, s = D - C
	double rx = B.x - A.x;
	double ry = B.y - A.y;
	double sx = D.x - C.x;
	double sy = D.y - C.y;

	// r × s
	double rxs = Cross2D(rx, ry, sx, sy);

	// 평행(또는 거의 평행)인 경우
	if (std::fabs(rxs) < eps)
	{
		cross = A;
		return TRUE; 
	}

	double qpx = C.x - A.x;
	double qpy = C.y - A.y;

	// t = (C-A) × s / (r × s)
	double t = Cross2D(qpx, qpy, sx, sy) / rxs;

	// u = (C-A) × r / (r × s)
	double u = Cross2D(qpx, qpy, rx, ry) / rxs;

	// 선분 범위(0~1) 안에 있는지 확인
	if (t < -eps || t > 1.0 + eps ||
		u < -eps || u > 1.0 + eps)
	{
		return FALSE; // 직선은 만나지만, 선분 구간 밖에서 만남
	}

	// 교점 좌표 계산 (AB를 기준으로)
	cross.x = A.x + t * rx;
	cross.y = A.y + t * ry;
	cross.z = A.z + t * (B.z - A.z);  // z도 AB를 따라 보간

	tAB = t;   // AB에서의 위치 비율 (AE / AB)

	return TRUE;
}

// Vec,    // 기준 방향 벡터
void CAttrCtrl::CheckPointSideAndDistance(const T_NODE_D& Center, const T_NODE_D& Vec, const T_NODE_D& Point, int& side,  double& dist)
{
	// Point - Center 벡터
	double dx = Point.x - Center.x;
	double dy = Point.y - Center.y;

	// Vec × CP (2D cross product)
	double cross = Vec.x * dy - Vec.y * dx;

	side = 0;
	if (cross > 0)      side = -1; // Left
	else if (cross < 0) side = +1; // Right

	// 거리 (z는 무시)
	dist = std::sqrt(dx * dx + dy * dy);
}